insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','placement',0,'PLACEMENT','Khảo sát đầu vào','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "math-12-monotonicity-q1", "prompt": "Cho hàm số y = f(x) có đạo hàm f''(x) > 0 với mọi x thuộc khoảng (1; 3). Kết luận nào sau đây đúng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Hàm số đồng biến trên khoảng (1; 3)"}, {"id": "b", "text": "Hàm số nghịch biến trên khoảng (1; 3)"}, {"id": "c", "text": "Hàm số không đổi trên khoảng (1; 3)"}], "correctOptionId": "a", "explanation": "Đạo hàm luôn mang dấu dương trên một khoảng là điều kiện đủ để hàm số đồng biến trên khoảng đó."}, {"id": "math-12-monotonicity-q2", "prompt": "Tìm các khoảng nghịch biến của hàm số y = -x³ + 3x.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "(-1; 1)"}, {"id": "b", "text": "(-∞; 0)"}, {"id": "c", "text": "(-∞; -1) và (1; +∞)"}], "correctOptionId": "c", "explanation": "Đạo hàm y'' = -3x² + 3 = -3(x² - 1). Ta có y'' < 0 khi x² - 1 > 0, tức x < -1 hoặc x > 1."}, {"id": "math-12-extrema-q1", "prompt": "Giả sử hàm số y = f(x) có đạo hàm tại điểm x₀. Điều kiện cần để x₀ là một điểm cực trị của hàm số là:", "difficulty": "EASY", "options": [{"id": "a", "text": "f''(x₀) > 0"}, {"id": "b", "text": "f''(x₀) < 0"}, {"id": "c", "text": "f''(x₀) = 0"}], "correctOptionId": "c", "explanation": "Theo định lí Fermat, nếu hàm số đạt cực trị tại x₀ và có đạo hàm tại đó thì f''(x₀) = 0."}, {"id": "math-12-extrema-q2", "prompt": "Tìm điểm cực tiểu của hàm số y = x³ - 3x + 2.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "x = 0"}, {"id": "b", "text": "x = 1"}, {"id": "c", "text": "x = -1"}], "correctOptionId": "b", "explanation": "y'' = 3x² - 3 = 0 ⇔ x = ±1. Đạo hàm đổi dấu từ âm sang dương khi đi qua x = 1 nên x = 1 là điểm cực tiểu."}, {"id": "math-12-min-max-q1", "prompt": "Cho hàm số y = f(x) liên tục trên đoạn [a; b]. Khẳng định nào sau đây luôn đúng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Giá trị lớn nhất luôn đạt tại một trong hai đầu mút a hoặc b"}, {"id": "b", "text": "Hàm số luôn đạt giá trị lớn nhất và giá trị nhỏ nhất trên [a; b]"}, {"id": "c", "text": "Hàm số chỉ đạt cực đại mà không thể đạt giá trị lớn nhất"}], "correctOptionId": "b", "explanation": "Theo định lí Weierstrass, hàm số liên tục trên một đoạn đóng bị chặn luôn đạt giá trị lớn nhất và nhỏ nhất trên đoạn đó."}, {"id": "math-12-min-max-q2", "prompt": "Giá trị lớn nhất của hàm số y = -x² + 4x + 1 trên đoạn [0; 3] bằng bao nhiêu?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "5"}, {"id": "b", "text": "4"}, {"id": "c", "text": "1"}], "correctOptionId": "a", "explanation": "y'' = -2x + 4 = 0 ⇔ x = 2 thuộc [0; 3]. Ta tính: y(0) = 1, y(2) = 5, y(3) = 4. Vậy giá trị lớn nhất bằng 5."}, {"id": "math-12-asymptotes-q1", "prompt": "Đường thẳng x = a được gọi là đường tiệm cận đứng của đồ thị hàm số y = f(x) nếu thỏa mãn điều kiện nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ít nhất một trong các giới hạn một bên khi x tiến đến a là vô cực"}, {"id": "b", "text": "Giới hạn khi x tiến đến vô cực bằng a"}, {"id": "c", "text": "Đạo hàm f''(a) bằng 0"}], "correctOptionId": "a", "explanation": "Định nghĩa tiệm cận đứng yêu cầu lim_{x→a⁺} f(x) = ±∞ hoặc lim_{x→a⁻} f(x) = ±∞."}, {"id": "math-12-asymptotes-q2", "prompt": "Tìm phương trình đường tiệm cận ngang của đồ thị hàm số y = (3x - 1)/(x + 2).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "x = -2"}, {"id": "b", "text": "y = -1/2"}, {"id": "c", "text": "y = 3"}], "correctOptionId": "c", "explanation": "Ta có lim_{x→+∞} (3x - 1)/(x + 2) = 3 và lim_{x→-∞} (3x - 1)/(x + 2) = 3 nên y = 3 là tiệm cận ngang."}, {"id": "math-12-graph-analysis-q1", "prompt": "Đối với hàm số bậc ba y = ax³ + bx² + cx + d (a ≠ 0), nếu lim_{x→+∞} y = +∞ thì dấu của hệ số a là:", "difficulty": "EASY", "options": [{"id": "a", "text": "a < 0"}, {"id": "b", "text": "a = 0"}, {"id": "c", "text": "a > 0"}], "correctOptionId": "c", "explanation": "Khi x tiến ra dương vô cực, giới hạn của đa thức bậc ba cùng dấu với hệ số cao nhất a. Do đó a > 0."}, {"id": "math-12-graph-analysis-q2", "prompt": "Tâm đối xứng của đồ thị hàm phân thức bậc nhất trên bậc nhất y = (ax + b)/(cx + d) (với c ≠ 0, ad - bc ≠ 0) là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Giao điểm của đồ thị với trục hoành Ox"}, {"id": "b", "text": "Giao điểm của tiệm cận đứng và tiệm cận ngang"}, {"id": "c", "text": "Giao điểm của đồ thị với trục tung Oy"}], "correctOptionId": "b", "explanation": "Đồ thị hàm nhất biến nhận giao điểm của hai đường tiệm cận làm tâm đối xứng."}, {"id": "math-12-vectors-space-q1", "prompt": "Trong không gian, quy tắc hình hộp khẳng định tổng ba vectơ chung gốc xuất phát từ một đỉnh của hình hộp bằng vectơ nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Vectơ cạnh đối diện"}, {"id": "b", "text": "Vectơ đường chéo xuất phát từ đỉnh đó"}, {"id": "c", "text": "Vectơ đường chéo của mặt đáy"}], "correctOptionId": "b", "explanation": "Với hình hộp ABCD.A''B''C''D'', ta luôn có vectơ AB + vectơ AD + vectơ AA'' = vectơ AC''."}, {"id": "math-12-vectors-space-q2", "prompt": "Cho tứ diện ABCD có G là trọng tâm của tam giác BCD. Đẳng thức vectơ nào sau đây đúng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "vectơ AB + vectơ AC + vectơ AD = 3 vectơ AG"}, {"id": "b", "text": "vectơ AB + vectơ AC + vectơ AD = vectơ AG"}, {"id": "c", "text": "vectơ AB + vectơ AC + vectơ AD = 4 vectơ AG"}], "correctOptionId": "a", "explanation": "Vì G là trọng tâm tam giác BCD nên vectơ GB + vectơ GC + vectơ GD = vectơ 0. Biểu diễn qua điểm A ta được vectơ AB + AC + AD = 3 AG."}, {"id": "math-12-coordinates-space-q1", "prompt": "Trong không gian Oxyz, tọa độ của gốc tọa độ O là:", "difficulty": "EASY", "options": [{"id": "a", "text": "(0; 0; 0)"}, {"id": "b", "text": "(1; 1; 1)"}, {"id": "c", "text": "(0; 0; 1)"}], "correctOptionId": "a", "explanation": "Gốc tọa độ O có hoành độ, tung độ và cao độ đều bằng 0."}, {"id": "math-12-coordinates-space-q2", "prompt": "Cho hai điểm A(2; -1; 4) và B(4; 3; 0). Tọa độ trung điểm M của đoạn thẳng AB là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "(6; 2; 4)"}, {"id": "b", "text": "(1; 2; -2)"}, {"id": "c", "text": "(3; 1; 2)"}], "correctOptionId": "c", "explanation": "xM = (2 + 4)/2 = 3; yM = (-1 + 3)/2 = 1; zM = (4 + 0)/2 = 2. Vậy M(3; 1; 2)."}, {"id": "math-12-dot-product-space-q1", "prompt": "Hai vectơ u và v khác vectơ không trong không gian vuông góc với nhau khi và chỉ khi:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tổng u + v = 0"}, {"id": "b", "text": "Độ dài |u| = |v|"}, {"id": "c", "text": "Tích vô hướng u · v = 0"}], "correctOptionId": "c", "explanation": "cos 90° = 0 nên tích vô hướng u · v = |u||v|cos 90° = 0."}, {"id": "math-12-dot-product-space-q2", "prompt": "Tính tích vô hướng của hai vectơ a = (1; 3; -2) và b = (4; -1; 1).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "9"}, {"id": "b", "text": "-1"}, {"id": "c", "text": "5"}], "correctOptionId": "b", "explanation": "a · b = 1*4 + 3*(-1) + (-2)*1 = 4 - 3 - 2 = -1."}, {"id": "math-12-sphere-equation-q1", "prompt": "Mặt cầu (S): (x - 2)² + (y + 1)² + (z - 3)² = 25 có tọa độ tâm I và bán kính R lần lượt là:", "difficulty": "EASY", "options": [{"id": "a", "text": "I(2; -1; 3) và R = 25"}, {"id": "b", "text": "I(2; -1; 3) và R = 5"}, {"id": "c", "text": "I(-2; 1; -3) và R = 25"}], "correctOptionId": "b", "explanation": "Từ phương trình chính tắc (x - a)² + (y - b)² + (z - c)² = R², ta có a = 2, b = -1, c = 3 và R = √25 = 5."}, {"id": "math-12-sphere-equation-q2", "prompt": "Viết phương trình mặt cầu nhận đoạn thẳng AB làm đường kính với A(1; 0; 2) và B(3; 4; 0).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "(x - 2)² + (y - 2)² + (z - 1)² = 6"}, {"id": "b", "text": "(x - 2)² + (y - 2)² + (z - 1)² = 24"}, {"id": "c", "text": "(x - 1)² + y² + (z - 2)² = 6"}], "correctOptionId": "a", "explanation": "Tâm I là trung điểm AB: I(2; 2; 1). Bán kính R = AB/2 = √[(3-1)² + (4-0)² + (0-2)²]/2 = √24 / 2 = √6. R² = 6."}, {"id": "math-12-plane-equation-q1", "prompt": "Một vectơ pháp tuyến của mặt phẳng (P): 2x - 3y + z - 5 = 0 là:", "difficulty": "EASY", "options": [{"id": "a", "text": "n = (2; -3; 1)"}, {"id": "b", "text": "n = (2; 3; 1)"}, {"id": "c", "text": "n = (2; -3; -5)"}], "correctOptionId": "a", "explanation": "Các hệ số của x, y, z trong phương trình tổng quát chính là tọa độ của một vectơ pháp tuyến."}, {"id": "math-12-plane-equation-q2", "prompt": "Phương trình mặt phẳng đi qua M(1; 2; -1) và nhận n = (2; 1; 3) làm vectơ pháp tuyến là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2x + y + 3z + 1 = 0"}, {"id": "b", "text": "x + 2y - z - 6 = 0"}, {"id": "c", "text": "2x + y + 3z - 1 = 0"}], "correctOptionId": "c", "explanation": "Phương trình: 2(x - 1) + 1(y - 2) + 3(z + 1) = 0 ⇔ 2x + y + 3z - 2 - 2 + 3 = 0 ⇔ 2x + y + 3z - 1 = 0."}, {"id": "math-12-antiderivative-q1", "prompt": "Cho F(x) là một nguyên hàm của hàm số f(x) trên khoảng K. Khẳng định nào sau đây đúng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đạo hàm F''(x) bằng -f(x) với mọi x thuộc K"}, {"id": "b", "text": "∫ F(x) dx = f(x) + C"}, {"id": "c", "text": "F''(x) = f(x) với mọi x thuộc K"}], "correctOptionId": "c", "explanation": "Định nghĩa nguyên hàm: F(x) là nguyên hàm của f(x) khi và chỉ khi đạo hàm của F(x) bằng f(x)."}, {"id": "math-12-antiderivative-q2", "prompt": "Tìm họ nguyên hàm của hàm số f(x) = 4x³ - 2x + 1.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "4x⁴ - 2x² + x + C"}, {"id": "b", "text": "x⁴ - x² + x + C"}, {"id": "c", "text": "12x² - 2 + C"}], "correctOptionId": "b", "explanation": "Áp dụng công thức nguyên hàm từng số hạng: ∫ 4x³ dx = x⁴, ∫ (-2x) dx = -x², ∫ 1 dx = x."}, {"id": "math-12-definite-integral-q1", "prompt": "Theo công thức Newton - Leibniz, nếu F(x) là một nguyên hàm của hàm số f(x) liên tục trên [a; b] thì:", "difficulty": "EASY", "options": [{"id": "a", "text": "∫_a^b f(x) dx = F(a) + F(b)"}, {"id": "b", "text": "∫_a^b f(x) dx = F(b) - F(a)"}, {"id": "c", "text": "∫_a^b f(x) dx = F(a) - F(b)"}], "correctOptionId": "b", "explanation": "Công thức cơ bản của giải tích liên hệ tích phân xác định với hiệu giá trị của nguyên hàm tại hai đầu mút."}, {"id": "math-12-definite-integral-q2", "prompt": "Tính tích phân I = ∫_1^2 (3x² + 1) dx.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8"}, {"id": "b", "text": "10"}, {"id": "c", "text": "7"}], "correctOptionId": "a", "explanation": "F(x) = x³ + x. Ta có F(2) = 2³ + 2 = 10; F(1) = 1³ + 1 = 2. Vậy I = F(2) - F(1) = 10 - 2 = 8."}, {"id": "math-12-grouped-dispersion-q1", "prompt": "Số đặc trưng nào bằng căn bậc hai số học của phương sai trong thống kê?", "difficulty": "EASY", "options": [{"id": "a", "text": "Độ lệch chuẩn"}, {"id": "b", "text": "Khoảng biến thiên"}, {"id": "c", "text": "Khoảng tứ phân vị"}], "correctOptionId": "a", "explanation": "Độ lệch chuẩn s được định nghĩa là căn bậc hai số học của phương sai s²: s = √(s²)."}, {"id": "math-12-grouped-dispersion-q2", "prompt": "Một mẫu số liệu ghép nhóm có tứ phân vị thứ nhất Q₁ = 45 và tứ phân vị thứ ba Q₃ = 75. Khoảng tứ phân vị IQR của mẫu bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "120"}, {"id": "b", "text": "60"}, {"id": "c", "text": "30"}], "correctOptionId": "c", "explanation": "Khoảng tứ phân vị được tính theo công thức IQR = Q₃ - Q₁ = 75 - 45 = 30."}, {"id": "math-12-conditional-probability-q1", "prompt": "Cho hai biến cố A và B với P(B) > 0. Công thức tính xác suất có điều kiện của A khi biết B đã xảy ra là:", "difficulty": "EASY", "options": [{"id": "a", "text": "P(A|B) = P(A) / P(B)"}, {"id": "b", "text": "P(A|B) = P(A ∩ B) · P(B)"}, {"id": "c", "text": "P(A|B) = P(A ∩ B) / P(B)"}], "correctOptionId": "c", "explanation": "Định nghĩa xác suất có điều kiện là tỉ số giữa xác suất đồng thời P(A ∩ B) và xác suất điều kiện P(B)."}, {"id": "math-12-conditional-probability-q2", "prompt": "Cho P(A) = 0,6; P(B) = 0,5 và P(A ∩ B) = 0,3. Giá trị của P(A|B) bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,15"}, {"id": "b", "text": "0,6"}, {"id": "c", "text": "0,5"}], "correctOptionId": "b", "explanation": "P(A|B) = P(A ∩ B) / P(B) = 0,3 / 0,5 = 0,6."}, {"id": "math-12-bayes-formula-q1", "prompt": "Nếu {B₁, B₂} là một hệ đầy đủ các biến cố thì công thức xác suất toàn phần đối với biến cố A là:", "difficulty": "EASY", "options": [{"id": "a", "text": "P(A) = P(A|B₁) · P(A|B₂)"}, {"id": "b", "text": "P(A) = P(B₁) · P(A|B₁) + P(B₂) · P(A|B₂)"}, {"id": "c", "text": "P(A) = P(B₁) + P(B₂)"}], "correctOptionId": "b", "explanation": "Công thức xác suất toàn phần phân tích biến cố A thành tổng hợp các trường hợp loại trừ nhau tương ứng với hệ đầy đủ."}, {"id": "math-12-bayes-formula-q2", "prompt": "Một xí nghiệp có hai dây chuyền sản xuất: máy I sản xuất 60% sản phẩm với tỉ lệ phế phẩm 2%; máy II sản xuất 40% sản phẩm với tỉ lệ phế phẩm 3%. Tỉ lệ phế phẩm chung P(A) của xí nghiệp là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,024 (2,4%)"}, {"id": "b", "text": "0,050 (5,0%)"}, {"id": "c", "text": "0,012 (1,2%)"}], "correctOptionId": "a", "explanation": "P(A) = P(I)P(A|I) + P(II)P(A|II) = 0,6 * 0,02 + 0,4 * 0,03 = 0,012 + 0,012 = 0,024 = 2,4%."}]'::jsonb,'[]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-monotonicity',1,'LESSON','Tính đơn điệu của hàm số','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Hàm số y = f(x) đồng biến trên khoảng K khi f''(x) ≥ 0 với mọi x thuộc K (dấu bằng chỉ xảy ra tại hữu hạn điểm). Hàm số nghịch biến khi f''(x) ≤ 0 trên K."]'::jsonb,'["Xét f(x) = x³ - 3x: f''(x) = 3x² - 3 = 3(x² - 1). f''(x) > 0 khi x < -1 hoặc x > 1, do đó f(x) đồng biến trên (-∞; -1) và (1; +∞)."]'::jsonb,'[{"id": "math-12-monotonicity-q1", "prompt": "Cho hàm số y = f(x) có đạo hàm f''(x) > 0 với mọi x thuộc khoảng (1; 3). Kết luận nào sau đây đúng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Hàm số đồng biến trên khoảng (1; 3)"}, {"id": "b", "text": "Hàm số nghịch biến trên khoảng (1; 3)"}, {"id": "c", "text": "Hàm số không đổi trên khoảng (1; 3)"}], "correctOptionId": "a", "explanation": "Đạo hàm luôn mang dấu dương trên một khoảng là điều kiện đủ để hàm số đồng biến trên khoảng đó."}, {"id": "math-12-monotonicity-q2", "prompt": "Tìm các khoảng nghịch biến của hàm số y = -x³ + 3x.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "(-1; 1)"}, {"id": "b", "text": "(-∞; 0)"}, {"id": "c", "text": "(-∞; -1) và (1; +∞)"}], "correctOptionId": "c", "explanation": "Đạo hàm y'' = -3x² + 3 = -3(x² - 1). Ta có y'' < 0 khi x² - 1 > 0, tức x < -1 hoặc x > 1."}, {"id": "math-12-monotonicity-q3", "prompt": "Chi phí sản xuất x sản phẩm của một xí nghiệp là C(x) = 2x² + 50x + 800 (nghìn đồng) với x > 0. Ý nghĩa thực tế của việc chi phí biên C''(x) > 0 với mọi x > 0 là gì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chi phí sản xuất không phụ thuộc vào sản lượng"}, {"id": "b", "text": "Tổng chi phí sản xuất luôn tăng khi quy mô sản lượng mở rộng"}, {"id": "c", "text": "Tổng chi phí sản xuất luôn giảm khi mở rộng sản lượng"}], "correctOptionId": "b", "explanation": "Chi phí biên C''(x) = 4x + 50 > 0 với mọi x > 0, cho thấy hàm chi phí là hàm đồng biến theo sản lượng x."}]'::jsonb,'["math-12-monotonicity"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-extrema',2,'LESSON','Cực trị của hàm số','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Nếu f''(x₀) = 0 (hoặc f''(x₀) không xác định) và đạo hàm f''(x) đổi dấu từ dương sang âm khi qua x₀ thì x₀ là điểm cực đại. Nếu đổi dấu từ âm sang dương thì x₀ là điểm cực tiểu."]'::jsonb,'["Với y = x³ - 3x²: y'' = 3x(x - 2). y'' đổi dấu từ + sang - qua x = 0 (cực đại), từ - sang + qua x = 2 (cực tiểu)."]'::jsonb,'[{"id": "math-12-extrema-q1", "prompt": "Giả sử hàm số y = f(x) có đạo hàm tại điểm x₀. Điều kiện cần để x₀ là một điểm cực trị của hàm số là:", "difficulty": "EASY", "options": [{"id": "a", "text": "f''(x₀) > 0"}, {"id": "b", "text": "f''(x₀) < 0"}, {"id": "c", "text": "f''(x₀) = 0"}], "correctOptionId": "c", "explanation": "Theo định lí Fermat, nếu hàm số đạt cực trị tại x₀ và có đạo hàm tại đó thì f''(x₀) = 0."}, {"id": "math-12-extrema-q2", "prompt": "Tìm điểm cực tiểu của hàm số y = x³ - 3x + 2.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "x = 0"}, {"id": "b", "text": "x = 1"}, {"id": "c", "text": "x = -1"}], "correctOptionId": "b", "explanation": "y'' = 3x² - 3 = 0 ⇔ x = ±1. Đạo hàm đổi dấu từ âm sang dương khi đi qua x = 1 nên x = 1 là điểm cực tiểu."}, {"id": "math-12-extrema-q3", "prompt": "Hàm lợi nhuận của một cơ sở kinh doanh theo số lượng sản phẩm x bán ra là P(x) = -2x² + 120x - 500 (nghìn đồng). Để lợi nhuận đạt giá trị cực đại, cơ sở cần sản xuất bao nhiêu sản phẩm?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "30 sản phẩm"}, {"id": "b", "text": "60 sản phẩm"}, {"id": "c", "text": "20 sản phẩm"}], "correctOptionId": "a", "explanation": "P''(x) = -4x + 120 = 0 ⇔ x = 30. Vì P''''(30) = -4 < 0 nên tại x = 30 lợi nhuận đạt cực đại."}]'::jsonb,'["math-12-extrema"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-min-max',3,'LESSON','Giá trị lớn nhất và nhỏ nhất của hàm số','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Mọi hàm số liên tục trên đoạn [a; b] đều đạt giá trị lớn nhất (GTLN) và giá trị nhỏ nhất (GTNN) trên đoạn đó. Ta tìm các điểm tới hạn trong khoảng (a; b) rồi so sánh giá trị tại các điểm đó với f(a) và f(b)."]'::jsonb,'["Tìm GTLN và GTNN của f(x) = x³ - 3x trên [0; 2]: f''(x) = 3x² - 3 = 0 có nghiệm x = 1 thuộc (0; 2). Ta có f(0) = 0, f(1) = -2, f(2) = 2. Vậy GTLN bằng 2, GTNN bằng -2."]'::jsonb,'[{"id": "math-12-min-max-q1", "prompt": "Cho hàm số y = f(x) liên tục trên đoạn [a; b]. Khẳng định nào sau đây luôn đúng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Giá trị lớn nhất luôn đạt tại một trong hai đầu mút a hoặc b"}, {"id": "b", "text": "Hàm số luôn đạt giá trị lớn nhất và giá trị nhỏ nhất trên [a; b]"}, {"id": "c", "text": "Hàm số chỉ đạt cực đại mà không thể đạt giá trị lớn nhất"}], "correctOptionId": "b", "explanation": "Theo định lí Weierstrass, hàm số liên tục trên một đoạn đóng bị chặn luôn đạt giá trị lớn nhất và nhỏ nhất trên đoạn đó."}, {"id": "math-12-min-max-q2", "prompt": "Giá trị lớn nhất của hàm số y = -x² + 4x + 1 trên đoạn [0; 3] bằng bao nhiêu?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "5"}, {"id": "b", "text": "4"}, {"id": "c", "text": "1"}], "correctOptionId": "a", "explanation": "y'' = -2x + 4 = 0 ⇔ x = 2 thuộc [0; 3]. Ta tính: y(0) = 1, y(2) = 5, y(3) = 4. Vậy giá trị lớn nhất bằng 5."}, {"id": "math-12-min-max-q3", "prompt": "Bác thợ rèn dùng 40 m lưới rào quanh một mảnh vườn hình chữ nhật tựa vào bờ tường thẳng có sẵn (không cần rào phía tường). Diện tích lớn nhất có thể rào được là bao nhiêu?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "400 m²"}, {"id": "b", "text": "100 m²"}, {"id": "c", "text": "200 m²"}], "correctOptionId": "c", "explanation": "Gọi chiều rộng vuông góc với tường là x (m) thì chiều dài là 40 - 2x (m) với 0 < x < 20. Diện tích S(x) = x(40 - 2x) = -2x² + 40x. S''(x) = -4x + 40 = 0 ⇔ x = 10, khi đó S = 200 m²."}]'::jsonb,'["math-12-min-max"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-asymptotes',4,'LESSON','Đường tiệm cận của đồ thị hàm số','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Đường thẳng y = y₀ là tiệm cận ngang nếu lim_{x→+∞} f(x) = y₀ hoặc lim_{x→-∞} f(x) = y₀. Đường thẳng x = x₀ là tiệm cận đứng nếu ít nhất một trong các giới hạn một bên khi x tiến tới x₀ bằng vô cực."]'::jsonb,'["Hàm số y = (2x + 1)/(x - 1) có lim_{x→1⁺} y = +∞ nên x = 1 là tiệm cận đứng; lim_{x→±∞} y = 2 nên y = 2 là tiệm cận ngang."]'::jsonb,'[{"id": "math-12-asymptotes-q1", "prompt": "Đường thẳng x = a được gọi là đường tiệm cận đứng của đồ thị hàm số y = f(x) nếu thỏa mãn điều kiện nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ít nhất một trong các giới hạn một bên khi x tiến đến a là vô cực"}, {"id": "b", "text": "Giới hạn khi x tiến đến vô cực bằng a"}, {"id": "c", "text": "Đạo hàm f''(a) bằng 0"}], "correctOptionId": "a", "explanation": "Định nghĩa tiệm cận đứng yêu cầu lim_{x→a⁺} f(x) = ±∞ hoặc lim_{x→a⁻} f(x) = ±∞."}, {"id": "math-12-asymptotes-q2", "prompt": "Tìm phương trình đường tiệm cận ngang của đồ thị hàm số y = (3x - 1)/(x + 2).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "x = -2"}, {"id": "b", "text": "y = -1/2"}, {"id": "c", "text": "y = 3"}], "correctOptionId": "c", "explanation": "Ta có lim_{x→+∞} (3x - 1)/(x + 2) = 3 và lim_{x→-∞} (3x - 1)/(x + 2) = 3 nên y = 3 là tiệm cận ngang."}, {"id": "math-12-asymptotes-q3", "prompt": "Nồng độ của một loại thuốc trong máu bệnh nhân sau t giờ được mô hình hóa bởi C(t) = 4t / (t² + 2) (mg/L). Khi thời gian t tăng lên vô hạn, nồng độ thuốc tiến về giá trị nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "4 mg/L"}, {"id": "b", "text": "0 mg/L"}, {"id": "c", "text": "2 mg/L"}], "correctOptionId": "b", "explanation": "lim_{t→+∞} 4t / (t² + 2) = lim_{t→+∞} (4/t) / (1 + 2/t²) = 0 mg/L. Đồ thị có tiệm cận ngang y = 0."}]'::jsonb,'["math-12-asymptotes"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-graph-analysis',5,'LESSON','Khảo sát và nhận dạng đồ thị hàm số','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Khảo sát hàm số gồm: tìm tập xác định, xét chiều biến thiên (đạo hàm, cực trị, tiệm cận, bảng biến thiên) và vẽ đồ thị (giao trục tọa độ, tính đối xứng). Đồ thị hàm bậc ba có tâm đối xứng là điểm uốn."]'::jsonb,'["Hàm số y = x³ - 3x: f''(x) = 3(x² - 1); cực đại (-1; 2), cực tiểu (1; -2). Đồ thị nhận gốc tọa độ O(0; 0) làm tâm đối xứng."]'::jsonb,'[{"id": "math-12-graph-analysis-q1", "prompt": "Đối với hàm số bậc ba y = ax³ + bx² + cx + d (a ≠ 0), nếu lim_{x→+∞} y = +∞ thì dấu của hệ số a là:", "difficulty": "EASY", "options": [{"id": "a", "text": "a < 0"}, {"id": "b", "text": "a = 0"}, {"id": "c", "text": "a > 0"}], "correctOptionId": "c", "explanation": "Khi x tiến ra dương vô cực, giới hạn của đa thức bậc ba cùng dấu với hệ số cao nhất a. Do đó a > 0."}, {"id": "math-12-graph-analysis-q2", "prompt": "Tâm đối xứng của đồ thị hàm phân thức bậc nhất trên bậc nhất y = (ax + b)/(cx + d) (với c ≠ 0, ad - bc ≠ 0) là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Giao điểm của đồ thị với trục hoành Ox"}, {"id": "b", "text": "Giao điểm của tiệm cận đứng và tiệm cận ngang"}, {"id": "c", "text": "Giao điểm của đồ thị với trục tung Oy"}], "correctOptionId": "b", "explanation": "Đồ thị hàm nhất biến nhận giao điểm của hai đường tiệm cận làm tâm đối xứng."}, {"id": "math-12-graph-analysis-q3", "prompt": "Cho hàm số f(x) liên tục trên R có bảng biến thiên: cực đại tại x = -1 với f(-1) = 4, cực tiểu tại x = 2 với f(2) = -1. Khi x → -∞ thì y → -∞; khi x → +∞ thì y → +∞. Số nghiệm phân biệt của phương trình f(x) = 0 là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "3 nghiệm phân biệt"}, {"id": "b", "text": "1 nghiệm"}, {"id": "c", "text": "2 nghiệm phân biệt"}], "correctOptionId": "a", "explanation": "Trên (-∞; -1), f tăng từ -∞ lên 4 nên cắt Ox tại 1 điểm. Trên (-1; 2), f giảm từ 4 xuống -1 nên cắt Ox tại điểm thứ hai. Trên (2; +∞), f tăng từ -1 lên +∞ nên cắt Ox tại điểm thứ ba."}]'::jsonb,'["math-12-graph-analysis"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-review-1',6,'FIVE_LESSON_REVIEW','Ôn tập 1','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "math-12-monotonicity-q1", "prompt": "Cho hàm số y = f(x) có đạo hàm f''(x) > 0 với mọi x thuộc khoảng (1; 3). Kết luận nào sau đây đúng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Hàm số đồng biến trên khoảng (1; 3)"}, {"id": "b", "text": "Hàm số nghịch biến trên khoảng (1; 3)"}, {"id": "c", "text": "Hàm số không đổi trên khoảng (1; 3)"}], "correctOptionId": "a", "explanation": "Đạo hàm luôn mang dấu dương trên một khoảng là điều kiện đủ để hàm số đồng biến trên khoảng đó."}, {"id": "math-12-monotonicity-q2", "prompt": "Tìm các khoảng nghịch biến của hàm số y = -x³ + 3x.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "(-1; 1)"}, {"id": "b", "text": "(-∞; 0)"}, {"id": "c", "text": "(-∞; -1) và (1; +∞)"}], "correctOptionId": "c", "explanation": "Đạo hàm y'' = -3x² + 3 = -3(x² - 1). Ta có y'' < 0 khi x² - 1 > 0, tức x < -1 hoặc x > 1."}, {"id": "math-12-extrema-q1", "prompt": "Giả sử hàm số y = f(x) có đạo hàm tại điểm x₀. Điều kiện cần để x₀ là một điểm cực trị của hàm số là:", "difficulty": "EASY", "options": [{"id": "a", "text": "f''(x₀) > 0"}, {"id": "b", "text": "f''(x₀) < 0"}, {"id": "c", "text": "f''(x₀) = 0"}], "correctOptionId": "c", "explanation": "Theo định lí Fermat, nếu hàm số đạt cực trị tại x₀ và có đạo hàm tại đó thì f''(x₀) = 0."}, {"id": "math-12-extrema-q2", "prompt": "Tìm điểm cực tiểu của hàm số y = x³ - 3x + 2.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "x = 0"}, {"id": "b", "text": "x = 1"}, {"id": "c", "text": "x = -1"}], "correctOptionId": "b", "explanation": "y'' = 3x² - 3 = 0 ⇔ x = ±1. Đạo hàm đổi dấu từ âm sang dương khi đi qua x = 1 nên x = 1 là điểm cực tiểu."}, {"id": "math-12-min-max-q1", "prompt": "Cho hàm số y = f(x) liên tục trên đoạn [a; b]. Khẳng định nào sau đây luôn đúng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Giá trị lớn nhất luôn đạt tại một trong hai đầu mút a hoặc b"}, {"id": "b", "text": "Hàm số luôn đạt giá trị lớn nhất và giá trị nhỏ nhất trên [a; b]"}, {"id": "c", "text": "Hàm số chỉ đạt cực đại mà không thể đạt giá trị lớn nhất"}], "correctOptionId": "b", "explanation": "Theo định lí Weierstrass, hàm số liên tục trên một đoạn đóng bị chặn luôn đạt giá trị lớn nhất và nhỏ nhất trên đoạn đó."}, {"id": "math-12-min-max-q2", "prompt": "Giá trị lớn nhất của hàm số y = -x² + 4x + 1 trên đoạn [0; 3] bằng bao nhiêu?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "5"}, {"id": "b", "text": "4"}, {"id": "c", "text": "1"}], "correctOptionId": "a", "explanation": "y'' = -2x + 4 = 0 ⇔ x = 2 thuộc [0; 3]. Ta tính: y(0) = 1, y(2) = 5, y(3) = 4. Vậy giá trị lớn nhất bằng 5."}, {"id": "math-12-asymptotes-q1", "prompt": "Đường thẳng x = a được gọi là đường tiệm cận đứng của đồ thị hàm số y = f(x) nếu thỏa mãn điều kiện nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ít nhất một trong các giới hạn một bên khi x tiến đến a là vô cực"}, {"id": "b", "text": "Giới hạn khi x tiến đến vô cực bằng a"}, {"id": "c", "text": "Đạo hàm f''(a) bằng 0"}], "correctOptionId": "a", "explanation": "Định nghĩa tiệm cận đứng yêu cầu lim_{x→a⁺} f(x) = ±∞ hoặc lim_{x→a⁻} f(x) = ±∞."}, {"id": "math-12-asymptotes-q2", "prompt": "Tìm phương trình đường tiệm cận ngang của đồ thị hàm số y = (3x - 1)/(x + 2).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "x = -2"}, {"id": "b", "text": "y = -1/2"}, {"id": "c", "text": "y = 3"}], "correctOptionId": "c", "explanation": "Ta có lim_{x→+∞} (3x - 1)/(x + 2) = 3 và lim_{x→-∞} (3x - 1)/(x + 2) = 3 nên y = 3 là tiệm cận ngang."}, {"id": "math-12-graph-analysis-q1", "prompt": "Đối với hàm số bậc ba y = ax³ + bx² + cx + d (a ≠ 0), nếu lim_{x→+∞} y = +∞ thì dấu của hệ số a là:", "difficulty": "EASY", "options": [{"id": "a", "text": "a < 0"}, {"id": "b", "text": "a = 0"}, {"id": "c", "text": "a > 0"}], "correctOptionId": "c", "explanation": "Khi x tiến ra dương vô cực, giới hạn của đa thức bậc ba cùng dấu với hệ số cao nhất a. Do đó a > 0."}, {"id": "math-12-graph-analysis-q2", "prompt": "Tâm đối xứng của đồ thị hàm phân thức bậc nhất trên bậc nhất y = (ax + b)/(cx + d) (với c ≠ 0, ad - bc ≠ 0) là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Giao điểm của đồ thị với trục hoành Ox"}, {"id": "b", "text": "Giao điểm của tiệm cận đứng và tiệm cận ngang"}, {"id": "c", "text": "Giao điểm của đồ thị với trục tung Oy"}], "correctOptionId": "b", "explanation": "Đồ thị hàm nhất biến nhận giao điểm của hai đường tiệm cận làm tâm đối xứng."}]'::jsonb,'["math-12-monotonicity", "math-12-extrema", "math-12-min-max", "math-12-asymptotes", "math-12-graph-analysis"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-vectors-space',7,'LESSON','Vectơ và các phép toán trong không gian','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Vectơ trong không gian là đoạn thẳng có hướng. Phép cộng vectơ tuân theo quy tắc ba điểm, hình bình hành và hình hộp: vectơ đường chéo xuất phát từ một đỉnh bằng tổng ba vectơ cạnh cùng xuất phát từ đỉnh đó."]'::jsonb,'["Cho hình hộp ABCD.A''B''C''D'': vectơ AC'' = vectơ AB + vectơ AD + vectơ AA''."]'::jsonb,'[{"id": "math-12-vectors-space-q1", "prompt": "Trong không gian, quy tắc hình hộp khẳng định tổng ba vectơ chung gốc xuất phát từ một đỉnh của hình hộp bằng vectơ nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Vectơ cạnh đối diện"}, {"id": "b", "text": "Vectơ đường chéo xuất phát từ đỉnh đó"}, {"id": "c", "text": "Vectơ đường chéo của mặt đáy"}], "correctOptionId": "b", "explanation": "Với hình hộp ABCD.A''B''C''D'', ta luôn có vectơ AB + vectơ AD + vectơ AA'' = vectơ AC''."}, {"id": "math-12-vectors-space-q2", "prompt": "Cho tứ diện ABCD có G là trọng tâm của tam giác BCD. Đẳng thức vectơ nào sau đây đúng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "vectơ AB + vectơ AC + vectơ AD = 3 vectơ AG"}, {"id": "b", "text": "vectơ AB + vectơ AC + vectơ AD = vectơ AG"}, {"id": "c", "text": "vectơ AB + vectơ AC + vectơ AD = 4 vectơ AG"}], "correctOptionId": "a", "explanation": "Vì G là trọng tâm tam giác BCD nên vectơ GB + vectơ GC + vectơ GD = vectơ 0. Biểu diễn qua điểm A ta được vectơ AB + AC + AD = 3 AG."}, {"id": "math-12-vectors-space-q3", "prompt": "Ba lực vectơ F₁, F₂, F₃ cùng tác dụng vào một chất điểm đứng yên ở trạng thái cân bằng. Hệ thức vectơ nào sau đây phản ánh đúng định luật cân bằng?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "|F₁| + |F₂| + |F₃| = 0"}, {"id": "b", "text": "vectơ F₁ + vectơ F₂ = vectơ F₃"}, {"id": "c", "text": "vectơ F₁ + vectơ F₂ + vectơ F₃ = vectơ 0"}], "correctOptionId": "c", "explanation": "Hợp lực của tất cả các lực tác dụng lên một vật cân bằng phải triệt tiêu, tức tổng vectơ bằng vectơ 0."}]'::jsonb,'["math-12-vectors-space"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-coordinates-space',8,'LESSON','Hệ tọa độ Oxyz và tọa độ điểm, vectơ','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Hệ tọa độ Oxyz gồm ba trục Ox, Oy, Oz đôi một vuông góc tại gốc O với ba vectơ đơn vị i, j, k. Vectơ u = x.i + y.j + z.k có tọa độ u = (x; y; z). Tọa độ trung điểm M của đoạn thẳng AB là trung bình cộng tọa độ của A và B."]'::jsonb,'["A(1; 2; 3) và B(3; 0; -1) thì trung điểm M có tọa độ ((1+3)/2; (2+0)/2; (3-1)/2) = (2; 1; 1). Vectơ AB = (2; -2; -4)."]'::jsonb,'[{"id": "math-12-coordinates-space-q1", "prompt": "Trong không gian Oxyz, tọa độ của gốc tọa độ O là:", "difficulty": "EASY", "options": [{"id": "a", "text": "(0; 0; 0)"}, {"id": "b", "text": "(1; 1; 1)"}, {"id": "c", "text": "(0; 0; 1)"}], "correctOptionId": "a", "explanation": "Gốc tọa độ O có hoành độ, tung độ và cao độ đều bằng 0."}, {"id": "math-12-coordinates-space-q2", "prompt": "Cho hai điểm A(2; -1; 4) và B(4; 3; 0). Tọa độ trung điểm M của đoạn thẳng AB là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "(6; 2; 4)"}, {"id": "b", "text": "(1; 2; -2)"}, {"id": "c", "text": "(3; 1; 2)"}], "correctOptionId": "c", "explanation": "xM = (2 + 4)/2 = 3; yM = (-1 + 3)/2 = 1; zM = (4 + 0)/2 = 2. Vậy M(3; 1; 2)."}, {"id": "math-12-coordinates-space-q3", "prompt": "Trong trạm không lưu, máy bay A tại tọa độ P(120; 80; 10) di chuyển với vận tốc đều v = (30; 20; 2) (km/h) trong không gian Oxyz. Sau 2 giờ bay, tọa độ mới của máy bay là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "(240; 160; 20)"}, {"id": "b", "text": "(180; 120; 14)"}, {"id": "c", "text": "(150; 100; 12)"}], "correctOptionId": "b", "explanation": "Tọa độ mới P'' = P + 2v = (120 + 2*30; 80 + 2*20; 10 + 2*2) = (180; 120; 14)."}]'::jsonb,'["math-12-coordinates-space"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-dot-product-space',9,'LESSON','Tích vô hướng và góc giữa hai vectơ','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Tích vô hướng của u = (x₁; y₁; z₁) và v = (x₂; y₂; z₂) là u.v = x₁x₂ + y₁y₂ + z₁z₂. Góc θ giữa hai vectơ thỏa mãn cos θ = (u.v)/(|u|.|v|). Hai vectơ vuông góc khi và chỉ khi tích vô hướng bằng 0."]'::jsonb,'["Cho u = (1; 2; 2) và v = (2; -1; 0): u.v = 1*2 + 2*(-1) + 2*0 = 0, suy ra u vuông góc với v."]'::jsonb,'[{"id": "math-12-dot-product-space-q1", "prompt": "Hai vectơ u và v khác vectơ không trong không gian vuông góc với nhau khi và chỉ khi:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tổng u + v = 0"}, {"id": "b", "text": "Độ dài |u| = |v|"}, {"id": "c", "text": "Tích vô hướng u · v = 0"}], "correctOptionId": "c", "explanation": "cos 90° = 0 nên tích vô hướng u · v = |u||v|cos 90° = 0."}, {"id": "math-12-dot-product-space-q2", "prompt": "Tính tích vô hướng của hai vectơ a = (1; 3; -2) và b = (4; -1; 1).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "9"}, {"id": "b", "text": "-1"}, {"id": "c", "text": "5"}], "correctOptionId": "b", "explanation": "a · b = 1*4 + 3*(-1) + (-2)*1 = 4 - 3 - 2 = -1."}, {"id": "math-12-dot-product-space-q3", "prompt": "Tính số đo góc giữa hai vectơ u = (1; 0; 1) và v = (0; 1; 1).", "difficulty": "APPLIED", "options": [{"id": "a", "text": "60°"}, {"id": "b", "text": "45°"}, {"id": "c", "text": "90°"}], "correctOptionId": "a", "explanation": "u · v = 1*0 + 0*1 + 1*1 = 1. Độ dài |u| = √(1² + 1²) = √2, |v| = √2. cos θ = 1 / (√2 * √2) = 1/2 ⇒ θ = 60°."}]'::jsonb,'["math-12-dot-product-space"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-sphere-equation',10,'LESSON','Phương trình mặt cầu trong không gian','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Mặt cầu tâm I(a; b; c) bán kính R có phương trình chính tắc: (x - a)² + (y - b)² + (z - c)² = R². Dạng tổng quát x² + y² + z² - 2ax - 2by - 2cz + d = 0 với điều kiện a² + b² + c² - d > 0 và R = √(a² + b² + c² - d)."]'::jsonb,'["Mặt cầu tâm I(1; -2; 3) bán kính R = 4 có phương trình: (x - 1)² + (y + 2)² + (z - 3)² = 16."]'::jsonb,'[{"id": "math-12-sphere-equation-q1", "prompt": "Mặt cầu (S): (x - 2)² + (y + 1)² + (z - 3)² = 25 có tọa độ tâm I và bán kính R lần lượt là:", "difficulty": "EASY", "options": [{"id": "a", "text": "I(2; -1; 3) và R = 25"}, {"id": "b", "text": "I(2; -1; 3) và R = 5"}, {"id": "c", "text": "I(-2; 1; -3) và R = 25"}], "correctOptionId": "b", "explanation": "Từ phương trình chính tắc (x - a)² + (y - b)² + (z - c)² = R², ta có a = 2, b = -1, c = 3 và R = √25 = 5."}, {"id": "math-12-sphere-equation-q2", "prompt": "Viết phương trình mặt cầu nhận đoạn thẳng AB làm đường kính với A(1; 0; 2) và B(3; 4; 0).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "(x - 2)² + (y - 2)² + (z - 1)² = 6"}, {"id": "b", "text": "(x - 2)² + (y - 2)² + (z - 1)² = 24"}, {"id": "c", "text": "(x - 1)² + y² + (z - 2)² = 6"}], "correctOptionId": "a", "explanation": "Tâm I là trung điểm AB: I(2; 2; 1). Bán kính R = AB/2 = √[(3-1)² + (4-0)² + (0-2)²]/2 = √24 / 2 = √6. R² = 6."}, {"id": "math-12-sphere-equation-q3", "prompt": "Một trạm radar phủ sóng hình cầu bán kính 10 km, đặt tại tâm I(1; 2; 3) (đơn vị tọa độ km). Điểm nào sau đây nằm bên trong vùng phát sóng của trạm?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Điểm N(10; 10; 10)"}, {"id": "b", "text": "Điểm P(15; 2; 3)"}, {"id": "c", "text": "Điểm M(3; 4; 5)"}], "correctOptionId": "c", "explanation": "Khoảng cách IM² = (3-1)² + (4-2)² + (5-3)² = 4 + 4 + 4 = 12 < 10² = 100, do đó M nằm bên trong mặt cầu."}]'::jsonb,'["math-12-sphere-equation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-plane-equation',11,'LESSON','Phương trình mặt phẳng trong không gian','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Mặt phẳng đi qua M(x₀; y₀; z₀) và có vectơ pháp tuyến n = (A; B; C) có phương trình: A(x - x₀) + B(y - y₀) + C(z - z₀) = 0 hay Ax + By + Cz + D = 0 (A² + B² + C² > 0). Khoảng cách từ M đến (P) là d = |Ax₀ + By₀ + Cz₀ + D| / √(A² + B² + C²)."]'::jsonb,'["Mặt phẳng qua M(1; 2; 3) vuông góc với n = (2; -1; 4) có phương trình: 2(x - 1) - 1(y - 2) + 4(z - 3) = 0 ⇔ 2x - y + 4z - 12 = 0."]'::jsonb,'[{"id": "math-12-plane-equation-q1", "prompt": "Một vectơ pháp tuyến của mặt phẳng (P): 2x - 3y + z - 5 = 0 là:", "difficulty": "EASY", "options": [{"id": "a", "text": "n = (2; -3; 1)"}, {"id": "b", "text": "n = (2; 3; 1)"}, {"id": "c", "text": "n = (2; -3; -5)"}], "correctOptionId": "a", "explanation": "Các hệ số của x, y, z trong phương trình tổng quát chính là tọa độ của một vectơ pháp tuyến."}, {"id": "math-12-plane-equation-q2", "prompt": "Phương trình mặt phẳng đi qua M(1; 2; -1) và nhận n = (2; 1; 3) làm vectơ pháp tuyến là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2x + y + 3z + 1 = 0"}, {"id": "b", "text": "x + 2y - z - 6 = 0"}, {"id": "c", "text": "2x + y + 3z - 1 = 0"}], "correctOptionId": "c", "explanation": "Phương trình: 2(x - 1) + 1(y - 2) + 3(z + 1) = 0 ⇔ 2x + y + 3z - 2 - 2 + 3 = 0 ⇔ 2x + y + 3z - 1 = 0."}, {"id": "math-12-plane-equation-q3", "prompt": "Khoảng cách từ điểm A(1; 2; 3) đến mặt phẳng (P): 2x - 2y + z + 5 = 0 bằng bao nhiêu?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "3"}, {"id": "b", "text": "2"}, {"id": "c", "text": "6"}], "correctOptionId": "b", "explanation": "d(A, (P)) = |2*1 - 2*2 + 3 + 5| / √(2² + (-2)² + 1²) = |2 - 4 + 3 + 5| / √9 = 6 / 3 = 2."}]'::jsonb,'["math-12-plane-equation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-review-2',12,'FIVE_LESSON_REVIEW','Ôn tập 2','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "math-12-vectors-space-q1", "prompt": "Trong không gian, quy tắc hình hộp khẳng định tổng ba vectơ chung gốc xuất phát từ một đỉnh của hình hộp bằng vectơ nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Vectơ cạnh đối diện"}, {"id": "b", "text": "Vectơ đường chéo xuất phát từ đỉnh đó"}, {"id": "c", "text": "Vectơ đường chéo của mặt đáy"}], "correctOptionId": "b", "explanation": "Với hình hộp ABCD.A''B''C''D'', ta luôn có vectơ AB + vectơ AD + vectơ AA'' = vectơ AC''."}, {"id": "math-12-vectors-space-q2", "prompt": "Cho tứ diện ABCD có G là trọng tâm của tam giác BCD. Đẳng thức vectơ nào sau đây đúng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "vectơ AB + vectơ AC + vectơ AD = 3 vectơ AG"}, {"id": "b", "text": "vectơ AB + vectơ AC + vectơ AD = vectơ AG"}, {"id": "c", "text": "vectơ AB + vectơ AC + vectơ AD = 4 vectơ AG"}], "correctOptionId": "a", "explanation": "Vì G là trọng tâm tam giác BCD nên vectơ GB + vectơ GC + vectơ GD = vectơ 0. Biểu diễn qua điểm A ta được vectơ AB + AC + AD = 3 AG."}, {"id": "math-12-coordinates-space-q1", "prompt": "Trong không gian Oxyz, tọa độ của gốc tọa độ O là:", "difficulty": "EASY", "options": [{"id": "a", "text": "(0; 0; 0)"}, {"id": "b", "text": "(1; 1; 1)"}, {"id": "c", "text": "(0; 0; 1)"}], "correctOptionId": "a", "explanation": "Gốc tọa độ O có hoành độ, tung độ và cao độ đều bằng 0."}, {"id": "math-12-coordinates-space-q2", "prompt": "Cho hai điểm A(2; -1; 4) và B(4; 3; 0). Tọa độ trung điểm M của đoạn thẳng AB là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "(6; 2; 4)"}, {"id": "b", "text": "(1; 2; -2)"}, {"id": "c", "text": "(3; 1; 2)"}], "correctOptionId": "c", "explanation": "xM = (2 + 4)/2 = 3; yM = (-1 + 3)/2 = 1; zM = (4 + 0)/2 = 2. Vậy M(3; 1; 2)."}, {"id": "math-12-dot-product-space-q1", "prompt": "Hai vectơ u và v khác vectơ không trong không gian vuông góc với nhau khi và chỉ khi:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tổng u + v = 0"}, {"id": "b", "text": "Độ dài |u| = |v|"}, {"id": "c", "text": "Tích vô hướng u · v = 0"}], "correctOptionId": "c", "explanation": "cos 90° = 0 nên tích vô hướng u · v = |u||v|cos 90° = 0."}, {"id": "math-12-dot-product-space-q2", "prompt": "Tính tích vô hướng của hai vectơ a = (1; 3; -2) và b = (4; -1; 1).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "9"}, {"id": "b", "text": "-1"}, {"id": "c", "text": "5"}], "correctOptionId": "b", "explanation": "a · b = 1*4 + 3*(-1) + (-2)*1 = 4 - 3 - 2 = -1."}, {"id": "math-12-sphere-equation-q1", "prompt": "Mặt cầu (S): (x - 2)² + (y + 1)² + (z - 3)² = 25 có tọa độ tâm I và bán kính R lần lượt là:", "difficulty": "EASY", "options": [{"id": "a", "text": "I(2; -1; 3) và R = 25"}, {"id": "b", "text": "I(2; -1; 3) và R = 5"}, {"id": "c", "text": "I(-2; 1; -3) và R = 25"}], "correctOptionId": "b", "explanation": "Từ phương trình chính tắc (x - a)² + (y - b)² + (z - c)² = R², ta có a = 2, b = -1, c = 3 và R = √25 = 5."}, {"id": "math-12-sphere-equation-q2", "prompt": "Viết phương trình mặt cầu nhận đoạn thẳng AB làm đường kính với A(1; 0; 2) và B(3; 4; 0).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "(x - 2)² + (y - 2)² + (z - 1)² = 6"}, {"id": "b", "text": "(x - 2)² + (y - 2)² + (z - 1)² = 24"}, {"id": "c", "text": "(x - 1)² + y² + (z - 2)² = 6"}], "correctOptionId": "a", "explanation": "Tâm I là trung điểm AB: I(2; 2; 1). Bán kính R = AB/2 = √[(3-1)² + (4-0)² + (0-2)²]/2 = √24 / 2 = √6. R² = 6."}, {"id": "math-12-plane-equation-q1", "prompt": "Một vectơ pháp tuyến của mặt phẳng (P): 2x - 3y + z - 5 = 0 là:", "difficulty": "EASY", "options": [{"id": "a", "text": "n = (2; -3; 1)"}, {"id": "b", "text": "n = (2; 3; 1)"}, {"id": "c", "text": "n = (2; -3; -5)"}], "correctOptionId": "a", "explanation": "Các hệ số của x, y, z trong phương trình tổng quát chính là tọa độ của một vectơ pháp tuyến."}, {"id": "math-12-plane-equation-q2", "prompt": "Phương trình mặt phẳng đi qua M(1; 2; -1) và nhận n = (2; 1; 3) làm vectơ pháp tuyến là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2x + y + 3z + 1 = 0"}, {"id": "b", "text": "x + 2y - z - 6 = 0"}, {"id": "c", "text": "2x + y + 3z - 1 = 0"}], "correctOptionId": "c", "explanation": "Phương trình: 2(x - 1) + 1(y - 2) + 3(z + 1) = 0 ⇔ 2x + y + 3z - 2 - 2 + 3 = 0 ⇔ 2x + y + 3z - 1 = 0."}]'::jsonb,'["math-12-vectors-space", "math-12-coordinates-space", "math-12-dot-product-space", "math-12-sphere-equation", "math-12-plane-equation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-antiderivative',13,'LESSON','Nguyên hàm và tính chất cơ bản','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Hàm số F(x) là một nguyên hàm của f(x) trên K nếu F''(x) = f(x) với mọi x thuộc K. Họ tất cả các nguyên hàm là ∫ f(x) dx = F(x) + C. Các nguyên hàm cơ bản: ∫ xⁿ dx = xⁿ⁺¹/(n+1) + C (n ≠ -1), ∫ eˣ dx = eˣ + C."]'::jsonb,'["∫ (3x² + 2x) dx = x³ + x² + C."]'::jsonb,'[{"id": "math-12-antiderivative-q1", "prompt": "Cho F(x) là một nguyên hàm của hàm số f(x) trên khoảng K. Khẳng định nào sau đây đúng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đạo hàm F''(x) bằng -f(x) với mọi x thuộc K"}, {"id": "b", "text": "∫ F(x) dx = f(x) + C"}, {"id": "c", "text": "F''(x) = f(x) với mọi x thuộc K"}], "correctOptionId": "c", "explanation": "Định nghĩa nguyên hàm: F(x) là nguyên hàm của f(x) khi và chỉ khi đạo hàm của F(x) bằng f(x)."}, {"id": "math-12-antiderivative-q2", "prompt": "Tìm họ nguyên hàm của hàm số f(x) = 4x³ - 2x + 1.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "4x⁴ - 2x² + x + C"}, {"id": "b", "text": "x⁴ - x² + x + C"}, {"id": "c", "text": "12x² - 2 + C"}], "correctOptionId": "b", "explanation": "Áp dụng công thức nguyên hàm từng số hạng: ∫ 4x³ dx = x⁴, ∫ (-2x) dx = -x², ∫ 1 dx = x."}, {"id": "math-12-antiderivative-q3", "prompt": "Một vật chuyển động thẳng có vận tốc tức thời v(t) = 3t² + 2t (m/s). Biết tại thời điểm t = 0 vật ở vị trí s(0) = 5 m. Phương trình vị trí s(t) của vật là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "s(t) = t³ + t² + 5 (m)"}, {"id": "b", "text": "s(t) = 6t + 2 (m)"}, {"id": "c", "text": "s(t) = t³ + t² (m)"}], "correctOptionId": "a", "explanation": "s(t) = ∫ (3t² + 2t) dt = t³ + t² + C. Với s(0) = 5 suy ra C = 5, do đó s(t) = t³ + t² + 5."}]'::jsonb,'["math-12-antiderivative"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-definite-integral',14,'LESSON','Tích phân và ứng dụng tính diện tích','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Định nghĩa tích phân theo công thức Newton - Leibniz: ∫_a^b f(x) dx = F(b) - F(a). Diện tích hình phẳng giới hạn bởi đồ thị y = f(x) liên tục, trục hoành và hai đường thẳng x = a, x = b là S = ∫_a^b |f(x)| dx."]'::jsonb,'["Tính diện tích hình phẳng giới hạn bởi y = x², trục hoành, x = 0 và x = 3: S = ∫_0^3 x² dx = [x³/3]_0^3 = 27/3 = 9."]'::jsonb,'[{"id": "math-12-definite-integral-q1", "prompt": "Theo công thức Newton - Leibniz, nếu F(x) là một nguyên hàm của hàm số f(x) liên tục trên [a; b] thì:", "difficulty": "EASY", "options": [{"id": "a", "text": "∫_a^b f(x) dx = F(a) + F(b)"}, {"id": "b", "text": "∫_a^b f(x) dx = F(b) - F(a)"}, {"id": "c", "text": "∫_a^b f(x) dx = F(a) - F(b)"}], "correctOptionId": "b", "explanation": "Công thức cơ bản của giải tích liên hệ tích phân xác định với hiệu giá trị của nguyên hàm tại hai đầu mút."}, {"id": "math-12-definite-integral-q2", "prompt": "Tính tích phân I = ∫_1^2 (3x² + 1) dx.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8"}, {"id": "b", "text": "10"}, {"id": "c", "text": "7"}], "correctOptionId": "a", "explanation": "F(x) = x³ + x. Ta có F(2) = 2³ + 2 = 10; F(1) = 1³ + 1 = 2. Vậy I = F(2) - F(1) = 10 - 2 = 8."}, {"id": "math-12-definite-integral-q3", "prompt": "Tính diện tích hình phẳng giới hạn bởi đồ thị hàm số y = 3x², trục hoành Ox và hai đường thẳng x = 0, x = 2.", "difficulty": "APPLIED", "options": [{"id": "a", "text": "12"}, {"id": "b", "text": "6"}, {"id": "c", "text": "8"}], "correctOptionId": "c", "explanation": "Vì 3x² ≥ 0 trên [0; 2] nên diện tích S = ∫_0^2 3x² dx = [x³]_0^2 = 2³ - 0³ = 8."}]'::jsonb,'["math-12-definite-integral"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-grouped-dispersion',15,'LESSON','Đo độ phân tán của mẫu số liệu ghép nhóm','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Các số đặc trưng đo độ phân tán của mẫu số liệu ghép nhóm gồm: khoảng biến thiên R = x_max - x_min, khoảng tứ phân vị IQR = Q₃ - Q₁, phương sai s² và độ lệch chuẩn s = √(s²). Độ lệch chuẩn càng nhỏ thể hiện dữ liệu càng phân tán ít quanh giá trị trung bình."]'::jsonb,'["Mẫu số liệu có phương sai s² = 16 thì độ lệch chuẩn s = √16 = 4."]'::jsonb,'[{"id": "math-12-grouped-dispersion-q1", "prompt": "Số đặc trưng nào bằng căn bậc hai số học của phương sai trong thống kê?", "difficulty": "EASY", "options": [{"id": "a", "text": "Độ lệch chuẩn"}, {"id": "b", "text": "Khoảng biến thiên"}, {"id": "c", "text": "Khoảng tứ phân vị"}], "correctOptionId": "a", "explanation": "Độ lệch chuẩn s được định nghĩa là căn bậc hai số học của phương sai s²: s = √(s²)."}, {"id": "math-12-grouped-dispersion-q2", "prompt": "Một mẫu số liệu ghép nhóm có tứ phân vị thứ nhất Q₁ = 45 và tứ phân vị thứ ba Q₃ = 75. Khoảng tứ phân vị IQR của mẫu bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "120"}, {"id": "b", "text": "60"}, {"id": "c", "text": "30"}], "correctOptionId": "c", "explanation": "Khoảng tứ phân vị được tính theo công thức IQR = Q₃ - Q₁ = 75 - 45 = 30."}, {"id": "math-12-grouped-dispersion-q3", "prompt": "Hai lớp 12A và 12B có cùng điểm trung bình môn Toán là 7,5 điểm. Độ lệch chuẩn điểm kiểm tra của lớp 12A là 0,8 còn của lớp 12B là 1,6. Kết luận nào sau đây chính xác nhất?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Hai lớp có độ phân tán kết quả học tập như nhau"}, {"id": "b", "text": "Điểm số của học sinh lớp 12A đồng đều hơn học sinh lớp 12B"}, {"id": "c", "text": "Học sinh lớp 12B học tốt môn Toán hơn học sinh lớp 12A"}], "correctOptionId": "b", "explanation": "Độ lệch chuẩn đo mức độ phân tán quanh giá trị trung bình. Lớp 12A có độ lệch chuẩn nhỏ hơn nên mức độ đồng đều cao hơn."}]'::jsonb,'["math-12-grouped-dispersion"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-conditional-probability',16,'LESSON','Xác suất có điều kiện và quy tắc nhân','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Xác suất của biến cố A với điều kiện biến cố B đã xảy ra (P(B) > 0) là P(A|B) = P(A ∩ B) / P(B). Quy tắc nhân xác suất: P(A ∩ B) = P(B) · P(A|B). Khi A và B độc lập thì P(A|B) = P(A)."]'::jsonb,'["Gieo xúc xắc cân đối. Gọi B là biến cố ''xuất hiện mặt chẵn'' ({2, 4, 6}), A là biến cố ''xuất hiện mặt 6''. P(B) = 3/6 = 1/2, P(A ∩ B) = 1/6. Xác suất P(A|B) = (1/6)/(1/2) = 1/3."]'::jsonb,'[{"id": "math-12-conditional-probability-q1", "prompt": "Cho hai biến cố A và B với P(B) > 0. Công thức tính xác suất có điều kiện của A khi biết B đã xảy ra là:", "difficulty": "EASY", "options": [{"id": "a", "text": "P(A|B) = P(A) / P(B)"}, {"id": "b", "text": "P(A|B) = P(A ∩ B) · P(B)"}, {"id": "c", "text": "P(A|B) = P(A ∩ B) / P(B)"}], "correctOptionId": "c", "explanation": "Định nghĩa xác suất có điều kiện là tỉ số giữa xác suất đồng thời P(A ∩ B) và xác suất điều kiện P(B)."}, {"id": "math-12-conditional-probability-q2", "prompt": "Cho P(A) = 0,6; P(B) = 0,5 và P(A ∩ B) = 0,3. Giá trị của P(A|B) bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,15"}, {"id": "b", "text": "0,6"}, {"id": "c", "text": "0,5"}], "correctOptionId": "b", "explanation": "P(A|B) = P(A ∩ B) / P(B) = 0,3 / 0,5 = 0,6."}, {"id": "math-12-conditional-probability-q3", "prompt": "Một hộp có 5 viên bi xanh và 3 viên bi đỏ. Rút ngẫu nhiên lần lượt hai viên không hoàn lại. Xác suất để viên thứ hai rút được màu đỏ biết rằng viên thứ nhất màu xanh là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "3/7"}, {"id": "b", "text": "3/8"}, {"id": "c", "text": "2/7"}], "correctOptionId": "a", "explanation": "Sau khi rút viên 1 màu xanh, trong hộp còn 4 bi xanh và 3 bi đỏ (tổng cộng 7 viên). Xác suất chọn được bi đỏ là 3/7."}]'::jsonb,'["math-12-conditional-probability"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-bayes-formula',17,'LESSON','Công thức xác suất toàn phần và công thức Bayes','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Nếu {B₁, B₂} tạo thành một hệ biến cố đầy đủ thì công thức xác suất toàn phần là P(A) = P(B₁)P(A|B₁) + P(B₂)P(A|B₂). Công thức Bayes cho phép cập nhật xác suất tiên nghiệm khi có bằng chứng: P(B₁|A) = [P(B₁)P(A|B₁)] / P(A)."]'::jsonb,'["Xét nghiệm y tế có tỉ lệ dương tính giả; công thức Bayes cho phép tính xác suất thực sự mang bệnh khi kết quả xét nghiệm dương tính."]'::jsonb,'[{"id": "math-12-bayes-formula-q1", "prompt": "Nếu {B₁, B₂} là một hệ đầy đủ các biến cố thì công thức xác suất toàn phần đối với biến cố A là:", "difficulty": "EASY", "options": [{"id": "a", "text": "P(A) = P(A|B₁) · P(A|B₂)"}, {"id": "b", "text": "P(A) = P(B₁) · P(A|B₁) + P(B₂) · P(A|B₂)"}, {"id": "c", "text": "P(A) = P(B₁) + P(B₂)"}], "correctOptionId": "b", "explanation": "Công thức xác suất toàn phần phân tích biến cố A thành tổng hợp các trường hợp loại trừ nhau tương ứng với hệ đầy đủ."}, {"id": "math-12-bayes-formula-q2", "prompt": "Một xí nghiệp có hai dây chuyền sản xuất: máy I sản xuất 60% sản phẩm với tỉ lệ phế phẩm 2%; máy II sản xuất 40% sản phẩm với tỉ lệ phế phẩm 3%. Tỉ lệ phế phẩm chung P(A) của xí nghiệp là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,024 (2,4%)"}, {"id": "b", "text": "0,050 (5,0%)"}, {"id": "c", "text": "0,012 (1,2%)"}], "correctOptionId": "a", "explanation": "P(A) = P(I)P(A|I) + P(II)P(A|II) = 0,6 * 0,02 + 0,4 * 0,03 = 0,012 + 0,012 = 0,024 = 2,4%."}, {"id": "math-12-bayes-formula-q3", "prompt": "Từ dữ liệu xí nghiệp trên: lấy ngẫu nhiên một sản phẩm thấy bị phế phẩm. Xác suất để phế phẩm đó do máy I sản xuất là bao nhiêu (theo công thức Bayes)?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "0,60 (60%)"}, {"id": "b", "text": "0,40 (40%)"}, {"id": "c", "text": "0,50 (50%)"}], "correctOptionId": "c", "explanation": "Theo công thức Bayes: P(I|A) = [P(I)P(A|I)] / P(A) = (0,6 * 0,02) / 0,024 = 0,012 / 0,024 = 0,5 (50%)."}]'::jsonb,'["math-12-bayes-formula"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('math',12,'intro-2026.1','math-12-review-3',18,'FIVE_LESSON_REVIEW','Ôn tập 3','Toán 12: Khảo sát hàm số, Hình học Oxyz và Thống kê - Xác suất','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "math-12-antiderivative-q1", "prompt": "Cho F(x) là một nguyên hàm của hàm số f(x) trên khoảng K. Khẳng định nào sau đây đúng?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đạo hàm F''(x) bằng -f(x) với mọi x thuộc K"}, {"id": "b", "text": "∫ F(x) dx = f(x) + C"}, {"id": "c", "text": "F''(x) = f(x) với mọi x thuộc K"}], "correctOptionId": "c", "explanation": "Định nghĩa nguyên hàm: F(x) là nguyên hàm của f(x) khi và chỉ khi đạo hàm của F(x) bằng f(x)."}, {"id": "math-12-antiderivative-q2", "prompt": "Tìm họ nguyên hàm của hàm số f(x) = 4x³ - 2x + 1.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "4x⁴ - 2x² + x + C"}, {"id": "b", "text": "x⁴ - x² + x + C"}, {"id": "c", "text": "12x² - 2 + C"}], "correctOptionId": "b", "explanation": "Áp dụng công thức nguyên hàm từng số hạng: ∫ 4x³ dx = x⁴, ∫ (-2x) dx = -x², ∫ 1 dx = x."}, {"id": "math-12-definite-integral-q1", "prompt": "Theo công thức Newton - Leibniz, nếu F(x) là một nguyên hàm của hàm số f(x) liên tục trên [a; b] thì:", "difficulty": "EASY", "options": [{"id": "a", "text": "∫_a^b f(x) dx = F(a) + F(b)"}, {"id": "b", "text": "∫_a^b f(x) dx = F(b) - F(a)"}, {"id": "c", "text": "∫_a^b f(x) dx = F(a) - F(b)"}], "correctOptionId": "b", "explanation": "Công thức cơ bản của giải tích liên hệ tích phân xác định với hiệu giá trị của nguyên hàm tại hai đầu mút."}, {"id": "math-12-definite-integral-q2", "prompt": "Tính tích phân I = ∫_1^2 (3x² + 1) dx.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8"}, {"id": "b", "text": "10"}, {"id": "c", "text": "7"}], "correctOptionId": "a", "explanation": "F(x) = x³ + x. Ta có F(2) = 2³ + 2 = 10; F(1) = 1³ + 1 = 2. Vậy I = F(2) - F(1) = 10 - 2 = 8."}, {"id": "math-12-grouped-dispersion-q1", "prompt": "Số đặc trưng nào bằng căn bậc hai số học của phương sai trong thống kê?", "difficulty": "EASY", "options": [{"id": "a", "text": "Độ lệch chuẩn"}, {"id": "b", "text": "Khoảng biến thiên"}, {"id": "c", "text": "Khoảng tứ phân vị"}], "correctOptionId": "a", "explanation": "Độ lệch chuẩn s được định nghĩa là căn bậc hai số học của phương sai s²: s = √(s²)."}, {"id": "math-12-grouped-dispersion-q2", "prompt": "Một mẫu số liệu ghép nhóm có tứ phân vị thứ nhất Q₁ = 45 và tứ phân vị thứ ba Q₃ = 75. Khoảng tứ phân vị IQR của mẫu bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "120"}, {"id": "b", "text": "60"}, {"id": "c", "text": "30"}], "correctOptionId": "c", "explanation": "Khoảng tứ phân vị được tính theo công thức IQR = Q₃ - Q₁ = 75 - 45 = 30."}, {"id": "math-12-conditional-probability-q1", "prompt": "Cho hai biến cố A và B với P(B) > 0. Công thức tính xác suất có điều kiện của A khi biết B đã xảy ra là:", "difficulty": "EASY", "options": [{"id": "a", "text": "P(A|B) = P(A) / P(B)"}, {"id": "b", "text": "P(A|B) = P(A ∩ B) · P(B)"}, {"id": "c", "text": "P(A|B) = P(A ∩ B) / P(B)"}], "correctOptionId": "c", "explanation": "Định nghĩa xác suất có điều kiện là tỉ số giữa xác suất đồng thời P(A ∩ B) và xác suất điều kiện P(B)."}, {"id": "math-12-conditional-probability-q2", "prompt": "Cho P(A) = 0,6; P(B) = 0,5 và P(A ∩ B) = 0,3. Giá trị của P(A|B) bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,15"}, {"id": "b", "text": "0,6"}, {"id": "c", "text": "0,5"}], "correctOptionId": "b", "explanation": "P(A|B) = P(A ∩ B) / P(B) = 0,3 / 0,5 = 0,6."}, {"id": "math-12-bayes-formula-q1", "prompt": "Nếu {B₁, B₂} là một hệ đầy đủ các biến cố thì công thức xác suất toàn phần đối với biến cố A là:", "difficulty": "EASY", "options": [{"id": "a", "text": "P(A) = P(A|B₁) · P(A|B₂)"}, {"id": "b", "text": "P(A) = P(B₁) · P(A|B₁) + P(B₂) · P(A|B₂)"}, {"id": "c", "text": "P(A) = P(B₁) + P(B₂)"}], "correctOptionId": "b", "explanation": "Công thức xác suất toàn phần phân tích biến cố A thành tổng hợp các trường hợp loại trừ nhau tương ứng với hệ đầy đủ."}, {"id": "math-12-bayes-formula-q2", "prompt": "Một xí nghiệp có hai dây chuyền sản xuất: máy I sản xuất 60% sản phẩm với tỉ lệ phế phẩm 2%; máy II sản xuất 40% sản phẩm với tỉ lệ phế phẩm 3%. Tỉ lệ phế phẩm chung P(A) của xí nghiệp là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,024 (2,4%)"}, {"id": "b", "text": "0,050 (5,0%)"}, {"id": "c", "text": "0,012 (1,2%)"}], "correctOptionId": "a", "explanation": "P(A) = P(I)P(A|I) + P(II)P(A|II) = 0,6 * 0,02 + 0,4 * 0,03 = 0,012 + 0,012 = 0,024 = 2,4%."}]'::jsonb,'["math-12-antiderivative", "math-12-definite-integral", "math-12-grouped-dispersion", "math-12-conditional-probability", "math-12-bayes-formula"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','placement',0,'PLACEMENT','Khảo sát đầu vào','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "physics-12-matter-model-q1", "prompt": "Theo mô hình động học phân tử, khi nhiệt độ của một vật tăng lên thì:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tốc độ chuyển động hỗn loạn của các phân tử cấu tạo nên vật tăng"}, {"id": "b", "text": "Khối lượng của mỗi phân tử cấu tạo nên vật tăng lên"}, {"id": "c", "text": "Khoảng cách giữa các phân tử luôn giảm đi đáng kể"}], "correctOptionId": "a", "explanation": "Nhiệt độ là số đo động năng chuyển động nhiệt trung bình của các phân tử. Nhiệt độ tăng nghĩa là phân tử chuyển động nhanh hơn."}, {"id": "physics-12-matter-model-q2", "prompt": "Đặc điểm căn bản về cấu trúc phân tử của chất ở thể khí so với thể rắn và lỏng là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Các phân tử khí liên kết chặt chẽ và chỉ dao động quanh vị trí cân bằng"}, {"id": "b", "text": "Các phân tử khí hoàn toàn không có tương tác đẩy"}, {"id": "c", "text": "Khoảng cách giữa các phân tử rất lớn so với kích thước của chính chúng"}], "correctOptionId": "c", "explanation": "Ở thể khí, khoảng cách trung bình giữa các phân tử lớn gấp hàng chục lần kích thước phân tử nên lực tương tác rất yếu."}, {"id": "physics-12-temperature-scales-q1", "prompt": "Hai vật ở trạng thái cân bằng nhiệt với nhau khi và chỉ khi chúng có cùng:", "difficulty": "EASY", "options": [{"id": "a", "text": "Nội năng"}, {"id": "b", "text": "Khối lượng"}, {"id": "c", "text": "Nhiệt độ"}], "correctOptionId": "c", "explanation": "Điều kiện cân bằng nhiệt giữa hai hệ tiếp xúc nhiệt là nhiệt độ của chúng bằng nhau, khi đó không còn dòng nhiệt truyền qua lại."}, {"id": "physics-12-temperature-scales-q2", "prompt": "Nhiệt độ sôi của nước ở áp suất tiêu chuẩn là 100 °C tương ứng với bao nhiêu Kelvin?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "100 K"}, {"id": "b", "text": "373,15 K"}, {"id": "c", "text": "273,15 K"}], "correctOptionId": "b", "explanation": "Công thức chuyển đổi: T(K) = t(°C) + 273,15 = 100 + 273,15 = 373,15 K."}, {"id": "physics-12-heat-capacity-q1", "prompt": "Đơn vị đo của nhiệt dung riêng trong hệ đơn vị quốc tế SI là:", "difficulty": "EASY", "options": [{"id": "a", "text": "W/(kg·K)"}, {"id": "b", "text": "J/(kg·K)"}, {"id": "c", "text": "J/kg"}], "correctOptionId": "b", "explanation": "Nhiệt dung riêng c = Q / (m·ΔT) có đơn vị là Joule trên kilogram Kelvin (J/(kg·K))."}, {"id": "physics-12-heat-capacity-q2", "prompt": "Tính nhiệt lượng cần thiết để đun nóng 2 kg nước từ 20 °C lên 80 °C. Biết nhiệt dung riêng của nước c = 4200 J/(kg·K).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "504 kJ"}, {"id": "b", "text": "252 kJ"}, {"id": "c", "text": "672 kJ"}], "correctOptionId": "a", "explanation": "Q = m · c · ΔT = 2 · 4200 · (80 - 20) = 8400 · 60 = 504 000 J = 504 kJ."}, {"id": "physics-12-internal-energy-q1", "prompt": "Biểu thức toán học của định luật I nhiệt động lực học là:", "difficulty": "EASY", "options": [{"id": "a", "text": "ΔU = Q + A"}, {"id": "b", "text": "ΔU = Q · A"}, {"id": "c", "text": "Q = ΔU + A²"}], "correctOptionId": "a", "explanation": "Định luật I là dạng biểu diễn của định luật bảo toàn và chuyển hóa năng lượng áp dụng cho các quá trình nhiệt: ΔU = Q + A."}, {"id": "physics-12-internal-energy-q2", "prompt": "Một khối khí nhận nhiệt lượng 600 J từ nguồn nhiệt và thực hiện công 400 J đẩy piston nâng vật nặng lên. Độ biến thiên nội năng của khối khí là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "+1000 J"}, {"id": "b", "text": "-200 J"}, {"id": "c", "text": "+200 J"}], "correctOptionId": "c", "explanation": "Hệ nhận nhiệt: Q = +600 J; hệ sinh công: A = -400 J. Ta có ΔU = Q + A = 600 + (-400) = +200 J."}, {"id": "physics-12-thermal-efficiency-q1", "prompt": "Hiệu suất nhiệt H của động cơ nhiệt được định nghĩa là tỉ số giữa:", "difficulty": "EASY", "options": [{"id": "a", "text": "Nhiệt lượng truyền cho nguồn lạnh và nhiệt lượng nhận từ nguồn nóng"}, {"id": "b", "text": "Nhiệt lượng nhận từ nguồn nóng và công toàn phần"}, {"id": "c", "text": "Công cơ học có ích sinh ra và nhiệt lượng nhận từ nguồn nóng"}], "correctOptionId": "c", "explanation": "Hiệu suất H = A'' / Q₁ phản ánh tỉ lệ nhiệt năng được chuyển hóa thành cơ công hữu ích."}, {"id": "physics-12-thermal-efficiency-q2", "prompt": "Một động cơ nhiệt nhận nhiệt lượng 2000 J từ nguồn nóng trong mỗi chu trình và nhả cho nguồn lạnh 1200 J. Hiệu suất của động cơ là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "30%"}, {"id": "b", "text": "40%"}, {"id": "c", "text": "60%"}], "correctOptionId": "b", "explanation": "Công có ích A'' = Q₁ - |Q₂| = 2000 - 1200 = 800 J. Hiệu suất H = 800 / 2000 = 0,4 = 40%."}, {"id": "physics-12-ideal-gas-model-q1", "prompt": "Trong mô hình khí lí tưởng, tương tác giữa các phân tử khí được xem xét như thế nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn đẩy nhau liên tục kể cả khi ở rất xa nhau"}, {"id": "b", "text": "Chỉ tương tác đẩy hoặc hút khi chúng va chạm vào nhau hoặc vào thành bình"}, {"id": "c", "text": "Luôn hút nhau bằng lực tĩnh điện mạnh ở mọi khoảng cách"}], "correctOptionId": "b", "explanation": "Mô hình khí lí tưởng bỏ qua tương tác tầm xa giữa các phân tử; lực tương tác chỉ xuất hiện tức thời khi có va chạm."}, {"id": "physics-12-ideal-gas-model-q2", "prompt": "Mô hình khí lí tưởng coi các phân tử khí là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Các chất điểm có khối lượng nhưng thể tích bản thân không đáng kể so với thể tích bình"}, {"id": "b", "text": "Các hình cầu rắn có kích thước bằng thể tích bình chứa"}, {"id": "c", "text": "Các hạt đứng yên tại các nút mạng tinh thể xác định"}], "correctOptionId": "a", "explanation": "Vì khoảng cách giữa các phân tử khí rất lớn so với kích thước của chúng nên thể tích riêng của các phân tử được coi là chất điểm."}, {"id": "physics-12-boyle-law-q1", "prompt": "Định luật Boyle áp dụng cho quá trình biến đổi trạng thái nào của chất khí?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quá trình đẳng nhiệt"}, {"id": "b", "text": "Quá trình đẳng áp"}, {"id": "c", "text": "Quá trình đẳng tích"}], "correctOptionId": "a", "explanation": "Định luật Boyle nghiên cứu mối quan hệ giữa áp suất và thể tích khi nhiệt độ T được giữ không đổi."}, {"id": "physics-12-boyle-law-q2", "prompt": "Một khối khí lí tưởng có thể tích 6 lít ở áp suất 1,5 atm. Giữ nhiệt độ không đổi, nén khối khí đến thể tích 2 lít thì áp suất mới là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2,0 atm"}, {"id": "b", "text": "3,0 atm"}, {"id": "c", "text": "4,5 atm"}], "correctOptionId": "c", "explanation": "Theo định luật Boyle: p₁V₁ = p₂V₂ ⇒ p₂ = (1,5 * 6) / 2 = 9 / 2 = 4,5 atm."}, {"id": "physics-12-charles-law-q1", "prompt": "Trong quá trình đẳng áp của một lượng khí lí tưởng xác định, thể tích của khối khí:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tỉ lệ nghịch với nhiệt độ tuyệt đối T"}, {"id": "b", "text": "Tỉ lệ thuận với bình phương nhiệt độ Celsius"}, {"id": "c", "text": "Tỉ lệ thuận với nhiệt độ tuyệt đối T"}], "correctOptionId": "c", "explanation": "Định luật Charles: V / T = const, thể tích tỉ lệ thuận với nhiệt độ tính theo thang Kelvin."}, {"id": "physics-12-charles-law-q2", "prompt": "Một khối khí có thể tích 5 lít ở nhiệt độ 250 K. Giữ áp suất không đổi, khi nung nóng khối khí đến 350 K thì thể tích của nó bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8,5 lít"}, {"id": "b", "text": "7,0 lít"}, {"id": "c", "text": "6,0 lít"}], "correctOptionId": "b", "explanation": "Theo định luật Charles: V₂ = V₁ · (T₂ / T₁) = 5 · (350 / 250) = 5 · 1,4 = 7,0 lít."}, {"id": "physics-12-state-equation-q1", "prompt": "Phương trình trạng thái của khí lí tưởng cho một lượng khí xác định là:", "difficulty": "EASY", "options": [{"id": "a", "text": "(p · T) · V = hằng số"}, {"id": "b", "text": "(p · V) / T = hằng số"}, {"id": "c", "text": "p · T / V = hằng số"}], "correctOptionId": "b", "explanation": "Phương trình trạng thái kết hợp định luật Boyle và Charles cho hệ thức tổng quát pV/T = const."}, {"id": "physics-12-state-equation-q2", "prompt": "Tính áp suất của 1 mol khí lí tưởng chứa trong bình kín thể tích 0,01 m³ ở nhiệt độ 300 K. Cho hằng số khí R = 8,31 J/(mol·K).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2,49 × 10⁵ Pa"}, {"id": "b", "text": "1,25 × 10⁵ Pa"}, {"id": "c", "text": "8,31 × 10⁴ Pa"}], "correctOptionId": "a", "explanation": "Áp dụng p = nRT / V = (1 · 8,31 · 300) / 0,01 = 2493 / 0,01 = 249 300 Pa ≈ 2,49 × 10⁵ Pa."}, {"id": "physics-12-molecular-pressure-q1", "prompt": "Động năng chuyển động nhiệt tịnh tiến trung bình của các phân tử khí lí tưởng tỉ lệ thuận với:", "difficulty": "EASY", "options": [{"id": "a", "text": "Nhiệt độ tuyệt đối T của chất khí"}, {"id": "b", "text": "Thể tích V của bình chứa"}, {"id": "c", "text": "Khối lượng mol M của chất khí"}], "correctOptionId": "a", "explanation": "Hệ thức Boltzmann E_d = (3/2)kT cho thấy động năng tịnh tiến trung bình tỉ lệ thuận trực tiếp với nhiệt độ Kelvin."}, {"id": "physics-12-molecular-pressure-q2", "prompt": "Bản chất vi mô của áp suất chất khí tác dụng lên thành bình chứa là do:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Trọng lực của các phân tử khí đè nén lên đáy bình chứa"}, {"id": "b", "text": "Lực hút tĩnh điện giữa thành bình và các electron của chất khí"}, {"id": "c", "text": "Hàng tỉ phân tử khí va chạm liên tục và truyền động lượng lên thành bình"}], "correctOptionId": "c", "explanation": "Mỗi phân tử va chạm đàn hồi vào thành bình làm đổi hướng vận tốc, truyền xung lượng; tổng hợp vô số va chạm tạo nên áp suất liên tục."}, {"id": "physics-12-magnetic-field-q1", "prompt": "Từ trường không tác dụng lực lên đối tượng nào sau đây?", "difficulty": "EASY", "options": [{"id": "a", "text": "Một đoạn dây dẫn có dòng điện chạy qua"}, {"id": "b", "text": "Một hạt mang điện đang chuyển động cắt các đường sức từ"}, {"id": "c", "text": "Một điện tích đứng yên trong từ trường"}], "correctOptionId": "c", "explanation": "Lực từ chỉ xuất hiện khi điện tích chuyển động (hoặc có dòng điện); điện tích đứng yên không chịu tác dụng của lực từ."}, {"id": "physics-12-magnetic-field-q2", "prompt": "Tính chất hình học cơ bản của các đường sức từ là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Luôn cắt nhau tại các điểm có từ trường mạnh"}, {"id": "b", "text": "Là những đường cong khép kín (hoặc vô hạn ở hai đầu)"}, {"id": "c", "text": "Là các đoạn thẳng hở bắt đầu từ cực dương và kết thúc ở cực âm"}], "correctOptionId": "b", "explanation": "Từ trường là trường xoáy, không có điểm khởi đầu hay kết thúc nên các đường sức từ luôn là đường cong kín."}, {"id": "physics-12-magnetic-force-q1", "prompt": "Lực từ tác dụng lên đoạn dây dẫn mang dòng điện đặt trong từ trường đều đạt giá trị cực đại khi góc θ giữa đoạn dây và vectơ cảm ứng từ bằng:", "difficulty": "EASY", "options": [{"id": "a", "text": "180°"}, {"id": "b", "text": "90°"}, {"id": "c", "text": "0°"}], "correctOptionId": "b", "explanation": "F = B·I·L·sin θ. Hàm sin θ đạt cực đại bằng 1 khi góc θ = 90° (dây dẫn vuông góc với đường sức từ)."}, {"id": "physics-12-magnetic-force-q2", "prompt": "Đoạn dây dẫn thẳng dài 0,2 m mang dòng điện cường độ 5 A đặt vuông góc với các đường cảm ứng từ của từ trường đều B = 0,4 T. Độ lớn lực từ tác dụng lên đoạn dây là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,4 N"}, {"id": "b", "text": "0,8 N"}, {"id": "c", "text": "0,2 N"}], "correctOptionId": "a", "explanation": "F = B · I · L · sin 90° = 0,4 · 5 · 0,2 · 1 = 0,4 N."}, {"id": "physics-12-magnetic-induction-q1", "prompt": "Vectơ cảm ứng từ B tại một điểm đặc trưng cho từ trường tại điểm đó về phương diện:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tác dụng lực từ"}, {"id": "b", "text": "Năng lượng tĩnh điện"}, {"id": "c", "text": "Tốc độ truyền sóng"}], "correctOptionId": "a", "explanation": "Cảm ứng từ B là đại lượng vectơ đặc trưng cho từ trường về mặt gây ra lực từ tác dụng lên dòng điện hay điện tích chuyển động."}, {"id": "physics-12-magnetic-induction-q2", "prompt": "Tính cảm ứng từ do dòng điện thẳng dài cường độ 10 A gây ra tại một điểm cách dây dẫn 0,05 m trong không khí.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2 × 10⁻⁵ T"}, {"id": "b", "text": "4 × 10⁻⁶ T"}, {"id": "c", "text": "4 × 10⁻⁵ T"}], "correctOptionId": "c", "explanation": "B = 2 · 10⁻⁷ · (I / r) = 2 · 10⁻⁷ · (10 / 0,05) = 2 · 10⁻⁷ · 200 = 4 · 10⁻⁵ T."}, {"id": "physics-12-lorentz-force-q1", "prompt": "Phương của lực Lorentz tác dụng lên hạt mang điện chuyển động trong từ trường đều có đặc điểm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cùng phương với vectơ cảm ứng từ B"}, {"id": "b", "text": "Cùng phương với vectơ vận tốc v của hạt"}, {"id": "c", "text": "Vuông góc với cả vectơ vận tốc v và vectơ cảm ứng từ B"}], "correctOptionId": "c", "explanation": "Lực Lorentz có phương vuông góc với mặt phẳng tạo bởi vectơ vận tốc v và vectơ cảm ứng từ B."}, {"id": "physics-12-lorentz-force-q2", "prompt": "Một hạt mang điện tích q = 1,6·10⁻¹⁹ C bay với vận tốc v = 2·10⁶ m/s vuông góc vào từ trường đều B = 0,5 T. Độ lớn lực Lorentz tác dụng lên hạt là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,8 × 10⁻¹³ N"}, {"id": "b", "text": "1,6 × 10⁻¹³ N"}, {"id": "c", "text": "3,2 × 10⁻¹³ N"}], "correctOptionId": "b", "explanation": "f = |q| · v · B · sin 90° = 1,6 · 10⁻¹⁹ · 2 · 10⁶ · 0,5 · 1 = 1,6 · 10⁻¹³ N."}, {"id": "physics-12-electromagnetic-induction-q1", "prompt": "Điều kiện tiên quyết để xuất hiện dòng điện cảm ứng trong một khung dây dẫn kín là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Khung dây phải luôn chuyển động nhanh dần đều"}, {"id": "b", "text": "Từ thông qua diện tích giới hạn bởi khung dây biến thiên theo thời gian"}, {"id": "c", "text": "Khung dây phải được đặt trong từ trường có độ lớn cực kì lớn"}], "correctOptionId": "b", "explanation": "Hiện tượng cảm ứng điện từ chỉ xảy ra khi có sự biến thiên từ thông gửi qua mạch kín theo thời gian."}, {"id": "physics-12-electromagnetic-induction-q2", "prompt": "Từ thông qua một mạch kín biến thiên đều giảm từ 0,08 Wb xuống 0,02 Wb trong khoảng thời gian 0,1 s. Độ lớn suất điện động cảm ứng xuất hiện trong mạch là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,6 V"}, {"id": "b", "text": "0,06 V"}, {"id": "c", "text": "6,0 V"}], "correctOptionId": "a", "explanation": "Theo định luật Faraday: |e_c| = |ΔΦ / Δt| = |(0,02 - 0,08) / 0,1| = |-0,06 / 0,1| = 0,6 V."}, {"id": "physics-12-nuclear-structure-q1", "prompt": "Hạt nhân nguyên tử được cấu tạo bởi hai loại hạt cơ bản (gọi chung là nucleon) gồm:", "difficulty": "EASY", "options": [{"id": "a", "text": "Proton và neutron"}, {"id": "b", "text": "Proton và electron"}, {"id": "c", "text": "Neutron và electron"}], "correctOptionId": "a", "explanation": "Nucleon cấu tạo nên hạt nhân nguyên tử bao gồm các hạt proton mang điện tích dương và neutron không mang điện."}, {"id": "physics-12-nuclear-structure-q2", "prompt": "Hạt nhân He-4 có độ hụt khối Δm = 0,0304 u. Cho biết 1 u ≈ 931,5 MeV/c². Năng lượng liên kết của hạt nhân He-4 xấp xỉ bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "14,2 MeV"}, {"id": "b", "text": "56,6 MeV"}, {"id": "c", "text": "28,3 MeV"}], "correctOptionId": "c", "explanation": "E_lk = Δm · c² = 0,0304 u · c² = 0,0304 · 931,5 MeV ≈ 28,3 MeV."}, {"id": "physics-12-radioactivity-q1", "prompt": "Tia phóng xạ nào sau đây có bản chất là sóng điện từ có bước sóng cực ngắn và năng lượng photon rất cao?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tia alpha (α)"}, {"id": "b", "text": "Tia beta trừ (β⁻)"}, {"id": "c", "text": "Tia gamma (γ)"}], "correctOptionId": "c", "explanation": "Tia gamma là bức xạ điện từ không mang điện, có tần số rất cao và khả năng đâm xuyên mạnh nhất."}, {"id": "physics-12-radioactivity-q2", "prompt": "Một chất phóng xạ có chu kì bán rã T = 8 ngày. Sau khoảng thời gian 24 ngày, tỉ lệ phần trăm số hạt nhân phóng xạ còn lại chưa phân rã so với ban đầu là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "6,25%"}, {"id": "b", "text": "12,5%"}, {"id": "c", "text": "25,0%"}], "correctOptionId": "b", "explanation": "Số chu kì bán rã trôi qua là k = t / T = 24 / 8 = 3. Số hạt còn lại: N / N₀ = (1/2)³ = 1/8 = 12,5%."}, {"id": "physics-12-nuclear-reactions-q1", "prompt": "Định luật nào sau đây KHÔNG áp dụng cho các phản ứng hạt nhân?", "difficulty": "EASY", "options": [{"id": "a", "text": "Định luật bảo toàn số nucleon (số khối A)"}, {"id": "b", "text": "Định luật bảo toàn khối lượng nghỉ"}, {"id": "c", "text": "Định luật bảo toàn điện tích"}], "correctOptionId": "b", "explanation": "Trong phản ứng hạt nhân, tổng khối lượng nghỉ trước và sau phản ứng có sự chênh lệch (độ hụt khối chuyển hóa thành năng lượng) nên khối lượng nghỉ không bảo toàn."}, {"id": "physics-12-nuclear-reactions-q2", "prompt": "Trong phản ứng hạt nhân: ₁²H + ₁³H → ₂⁴He + X. Hạt X sinh ra là hạt nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hạt neutron (₀¹n)"}, {"id": "b", "text": "Hạt proton (₁¹p)"}, {"id": "c", "text": "Hạt electron (-₁⁰e)"}], "correctOptionId": "a", "explanation": "Áp dụng bảo toàn điện tích Z: 1 + 1 = 2 + Z_X ⇒ Z_X = 0. Bảo toàn số nucleon A: 2 + 3 = 4 + A_X ⇒ A_X = 1. Hạt có Z = 0, A = 1 là neutron."}, {"id": "physics-12-fission-fusion-q1", "prompt": "Bản chất của phản ứng nhiệt hạch (phản ứng tổng hợp hạt nhân) là quá trình:", "difficulty": "EASY", "options": [{"id": "a", "text": "Kết hợp hai hạt nhân rất nhẹ thành một hạt nhân nặng hơn ở nhiệt độ cực kì cao"}, {"id": "b", "text": "Bắn phá hạt nhân nặng bằng neutron làm nó vỡ thành hai mảnh nhẹ"}, {"id": "c", "text": "Hạt nhân tự phát bức xạ tia gamma mà không thay đổi cấu tạo"}], "correctOptionId": "a", "explanation": "Nhiệt hạch là phản ứng kết hợp hai hạt nhân có số khối nhỏ (như hydro, deuteri, triti) thành hạt nhân nặng hơn ở điều kiện nhiệt độ hàng trăm triệu độ."}, {"id": "physics-12-fission-fusion-q2", "prompt": "Để duy trì phản ứng phân hạch dây chuyền tự duy trì có kiểm soát hoạt động ổn định trong lò phản ứng hạt nhân, hệ số nhân neutron k phải bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "k > 1"}, {"id": "b", "text": "k < 1"}, {"id": "c", "text": "k = 1"}], "correctOptionId": "c", "explanation": "Hệ số k = 1 gọi là trạng thái tới hạn: số neutron sinh ra trung bình bù đắp đủ số neutron thất thoát và hấp thụ, duy trì công suất phát điện ổn định."}, {"id": "physics-12-radiation-safety-q1", "prompt": "Biện pháp nào sau đây giúp giảm liều chiếu xạ nguy hiểm cho người khi làm việc gần nguồn phóng xạ?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đứng càng gần nguồn phát phóng xạ càng tốt"}, {"id": "b", "text": "Tăng tối đa thời gian tiếp xúc trực tiếp với nguồn phóng xạ"}, {"id": "c", "text": "Tăng khoảng cách tới nguồn và sử dụng tấm che chắn chì/bê tông dày"}], "correctOptionId": "c", "explanation": "Liều bức xạ tỉ lệ nghịch với bình phương khoảng cách và giảm theo hàm mũ khi qua các tấm che chắn chì hoặc bê tông."}, {"id": "physics-12-radiation-safety-q2", "prompt": "Ứng dụng quan trọng của nguồn phóng xạ phát tia gamma trong y học hiện đại là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đun sôi nước khử trùng phòng bệnh nhanh chóng"}, {"id": "b", "text": "Xạ trị tiêu diệt tế bào khối u ác tính hoặc phẫu thuật bằng dao mổ gamma"}, {"id": "c", "text": "Uống trực tiếp để cung cấp năng lượng trao đổi chất cho cơ thể"}], "correctOptionId": "b", "explanation": "Tia gamma mang năng lượng photon lớn được hội tụ chính xác để phá hủy cấu trúc DNA của các tế bào ung thư mà ít tổn thương mô lành."}]'::jsonb,'[]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-matter-model',1,'LESSON','Mô hình động học phân tử và cấu trúc chất','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Mọi chất đều cấu tạo từ các phân tử chuyển động không ngừng; nhiệt độ càng cao thì chuyển động nhiệt càng nhanh. Thể rắn có trật tự và thể tích, hình dạng xác định; thể lỏng có thể tích xác định nhưng hình dạng theo bình chứa; thể khí phân tử ở rất xa nhau và chuyển động hỗn loạn."]'::jsonb,'["Mở nắp lọ tinh dầu ở một góc phòng, một lát sau cả phòng đều ngửi thấy mùi thơm do các phân tử khuếch tán vào không khí nhờ chuyển động nhiệt."]'::jsonb,'[{"id": "physics-12-matter-model-q1", "prompt": "Theo mô hình động học phân tử, khi nhiệt độ của một vật tăng lên thì:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tốc độ chuyển động hỗn loạn của các phân tử cấu tạo nên vật tăng"}, {"id": "b", "text": "Khối lượng của mỗi phân tử cấu tạo nên vật tăng lên"}, {"id": "c", "text": "Khoảng cách giữa các phân tử luôn giảm đi đáng kể"}], "correctOptionId": "a", "explanation": "Nhiệt độ là số đo động năng chuyển động nhiệt trung bình của các phân tử. Nhiệt độ tăng nghĩa là phân tử chuyển động nhanh hơn."}, {"id": "physics-12-matter-model-q2", "prompt": "Đặc điểm căn bản về cấu trúc phân tử của chất ở thể khí so với thể rắn và lỏng là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Các phân tử khí liên kết chặt chẽ và chỉ dao động quanh vị trí cân bằng"}, {"id": "b", "text": "Các phân tử khí hoàn toàn không có tương tác đẩy"}, {"id": "c", "text": "Khoảng cách giữa các phân tử rất lớn so với kích thước của chính chúng"}], "correctOptionId": "c", "explanation": "Ở thể khí, khoảng cách trung bình giữa các phân tử lớn gấp hàng chục lần kích thước phân tử nên lực tương tác rất yếu."}, {"id": "physics-12-matter-model-q3", "prompt": "Hiện tượng khuếch tán chất màu trong nước xảy ra nhanh hơn khi nước nóng hơn là do:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Nước nóng làm phân tử chất màu bị phân hủy thành nguyên tử"}, {"id": "b", "text": "Nhiệt độ cao làm các phân tử nước và phân tử màu chuyển động nhiệt nhanh hơn"}, {"id": "c", "text": "Nước nóng làm tăng trọng lực tác dụng lên các phân tử màu"}], "correctOptionId": "b", "explanation": "Chuyển động nhiệt của các phân tử diễn ra mãnh liệt hơn ở nhiệt độ cao, thúc đẩy quá trình va chạm và trộn lẫn lẫn nhau."}]'::jsonb,'["physics-12-matter-model"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-temperature-scales',2,'LESSON','Nhiệt độ, thang nhiệt độ và cân bằng nhiệt','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Cân bằng nhiệt xảy ra khi hai vật tiếp xúc truyền nhiệt cho nhau đến khi có cùng nhiệt độ. Thang nhiệt độ Celsius (°C) dựa trên điểm đóng băng và điểm sôi của nước ở 1 atm; thang Kelvin (K) là thang nhiệt độ tuyệt đối: T(K) = t(°C) + 273,15."]'::jsonb,'["Nhiệt độ phòng 25 °C tương ứng với T = 25 + 273,15 = 298,15 K."]'::jsonb,'[{"id": "physics-12-temperature-scales-q1", "prompt": "Hai vật ở trạng thái cân bằng nhiệt với nhau khi và chỉ khi chúng có cùng:", "difficulty": "EASY", "options": [{"id": "a", "text": "Nội năng"}, {"id": "b", "text": "Khối lượng"}, {"id": "c", "text": "Nhiệt độ"}], "correctOptionId": "c", "explanation": "Điều kiện cân bằng nhiệt giữa hai hệ tiếp xúc nhiệt là nhiệt độ của chúng bằng nhau, khi đó không còn dòng nhiệt truyền qua lại."}, {"id": "physics-12-temperature-scales-q2", "prompt": "Nhiệt độ sôi của nước ở áp suất tiêu chuẩn là 100 °C tương ứng với bao nhiêu Kelvin?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "100 K"}, {"id": "b", "text": "373,15 K"}, {"id": "c", "text": "273,15 K"}], "correctOptionId": "b", "explanation": "Công thức chuyển đổi: T(K) = t(°C) + 273,15 = 100 + 273,15 = 373,15 K."}, {"id": "physics-12-temperature-scales-q3", "prompt": "Thả một miếng nhôm ở 80 °C vào cốc nước ở 20 °C trong một bình cách nhiệt. Sau một thời gian hệ đạt cân bằng nhiệt ở 30 °C. Nhận xét nào sau đây đúng?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Miếng nhôm tỏa nhiệt lượng và nước thu vào nhiệt lượng đó"}, {"id": "b", "text": "Cả miếng nhôm và nước đều thu nhiệt từ môi trường ngoài"}, {"id": "c", "text": "Nhiệt độ cuối cùng luôn bằng trung bình cộng hai nhiệt độ ban đầu"}], "correctOptionId": "a", "explanation": "Nhiệt tự truyền từ vật có nhiệt độ cao (nhôm) sang vật có nhiệt độ thấp hơn (nước) cho đến khi đạt cân bằng nhiệt."}]'::jsonb,'["physics-12-temperature-scales"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-heat-capacity',3,'LESSON','Nhiệt dung riêng và nhiệt chuyển thể','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Nhiệt lượng cần để làm biến đổi nhiệt độ: Q = m.c.ΔT (c: nhiệt dung riêng, J/(kg.K)). Nhiệt nóng chảy: Q = λ.m (λ: nhiệt nóng chảy riêng). Nhiệt hóa hơi: Q = L.m (L: nhiệt hóa hơi riêng). Trong quá trình chuyển thể ở áp suất chuẩn, nhiệt độ không đổi."]'::jsonb,'["Cần đun nóng 2 kg nước (c = 4200 J/(kg.K)) từ 25 °C lên 75 °C: Q = 2 * 4200 * (75 - 25) = 420 000 J = 420 kJ."]'::jsonb,'[{"id": "physics-12-heat-capacity-q1", "prompt": "Đơn vị đo của nhiệt dung riêng trong hệ đơn vị quốc tế SI là:", "difficulty": "EASY", "options": [{"id": "a", "text": "W/(kg·K)"}, {"id": "b", "text": "J/(kg·K)"}, {"id": "c", "text": "J/kg"}], "correctOptionId": "b", "explanation": "Nhiệt dung riêng c = Q / (m·ΔT) có đơn vị là Joule trên kilogram Kelvin (J/(kg·K))."}, {"id": "physics-12-heat-capacity-q2", "prompt": "Tính nhiệt lượng cần thiết để đun nóng 2 kg nước từ 20 °C lên 80 °C. Biết nhiệt dung riêng của nước c = 4200 J/(kg·K).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "504 kJ"}, {"id": "b", "text": "252 kJ"}, {"id": "c", "text": "672 kJ"}], "correctOptionId": "a", "explanation": "Q = m · c · ΔT = 2 · 4200 · (80 - 20) = 8400 · 60 = 504 000 J = 504 kJ."}, {"id": "physics-12-heat-capacity-q3", "prompt": "Trong suốt thời gian một khối nước đá tinh khiết đang nóng chảy hoàn toàn ở 0 °C dưới áp suất tiêu chuẩn 1 atm, nhiệt độ của khối đá:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Tăng dần đều từ 0 °C lên 10 °C"}, {"id": "b", "text": "Giảm xuống dưới 0 °C do thu nhiệt"}, {"id": "c", "text": "Giữ nguyên không đổi ở 0 °C"}], "correctOptionId": "c", "explanation": "Nhiệt lượng thu vào trong quá trình chuyển thể dùng để phá vỡ mạng tinh thể, không làm tăng động năng phân tử nên nhiệt độ không đổi."}]'::jsonb,'["physics-12-heat-capacity"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-internal-energy',4,'LESSON','Nội năng và định luật I nhiệt động lực học','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Nội năng U là tổng động năng chuyển động hỗn loạn và thế năng tương tác của các phân tử cấu tạo nên hệ. Định luật I nhiệt động lực học: ΔU = Q + A (quy ước: Q > 0 hệ nhận nhiệt, Q < 0 hệ truyền nhiệt; A > 0 hệ nhận công, A < 0 hệ sinh công)."]'::jsonb,'["Chất khí nhận 500 J nhiệt lượng và thực hiện công 300 J đẩy piston: Q = +500 J, A = -300 J ⇒ ΔU = 500 - 300 = +200 J (nội năng tăng 200 J)."]'::jsonb,'[{"id": "physics-12-internal-energy-q1", "prompt": "Biểu thức toán học của định luật I nhiệt động lực học là:", "difficulty": "EASY", "options": [{"id": "a", "text": "ΔU = Q + A"}, {"id": "b", "text": "ΔU = Q · A"}, {"id": "c", "text": "Q = ΔU + A²"}], "correctOptionId": "a", "explanation": "Định luật I là dạng biểu diễn của định luật bảo toàn và chuyển hóa năng lượng áp dụng cho các quá trình nhiệt: ΔU = Q + A."}, {"id": "physics-12-internal-energy-q2", "prompt": "Một khối khí nhận nhiệt lượng 600 J từ nguồn nhiệt và thực hiện công 400 J đẩy piston nâng vật nặng lên. Độ biến thiên nội năng của khối khí là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "+1000 J"}, {"id": "b", "text": "-200 J"}, {"id": "c", "text": "+200 J"}], "correctOptionId": "c", "explanation": "Hệ nhận nhiệt: Q = +600 J; hệ sinh công: A = -400 J. Ta có ΔU = Q + A = 600 + (-400) = +200 J."}, {"id": "physics-12-internal-energy-q3", "prompt": "Dùng bơm tay để bơm lốp xe đạp, sau một thời gian thân ống bơm bị nóng lên. Nguyên nhân chính là do:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Khối lượng không khí bên trong ống bơm tự tăng lên"}, {"id": "b", "text": "Khí bị nén nhận công làm tăng nội năng và ma sát sinh nhiệt"}, {"id": "c", "text": "Không khí từ khí quyển truyền nhiệt lượng trực tiếp vào ống bơm"}], "correctOptionId": "b", "explanation": "Quá trình nén khí thực hiện công lên chất khí làm tăng nội năng (nhiệt độ tăng) kết hợp với lực ma sát giữa piston và xilanh sinh nhiệt."}]'::jsonb,'["physics-12-internal-energy"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-thermal-efficiency',5,'LESSON','Động cơ nhiệt và hiệu suất nhiệt','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Động cơ nhiệt nhận nhiệt lượng Q₁ từ nguồn nóng, chuyển hóa một phần thành công cơ học A'' và nhả nhiệt lượng |Q₂| cho nguồn lạnh. Hiệu suất nhiệt: H = A'' / Q₁ = (Q₁ - |Q₂|) / Q₁ = 1 - |Q₂| / Q₁ < 1."]'::jsonb,'["Động cơ nhận 1000 J từ nguồn nóng và truyền cho nguồn lạnh 600 J: công sinh ra A'' = 400 J, hiệu suất H = 400 / 1000 = 40%."]'::jsonb,'[{"id": "physics-12-thermal-efficiency-q1", "prompt": "Hiệu suất nhiệt H của động cơ nhiệt được định nghĩa là tỉ số giữa:", "difficulty": "EASY", "options": [{"id": "a", "text": "Nhiệt lượng truyền cho nguồn lạnh và nhiệt lượng nhận từ nguồn nóng"}, {"id": "b", "text": "Nhiệt lượng nhận từ nguồn nóng và công toàn phần"}, {"id": "c", "text": "Công cơ học có ích sinh ra và nhiệt lượng nhận từ nguồn nóng"}], "correctOptionId": "c", "explanation": "Hiệu suất H = A'' / Q₁ phản ánh tỉ lệ nhiệt năng được chuyển hóa thành cơ công hữu ích."}, {"id": "physics-12-thermal-efficiency-q2", "prompt": "Một động cơ nhiệt nhận nhiệt lượng 2000 J từ nguồn nóng trong mỗi chu trình và nhả cho nguồn lạnh 1200 J. Hiệu suất của động cơ là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "30%"}, {"id": "b", "text": "40%"}, {"id": "c", "text": "60%"}], "correctOptionId": "b", "explanation": "Công có ích A'' = Q₁ - |Q₂| = 2000 - 1200 = 800 J. Hiệu suất H = 800 / 2000 = 0,4 = 40%."}, {"id": "physics-12-thermal-efficiency-q3", "prompt": "Theo nguyên lí II nhiệt động lực học, có thể chế tạo được một động cơ nhiệt làm việc tuần hoàn biến đổi hoàn toàn 100% nhiệt lượng thu được thành công cơ học không?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Không thể chế tạo được"}, {"id": "b", "text": "Hoàn toàn có thể chế tạo được nếu dùng vật liệu siêu dẫn"}, {"id": "c", "text": "Có thể chế tạo được nếu nhiệt độ nguồn lạnh bằng 100 °C"}], "correctOptionId": "a", "explanation": "Theo cách phát biểu của Kelvin - Planck, động cơ nhiệt tuần hoàn không thể biến đổi toàn bộ nhiệt lượng nhận từ một nguồn thành công mà bắt buộc phải truyền một phần cho nguồn lạnh."}]'::jsonb,'["physics-12-thermal-efficiency"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-review-1',6,'FIVE_LESSON_REVIEW','Ôn tập 1','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "physics-12-matter-model-q1", "prompt": "Theo mô hình động học phân tử, khi nhiệt độ của một vật tăng lên thì:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tốc độ chuyển động hỗn loạn của các phân tử cấu tạo nên vật tăng"}, {"id": "b", "text": "Khối lượng của mỗi phân tử cấu tạo nên vật tăng lên"}, {"id": "c", "text": "Khoảng cách giữa các phân tử luôn giảm đi đáng kể"}], "correctOptionId": "a", "explanation": "Nhiệt độ là số đo động năng chuyển động nhiệt trung bình của các phân tử. Nhiệt độ tăng nghĩa là phân tử chuyển động nhanh hơn."}, {"id": "physics-12-matter-model-q2", "prompt": "Đặc điểm căn bản về cấu trúc phân tử của chất ở thể khí so với thể rắn và lỏng là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Các phân tử khí liên kết chặt chẽ và chỉ dao động quanh vị trí cân bằng"}, {"id": "b", "text": "Các phân tử khí hoàn toàn không có tương tác đẩy"}, {"id": "c", "text": "Khoảng cách giữa các phân tử rất lớn so với kích thước của chính chúng"}], "correctOptionId": "c", "explanation": "Ở thể khí, khoảng cách trung bình giữa các phân tử lớn gấp hàng chục lần kích thước phân tử nên lực tương tác rất yếu."}, {"id": "physics-12-temperature-scales-q1", "prompt": "Hai vật ở trạng thái cân bằng nhiệt với nhau khi và chỉ khi chúng có cùng:", "difficulty": "EASY", "options": [{"id": "a", "text": "Nội năng"}, {"id": "b", "text": "Khối lượng"}, {"id": "c", "text": "Nhiệt độ"}], "correctOptionId": "c", "explanation": "Điều kiện cân bằng nhiệt giữa hai hệ tiếp xúc nhiệt là nhiệt độ của chúng bằng nhau, khi đó không còn dòng nhiệt truyền qua lại."}, {"id": "physics-12-temperature-scales-q2", "prompt": "Nhiệt độ sôi của nước ở áp suất tiêu chuẩn là 100 °C tương ứng với bao nhiêu Kelvin?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "100 K"}, {"id": "b", "text": "373,15 K"}, {"id": "c", "text": "273,15 K"}], "correctOptionId": "b", "explanation": "Công thức chuyển đổi: T(K) = t(°C) + 273,15 = 100 + 273,15 = 373,15 K."}, {"id": "physics-12-heat-capacity-q1", "prompt": "Đơn vị đo của nhiệt dung riêng trong hệ đơn vị quốc tế SI là:", "difficulty": "EASY", "options": [{"id": "a", "text": "W/(kg·K)"}, {"id": "b", "text": "J/(kg·K)"}, {"id": "c", "text": "J/kg"}], "correctOptionId": "b", "explanation": "Nhiệt dung riêng c = Q / (m·ΔT) có đơn vị là Joule trên kilogram Kelvin (J/(kg·K))."}, {"id": "physics-12-heat-capacity-q2", "prompt": "Tính nhiệt lượng cần thiết để đun nóng 2 kg nước từ 20 °C lên 80 °C. Biết nhiệt dung riêng của nước c = 4200 J/(kg·K).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "504 kJ"}, {"id": "b", "text": "252 kJ"}, {"id": "c", "text": "672 kJ"}], "correctOptionId": "a", "explanation": "Q = m · c · ΔT = 2 · 4200 · (80 - 20) = 8400 · 60 = 504 000 J = 504 kJ."}, {"id": "physics-12-internal-energy-q1", "prompt": "Biểu thức toán học của định luật I nhiệt động lực học là:", "difficulty": "EASY", "options": [{"id": "a", "text": "ΔU = Q + A"}, {"id": "b", "text": "ΔU = Q · A"}, {"id": "c", "text": "Q = ΔU + A²"}], "correctOptionId": "a", "explanation": "Định luật I là dạng biểu diễn của định luật bảo toàn và chuyển hóa năng lượng áp dụng cho các quá trình nhiệt: ΔU = Q + A."}, {"id": "physics-12-internal-energy-q2", "prompt": "Một khối khí nhận nhiệt lượng 600 J từ nguồn nhiệt và thực hiện công 400 J đẩy piston nâng vật nặng lên. Độ biến thiên nội năng của khối khí là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "+1000 J"}, {"id": "b", "text": "-200 J"}, {"id": "c", "text": "+200 J"}], "correctOptionId": "c", "explanation": "Hệ nhận nhiệt: Q = +600 J; hệ sinh công: A = -400 J. Ta có ΔU = Q + A = 600 + (-400) = +200 J."}, {"id": "physics-12-thermal-efficiency-q1", "prompt": "Hiệu suất nhiệt H của động cơ nhiệt được định nghĩa là tỉ số giữa:", "difficulty": "EASY", "options": [{"id": "a", "text": "Nhiệt lượng truyền cho nguồn lạnh và nhiệt lượng nhận từ nguồn nóng"}, {"id": "b", "text": "Nhiệt lượng nhận từ nguồn nóng và công toàn phần"}, {"id": "c", "text": "Công cơ học có ích sinh ra và nhiệt lượng nhận từ nguồn nóng"}], "correctOptionId": "c", "explanation": "Hiệu suất H = A'' / Q₁ phản ánh tỉ lệ nhiệt năng được chuyển hóa thành cơ công hữu ích."}, {"id": "physics-12-thermal-efficiency-q2", "prompt": "Một động cơ nhiệt nhận nhiệt lượng 2000 J từ nguồn nóng trong mỗi chu trình và nhả cho nguồn lạnh 1200 J. Hiệu suất của động cơ là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "30%"}, {"id": "b", "text": "40%"}, {"id": "c", "text": "60%"}], "correctOptionId": "b", "explanation": "Công có ích A'' = Q₁ - |Q₂| = 2000 - 1200 = 800 J. Hiệu suất H = 800 / 2000 = 0,4 = 40%."}]'::jsonb,'["physics-12-matter-model", "physics-12-temperature-scales", "physics-12-heat-capacity", "physics-12-internal-energy", "physics-12-thermal-efficiency"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-ideal-gas-model',7,'LESSON','Thuyết động học phân tử chất khí và mô hình khí lí tưởng','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Khí lí tưởng là mô hình trong đó các phân tử được coi là chất điểm, chuyển động hỗn loạn không ngừng và chỉ tương tác với nhau khi va chạm; các va chạm được coi là hoàn toàn đàn hồi."]'::jsonb,'["Ở điều kiện nhiệt độ phòng và áp suất thường, các khí thực như heli, hydro, oxy tuân theo các quy luật của khí lí tưởng với độ chính xác rất cao."]'::jsonb,'[{"id": "physics-12-ideal-gas-model-q1", "prompt": "Trong mô hình khí lí tưởng, tương tác giữa các phân tử khí được xem xét như thế nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn đẩy nhau liên tục kể cả khi ở rất xa nhau"}, {"id": "b", "text": "Chỉ tương tác đẩy hoặc hút khi chúng va chạm vào nhau hoặc vào thành bình"}, {"id": "c", "text": "Luôn hút nhau bằng lực tĩnh điện mạnh ở mọi khoảng cách"}], "correctOptionId": "b", "explanation": "Mô hình khí lí tưởng bỏ qua tương tác tầm xa giữa các phân tử; lực tương tác chỉ xuất hiện tức thời khi có va chạm."}, {"id": "physics-12-ideal-gas-model-q2", "prompt": "Mô hình khí lí tưởng coi các phân tử khí là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Các chất điểm có khối lượng nhưng thể tích bản thân không đáng kể so với thể tích bình"}, {"id": "b", "text": "Các hình cầu rắn có kích thước bằng thể tích bình chứa"}, {"id": "c", "text": "Các hạt đứng yên tại các nút mạng tinh thể xác định"}], "correctOptionId": "a", "explanation": "Vì khoảng cách giữa các phân tử khí rất lớn so với kích thước của chúng nên thể tích riêng của các phân tử được coi là chất điểm."}, {"id": "physics-12-ideal-gas-model-q3", "prompt": "Khi giữ thể tích bình kín không đổi, việc bơm thêm khí làm tăng mật độ hạt phân tử dẫn đến hiện tượng gì ở cấp độ vi mô?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Khối lượng của từng phân tử khí riêng lẻ tự tăng lên"}, {"id": "b", "text": "Tốc độ trung bình của các phân tử khí tự động giảm về 0"}, {"id": "c", "text": "Số va chạm của các phân tử lên một đơn vị diện tích thành bình trong một giây tăng lên"}], "correctOptionId": "c", "explanation": "Mật độ phân tử tăng làm tần số va chạm lên thành bình tăng, qua đó làm tăng lực tác dụng trung bình và tăng áp suất chất khí."}]'::jsonb,'["physics-12-ideal-gas-model"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-boyle-law',8,'LESSON','Định luật Boyle - Quá trình đẳng nhiệt','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Quá trình biến đổi trạng thái trong đó nhiệt độ được giữ không đổi gọi là quá trình đẳng nhiệt. Định luật Boyle: Với một lượng khí xác định ở nhiệt độ không đổi, áp suất tỉ lệ nghịch với thể tích: p₁V₁ = p₂V₂ = const."]'::jsonb,'["Một lượng khí ở 1 atm có thể tích 4 lít. Nén đẳng nhiệt xuống 2 lít thì áp suất mới là p₂ = 1 * 4 / 2 = 2 atm."]'::jsonb,'[{"id": "physics-12-boyle-law-q1", "prompt": "Định luật Boyle áp dụng cho quá trình biến đổi trạng thái nào của chất khí?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quá trình đẳng nhiệt"}, {"id": "b", "text": "Quá trình đẳng áp"}, {"id": "c", "text": "Quá trình đẳng tích"}], "correctOptionId": "a", "explanation": "Định luật Boyle nghiên cứu mối quan hệ giữa áp suất và thể tích khi nhiệt độ T được giữ không đổi."}, {"id": "physics-12-boyle-law-q2", "prompt": "Một khối khí lí tưởng có thể tích 6 lít ở áp suất 1,5 atm. Giữ nhiệt độ không đổi, nén khối khí đến thể tích 2 lít thì áp suất mới là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2,0 atm"}, {"id": "b", "text": "3,0 atm"}, {"id": "c", "text": "4,5 atm"}], "correctOptionId": "c", "explanation": "Theo định luật Boyle: p₁V₁ = p₂V₂ ⇒ p₂ = (1,5 * 6) / 2 = 9 / 2 = 4,5 atm."}, {"id": "physics-12-boyle-law-q3", "prompt": "Một bọt khí nổi từ đáy hồ nước sâu lên mặt thoáng ở nhiệt độ không đổi. Thể tích của bọt khí thay đổi thế nào khi nổi lên?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Thể tích luôn không đổi vì khối lượng khí không đổi"}, {"id": "b", "text": "Thể tích tăng dần do áp suất nước giảm khi tiến gần mặt thoáng"}, {"id": "c", "text": "Thể tích giảm dần do áp suất nước tăng lên"}], "correctOptionId": "b", "explanation": "Áp suất ở đáy hồ lớn hơn ở mặt nước do có thêm áp suất cột nước p = p₀ + ρgh. Khi nổi lên áp suất giảm nên theo định luật Boyle thể tích bọt khí tăng lên."}]'::jsonb,'["physics-12-boyle-law"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-charles-law',9,'LESSON','Định luật Charles - Quá trình đẳng áp','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Quá trình biến đổi trạng thái khi áp suất không đổi gọi là quá trình đẳng áp. Định luật Charles: Với một lượng khí xác định ở áp suất không đổi, thể tích tỉ lệ thuận với nhiệt độ tuyệt đối T (Kelvin): V₁ / T₁ = V₂ / T₂ = const."]'::jsonb,'["Lượng khí có thể tích 3 lít ở 300 K. Giữ áp suất không đổi, khi nung nóng lên 400 K thì V₂ = 3 * (400 / 300) = 4 lít."]'::jsonb,'[{"id": "physics-12-charles-law-q1", "prompt": "Trong quá trình đẳng áp của một lượng khí lí tưởng xác định, thể tích của khối khí:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tỉ lệ nghịch với nhiệt độ tuyệt đối T"}, {"id": "b", "text": "Tỉ lệ thuận với bình phương nhiệt độ Celsius"}, {"id": "c", "text": "Tỉ lệ thuận với nhiệt độ tuyệt đối T"}], "correctOptionId": "c", "explanation": "Định luật Charles: V / T = const, thể tích tỉ lệ thuận với nhiệt độ tính theo thang Kelvin."}, {"id": "physics-12-charles-law-q2", "prompt": "Một khối khí có thể tích 5 lít ở nhiệt độ 250 K. Giữ áp suất không đổi, khi nung nóng khối khí đến 350 K thì thể tích của nó bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8,5 lít"}, {"id": "b", "text": "7,0 lít"}, {"id": "c", "text": "6,0 lít"}], "correctOptionId": "b", "explanation": "Theo định luật Charles: V₂ = V₁ · (T₂ / T₁) = 5 · (350 / 250) = 5 · 1,4 = 7,0 lít."}, {"id": "physics-12-charles-law-q3", "prompt": "Một quả bóng bàn bị móp nhẹ (vỏ chưa bị rách thủng), khi nhúng vào bát nước nóng thì quả bóng phồng trở lại như cũ. Hiện tượng này được giải thích chủ yếu bằng:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Không khí bên trong nhận nhiệt nóng lên, giãn nở đẳng áp đẩy vỏ bóng phồng lại"}, {"id": "b", "text": "Nước nóng thấm qua vỏ bóng làm tăng thể tích chất lỏng bên trong"}, {"id": "c", "text": "Khối lượng không khí bên trong quả bóng tự động tăng lên"}], "correctOptionId": "a", "explanation": "Nhiệt độ không khí bên trong tăng làm áp suất và thể tích khí giãn nở, tạo lực đẩy vỏ nhựa phồng trở lại hình cầu."}]'::jsonb,'["physics-12-charles-law"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-state-equation',10,'LESSON','Phương trình trạng thái khí lí tưởng','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Phương trình trạng thái liên hệ cả ba thông số p, V, T của một lượng khí: (p₁V₁)/T₁ = (p₂V₂)/T₂ = const. Dạng phương trình Clapeyron - Mendeleev: p.V = n.R.T = (m/M).R.T với hằng số khí R ≈ 8,31 J/(mol.K)."]'::jsonb,'["Bình 0,02 m³ chứa 2 mol khí ở 300 K: p = (2 * 8,31 * 300) / 0,02 = 249 300 Pa ≈ 2,49 × 10⁵ Pa."]'::jsonb,'[{"id": "physics-12-state-equation-q1", "prompt": "Phương trình trạng thái của khí lí tưởng cho một lượng khí xác định là:", "difficulty": "EASY", "options": [{"id": "a", "text": "(p · T) · V = hằng số"}, {"id": "b", "text": "(p · V) / T = hằng số"}, {"id": "c", "text": "p · T / V = hằng số"}], "correctOptionId": "b", "explanation": "Phương trình trạng thái kết hợp định luật Boyle và Charles cho hệ thức tổng quát pV/T = const."}, {"id": "physics-12-state-equation-q2", "prompt": "Tính áp suất của 1 mol khí lí tưởng chứa trong bình kín thể tích 0,01 m³ ở nhiệt độ 300 K. Cho hằng số khí R = 8,31 J/(mol·K).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2,49 × 10⁵ Pa"}, {"id": "b", "text": "1,25 × 10⁵ Pa"}, {"id": "c", "text": "8,31 × 10⁴ Pa"}], "correctOptionId": "a", "explanation": "Áp dụng p = nRT / V = (1 · 8,31 · 300) / 0,01 = 2493 / 0,01 = 249 300 Pa ≈ 2,49 × 10⁵ Pa."}, {"id": "physics-12-state-equation-q3", "prompt": "Bình xịt chứa khí nén luôn có cảnh báo ''Không để ở nơi có nhiệt độ trên 50 °C hoặc ném vào lửa'' vì lý do vật lí nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Nhiệt độ cao làm chất khí biến thành chất rắn làm nặng bình"}, {"id": "b", "text": "Vỏ kim loại của bình bị tan chảy ngay ở nhiệt độ 50 °C"}, {"id": "c", "text": "Thể tích bình cố định, nhiệt độ tăng cao làm áp suất khí tăng vọt gây nguy cơ nổ"}], "correctOptionId": "c", "explanation": "Theo quá trình đẳng tích (V không đổi), p tỉ lệ thuận với T. Nhiệt độ cao làm áp suất bên trong vượt quá giới hạn chịu lực của vỏ bình."}]'::jsonb,'["physics-12-state-equation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-molecular-pressure',11,'LESSON','Áp suất khí theo mô hình động học phân tử','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Áp suất chất khí tác dụng lên thành bình sinh ra do các phân tử khí va chạm liên tục và truyền động lượng lên thành bình. Công thức cơ bản: p = (1/3) μ m v_tb² = (2/3) μ E_d, trong đó động năng tịnh tiến trung bình E_d = (3/2) k T (với hằng số Boltzmann k = R/N_A)."]'::jsonb,'["Nhiệt độ T đo trực tiếp động năng tịnh tiến trung bình: khi T tăng gấp đôi thì E_d tăng gấp đôi."]'::jsonb,'[{"id": "physics-12-molecular-pressure-q1", "prompt": "Động năng chuyển động nhiệt tịnh tiến trung bình của các phân tử khí lí tưởng tỉ lệ thuận với:", "difficulty": "EASY", "options": [{"id": "a", "text": "Nhiệt độ tuyệt đối T của chất khí"}, {"id": "b", "text": "Thể tích V của bình chứa"}, {"id": "c", "text": "Khối lượng mol M của chất khí"}], "correctOptionId": "a", "explanation": "Hệ thức Boltzmann E_d = (3/2)kT cho thấy động năng tịnh tiến trung bình tỉ lệ thuận trực tiếp với nhiệt độ Kelvin."}, {"id": "physics-12-molecular-pressure-q2", "prompt": "Bản chất vi mô của áp suất chất khí tác dụng lên thành bình chứa là do:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Trọng lực của các phân tử khí đè nén lên đáy bình chứa"}, {"id": "b", "text": "Lực hút tĩnh điện giữa thành bình và các electron của chất khí"}, {"id": "c", "text": "Hàng tỉ phân tử khí va chạm liên tục và truyền động lượng lên thành bình"}], "correctOptionId": "c", "explanation": "Mỗi phân tử va chạm đàn hồi vào thành bình làm đổi hướng vận tốc, truyền xung lượng; tổng hợp vô số va chạm tạo nên áp suất liên tục."}, {"id": "physics-12-molecular-pressure-q3", "prompt": "Khi đun nóng đẳng tích một khối khí lí tưởng để nhiệt độ tuyệt đối tăng từ 300 K lên 600 K, động năng tịnh tiến trung bình của các phân tử khí sẽ:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Không thay đổi"}, {"id": "b", "text": "Tăng lên 2 lần"}, {"id": "c", "text": "Tăng lên 4 lần"}], "correctOptionId": "b", "explanation": "Vì E_d = (3/2)kT tỉ lệ thuận với T bậc nhất, nên khi T tăng từ 300 K lên 600 K (gấp 2 lần) thì động năng trung bình tăng 2 lần."}]'::jsonb,'["physics-12-molecular-pressure"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-review-2',12,'FIVE_LESSON_REVIEW','Ôn tập 2','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "physics-12-ideal-gas-model-q1", "prompt": "Trong mô hình khí lí tưởng, tương tác giữa các phân tử khí được xem xét như thế nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn đẩy nhau liên tục kể cả khi ở rất xa nhau"}, {"id": "b", "text": "Chỉ tương tác đẩy hoặc hút khi chúng va chạm vào nhau hoặc vào thành bình"}, {"id": "c", "text": "Luôn hút nhau bằng lực tĩnh điện mạnh ở mọi khoảng cách"}], "correctOptionId": "b", "explanation": "Mô hình khí lí tưởng bỏ qua tương tác tầm xa giữa các phân tử; lực tương tác chỉ xuất hiện tức thời khi có va chạm."}, {"id": "physics-12-ideal-gas-model-q2", "prompt": "Mô hình khí lí tưởng coi các phân tử khí là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Các chất điểm có khối lượng nhưng thể tích bản thân không đáng kể so với thể tích bình"}, {"id": "b", "text": "Các hình cầu rắn có kích thước bằng thể tích bình chứa"}, {"id": "c", "text": "Các hạt đứng yên tại các nút mạng tinh thể xác định"}], "correctOptionId": "a", "explanation": "Vì khoảng cách giữa các phân tử khí rất lớn so với kích thước của chúng nên thể tích riêng của các phân tử được coi là chất điểm."}, {"id": "physics-12-boyle-law-q1", "prompt": "Định luật Boyle áp dụng cho quá trình biến đổi trạng thái nào của chất khí?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quá trình đẳng nhiệt"}, {"id": "b", "text": "Quá trình đẳng áp"}, {"id": "c", "text": "Quá trình đẳng tích"}], "correctOptionId": "a", "explanation": "Định luật Boyle nghiên cứu mối quan hệ giữa áp suất và thể tích khi nhiệt độ T được giữ không đổi."}, {"id": "physics-12-boyle-law-q2", "prompt": "Một khối khí lí tưởng có thể tích 6 lít ở áp suất 1,5 atm. Giữ nhiệt độ không đổi, nén khối khí đến thể tích 2 lít thì áp suất mới là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2,0 atm"}, {"id": "b", "text": "3,0 atm"}, {"id": "c", "text": "4,5 atm"}], "correctOptionId": "c", "explanation": "Theo định luật Boyle: p₁V₁ = p₂V₂ ⇒ p₂ = (1,5 * 6) / 2 = 9 / 2 = 4,5 atm."}, {"id": "physics-12-charles-law-q1", "prompt": "Trong quá trình đẳng áp của một lượng khí lí tưởng xác định, thể tích của khối khí:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tỉ lệ nghịch với nhiệt độ tuyệt đối T"}, {"id": "b", "text": "Tỉ lệ thuận với bình phương nhiệt độ Celsius"}, {"id": "c", "text": "Tỉ lệ thuận với nhiệt độ tuyệt đối T"}], "correctOptionId": "c", "explanation": "Định luật Charles: V / T = const, thể tích tỉ lệ thuận với nhiệt độ tính theo thang Kelvin."}, {"id": "physics-12-charles-law-q2", "prompt": "Một khối khí có thể tích 5 lít ở nhiệt độ 250 K. Giữ áp suất không đổi, khi nung nóng khối khí đến 350 K thì thể tích của nó bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "8,5 lít"}, {"id": "b", "text": "7,0 lít"}, {"id": "c", "text": "6,0 lít"}], "correctOptionId": "b", "explanation": "Theo định luật Charles: V₂ = V₁ · (T₂ / T₁) = 5 · (350 / 250) = 5 · 1,4 = 7,0 lít."}, {"id": "physics-12-state-equation-q1", "prompt": "Phương trình trạng thái của khí lí tưởng cho một lượng khí xác định là:", "difficulty": "EASY", "options": [{"id": "a", "text": "(p · T) · V = hằng số"}, {"id": "b", "text": "(p · V) / T = hằng số"}, {"id": "c", "text": "p · T / V = hằng số"}], "correctOptionId": "b", "explanation": "Phương trình trạng thái kết hợp định luật Boyle và Charles cho hệ thức tổng quát pV/T = const."}, {"id": "physics-12-state-equation-q2", "prompt": "Tính áp suất của 1 mol khí lí tưởng chứa trong bình kín thể tích 0,01 m³ ở nhiệt độ 300 K. Cho hằng số khí R = 8,31 J/(mol·K).", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2,49 × 10⁵ Pa"}, {"id": "b", "text": "1,25 × 10⁵ Pa"}, {"id": "c", "text": "8,31 × 10⁴ Pa"}], "correctOptionId": "a", "explanation": "Áp dụng p = nRT / V = (1 · 8,31 · 300) / 0,01 = 2493 / 0,01 = 249 300 Pa ≈ 2,49 × 10⁵ Pa."}, {"id": "physics-12-molecular-pressure-q1", "prompt": "Động năng chuyển động nhiệt tịnh tiến trung bình của các phân tử khí lí tưởng tỉ lệ thuận với:", "difficulty": "EASY", "options": [{"id": "a", "text": "Nhiệt độ tuyệt đối T của chất khí"}, {"id": "b", "text": "Thể tích V của bình chứa"}, {"id": "c", "text": "Khối lượng mol M của chất khí"}], "correctOptionId": "a", "explanation": "Hệ thức Boltzmann E_d = (3/2)kT cho thấy động năng tịnh tiến trung bình tỉ lệ thuận trực tiếp với nhiệt độ Kelvin."}, {"id": "physics-12-molecular-pressure-q2", "prompt": "Bản chất vi mô của áp suất chất khí tác dụng lên thành bình chứa là do:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Trọng lực của các phân tử khí đè nén lên đáy bình chứa"}, {"id": "b", "text": "Lực hút tĩnh điện giữa thành bình và các electron của chất khí"}, {"id": "c", "text": "Hàng tỉ phân tử khí va chạm liên tục và truyền động lượng lên thành bình"}], "correctOptionId": "c", "explanation": "Mỗi phân tử va chạm đàn hồi vào thành bình làm đổi hướng vận tốc, truyền xung lượng; tổng hợp vô số va chạm tạo nên áp suất liên tục."}]'::jsonb,'["physics-12-ideal-gas-model", "physics-12-boyle-law", "physics-12-charles-law", "physics-12-state-equation", "physics-12-molecular-pressure"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-magnetic-field',13,'LESSON','Từ trường và đường sức từ','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Từ trường là dạng vật chất tồn tại xung quanh nam châm hoặc dòng điện, tác dụng lực từ lên kim nam châm hoặc hạt điện tích chuyển động. Đường sức từ là các đường cong khép kín có chiều quy ước: vào cực Nam (S) ra cực Bắc (N)."]'::jsonb,'["Kim la bàn đặt tự do luôn định hướng theo trục Bắc - Nam địa lí chứng tỏ Trái Đất có từ trường riêng (địa từ trường)."]'::jsonb,'[{"id": "physics-12-magnetic-field-q1", "prompt": "Từ trường không tác dụng lực lên đối tượng nào sau đây?", "difficulty": "EASY", "options": [{"id": "a", "text": "Một đoạn dây dẫn có dòng điện chạy qua"}, {"id": "b", "text": "Một hạt mang điện đang chuyển động cắt các đường sức từ"}, {"id": "c", "text": "Một điện tích đứng yên trong từ trường"}], "correctOptionId": "c", "explanation": "Lực từ chỉ xuất hiện khi điện tích chuyển động (hoặc có dòng điện); điện tích đứng yên không chịu tác dụng của lực từ."}, {"id": "physics-12-magnetic-field-q2", "prompt": "Tính chất hình học cơ bản của các đường sức từ là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Luôn cắt nhau tại các điểm có từ trường mạnh"}, {"id": "b", "text": "Là những đường cong khép kín (hoặc vô hạn ở hai đầu)"}, {"id": "c", "text": "Là các đoạn thẳng hở bắt đầu từ cực dương và kết thúc ở cực âm"}], "correctOptionId": "b", "explanation": "Từ trường là trường xoáy, không có điểm khởi đầu hay kết thúc nên các đường sức từ luôn là đường cong kín."}, {"id": "physics-12-magnetic-field-q3", "prompt": "Hiện tượng kim la bàn đặt tự do trên mặt đất luôn định hướng theo phương gần trùng với phương Bắc - Nam chứng tỏ:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Xung quanh Trái Đất tồn tại một từ trường gọi là địa từ trường"}, {"id": "b", "text": "Không khí xung quanh Trái Đất bị nhiễm điện tĩnh điện mạnh"}, {"id": "c", "text": "Trọng lực của Trái Đất chỉ tác dụng theo phương Bắc - Nam"}], "correctOptionId": "a", "explanation": "Trái Đất hoạt động như một nam châm khổng lồ có cực từ Nam nằm gần cực Bắc địa lí và ngược lại, định hướng kim la bàn."}]'::jsonb,'["physics-12-magnetic-field"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-magnetic-force',14,'LESSON','Lực từ tác dụng lên đoạn dây dẫn mang dòng điện','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Lực từ tác dụng lên đoạn dây dẫn thẳng mang dòng điện I dài L đặt trong từ trường đều B: F = B.I.L.sin θ (θ là góc giữa dây dẫn và B). Phương của F vuông góc với mặt phẳng chứa đoạn dây và vectơ B; chiều xác định theo quy tắc bàn tay trái."]'::jsonb,'["Dây dài 0,2 m mang dòng điện 5 A đặt vuông góc với B = 0,4 T: F = 0,4 * 5 * 0,2 * sin 90° = 0,4 N."]'::jsonb,'[{"id": "physics-12-magnetic-force-q1", "prompt": "Lực từ tác dụng lên đoạn dây dẫn mang dòng điện đặt trong từ trường đều đạt giá trị cực đại khi góc θ giữa đoạn dây và vectơ cảm ứng từ bằng:", "difficulty": "EASY", "options": [{"id": "a", "text": "180°"}, {"id": "b", "text": "90°"}, {"id": "c", "text": "0°"}], "correctOptionId": "b", "explanation": "F = B·I·L·sin θ. Hàm sin θ đạt cực đại bằng 1 khi góc θ = 90° (dây dẫn vuông góc với đường sức từ)."}, {"id": "physics-12-magnetic-force-q2", "prompt": "Đoạn dây dẫn thẳng dài 0,2 m mang dòng điện cường độ 5 A đặt vuông góc với các đường cảm ứng từ của từ trường đều B = 0,4 T. Độ lớn lực từ tác dụng lên đoạn dây là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,4 N"}, {"id": "b", "text": "0,8 N"}, {"id": "c", "text": "0,2 N"}], "correctOptionId": "a", "explanation": "F = B · I · L · sin 90° = 0,4 · 5 · 0,2 · 1 = 0,4 N."}, {"id": "physics-12-magnetic-force-q3", "prompt": "Đặt hai dây dẫn thẳng dài song song mang dòng điện cùng chiều gần nhau. Tương tác từ giữa hai dây dẫn là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chúng đẩy nhau"}, {"id": "b", "text": "Không có lực tương tác nào giữa hai dây"}, {"id": "c", "text": "Chúng hút nhau"}], "correctOptionId": "c", "explanation": "Áp dụng quy tắc nắm tay phải để tìm chiều từ trường của dây 1 và quy tắc bàn tay trái để tìm lực từ tác dụng lên dây 2, ta thấy hai dòng điện cùng chiều hút nhau."}]'::jsonb,'["physics-12-magnetic-force"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-magnetic-induction',15,'LESSON','Cảm ứng từ của dòng điện có hình dạng đặc biệt','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Độ lớn cảm ứng từ B đặc trưng cho tác dụng lực từ: dòng điện thẳng dài: B = 2·10⁻⁷·(I/r); dòng điện tròn bán kính R tại tâm: B = 2π·10⁻⁷·(I/R); trong lòng ống dây dài n vòng/m: B = 4π·10⁻⁷·n·I (từ trường đều)."]'::jsonb,'["Dòng điện 10 A trong dây thẳng dài gây ra tại điểm cách 0,05 m cảm ứng từ B = 2·10⁻⁷ * 10 / 0,05 = 4 × 10⁻⁵ T."]'::jsonb,'[{"id": "physics-12-magnetic-induction-q1", "prompt": "Vectơ cảm ứng từ B tại một điểm đặc trưng cho từ trường tại điểm đó về phương diện:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tác dụng lực từ"}, {"id": "b", "text": "Năng lượng tĩnh điện"}, {"id": "c", "text": "Tốc độ truyền sóng"}], "correctOptionId": "a", "explanation": "Cảm ứng từ B là đại lượng vectơ đặc trưng cho từ trường về mặt gây ra lực từ tác dụng lên dòng điện hay điện tích chuyển động."}, {"id": "physics-12-magnetic-induction-q2", "prompt": "Tính cảm ứng từ do dòng điện thẳng dài cường độ 10 A gây ra tại một điểm cách dây dẫn 0,05 m trong không khí.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2 × 10⁻⁵ T"}, {"id": "b", "text": "4 × 10⁻⁶ T"}, {"id": "c", "text": "4 × 10⁻⁵ T"}], "correctOptionId": "c", "explanation": "B = 2 · 10⁻⁷ · (I / r) = 2 · 10⁻⁷ · (10 / 0,05) = 2 · 10⁻⁷ · 200 = 4 · 10⁻⁵ T."}, {"id": "physics-12-magnetic-induction-q3", "prompt": "Trong lòng một ống dây hình trụ dài có dòng điện không đổi chạy qua, từ trường có đặc điểm quan trọng nào sau đây?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Đường sức từ xoáy tròn đồng tâm quanh trục ống dây"}, {"id": "b", "text": "Là từ trường đều với các đường sức từ song song và cách đều nhau"}, {"id": "c", "text": "Cảm ứng từ tại tâm bằng 0 và tăng dần ra hai mép ngoài"}], "correctOptionId": "b", "explanation": "Bên trong lòng ống dây hình trụ dài mang dòng điện, từ trường là từ trường đều, có vectơ cảm ứng từ không đổi ở mọi điểm."}]'::jsonb,'["physics-12-magnetic-induction"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-lorentz-force',16,'LESSON','Lực Lorentz tác dụng lên điện tích chuyển động','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Điện tích q chuyển động với vận tốc v trong từ trường B chịu lực Lorentz: f = |q|.v.B.sin α (α là góc giữa v và B). Phương của f vuông góc với cả v và B. Vì f luôn vuông góc với vectơ vận tốc tức thời nên lực Lorentz không sinh công, chỉ làm đổi hướng chuyển động."]'::jsonb,'["Một proton bay vuông góc vào B: chuyển động theo quỹ đạo tròn với bán kính R = (m.v)/(|q|.B)."]'::jsonb,'[{"id": "physics-12-lorentz-force-q1", "prompt": "Phương của lực Lorentz tác dụng lên hạt mang điện chuyển động trong từ trường đều có đặc điểm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cùng phương với vectơ cảm ứng từ B"}, {"id": "b", "text": "Cùng phương với vectơ vận tốc v của hạt"}, {"id": "c", "text": "Vuông góc với cả vectơ vận tốc v và vectơ cảm ứng từ B"}], "correctOptionId": "c", "explanation": "Lực Lorentz có phương vuông góc với mặt phẳng tạo bởi vectơ vận tốc v và vectơ cảm ứng từ B."}, {"id": "physics-12-lorentz-force-q2", "prompt": "Một hạt mang điện tích q = 1,6·10⁻¹⁹ C bay với vận tốc v = 2·10⁶ m/s vuông góc vào từ trường đều B = 0,5 T. Độ lớn lực Lorentz tác dụng lên hạt là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,8 × 10⁻¹³ N"}, {"id": "b", "text": "1,6 × 10⁻¹³ N"}, {"id": "c", "text": "3,2 × 10⁻¹³ N"}], "correctOptionId": "b", "explanation": "f = |q| · v · B · sin 90° = 1,6 · 10⁻¹⁹ · 2 · 10⁶ · 0,5 · 1 = 1,6 · 10⁻¹³ N."}, {"id": "physics-12-lorentz-force-q3", "prompt": "Lực Lorentz có thực hiện công cơ học lên một điện tích chuyển động tự do trong từ trường đều không? Vì sao?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Không thực hiện công, vì lực Lorentz luôn vuông góc với vectơ vận tốc tức thời của hạt"}, {"id": "b", "text": "Có thực hiện công dương làm tăng động năng của hạt"}, {"id": "c", "text": "Có thực hiện công âm làm hạt chuyển động chậm dần đều"}], "correctOptionId": "a", "explanation": "Công tức thời dA = f · v · dt. Do lực Lorentz f ⊥ v nên tích vô hướng f · v = 0, công toàn phần luôn bằng 0."}]'::jsonb,'["physics-12-lorentz-force"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-electromagnetic-induction',17,'LESSON','Hiện tượng cảm ứng điện từ và định luật Faraday','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Từ thông qua diện tích S: Φ = B.S.cos α. Khi từ thông qua mạch kín biến thiên, trong mạch xuất hiện dòng điện cảm ứng (hiện tượng cảm ứng điện từ). Độ lớn suất điện động cảm ứng: |e_c| = |ΔΦ/Δt|. Định luật Lenz: dòng điện cảm ứng có chiều chống lại sự biến thiên từ thông sinh ra nó."]'::jsonb,'["Từ thông giảm từ 0,08 Wb xuống 0,02 Wb trong 0,1 s: |e_c| = |(0,02 - 0,08)/0,1| = 0,6 V."]'::jsonb,'[{"id": "physics-12-electromagnetic-induction-q1", "prompt": "Điều kiện tiên quyết để xuất hiện dòng điện cảm ứng trong một khung dây dẫn kín là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Khung dây phải luôn chuyển động nhanh dần đều"}, {"id": "b", "text": "Từ thông qua diện tích giới hạn bởi khung dây biến thiên theo thời gian"}, {"id": "c", "text": "Khung dây phải được đặt trong từ trường có độ lớn cực kì lớn"}], "correctOptionId": "b", "explanation": "Hiện tượng cảm ứng điện từ chỉ xảy ra khi có sự biến thiên từ thông gửi qua mạch kín theo thời gian."}, {"id": "physics-12-electromagnetic-induction-q2", "prompt": "Từ thông qua một mạch kín biến thiên đều giảm từ 0,08 Wb xuống 0,02 Wb trong khoảng thời gian 0,1 s. Độ lớn suất điện động cảm ứng xuất hiện trong mạch là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,6 V"}, {"id": "b", "text": "0,06 V"}, {"id": "c", "text": "6,0 V"}], "correctOptionId": "a", "explanation": "Theo định luật Faraday: |e_c| = |ΔΦ / Δt| = |(0,02 - 0,08) / 0,1| = |-0,06 / 0,1| = 0,6 V."}, {"id": "physics-12-electromagnetic-induction-q3", "prompt": "Đưa cực Bắc của một thanh nam châm lại gần một vòng nhôm kín nhẹ treo tự do bằng sợi chỉ. Vòng nhôm sẽ phản ứng thế nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Vòng nhôm bị hút mạnh vào thanh nam châm"}, {"id": "b", "text": "Vòng nhôm đứng yên không dịch chuyển"}, {"id": "c", "text": "Vòng nhôm bị đẩy ra xa thanh nam châm"}], "correctOptionId": "c", "explanation": "Theo định luật Lenz, dòng điện cảm ứng sinh ra từ trường chống lại sự lại gần của nam châm (mặt đối diện biến thành cực Bắc), gây lực đẩy đẩy vòng nhôm ra xa."}]'::jsonb,'["physics-12-electromagnetic-induction"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-review-3',18,'FIVE_LESSON_REVIEW','Ôn tập 3','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "physics-12-magnetic-field-q1", "prompt": "Từ trường không tác dụng lực lên đối tượng nào sau đây?", "difficulty": "EASY", "options": [{"id": "a", "text": "Một đoạn dây dẫn có dòng điện chạy qua"}, {"id": "b", "text": "Một hạt mang điện đang chuyển động cắt các đường sức từ"}, {"id": "c", "text": "Một điện tích đứng yên trong từ trường"}], "correctOptionId": "c", "explanation": "Lực từ chỉ xuất hiện khi điện tích chuyển động (hoặc có dòng điện); điện tích đứng yên không chịu tác dụng của lực từ."}, {"id": "physics-12-magnetic-field-q2", "prompt": "Tính chất hình học cơ bản của các đường sức từ là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Luôn cắt nhau tại các điểm có từ trường mạnh"}, {"id": "b", "text": "Là những đường cong khép kín (hoặc vô hạn ở hai đầu)"}, {"id": "c", "text": "Là các đoạn thẳng hở bắt đầu từ cực dương và kết thúc ở cực âm"}], "correctOptionId": "b", "explanation": "Từ trường là trường xoáy, không có điểm khởi đầu hay kết thúc nên các đường sức từ luôn là đường cong kín."}, {"id": "physics-12-magnetic-force-q1", "prompt": "Lực từ tác dụng lên đoạn dây dẫn mang dòng điện đặt trong từ trường đều đạt giá trị cực đại khi góc θ giữa đoạn dây và vectơ cảm ứng từ bằng:", "difficulty": "EASY", "options": [{"id": "a", "text": "180°"}, {"id": "b", "text": "90°"}, {"id": "c", "text": "0°"}], "correctOptionId": "b", "explanation": "F = B·I·L·sin θ. Hàm sin θ đạt cực đại bằng 1 khi góc θ = 90° (dây dẫn vuông góc với đường sức từ)."}, {"id": "physics-12-magnetic-force-q2", "prompt": "Đoạn dây dẫn thẳng dài 0,2 m mang dòng điện cường độ 5 A đặt vuông góc với các đường cảm ứng từ của từ trường đều B = 0,4 T. Độ lớn lực từ tác dụng lên đoạn dây là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,4 N"}, {"id": "b", "text": "0,8 N"}, {"id": "c", "text": "0,2 N"}], "correctOptionId": "a", "explanation": "F = B · I · L · sin 90° = 0,4 · 5 · 0,2 · 1 = 0,4 N."}, {"id": "physics-12-magnetic-induction-q1", "prompt": "Vectơ cảm ứng từ B tại một điểm đặc trưng cho từ trường tại điểm đó về phương diện:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tác dụng lực từ"}, {"id": "b", "text": "Năng lượng tĩnh điện"}, {"id": "c", "text": "Tốc độ truyền sóng"}], "correctOptionId": "a", "explanation": "Cảm ứng từ B là đại lượng vectơ đặc trưng cho từ trường về mặt gây ra lực từ tác dụng lên dòng điện hay điện tích chuyển động."}, {"id": "physics-12-magnetic-induction-q2", "prompt": "Tính cảm ứng từ do dòng điện thẳng dài cường độ 10 A gây ra tại một điểm cách dây dẫn 0,05 m trong không khí.", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2 × 10⁻⁵ T"}, {"id": "b", "text": "4 × 10⁻⁶ T"}, {"id": "c", "text": "4 × 10⁻⁵ T"}], "correctOptionId": "c", "explanation": "B = 2 · 10⁻⁷ · (I / r) = 2 · 10⁻⁷ · (10 / 0,05) = 2 · 10⁻⁷ · 200 = 4 · 10⁻⁵ T."}, {"id": "physics-12-lorentz-force-q1", "prompt": "Phương của lực Lorentz tác dụng lên hạt mang điện chuyển động trong từ trường đều có đặc điểm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cùng phương với vectơ cảm ứng từ B"}, {"id": "b", "text": "Cùng phương với vectơ vận tốc v của hạt"}, {"id": "c", "text": "Vuông góc với cả vectơ vận tốc v và vectơ cảm ứng từ B"}], "correctOptionId": "c", "explanation": "Lực Lorentz có phương vuông góc với mặt phẳng tạo bởi vectơ vận tốc v và vectơ cảm ứng từ B."}, {"id": "physics-12-lorentz-force-q2", "prompt": "Một hạt mang điện tích q = 1,6·10⁻¹⁹ C bay với vận tốc v = 2·10⁶ m/s vuông góc vào từ trường đều B = 0,5 T. Độ lớn lực Lorentz tác dụng lên hạt là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,8 × 10⁻¹³ N"}, {"id": "b", "text": "1,6 × 10⁻¹³ N"}, {"id": "c", "text": "3,2 × 10⁻¹³ N"}], "correctOptionId": "b", "explanation": "f = |q| · v · B · sin 90° = 1,6 · 10⁻¹⁹ · 2 · 10⁶ · 0,5 · 1 = 1,6 · 10⁻¹³ N."}, {"id": "physics-12-electromagnetic-induction-q1", "prompt": "Điều kiện tiên quyết để xuất hiện dòng điện cảm ứng trong một khung dây dẫn kín là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Khung dây phải luôn chuyển động nhanh dần đều"}, {"id": "b", "text": "Từ thông qua diện tích giới hạn bởi khung dây biến thiên theo thời gian"}, {"id": "c", "text": "Khung dây phải được đặt trong từ trường có độ lớn cực kì lớn"}], "correctOptionId": "b", "explanation": "Hiện tượng cảm ứng điện từ chỉ xảy ra khi có sự biến thiên từ thông gửi qua mạch kín theo thời gian."}, {"id": "physics-12-electromagnetic-induction-q2", "prompt": "Từ thông qua một mạch kín biến thiên đều giảm từ 0,08 Wb xuống 0,02 Wb trong khoảng thời gian 0,1 s. Độ lớn suất điện động cảm ứng xuất hiện trong mạch là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0,6 V"}, {"id": "b", "text": "0,06 V"}, {"id": "c", "text": "6,0 V"}], "correctOptionId": "a", "explanation": "Theo định luật Faraday: |e_c| = |ΔΦ / Δt| = |(0,02 - 0,08) / 0,1| = |-0,06 / 0,1| = 0,6 V."}]'::jsonb,'["physics-12-magnetic-field", "physics-12-magnetic-force", "physics-12-magnetic-induction", "physics-12-lorentz-force", "physics-12-electromagnetic-induction"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-nuclear-structure',19,'LESSON','Cấu tạo hạt nhân và năng lượng liên kết','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Hạt nhân nguyên tử cấu tạo từ Z proton và (A - Z) neutron. Khối lượng hạt nhân luôn nhỏ hơn tổng khối lượng các nucleon tạo nên nó một lượng gọi là độ hụt khối: Δm = Z.m_p + (A - Z).m_n - m_X. Năng lượng liên kết E_lk = Δm.c²; năng lượng liên kết riêng E_lk/A đặc trưng cho độ bền vững của hạt nhân (lớn nhất ở các hạt nhân có 50 < A < 80)."]'::jsonb,'["Hạt He-4 có Δm = 0,0304 u: E_lk = 0,0304 * 931,5 ≈ 28,3 MeV. Năng lượng liên kết riêng là 28,3 / 4 ≈ 7,07 MeV/nucleon."]'::jsonb,'[{"id": "physics-12-nuclear-structure-q1", "prompt": "Hạt nhân nguyên tử được cấu tạo bởi hai loại hạt cơ bản (gọi chung là nucleon) gồm:", "difficulty": "EASY", "options": [{"id": "a", "text": "Proton và neutron"}, {"id": "b", "text": "Proton và electron"}, {"id": "c", "text": "Neutron và electron"}], "correctOptionId": "a", "explanation": "Nucleon cấu tạo nên hạt nhân nguyên tử bao gồm các hạt proton mang điện tích dương và neutron không mang điện."}, {"id": "physics-12-nuclear-structure-q2", "prompt": "Hạt nhân He-4 có độ hụt khối Δm = 0,0304 u. Cho biết 1 u ≈ 931,5 MeV/c². Năng lượng liên kết của hạt nhân He-4 xấp xỉ bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "14,2 MeV"}, {"id": "b", "text": "56,6 MeV"}, {"id": "c", "text": "28,3 MeV"}], "correctOptionId": "c", "explanation": "E_lk = Δm · c² = 0,0304 u · c² = 0,0304 · 931,5 MeV ≈ 28,3 MeV."}, {"id": "physics-12-nuclear-structure-q3", "prompt": "Đại lượng vật lí nào sau đây đặc trưng cho mức độ bền vững của một hạt nhân nguyên tử?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Độ hụt khối toàn phần của hạt nhân"}, {"id": "b", "text": "Năng lượng liên kết riêng (năng lượng liên kết tính trên một nucleon)"}, {"id": "c", "text": "Năng lượng liên kết toàn phần của hạt nhân"}], "correctOptionId": "b", "explanation": "Hạt nhân có năng lượng liên kết riêng E_lk/A càng lớn thì càng bền vững; bền vững nhất là các hạt nhân có số khối trung bình như sắt Fe-56."}]'::jsonb,'["physics-12-nuclear-structure"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-radioactivity',20,'LESSON','Hiện tượng phóng xạ và định luật phóng xạ','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Phóng xạ là quá trình phân rã tự phát của hạt nhân không bền vững kèm theo phát ra các tia phóng xạ (α: hạt nhân He-4; β⁻: electron; β⁺: positron; γ: sóng điện từ photon năng lượng cao). Định luật phóng xạ: N(t) = N₀ · 2^(-t/T) = N₀ · e^(-λt) với T là chu kì bán rã."]'::jsonb,'["Chất phóng xạ có T = 8 ngày, sau 24 ngày (3 chu kì) số hạt nhân còn lại là N = N₀ / 2³ = N₀ / 8 = 12,5% ban đầu."]'::jsonb,'[{"id": "physics-12-radioactivity-q1", "prompt": "Tia phóng xạ nào sau đây có bản chất là sóng điện từ có bước sóng cực ngắn và năng lượng photon rất cao?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tia alpha (α)"}, {"id": "b", "text": "Tia beta trừ (β⁻)"}, {"id": "c", "text": "Tia gamma (γ)"}], "correctOptionId": "c", "explanation": "Tia gamma là bức xạ điện từ không mang điện, có tần số rất cao và khả năng đâm xuyên mạnh nhất."}, {"id": "physics-12-radioactivity-q2", "prompt": "Một chất phóng xạ có chu kì bán rã T = 8 ngày. Sau khoảng thời gian 24 ngày, tỉ lệ phần trăm số hạt nhân phóng xạ còn lại chưa phân rã so với ban đầu là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "6,25%"}, {"id": "b", "text": "12,5%"}, {"id": "c", "text": "25,0%"}], "correctOptionId": "b", "explanation": "Số chu kì bán rã trôi qua là k = t / T = 24 / 8 = 3. Số hạt còn lại: N / N₀ = (1/2)³ = 1/8 = 12,5%."}, {"id": "physics-12-radioactivity-q3", "prompt": "Đồng vị phóng xạ Carbon-14 (C-14) có chu kì bán rã khoảng 5730 năm được ứng dụng rộng rãi trong khoa học để:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Xác định niên đại của các cổ vật hữu cơ và mẫu hóa thạch khảo cổ học"}, {"id": "b", "text": "Chế tạo nhiên liệu phản ứng nhiệt hạch trên tàu vũ trụ"}, {"id": "c", "text": "Làm nguồn phát tia laser trong phẫu thuật mắt"}], "correctOptionId": "a", "explanation": "Thực vật hấp thụ C-14 qua quang hợp khi còn sống; khi sinh vật chết lượng C-14 phân rã theo thời gian giúp xác định tuổi mẫu vật."}]'::jsonb,'["physics-12-radioactivity"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-nuclear-reactions',21,'LESSON','Phản ứng hạt nhân và các định luật bảo toàn','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Phản ứng hạt nhân tuân theo 4 định luật bảo toàn: bảo toàn điện tích (Z), bảo toàn số nucleon (A), bảo toàn năng lượng toàn phần và bảo toàn động lượng. Không có định luật bảo toàn khối lượng nghỉ. Năng lượng tỏa ra: ΔE = (m_trước - m_sau).c²."]'::jsonb,'["Phản ứng: ₁²H + ₁³H → ₂⁴He + ₀¹n. Tổng Z: 1 + 1 = 2 + 0; Tổng A: 2 + 3 = 4 + 1. Khối lượng giảm nên tỏa năng lượng ~17,6 MeV."]'::jsonb,'[{"id": "physics-12-nuclear-reactions-q1", "prompt": "Định luật nào sau đây KHÔNG áp dụng cho các phản ứng hạt nhân?", "difficulty": "EASY", "options": [{"id": "a", "text": "Định luật bảo toàn số nucleon (số khối A)"}, {"id": "b", "text": "Định luật bảo toàn khối lượng nghỉ"}, {"id": "c", "text": "Định luật bảo toàn điện tích"}], "correctOptionId": "b", "explanation": "Trong phản ứng hạt nhân, tổng khối lượng nghỉ trước và sau phản ứng có sự chênh lệch (độ hụt khối chuyển hóa thành năng lượng) nên khối lượng nghỉ không bảo toàn."}, {"id": "physics-12-nuclear-reactions-q2", "prompt": "Trong phản ứng hạt nhân: ₁²H + ₁³H → ₂⁴He + X. Hạt X sinh ra là hạt nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hạt neutron (₀¹n)"}, {"id": "b", "text": "Hạt proton (₁¹p)"}, {"id": "c", "text": "Hạt electron (-₁⁰e)"}], "correctOptionId": "a", "explanation": "Áp dụng bảo toàn điện tích Z: 1 + 1 = 2 + Z_X ⇒ Z_X = 0. Bảo toàn số nucleon A: 2 + 3 = 4 + A_X ⇒ A_X = 1. Hạt có Z = 0, A = 1 là neutron."}, {"id": "physics-12-nuclear-reactions-q3", "prompt": "Nếu một phản ứng hạt nhân có tổng khối lượng nghỉ của các hạt trước phản ứng m_trước lớn hơn tổng khối lượng nghỉ các hạt sau phản ứng m_sau thì phản ứng đó:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Thu năng lượng"}, {"id": "b", "text": "Không giải phóng hay hấp thụ năng lượng"}, {"id": "c", "text": "Tỏa năng lượng"}], "correctOptionId": "c", "explanation": "Độ biến thiên năng lượng ΔE = (m_trước - m_sau)c² > 0, phần khối lượng giảm chuyển thành động năng hạt và năng lượng photon tỏa ra môi trường."}]'::jsonb,'["physics-12-nuclear-reactions"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-fission-fusion',22,'LESSON','Phản ứng phân hạch và phản ứng nhiệt hạch','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Phân hạch là phản ứng hạt nhân nặng (như U-235) hấp thụ neutron chậm rồi vỡ thành hai mảnh trung bình và giải phóng 2-3 neutron mới (tạo phản ứng dây chuyền; k = 1 là tới hạn có kiểm soát). Nhiệt hạch là phản ứng kết hợp hai hạt nhân nhẹ (H-2, H-3) thành hạt nhân nặng hơn ở nhiệt độ hàng trăm triệu độ."]'::jsonb,'["Phản ứng nhiệt hạch tỏa năng lượng lớn hơn phân hạch tính trên cùng một đơn vị khối lượng và là nguồn năng lượng của các ngôi sao."]'::jsonb,'[{"id": "physics-12-fission-fusion-q1", "prompt": "Bản chất của phản ứng nhiệt hạch (phản ứng tổng hợp hạt nhân) là quá trình:", "difficulty": "EASY", "options": [{"id": "a", "text": "Kết hợp hai hạt nhân rất nhẹ thành một hạt nhân nặng hơn ở nhiệt độ cực kì cao"}, {"id": "b", "text": "Bắn phá hạt nhân nặng bằng neutron làm nó vỡ thành hai mảnh nhẹ"}, {"id": "c", "text": "Hạt nhân tự phát bức xạ tia gamma mà không thay đổi cấu tạo"}], "correctOptionId": "a", "explanation": "Nhiệt hạch là phản ứng kết hợp hai hạt nhân có số khối nhỏ (như hydro, deuteri, triti) thành hạt nhân nặng hơn ở điều kiện nhiệt độ hàng trăm triệu độ."}, {"id": "physics-12-fission-fusion-q2", "prompt": "Để duy trì phản ứng phân hạch dây chuyền tự duy trì có kiểm soát hoạt động ổn định trong lò phản ứng hạt nhân, hệ số nhân neutron k phải bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "k > 1"}, {"id": "b", "text": "k < 1"}, {"id": "c", "text": "k = 1"}], "correctOptionId": "c", "explanation": "Hệ số k = 1 gọi là trạng thái tới hạn: số neutron sinh ra trung bình bù đắp đủ số neutron thất thoát và hấp thụ, duy trì công suất phát điện ổn định."}, {"id": "physics-12-fission-fusion-q3", "prompt": "Nguồn năng lượng khổng lồ phát ra liên tục hàng tỉ năm của Mặt Trời và các vì sao trong vũ trụ có nguồn gốc từ:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Sự cháy oxy hóa khử hóa học của khí methane"}, {"id": "b", "text": "Các phản ứng nhiệt hạch tổng hợp hạt nhân hydrogen thành helium"}, {"id": "c", "text": "Các phản ứng phân hạch dây chuyền của uranium"}], "correctOptionId": "b", "explanation": "Tại vùng lõi Mặt Trời với áp suất và nhiệt độ hàng chục triệu độ Kelvin, phản ứng tổng hợp hạt nhân hydro tạo heli diễn ra liên tục giải phóng năng lượng bức xạ."}]'::jsonb,'["physics-12-fission-fusion"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-radiation-safety',23,'LESSON','Ứng dụng bức xạ và an toàn hạt nhân','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Ứng dụng bức xạ: y học (xạ trị, máy đo PET, dao gamma), nông nghiệp (chiếu xạ giống đột biến, bảo quản nông sản), công nghiệp (kiểm tra khuyết tật mối hàn bằng tia gamma). Nguyên tắc an toàn: giảm thời gian phơi nhiễm, tăng khoảng cách tới nguồn và sử dụng vật liệu che chắn hấp thụ (chì, bê tông cốt thép)."]'::jsonb,'["Phòng chụp X-quang hoặc xạ trị luôn có tường lót chì và kính pha chì để ngăn bức xạ lọt ra ngoài."]'::jsonb,'[{"id": "physics-12-radiation-safety-q1", "prompt": "Biện pháp nào sau đây giúp giảm liều chiếu xạ nguy hiểm cho người khi làm việc gần nguồn phóng xạ?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đứng càng gần nguồn phát phóng xạ càng tốt"}, {"id": "b", "text": "Tăng tối đa thời gian tiếp xúc trực tiếp với nguồn phóng xạ"}, {"id": "c", "text": "Tăng khoảng cách tới nguồn và sử dụng tấm che chắn chì/bê tông dày"}], "correctOptionId": "c", "explanation": "Liều bức xạ tỉ lệ nghịch với bình phương khoảng cách và giảm theo hàm mũ khi qua các tấm che chắn chì hoặc bê tông."}, {"id": "physics-12-radiation-safety-q2", "prompt": "Ứng dụng quan trọng của nguồn phóng xạ phát tia gamma trong y học hiện đại là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đun sôi nước khử trùng phòng bệnh nhanh chóng"}, {"id": "b", "text": "Xạ trị tiêu diệt tế bào khối u ác tính hoặc phẫu thuật bằng dao mổ gamma"}, {"id": "c", "text": "Uống trực tiếp để cung cấp năng lượng trao đổi chất cho cơ thể"}], "correctOptionId": "b", "explanation": "Tia gamma mang năng lượng photon lớn được hội tụ chính xác để phá hủy cấu trúc DNA của các tế bào ung thư mà ít tổn thương mô lành."}, {"id": "physics-12-radiation-safety-q3", "prompt": "Biển báo có hình cánh quạt ba lá màu đen trên nền vàng tươi gắn tại cửa phòng chuyên dụng mang ý nghĩa cảnh báo gì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Khu vực có nguy cơ bức xạ ion hóa nguy hiểm cần tuân thủ an toàn"}, {"id": "b", "text": "Khu vực có quạt thông gió công suất cao đang quay nhanh"}, {"id": "c", "text": "Khu vực nguy cơ cháy nổ khí gas dễ bắt lửa"}], "correctOptionId": "a", "explanation": "Biểu tượng ba cánh quạt (trefoil) là kí hiệu quốc tế chuẩn cảnh báo khu vực chứa nguồn phóng xạ ion hóa hoặc thiết bị phát tia bức xạ hạt nhân."}]'::jsonb,'["physics-12-radiation-safety"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('physics',12,'intro-2026.1','physics-12-review-4',24,'FIVE_LESSON_REVIEW','Ôn tập 4','Vật lí 12: Vật lí nhiệt, Khí lí tưởng, Từ trường và Hạt nhân','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "physics-12-nuclear-structure-q1", "prompt": "Hạt nhân nguyên tử được cấu tạo bởi hai loại hạt cơ bản (gọi chung là nucleon) gồm:", "difficulty": "EASY", "options": [{"id": "a", "text": "Proton và neutron"}, {"id": "b", "text": "Proton và electron"}, {"id": "c", "text": "Neutron và electron"}], "correctOptionId": "a", "explanation": "Nucleon cấu tạo nên hạt nhân nguyên tử bao gồm các hạt proton mang điện tích dương và neutron không mang điện."}, {"id": "physics-12-nuclear-structure-q2", "prompt": "Hạt nhân He-4 có độ hụt khối Δm = 0,0304 u. Cho biết 1 u ≈ 931,5 MeV/c². Năng lượng liên kết của hạt nhân He-4 xấp xỉ bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "14,2 MeV"}, {"id": "b", "text": "56,6 MeV"}, {"id": "c", "text": "28,3 MeV"}], "correctOptionId": "c", "explanation": "E_lk = Δm · c² = 0,0304 u · c² = 0,0304 · 931,5 MeV ≈ 28,3 MeV."}, {"id": "physics-12-radioactivity-q1", "prompt": "Tia phóng xạ nào sau đây có bản chất là sóng điện từ có bước sóng cực ngắn và năng lượng photon rất cao?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tia alpha (α)"}, {"id": "b", "text": "Tia beta trừ (β⁻)"}, {"id": "c", "text": "Tia gamma (γ)"}], "correctOptionId": "c", "explanation": "Tia gamma là bức xạ điện từ không mang điện, có tần số rất cao và khả năng đâm xuyên mạnh nhất."}, {"id": "physics-12-radioactivity-q2", "prompt": "Một chất phóng xạ có chu kì bán rã T = 8 ngày. Sau khoảng thời gian 24 ngày, tỉ lệ phần trăm số hạt nhân phóng xạ còn lại chưa phân rã so với ban đầu là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "6,25%"}, {"id": "b", "text": "12,5%"}, {"id": "c", "text": "25,0%"}], "correctOptionId": "b", "explanation": "Số chu kì bán rã trôi qua là k = t / T = 24 / 8 = 3. Số hạt còn lại: N / N₀ = (1/2)³ = 1/8 = 12,5%."}, {"id": "physics-12-nuclear-reactions-q1", "prompt": "Định luật nào sau đây KHÔNG áp dụng cho các phản ứng hạt nhân?", "difficulty": "EASY", "options": [{"id": "a", "text": "Định luật bảo toàn số nucleon (số khối A)"}, {"id": "b", "text": "Định luật bảo toàn khối lượng nghỉ"}, {"id": "c", "text": "Định luật bảo toàn điện tích"}], "correctOptionId": "b", "explanation": "Trong phản ứng hạt nhân, tổng khối lượng nghỉ trước và sau phản ứng có sự chênh lệch (độ hụt khối chuyển hóa thành năng lượng) nên khối lượng nghỉ không bảo toàn."}, {"id": "physics-12-nuclear-reactions-q2", "prompt": "Trong phản ứng hạt nhân: ₁²H + ₁³H → ₂⁴He + X. Hạt X sinh ra là hạt nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hạt neutron (₀¹n)"}, {"id": "b", "text": "Hạt proton (₁¹p)"}, {"id": "c", "text": "Hạt electron (-₁⁰e)"}], "correctOptionId": "a", "explanation": "Áp dụng bảo toàn điện tích Z: 1 + 1 = 2 + Z_X ⇒ Z_X = 0. Bảo toàn số nucleon A: 2 + 3 = 4 + A_X ⇒ A_X = 1. Hạt có Z = 0, A = 1 là neutron."}, {"id": "physics-12-fission-fusion-q1", "prompt": "Bản chất của phản ứng nhiệt hạch (phản ứng tổng hợp hạt nhân) là quá trình:", "difficulty": "EASY", "options": [{"id": "a", "text": "Kết hợp hai hạt nhân rất nhẹ thành một hạt nhân nặng hơn ở nhiệt độ cực kì cao"}, {"id": "b", "text": "Bắn phá hạt nhân nặng bằng neutron làm nó vỡ thành hai mảnh nhẹ"}, {"id": "c", "text": "Hạt nhân tự phát bức xạ tia gamma mà không thay đổi cấu tạo"}], "correctOptionId": "a", "explanation": "Nhiệt hạch là phản ứng kết hợp hai hạt nhân có số khối nhỏ (như hydro, deuteri, triti) thành hạt nhân nặng hơn ở điều kiện nhiệt độ hàng trăm triệu độ."}, {"id": "physics-12-fission-fusion-q2", "prompt": "Để duy trì phản ứng phân hạch dây chuyền tự duy trì có kiểm soát hoạt động ổn định trong lò phản ứng hạt nhân, hệ số nhân neutron k phải bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "k > 1"}, {"id": "b", "text": "k < 1"}, {"id": "c", "text": "k = 1"}], "correctOptionId": "c", "explanation": "Hệ số k = 1 gọi là trạng thái tới hạn: số neutron sinh ra trung bình bù đắp đủ số neutron thất thoát và hấp thụ, duy trì công suất phát điện ổn định."}, {"id": "physics-12-radiation-safety-q1", "prompt": "Biện pháp nào sau đây giúp giảm liều chiếu xạ nguy hiểm cho người khi làm việc gần nguồn phóng xạ?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đứng càng gần nguồn phát phóng xạ càng tốt"}, {"id": "b", "text": "Tăng tối đa thời gian tiếp xúc trực tiếp với nguồn phóng xạ"}, {"id": "c", "text": "Tăng khoảng cách tới nguồn và sử dụng tấm che chắn chì/bê tông dày"}], "correctOptionId": "c", "explanation": "Liều bức xạ tỉ lệ nghịch với bình phương khoảng cách và giảm theo hàm mũ khi qua các tấm che chắn chì hoặc bê tông."}, {"id": "physics-12-radiation-safety-q2", "prompt": "Ứng dụng quan trọng của nguồn phóng xạ phát tia gamma trong y học hiện đại là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đun sôi nước khử trùng phòng bệnh nhanh chóng"}, {"id": "b", "text": "Xạ trị tiêu diệt tế bào khối u ác tính hoặc phẫu thuật bằng dao mổ gamma"}, {"id": "c", "text": "Uống trực tiếp để cung cấp năng lượng trao đổi chất cho cơ thể"}], "correctOptionId": "b", "explanation": "Tia gamma mang năng lượng photon lớn được hội tụ chính xác để phá hủy cấu trúc DNA của các tế bào ung thư mà ít tổn thương mô lành."}]'::jsonb,'["physics-12-nuclear-structure", "physics-12-radioactivity", "physics-12-nuclear-reactions", "physics-12-fission-fusion", "physics-12-radiation-safety"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','placement',0,'PLACEMENT','Khảo sát đầu vào','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "chemistry-12-ester-structure-q1", "prompt": "Tên gọi theo danh pháp thông thường của ester có công thức cấu tạo thu gọn CH₃COOC₂H₅ là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Ethyl acetate"}, {"id": "b", "text": "Methyl acetate"}, {"id": "c", "text": "Ethyl propionate"}], "correctOptionId": "a", "explanation": "Tên gọi gồm tên gốc ethyl (C₂H₅-) kết hợp với gốc acetate (CH₃COO-), thành ethyl acetate."}, {"id": "chemistry-12-ester-structure-q2", "prompt": "Trong các chất có khối lượng phân tử xấp xỉ nhau sau đây, chất nào có nhiệt độ sôi thấp nhất?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "CH₃COOH (Acetic acid)"}, {"id": "b", "text": "C₃H₇OH (Propan-1-ol)"}, {"id": "c", "text": "HCOOCH₃ (Methyl formate)"}], "correctOptionId": "c", "explanation": "Ester không có nguyên tử hydro linh động liên kết với oxy nên không tạo được liên kết hydro liên phân tử, do đó nhiệt độ sôi thấp hơn hẳn acid và alcohol."}, {"id": "chemistry-12-ester-reactions-q1", "prompt": "Phản ứng thủy phân ester trong dung dịch kiềm đun nóng còn được gọi là phản ứng gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Phản ứng ester hóa"}, {"id": "b", "text": "Phản ứng trùng hợp"}, {"id": "c", "text": "Phản ứng xà phòng hóa"}], "correctOptionId": "c", "explanation": "Thủy phân ester tạo ra muối của acid béo (thành phần xà phòng) nên phản ứng này gọi là phản ứng xà phòng hóa."}, {"id": "chemistry-12-ester-reactions-q2", "prompt": "Đun nóng ethyl formate (HCOOC₂H₅) với dung dịch NaOH vừa đủ thu được các sản phẩm là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "HCOONa và CH₃OH"}, {"id": "b", "text": "HCOONa và C₂H₅OH"}, {"id": "c", "text": "CH₃COONa và CH₃OH"}], "correctOptionId": "b", "explanation": "Phương trình phản ứng: HCOOC₂H₅ + NaOH → HCOONa (sodium formate) + C₂H₅OH (ethanol)."}, {"id": "chemistry-12-lipid-triglyceride-q1", "prompt": "Glycerol (glycerin) là polyalcohol ba chức tham gia cấu tạo nên mọi triglyceride có công thức là:", "difficulty": "EASY", "options": [{"id": "a", "text": "C₃H₇OH"}, {"id": "b", "text": "C₃H₅(OH)₃"}, {"id": "c", "text": "C₂H₄(OH)₂"}], "correctOptionId": "b", "explanation": "Glycerol là propane-1,2,3-triol có 3 nhóm -OH liên kết với 3 nguyên tử carbon: C₃H₅(OH)₃."}, {"id": "chemistry-12-lipid-triglyceride-q2", "prompt": "Acid béo nào sau đây là acid béo no phổ biến trong mỡ động vật?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Acid stearic (C₁₇H₃₅COOH)"}, {"id": "b", "text": "Acid oleic (C₁₇H₃₃COOH)"}, {"id": "c", "text": "Acid linoleic (C₁₇H₃₁COOH)"}], "correctOptionId": "a", "explanation": "Acid stearic có gốc hydrocarbon C₁₇H₃₅- no (dạng C_n H_2n+1) nên là acid béo no."}, {"id": "chemistry-12-lipid-reactions-q1", "prompt": "Xà phòng hóa hoàn toàn 1 mol chất béo triglyceride bằng dung dịch NaOH luôn thu được bao nhiêu mol glycerol?", "difficulty": "EASY", "options": [{"id": "a", "text": "1 mol"}, {"id": "b", "text": "3 mol"}, {"id": "c", "text": "2 mol"}], "correctOptionId": "a", "explanation": "Mỗi phân tử triglyceride liên kết 3 gốc acid với 1 khung glycerol, do đó thủy phân 1 mol chất béo luôn giải phóng đúng 1 mol glycerol."}, {"id": "chemistry-12-lipid-reactions-q2", "prompt": "Quá trình chuyển hóa dầu thực vật (chất béo lỏng) thành bơ nhân tạo (chất béo rắn) trong công nghiệp dựa trên phản ứng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thủy phân chất béo trong môi trường acid loãng"}, {"id": "b", "text": "Oxi hóa cắt mạch hydrocarbon bằng thuốc tím"}, {"id": "c", "text": "Hydrogen hóa chất béo không no có xúc tác nickel ở nhiệt độ cao"}], "correctOptionId": "c", "explanation": "Cộng hydrogen vào các liên kết đôi C=C của gốc acid béo không no chuyển thành gốc acid no có nhiệt độ nóng chảy cao hơn ở thể rắn."}, {"id": "chemistry-12-soap-detergent-q1", "prompt": "Muối nào sau đây là thành phần hoạt chất chính trong bánh xà phòng thông thường?", "difficulty": "EASY", "options": [{"id": "a", "text": "Sodium chloride (NaCl)"}, {"id": "b", "text": "Calcium carbonate (CaCO₃)"}, {"id": "c", "text": "Sodium stearate (C₁₇H₃₅COONa)"}], "correctOptionId": "c", "explanation": "Xà phòng là muối sodium hoặc potassium của các acid béo, phổ biến là sodium stearate và sodium palmitate."}, {"id": "chemistry-12-soap-detergent-q2", "prompt": "Cơ chế làm sạch vết bẩn dầu mỡ của xà phòng dựa vào đặc điểm cấu tạo phân tử nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Phân tử đóng vai trò là chất oxi hóa cực mạnh đốt cháy dầu mỡ"}, {"id": "b", "text": "Phân tử gồm một đầu ưa nước tan trong nước và một đuôi kị nước ưa dầu mỡ"}, {"id": "c", "text": "Phân tử có tính acid mạnh hòa tan mọi kim loại"}], "correctOptionId": "b", "explanation": "Đuôi kị nước găm vào giọt dầu mỡ, đầu ưa nước quay ra ngoài nước tạo thành các hạt micelle lơ lửng bị dòng nước cuốn đi."}, {"id": "chemistry-12-carbohydrate-classification-q1", "prompt": "Chất nào sau đây thuộc loại monosaccharide không bị thủy phân?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tinh bột"}, {"id": "b", "text": "Glucose"}, {"id": "c", "text": "Saccharose"}], "correctOptionId": "b", "explanation": "Monosaccharide là carbohydrate đơn giản nhất không thể bị thủy phân thành đường nhỏ hơn, ví dụ glucose và fructose."}, {"id": "chemistry-12-carbohydrate-classification-q2", "prompt": "Glucose và fructose là hai chất:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đồng phân cấu tạo của nhau có cùng công thức phân tử C₆H₁₂O₆"}, {"id": "b", "text": "Đồng đẳng kế tiếp nhau trong cùng dãy đồng đẳng"}, {"id": "c", "text": "Thuộc hai loại đường disaccharide khác nhau"}], "correctOptionId": "a", "explanation": "Cả glucose và fructose đều có công thức phân tử C₆H₁₂O₆ nhưng glucose chứa nhóm -CHO còn fructose chứa nhóm >C=O, nên là đồng phân."}, {"id": "chemistry-12-glucose-fructose-reactions-q1", "prompt": "Thuốc thử được dùng để nhận biết dung dịch glucose tạo dung dịch phức chất màu xanh lam thẫm ở nhiệt độ thường là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Cu(OH)₂ trong môi trường kiềm"}, {"id": "b", "text": "Dung dịch AgNO₃ trong NH₃"}, {"id": "c", "text": "Dung dịch nước vôi trong Ca(OH)₂"}], "correctOptionId": "a", "explanation": "Vì glucose có nhiều nhóm -OH liền kề (polyalcohol) nên hòa tan Cu(OH)₂ ở nhiệt độ thường tạo dung dịch màu xanh lam thẫm."}, {"id": "chemistry-12-glucose-fructose-reactions-q2", "prompt": "Cho 1 mol glucose tham gia phản ứng tráng bạc hoàn toàn với dung dịch AgNO₃ trong NH₃ dư, lượng Ag kim loại kết tủa thu được tối đa là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "1 mol"}, {"id": "b", "text": "4 mol"}, {"id": "c", "text": "2 mol"}], "correctOptionId": "c", "explanation": "Phân tử glucose có 1 nhóm aldehyde -CHO, theo phương trình phản ứng tráng bạc: 1 mol -CHO giải phóng 2 mol Ag kim loại."}, {"id": "chemistry-12-sucrose-maltose-q1", "prompt": "Đường mía, đường củ cải dùng làm chất tạo ngọt trong đời sống hàng ngày có thành phần chính là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Glucose"}, {"id": "b", "text": "Maltose"}, {"id": "c", "text": "Saccharose"}], "correctOptionId": "c", "explanation": "Saccharose là disaccharide phổ biến nhất, được sản xuất công nghiệp từ cây mía hoặc củ cải đường."}, {"id": "chemistry-12-sucrose-maltose-q2", "prompt": "Khi thủy phân hoàn toàn 1 mol saccharose trong môi trường acid đun nóng, ta thu được sản phẩm gồm:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2 mol fructose"}, {"id": "b", "text": "1 mol glucose và 1 mol fructose"}, {"id": "c", "text": "2 mol glucose"}], "correctOptionId": "b", "explanation": "Phân tử saccharose được cấu tạo từ 1 gốc glucose và 1 gốc fructose, khi thủy phân phân cắt liên kết glycosidic tạo tỉ lệ mol 1:1."}, {"id": "chemistry-12-starch-q1", "prompt": "Thuốc thử đặc trưng dùng để nhận biết hồ tinh bột bằng phản ứng tạo màu xanh tím là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Dung dịch AgNO₃/NH₃"}, {"id": "b", "text": "Dung dịch iodine (I₂)"}, {"id": "c", "text": "Dung dịch Cu(OH)₂"}], "correctOptionId": "b", "explanation": "Cấu trúc xoắn ốc của amylose tạo các khoang rỗng hấp phụ phân tử iodine tạo phức chất có màu xanh tím đặc trưng."}, {"id": "chemistry-12-starch-q2", "prompt": "Điểm khác biệt cơ bản về mặt cấu trúc giữa amylose và amylopectin trong hạt tinh bột là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Amylose có cấu trúc mạch không phân nhánh, còn amylopectin có cấu trúc mạch phân nhánh"}, {"id": "b", "text": "Amylose là đường đơn, còn amylopectin là đường đôi"}, {"id": "c", "text": "Amylose có liên kết peptide, còn amylopectin có liên kết ester"}], "correctOptionId": "a", "explanation": "Amylose gồm các gốc α-glucose liên kết α-1,4 mạch thẳng xoắn; amylopectin có thêm các nhánh tại vị trí liên kết α-1,6-glycosidic."}, {"id": "chemistry-12-cellulose-q1", "prompt": "Trong công thức cấu tạo thu gọn [C₆H₇O₂(OH)₃]_n của cellulose, mỗi mắt xích C₆H₁₀O₅ chứa bao nhiêu nhóm hydroxy (-OH) tự do?", "difficulty": "EASY", "options": [{"id": "a", "text": "3 nhóm -OH"}, {"id": "b", "text": "2 nhóm -OH"}, {"id": "c", "text": "5 nhóm -OH"}], "correctOptionId": "a", "explanation": "Mỗi mắt xích glucose trong mạch cellulose còn giữ lại đúng 3 nhóm alcohol tự do: [C₆H₇O₂(OH)₃]_n."}, {"id": "chemistry-12-cellulose-q2", "prompt": "Sản phẩm thu được khi cho cellulose phản ứng hoàn toàn với hỗn hợp acid nitric đặc và acid sulfuric đặc làm thuốc súng không khói là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cellulose triacetate"}, {"id": "b", "text": "Trinitrotoluene (TNT)"}, {"id": "c", "text": "Cellulose trinitrate"}], "correctOptionId": "c", "explanation": "Ba nhóm -OH trong mỗi mắt xích bị ester hóa bởi HNO₃ tạo [C₆H₇O₂(ONO₂)₃]_n (cellulose trinitrate), một chất nổ mạnh không khói."}, {"id": "chemistry-12-amines-q1", "prompt": "Hợp chất methylamine có công thức CH₃NH₂ thuộc loại amine bậc mấy?", "difficulty": "EASY", "options": [{"id": "a", "text": "Amine bậc 2"}, {"id": "b", "text": "Amine bậc 3"}, {"id": "c", "text": "Amine bậc 1"}], "correctOptionId": "c", "explanation": "Bậc của amine tính bằng số nguyên tử H trong NH₃ được thay thế bằng gốc hydrocarbon. CH₃NH₂ có 1 gốc CH₃- nên là amine bậc 1."}, {"id": "chemistry-12-amines-q2", "prompt": "Dãy sắp xếp các chất theo thứ tự lực base giảm dần từ trái sang phải là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "NH₃ > CH₃NH₂ > C₆H₅NH₂"}, {"id": "b", "text": "CH₃NH₂ > NH₃ > C₆H₅NH₂ (aniline)"}, {"id": "c", "text": "C₆H₅NH₂ > NH₃ > CH₃NH₂"}], "correctOptionId": "b", "explanation": "Gốc alkyl -CH₃ đẩy electron làm tăng mật độ điện tích trên N (tính base mạnh hơn NH₃); vòng phenyl -C₆H₅ hút electron làm giảm mật độ trên N (tính base yếu hơn NH₃)."}, {"id": "chemistry-12-amino-acids-q1", "prompt": "Amino acid đơn giản nhất có tên gọi là glycine có công thức cấu tạo là:", "difficulty": "EASY", "options": [{"id": "a", "text": "H₂N-CH₂-CH₂-COOH"}, {"id": "b", "text": "H₂N-CH₂-COOH"}, {"id": "c", "text": "CH₃-CH(NH₂)-COOH"}], "correctOptionId": "b", "explanation": "Glycine (acid aminoacetic) có phân tử khối bằng 75, công thức H₂N-CH₂-COOH."}, {"id": "chemistry-12-amino-acids-q2", "prompt": "Ở trạng thái tinh thể và trong dung dịch nước, phân tử amino acid tồn tại chủ yếu ở dạng cấu trúc nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ion lưỡng cực (muối nội phân tử H₃N⁺-CH(R)-COO⁻)"}, {"id": "b", "text": "Dạng phân tử trung hòa H₂N-CH(R)-COOH"}, {"id": "c", "text": "Dạng cation mang điện tích dương hoàn toàn"}], "correctOptionId": "a", "explanation": "Nhóm -COOH có tính acid nhường H⁺ cho nhóm -NH₂ có tính base ngay trong phân tử, tạo dạng ion lưỡng cực bền vững."}, {"id": "chemistry-12-peptides-proteins-q1", "prompt": "Liên kết hóa học giữa nhóm -CO- và nhóm -NH- của hai đơn vị α-amino acid được gọi là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Liên kết peptide"}, {"id": "b", "text": "Liên kết glycosidic"}, {"id": "c", "text": "Liên kết ester"}], "correctOptionId": "a", "explanation": "Định nghĩa liên kết peptide là liên kết amide tạo bởi nhóm carboxyl của α-amino acid này với nhóm amino của α-amino acid kia."}, {"id": "chemistry-12-peptides-proteins-q2", "prompt": "Hợp chất nào sau đây tham gia phản ứng màu biuret với Cu(OH)₂ trong môi trường kiềm tạo dung dịch màu tím đặc trưng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Dipeptide"}, {"id": "b", "text": "Monosaccharide"}, {"id": "c", "text": "Tripeptide trở lên và protein"}], "correctOptionId": "c", "explanation": "Điều kiện của phản ứng màu biuret là phân tử phải có từ 2 liên kết peptide trở lên, tức từ tripeptide trở lên."}, {"id": "chemistry-12-polymer-basics-q1", "prompt": "Phản ứng kết hợp nhiều phân tử nhỏ (monomer) giống nhau hay tương tự nhau thành phân tử lớn (polymer) gọi là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Phản ứng xà phòng hóa"}, {"id": "b", "text": "Phản ứng este hóa"}, {"id": "c", "text": "Phản ứng trùng hợp"}], "correctOptionId": "c", "explanation": "Định nghĩa phản ứng trùng hợp là quá trình cộng hợp liên tiếp nhiều phân tử nhỏ thành phân tử có khối lượng phân tử rất lớn."}, {"id": "chemistry-12-polymer-basics-q2", "prompt": "Polyethylene (PE) là vật liệu polymer thông dụng được tổng hợp bằng phản ứng trùng hợp monomer nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Vinyl chloride (CH₂=CH-Cl)"}, {"id": "b", "text": "Ethylene (CH₂=CH₂)"}, {"id": "c", "text": "Propylene (CH₂=CH-CH₃)"}], "correctOptionId": "b", "explanation": "Polyethylene được tạo ra từ phản ứng trùng hợp khí ethylene dưới áp suất và xúc tác thích hợp: n CH₂=CH₂ → (-CH₂-CH₂-)_n."}, {"id": "chemistry-12-polymer-materials-q1", "prompt": "Vật liệu polymer nào sau đây được phủ lên bề mặt chảo chống dính nhờ độ bền nhiệt cao và tính trơ hóa học tuyệt vời?", "difficulty": "EASY", "options": [{"id": "a", "text": "Polyethylene (PE)"}, {"id": "b", "text": "Teflon (polytetrafluoroethylene)"}, {"id": "c", "text": "Polyvinyl chloride (PVC)"}], "correctOptionId": "b", "explanation": "Teflon (-CF₂-CF₂-)_n có liên kết C-F rất bền vững, không phản ứng với dầu mỡ ở nhiệt độ nấu nướng và có hệ số ma sát cực thấp."}, {"id": "chemistry-12-polymer-materials-q2", "prompt": "Tơ nylon-6,6 là một loại tơ tổng hợp thuộc phân loại tơ nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tơ polyamide"}, {"id": "b", "text": "Tơ polyester"}, {"id": "c", "text": "Tơ bán tổng hợp (tơ nhân tạo)"}], "correctOptionId": "a", "explanation": "Nylon-6,6 được điều chế từ hexamethylenediamine và adipic acid, chứa các liên kết amide -CO-NH- lặp lại nên là tơ polyamide."}, {"id": "chemistry-12-electrode-potentials-q1", "prompt": "Trong thang đo thế điện cực chuẩn, điện cực chuẩn hydrogen được quy ước có thế điện cực ở 25 °C bằng:", "difficulty": "EASY", "options": [{"id": "a", "text": "0,00 V"}, {"id": "b", "text": "1,00 V"}, {"id": "c", "text": "-1,00 V"}], "correctOptionId": "a", "explanation": "Điện cực hydro chuẩn (SHE) với H⁺ (1 M) và khí H₂ (1 bar) trên bề mặt platin được chọn làm mốc chuẩn có E° = 0,00 V."}, {"id": "chemistry-12-electrode-potentials-q2", "prompt": "Cho thế điện cực chuẩn: E°(Zn²⁺/Zn) = -0,76 V và E°(Cu²⁺/Cu) = +0,34 V. So sánh tính oxi hóa giữa hai ion kim loại:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ion Zn²⁺ có tính oxi hóa mạnh hơn ion Cu²⁺"}, {"id": "b", "text": "Hai ion có tính oxi hóa tương đương nhau"}, {"id": "c", "text": "Ion Cu²⁺ có tính oxi hóa mạnh hơn ion Zn²⁺"}], "correctOptionId": "c", "explanation": "Cặp có thế điện cực chuẩn lớn hơn (+0,34 V > -0,76 V) thì dạng oxi hóa (Cu²⁺) có tính oxi hóa mạnh hơn."}, {"id": "chemistry-12-galvanic-cells-q1", "prompt": "Trong pin điện hóa Zn - Cu (pin Daniell) khi hoạt động, tại cực âm (anode) xảy ra quá trình nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quá trình khử ion kẽm (Zn²⁺ + 2e → Zn)"}, {"id": "b", "text": "Quá trình oxi hóa ion đồng (Cu → Cu²⁺ + 2e)"}, {"id": "c", "text": "Quá trình oxi hóa kẽm (Zn → Zn²⁺ + 2e)"}], "correctOptionId": "c", "explanation": "Tại cực âm (anode), kẽm có tính khử mạnh hơn bị oxi hóa nhường electron đi vào mạch ngoài."}, {"id": "chemistry-12-galvanic-cells-q2", "prompt": "Cho E°(Zn²⁺/Zn) = -0,76 V và E°(Cu²⁺/Cu) = +0,34 V. Sức điện động chuẩn của pin điện hóa Zn - Cu bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "-0,42 V"}, {"id": "b", "text": "1,10 V"}, {"id": "c", "text": "0,42 V"}], "correctOptionId": "b", "explanation": "E°_pin = E°_cathode - E°_anode = E°(Cu²⁺/Cu) - E°(Zn²⁺/Zn) = +0,34 - (-0,76) = +1,10 V."}, {"id": "chemistry-12-electrolysis-q1", "prompt": "Kim loại nhôm (Al) trong công nghiệp được sản xuất với quy mô lớn bằng phương pháp nào sau đây?", "difficulty": "EASY", "options": [{"id": "a", "text": "Thủy luyện dùng sắt đẩy nhôm ra khỏi dung dịch muối AlCl₃"}, {"id": "b", "text": "Điện phân nóng chảy Al₂O₃ với sự có mặt của phụ gia cryolite (Na₃AlF₆)"}, {"id": "c", "text": "Nhiệt luyện dùng CO khử Al₂O₃ ở nhiệt độ cao"}], "correctOptionId": "b", "explanation": "Nhôm là kim loại có tính khử mạnh, ion Al³⁺ rất khó bị khử nên bắt buộc phải dùng phương pháp điện phân nóng chảy."}, {"id": "chemistry-12-electrolysis-q2", "prompt": "Trong quá trình điện phân dung dịch CuCl₂ bằng dòng điện một chiều với hai điện cực trơ, tại cathode (cực âm) xảy ra quá trình nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Khử ion Cu²⁺ thành Cu kim loại (Cu²⁺ + 2e → Cu)"}, {"id": "b", "text": "Oxi hóa ion Cl⁻ thành khí Cl₂"}, {"id": "c", "text": "Oxi hóa nước giải phóng khí oxy"}], "correctOptionId": "a", "explanation": "Tại cathode (cực âm), cation Cu²⁺ bị hút về và nhận electron thực hiện quá trình khử tạo đồng kim loại bám lên điện cực."}, {"id": "chemistry-12-metal-corrosion-q1", "prompt": "Điều kiện để xảy ra hiện tượng ăn mòn điện hóa học kim loại bao gồm các yếu tố nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Hai điện cực khác bản chất, tiếp xúc trực tiếp hoặc gián tiếp, và cùng tiếp xúc với dung dịch điện li"}, {"id": "b", "text": "Chỉ cần kim loại được đặt trong môi trường chân không tuyệt đối"}, {"id": "c", "text": "Chỉ xảy ra khi nối kim loại với một nguồn điện một chiều bên ngoài"}], "correctOptionId": "a", "explanation": "Ăn mòn điện hóa đòi hỏi 3 điều kiện: hai điện cực khác nhau, có tiếp xúc điện và cùng nhúng trong môi trường dẫn điện điện li."}, {"id": "chemistry-12-metal-corrosion-q2", "prompt": "Để bảo vệ vỏ tàu thủy bằng thép (chứa Fe) khỏi bị ăn mòn khi hoạt động trên biển, người ta thường gắn vào vỏ tàu các tấm kim loại nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tấm đồng (Cu)"}, {"id": "b", "text": "Tấm bạc (Ag)"}, {"id": "c", "text": "Tấm kẽm (Zn)"}], "correctOptionId": "c", "explanation": "Kẽm có tính khử mạnh hơn sắt (E°(Zn²⁺/Zn) = -0,76 V < -0,44 V) nên đóng vai trò là anode hi sinh, bị ăn mòn thay cho vỏ tàu thép."}, {"id": "chemistry-12-metal-properties-extraction-q1", "prompt": "Các tính chất vật lí chung của kim loại như tính dẫn điện, dẫn nhiệt, tính dẻo và ánh kim do thành phần nào trong tinh thể quyết định?", "difficulty": "EASY", "options": [{"id": "a", "text": "Các liên kết cộng hóa trị phân cực giữa các nguyên tử"}, {"id": "b", "text": "Kích thước hạt nhân nguyên tử kim loại"}, {"id": "c", "text": "Các electron tự do di chuyển trong toàn bộ mạng tinh thể kim loại"}], "correctOptionId": "c", "explanation": "Mô hình biển electron tự do giải thích trọn vẹn 4 tính chất vật lí chung đặc trưng của giới kim loại."}, {"id": "chemistry-12-metal-properties-extraction-q2", "prompt": "Phương pháp nhiệt luyện dùng khí CO hoặc H₂ để khử oxit kim loại ở nhiệt độ cao thường được áp dụng để điều chế các kim loại nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ dùng riêng cho kim loại nhôm (Al)"}, {"id": "b", "text": "Các kim loại đứng sau nhôm trong dãy hoạt động hóa học (như Fe, Cu, Zn)"}, {"id": "c", "text": "Các kim loại kiềm và kiềm thổ (như Na, K, Ca)"}], "correctOptionId": "b", "explanation": "CO và H₂ chỉ có thể khử được các ion kim loại có tính oxi hóa từ kẽm (Zn) trở đi (sau Al) ở nhiệt độ cao."}]'::jsonb,'[]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-ester-structure',1,'LESSON','Cấu tạo, danh pháp và tính chất vật lí của ester','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Ester no đơn chức mạch hở có công thức chung C_n H_2n O_2 (n ≥ 2). Tên gọi: tên gốc hydrocarbon R'' + tên gốc acid đuôi ''at''. Ester có nhiệt độ sôi thấp hơn alcohol và carboxylic acid có cùng phân tử khối do không có liên kết hydrogen liên phân tử. Thường ít tan trong nước và có mùi thơm hoa quả."]'::jsonb,'["Ester CH₃COOC₂H₅ có tên gọi là ethyl acetate; có mùi thơm dễ chịu của hoa quả chín."]'::jsonb,'[{"id": "chemistry-12-ester-structure-q1", "prompt": "Tên gọi theo danh pháp thông thường của ester có công thức cấu tạo thu gọn CH₃COOC₂H₅ là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Ethyl acetate"}, {"id": "b", "text": "Methyl acetate"}, {"id": "c", "text": "Ethyl propionate"}], "correctOptionId": "a", "explanation": "Tên gọi gồm tên gốc ethyl (C₂H₅-) kết hợp với gốc acetate (CH₃COO-), thành ethyl acetate."}, {"id": "chemistry-12-ester-structure-q2", "prompt": "Trong các chất có khối lượng phân tử xấp xỉ nhau sau đây, chất nào có nhiệt độ sôi thấp nhất?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "CH₃COOH (Acetic acid)"}, {"id": "b", "text": "C₃H₇OH (Propan-1-ol)"}, {"id": "c", "text": "HCOOCH₃ (Methyl formate)"}], "correctOptionId": "c", "explanation": "Ester không có nguyên tử hydro linh động liên kết với oxy nên không tạo được liên kết hydro liên phân tử, do đó nhiệt độ sôi thấp hơn hẳn acid và alcohol."}, {"id": "chemistry-12-ester-structure-q3", "prompt": "Isoamyl acetate là ester có mùi thơm đặc trưng của quả chuối chín. Công thức phân tử tổng quát của một ester no, đơn chức, mạch hở là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "CnH2n-2O2 (n ≥ 3)"}, {"id": "b", "text": "CnH2nO2 (n ≥ 2)"}, {"id": "c", "text": "CnH2n+2O2 (n ≥ 1)"}], "correctOptionId": "b", "explanation": "Ester no đơn chức mạch hở được tạo thành từ acid no đơn chức và alcohol no đơn chức, có dạng C_n H_2n O_2 với số nguyên tử cacbon n ≥ 2."}]'::jsonb,'["chemistry-12-ester-structure"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-ester-reactions',2,'LESSON','Tính chất hóa học của ester','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Phản ứng thủy phân trong môi trường acid (H₂SO₄ loãng, đun nóng) là phản ứng thuận nghịch: RCOOR'' + H₂O ⇌ RCOOH + R''OH. Phản ứng thủy phân trong dung dịch kiềm (xà phòng hóa) là phản ứng một chiều: RCOOR'' + NaOH → RCOONa + R''OH."]'::jsonb,'["Thủy phân ethyl acetate bằng dung dịch NaOH: CH₃COOC₂H₅ + NaOH → CH₃COONa + C₂H₅OH."]'::jsonb,'[{"id": "chemistry-12-ester-reactions-q1", "prompt": "Phản ứng thủy phân ester trong dung dịch kiềm đun nóng còn được gọi là phản ứng gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Phản ứng ester hóa"}, {"id": "b", "text": "Phản ứng trùng hợp"}, {"id": "c", "text": "Phản ứng xà phòng hóa"}], "correctOptionId": "c", "explanation": "Thủy phân ester tạo ra muối của acid béo (thành phần xà phòng) nên phản ứng này gọi là phản ứng xà phòng hóa."}, {"id": "chemistry-12-ester-reactions-q2", "prompt": "Đun nóng ethyl formate (HCOOC₂H₅) với dung dịch NaOH vừa đủ thu được các sản phẩm là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "HCOONa và CH₃OH"}, {"id": "b", "text": "HCOONa và C₂H₅OH"}, {"id": "c", "text": "CH₃COONa và CH₃OH"}], "correctOptionId": "b", "explanation": "Phương trình phản ứng: HCOOC₂H₅ + NaOH → HCOONa (sodium formate) + C₂H₅OH (ethanol)."}, {"id": "chemistry-12-ester-reactions-q3", "prompt": "Điểm khác biệt căn bản về chiều phản ứng giữa thủy phân ester trong môi trường acid và kiềm là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Thủy phân trong acid là phản ứng thuận nghịch hai chiều, trong kiềm là phản ứng một chiều"}, {"id": "b", "text": "Thủy phân trong acid là phản ứng một chiều, trong kiềm là thuận nghịch"}, {"id": "c", "text": "Cả hai phản ứng đều là phản ứng thuận nghịch hai chiều"}], "correctOptionId": "a", "explanation": "Trong môi trường kiềm, muối sinh ra không phản ứng lại với alcohol để tái tạo ester nên phản ứng diễn ra một chiều hoàn toàn."}]'::jsonb,'["chemistry-12-ester-reactions"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-lipid-triglyceride',3,'LESSON','Cấu tạo của lipid và triglyceride','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Chất béo (triglyceride) là triester của glycerol với các acid béo mạch dài không phân nhánh có số carbon chẵn. Acid béo no: palmitic (C₁₅H₃₁COOH), stearic (C₁₇H₃₅COOH); tạo mỡ động vật thể rắn. Acid béo không no: oleic (C₁₇H₃₃COOH, 1 liên kết đôi C=C), linoleic (C₁₇H₃₁COOH); tạo dầu thực vật thể lỏng."]'::jsonb,'["Triolein ((C₁₇H₃₃COO)₃C₃H₅) là chất béo không no ở thể lỏng ở nhiệt độ thường; Tristearin ((C₁₇H₃₅COO)₃C₃H₅) là chất béo no ở thể rắn."]'::jsonb,'[{"id": "chemistry-12-lipid-triglyceride-q1", "prompt": "Glycerol (glycerin) là polyalcohol ba chức tham gia cấu tạo nên mọi triglyceride có công thức là:", "difficulty": "EASY", "options": [{"id": "a", "text": "C₃H₇OH"}, {"id": "b", "text": "C₃H₅(OH)₃"}, {"id": "c", "text": "C₂H₄(OH)₂"}], "correctOptionId": "b", "explanation": "Glycerol là propane-1,2,3-triol có 3 nhóm -OH liên kết với 3 nguyên tử carbon: C₃H₅(OH)₃."}, {"id": "chemistry-12-lipid-triglyceride-q2", "prompt": "Acid béo nào sau đây là acid béo no phổ biến trong mỡ động vật?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Acid stearic (C₁₇H₃₅COOH)"}, {"id": "b", "text": "Acid oleic (C₁₇H₃₃COOH)"}, {"id": "c", "text": "Acid linoleic (C₁₇H₃₁COOH)"}], "correctOptionId": "a", "explanation": "Acid stearic có gốc hydrocarbon C₁₇H₃₅- no (dạng C_n H_2n+1) nên là acid béo no."}, {"id": "chemistry-12-lipid-triglyceride-q3", "prompt": "Chất béo triolein ((C₁₇H₃₃COO)₃C₃H₅) ở điều kiện nhiệt độ phòng tồn tại ở thể lỏng vì lý do cấu tạo nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Phân tử có khối lượng mol quá nhỏ so với tristearin"}, {"id": "b", "text": "Phân tử tan hoàn toàn trong nước tạo dung dịch"}, {"id": "c", "text": "Phân tử chứa các gốc acid béo không no có nối đôi C=C làm giảm nhiệt độ nóng chảy"}], "correctOptionId": "c", "explanation": "Các liên kết đôi cis-C=C tạo cấu trúc gấp khúc ngăn cản sự xếp chặt các phân tử, làm giảm lực hút van der Waals và hạ nhiệt độ nóng chảy."}]'::jsonb,'["chemistry-12-lipid-triglyceride"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-lipid-reactions',4,'LESSON','Phản ứng thủy phân và hydrogen hóa chất béo','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Thủy phân chất béo trong kiềm: (RCOO)₃C₃H₅ + 3NaOH → 3RCOONa + C₃H₅(OH)₃. Phản ứng hydrogen hóa chất béo lỏng (dầu thực vật) thành chất béo rắn (mỡ nhân tạo) dùng xúc tác Ni, t°: chuyển acid béo không no thành no. Hiện tượng ôi mỡ do liên kết đôi C=C bị oxi hóa chậm bởi oxygen không khí tạo peroxide rồi phân hủy thành aldehyde có mùi khó chịu."]'::jsonb,'["Xà phòng hóa 1 mol tristearin bằng NaOH cần đúng 3 mol NaOH và thu được 1 mol glycerol cùng 3 mol sodium stearate."]'::jsonb,'[{"id": "chemistry-12-lipid-reactions-q1", "prompt": "Xà phòng hóa hoàn toàn 1 mol chất béo triglyceride bằng dung dịch NaOH luôn thu được bao nhiêu mol glycerol?", "difficulty": "EASY", "options": [{"id": "a", "text": "1 mol"}, {"id": "b", "text": "3 mol"}, {"id": "c", "text": "2 mol"}], "correctOptionId": "a", "explanation": "Mỗi phân tử triglyceride liên kết 3 gốc acid với 1 khung glycerol, do đó thủy phân 1 mol chất béo luôn giải phóng đúng 1 mol glycerol."}, {"id": "chemistry-12-lipid-reactions-q2", "prompt": "Quá trình chuyển hóa dầu thực vật (chất béo lỏng) thành bơ nhân tạo (chất béo rắn) trong công nghiệp dựa trên phản ứng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thủy phân chất béo trong môi trường acid loãng"}, {"id": "b", "text": "Oxi hóa cắt mạch hydrocarbon bằng thuốc tím"}, {"id": "c", "text": "Hydrogen hóa chất béo không no có xúc tác nickel ở nhiệt độ cao"}], "correctOptionId": "c", "explanation": "Cộng hydrogen vào các liên kết đôi C=C của gốc acid béo không no chuyển thành gốc acid no có nhiệt độ nóng chảy cao hơn ở thể rắn."}, {"id": "chemistry-12-lipid-reactions-q3", "prompt": "Dầu mỡ động thực vật để lâu ngày trong không khí thường bị ôi thiu và có mùi khét khó chịu. Nguyên nhân hóa học chính là do:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chất béo tự phản ứng với khí nitơ trong khí quyển"}, {"id": "b", "text": "Liên kết đôi C=C của acid béo không no bị oxi không khí oxi hóa chậm thành peroxide rồi phân hủy thành aldehyde"}, {"id": "c", "text": "Glycerol bị bốc hơi hoàn toàn vào không khí"}], "correctOptionId": "b", "explanation": "Sự oxi hóa tự phát các nối đôi C=C bởi oxi tạo các gốc tự do peroxide, phân cắt thành các aldehyde và ketone dễ bay hơi có mùi hôi."}]'::jsonb,'["chemistry-12-lipid-reactions"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-soap-detergent',5,'LESSON','Xà phòng và chất giặt rửa tổng hợp','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Xà phòng là hỗn hợp muối sodium hoặc potassium của các acid béo (như C₁₇H₃₅COONa). Phân tử gồm đầu ưa nước (-COO⁻Na⁺) và đuôi kị nước (gốc hydrocarbon dài ưa dầu). Cơ chế giặt: đuôi kị nước bám vào vết dầu mỡ, đầu ưa nước hướng ra ngoài tạo hạt micelle phân tán vào nước. Chất giặt rửa tổng hợp không bị kết tủa trong nước cứng (chứa Ca²⁺, Mg²⁺)."]'::jsonb,'["Khi rửa tay với xà phòng, các hạt dầu mỡ được bao bọc bởi các phân tử xà phòng và cuốn trôi theo dòng nước xối."]'::jsonb,'[{"id": "chemistry-12-soap-detergent-q1", "prompt": "Muối nào sau đây là thành phần hoạt chất chính trong bánh xà phòng thông thường?", "difficulty": "EASY", "options": [{"id": "a", "text": "Sodium chloride (NaCl)"}, {"id": "b", "text": "Calcium carbonate (CaCO₃)"}, {"id": "c", "text": "Sodium stearate (C₁₇H₃₅COONa)"}], "correctOptionId": "c", "explanation": "Xà phòng là muối sodium hoặc potassium của các acid béo, phổ biến là sodium stearate và sodium palmitate."}, {"id": "chemistry-12-soap-detergent-q2", "prompt": "Cơ chế làm sạch vết bẩn dầu mỡ của xà phòng dựa vào đặc điểm cấu tạo phân tử nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Phân tử đóng vai trò là chất oxi hóa cực mạnh đốt cháy dầu mỡ"}, {"id": "b", "text": "Phân tử gồm một đầu ưa nước tan trong nước và một đuôi kị nước ưa dầu mỡ"}, {"id": "c", "text": "Phân tử có tính acid mạnh hòa tan mọi kim loại"}], "correctOptionId": "b", "explanation": "Đuôi kị nước găm vào giọt dầu mỡ, đầu ưa nước quay ra ngoài nước tạo thành các hạt micelle lơ lửng bị dòng nước cuốn đi."}, {"id": "chemistry-12-soap-detergent-q3", "prompt": "Ưu điểm nổi bật của chất giặt rửa tổng hợp so với xà phòng truyền thống khi sử dụng trong môi trường nước cứng là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Vẫn duy trì khả năng giặt rửa tốt vì muối của chúng với Ca²⁺ và Mg²⁺ không bị kết tủa"}, {"id": "b", "text": "Hoàn toàn không có bọt nên xả nước rất nhanh"}, {"id": "c", "text": "Tự phân hủy thành khí cacbonic ngay sau khi hòa tan"}], "correctOptionId": "a", "explanation": "Xà phòng thông thường tạo kết tủa (RCOO)₂Ca và (RCOO)₂Mg làm mất tác dụng giặt, còn chất giặt rửa tổng hợp (muối sulfonate) tan tốt trong nước cứng."}]'::jsonb,'["chemistry-12-soap-detergent"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-review-1',6,'FIVE_LESSON_REVIEW','Ôn tập 1','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "chemistry-12-ester-structure-q1", "prompt": "Tên gọi theo danh pháp thông thường của ester có công thức cấu tạo thu gọn CH₃COOC₂H₅ là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Ethyl acetate"}, {"id": "b", "text": "Methyl acetate"}, {"id": "c", "text": "Ethyl propionate"}], "correctOptionId": "a", "explanation": "Tên gọi gồm tên gốc ethyl (C₂H₅-) kết hợp với gốc acetate (CH₃COO-), thành ethyl acetate."}, {"id": "chemistry-12-ester-structure-q2", "prompt": "Trong các chất có khối lượng phân tử xấp xỉ nhau sau đây, chất nào có nhiệt độ sôi thấp nhất?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "CH₃COOH (Acetic acid)"}, {"id": "b", "text": "C₃H₇OH (Propan-1-ol)"}, {"id": "c", "text": "HCOOCH₃ (Methyl formate)"}], "correctOptionId": "c", "explanation": "Ester không có nguyên tử hydro linh động liên kết với oxy nên không tạo được liên kết hydro liên phân tử, do đó nhiệt độ sôi thấp hơn hẳn acid và alcohol."}, {"id": "chemistry-12-ester-reactions-q1", "prompt": "Phản ứng thủy phân ester trong dung dịch kiềm đun nóng còn được gọi là phản ứng gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Phản ứng ester hóa"}, {"id": "b", "text": "Phản ứng trùng hợp"}, {"id": "c", "text": "Phản ứng xà phòng hóa"}], "correctOptionId": "c", "explanation": "Thủy phân ester tạo ra muối của acid béo (thành phần xà phòng) nên phản ứng này gọi là phản ứng xà phòng hóa."}, {"id": "chemistry-12-ester-reactions-q2", "prompt": "Đun nóng ethyl formate (HCOOC₂H₅) với dung dịch NaOH vừa đủ thu được các sản phẩm là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "HCOONa và CH₃OH"}, {"id": "b", "text": "HCOONa và C₂H₅OH"}, {"id": "c", "text": "CH₃COONa và CH₃OH"}], "correctOptionId": "b", "explanation": "Phương trình phản ứng: HCOOC₂H₅ + NaOH → HCOONa (sodium formate) + C₂H₅OH (ethanol)."}, {"id": "chemistry-12-lipid-triglyceride-q1", "prompt": "Glycerol (glycerin) là polyalcohol ba chức tham gia cấu tạo nên mọi triglyceride có công thức là:", "difficulty": "EASY", "options": [{"id": "a", "text": "C₃H₇OH"}, {"id": "b", "text": "C₃H₅(OH)₃"}, {"id": "c", "text": "C₂H₄(OH)₂"}], "correctOptionId": "b", "explanation": "Glycerol là propane-1,2,3-triol có 3 nhóm -OH liên kết với 3 nguyên tử carbon: C₃H₅(OH)₃."}, {"id": "chemistry-12-lipid-triglyceride-q2", "prompt": "Acid béo nào sau đây là acid béo no phổ biến trong mỡ động vật?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Acid stearic (C₁₇H₃₅COOH)"}, {"id": "b", "text": "Acid oleic (C₁₇H₃₃COOH)"}, {"id": "c", "text": "Acid linoleic (C₁₇H₃₁COOH)"}], "correctOptionId": "a", "explanation": "Acid stearic có gốc hydrocarbon C₁₇H₃₅- no (dạng C_n H_2n+1) nên là acid béo no."}, {"id": "chemistry-12-lipid-reactions-q1", "prompt": "Xà phòng hóa hoàn toàn 1 mol chất béo triglyceride bằng dung dịch NaOH luôn thu được bao nhiêu mol glycerol?", "difficulty": "EASY", "options": [{"id": "a", "text": "1 mol"}, {"id": "b", "text": "3 mol"}, {"id": "c", "text": "2 mol"}], "correctOptionId": "a", "explanation": "Mỗi phân tử triglyceride liên kết 3 gốc acid với 1 khung glycerol, do đó thủy phân 1 mol chất béo luôn giải phóng đúng 1 mol glycerol."}, {"id": "chemistry-12-lipid-reactions-q2", "prompt": "Quá trình chuyển hóa dầu thực vật (chất béo lỏng) thành bơ nhân tạo (chất béo rắn) trong công nghiệp dựa trên phản ứng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thủy phân chất béo trong môi trường acid loãng"}, {"id": "b", "text": "Oxi hóa cắt mạch hydrocarbon bằng thuốc tím"}, {"id": "c", "text": "Hydrogen hóa chất béo không no có xúc tác nickel ở nhiệt độ cao"}], "correctOptionId": "c", "explanation": "Cộng hydrogen vào các liên kết đôi C=C của gốc acid béo không no chuyển thành gốc acid no có nhiệt độ nóng chảy cao hơn ở thể rắn."}, {"id": "chemistry-12-soap-detergent-q1", "prompt": "Muối nào sau đây là thành phần hoạt chất chính trong bánh xà phòng thông thường?", "difficulty": "EASY", "options": [{"id": "a", "text": "Sodium chloride (NaCl)"}, {"id": "b", "text": "Calcium carbonate (CaCO₃)"}, {"id": "c", "text": "Sodium stearate (C₁₇H₃₅COONa)"}], "correctOptionId": "c", "explanation": "Xà phòng là muối sodium hoặc potassium của các acid béo, phổ biến là sodium stearate và sodium palmitate."}, {"id": "chemistry-12-soap-detergent-q2", "prompt": "Cơ chế làm sạch vết bẩn dầu mỡ của xà phòng dựa vào đặc điểm cấu tạo phân tử nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Phân tử đóng vai trò là chất oxi hóa cực mạnh đốt cháy dầu mỡ"}, {"id": "b", "text": "Phân tử gồm một đầu ưa nước tan trong nước và một đuôi kị nước ưa dầu mỡ"}, {"id": "c", "text": "Phân tử có tính acid mạnh hòa tan mọi kim loại"}], "correctOptionId": "b", "explanation": "Đuôi kị nước găm vào giọt dầu mỡ, đầu ưa nước quay ra ngoài nước tạo thành các hạt micelle lơ lửng bị dòng nước cuốn đi."}]'::jsonb,'["chemistry-12-ester-structure", "chemistry-12-ester-reactions", "chemistry-12-lipid-triglyceride", "chemistry-12-lipid-reactions", "chemistry-12-soap-detergent"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-carbohydrate-classification',7,'LESSON','Phân loại carbohydrate và cấu trúc Glucose, Fructose','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Carbohydrate chia thành 3 nhóm: Monosaccharide (glucose, fructose C₆H₁₂O₆ không bị thủy phân); Disaccharide (saccharose, maltose C₁₂H₂₂O₁₁ thủy phân ra 2 monosaccharide); Polysaccharide (tinh bột, cellulose (C₆H₁₀O₅)_n thủy phân ra nhiều glucose). Glucose là polyhydroxyaldehyde; Fructose là polyhydroxyketone. Trong dung dịch, glucose chủ yếu tồn tại ở dạng mạch vòng α và β."]'::jsonb,'["Glucose có trong máu người với nồng độ ổn định khoảng 0,1% (khoảng 4,4 - 7,2 mmol/L)."]'::jsonb,'[{"id": "chemistry-12-carbohydrate-classification-q1", "prompt": "Chất nào sau đây thuộc loại monosaccharide không bị thủy phân?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tinh bột"}, {"id": "b", "text": "Glucose"}, {"id": "c", "text": "Saccharose"}], "correctOptionId": "b", "explanation": "Monosaccharide là carbohydrate đơn giản nhất không thể bị thủy phân thành đường nhỏ hơn, ví dụ glucose và fructose."}, {"id": "chemistry-12-carbohydrate-classification-q2", "prompt": "Glucose và fructose là hai chất:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đồng phân cấu tạo của nhau có cùng công thức phân tử C₆H₁₂O₆"}, {"id": "b", "text": "Đồng đẳng kế tiếp nhau trong cùng dãy đồng đẳng"}, {"id": "c", "text": "Thuộc hai loại đường disaccharide khác nhau"}], "correctOptionId": "a", "explanation": "Cả glucose và fructose đều có công thức phân tử C₆H₁₂O₆ nhưng glucose chứa nhóm -CHO còn fructose chứa nhóm >C=O, nên là đồng phân."}, {"id": "chemistry-12-carbohydrate-classification-q3", "prompt": "Trong dung dịch nước ở trạng thái cân bằng, các phân tử glucose chủ yếu tồn tại ở dạng cấu trúc nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Dạng mạch hở thẳng chiếm trên 99%"}, {"id": "b", "text": "Dạng phân tử bị phân li hoàn toàn thành các ion"}, {"id": "c", "text": "Dạng mạch vòng 6 cạnh (dạng α-glucose và β-glucose)"}], "correctOptionId": "c", "explanation": "Trong dung dịch, nhóm -OH ở C5 cộng đóng vòng với nhóm -CHO ở C1 tạo vòng bán axetal 6 cạnh, chỉ dưới 0,1% ở dạng mạch hở."}]'::jsonb,'["chemistry-12-carbohydrate-classification"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-glucose-fructose-reactions',8,'LESSON','Tính chất hóa học của Glucose và Fructose','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Nhóm polyalcohol: glucose hòa tan Cu(OH)₂ ở nhiệt độ thường tạo phức chất xanh lam thẫm. Nhóm aldehyde (-CHO): glucose tham gia phản ứng tráng bạc với [Ag(NH₃)₂]OH (tạo 2 Ag), làm mất màu dung dịch nước bromine, và khử Cu(OH)₂ đun nóng tạo kết tủa Cu₂O đỏ gạch. Fructose không có nhóm -CHO nhưng trong môi trường kiềm chuyển hóa thành glucose nên cũng tráng bạc."]'::jsonb,'["1 mol glucose tráng bạc hoàn toàn giải phóng 2 mol Ag kim loại sáng bóng bám lên thành ống nghiệm."]'::jsonb,'[{"id": "chemistry-12-glucose-fructose-reactions-q1", "prompt": "Thuốc thử được dùng để nhận biết dung dịch glucose tạo dung dịch phức chất màu xanh lam thẫm ở nhiệt độ thường là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Cu(OH)₂ trong môi trường kiềm"}, {"id": "b", "text": "Dung dịch AgNO₃ trong NH₃"}, {"id": "c", "text": "Dung dịch nước vôi trong Ca(OH)₂"}], "correctOptionId": "a", "explanation": "Vì glucose có nhiều nhóm -OH liền kề (polyalcohol) nên hòa tan Cu(OH)₂ ở nhiệt độ thường tạo dung dịch màu xanh lam thẫm."}, {"id": "chemistry-12-glucose-fructose-reactions-q2", "prompt": "Cho 1 mol glucose tham gia phản ứng tráng bạc hoàn toàn với dung dịch AgNO₃ trong NH₃ dư, lượng Ag kim loại kết tủa thu được tối đa là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "1 mol"}, {"id": "b", "text": "4 mol"}, {"id": "c", "text": "2 mol"}], "correctOptionId": "c", "explanation": "Phân tử glucose có 1 nhóm aldehyde -CHO, theo phương trình phản ứng tráng bạc: 1 mol -CHO giải phóng 2 mol Ag kim loại."}, {"id": "chemistry-12-glucose-fructose-reactions-q3", "prompt": "Để phân biệt dung dịch glucose và dung dịch fructose trong phòng thí nghiệm, người ta thường dùng thuốc thử nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Cu(OH)₂ đun nóng"}, {"id": "b", "text": "Nước bromine (nước brom)"}, {"id": "c", "text": "Dung dịch AgNO₃ trong NH₃"}], "correctOptionId": "b", "explanation": "Glucose có nhóm -CHO khử được nước brom làm mất màu, trong khi fructose là ketone không làm mất màu nước brom trong môi trường acid."}]'::jsonb,'["chemistry-12-glucose-fructose-reactions"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-sucrose-maltose',9,'LESSON','Saccharose và Maltose','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Saccharose (đường mía, C₁₂H₂₂O₁₁) gồm 1 gốc α-glucose liên kết với 1 gốc β-fructose qua liên kết α-1,2-glycosidic. Do không còn nhóm -CHO tự do nên saccharose không có tính khử (không tráng bạc, không mất màu nước brom). Khi thủy phân có xúc tác acid hoặc enzyme, 1 mol saccharose tạo 1 mol glucose và 1 mol fructose."]'::jsonb,'["Đường kính trắng sử dụng hàng ngày có độ tinh khiết cao với thành phần chính là saccharose chiết xuất từ mía đường."]'::jsonb,'[{"id": "chemistry-12-sucrose-maltose-q1", "prompt": "Đường mía, đường củ cải dùng làm chất tạo ngọt trong đời sống hàng ngày có thành phần chính là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Glucose"}, {"id": "b", "text": "Maltose"}, {"id": "c", "text": "Saccharose"}], "correctOptionId": "c", "explanation": "Saccharose là disaccharide phổ biến nhất, được sản xuất công nghiệp từ cây mía hoặc củ cải đường."}, {"id": "chemistry-12-sucrose-maltose-q2", "prompt": "Khi thủy phân hoàn toàn 1 mol saccharose trong môi trường acid đun nóng, ta thu được sản phẩm gồm:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2 mol fructose"}, {"id": "b", "text": "1 mol glucose và 1 mol fructose"}, {"id": "c", "text": "2 mol glucose"}], "correctOptionId": "b", "explanation": "Phân tử saccharose được cấu tạo từ 1 gốc glucose và 1 gốc fructose, khi thủy phân phân cắt liên kết glycosidic tạo tỉ lệ mol 1:1."}, {"id": "chemistry-12-sucrose-maltose-q3", "prompt": "Dung dịch saccharose tinh khiết có tham gia phản ứng tráng bạc không? Vì sao?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Không, vì phân tử không còn nhóm aldehyde (-CHO) dạng mạch hở tự do"}, {"id": "b", "text": "Có, vì phân tử có khối lượng lớn hơn glucose"}, {"id": "c", "text": "Có, vì phân tử chứa nhiều nhóm hydroxy (-OH)"}], "correctOptionId": "a", "explanation": "Hai gốc monosaccharide liên kết với nhau qua hai nguyên tử C anomer của cả hai nhóm carbonyl, khóa kín vòng nên không mở mạch tạo nhóm -CHO được."}]'::jsonb,'["chemistry-12-sucrose-maltose"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-starch',10,'LESSON','Cấu trúc và tính chất của Tinh bột','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Tinh bột là polysaccharide ((C₆H₁₀O₅)_n) gồm hai thành phần: amylose (20-30%, mạch dài không phân nhánh, xoắn ốc liên kết α-1,4-glycosidic) và amylopectin (70-80%, cấu trúc phân nhánh liên kết α-1,4 và α-1,6-glycosidic). Tác dụng đặc trưng: hồ tinh bột tác dụng với dung dịch iodine cho hợp chất màu xanh tím (mất màu khi đun nóng, xuất hiện lại khi để nguội)."]'::jsonb,'["Nhỏ một giọt dung dịch cồn iodine lên lát cắt củ khoai tây, vị trí tiếp xúc lập tức chuyển sang màu xanh tím đậm."]'::jsonb,'[{"id": "chemistry-12-starch-q1", "prompt": "Thuốc thử đặc trưng dùng để nhận biết hồ tinh bột bằng phản ứng tạo màu xanh tím là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Dung dịch AgNO₃/NH₃"}, {"id": "b", "text": "Dung dịch iodine (I₂)"}, {"id": "c", "text": "Dung dịch Cu(OH)₂"}], "correctOptionId": "b", "explanation": "Cấu trúc xoắn ốc của amylose tạo các khoang rỗng hấp phụ phân tử iodine tạo phức chất có màu xanh tím đặc trưng."}, {"id": "chemistry-12-starch-q2", "prompt": "Điểm khác biệt cơ bản về mặt cấu trúc giữa amylose và amylopectin trong hạt tinh bột là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Amylose có cấu trúc mạch không phân nhánh, còn amylopectin có cấu trúc mạch phân nhánh"}, {"id": "b", "text": "Amylose là đường đơn, còn amylopectin là đường đôi"}, {"id": "c", "text": "Amylose có liên kết peptide, còn amylopectin có liên kết ester"}], "correctOptionId": "a", "explanation": "Amylose gồm các gốc α-glucose liên kết α-1,4 mạch thẳng xoắn; amylopectin có thêm các nhánh tại vị trí liên kết α-1,6-glycosidic."}, {"id": "chemistry-12-starch-q3", "prompt": "Phương trình hóa học tổng quát biểu diễn quá trình quang hợp của cây xanh tạo ra tinh bột dưới tác dụng của ánh sáng mặt trời là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "n CO₂ + n H₂O → (CH₂O)n + n O₂"}, {"id": "b", "text": "6 CO₂ + 6 H₂O → C₆H₁₂O₆ + 6 O₂"}, {"id": "c", "text": "6n CO₂ + 5n H₂O → (C₆H₁₀O₅)n + 6n O₂ (xúc tác ánh sáng, diệp lục)"}], "correctOptionId": "c", "explanation": "Quá trình quang hợp của diệp lục hấp thụ năng lượng mặt trời chuyển hóa CO₂ và H₂O thành tinh bột (C₆H₁₀O₅)_n và giải phóng oxy O₂."}]'::jsonb,'["chemistry-12-starch"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-cellulose',11,'LESSON','Cấu tạo, tính chất và ứng dụng của Cellulose','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Cellulose ((C₆H₁₀O₅)_n hay [C₆H₇O₂(OH)₃]_n) là thành phần chính tạo nên màng tế bào thực vật (gỗ, bông gòn). Cấu tạo từ các gốc β-glucose liên kết β-1,4-glycosidic tạo mạch kéo dài không phân nhánh. Cellulose không tan trong nước và dung môi hữu cơ thường; tan trong nước Schweizer ([Cu(NH₃)₄](OH)₂). Tác dụng với HNO₃ đặc có H₂SO₄ đặc làm xúc tác tạo cellulose trinitrate dùng làm thuốc súng không khói."]'::jsonb,'["Sợi bông nõn chứa gần 98% cellulose tinh khiết, dùng làm sợi dệt vải may mặc."]'::jsonb,'[{"id": "chemistry-12-cellulose-q1", "prompt": "Trong công thức cấu tạo thu gọn [C₆H₇O₂(OH)₃]_n của cellulose, mỗi mắt xích C₆H₁₀O₅ chứa bao nhiêu nhóm hydroxy (-OH) tự do?", "difficulty": "EASY", "options": [{"id": "a", "text": "3 nhóm -OH"}, {"id": "b", "text": "2 nhóm -OH"}, {"id": "c", "text": "5 nhóm -OH"}], "correctOptionId": "a", "explanation": "Mỗi mắt xích glucose trong mạch cellulose còn giữ lại đúng 3 nhóm alcohol tự do: [C₆H₇O₂(OH)₃]_n."}, {"id": "chemistry-12-cellulose-q2", "prompt": "Sản phẩm thu được khi cho cellulose phản ứng hoàn toàn với hỗn hợp acid nitric đặc và acid sulfuric đặc làm thuốc súng không khói là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cellulose triacetate"}, {"id": "b", "text": "Trinitrotoluene (TNT)"}, {"id": "c", "text": "Cellulose trinitrate"}], "correctOptionId": "c", "explanation": "Ba nhóm -OH trong mỗi mắt xích bị ester hóa bởi HNO₃ tạo [C₆H₇O₂(ONO₂)₃]_n (cellulose trinitrate), một chất nổ mạnh không khói."}, {"id": "chemistry-12-cellulose-q3", "prompt": "Động vật ăn cỏ như trâu bò tiêu hóa được cỏ (chứa nhiều cellulose) nhưng con người thì không thể tiêu hóa được vì hệ tiêu hóa của người thiếu:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Enzyme amylase trong tuyến nước bọt"}, {"id": "b", "text": "Enzyme cellulase để phân cắt liên kết β-1,4-glycosidic"}, {"id": "c", "text": "Acid clohydric HCl trong dịch vị dạ dày"}], "correctOptionId": "b", "explanation": "Liên kết β-1,4-glycosidic rất bền và đòi hỏi enzyme chuyên biệt cellulase (do vi sinh vật cộng sinh trong dạ cỏ động vật nhai lại tiết ra)."}]'::jsonb,'["chemistry-12-cellulose"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-review-2',12,'FIVE_LESSON_REVIEW','Ôn tập 2','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "chemistry-12-carbohydrate-classification-q1", "prompt": "Chất nào sau đây thuộc loại monosaccharide không bị thủy phân?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tinh bột"}, {"id": "b", "text": "Glucose"}, {"id": "c", "text": "Saccharose"}], "correctOptionId": "b", "explanation": "Monosaccharide là carbohydrate đơn giản nhất không thể bị thủy phân thành đường nhỏ hơn, ví dụ glucose và fructose."}, {"id": "chemistry-12-carbohydrate-classification-q2", "prompt": "Glucose và fructose là hai chất:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đồng phân cấu tạo của nhau có cùng công thức phân tử C₆H₁₂O₆"}, {"id": "b", "text": "Đồng đẳng kế tiếp nhau trong cùng dãy đồng đẳng"}, {"id": "c", "text": "Thuộc hai loại đường disaccharide khác nhau"}], "correctOptionId": "a", "explanation": "Cả glucose và fructose đều có công thức phân tử C₆H₁₂O₆ nhưng glucose chứa nhóm -CHO còn fructose chứa nhóm >C=O, nên là đồng phân."}, {"id": "chemistry-12-glucose-fructose-reactions-q1", "prompt": "Thuốc thử được dùng để nhận biết dung dịch glucose tạo dung dịch phức chất màu xanh lam thẫm ở nhiệt độ thường là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Cu(OH)₂ trong môi trường kiềm"}, {"id": "b", "text": "Dung dịch AgNO₃ trong NH₃"}, {"id": "c", "text": "Dung dịch nước vôi trong Ca(OH)₂"}], "correctOptionId": "a", "explanation": "Vì glucose có nhiều nhóm -OH liền kề (polyalcohol) nên hòa tan Cu(OH)₂ ở nhiệt độ thường tạo dung dịch màu xanh lam thẫm."}, {"id": "chemistry-12-glucose-fructose-reactions-q2", "prompt": "Cho 1 mol glucose tham gia phản ứng tráng bạc hoàn toàn với dung dịch AgNO₃ trong NH₃ dư, lượng Ag kim loại kết tủa thu được tối đa là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "1 mol"}, {"id": "b", "text": "4 mol"}, {"id": "c", "text": "2 mol"}], "correctOptionId": "c", "explanation": "Phân tử glucose có 1 nhóm aldehyde -CHO, theo phương trình phản ứng tráng bạc: 1 mol -CHO giải phóng 2 mol Ag kim loại."}, {"id": "chemistry-12-sucrose-maltose-q1", "prompt": "Đường mía, đường củ cải dùng làm chất tạo ngọt trong đời sống hàng ngày có thành phần chính là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Glucose"}, {"id": "b", "text": "Maltose"}, {"id": "c", "text": "Saccharose"}], "correctOptionId": "c", "explanation": "Saccharose là disaccharide phổ biến nhất, được sản xuất công nghiệp từ cây mía hoặc củ cải đường."}, {"id": "chemistry-12-sucrose-maltose-q2", "prompt": "Khi thủy phân hoàn toàn 1 mol saccharose trong môi trường acid đun nóng, ta thu được sản phẩm gồm:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "2 mol fructose"}, {"id": "b", "text": "1 mol glucose và 1 mol fructose"}, {"id": "c", "text": "2 mol glucose"}], "correctOptionId": "b", "explanation": "Phân tử saccharose được cấu tạo từ 1 gốc glucose và 1 gốc fructose, khi thủy phân phân cắt liên kết glycosidic tạo tỉ lệ mol 1:1."}, {"id": "chemistry-12-starch-q1", "prompt": "Thuốc thử đặc trưng dùng để nhận biết hồ tinh bột bằng phản ứng tạo màu xanh tím là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Dung dịch AgNO₃/NH₃"}, {"id": "b", "text": "Dung dịch iodine (I₂)"}, {"id": "c", "text": "Dung dịch Cu(OH)₂"}], "correctOptionId": "b", "explanation": "Cấu trúc xoắn ốc của amylose tạo các khoang rỗng hấp phụ phân tử iodine tạo phức chất có màu xanh tím đặc trưng."}, {"id": "chemistry-12-starch-q2", "prompt": "Điểm khác biệt cơ bản về mặt cấu trúc giữa amylose và amylopectin trong hạt tinh bột là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Amylose có cấu trúc mạch không phân nhánh, còn amylopectin có cấu trúc mạch phân nhánh"}, {"id": "b", "text": "Amylose là đường đơn, còn amylopectin là đường đôi"}, {"id": "c", "text": "Amylose có liên kết peptide, còn amylopectin có liên kết ester"}], "correctOptionId": "a", "explanation": "Amylose gồm các gốc α-glucose liên kết α-1,4 mạch thẳng xoắn; amylopectin có thêm các nhánh tại vị trí liên kết α-1,6-glycosidic."}, {"id": "chemistry-12-cellulose-q1", "prompt": "Trong công thức cấu tạo thu gọn [C₆H₇O₂(OH)₃]_n của cellulose, mỗi mắt xích C₆H₁₀O₅ chứa bao nhiêu nhóm hydroxy (-OH) tự do?", "difficulty": "EASY", "options": [{"id": "a", "text": "3 nhóm -OH"}, {"id": "b", "text": "2 nhóm -OH"}, {"id": "c", "text": "5 nhóm -OH"}], "correctOptionId": "a", "explanation": "Mỗi mắt xích glucose trong mạch cellulose còn giữ lại đúng 3 nhóm alcohol tự do: [C₆H₇O₂(OH)₃]_n."}, {"id": "chemistry-12-cellulose-q2", "prompt": "Sản phẩm thu được khi cho cellulose phản ứng hoàn toàn với hỗn hợp acid nitric đặc và acid sulfuric đặc làm thuốc súng không khói là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cellulose triacetate"}, {"id": "b", "text": "Trinitrotoluene (TNT)"}, {"id": "c", "text": "Cellulose trinitrate"}], "correctOptionId": "c", "explanation": "Ba nhóm -OH trong mỗi mắt xích bị ester hóa bởi HNO₃ tạo [C₆H₇O₂(ONO₂)₃]_n (cellulose trinitrate), một chất nổ mạnh không khói."}]'::jsonb,'["chemistry-12-carbohydrate-classification", "chemistry-12-glucose-fructose-reactions", "chemistry-12-sucrose-maltose", "chemistry-12-starch", "chemistry-12-cellulose"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-amines',13,'LESSON','Cấu tạo, bậc amine và tính bazơ','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Amine là hợp chất hình thành khi thay thế nguyên tử H trong NH₃ bằng gốc hydrocarbon. Bậc của amine là số gốc hydrocarbon liên kết với nguyên tử N (bậc 1: RNH₂, bậc 2: R₁R₂NH, bậc 3: R₁R₂R₃N). Tính base: do đôi electron tự do trên nguyên tử N: CH₃NH₂ > NH₃ > C₆H₅NH₂ (aniline). Aniline tạo kết tủa trắng với dung dịch nước bromine."]'::jsonb,'["Methylamine (CH₃NH₂) là chất khí có mùi khai tương tự amoniac, làm quỳ tím ẩm hóa xanh."]'::jsonb,'[{"id": "chemistry-12-amines-q1", "prompt": "Hợp chất methylamine có công thức CH₃NH₂ thuộc loại amine bậc mấy?", "difficulty": "EASY", "options": [{"id": "a", "text": "Amine bậc 2"}, {"id": "b", "text": "Amine bậc 3"}, {"id": "c", "text": "Amine bậc 1"}], "correctOptionId": "c", "explanation": "Bậc của amine tính bằng số nguyên tử H trong NH₃ được thay thế bằng gốc hydrocarbon. CH₃NH₂ có 1 gốc CH₃- nên là amine bậc 1."}, {"id": "chemistry-12-amines-q2", "prompt": "Dãy sắp xếp các chất theo thứ tự lực base giảm dần từ trái sang phải là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "NH₃ > CH₃NH₂ > C₆H₅NH₂"}, {"id": "b", "text": "CH₃NH₂ > NH₃ > C₆H₅NH₂ (aniline)"}, {"id": "c", "text": "C₆H₅NH₂ > NH₃ > CH₃NH₂"}], "correctOptionId": "b", "explanation": "Gốc alkyl -CH₃ đẩy electron làm tăng mật độ điện tích trên N (tính base mạnh hơn NH₃); vòng phenyl -C₆H₅ hút electron làm giảm mật độ trên N (tính base yếu hơn NH₃)."}, {"id": "chemistry-12-amines-q3", "prompt": "Để khử mùi tanh của cá mè do các amine bay hơi (như trimethylamine) gây ra, người nội trợ thường dùng biện pháp dân gian nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Rửa cá bằng giấm ăn hoặc nước cốt chanh"}, {"id": "b", "text": "Ngâm cá trong nước muối thật mặn"}, {"id": "c", "text": "Rửa cá bằng nước xà phòng kiềm"}], "correctOptionId": "a", "explanation": "Acid acetic trong giấm hoặc acid citric trong chanh phản ứng với các amine tạo thành muối tan không bay hơi, làm mất mùi tanh."}]'::jsonb,'["chemistry-12-amines"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-amino-acids',14,'LESSON','Cấu trúc và tính chất lưỡng tính của Amino acid','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Amino acid là hợp chất hữu cơ tạp chức chứa đồng thời nhóm amino (-NH₂) và carboxyl (-COOH). Tồn tại chủ yếu dưới dạng ion lưỡng cực: H₃N⁺-CH(R)-COO⁻ (dạng tinh thể, nhiệt độ nóng chảy cao, tan tốt trong nước). Tính chất lưỡng tính: phản ứng với cả acid mạnh và base mạnh."]'::jsonb,'["Glycine (H₂N-CH₂-COOH) phản ứng với HCl tạo Cl⁻H₃N⁺-CH₂-COOH và phản ứng với NaOH tạo H₂N-CH₂-COONa + H₂O."]'::jsonb,'[{"id": "chemistry-12-amino-acids-q1", "prompt": "Amino acid đơn giản nhất có tên gọi là glycine có công thức cấu tạo là:", "difficulty": "EASY", "options": [{"id": "a", "text": "H₂N-CH₂-CH₂-COOH"}, {"id": "b", "text": "H₂N-CH₂-COOH"}, {"id": "c", "text": "CH₃-CH(NH₂)-COOH"}], "correctOptionId": "b", "explanation": "Glycine (acid aminoacetic) có phân tử khối bằng 75, công thức H₂N-CH₂-COOH."}, {"id": "chemistry-12-amino-acids-q2", "prompt": "Ở trạng thái tinh thể và trong dung dịch nước, phân tử amino acid tồn tại chủ yếu ở dạng cấu trúc nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ion lưỡng cực (muối nội phân tử H₃N⁺-CH(R)-COO⁻)"}, {"id": "b", "text": "Dạng phân tử trung hòa H₂N-CH(R)-COOH"}, {"id": "c", "text": "Dạng cation mang điện tích dương hoàn toàn"}], "correctOptionId": "a", "explanation": "Nhóm -COOH có tính acid nhường H⁺ cho nhóm -NH₂ có tính base ngay trong phân tử, tạo dạng ion lưỡng cực bền vững."}, {"id": "chemistry-12-amino-acids-q3", "prompt": "Amino acid có tính chất lưỡng tính vì nguyên nhân cấu tạo nào sau đây?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Phân tử có chứa vòng thơm benzene"}, {"id": "b", "text": "Phân tử có khả năng hòa tan vô hạn trong các dung môi hữu cơ"}, {"id": "c", "text": "Phân tử chứa đồng thời nhóm carboxyl mang tính acid và nhóm amino mang tính base"}], "correctOptionId": "c", "explanation": "Nhóm -NH₂ nhận proton (phản ứng với acid), nhóm -COOH nhường proton (phản ứng với base), tạo nên tính chất lưỡng tính đặc trưng."}]'::jsonb,'["chemistry-12-amino-acids"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-peptides-proteins',15,'LESSON','Peptide và Protein','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Liên kết peptide là liên kết -CO-NH- giữa hai đơn vị α-amino acid. Chuỗi peptide từ 2 đến 50 đơn vị; protein là polypeptide cao phân tử từ trên 50 đơn vị. Phản ứng màu biuret: peptide chứa từ 2 liên kết peptide trở lên (tripeptide trở lên) tác dụng Cu(OH)₂ tạo phức chất màu tím. Protein bị đông tụ dưới tác dụng của nhiệt độ, acid, kiềm hoặc ion kim loại nặng."]'::jsonb,'["Nấu canh cua, thịt cua nổi lên từng mảng (riêu cua) là hiện tượng đông tụ protein dưới tác dụng của nhiệt độ."]'::jsonb,'[{"id": "chemistry-12-peptides-proteins-q1", "prompt": "Liên kết hóa học giữa nhóm -CO- và nhóm -NH- của hai đơn vị α-amino acid được gọi là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Liên kết peptide"}, {"id": "b", "text": "Liên kết glycosidic"}, {"id": "c", "text": "Liên kết ester"}], "correctOptionId": "a", "explanation": "Định nghĩa liên kết peptide là liên kết amide tạo bởi nhóm carboxyl của α-amino acid này với nhóm amino của α-amino acid kia."}, {"id": "chemistry-12-peptides-proteins-q2", "prompt": "Hợp chất nào sau đây tham gia phản ứng màu biuret với Cu(OH)₂ trong môi trường kiềm tạo dung dịch màu tím đặc trưng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Dipeptide"}, {"id": "b", "text": "Monosaccharide"}, {"id": "c", "text": "Tripeptide trở lên và protein"}], "correctOptionId": "c", "explanation": "Điều kiện của phản ứng màu biuret là phân tử phải có từ 2 liên kết peptide trở lên, tức từ tripeptide trở lên."}, {"id": "chemistry-12-peptides-proteins-q3", "prompt": "Hiện tượng riêu cua nổi lên khi đun sôi nước canh cua đồng hoặc lòng trắng trứng đông cứng khi luộc là do:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Phản ứng thủy phân hoàn toàn protein thành amino acid"}, {"id": "b", "text": "Sự đông tụ của protein dưới tác dụng của nhiệt độ cao"}, {"id": "c", "text": "Sự bay hơi của các phân tử nước trong dung dịch"}], "correctOptionId": "b", "explanation": "Nhiệt độ cao làm phá vỡ các liên kết hydro và tương tác bậc cao trong cấu trúc protein, làm mạch duỗi ra và kết tụ lại thành khối rắn."}]'::jsonb,'["chemistry-12-peptides-proteins"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-polymer-basics',16,'LESSON','Đại cương về polymer','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Polymer là hợp chất có phân tử khối rất lớn gồm nhiều mắt xích monomer lặp lại. Phản ứng trùng hợp: kết hợp nhiều monomer có liên kết đôi C=C hoặc vòng kém bền thành polymer mà không giải phóng phân tử nhỏ. Phản ứng trùng ngưng: kết hợp nhiều monomer có ít nhất 2 nhóm chức hoạt động thành polymer đồng thời giải phóng các phân tử nhỏ (như H₂O)."]'::jsonb,'["Trùng hợp ethylene tạo polyethylene (PE): n CH₂=CH₂ → (-CH₂-CH₂-)_n."]'::jsonb,'[{"id": "chemistry-12-polymer-basics-q1", "prompt": "Phản ứng kết hợp nhiều phân tử nhỏ (monomer) giống nhau hay tương tự nhau thành phân tử lớn (polymer) gọi là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Phản ứng xà phòng hóa"}, {"id": "b", "text": "Phản ứng este hóa"}, {"id": "c", "text": "Phản ứng trùng hợp"}], "correctOptionId": "c", "explanation": "Định nghĩa phản ứng trùng hợp là quá trình cộng hợp liên tiếp nhiều phân tử nhỏ thành phân tử có khối lượng phân tử rất lớn."}, {"id": "chemistry-12-polymer-basics-q2", "prompt": "Polyethylene (PE) là vật liệu polymer thông dụng được tổng hợp bằng phản ứng trùng hợp monomer nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Vinyl chloride (CH₂=CH-Cl)"}, {"id": "b", "text": "Ethylene (CH₂=CH₂)"}, {"id": "c", "text": "Propylene (CH₂=CH-CH₃)"}], "correctOptionId": "b", "explanation": "Polyethylene được tạo ra từ phản ứng trùng hợp khí ethylene dưới áp suất và xúc tác thích hợp: n CH₂=CH₂ → (-CH₂-CH₂-)_n."}, {"id": "chemistry-12-polymer-basics-q3", "prompt": "Tiêu chí then chốt để phân biệt phản ứng trùng hợp và phản ứng trùng ngưng là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Trùng hợp không giải phóng phân tử nhỏ, còn trùng ngưng có giải phóng phân tử nhỏ (như H₂O)"}, {"id": "b", "text": "Trùng hợp chỉ diễn ra ở nhiệt độ phòng"}, {"id": "c", "text": "Trùng ngưng không tạo ra liên kết hóa học giữa các mắt xích"}], "correctOptionId": "a", "explanation": "Phản ứng trùng ngưng kèm theo sự tách ra các phân tử nhỏ (như nước, amoniac) từ các nhóm chức tương tác, còn trùng hợp là phản ứng cộng hợp hoàn toàn."}]'::jsonb,'["chemistry-12-polymer-basics"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-polymer-materials',17,'LESSON','Một số vật liệu polymer thông dụng','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Chất dẻo: PE, PVC (ống dẫn nước), PS, Teflon (chống dính chảo). Tơ tổng hợp: nylon-6,6 (trùng ngưng hexamethylenediamine và adipic acid, tơ polyamide), tơ nitron/olon (trùng hợp vinyl cyanide). Cao su: cao su buna, cao su lưu hóa (tạo cầu nối -S-S- tăng đàn hồi và chịu nhiệt). Keo dán: keo dán epoxy, keo dán urea-formaldehyde."]'::jsonb,'["Chảo chống dính được tráng một lớp mỏng polymer Teflon (-CF₂-CF₂-)_n có độ bền nhiệt và tính trơ hóa học rất cao."]'::jsonb,'[{"id": "chemistry-12-polymer-materials-q1", "prompt": "Vật liệu polymer nào sau đây được phủ lên bề mặt chảo chống dính nhờ độ bền nhiệt cao và tính trơ hóa học tuyệt vời?", "difficulty": "EASY", "options": [{"id": "a", "text": "Polyethylene (PE)"}, {"id": "b", "text": "Teflon (polytetrafluoroethylene)"}, {"id": "c", "text": "Polyvinyl chloride (PVC)"}], "correctOptionId": "b", "explanation": "Teflon (-CF₂-CF₂-)_n có liên kết C-F rất bền vững, không phản ứng với dầu mỡ ở nhiệt độ nấu nướng và có hệ số ma sát cực thấp."}, {"id": "chemistry-12-polymer-materials-q2", "prompt": "Tơ nylon-6,6 là một loại tơ tổng hợp thuộc phân loại tơ nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tơ polyamide"}, {"id": "b", "text": "Tơ polyester"}, {"id": "c", "text": "Tơ bán tổng hợp (tơ nhân tạo)"}], "correctOptionId": "a", "explanation": "Nylon-6,6 được điều chế từ hexamethylenediamine và adipic acid, chứa các liên kết amide -CO-NH- lặp lại nên là tơ polyamide."}, {"id": "chemistry-12-polymer-materials-q3", "prompt": "Mục đích chính của quá trình lưu hóa cao su thiên nhiên bằng lưu huỳnh trong công nghiệp sản xuất lốp xe là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Làm cao su tan hoàn toàn trong nước để dễ đúc khuôn"}, {"id": "b", "text": "Biến cao su thành chất dẻo nhiệt mềm ở nhiệt độ cao"}, {"id": "c", "text": "Tạo các cầu nối disulfide (-S-S-) nối các mạch polymer thành mạng không gian giúp tăng tính đàn hồi và chịu mài mòn"}], "correctOptionId": "c", "explanation": "Cầu nối -S-S- liên kết các mạch phân tử cao su riêng lẻ thành mạng lưới không gian ba chiều, hạn chế biến dạng vĩnh viễn và tăng độ bền cơ nhiệt."}]'::jsonb,'["chemistry-12-polymer-materials"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-review-3',18,'FIVE_LESSON_REVIEW','Ôn tập 3','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "chemistry-12-amines-q1", "prompt": "Hợp chất methylamine có công thức CH₃NH₂ thuộc loại amine bậc mấy?", "difficulty": "EASY", "options": [{"id": "a", "text": "Amine bậc 2"}, {"id": "b", "text": "Amine bậc 3"}, {"id": "c", "text": "Amine bậc 1"}], "correctOptionId": "c", "explanation": "Bậc của amine tính bằng số nguyên tử H trong NH₃ được thay thế bằng gốc hydrocarbon. CH₃NH₂ có 1 gốc CH₃- nên là amine bậc 1."}, {"id": "chemistry-12-amines-q2", "prompt": "Dãy sắp xếp các chất theo thứ tự lực base giảm dần từ trái sang phải là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "NH₃ > CH₃NH₂ > C₆H₅NH₂"}, {"id": "b", "text": "CH₃NH₂ > NH₃ > C₆H₅NH₂ (aniline)"}, {"id": "c", "text": "C₆H₅NH₂ > NH₃ > CH₃NH₂"}], "correctOptionId": "b", "explanation": "Gốc alkyl -CH₃ đẩy electron làm tăng mật độ điện tích trên N (tính base mạnh hơn NH₃); vòng phenyl -C₆H₅ hút electron làm giảm mật độ trên N (tính base yếu hơn NH₃)."}, {"id": "chemistry-12-amino-acids-q1", "prompt": "Amino acid đơn giản nhất có tên gọi là glycine có công thức cấu tạo là:", "difficulty": "EASY", "options": [{"id": "a", "text": "H₂N-CH₂-CH₂-COOH"}, {"id": "b", "text": "H₂N-CH₂-COOH"}, {"id": "c", "text": "CH₃-CH(NH₂)-COOH"}], "correctOptionId": "b", "explanation": "Glycine (acid aminoacetic) có phân tử khối bằng 75, công thức H₂N-CH₂-COOH."}, {"id": "chemistry-12-amino-acids-q2", "prompt": "Ở trạng thái tinh thể và trong dung dịch nước, phân tử amino acid tồn tại chủ yếu ở dạng cấu trúc nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ion lưỡng cực (muối nội phân tử H₃N⁺-CH(R)-COO⁻)"}, {"id": "b", "text": "Dạng phân tử trung hòa H₂N-CH(R)-COOH"}, {"id": "c", "text": "Dạng cation mang điện tích dương hoàn toàn"}], "correctOptionId": "a", "explanation": "Nhóm -COOH có tính acid nhường H⁺ cho nhóm -NH₂ có tính base ngay trong phân tử, tạo dạng ion lưỡng cực bền vững."}, {"id": "chemistry-12-peptides-proteins-q1", "prompt": "Liên kết hóa học giữa nhóm -CO- và nhóm -NH- của hai đơn vị α-amino acid được gọi là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Liên kết peptide"}, {"id": "b", "text": "Liên kết glycosidic"}, {"id": "c", "text": "Liên kết ester"}], "correctOptionId": "a", "explanation": "Định nghĩa liên kết peptide là liên kết amide tạo bởi nhóm carboxyl của α-amino acid này với nhóm amino của α-amino acid kia."}, {"id": "chemistry-12-peptides-proteins-q2", "prompt": "Hợp chất nào sau đây tham gia phản ứng màu biuret với Cu(OH)₂ trong môi trường kiềm tạo dung dịch màu tím đặc trưng?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Dipeptide"}, {"id": "b", "text": "Monosaccharide"}, {"id": "c", "text": "Tripeptide trở lên và protein"}], "correctOptionId": "c", "explanation": "Điều kiện của phản ứng màu biuret là phân tử phải có từ 2 liên kết peptide trở lên, tức từ tripeptide trở lên."}, {"id": "chemistry-12-polymer-basics-q1", "prompt": "Phản ứng kết hợp nhiều phân tử nhỏ (monomer) giống nhau hay tương tự nhau thành phân tử lớn (polymer) gọi là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Phản ứng xà phòng hóa"}, {"id": "b", "text": "Phản ứng este hóa"}, {"id": "c", "text": "Phản ứng trùng hợp"}], "correctOptionId": "c", "explanation": "Định nghĩa phản ứng trùng hợp là quá trình cộng hợp liên tiếp nhiều phân tử nhỏ thành phân tử có khối lượng phân tử rất lớn."}, {"id": "chemistry-12-polymer-basics-q2", "prompt": "Polyethylene (PE) là vật liệu polymer thông dụng được tổng hợp bằng phản ứng trùng hợp monomer nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Vinyl chloride (CH₂=CH-Cl)"}, {"id": "b", "text": "Ethylene (CH₂=CH₂)"}, {"id": "c", "text": "Propylene (CH₂=CH-CH₃)"}], "correctOptionId": "b", "explanation": "Polyethylene được tạo ra từ phản ứng trùng hợp khí ethylene dưới áp suất và xúc tác thích hợp: n CH₂=CH₂ → (-CH₂-CH₂-)_n."}, {"id": "chemistry-12-polymer-materials-q1", "prompt": "Vật liệu polymer nào sau đây được phủ lên bề mặt chảo chống dính nhờ độ bền nhiệt cao và tính trơ hóa học tuyệt vời?", "difficulty": "EASY", "options": [{"id": "a", "text": "Polyethylene (PE)"}, {"id": "b", "text": "Teflon (polytetrafluoroethylene)"}, {"id": "c", "text": "Polyvinyl chloride (PVC)"}], "correctOptionId": "b", "explanation": "Teflon (-CF₂-CF₂-)_n có liên kết C-F rất bền vững, không phản ứng với dầu mỡ ở nhiệt độ nấu nướng và có hệ số ma sát cực thấp."}, {"id": "chemistry-12-polymer-materials-q2", "prompt": "Tơ nylon-6,6 là một loại tơ tổng hợp thuộc phân loại tơ nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tơ polyamide"}, {"id": "b", "text": "Tơ polyester"}, {"id": "c", "text": "Tơ bán tổng hợp (tơ nhân tạo)"}], "correctOptionId": "a", "explanation": "Nylon-6,6 được điều chế từ hexamethylenediamine và adipic acid, chứa các liên kết amide -CO-NH- lặp lại nên là tơ polyamide."}]'::jsonb,'["chemistry-12-amines", "chemistry-12-amino-acids", "chemistry-12-peptides-proteins", "chemistry-12-polymer-basics", "chemistry-12-polymer-materials"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-electrode-potentials',19,'LESSON','Thế điện cực chuẩn và dãy thế điện cực chuẩn','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Thế điện cực chuẩn E°(Ox/Red) đo xu hướng oxi hóa - khử của cặp ở điều kiện chuẩn so với điện cực chuẩn hydrogen (quy ước E°(2H⁺/H₂) = 0,00 V). E° càng lớn: dạng oxi hóa càng mạnh, dạng khử càng yếu. Quy tắc alpha: chất oxi hóa mạnh hơn phản ứng với chất khử mạnh hơn tạo chất oxi hóa yếu hơn và chất khử yếu hơn."]'::jsonb,'["E°(Zn²⁺/Zn) = -0,76 V và E°(Cu²⁺/Cu) = +0,34 V. Ion Cu²⁺ có tính oxi hóa mạnh hơn Zn²⁺; kim loại Zn khử được ion Cu²⁺: Zn + Cu²⁺ → Zn²⁺ + Cu."]'::jsonb,'[{"id": "chemistry-12-electrode-potentials-q1", "prompt": "Trong thang đo thế điện cực chuẩn, điện cực chuẩn hydrogen được quy ước có thế điện cực ở 25 °C bằng:", "difficulty": "EASY", "options": [{"id": "a", "text": "0,00 V"}, {"id": "b", "text": "1,00 V"}, {"id": "c", "text": "-1,00 V"}], "correctOptionId": "a", "explanation": "Điện cực hydro chuẩn (SHE) với H⁺ (1 M) và khí H₂ (1 bar) trên bề mặt platin được chọn làm mốc chuẩn có E° = 0,00 V."}, {"id": "chemistry-12-electrode-potentials-q2", "prompt": "Cho thế điện cực chuẩn: E°(Zn²⁺/Zn) = -0,76 V và E°(Cu²⁺/Cu) = +0,34 V. So sánh tính oxi hóa giữa hai ion kim loại:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ion Zn²⁺ có tính oxi hóa mạnh hơn ion Cu²⁺"}, {"id": "b", "text": "Hai ion có tính oxi hóa tương đương nhau"}, {"id": "c", "text": "Ion Cu²⁺ có tính oxi hóa mạnh hơn ion Zn²⁺"}], "correctOptionId": "c", "explanation": "Cặp có thế điện cực chuẩn lớn hơn (+0,34 V > -0,76 V) thì dạng oxi hóa (Cu²⁺) có tính oxi hóa mạnh hơn."}, {"id": "chemistry-12-electrode-potentials-q3", "prompt": "Nhúng một chiếc đinh sắt sạch vào dung dịch đồng(II) sulfate (CuSO₄), hiện tượng hóa học quan sát được là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Không có bất kì hiện tượng nào xảy ra"}, {"id": "b", "text": "Có lớp kim loại màu đỏ bám trên đinh sắt và màu xanh của dung dịch nhạt dần"}, {"id": "c", "text": "Có khí không màu mùi hắc thoát ra mãnh liệt"}], "correctOptionId": "b", "explanation": "Sắt có tính khử mạnh hơn đồng (E°(Fe²⁺/Fe) = -0,44 V < +0,34 V) nên khử Cu²⁺ thành Cu kim loại màu đỏ bám lên đinh sắt: Fe + Cu²⁺ → Fe²⁺ + Cu."}]'::jsonb,'["chemistry-12-electrode-potentials"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-galvanic-cells',20,'LESSON','Pin điện hóa (Galvanic cell)','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Pin điện hóa biến đổi hóa năng thành điện năng nhờ phản ứng oxi hóa - khử tự phát. Anode (cực âm): xảy ra quá trình oxi hóa; Cathode (cực dương): xảy ra quá trình khử. Sức điện động chuẩn: E°_pin = E°_cathode - E°_anode > 0. Cầu muối (chứa dung dịch KCl hoặc KNO₃) đóng kín mạch và trung hòa điện tích hai nửa pin."]'::jsonb,'["Pin Daniell Zn-Cu: Zn | Zn²⁺(1M) || Cu²⁺(1M) | Cu. E°_pin = +0,34 - (-0,76) = 1,10 V."]'::jsonb,'[{"id": "chemistry-12-galvanic-cells-q1", "prompt": "Trong pin điện hóa Zn - Cu (pin Daniell) khi hoạt động, tại cực âm (anode) xảy ra quá trình nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quá trình khử ion kẽm (Zn²⁺ + 2e → Zn)"}, {"id": "b", "text": "Quá trình oxi hóa ion đồng (Cu → Cu²⁺ + 2e)"}, {"id": "c", "text": "Quá trình oxi hóa kẽm (Zn → Zn²⁺ + 2e)"}], "correctOptionId": "c", "explanation": "Tại cực âm (anode), kẽm có tính khử mạnh hơn bị oxi hóa nhường electron đi vào mạch ngoài."}, {"id": "chemistry-12-galvanic-cells-q2", "prompt": "Cho E°(Zn²⁺/Zn) = -0,76 V và E°(Cu²⁺/Cu) = +0,34 V. Sức điện động chuẩn của pin điện hóa Zn - Cu bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "-0,42 V"}, {"id": "b", "text": "1,10 V"}, {"id": "c", "text": "0,42 V"}], "correctOptionId": "b", "explanation": "E°_pin = E°_cathode - E°_anode = E°(Cu²⁺/Cu) - E°(Zn²⁺/Zn) = +0,34 - (-0,76) = +1,10 V."}, {"id": "chemistry-12-galvanic-cells-q3", "prompt": "Vai trò chủ yếu của cầu muối (salt bridge) trong một pin điện hóa hoạt động là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Khép kín mạch điện và duy trì tính trung hòa điện tích cho hai dung dịch điện cực"}, {"id": "b", "text": "Trực tiếp tạo ra các electron dẫn điện cho mạch ngoài"}, {"id": "c", "text": "Tăng nhiệt độ của pin điện hóa lên mức tối đa"}], "correctOptionId": "a", "explanation": "Cầu muối cho phép các ion di chuyển qua lại để bù đắp sự chênh lệch điện tích giữa hai bán pin, ngăn cản sự phân cực và khép kín mạch."}]'::jsonb,'["chemistry-12-galvanic-cells"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-electrolysis',21,'LESSON','Điện phân dung dịch và điện phân nóng chảy','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Điện phân biến đổi điện năng thành hóa năng nhờ dòng điện một chiều cưỡng bức phản ứng oxi hóa - khử. Cathode (cực âm nối cực âm nguồn): xảy ra quá trình khử; Anode (cực dương nối cực dương nguồn): xảy ra quá trình oxi hóa. Các kim loại hoạt động mạnh (từ Al trở về trước) chỉ có thể điều chế bằng điện phân nóng chảy hợp chất (như nóng chảy Al₂O₃ có cryolite Na₃AlF₆)."]'::jsonb,'["Điện phân dung dịch CuCl₂ với điện cực trơ: CuCl₂ → Cu (ở cathode) + Cl₂ (ở anode)."]'::jsonb,'[{"id": "chemistry-12-electrolysis-q1", "prompt": "Kim loại nhôm (Al) trong công nghiệp được sản xuất với quy mô lớn bằng phương pháp nào sau đây?", "difficulty": "EASY", "options": [{"id": "a", "text": "Thủy luyện dùng sắt đẩy nhôm ra khỏi dung dịch muối AlCl₃"}, {"id": "b", "text": "Điện phân nóng chảy Al₂O₃ với sự có mặt của phụ gia cryolite (Na₃AlF₆)"}, {"id": "c", "text": "Nhiệt luyện dùng CO khử Al₂O₃ ở nhiệt độ cao"}], "correctOptionId": "b", "explanation": "Nhôm là kim loại có tính khử mạnh, ion Al³⁺ rất khó bị khử nên bắt buộc phải dùng phương pháp điện phân nóng chảy."}, {"id": "chemistry-12-electrolysis-q2", "prompt": "Trong quá trình điện phân dung dịch CuCl₂ bằng dòng điện một chiều với hai điện cực trơ, tại cathode (cực âm) xảy ra quá trình nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Khử ion Cu²⁺ thành Cu kim loại (Cu²⁺ + 2e → Cu)"}, {"id": "b", "text": "Oxi hóa ion Cl⁻ thành khí Cl₂"}, {"id": "c", "text": "Oxi hóa nước giải phóng khí oxy"}], "correctOptionId": "a", "explanation": "Tại cathode (cực âm), cation Cu²⁺ bị hút về và nhận electron thực hiện quá trình khử tạo đồng kim loại bám lên điện cực."}, {"id": "chemistry-12-electrolysis-q3", "prompt": "Vai trò quan trọng của quặng cryolite (Na₃AlF₆) khi pha trộn với Al₂O₃ trong quá trình điện phân nóng chảy nhôm là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Làm tăng khối lượng nhôm thu được lên gấp đôi"}, {"id": "b", "text": "Ngăn không cho khí oxi phản ứng với nhôm lỏng"}, {"id": "c", "text": "Hạ nhiệt độ nóng chảy của Al₂O₃ từ trên 2000 °C xuống khoảng 950 °C và tăng tính dẫn điện"}], "correctOptionId": "c", "explanation": "Cryolite tạo hỗn hợp eutectic nóng chảy ở nhiệt độ thấp hơn nhiều (~950 °C so với 2050 °C), giúp tiết kiệm năng lượng điện khổng lồ."}]'::jsonb,'["chemistry-12-electrolysis"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-metal-corrosion',22,'LESSON','Ăn mòn kim loại và các phương pháp bảo vệ','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Ăn mòn kim loại là sự phá hủy kim loại hoặc hợp kim do tác dụng của môi trường. Ăn mòn hóa học: không phát sinh dòng điện. Ăn mòn điện hóa: có 2 điện cực khác bản chất, tiếp xúc và cùng nhúng trong dung dịch điện li; cực âm (kim loại mạnh hơn) bị ăn mòn trước. Bảo vệ: phủ bề mặt (sơn, mạ) hoặc phương pháp điện hóa (dùng kim loại hi sinh như gắn tấm kẽm bảo vệ vỏ tàu thép)."]'::jsonb,'["Vỏ tàu biển bằng thép ngâm trong nước biển (dung dịch điện li) được bảo vệ bằng cách gắn các khối kẽm (Zn); Zn bị ăn mòn thay thế cho Fe."]'::jsonb,'[{"id": "chemistry-12-metal-corrosion-q1", "prompt": "Điều kiện để xảy ra hiện tượng ăn mòn điện hóa học kim loại bao gồm các yếu tố nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Hai điện cực khác bản chất, tiếp xúc trực tiếp hoặc gián tiếp, và cùng tiếp xúc với dung dịch điện li"}, {"id": "b", "text": "Chỉ cần kim loại được đặt trong môi trường chân không tuyệt đối"}, {"id": "c", "text": "Chỉ xảy ra khi nối kim loại với một nguồn điện một chiều bên ngoài"}], "correctOptionId": "a", "explanation": "Ăn mòn điện hóa đòi hỏi 3 điều kiện: hai điện cực khác nhau, có tiếp xúc điện và cùng nhúng trong môi trường dẫn điện điện li."}, {"id": "chemistry-12-metal-corrosion-q2", "prompt": "Để bảo vệ vỏ tàu thủy bằng thép (chứa Fe) khỏi bị ăn mòn khi hoạt động trên biển, người ta thường gắn vào vỏ tàu các tấm kim loại nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tấm đồng (Cu)"}, {"id": "b", "text": "Tấm bạc (Ag)"}, {"id": "c", "text": "Tấm kẽm (Zn)"}], "correctOptionId": "c", "explanation": "Kẽm có tính khử mạnh hơn sắt (E°(Zn²⁺/Zn) = -0,76 V < -0,44 V) nên đóng vai trò là anode hi sinh, bị ăn mòn thay cho vỏ tàu thép."}, {"id": "chemistry-12-metal-corrosion-q3", "prompt": "Nối một đoạn dây sắt với một đoạn dây đồng rồi cùng nhúng vào cốc nước muối NaCl. Kim loại nào sẽ bị ăn mòn điện hóa trước?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Cả hai kim loại bị ăn mòn với tốc độ hoàn toàn như nhau"}, {"id": "b", "text": "Dây sắt bị ăn mòn trước"}, {"id": "c", "text": "Dây đồng bị ăn mòn trước"}], "correctOptionId": "b", "explanation": "Sắt có tính khử mạnh hơn đồng nên đóng vai trò là cực âm (anode) và bị oxi hóa hòa tan trước, đồng là cathode chỉ truyền electron."}]'::jsonb,'["chemistry-12-metal-corrosion"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-metal-properties-extraction',23,'LESSON','Tính chất chung và phương pháp điều chế kim loại','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Kim loại có liên kết kim loại (mạng tinh thể cation và các electron tự do). Tính chất vật lí chung do electron tự do quyết định: tính dẻo, tính dẫn điện, tính dẫn nhiệt và ánh kim. Dẫn điện tốt nhất: Ag > Cu > Au > Al > Fe. Phương pháp điều chế: Nhiệt luyện (khử oxit kim loại đứng sau Al bằng CO, H₂, C ở t° cao); Thủy luyện (dùng kim loại mạnh đẩy ion kim loại yếu ra khỏi dung dịch); Điện phân."]'::jsonb,'["Trong công nghiệp luyện kim, sắt (Fe) được sản xuất trong lò cao bằng phương pháp nhiệt luyện: dùng khí CO khử Fe₂O₃ ở nhiệt độ cao."]'::jsonb,'[{"id": "chemistry-12-metal-properties-extraction-q1", "prompt": "Các tính chất vật lí chung của kim loại như tính dẫn điện, dẫn nhiệt, tính dẻo và ánh kim do thành phần nào trong tinh thể quyết định?", "difficulty": "EASY", "options": [{"id": "a", "text": "Các liên kết cộng hóa trị phân cực giữa các nguyên tử"}, {"id": "b", "text": "Kích thước hạt nhân nguyên tử kim loại"}, {"id": "c", "text": "Các electron tự do di chuyển trong toàn bộ mạng tinh thể kim loại"}], "correctOptionId": "c", "explanation": "Mô hình biển electron tự do giải thích trọn vẹn 4 tính chất vật lí chung đặc trưng của giới kim loại."}, {"id": "chemistry-12-metal-properties-extraction-q2", "prompt": "Phương pháp nhiệt luyện dùng khí CO hoặc H₂ để khử oxit kim loại ở nhiệt độ cao thường được áp dụng để điều chế các kim loại nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ dùng riêng cho kim loại nhôm (Al)"}, {"id": "b", "text": "Các kim loại đứng sau nhôm trong dãy hoạt động hóa học (như Fe, Cu, Zn)"}, {"id": "c", "text": "Các kim loại kiềm và kiềm thổ (như Na, K, Ca)"}], "correctOptionId": "b", "explanation": "CO và H₂ chỉ có thể khử được các ion kim loại có tính oxi hóa từ kẽm (Zn) trở đi (sau Al) ở nhiệt độ cao."}, {"id": "chemistry-12-metal-properties-extraction-q3", "prompt": "Kim loại có độ dẫn điện tốt nhất trong tất cả các kim loại ở điều kiện nhiệt độ phòng là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Bạc (Ag)"}, {"id": "b", "text": "Đồng (Cu)"}, {"id": "c", "text": "Vàng (Au)"}], "correctOptionId": "a", "explanation": "Thứ tự độ dẫn điện giảm dần của các kim loại phổ biến là: Ag > Cu > Au > Al > Fe; bạc dẫn điện tốt nhất."}]'::jsonb,'["chemistry-12-metal-properties-extraction"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('chemistry',12,'intro-2026.1','chemistry-12-review-4',24,'FIVE_LESSON_REVIEW','Ôn tập 4','Hóa học 12: Hợp chất hữu cơ, Đại cương polymer và Điện hóa học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "chemistry-12-electrode-potentials-q1", "prompt": "Trong thang đo thế điện cực chuẩn, điện cực chuẩn hydrogen được quy ước có thế điện cực ở 25 °C bằng:", "difficulty": "EASY", "options": [{"id": "a", "text": "0,00 V"}, {"id": "b", "text": "1,00 V"}, {"id": "c", "text": "-1,00 V"}], "correctOptionId": "a", "explanation": "Điện cực hydro chuẩn (SHE) với H⁺ (1 M) và khí H₂ (1 bar) trên bề mặt platin được chọn làm mốc chuẩn có E° = 0,00 V."}, {"id": "chemistry-12-electrode-potentials-q2", "prompt": "Cho thế điện cực chuẩn: E°(Zn²⁺/Zn) = -0,76 V và E°(Cu²⁺/Cu) = +0,34 V. So sánh tính oxi hóa giữa hai ion kim loại:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ion Zn²⁺ có tính oxi hóa mạnh hơn ion Cu²⁺"}, {"id": "b", "text": "Hai ion có tính oxi hóa tương đương nhau"}, {"id": "c", "text": "Ion Cu²⁺ có tính oxi hóa mạnh hơn ion Zn²⁺"}], "correctOptionId": "c", "explanation": "Cặp có thế điện cực chuẩn lớn hơn (+0,34 V > -0,76 V) thì dạng oxi hóa (Cu²⁺) có tính oxi hóa mạnh hơn."}, {"id": "chemistry-12-galvanic-cells-q1", "prompt": "Trong pin điện hóa Zn - Cu (pin Daniell) khi hoạt động, tại cực âm (anode) xảy ra quá trình nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quá trình khử ion kẽm (Zn²⁺ + 2e → Zn)"}, {"id": "b", "text": "Quá trình oxi hóa ion đồng (Cu → Cu²⁺ + 2e)"}, {"id": "c", "text": "Quá trình oxi hóa kẽm (Zn → Zn²⁺ + 2e)"}], "correctOptionId": "c", "explanation": "Tại cực âm (anode), kẽm có tính khử mạnh hơn bị oxi hóa nhường electron đi vào mạch ngoài."}, {"id": "chemistry-12-galvanic-cells-q2", "prompt": "Cho E°(Zn²⁺/Zn) = -0,76 V và E°(Cu²⁺/Cu) = +0,34 V. Sức điện động chuẩn của pin điện hóa Zn - Cu bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "-0,42 V"}, {"id": "b", "text": "1,10 V"}, {"id": "c", "text": "0,42 V"}], "correctOptionId": "b", "explanation": "E°_pin = E°_cathode - E°_anode = E°(Cu²⁺/Cu) - E°(Zn²⁺/Zn) = +0,34 - (-0,76) = +1,10 V."}, {"id": "chemistry-12-electrolysis-q1", "prompt": "Kim loại nhôm (Al) trong công nghiệp được sản xuất với quy mô lớn bằng phương pháp nào sau đây?", "difficulty": "EASY", "options": [{"id": "a", "text": "Thủy luyện dùng sắt đẩy nhôm ra khỏi dung dịch muối AlCl₃"}, {"id": "b", "text": "Điện phân nóng chảy Al₂O₃ với sự có mặt của phụ gia cryolite (Na₃AlF₆)"}, {"id": "c", "text": "Nhiệt luyện dùng CO khử Al₂O₃ ở nhiệt độ cao"}], "correctOptionId": "b", "explanation": "Nhôm là kim loại có tính khử mạnh, ion Al³⁺ rất khó bị khử nên bắt buộc phải dùng phương pháp điện phân nóng chảy."}, {"id": "chemistry-12-electrolysis-q2", "prompt": "Trong quá trình điện phân dung dịch CuCl₂ bằng dòng điện một chiều với hai điện cực trơ, tại cathode (cực âm) xảy ra quá trình nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Khử ion Cu²⁺ thành Cu kim loại (Cu²⁺ + 2e → Cu)"}, {"id": "b", "text": "Oxi hóa ion Cl⁻ thành khí Cl₂"}, {"id": "c", "text": "Oxi hóa nước giải phóng khí oxy"}], "correctOptionId": "a", "explanation": "Tại cathode (cực âm), cation Cu²⁺ bị hút về và nhận electron thực hiện quá trình khử tạo đồng kim loại bám lên điện cực."}, {"id": "chemistry-12-metal-corrosion-q1", "prompt": "Điều kiện để xảy ra hiện tượng ăn mòn điện hóa học kim loại bao gồm các yếu tố nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Hai điện cực khác bản chất, tiếp xúc trực tiếp hoặc gián tiếp, và cùng tiếp xúc với dung dịch điện li"}, {"id": "b", "text": "Chỉ cần kim loại được đặt trong môi trường chân không tuyệt đối"}, {"id": "c", "text": "Chỉ xảy ra khi nối kim loại với một nguồn điện một chiều bên ngoài"}], "correctOptionId": "a", "explanation": "Ăn mòn điện hóa đòi hỏi 3 điều kiện: hai điện cực khác nhau, có tiếp xúc điện và cùng nhúng trong môi trường dẫn điện điện li."}, {"id": "chemistry-12-metal-corrosion-q2", "prompt": "Để bảo vệ vỏ tàu thủy bằng thép (chứa Fe) khỏi bị ăn mòn khi hoạt động trên biển, người ta thường gắn vào vỏ tàu các tấm kim loại nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tấm đồng (Cu)"}, {"id": "b", "text": "Tấm bạc (Ag)"}, {"id": "c", "text": "Tấm kẽm (Zn)"}], "correctOptionId": "c", "explanation": "Kẽm có tính khử mạnh hơn sắt (E°(Zn²⁺/Zn) = -0,76 V < -0,44 V) nên đóng vai trò là anode hi sinh, bị ăn mòn thay cho vỏ tàu thép."}, {"id": "chemistry-12-metal-properties-extraction-q1", "prompt": "Các tính chất vật lí chung của kim loại như tính dẫn điện, dẫn nhiệt, tính dẻo và ánh kim do thành phần nào trong tinh thể quyết định?", "difficulty": "EASY", "options": [{"id": "a", "text": "Các liên kết cộng hóa trị phân cực giữa các nguyên tử"}, {"id": "b", "text": "Kích thước hạt nhân nguyên tử kim loại"}, {"id": "c", "text": "Các electron tự do di chuyển trong toàn bộ mạng tinh thể kim loại"}], "correctOptionId": "c", "explanation": "Mô hình biển electron tự do giải thích trọn vẹn 4 tính chất vật lí chung đặc trưng của giới kim loại."}, {"id": "chemistry-12-metal-properties-extraction-q2", "prompt": "Phương pháp nhiệt luyện dùng khí CO hoặc H₂ để khử oxit kim loại ở nhiệt độ cao thường được áp dụng để điều chế các kim loại nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ dùng riêng cho kim loại nhôm (Al)"}, {"id": "b", "text": "Các kim loại đứng sau nhôm trong dãy hoạt động hóa học (như Fe, Cu, Zn)"}, {"id": "c", "text": "Các kim loại kiềm và kiềm thổ (như Na, K, Ca)"}], "correctOptionId": "b", "explanation": "CO và H₂ chỉ có thể khử được các ion kim loại có tính oxi hóa từ kẽm (Zn) trở đi (sau Al) ở nhiệt độ cao."}]'::jsonb,'["chemistry-12-electrode-potentials", "chemistry-12-galvanic-cells", "chemistry-12-electrolysis", "chemistry-12-metal-corrosion", "chemistry-12-metal-properties-extraction"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','placement',0,'PLACEMENT','Khảo sát đầu vào','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "biology-12-dna-replication-q1", "prompt": "Nguyên tắc bán bảo toàn trong quá trình tái bản DNA có nghĩa là gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Mỗi phân tử DNA con tạo ra gồm một mạch cũ của mẹ và một mạch mới tổng hợp"}, {"id": "b", "text": "Hai phân tử DNA con đều gồm toàn bộ các nucleotide hoàn toàn mới"}, {"id": "c", "text": "Toàn bộ phân tử DNA mẹ được giữ nguyên vẹn ở một tế bào con"}], "correctOptionId": "a", "explanation": "Bán bảo toàn nghĩa là giữ lại một nửa: mỗi phân tử DNA con chứa một mạch gốc từ phân tử mẹ và một mạch mới."}, {"id": "biology-12-dna-replication-q2", "prompt": "Enzyme DNA polymerase xúc tác gắn các nucleotide tự do vào đầu nào của chuỗi polynucleotide đang tổng hợp?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đầu 5''-phosphate tự do (tổng hợp theo chiều 3'' → 5'')"}, {"id": "b", "text": "Có thể gắn ngẫu nhiên vào cả hai đầu 3'' và 5'' cùng lúc"}, {"id": "c", "text": "Đầu 3''-OH tự do (tổng hợp theo chiều 5'' → 3'')"}], "correctOptionId": "c", "explanation": "DNA polymerase chỉ có thể gắn nucleotide vào nhóm 3''-OH tự do nên chuỗi mới luôn kéo dài theo chiều 5'' -> 3''."}, {"id": "biology-12-transcription-q1", "prompt": "Phân tử enzyme trực tiếp xúc tác quá trình tháo xoắn và tổng hợp mạch RNA trong phiên mã là:", "difficulty": "EASY", "options": [{"id": "a", "text": "DNA polymerase"}, {"id": "b", "text": "Enzyme ligase nối mạch"}, {"id": "c", "text": "RNA polymerase"}], "correctOptionId": "c", "explanation": "RNA polymerase tự tháo xoắn DNA và liên kết các ribonucleotide tự do tương ứng với mạch khuôn DNA."}, {"id": "biology-12-transcription-q2", "prompt": "Mạch khuôn của gene được enzyme phiên mã sử dụng để tổng hợp phân tử mRNA có chiều:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cả hai mạch đều được dùng làm khuôn đồng thời"}, {"id": "b", "text": "Chiều 3'' → 5''"}, {"id": "c", "text": "Chiều 5'' → 3''"}], "correctOptionId": "b", "explanation": "Mạch khuôn của gene có chiều 3'' -> 5'' để phân tử RNA sinh ra kéo dài theo chiều 5'' -> 3''."}, {"id": "biology-12-translation-q1", "prompt": "Đặc điểm thoái hóa (dư thừa) của mã di truyền có nghĩa là gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Mã di truyền bị suy giảm chất lượng qua các thế hệ tế bào"}, {"id": "b", "text": "Nhiều bộ ba codon khác nhau có thể cùng mã hóa cho một loại amino acid"}, {"id": "c", "text": "Một bộ ba codon có thể mã hóa cho nhiều loại amino acid khác nhau"}], "correctOptionId": "b", "explanation": "Tính thoái hóa: 61 codon chỉ mã hóa 20 loại amino acid, do đó nhiều codon cùng chỉ định một amino acid (trừ AUG và UGG)."}, {"id": "biology-12-translation-q2", "prompt": "Codon nào sau đây trên phân tử mRNA đóng vai trò là tín hiệu bắt đầu dịch mã (codon mở đầu)?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "5''-AUG-3''"}, {"id": "b", "text": "5''-UAA-3''"}, {"id": "c", "text": "5''-UGA-3''"}], "correctOptionId": "a", "explanation": "5''-AUG-3'' là codon mở đầu duy nhất trên mRNA, mã hóa Methionine ở nhân thực (hoặc fMet ở nhân sơ)."}, {"id": "biology-12-gene-regulation-q1", "prompt": "Trong cấu trúc của Operon Lac ở vi khuẩn E. coli, vùng vận hành (operator - O) là nơi:", "difficulty": "EASY", "options": [{"id": "a", "text": "Protein ức chế liên kết để ngăn cản quá trình phiên mã"}, {"id": "b", "text": "Enzyme RNA polymerase bám vào để khởi động phiên mã"}, {"id": "c", "text": "Chứa mã di truyền quy định cấu trúc của enzyme phân giải đường"}], "correctOptionId": "a", "explanation": "Vùng vận hành O là vị trí gắn của protein ức chế; khi bị chặn, RNA polymerase không thể trượt qua phiên mã."}, {"id": "biology-12-gene-regulation-q2", "prompt": "Khi môi trường sống của vi khuẩn E. coli có đường lactose, sự kiện nào sau đây xảy ra?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Gene điều hòa R ngừng hoàn toàn quá trình phiên mã tạo protein"}, {"id": "b", "text": "Vùng khởi động P bị phân hủy bởi các enzyme trong tế bào chất"}, {"id": "c", "text": "Phân tử lactose liên kết làm biến đổi cấu hình protein ức chế khiến nó không bám được vào vùng O"}], "correctOptionId": "c", "explanation": "Lactose đóng vai trò chất cảm ứng gắn vào protein ức chế làm nó mất khả năng bám vùng vận hành, mở đường cho phiên mã."}, {"id": "biology-12-gene-mutation-q1", "prompt": "Dạng đột biến điểm nào sau đây KHÔNG làm thay đổi số lượng liên kết hydro của gene?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đột biến thay thế cặp A-T bằng cặp G-C"}, {"id": "b", "text": "Đột biến mất một cặp A-T"}, {"id": "c", "text": "Đột biến thay thế cặp A-T bằng cặp T-A"}], "correctOptionId": "c", "explanation": "Cặp A-T và T-A đều có 2 liên kết hydro, nên đảo chiều thay thế A-T bằng T-A không làm thay đổi tổng số liên kết hydro."}, {"id": "biology-12-gene-mutation-q2", "prompt": "Đột biến gene xảy ra làm xuất hiện một bộ ba kết thúc sớm ở đoạn đầu của vùng mã hóa sẽ dẫn tới hậu quả:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hoàn toàn không ảnh hưởng gì tới hoạt tính sinh học của protein"}, {"id": "b", "text": "Quá trình dịch mã dừng sớm tạo ra chuỗi polypeptide ngắn bất thường và mất chức năng"}, {"id": "c", "text": "Làm tăng gấp đôi chiều dài của phân tử protein được tổng hợp"}], "correctOptionId": "b", "explanation": "Đột biến vô nghĩa (nonsense) tạo codon kết thúc sớm làm ribosome dừng dịch mã ngay, sinh ra chuỗi polypeptide cụt ngắn."}, {"id": "biology-12-mendelian-genetics-q1", "prompt": "Cơ sở tế bào học trực tiếp của quy luật phân li độc lập theo quan điểm di truyền học hiện đại là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Sự nhân đôi đồng thời của các phân tử DNA ở pha S của chu kì tế bào"}, {"id": "b", "text": "Sự phân li độc lập và tổ hợp ngẫu nhiên của các cặp nhiễm sắc thể tương đồng trong giảm phân"}, {"id": "c", "text": "Sự tiếp hợp và trao đổi chéo giữa các chromatid chị em trong nguyên phân"}], "correctOptionId": "b", "explanation": "Các cặp gene nằm trên các cặp NST tương đồng khác nhau phân li độc lập khi các cặp NST này phân li ngẫu nhiên về hai cực tế bào ở kì sau I."}, {"id": "biology-12-mendelian-genetics-q2", "prompt": "Cho phép lai P: AaBb × aabb (lai phân tích hai cặp gene phân li độc lập). Tỉ lệ phân li kiểu hình ở đời con Fa là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "1 : 1 : 1 : 1"}, {"id": "b", "text": "9 : 3 : 3 : 1"}, {"id": "c", "text": "3 : 3 : 1 : 1"}], "correctOptionId": "a", "explanation": "Cơ thể AaBb cho 4 loại giao tử với tỉ lệ 1/4 AB : 1/4 Ab : 1/4 aB : 1/4 ab; cơ thể aabb cho 1 loại giao tử ab. Con lai phân tích có tỉ lệ kiểu hình 1:1:1:1."}, {"id": "biology-12-linkage-crossing-over-q1", "prompt": "Hiện tượng hoán vị gene xảy ra do cơ chế tiếp hợp và trao đổi chéo giữa các đoạn chromatid ở kì nào của quá trình phân bào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Kì đầu của giảm phân I"}, {"id": "b", "text": "Kì giữa của giảm phân II"}, {"id": "c", "text": "Kì sau của nguyên phân"}], "correctOptionId": "a", "explanation": "Sự tiếp hợp và trao đổi chéo giữa các chromatid khác nguồn gốc của cặp NST tương đồng xảy ra ở kì đầu I của giảm phân."}, {"id": "biology-12-linkage-crossing-over-q2", "prompt": "Tần số hoán vị gene giữa hai locus gene trên cùng một nhiễm sắc thể:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Luôn bằng đúng 100% ở mọi loài sinh vật"}, {"id": "b", "text": "Luôn lớn hơn 75% đối với các gene liên kết xa nhau"}, {"id": "c", "text": "Không bao giờ vượt quá 50%"}], "correctOptionId": "c", "explanation": "Trao đổi chéo chỉ xảy ra giữa 2 trong 4 chromatid của thể tứ tử, tối đa 50% số giao tử tạo ra là giao tử hoán vị (f ≤ 50%)."}, {"id": "biology-12-sex-linked-inheritance-q1", "prompt": "Đặc điểm nổi bật của quy luật di truyền các tính trạng do gene lặn nằm trên vùng không tương đồng của nhiễm sắc thể X quy định ở người là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ truyền trực tiếp từ bố cho con trai"}, {"id": "b", "text": "Biểu hiện đồng đều 100% ở tất cả các thế hệ con cháu"}, {"id": "c", "text": "Di truyền chéo và bệnh thường biểu hiện ở nam giới với tần suất cao hơn nữ giới"}], "correctOptionId": "c", "explanation": "Nam giới chỉ có 1 NST X (XY) nên chỉ cần mang 1 allele lặn là biểu hiện bệnh; tính trạng truyền chéo từ mẹ sang con trai."}, {"id": "biology-12-sex-linked-inheritance-q2", "prompt": "Ở người, bệnh máu khó đông do allele lặn h nằm trên vùng không tương đồng của NST X quy định (Xʰ), allele H quy định máu đông bình thường. Bố bình thường kết hôn với mẹ mang gene bệnh dị hợp (XᴴXʰ). Xác suất họ sinh con trai bị bệnh là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0% vì bố có kiểu gene bình thường"}, {"id": "b", "text": "25% (hay 1/2 số con trai)"}, {"id": "c", "text": "50% tổng số con"}], "correctOptionId": "b", "explanation": "Sơ đồ lai: XᴴY × XᴴXʰ → 1/4 XᴴXᴴ : 1/4 XᴴXʰ : 1/4 XᴴY : 1/4 XʰY. Xác suất sinh con trai bị bệnh (XʰY) trong tổng số con là 1/4 = 25%."}, {"id": "biology-12-chromosomal-mutation-q1", "prompt": "Dạng đột biến cấu trúc nhiễm sắc thể nào sau đây làm giảm số lượng gene trên một nhiễm sắc thể và thường gây hại nhiều nhất cho sinh vật?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đột biến đảo đoạn"}, {"id": "b", "text": "Đột biến mất đoạn"}, {"id": "c", "text": "Đột biến lặp đoạn"}], "correctOptionId": "b", "explanation": "Mất đoạn làm mất vật chất di truyền mang gene, phá vỡ cân bằng gene trong hệ gen nên thường gây chết hoặc giảm sức sống nghiêm trọng."}, {"id": "biology-12-chromosomal-mutation-q2", "prompt": "Người mắc hội chứng Down có bộ nhiễm sắc thể thuộc dạng đột biến số lượng nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thể ba nhiễm (2n + 1) ở cặp nhiễm sắc thể số 21"}, {"id": "b", "text": "Thể một nhiễm (2n - 1) ở cặp nhiễm sắc thể giới tính"}, {"id": "c", "text": "Thể tam bội (3n) toàn bộ bộ nhiễm sắc thể"}], "correctOptionId": "a", "explanation": "Hội chứng Down xuất hiện do có 3 nhiễm sắc thể ở cặp số 21 (thể ba 2n+1 = 47 chiếc)."}, {"id": "biology-12-human-genetics-q1", "prompt": "Phương pháp nghiên cứu phả hệ ở người có mục đích chính là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Theo dõi sự di truyền của một tính trạng qua nhiều thế hệ để xác định quy luật di truyền của tính trạng đó"}, {"id": "b", "text": "Gây đột biến nhân tạo bằng tia phóng xạ để quan sát kiểu hình người"}, {"id": "c", "text": "Lai phân tích người với các loài linh trưởng khác để xác định kiểu gene"}], "correctOptionId": "a", "explanation": "Do không thể thực hiện các phép lai thực nghiệm ở người, phả hệ ghi nhận lịch sử gia đình qua các thế hệ để suy luận quy luật di truyền."}, {"id": "biology-12-human-genetics-q2", "prompt": "Kĩ thuật chọc dò dịch ối hoặc sinh thiết gai nhau ở phụ nữ mang thai nhằm mục đích:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bơm thêm chất dinh dưỡng trực tiếp vào dạ dày của thai nhi"}, {"id": "b", "text": "Tiêu diệt các vi khuẩn có hại bám trên thành tử cung"}, {"id": "c", "text": "Lấy tế bào thai nhi để phân tích nhiễm sắc thể và phát hiện sớm các dị tật di truyền"}], "correctOptionId": "c", "explanation": "Tế bào bong từ thai trong dịch ối cho phép lập karyotype để chẩn đoán thể tam nhiễm hoặc giải trình tự gene phát hiện bệnh lý trước sinh."}, {"id": "biology-12-evolution-evidence-q1", "prompt": "Cánh dơi và tay người có cùng cấu trúc giải phẫu xương nhưng đảm nhiệm các chức năng khác nhau là ví dụ về:", "difficulty": "EASY", "options": [{"id": "a", "text": "Cơ quan tương tự"}, {"id": "b", "text": "Cơ quan thoái hóa"}, {"id": "c", "text": "Cơ quan tương đồng"}], "correctOptionId": "c", "explanation": "Cơ quan tương đồng bắt nguồn từ cùng một nguồn gốc phôi thai ở tổ tiên chung nhưng biến đổi thích nghi với các chức năng khác nhau."}, {"id": "biology-12-evolution-evidence-q2", "prompt": "Bằng chứng tiến hóa nào sau đây được coi là bằng chứng trực tiếp và xác thực nhất về lịch sử phát triển của sinh giới?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cơ quan thoái hóa ruột thừa ở người"}, {"id": "b", "text": "Hóa thạch các sinh vật cổ xưa còn lưu lại trong các tầng địa chất"}, {"id": "c", "text": "Sự tương đồng về cấu trúc protein cytochrom c"}], "correctOptionId": "b", "explanation": "Hóa thạch là di tích thực tế của sinh vật cổ sinh được bảo tồn trong đá, là bằng chứng trực tiếp duy nhất về niên đại và hình dạng sinh vật cổ."}, {"id": "biology-12-modern-evolution-synthesis-q1", "prompt": "Theo thuyết tiến hóa tổng hợp hiện đại, đơn vị tiến hóa cơ sở nhỏ nhất có thể biến đổi tần số allele qua thời gian là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Toàn bộ loài sinh vật trên Trái Đất"}, {"id": "b", "text": "Quần thể"}, {"id": "c", "text": "Cá thể sinh vật đơn lẻ"}], "correctOptionId": "b", "explanation": "Cá thể không tiến hóa vì hệ gene không đổi; quần thể với vốn gene biến đổi qua các thế hệ giao phối mới là đơn vị tiến hóa cơ sở."}, {"id": "biology-12-modern-evolution-synthesis-q2", "prompt": "Nhân tố tiến hóa nào sau đây có vai trò định hướng quá trình tiến hóa bằng cách quy định chiều hướng và tốc độ biến đổi tần số allele?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chọn lọc tự nhiên"}, {"id": "b", "text": "Đột biến gene ngẫu nhiên"}, {"id": "c", "text": "Giao phối không ngẫu nhiên"}], "correctOptionId": "a", "explanation": "Chỉ có chọn lọc tự nhiên giữ lại các kiểu hình thích nghi và đào thải kiểu hình có hại, do đó có vai trò định hướng tiến hóa."}, {"id": "biology-12-natural-selection-q1", "prompt": "Chọn lọc tự nhiên tác động trực tiếp lên cấp độ nào của sinh vật trong tự nhiên?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cấp độ kiểu hình của từng cá thể sinh vật"}, {"id": "b", "text": "Trực tiếp lên từng nucleotide của phân tử DNA trong nhân"}, {"id": "c", "text": "Chỉ tác động lên các tế bào sinh dục đơn lẻ"}], "correctOptionId": "a", "explanation": "Ngoại cảnh tương tác trực tiếp với kiểu hình (hình thái, sinh lí); các kiểu hình thích nghi sống sót sẽ truyền kiểu gene cho thế hệ sau."}, {"id": "biology-12-natural-selection-q2", "prompt": "Hiện tượng vi khuẩn kháng thuốc kháng sinh phát triển nhanh chóng sau một thời gian dài sử dụng thuốc trong y tế được giải thích bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thuốc kháng sinh trực tiếp kích thích vi khuẩn tự tạo ra các gene kháng thuốc mới"}, {"id": "b", "text": "Vi khuẩn học tập được cách phân hủy thuốc kháng sinh để lấy năng lượng"}, {"id": "c", "text": "Thuốc kháng sinh đóng vai trò nhân tố chọn lọc, giữ lại và nhân lên các vi khuẩn mang đột biến kháng thuốc"}], "correctOptionId": "c", "explanation": "Đột biến kháng thuốc có sẵn ngẫu nhiên trong quần thể vi khuẩn; thuốc kháng sinh diệt vi khuẩn mẫn cảm, tạo ưu thế cho chủng kháng sinh sản nhanh."}, {"id": "biology-12-speciation-q1", "prompt": "Tiêu chuẩn cơ bản và quan trọng nhất để phân biệt hai loài sinh sản hữu tính thân thuộc trong tự nhiên là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tiêu chuẩn hình thái học bên ngoài"}, {"id": "b", "text": "Tiêu chuẩn màu sắc nơi cư trú"}, {"id": "c", "text": "Tiêu chuẩn cách li sinh sản"}], "correctOptionId": "c", "explanation": "Khái niệm loài sinh học dựa trên sự cách li sinh sản: nếu hai quần thể không giao phối hoặc con lai bất thụ thì chúng thuộc hai loài khác nhau."}, {"id": "biology-12-speciation-q2", "prompt": "Ngựa (2n = 64) lai với lừa (2n = 62) sinh ra con la (2n = 63) hoàn toàn bất thụ. Đây là ví dụ về cơ chế cách li sinh sản nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cách li sinh thái do không gặp nhau"}, {"id": "b", "text": "Cách li sau hợp tử (bất thụ con lai)"}, {"id": "c", "text": "Cách li trước hợp tử về mặt cơ học"}], "correctOptionId": "b", "explanation": "Con la hình thành từ thụ tinh nhưng bộ NST cọc cạch không giảm phân được, con lai bất thụ thuộc cơ chế cách li sau hợp tử."}, {"id": "biology-12-origin-of-life-q1", "prompt": "Thí nghiệm nổi tiếng năm 1953 của Stanley Miller và Harold Urey đã chứng minh điều gì về nguồn gốc sự sống?", "difficulty": "EASY", "options": [{"id": "a", "text": "Phân tử DNA là dạng vật chất di truyền đầu tiên xuất hiện trên Trái Đất"}, {"id": "b", "text": "Các hợp chất hữu cơ đơn giản có thể được hình thành từ các chất vô cơ trong điều kiện khí quyển nguyên thủy"}, {"id": "c", "text": "Tế bào sống nguyên thủy có thể tự lắp ráp hoàn chỉnh chỉ trong 24 giờ"}], "correctOptionId": "b", "explanation": "Thí nghiệm mô phỏng phóng điện qua khí quyển nguyên thủy khử tạo ra các amino acid, chứng minh bước tiến hóa hóa học là hoàn toàn khả thi."}, {"id": "biology-12-origin-of-life-q2", "prompt": "Đại địa chất nào sau đây được gọi là ''Kỉ nguyên của các loài bò sát'' và chứng kiến sự thống trị của các loài khủng long?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đại Trung sinh (Mesozoic)"}, {"id": "b", "text": "Đại Cổ sinh (Paleozoic)"}, {"id": "c", "text": "Đại Tân sinh (Cenozoic)"}], "correctOptionId": "a", "explanation": "Đại Trung sinh gồm kỉ Trias, Jura và Creta là thời kì bò sát khổng lồ (khủng long) phát triển cực thịnh và tuyệt diệt vào cuối kỉ Creta."}, {"id": "biology-12-ecological-factors-q1", "prompt": "Giới hạn sinh thái của một loài đối với một nhân tố sinh thái nhất định được định nghĩa là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Khoảng giá trị xác định của nhân tố sinh thái mà trong đó sinh vật có thể tồn tại và phát triển ổn định"}, {"id": "b", "text": "Điểm nhiệt độ cao nhất mà sinh vật bắt đầu bị chết"}, {"id": "c", "text": "Toàn bộ các nhân tố môi trường tác động đồng thời lên sinh vật"}], "correctOptionId": "a", "explanation": "Giới hạn sinh thái là giới hạn chịu đựng của loài đối với một nhân tố sinh thái (giữa giới hạn dưới và giới hạn trên)."}, {"id": "biology-12-ecological-factors-q2", "prompt": "Nhóm nhân tố sinh thái nào sau đây thuộc nhóm nhân tố sinh thái hữu sinh?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Độ pH và lượng oxy hòa tan trong nước ao"}, {"id": "b", "text": "Ánh sáng mặt trời và nhiệt độ không khí"}, {"id": "c", "text": "Mối quan hệ cạnh tranh thức ăn giữa các loài động vật trong rừng"}], "correctOptionId": "c", "explanation": "Nhân tố hữu sinh là thế giới sống xung quanh sinh vật bao gồm các sinh vật khác và mối quan hệ giữa chúng, cũng như con người."}, {"id": "biology-12-population-ecology-q1", "prompt": "Đặc trưng cơ bản quan trọng nhất ảnh hưởng trực tiếp đến mức độ sử dụng nguồn sống và khả năng sinh sản của quần thể là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tỉ lệ giới tính ở nhóm tuổi già"}, {"id": "b", "text": "Màu sắc bộ lông của các cá thể non"}, {"id": "c", "text": "Mật độ cá thể trong quần thể"}], "correctOptionId": "c", "explanation": "Mật độ (số cá thể trên đơn vị diện tích/thể tích) quyết định mức độ cạnh tranh, khả năng tìm kiếm thức ăn và bạn tình."}, {"id": "biology-12-population-ecology-q2", "prompt": "Trong điều kiện môi trường sống bị giới hạn về không gian và nguồn thức ăn, đường cong tăng trưởng số lượng của quần thể sinh vật trong tự nhiên có dạng hình chữ gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đường thẳng nằm ngang không đổi"}, {"id": "b", "text": "Hình chữ S (tăng trưởng logistic tiệm cận sức chứa K)"}, {"id": "c", "text": "Hình chữ J tăng trưởng theo hàm mũ vô hạn"}], "correctOptionId": "b", "explanation": "Nguồn sống giới hạn làm mức sinh giảm và mức tử tăng khi kích thước quần thể tiến tới sức chứa tối đa K của môi trường, tạo đường cong chữ S."}, {"id": "biology-12-community-ecology-q1", "prompt": "Mối quan hệ sinh thái chặt chẽ giữa hai loài sinh vật trong đó cả hai bên cùng có lợi và không thể tách rời nhau gọi là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Quan hệ kí sinh (parasitism)"}, {"id": "b", "text": "Quan hệ cộng sinh (mutualism)"}, {"id": "c", "text": "Quan hệ hội sinh (commensalism)"}], "correctOptionId": "b", "explanation": "Cộng sinh là quan hệ bắt buộc giữa hai loài, cả hai đều có lợi và sống phụ thuộc vào nhau (như nấm và vi khuẩn lam trong địa y)."}, {"id": "biology-12-community-ecology-q2", "prompt": "Hiện tượng diễn thế sinh thái khởi đầu từ một môi trường trống trơn (như đảo tro tàn núi lửa mới hình thành) gọi là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Diễn thế nguyên sinh"}, {"id": "b", "text": "Diễn thế thứ sinh"}, {"id": "c", "text": "Diễn thế thoái hóa"}], "correctOptionId": "a", "explanation": "Diễn thế nguyên sinh bắt đầu từ môi trường chưa từng có quần xã sinh vật nào sinh sống trước đó."}, {"id": "biology-12-ecosystem-matter-energy-q1", "prompt": "Trong cấu trúc thành phần sinh học của một hệ sinh thái, sinh vật nào sau đây đóng vai trò là sinh vật sản xuất sơ cấp?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cây xanh và vi khuẩn lam quang hợp"}, {"id": "b", "text": "Động vật ăn cỏ như trâu bò"}, {"id": "c", "text": "Nấm mốc và vi khuẩn hoại sinh trong đất"}], "correctOptionId": "a", "explanation": "Sinh vật sản xuất sơ cấp tự tổng hợp chất hữu cơ từ năng lượng ánh sáng mặt trời hoặc năng lượng hóa học."}, {"id": "biology-12-ecosystem-matter-energy-q2", "prompt": "Dòng năng lượng trong một hệ sinh thái tự nhiên có đặc điểm căn bản nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Luôn tuần hoàn khép kín 100% quay trở lại sinh vật sản xuất"}, {"id": "b", "text": "Càng lên bậc dinh dưỡng cao năng lượng tích lũy càng tăng vọt"}, {"id": "c", "text": "Di chuyển theo một chiều qua các bậc dinh dưỡng và tiêu hao dần dưới dạng nhiệt"}], "correctOptionId": "c", "explanation": "Năng lượng đi vào hệ sinh thái một chiều và tỏa nhiệt qua hô hấp, bài tiết ở từng bậc dinh dưỡng chứ không tuần hoàn."}, {"id": "biology-12-biosphere-conservation-q1", "prompt": "Nhóm vi sinh vật nào có khả năng biến đổi khí nitrogen tự do (N2) trong khí quyển thành dạng ion ammonium (NH4+) cây có thể hấp thụ được?", "difficulty": "EASY", "options": [{"id": "a", "text": "Vi khuẩn phản nitrat hóa phân giải đạm"}, {"id": "b", "text": "Các loại nấm men làm bánh mì"}, {"id": "c", "text": "Vi khuẩn cố định đạm (như Rhizobium sống cộng sinh trong nốt sần cây họ Đậu)"}], "correctOptionId": "c", "explanation": "Nhờ enzyme nitrogenase, vi khuẩn cố định đạm phá vỡ liên kết ba N≡N để cố định nitrogen thành dạng hợp chất hữu dụng cho thực vật."}, {"id": "biology-12-biosphere-conservation-q2", "prompt": "Biện pháp bảo tồn đa dạng sinh học nào sau đây là hình thức bảo tồn tại chỗ (in-situ conservation)?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chuyển các loài động vật quý hiếm vào nuôi nhốt trong vườn bách thú"}, {"id": "b", "text": "Thành lập các vườn quốc gia và khu dự trữ sinh quyển thiên nhiên"}, {"id": "c", "text": "Thu thập hạt giống đưa vào bảo quản đông lạnh trong ngân hàng gene"}], "correctOptionId": "b", "explanation": "Bảo tồn tại chỗ bảo vệ loài sinh vật ngay tại môi trường sống tự nhiên vốn có của chúng trong các vườn quốc gia, khu bảo tồn."}]'::jsonb,'[]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-dna-replication',1,'LESSON','Cấu trúc và tái bản DNA','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["DNA gồm hai chuỗi polynucleotide xoắn kép, ngược chiều (5''-3'' và 3''-5''), liên kết hydro theo nguyên tắc bổ sung (A-T 2 liên kết, G-C 3 liên kết). Tái bản theo nguyên tắc bán bảo toàn và nguyên tắc bổ sung. Enzyme DNA polymerase xúc tác kéo dài chuỗi theo chiều 5'' → 3''."]'::jsonb,'["Phân tử DNA ban đầu mang đồng vị phóng xạ N-15, nhân đôi 3 lần trong môi trường N-14 tạo ra 8 phân tử DNA con, trong đó có đúng 2 phân tử chứa một mạch N-15 và một mạch N-14."]'::jsonb,'[{"id": "biology-12-dna-replication-q1", "prompt": "Nguyên tắc bán bảo toàn trong quá trình tái bản DNA có nghĩa là gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Mỗi phân tử DNA con tạo ra gồm một mạch cũ của mẹ và một mạch mới tổng hợp"}, {"id": "b", "text": "Hai phân tử DNA con đều gồm toàn bộ các nucleotide hoàn toàn mới"}, {"id": "c", "text": "Toàn bộ phân tử DNA mẹ được giữ nguyên vẹn ở một tế bào con"}], "correctOptionId": "a", "explanation": "Bán bảo toàn nghĩa là giữ lại một nửa: mỗi phân tử DNA con chứa một mạch gốc từ phân tử mẹ và một mạch mới."}, {"id": "biology-12-dna-replication-q2", "prompt": "Enzyme DNA polymerase xúc tác gắn các nucleotide tự do vào đầu nào của chuỗi polynucleotide đang tổng hợp?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đầu 5''-phosphate tự do (tổng hợp theo chiều 3'' → 5'')"}, {"id": "b", "text": "Có thể gắn ngẫu nhiên vào cả hai đầu 3'' và 5'' cùng lúc"}, {"id": "c", "text": "Đầu 3''-OH tự do (tổng hợp theo chiều 5'' → 3'')"}], "correctOptionId": "c", "explanation": "DNA polymerase chỉ có thể gắn nucleotide vào nhóm 3''-OH tự do nên chuỗi mới luôn kéo dài theo chiều 5'' -> 3''."}, {"id": "biology-12-dna-replication-q3", "prompt": "Một đoạn phân tử DNA nhân đôi liên tiếp 4 lần trong môi trường chứa nucleotide tự do đánh dấu phóng xạ. Số mạch đơn mang chất phóng xạ trong tổng số mạch đơn DNA tạo thành là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "32 mạch mang phóng xạ"}, {"id": "b", "text": "30 mạch mang phóng xạ"}, {"id": "c", "text": "16 mạch mang phóng xạ"}], "correctOptionId": "b", "explanation": "4 lần nhân đôi tạo 2⁴ = 16 phân tử DNA = 32 mạch đơn. Chỉ có 2 mạch đơn ban đầu không phóng xạ, vậy số mạch mang phóng xạ là 32 - 2 = 30 mạch."}]'::jsonb,'["biology-12-dna-replication"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-transcription',2,'LESSON','Phiên mã và cơ chế tổng hợp RNA','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Phiên mã là quá trình tổng hợp RNA từ mạch khuôn DNA (chiều 3'' → 5'') do enzyme RNA polymerase xúc tác theo nguyên tắc bổ sung (A-U, T-A, G-C, C-G). Ở sinh vật nhân thực, phân tử pre-mRNA phải qua cắt bỏ intron và nối exon tạo mRNA trưởng thành."]'::jsonb,'["Mạch khuôn DNA có trình tự 3''-TAC GGC TTA-5'' thì phân tử mRNA được tổng hợp có trình tự tương ứng là 5''-AUG CCG AAU-3''."]'::jsonb,'[{"id": "biology-12-transcription-q1", "prompt": "Phân tử enzyme trực tiếp xúc tác quá trình tháo xoắn và tổng hợp mạch RNA trong phiên mã là:", "difficulty": "EASY", "options": [{"id": "a", "text": "DNA polymerase"}, {"id": "b", "text": "Enzyme ligase nối mạch"}, {"id": "c", "text": "RNA polymerase"}], "correctOptionId": "c", "explanation": "RNA polymerase tự tháo xoắn DNA và liên kết các ribonucleotide tự do tương ứng với mạch khuôn DNA."}, {"id": "biology-12-transcription-q2", "prompt": "Mạch khuôn của gene được enzyme phiên mã sử dụng để tổng hợp phân tử mRNA có chiều:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cả hai mạch đều được dùng làm khuôn đồng thời"}, {"id": "b", "text": "Chiều 3'' → 5''"}, {"id": "c", "text": "Chiều 5'' → 3''"}], "correctOptionId": "b", "explanation": "Mạch khuôn của gene có chiều 3'' -> 5'' để phân tử RNA sinh ra kéo dài theo chiều 5'' -> 3''."}, {"id": "biology-12-transcription-q3", "prompt": "Điểm khác biệt quan trọng trong quá trình hoàn thiện mRNA ở sinh vật nhân thực so với nhân sơ là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Phân tử pre-mRNA phải trải qua quá trình cắt bỏ các đoạn intron và nối các đoạn exon"}, {"id": "b", "text": "mRNA nhân thực không cần codon mở đầu để dịch mã"}, {"id": "c", "text": "Quá trình phiên mã ở sinh vật nhân thực diễn ra ngay ngoài màng tế bào"}], "correctOptionId": "a", "explanation": "Gene nhân thực là gene phân mảnh (gồm exon có mã hóa và intron không mã hóa), mRNA sơ khai phải cắt intron nối exon trước khi ra tế bào chất."}]'::jsonb,'["biology-12-transcription"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-translation',3,'LESSON','Mã di truyền và dịch mã','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Mã di truyền là mã bộ ba (64 codon, trong đó 61 codon mã hóa 20 loại amino acid, 3 codon kết thúc UAA, UAG, UGA; codon mở đầu 5''-AUG-3'' mã hóa Methionine ở nhân thực). Dịch mã diễn ra tại ribosome qua hai giai đoạn: hoạt hóa amino acid và tổng hợp chuỗi polypeptide."]'::jsonb,'["Codon 5''-AUG-3'' trên mRNA khớp bổ sung với anticodon 3''-UAC-5'' trên tRNA mang amino acid mở đầu."]'::jsonb,'[{"id": "biology-12-translation-q1", "prompt": "Đặc điểm thoái hóa (dư thừa) của mã di truyền có nghĩa là gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Mã di truyền bị suy giảm chất lượng qua các thế hệ tế bào"}, {"id": "b", "text": "Nhiều bộ ba codon khác nhau có thể cùng mã hóa cho một loại amino acid"}, {"id": "c", "text": "Một bộ ba codon có thể mã hóa cho nhiều loại amino acid khác nhau"}], "correctOptionId": "b", "explanation": "Tính thoái hóa: 61 codon chỉ mã hóa 20 loại amino acid, do đó nhiều codon cùng chỉ định một amino acid (trừ AUG và UGG)."}, {"id": "biology-12-translation-q2", "prompt": "Codon nào sau đây trên phân tử mRNA đóng vai trò là tín hiệu bắt đầu dịch mã (codon mở đầu)?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "5''-AUG-3''"}, {"id": "b", "text": "5''-UAA-3''"}, {"id": "c", "text": "5''-UGA-3''"}], "correctOptionId": "a", "explanation": "5''-AUG-3'' là codon mở đầu duy nhất trên mRNA, mã hóa Methionine ở nhân thực (hoặc fMet ở nhân sơ)."}, {"id": "biology-12-translation-q3", "prompt": "Trong quá trình dịch mã, hiện tượng polysome (nhiều ribosome cùng trượt trên một phân tử mRNA) có ý nghĩa sinh học gì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Giúp tế bào tổng hợp được nhiều loại protein hoàn toàn khác nhau cùng lúc"}, {"id": "b", "text": "Sửa chữa các đột biến nucleotide xảy ra trên phân tử mRNA"}, {"id": "c", "text": "Tăng hiệu suất tổng hợp cùng một loại chuỗi polypeptide cần thiết trong thời gian ngắn"}], "correctOptionId": "c", "explanation": "Nhiều ribosome nối tiếp dịch mã trên 1 mRNA giúp nhân bản nhanh nhiều phân tử của cùng một loại protein."}]'::jsonb,'["biology-12-translation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-gene-regulation',4,'LESSON','Điều hòa biểu hiện gene','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Mô hình Operon Lac ở vi khuẩn E. coli gồm: vùng khởi động P (RNA polymerase bám), vùng vận hành O (protein ức chế bám), và cụm gene cấu trúc Z, Y, A. Gene điều hòa R liên tục tổng hợp protein ức chế. Khi môi trường có lactose, lactose bám làm biến tính protein ức chế, giải phóng vùng O cho phiên mã."]'::jsonb,'["Khi có đường lactose, phân tử allolactose đóng vai trò chất cảm ứng làm thay đổi cấu hình không gian của protein ức chế, khiến nó không gắn được vào vùng O."]'::jsonb,'[{"id": "biology-12-gene-regulation-q1", "prompt": "Trong cấu trúc của Operon Lac ở vi khuẩn E. coli, vùng vận hành (operator - O) là nơi:", "difficulty": "EASY", "options": [{"id": "a", "text": "Protein ức chế liên kết để ngăn cản quá trình phiên mã"}, {"id": "b", "text": "Enzyme RNA polymerase bám vào để khởi động phiên mã"}, {"id": "c", "text": "Chứa mã di truyền quy định cấu trúc của enzyme phân giải đường"}], "correctOptionId": "a", "explanation": "Vùng vận hành O là vị trí gắn của protein ức chế; khi bị chặn, RNA polymerase không thể trượt qua phiên mã."}, {"id": "biology-12-gene-regulation-q2", "prompt": "Khi môi trường sống của vi khuẩn E. coli có đường lactose, sự kiện nào sau đây xảy ra?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Gene điều hòa R ngừng hoàn toàn quá trình phiên mã tạo protein"}, {"id": "b", "text": "Vùng khởi động P bị phân hủy bởi các enzyme trong tế bào chất"}, {"id": "c", "text": "Phân tử lactose liên kết làm biến đổi cấu hình protein ức chế khiến nó không bám được vào vùng O"}], "correctOptionId": "c", "explanation": "Lactose đóng vai trò chất cảm ứng gắn vào protein ức chế làm nó mất khả năng bám vùng vận hành, mở đường cho phiên mã."}, {"id": "biology-12-gene-regulation-q3", "prompt": "Một đột biến xảy ra ở vùng vận hành (O) của Operon Lac làm vùng này mất khả năng liên kết với protein ức chế. Hậu quả kiểu hình phân tử là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Vi khuẩn lập tức bị chết do không tổng hợp được màng tế bào"}, {"id": "b", "text": "Các gene cấu trúc Z, Y, A phiên mã liên tục ngay cả khi môi trường không có lactose"}, {"id": "c", "text": "Các gene cấu trúc Z, Y, A không bao giờ được phiên mã trong mọi điều kiện"}], "correctOptionId": "b", "explanation": "Do protein ức chế không thể bám vào O để chặn, RNA polymerase tự do phiên mã liên tục các gene Z, Y, A."}]'::jsonb,'["biology-12-gene-regulation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-gene-mutation',5,'LESSON','Đột biến gene','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Đột biến gene là những biến đổi trong cấu trúc của gene liên quan đến một hoặc một số cặp nucleotide (đột biến điểm: thay thế, thêm, mất một cặp nucleotide). Đột biến thay thế có thể là đồng nghĩa (câm), sai nghĩa (đổi amino acid), hoặc vô nghĩa (tạo codon kết thúc sớm). Đột biến thêm hoặc mất gây dịch khung đọc mã."]'::jsonb,'["Bệnh hồng cầu hình liềm do đột biến thay thế cặp T-A bằng A-T ở codon thứ 6 của chuỗi beta-hemoglobin, biến acid glutamic thành valine."]'::jsonb,'[{"id": "biology-12-gene-mutation-q1", "prompt": "Dạng đột biến điểm nào sau đây KHÔNG làm thay đổi số lượng liên kết hydro của gene?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đột biến thay thế cặp A-T bằng cặp G-C"}, {"id": "b", "text": "Đột biến mất một cặp A-T"}, {"id": "c", "text": "Đột biến thay thế cặp A-T bằng cặp T-A"}], "correctOptionId": "c", "explanation": "Cặp A-T và T-A đều có 2 liên kết hydro, nên đảo chiều thay thế A-T bằng T-A không làm thay đổi tổng số liên kết hydro."}, {"id": "biology-12-gene-mutation-q2", "prompt": "Đột biến gene xảy ra làm xuất hiện một bộ ba kết thúc sớm ở đoạn đầu của vùng mã hóa sẽ dẫn tới hậu quả:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hoàn toàn không ảnh hưởng gì tới hoạt tính sinh học của protein"}, {"id": "b", "text": "Quá trình dịch mã dừng sớm tạo ra chuỗi polypeptide ngắn bất thường và mất chức năng"}, {"id": "c", "text": "Làm tăng gấp đôi chiều dài của phân tử protein được tổng hợp"}], "correctOptionId": "b", "explanation": "Đột biến vô nghĩa (nonsense) tạo codon kết thúc sớm làm ribosome dừng dịch mã ngay, sinh ra chuỗi polypeptide cụt ngắn."}, {"id": "biology-12-gene-mutation-q3", "prompt": "Tác nhân hóa học 5-bromouracil (5-BU) là đồng đẳng của thymine thường gây ra dạng đột biến thay thế nào qua các chu kì tái bản DNA?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Thay thế cặp A-T bằng cặp G-C"}, {"id": "b", "text": "Thay thế cặp G-C bằng cặp A-T"}, {"id": "c", "text": "Mất hẳn một cặp nucleotide bất kì"}], "correctOptionId": "a", "explanation": "5-BU bắt cặp với A ở dạng thường, sau đó chuyển sang dạng hiếm bắt cặp với G, qua 3 lần tái bản dẫn đến thay thế A-T thành G-C."}]'::jsonb,'["biology-12-gene-mutation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-review-1',6,'FIVE_LESSON_REVIEW','Ôn tập 1','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "biology-12-dna-replication-q1", "prompt": "Nguyên tắc bán bảo toàn trong quá trình tái bản DNA có nghĩa là gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Mỗi phân tử DNA con tạo ra gồm một mạch cũ của mẹ và một mạch mới tổng hợp"}, {"id": "b", "text": "Hai phân tử DNA con đều gồm toàn bộ các nucleotide hoàn toàn mới"}, {"id": "c", "text": "Toàn bộ phân tử DNA mẹ được giữ nguyên vẹn ở một tế bào con"}], "correctOptionId": "a", "explanation": "Bán bảo toàn nghĩa là giữ lại một nửa: mỗi phân tử DNA con chứa một mạch gốc từ phân tử mẹ và một mạch mới."}, {"id": "biology-12-dna-replication-q2", "prompt": "Enzyme DNA polymerase xúc tác gắn các nucleotide tự do vào đầu nào của chuỗi polynucleotide đang tổng hợp?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đầu 5''-phosphate tự do (tổng hợp theo chiều 3'' → 5'')"}, {"id": "b", "text": "Có thể gắn ngẫu nhiên vào cả hai đầu 3'' và 5'' cùng lúc"}, {"id": "c", "text": "Đầu 3''-OH tự do (tổng hợp theo chiều 5'' → 3'')"}], "correctOptionId": "c", "explanation": "DNA polymerase chỉ có thể gắn nucleotide vào nhóm 3''-OH tự do nên chuỗi mới luôn kéo dài theo chiều 5'' -> 3''."}, {"id": "biology-12-transcription-q1", "prompt": "Phân tử enzyme trực tiếp xúc tác quá trình tháo xoắn và tổng hợp mạch RNA trong phiên mã là:", "difficulty": "EASY", "options": [{"id": "a", "text": "DNA polymerase"}, {"id": "b", "text": "Enzyme ligase nối mạch"}, {"id": "c", "text": "RNA polymerase"}], "correctOptionId": "c", "explanation": "RNA polymerase tự tháo xoắn DNA và liên kết các ribonucleotide tự do tương ứng với mạch khuôn DNA."}, {"id": "biology-12-transcription-q2", "prompt": "Mạch khuôn của gene được enzyme phiên mã sử dụng để tổng hợp phân tử mRNA có chiều:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cả hai mạch đều được dùng làm khuôn đồng thời"}, {"id": "b", "text": "Chiều 3'' → 5''"}, {"id": "c", "text": "Chiều 5'' → 3''"}], "correctOptionId": "b", "explanation": "Mạch khuôn của gene có chiều 3'' -> 5'' để phân tử RNA sinh ra kéo dài theo chiều 5'' -> 3''."}, {"id": "biology-12-translation-q1", "prompt": "Đặc điểm thoái hóa (dư thừa) của mã di truyền có nghĩa là gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Mã di truyền bị suy giảm chất lượng qua các thế hệ tế bào"}, {"id": "b", "text": "Nhiều bộ ba codon khác nhau có thể cùng mã hóa cho một loại amino acid"}, {"id": "c", "text": "Một bộ ba codon có thể mã hóa cho nhiều loại amino acid khác nhau"}], "correctOptionId": "b", "explanation": "Tính thoái hóa: 61 codon chỉ mã hóa 20 loại amino acid, do đó nhiều codon cùng chỉ định một amino acid (trừ AUG và UGG)."}, {"id": "biology-12-translation-q2", "prompt": "Codon nào sau đây trên phân tử mRNA đóng vai trò là tín hiệu bắt đầu dịch mã (codon mở đầu)?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "5''-AUG-3''"}, {"id": "b", "text": "5''-UAA-3''"}, {"id": "c", "text": "5''-UGA-3''"}], "correctOptionId": "a", "explanation": "5''-AUG-3'' là codon mở đầu duy nhất trên mRNA, mã hóa Methionine ở nhân thực (hoặc fMet ở nhân sơ)."}, {"id": "biology-12-gene-regulation-q1", "prompt": "Trong cấu trúc của Operon Lac ở vi khuẩn E. coli, vùng vận hành (operator - O) là nơi:", "difficulty": "EASY", "options": [{"id": "a", "text": "Protein ức chế liên kết để ngăn cản quá trình phiên mã"}, {"id": "b", "text": "Enzyme RNA polymerase bám vào để khởi động phiên mã"}, {"id": "c", "text": "Chứa mã di truyền quy định cấu trúc của enzyme phân giải đường"}], "correctOptionId": "a", "explanation": "Vùng vận hành O là vị trí gắn của protein ức chế; khi bị chặn, RNA polymerase không thể trượt qua phiên mã."}, {"id": "biology-12-gene-regulation-q2", "prompt": "Khi môi trường sống của vi khuẩn E. coli có đường lactose, sự kiện nào sau đây xảy ra?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Gene điều hòa R ngừng hoàn toàn quá trình phiên mã tạo protein"}, {"id": "b", "text": "Vùng khởi động P bị phân hủy bởi các enzyme trong tế bào chất"}, {"id": "c", "text": "Phân tử lactose liên kết làm biến đổi cấu hình protein ức chế khiến nó không bám được vào vùng O"}], "correctOptionId": "c", "explanation": "Lactose đóng vai trò chất cảm ứng gắn vào protein ức chế làm nó mất khả năng bám vùng vận hành, mở đường cho phiên mã."}, {"id": "biology-12-gene-mutation-q1", "prompt": "Dạng đột biến điểm nào sau đây KHÔNG làm thay đổi số lượng liên kết hydro của gene?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đột biến thay thế cặp A-T bằng cặp G-C"}, {"id": "b", "text": "Đột biến mất một cặp A-T"}, {"id": "c", "text": "Đột biến thay thế cặp A-T bằng cặp T-A"}], "correctOptionId": "c", "explanation": "Cặp A-T và T-A đều có 2 liên kết hydro, nên đảo chiều thay thế A-T bằng T-A không làm thay đổi tổng số liên kết hydro."}, {"id": "biology-12-gene-mutation-q2", "prompt": "Đột biến gene xảy ra làm xuất hiện một bộ ba kết thúc sớm ở đoạn đầu của vùng mã hóa sẽ dẫn tới hậu quả:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hoàn toàn không ảnh hưởng gì tới hoạt tính sinh học của protein"}, {"id": "b", "text": "Quá trình dịch mã dừng sớm tạo ra chuỗi polypeptide ngắn bất thường và mất chức năng"}, {"id": "c", "text": "Làm tăng gấp đôi chiều dài của phân tử protein được tổng hợp"}], "correctOptionId": "b", "explanation": "Đột biến vô nghĩa (nonsense) tạo codon kết thúc sớm làm ribosome dừng dịch mã ngay, sinh ra chuỗi polypeptide cụt ngắn."}]'::jsonb,'["biology-12-dna-replication", "biology-12-transcription", "biology-12-translation", "biology-12-gene-regulation", "biology-12-gene-mutation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-mendelian-genetics',7,'LESSON','Các quy luật di truyền Mendel','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Quy luật phân li: mỗi tính trạng do một cặp allele quy định, trong giảm phân các allele phân li đồng đều về các giao tử. Quy luật phân li độc lập: các cặp allele trên các cặp NST tương đồng khác nhau phân li độc lập trong quá trình hình thành giao tử. Tỉ lệ F2 ở phép lai 2 tính trạng độc lập: 9:3:3:1."]'::jsonb,'["P: AaBb × AaBb cho F1 có tỉ lệ kiểu hình: 9 A-B- : 3 A-bb : 3 aaB- : 1 aabb = (3:1)(3:1)."]'::jsonb,'[{"id": "biology-12-mendelian-genetics-q1", "prompt": "Cơ sở tế bào học trực tiếp của quy luật phân li độc lập theo quan điểm di truyền học hiện đại là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Sự nhân đôi đồng thời của các phân tử DNA ở pha S của chu kì tế bào"}, {"id": "b", "text": "Sự phân li độc lập và tổ hợp ngẫu nhiên của các cặp nhiễm sắc thể tương đồng trong giảm phân"}, {"id": "c", "text": "Sự tiếp hợp và trao đổi chéo giữa các chromatid chị em trong nguyên phân"}], "correctOptionId": "b", "explanation": "Các cặp gene nằm trên các cặp NST tương đồng khác nhau phân li độc lập khi các cặp NST này phân li ngẫu nhiên về hai cực tế bào ở kì sau I."}, {"id": "biology-12-mendelian-genetics-q2", "prompt": "Cho phép lai P: AaBb × aabb (lai phân tích hai cặp gene phân li độc lập). Tỉ lệ phân li kiểu hình ở đời con Fa là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "1 : 1 : 1 : 1"}, {"id": "b", "text": "9 : 3 : 3 : 1"}, {"id": "c", "text": "3 : 3 : 1 : 1"}], "correctOptionId": "a", "explanation": "Cơ thể AaBb cho 4 loại giao tử với tỉ lệ 1/4 AB : 1/4 Ab : 1/4 aB : 1/4 ab; cơ thể aabb cho 1 loại giao tử ab. Con lai phân tích có tỉ lệ kiểu hình 1:1:1:1."}, {"id": "biology-12-mendelian-genetics-q3", "prompt": "Trong một phép lai P: AaBbDd × AaBbDd (3 cặp gene nằm trên 3 cặp NST khác nhau, tính trạng trội hoàn toàn). Tỉ lệ cá thể mang kiểu hình có ít nhất một tính trạng lặn ở đời F1 là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "27/64"}, {"id": "b", "text": "1/64"}, {"id": "c", "text": "37/64"}], "correctOptionId": "c", "explanation": "Tỉ lệ cá thể mang toàn tính trạng trội (A-B-D-) là (3/4)*(3/4)*(3/4) = 27/64. Tỉ lệ cá thể có ít nhất một tính trạng lặn = 1 - 27/64 = 37/64."}]'::jsonb,'["biology-12-mendelian-genetics"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-linkage-crossing-over',8,'LESSON','Liên kết gene và hoán vị gene','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Các gene trên cùng một nhiễm sắc thể di truyền cùng nhau tạo thành nhóm gene liên kết (số nhóm liên kết bằng số NST đơn bội n). Hoán vị gene do sự trao đổi chéo giữa hai chromatid khác nguồn gốc ở kì đầu giảm phân I. Tần số hoán vị gene f ≤ 50%, tỉ lệ thuận với khoảng cách giữa hai locus gene trên NST (1% hoán vị = 1 cM)."]'::jsonb,'["Ruồi giấm cái thân xám, cánh dài dị hợp chéo lai với đực thân đen, cánh cụt cho đời con có 4 kiểu hình với tần số hoán vị f = 17%."]'::jsonb,'[{"id": "biology-12-linkage-crossing-over-q1", "prompt": "Hiện tượng hoán vị gene xảy ra do cơ chế tiếp hợp và trao đổi chéo giữa các đoạn chromatid ở kì nào của quá trình phân bào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Kì đầu của giảm phân I"}, {"id": "b", "text": "Kì giữa của giảm phân II"}, {"id": "c", "text": "Kì sau của nguyên phân"}], "correctOptionId": "a", "explanation": "Sự tiếp hợp và trao đổi chéo giữa các chromatid khác nguồn gốc của cặp NST tương đồng xảy ra ở kì đầu I của giảm phân."}, {"id": "biology-12-linkage-crossing-over-q2", "prompt": "Tần số hoán vị gene giữa hai locus gene trên cùng một nhiễm sắc thể:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Luôn bằng đúng 100% ở mọi loài sinh vật"}, {"id": "b", "text": "Luôn lớn hơn 75% đối với các gene liên kết xa nhau"}, {"id": "c", "text": "Không bao giờ vượt quá 50%"}], "correctOptionId": "c", "explanation": "Trao đổi chéo chỉ xảy ra giữa 2 trong 4 chromatid của thể tứ tử, tối đa 50% số giao tử tạo ra là giao tử hoán vị (f ≤ 50%)."}, {"id": "biology-12-linkage-crossing-over-q3", "prompt": "Ở một loài thực vật, lai phân tích cây dị hợp 2 cặp gene thu được đời con gồm: 40% cây cao, hoa đỏ; 40% cây thấp, hoa trắng; 10% cây cao, hoa trắng; 10% cây thấp, hoa đỏ. Tần số hoán vị gene là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "40%"}, {"id": "b", "text": "20%"}, {"id": "c", "text": "10%"}], "correctOptionId": "b", "explanation": "Các kiểu hình hoán vị (chiếm tỉ lệ nhỏ hơn 25%) là cao, hoa trắng (10%) và thấp, hoa đỏ (10%). Tần số hoán vị f = 10% + 10% = 20%."}]'::jsonb,'["biology-12-linkage-crossing-over"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-sex-linked-inheritance',9,'LESSON','Di truyền liên kết với giới tính','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Nhiễm sắc thể giới tính (XX/XY ở người, thú, ruồi giấm; ZZ/ZW ở chim, bướm, bò sát). Di truyền chéo: gene trên vùng không tương đồng của NST X di truyền từ bố cho con gái, từ mẹ cho con trai. Di truyền thẳng: gene trên vùng không tương đồng của NST Y truyền 100% cho giới dị giao tử (nam)."]'::jsonb,'["Bệnh mù màu đỏ - xanh lục do allele lặn trên NST X (Xm). Bố mẹ bình thường XᴹY × XᴹXᵐ có thể sinh con trai bị bệnh XᵐY."]'::jsonb,'[{"id": "biology-12-sex-linked-inheritance-q1", "prompt": "Đặc điểm nổi bật của quy luật di truyền các tính trạng do gene lặn nằm trên vùng không tương đồng của nhiễm sắc thể X quy định ở người là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ truyền trực tiếp từ bố cho con trai"}, {"id": "b", "text": "Biểu hiện đồng đều 100% ở tất cả các thế hệ con cháu"}, {"id": "c", "text": "Di truyền chéo và bệnh thường biểu hiện ở nam giới với tần suất cao hơn nữ giới"}], "correctOptionId": "c", "explanation": "Nam giới chỉ có 1 NST X (XY) nên chỉ cần mang 1 allele lặn là biểu hiện bệnh; tính trạng truyền chéo từ mẹ sang con trai."}, {"id": "biology-12-sex-linked-inheritance-q2", "prompt": "Ở người, bệnh máu khó đông do allele lặn h nằm trên vùng không tương đồng của NST X quy định (Xʰ), allele H quy định máu đông bình thường. Bố bình thường kết hôn với mẹ mang gene bệnh dị hợp (XᴴXʰ). Xác suất họ sinh con trai bị bệnh là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0% vì bố có kiểu gene bình thường"}, {"id": "b", "text": "25% (hay 1/2 số con trai)"}, {"id": "c", "text": "50% tổng số con"}], "correctOptionId": "b", "explanation": "Sơ đồ lai: XᴴY × XᴴXʰ → 1/4 XᴴXᴴ : 1/4 XᴴXʰ : 1/4 XᴴY : 1/4 XʰY. Xác suất sinh con trai bị bệnh (XʰY) trong tổng số con là 1/4 = 25%."}, {"id": "biology-12-sex-linked-inheritance-q3", "prompt": "Một tính trạng chỉ xuất hiện ở tất cả các con đực mà không bao giờ xuất hiện ở con cái trong một dòng động vật có cặp NST giới tính đực XY và cái XX. Gene quy định tính trạng này nằm ở đâu?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Nằm trên vùng không tương đồng của nhiễm sắc thể Y"}, {"id": "b", "text": "Nằm trên nhiễm sắc thể thường"}, {"id": "c", "text": "Nằm trong ti thể ở tế bào chất của trứng"}], "correctOptionId": "a", "explanation": "Gene nằm trên vùng không tương đồng của NST Y chỉ truyền từ bố sang 100% các con trai (di truyền thẳng)."}]'::jsonb,'["biology-12-sex-linked-inheritance"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-chromosomal-mutation',10,'LESSON','Đột biến nhiễm sắc thể','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Đột biến cấu trúc NST gồm: mất đoạn (mất đoạn NST số 5 gây hội chứng tiếng mèo kêu), lặp đoạn (tăng liều lượng gene), đảo đoạn (không đổi vật chất di truyền nhưng đổi trật tự), chuyển đoạn (tương hỗ hoặc không tương hỗ). Đột biến số lượng NST gồm: lệch bội (2n+1 thể ba, 2n-1 thể một) và đa bội (tự đa bội 3n, 4n; dị đa bội)."]'::jsonb,'["Hội chứng Down do thừa một nhiễm sắc thể số 21 (thể ba nhiễm 2n + 1 = 47 chiếc)."]'::jsonb,'[{"id": "biology-12-chromosomal-mutation-q1", "prompt": "Dạng đột biến cấu trúc nhiễm sắc thể nào sau đây làm giảm số lượng gene trên một nhiễm sắc thể và thường gây hại nhiều nhất cho sinh vật?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đột biến đảo đoạn"}, {"id": "b", "text": "Đột biến mất đoạn"}, {"id": "c", "text": "Đột biến lặp đoạn"}], "correctOptionId": "b", "explanation": "Mất đoạn làm mất vật chất di truyền mang gene, phá vỡ cân bằng gene trong hệ gen nên thường gây chết hoặc giảm sức sống nghiêm trọng."}, {"id": "biology-12-chromosomal-mutation-q2", "prompt": "Người mắc hội chứng Down có bộ nhiễm sắc thể thuộc dạng đột biến số lượng nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thể ba nhiễm (2n + 1) ở cặp nhiễm sắc thể số 21"}, {"id": "b", "text": "Thể một nhiễm (2n - 1) ở cặp nhiễm sắc thể giới tính"}, {"id": "c", "text": "Thể tam bội (3n) toàn bộ bộ nhiễm sắc thể"}], "correctOptionId": "a", "explanation": "Hội chứng Down xuất hiện do có 3 nhiễm sắc thể ở cặp số 21 (thể ba 2n+1 = 47 chiếc)."}, {"id": "biology-12-chromosomal-mutation-q3", "prompt": "Cây tứ bội (4n) được tạo ra từ cây lưỡng bội (2n) thường có đặc điểm sinh học nổi bật nào sau đây?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Hạt phấn và noãn luôn bị bất thụ 100% không thể sinh sản"}, {"id": "b", "text": "Toàn bộ lá bị biến dạng thành gai nhọn do đột biến gene kèm theo"}, {"id": "c", "text": "Cơ quan sinh dưỡng to, tế bào lớn, sinh trưởng phát triển mạnh và chống chịu tốt"}], "correctOptionId": "c", "explanation": "Đa bội chẵn (4n) nhân đôi hàm lượng DNA dẫn tới tăng kích thước tế bào, cơ quan sinh dưỡng phát triển to lớn và tăng sức sống."}]'::jsonb,'["biology-12-chromosomal-mutation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-human-genetics',11,'LESSON','Di truyền học người và y học','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Phương pháp nghiên cứu phả hệ (xác định tính trạng trội/lặn, liên kết NST thường hay giới tính). Xét nghiệm trước sinh: chọc ối, sinh thiết gai nhau, làm tiêu bản NST karyotyping. Tư vấn di truyền giúp dự đoán xác suất rủi ro mắc bệnh tật di truyền ở đời con. Liệu pháp gene nhằm chữa trị bệnh bằng cách thay thế gene đột biến."]'::jsonb,'["Bệnh bạch tạng do gene lặn trên NST thường; bố mẹ bình thường mang gene dị hợp có xác suất 1/4 sinh con bị bệnh."]'::jsonb,'[{"id": "biology-12-human-genetics-q1", "prompt": "Phương pháp nghiên cứu phả hệ ở người có mục đích chính là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Theo dõi sự di truyền của một tính trạng qua nhiều thế hệ để xác định quy luật di truyền của tính trạng đó"}, {"id": "b", "text": "Gây đột biến nhân tạo bằng tia phóng xạ để quan sát kiểu hình người"}, {"id": "c", "text": "Lai phân tích người với các loài linh trưởng khác để xác định kiểu gene"}], "correctOptionId": "a", "explanation": "Do không thể thực hiện các phép lai thực nghiệm ở người, phả hệ ghi nhận lịch sử gia đình qua các thế hệ để suy luận quy luật di truyền."}, {"id": "biology-12-human-genetics-q2", "prompt": "Kĩ thuật chọc dò dịch ối hoặc sinh thiết gai nhau ở phụ nữ mang thai nhằm mục đích:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bơm thêm chất dinh dưỡng trực tiếp vào dạ dày của thai nhi"}, {"id": "b", "text": "Tiêu diệt các vi khuẩn có hại bám trên thành tử cung"}, {"id": "c", "text": "Lấy tế bào thai nhi để phân tích nhiễm sắc thể và phát hiện sớm các dị tật di truyền"}], "correctOptionId": "c", "explanation": "Tế bào bong từ thai trong dịch ối cho phép lập karyotype để chẩn đoán thể tam nhiễm hoặc giải trình tự gene phát hiện bệnh lý trước sinh."}, {"id": "biology-12-human-genetics-q3", "prompt": "Liệu pháp gene (gene therapy) trong y học hiện đại hướng tới mục tiêu điều trị nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Tiêm kháng sinh phổ rộng liều cao để tiêu diệt các đoạn gene lạ"}, {"id": "b", "text": "Thay thế hoặc sửa chữa gene đột biến gây bệnh bằng gene lành chức năng bình thường"}, {"id": "c", "text": "Cắt bỏ toàn bộ hệ cơ quan bị nhiễm bệnh trên cơ thể người bệnh"}], "correctOptionId": "b", "explanation": "Liệu pháp gene dùng vector virus chuyển gene lành vào tế bào đích để bù đắp hoặc sửa chữa chức năng của gene bị khiếm khuyết."}]'::jsonb,'["biology-12-human-genetics"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-review-2',12,'FIVE_LESSON_REVIEW','Ôn tập 2','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "biology-12-mendelian-genetics-q1", "prompt": "Cơ sở tế bào học trực tiếp của quy luật phân li độc lập theo quan điểm di truyền học hiện đại là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Sự nhân đôi đồng thời của các phân tử DNA ở pha S của chu kì tế bào"}, {"id": "b", "text": "Sự phân li độc lập và tổ hợp ngẫu nhiên của các cặp nhiễm sắc thể tương đồng trong giảm phân"}, {"id": "c", "text": "Sự tiếp hợp và trao đổi chéo giữa các chromatid chị em trong nguyên phân"}], "correctOptionId": "b", "explanation": "Các cặp gene nằm trên các cặp NST tương đồng khác nhau phân li độc lập khi các cặp NST này phân li ngẫu nhiên về hai cực tế bào ở kì sau I."}, {"id": "biology-12-mendelian-genetics-q2", "prompt": "Cho phép lai P: AaBb × aabb (lai phân tích hai cặp gene phân li độc lập). Tỉ lệ phân li kiểu hình ở đời con Fa là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "1 : 1 : 1 : 1"}, {"id": "b", "text": "9 : 3 : 3 : 1"}, {"id": "c", "text": "3 : 3 : 1 : 1"}], "correctOptionId": "a", "explanation": "Cơ thể AaBb cho 4 loại giao tử với tỉ lệ 1/4 AB : 1/4 Ab : 1/4 aB : 1/4 ab; cơ thể aabb cho 1 loại giao tử ab. Con lai phân tích có tỉ lệ kiểu hình 1:1:1:1."}, {"id": "biology-12-linkage-crossing-over-q1", "prompt": "Hiện tượng hoán vị gene xảy ra do cơ chế tiếp hợp và trao đổi chéo giữa các đoạn chromatid ở kì nào của quá trình phân bào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Kì đầu của giảm phân I"}, {"id": "b", "text": "Kì giữa của giảm phân II"}, {"id": "c", "text": "Kì sau của nguyên phân"}], "correctOptionId": "a", "explanation": "Sự tiếp hợp và trao đổi chéo giữa các chromatid khác nguồn gốc của cặp NST tương đồng xảy ra ở kì đầu I của giảm phân."}, {"id": "biology-12-linkage-crossing-over-q2", "prompt": "Tần số hoán vị gene giữa hai locus gene trên cùng một nhiễm sắc thể:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Luôn bằng đúng 100% ở mọi loài sinh vật"}, {"id": "b", "text": "Luôn lớn hơn 75% đối với các gene liên kết xa nhau"}, {"id": "c", "text": "Không bao giờ vượt quá 50%"}], "correctOptionId": "c", "explanation": "Trao đổi chéo chỉ xảy ra giữa 2 trong 4 chromatid của thể tứ tử, tối đa 50% số giao tử tạo ra là giao tử hoán vị (f ≤ 50%)."}, {"id": "biology-12-sex-linked-inheritance-q1", "prompt": "Đặc điểm nổi bật của quy luật di truyền các tính trạng do gene lặn nằm trên vùng không tương đồng của nhiễm sắc thể X quy định ở người là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ truyền trực tiếp từ bố cho con trai"}, {"id": "b", "text": "Biểu hiện đồng đều 100% ở tất cả các thế hệ con cháu"}, {"id": "c", "text": "Di truyền chéo và bệnh thường biểu hiện ở nam giới với tần suất cao hơn nữ giới"}], "correctOptionId": "c", "explanation": "Nam giới chỉ có 1 NST X (XY) nên chỉ cần mang 1 allele lặn là biểu hiện bệnh; tính trạng truyền chéo từ mẹ sang con trai."}, {"id": "biology-12-sex-linked-inheritance-q2", "prompt": "Ở người, bệnh máu khó đông do allele lặn h nằm trên vùng không tương đồng của NST X quy định (Xʰ), allele H quy định máu đông bình thường. Bố bình thường kết hôn với mẹ mang gene bệnh dị hợp (XᴴXʰ). Xác suất họ sinh con trai bị bệnh là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "0% vì bố có kiểu gene bình thường"}, {"id": "b", "text": "25% (hay 1/2 số con trai)"}, {"id": "c", "text": "50% tổng số con"}], "correctOptionId": "b", "explanation": "Sơ đồ lai: XᴴY × XᴴXʰ → 1/4 XᴴXᴴ : 1/4 XᴴXʰ : 1/4 XᴴY : 1/4 XʰY. Xác suất sinh con trai bị bệnh (XʰY) trong tổng số con là 1/4 = 25%."}, {"id": "biology-12-chromosomal-mutation-q1", "prompt": "Dạng đột biến cấu trúc nhiễm sắc thể nào sau đây làm giảm số lượng gene trên một nhiễm sắc thể và thường gây hại nhiều nhất cho sinh vật?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đột biến đảo đoạn"}, {"id": "b", "text": "Đột biến mất đoạn"}, {"id": "c", "text": "Đột biến lặp đoạn"}], "correctOptionId": "b", "explanation": "Mất đoạn làm mất vật chất di truyền mang gene, phá vỡ cân bằng gene trong hệ gen nên thường gây chết hoặc giảm sức sống nghiêm trọng."}, {"id": "biology-12-chromosomal-mutation-q2", "prompt": "Người mắc hội chứng Down có bộ nhiễm sắc thể thuộc dạng đột biến số lượng nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thể ba nhiễm (2n + 1) ở cặp nhiễm sắc thể số 21"}, {"id": "b", "text": "Thể một nhiễm (2n - 1) ở cặp nhiễm sắc thể giới tính"}, {"id": "c", "text": "Thể tam bội (3n) toàn bộ bộ nhiễm sắc thể"}], "correctOptionId": "a", "explanation": "Hội chứng Down xuất hiện do có 3 nhiễm sắc thể ở cặp số 21 (thể ba 2n+1 = 47 chiếc)."}, {"id": "biology-12-human-genetics-q1", "prompt": "Phương pháp nghiên cứu phả hệ ở người có mục đích chính là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Theo dõi sự di truyền của một tính trạng qua nhiều thế hệ để xác định quy luật di truyền của tính trạng đó"}, {"id": "b", "text": "Gây đột biến nhân tạo bằng tia phóng xạ để quan sát kiểu hình người"}, {"id": "c", "text": "Lai phân tích người với các loài linh trưởng khác để xác định kiểu gene"}], "correctOptionId": "a", "explanation": "Do không thể thực hiện các phép lai thực nghiệm ở người, phả hệ ghi nhận lịch sử gia đình qua các thế hệ để suy luận quy luật di truyền."}, {"id": "biology-12-human-genetics-q2", "prompt": "Kĩ thuật chọc dò dịch ối hoặc sinh thiết gai nhau ở phụ nữ mang thai nhằm mục đích:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bơm thêm chất dinh dưỡng trực tiếp vào dạ dày của thai nhi"}, {"id": "b", "text": "Tiêu diệt các vi khuẩn có hại bám trên thành tử cung"}, {"id": "c", "text": "Lấy tế bào thai nhi để phân tích nhiễm sắc thể và phát hiện sớm các dị tật di truyền"}], "correctOptionId": "c", "explanation": "Tế bào bong từ thai trong dịch ối cho phép lập karyotype để chẩn đoán thể tam nhiễm hoặc giải trình tự gene phát hiện bệnh lý trước sinh."}]'::jsonb,'["biology-12-mendelian-genetics", "biology-12-linkage-crossing-over", "biology-12-sex-linked-inheritance", "biology-12-chromosomal-mutation", "biology-12-human-genetics"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-evolution-evidence',13,'LESSON','Bằng chứng tiến hóa','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Bằng chứng trực tiếp: hóa thạch (di tích sinh vật cổ lưu trong đá). Bằng chứng gián tiếp: giải phẫu so sánh (cơ quan tương đồng: cùng nguồn gốc khác chức năng, như cánh dơi và tay người; cơ quan tương tự: khác nguồn gốc cùng chức năng; cơ quan thoái hóa: ruột thừa), phôi sinh học và sinh học phân tử (tương đồng về trình tự DNA, amino acid trong cytochrom c)."]'::jsonb,'["Cánh của dơi và tay của người có cùng cấu trúc giải phẫu xương chi trước chứng tỏ bắt nguồn từ cùng một tổ tiên chung (cơ quan tương đồng)."]'::jsonb,'[{"id": "biology-12-evolution-evidence-q1", "prompt": "Cánh dơi và tay người có cùng cấu trúc giải phẫu xương nhưng đảm nhiệm các chức năng khác nhau là ví dụ về:", "difficulty": "EASY", "options": [{"id": "a", "text": "Cơ quan tương tự"}, {"id": "b", "text": "Cơ quan thoái hóa"}, {"id": "c", "text": "Cơ quan tương đồng"}], "correctOptionId": "c", "explanation": "Cơ quan tương đồng bắt nguồn từ cùng một nguồn gốc phôi thai ở tổ tiên chung nhưng biến đổi thích nghi với các chức năng khác nhau."}, {"id": "biology-12-evolution-evidence-q2", "prompt": "Bằng chứng tiến hóa nào sau đây được coi là bằng chứng trực tiếp và xác thực nhất về lịch sử phát triển của sinh giới?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cơ quan thoái hóa ruột thừa ở người"}, {"id": "b", "text": "Hóa thạch các sinh vật cổ xưa còn lưu lại trong các tầng địa chất"}, {"id": "c", "text": "Sự tương đồng về cấu trúc protein cytochrom c"}], "correctOptionId": "b", "explanation": "Hóa thạch là di tích thực tế của sinh vật cổ sinh được bảo tồn trong đá, là bằng chứng trực tiếp duy nhất về niên đại và hình dạng sinh vật cổ."}, {"id": "biology-12-evolution-evidence-q3", "prompt": "Mức độ tương đồng về trình tự nucleotide trong DNA hoặc trình tự amino acid trong cùng một loại protein giữa hai loài phản ánh điều gì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Mức độ gần gũi về quan hệ họ hàng tiến hóa giữa hai loài đó"}, {"id": "b", "text": "Kích thước cơ thể và tuổi thọ trung bình của hai loài là như nhau"}, {"id": "c", "text": "Hai loài sống ở cùng một sinh cảnh và có chung một nguồn thức ăn"}], "correctOptionId": "a", "explanation": "Hai loài càng gần nhau trên cây phát sinh chủng loại thì thời gian phân nhánh từ tổ tiên chung càng ngắn, dẫn đến trình tự phân tử càng tương đồng."}]'::jsonb,'["biology-12-evolution-evidence"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-modern-evolution-synthesis',14,'LESSON','Thuyết tiến hóa tổng hợp hiện đại','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Quần thể là đơn vị tiến hóa cơ sở. Tiến hóa nhỏ: biến đổi tần số allele và thành phần kiểu gene của quần thể dẫn đến hình thành loài mới. 5 nhân tố tiến hóa: đột biến (tạo nguyên liệu sơ cấp), di - nhập gene (gene flow), chọn lọc tự nhiên (định hướng), các yếu tố ngẫu nhiên (genetic drift: làm biến đổi đột ngột tần số allele), giao phối không ngẫu nhiên (tăng đồng hợp, giảm dị hợp)."]'::jsonb,'["Một trận bão cuốn trôi phần lớn cá thể của quần thể ốc sên, làm mất ngẫu nhiên một allele quý (hiệu ứng thắt cổ chai do yếu tố ngẫu nhiên)."]'::jsonb,'[{"id": "biology-12-modern-evolution-synthesis-q1", "prompt": "Theo thuyết tiến hóa tổng hợp hiện đại, đơn vị tiến hóa cơ sở nhỏ nhất có thể biến đổi tần số allele qua thời gian là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Toàn bộ loài sinh vật trên Trái Đất"}, {"id": "b", "text": "Quần thể"}, {"id": "c", "text": "Cá thể sinh vật đơn lẻ"}], "correctOptionId": "b", "explanation": "Cá thể không tiến hóa vì hệ gene không đổi; quần thể với vốn gene biến đổi qua các thế hệ giao phối mới là đơn vị tiến hóa cơ sở."}, {"id": "biology-12-modern-evolution-synthesis-q2", "prompt": "Nhân tố tiến hóa nào sau đây có vai trò định hướng quá trình tiến hóa bằng cách quy định chiều hướng và tốc độ biến đổi tần số allele?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chọn lọc tự nhiên"}, {"id": "b", "text": "Đột biến gene ngẫu nhiên"}, {"id": "c", "text": "Giao phối không ngẫu nhiên"}], "correctOptionId": "a", "explanation": "Chỉ có chọn lọc tự nhiên giữ lại các kiểu hình thích nghi và đào thải kiểu hình có hại, do đó có vai trò định hướng tiến hóa."}, {"id": "biology-12-modern-evolution-synthesis-q3", "prompt": "Một đợt cháy rừng dữ dội quét qua làm chết 95% cá thể của một quần thể hươu. Quần thể phục hồi từ số ít cá thể sống sót nhưng thành phần vốn gene khác biệt hẳn ban đầu. Đây là ví dụ về:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Quá trình chọn lọc tự nhiên theo hướng thích nghi"}, {"id": "b", "text": "Hiện tượng di - nhập gene từ quần thể láng giềng"}, {"id": "c", "text": "Các yếu tố ngẫu nhiên (hiệu ứng thắt cổ chai quần thể)"}], "correctOptionId": "c", "explanation": "Thiên tai làm giảm số lượng ngẫu nhiên không phụ thuộc giá trị thích nghi là biến động di truyền ngẫu nhiên (bottleneck effect)."}]'::jsonb,'["biology-12-modern-evolution-synthesis"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-natural-selection',15,'LESSON','Chọn lọc tự nhiên và đặc điểm thích nghi','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Thực chất của chọn lọc tự nhiên là sự phân hóa khả năng sống sót và sinh sản của các cá thể với các kiểu gene khác nhau trong quần thể. CLTN tác động trực tiếp lên kiểu hình, qua đó gián tiếp chọn lọc kiểu gene. Các kiểu chọn lọc: chọn lọc ổn định, chọn lọc vận động, chọn lọc phân hóa."]'::jsonb,'["Bướm sâu đo bạch dương cánh màu sẫm phát triển ưu thế ở vùng công nghiệp bị ô nhiễm bụi than nhờ khả năng ngụy trang tránh chim săn mồi."]'::jsonb,'[{"id": "biology-12-natural-selection-q1", "prompt": "Chọn lọc tự nhiên tác động trực tiếp lên cấp độ nào của sinh vật trong tự nhiên?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cấp độ kiểu hình của từng cá thể sinh vật"}, {"id": "b", "text": "Trực tiếp lên từng nucleotide của phân tử DNA trong nhân"}, {"id": "c", "text": "Chỉ tác động lên các tế bào sinh dục đơn lẻ"}], "correctOptionId": "a", "explanation": "Ngoại cảnh tương tác trực tiếp với kiểu hình (hình thái, sinh lí); các kiểu hình thích nghi sống sót sẽ truyền kiểu gene cho thế hệ sau."}, {"id": "biology-12-natural-selection-q2", "prompt": "Hiện tượng vi khuẩn kháng thuốc kháng sinh phát triển nhanh chóng sau một thời gian dài sử dụng thuốc trong y tế được giải thích bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thuốc kháng sinh trực tiếp kích thích vi khuẩn tự tạo ra các gene kháng thuốc mới"}, {"id": "b", "text": "Vi khuẩn học tập được cách phân hủy thuốc kháng sinh để lấy năng lượng"}, {"id": "c", "text": "Thuốc kháng sinh đóng vai trò nhân tố chọn lọc, giữ lại và nhân lên các vi khuẩn mang đột biến kháng thuốc"}], "correctOptionId": "c", "explanation": "Đột biến kháng thuốc có sẵn ngẫu nhiên trong quần thể vi khuẩn; thuốc kháng sinh diệt vi khuẩn mẫn cảm, tạo ưu thế cho chủng kháng sinh sản nhanh."}, {"id": "biology-12-natural-selection-q3", "prompt": "Dạng chọn lọc tự nhiên bảo tồn những cá thể có giá trị tính trạng trung bình và đào thải các cá thể có giá trị tính trạng ở hai cực đoan gọi là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chọn lọc phân hóa (tạo ra hai đỉnh phân bố mới)"}, {"id": "b", "text": "Chọn lọc ổn định (kiểu duy trì trạng thái cân bằng)"}, {"id": "c", "text": "Chọn lọc vận động (làm lệch đỉnh phân bố)"}], "correctOptionId": "b", "explanation": "Chọn lọc ổn định xảy ra trong điều kiện môi trường ổn định, đào thải các sai lệch cực đoan và giữ lại tính trạng trung bình tối ưu."}]'::jsonb,'["biology-12-natural-selection"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-speciation',16,'LESSON','Loài và cơ chế hình thành loài','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Khái niệm loài sinh học: quần thể các cá thể có khả năng giao phối sinh ra con hữu thụ và cách li sinh sản với các nhóm khác. Các cơ chế cách li sinh sản: cách li trước hợp tử (nơi ở, tập tính, thời gian, cơ học) và cách li sau hợp tử (hợp tử chết, con lai bất thụ như con la). Con đường hình thành loài: cách li địa lí (khác vùng) và cùng vùng địa lí (cách li sinh thái, tập tính, lai xa và đa bội hóa)."]'::jsonb,'["Ngựa lai với lừa sinh ra con la bất thụ do bộ NST không tương đồng không thể giảm phân bình thường (cách li sau hợp tử)."]'::jsonb,'[{"id": "biology-12-speciation-q1", "prompt": "Tiêu chuẩn cơ bản và quan trọng nhất để phân biệt hai loài sinh sản hữu tính thân thuộc trong tự nhiên là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tiêu chuẩn hình thái học bên ngoài"}, {"id": "b", "text": "Tiêu chuẩn màu sắc nơi cư trú"}, {"id": "c", "text": "Tiêu chuẩn cách li sinh sản"}], "correctOptionId": "c", "explanation": "Khái niệm loài sinh học dựa trên sự cách li sinh sản: nếu hai quần thể không giao phối hoặc con lai bất thụ thì chúng thuộc hai loài khác nhau."}, {"id": "biology-12-speciation-q2", "prompt": "Ngựa (2n = 64) lai với lừa (2n = 62) sinh ra con la (2n = 63) hoàn toàn bất thụ. Đây là ví dụ về cơ chế cách li sinh sản nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cách li sinh thái do không gặp nhau"}, {"id": "b", "text": "Cách li sau hợp tử (bất thụ con lai)"}, {"id": "c", "text": "Cách li trước hợp tử về mặt cơ học"}], "correctOptionId": "b", "explanation": "Con la hình thành từ thụ tinh nhưng bộ NST cọc cạch không giảm phân được, con lai bất thụ thuộc cơ chế cách li sau hợp tử."}, {"id": "biology-12-speciation-q3", "prompt": "Hình thành loài mới bằng con đường lai xa và đa bội hóa (dị đa bội) thường gặp phổ biến nhất ở nhóm sinh vật nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Thực vật có hoa"}, {"id": "b", "text": "Động vật có vú bậc cao"}, {"id": "c", "text": "Các loài chim di cư"}], "correctOptionId": "a", "explanation": "Thực vật có khả năng tự thụ phấn và sinh sản sinh dưỡng giúp duy trì thể dị đa bội (như lúa mì, chuối, bông), ở động vật đa bội thường gây chết."}]'::jsonb,'["biology-12-speciation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-origin-of-life',17,'LESSON','Nguồn gốc sự sống và lịch sử sinh giới','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Ba giai đoạn tiến hóa: Tiến hóa hóa học (chất vô cơ -> chất hữu cơ đơn giản -> đại phân tử tự nhân đôi như RNA, DNA, protein; thí nghiệm Miller-Urey); Tiến hóa tiền sinh học (tạo giọt coacervate / liposome có màng phân cách); Tiến hóa sinh học (từ tế bào nguyên thủy đến sinh giới đa dạng). Các đại địa chất: Thái cổ, Nguyên sinh, Cổ sinh, Trung sinh (thời đại bò sát), Tân sinh (thời đại thú và thực vật có hoa, xuất hiện loài người)."]'::jsonb,'["Thí nghiệm năm 1953 của Miller và Urey phóng tia lửa điện qua hỗn hợp khí CH4, NH3, H2, H2O đã tổng hợp được các amino acid tự nhiên."]'::jsonb,'[{"id": "biology-12-origin-of-life-q1", "prompt": "Thí nghiệm nổi tiếng năm 1953 của Stanley Miller và Harold Urey đã chứng minh điều gì về nguồn gốc sự sống?", "difficulty": "EASY", "options": [{"id": "a", "text": "Phân tử DNA là dạng vật chất di truyền đầu tiên xuất hiện trên Trái Đất"}, {"id": "b", "text": "Các hợp chất hữu cơ đơn giản có thể được hình thành từ các chất vô cơ trong điều kiện khí quyển nguyên thủy"}, {"id": "c", "text": "Tế bào sống nguyên thủy có thể tự lắp ráp hoàn chỉnh chỉ trong 24 giờ"}], "correctOptionId": "b", "explanation": "Thí nghiệm mô phỏng phóng điện qua khí quyển nguyên thủy khử tạo ra các amino acid, chứng minh bước tiến hóa hóa học là hoàn toàn khả thi."}, {"id": "biology-12-origin-of-life-q2", "prompt": "Đại địa chất nào sau đây được gọi là ''Kỉ nguyên của các loài bò sát'' và chứng kiến sự thống trị của các loài khủng long?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đại Trung sinh (Mesozoic)"}, {"id": "b", "text": "Đại Cổ sinh (Paleozoic)"}, {"id": "c", "text": "Đại Tân sinh (Cenozoic)"}], "correctOptionId": "a", "explanation": "Đại Trung sinh gồm kỉ Trias, Jura và Creta là thời kì bò sát khổng lồ (khủng long) phát triển cực thịnh và tuyệt diệt vào cuối kỉ Creta."}, {"id": "biology-12-origin-of-life-q3", "prompt": "Giả thuyết ''Thế giới RNA'' (RNA World) cho rằng RNA xuất hiện trước DNA và protein vì phân tử RNA có khả năng độc đáo nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Không bao giờ bị phân hủy bởi nhiệt độ cao"}, {"id": "b", "text": "Có cấu trúc vòng khép kín bền vững hơn kim cương"}, {"id": "c", "text": "Vừa có khả năng lưu trữ thông tin di truyền vừa có hoạt tính xúc tác như một enzyme (ribozyme)"}], "correctOptionId": "c", "explanation": "RNA vừa mang mã di truyền vừa có hoạt tính xúc tác (ribozyme), đóng vai trò vừa là vật chất di truyền vừa là enzyme sơ khai của sự sống."}]'::jsonb,'["biology-12-origin-of-life"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-review-3',18,'FIVE_LESSON_REVIEW','Ôn tập 3','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "biology-12-evolution-evidence-q1", "prompt": "Cánh dơi và tay người có cùng cấu trúc giải phẫu xương nhưng đảm nhiệm các chức năng khác nhau là ví dụ về:", "difficulty": "EASY", "options": [{"id": "a", "text": "Cơ quan tương tự"}, {"id": "b", "text": "Cơ quan thoái hóa"}, {"id": "c", "text": "Cơ quan tương đồng"}], "correctOptionId": "c", "explanation": "Cơ quan tương đồng bắt nguồn từ cùng một nguồn gốc phôi thai ở tổ tiên chung nhưng biến đổi thích nghi với các chức năng khác nhau."}, {"id": "biology-12-evolution-evidence-q2", "prompt": "Bằng chứng tiến hóa nào sau đây được coi là bằng chứng trực tiếp và xác thực nhất về lịch sử phát triển của sinh giới?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cơ quan thoái hóa ruột thừa ở người"}, {"id": "b", "text": "Hóa thạch các sinh vật cổ xưa còn lưu lại trong các tầng địa chất"}, {"id": "c", "text": "Sự tương đồng về cấu trúc protein cytochrom c"}], "correctOptionId": "b", "explanation": "Hóa thạch là di tích thực tế của sinh vật cổ sinh được bảo tồn trong đá, là bằng chứng trực tiếp duy nhất về niên đại và hình dạng sinh vật cổ."}, {"id": "biology-12-modern-evolution-synthesis-q1", "prompt": "Theo thuyết tiến hóa tổng hợp hiện đại, đơn vị tiến hóa cơ sở nhỏ nhất có thể biến đổi tần số allele qua thời gian là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Toàn bộ loài sinh vật trên Trái Đất"}, {"id": "b", "text": "Quần thể"}, {"id": "c", "text": "Cá thể sinh vật đơn lẻ"}], "correctOptionId": "b", "explanation": "Cá thể không tiến hóa vì hệ gene không đổi; quần thể với vốn gene biến đổi qua các thế hệ giao phối mới là đơn vị tiến hóa cơ sở."}, {"id": "biology-12-modern-evolution-synthesis-q2", "prompt": "Nhân tố tiến hóa nào sau đây có vai trò định hướng quá trình tiến hóa bằng cách quy định chiều hướng và tốc độ biến đổi tần số allele?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chọn lọc tự nhiên"}, {"id": "b", "text": "Đột biến gene ngẫu nhiên"}, {"id": "c", "text": "Giao phối không ngẫu nhiên"}], "correctOptionId": "a", "explanation": "Chỉ có chọn lọc tự nhiên giữ lại các kiểu hình thích nghi và đào thải kiểu hình có hại, do đó có vai trò định hướng tiến hóa."}, {"id": "biology-12-natural-selection-q1", "prompt": "Chọn lọc tự nhiên tác động trực tiếp lên cấp độ nào của sinh vật trong tự nhiên?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cấp độ kiểu hình của từng cá thể sinh vật"}, {"id": "b", "text": "Trực tiếp lên từng nucleotide của phân tử DNA trong nhân"}, {"id": "c", "text": "Chỉ tác động lên các tế bào sinh dục đơn lẻ"}], "correctOptionId": "a", "explanation": "Ngoại cảnh tương tác trực tiếp với kiểu hình (hình thái, sinh lí); các kiểu hình thích nghi sống sót sẽ truyền kiểu gene cho thế hệ sau."}, {"id": "biology-12-natural-selection-q2", "prompt": "Hiện tượng vi khuẩn kháng thuốc kháng sinh phát triển nhanh chóng sau một thời gian dài sử dụng thuốc trong y tế được giải thích bằng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thuốc kháng sinh trực tiếp kích thích vi khuẩn tự tạo ra các gene kháng thuốc mới"}, {"id": "b", "text": "Vi khuẩn học tập được cách phân hủy thuốc kháng sinh để lấy năng lượng"}, {"id": "c", "text": "Thuốc kháng sinh đóng vai trò nhân tố chọn lọc, giữ lại và nhân lên các vi khuẩn mang đột biến kháng thuốc"}], "correctOptionId": "c", "explanation": "Đột biến kháng thuốc có sẵn ngẫu nhiên trong quần thể vi khuẩn; thuốc kháng sinh diệt vi khuẩn mẫn cảm, tạo ưu thế cho chủng kháng sinh sản nhanh."}, {"id": "biology-12-speciation-q1", "prompt": "Tiêu chuẩn cơ bản và quan trọng nhất để phân biệt hai loài sinh sản hữu tính thân thuộc trong tự nhiên là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tiêu chuẩn hình thái học bên ngoài"}, {"id": "b", "text": "Tiêu chuẩn màu sắc nơi cư trú"}, {"id": "c", "text": "Tiêu chuẩn cách li sinh sản"}], "correctOptionId": "c", "explanation": "Khái niệm loài sinh học dựa trên sự cách li sinh sản: nếu hai quần thể không giao phối hoặc con lai bất thụ thì chúng thuộc hai loài khác nhau."}, {"id": "biology-12-speciation-q2", "prompt": "Ngựa (2n = 64) lai với lừa (2n = 62) sinh ra con la (2n = 63) hoàn toàn bất thụ. Đây là ví dụ về cơ chế cách li sinh sản nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cách li sinh thái do không gặp nhau"}, {"id": "b", "text": "Cách li sau hợp tử (bất thụ con lai)"}, {"id": "c", "text": "Cách li trước hợp tử về mặt cơ học"}], "correctOptionId": "b", "explanation": "Con la hình thành từ thụ tinh nhưng bộ NST cọc cạch không giảm phân được, con lai bất thụ thuộc cơ chế cách li sau hợp tử."}, {"id": "biology-12-origin-of-life-q1", "prompt": "Thí nghiệm nổi tiếng năm 1953 của Stanley Miller và Harold Urey đã chứng minh điều gì về nguồn gốc sự sống?", "difficulty": "EASY", "options": [{"id": "a", "text": "Phân tử DNA là dạng vật chất di truyền đầu tiên xuất hiện trên Trái Đất"}, {"id": "b", "text": "Các hợp chất hữu cơ đơn giản có thể được hình thành từ các chất vô cơ trong điều kiện khí quyển nguyên thủy"}, {"id": "c", "text": "Tế bào sống nguyên thủy có thể tự lắp ráp hoàn chỉnh chỉ trong 24 giờ"}], "correctOptionId": "b", "explanation": "Thí nghiệm mô phỏng phóng điện qua khí quyển nguyên thủy khử tạo ra các amino acid, chứng minh bước tiến hóa hóa học là hoàn toàn khả thi."}, {"id": "biology-12-origin-of-life-q2", "prompt": "Đại địa chất nào sau đây được gọi là ''Kỉ nguyên của các loài bò sát'' và chứng kiến sự thống trị của các loài khủng long?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đại Trung sinh (Mesozoic)"}, {"id": "b", "text": "Đại Cổ sinh (Paleozoic)"}, {"id": "c", "text": "Đại Tân sinh (Cenozoic)"}], "correctOptionId": "a", "explanation": "Đại Trung sinh gồm kỉ Trias, Jura và Creta là thời kì bò sát khổng lồ (khủng long) phát triển cực thịnh và tuyệt diệt vào cuối kỉ Creta."}]'::jsonb,'["biology-12-evolution-evidence", "biology-12-modern-evolution-synthesis", "biology-12-natural-selection", "biology-12-speciation", "biology-12-origin-of-life"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-ecological-factors',19,'LESSON','Môi trường và các nhân tố sinh thái','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Môi trường sống gồm: đất, nước, không khí, sinh vật. Nhân tố sinh thái: vô sinh (ánh sáng, nhiệt độ, độ ẩm) và hữu sinh (con người, sinh vật khác). Giới hạn sinh thái: khoảng chống chịu và khoảng thuận lợi; điểm cực thuận. Quy tắc nhiệt độ: Allen (tai, đuôi thuôn nhỏ ở vùng lạnh), Bergmann (kích thước cơ thể lớn hơn ở vùng lạnh)."]'::jsonb,'["Cá rô phi ở Việt Nam có giới hạn nhiệt độ từ 5,6 °C đến 42 °C, điểm cực thuận khoảng 30 °C."]'::jsonb,'[{"id": "biology-12-ecological-factors-q1", "prompt": "Giới hạn sinh thái của một loài đối với một nhân tố sinh thái nhất định được định nghĩa là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Khoảng giá trị xác định của nhân tố sinh thái mà trong đó sinh vật có thể tồn tại và phát triển ổn định"}, {"id": "b", "text": "Điểm nhiệt độ cao nhất mà sinh vật bắt đầu bị chết"}, {"id": "c", "text": "Toàn bộ các nhân tố môi trường tác động đồng thời lên sinh vật"}], "correctOptionId": "a", "explanation": "Giới hạn sinh thái là giới hạn chịu đựng của loài đối với một nhân tố sinh thái (giữa giới hạn dưới và giới hạn trên)."}, {"id": "biology-12-ecological-factors-q2", "prompt": "Nhóm nhân tố sinh thái nào sau đây thuộc nhóm nhân tố sinh thái hữu sinh?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Độ pH và lượng oxy hòa tan trong nước ao"}, {"id": "b", "text": "Ánh sáng mặt trời và nhiệt độ không khí"}, {"id": "c", "text": "Mối quan hệ cạnh tranh thức ăn giữa các loài động vật trong rừng"}], "correctOptionId": "c", "explanation": "Nhân tố hữu sinh là thế giới sống xung quanh sinh vật bao gồm các sinh vật khác và mối quan hệ giữa chúng, cũng như con người."}, {"id": "biology-12-ecological-factors-q3", "prompt": "Theo quy tắc Bergmann trong sinh thái học động vật hằng nhiệt, động vật sống ở vùng có vĩ độ cao khí hậu lạnh giá thường có:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Nhiệt độ cơ thể giảm xuống xấp xỉ nhiệt độ môi trường"}, {"id": "b", "text": "Kích thước cơ thể lớn hơn các cá thể cùng loài hoặc loài thân thuộc sống ở vùng nhiệt đới ấm áp"}, {"id": "c", "text": "Lớp lông mỏng hơn và tai, đuôi dài hơn hẳn"}], "correctOptionId": "b", "explanation": "Kích thước lớn làm giảm tỉ lệ diện tích bề mặt trên thể tích (S/V), giúp giảm tốc độ mất nhiệt ra môi trường lạnh giá."}]'::jsonb,'["biology-12-ecological-factors"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-population-ecology',20,'LESSON','Sinh thái học quần thể','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Quần thể là tập hợp cá thể cùng loài, cùng sinh sống trong 1 khoảng không gian xác định, tại thời điểm xác định, có khả năng giao phối sinh con. Các đặc trưng cơ bản: tỉ lệ giới tính, thành phần tuổi (trước sinh sản, sinh sản, sau sinh sản), phân bố cá thể (đồng đều, theo nhóm, ngẫu nhiên), mật độ cá thể (đặc trưng quan trọng nhất), kích thước quần thể (tối thiểu, tối đa). Tăng trưởng theo hàm mũ (J) và logit (S, khi môi trường bị giới hạn sức chứa K)."]'::jsonb,'["Quần thể cây gỗ trong rừng ngập mặn thường phân bố theo nhóm tại những nơi có bãi bồi phù sa thích hợp."]'::jsonb,'[{"id": "biology-12-population-ecology-q1", "prompt": "Đặc trưng cơ bản quan trọng nhất ảnh hưởng trực tiếp đến mức độ sử dụng nguồn sống và khả năng sinh sản của quần thể là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tỉ lệ giới tính ở nhóm tuổi già"}, {"id": "b", "text": "Màu sắc bộ lông của các cá thể non"}, {"id": "c", "text": "Mật độ cá thể trong quần thể"}], "correctOptionId": "c", "explanation": "Mật độ (số cá thể trên đơn vị diện tích/thể tích) quyết định mức độ cạnh tranh, khả năng tìm kiếm thức ăn và bạn tình."}, {"id": "biology-12-population-ecology-q2", "prompt": "Trong điều kiện môi trường sống bị giới hạn về không gian và nguồn thức ăn, đường cong tăng trưởng số lượng của quần thể sinh vật trong tự nhiên có dạng hình chữ gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đường thẳng nằm ngang không đổi"}, {"id": "b", "text": "Hình chữ S (tăng trưởng logistic tiệm cận sức chứa K)"}, {"id": "c", "text": "Hình chữ J tăng trưởng theo hàm mũ vô hạn"}], "correctOptionId": "b", "explanation": "Nguồn sống giới hạn làm mức sinh giảm và mức tử tăng khi kích thước quần thể tiến tới sức chứa tối đa K của môi trường, tạo đường cong chữ S."}, {"id": "biology-12-population-ecology-q3", "prompt": "Kiểu phân bố cá thể nào là phổ biến nhất trong tự nhiên đối với các quần thể sinh vật?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Phân bố theo nhóm (tập trung tại nơi có điều kiện thuận lợi)"}, {"id": "b", "text": "Phân bố đồng đều tuyệt đối"}, {"id": "c", "text": "Phân bố ngẫu nhiên phân tán"}], "correctOptionId": "a", "explanation": "Môi trường tự nhiên không đồng nhất và sinh vật có tập tính bầy đàn nên phân bố theo nhóm là phổ biến nhất."}]'::jsonb,'["biology-12-population-ecology"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-community-ecology',21,'LESSON','Quần xã sinh vật và tương tác loài','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Quần xã là tập hợp các quần thể khác loài cùng sinh sống. Các mối quan hệ: Hỗ trợ (cộng sinh: cùng có lợi bắt buộc như địa y; hợp tác; hội sinh: cá ép bám rùa biển); Đối kháng (cạnh tranh; kí sinh; ức chế - cảm nhiễm; vật ăn thịt - con mồi). Diễn thế sinh thái: nguyên sinh (từ môi trường trống trơn) và thứ sinh (từ môi trường đã có quần xã bị tàn phá)."]'::jsonb,'["Địa y là ví dụ điển hình về mối quan hệ cộng sinh mật thiết giữa nấm và tảo đơn bào."]'::jsonb,'[{"id": "biology-12-community-ecology-q1", "prompt": "Mối quan hệ sinh thái chặt chẽ giữa hai loài sinh vật trong đó cả hai bên cùng có lợi và không thể tách rời nhau gọi là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Quan hệ kí sinh (parasitism)"}, {"id": "b", "text": "Quan hệ cộng sinh (mutualism)"}, {"id": "c", "text": "Quan hệ hội sinh (commensalism)"}], "correctOptionId": "b", "explanation": "Cộng sinh là quan hệ bắt buộc giữa hai loài, cả hai đều có lợi và sống phụ thuộc vào nhau (như nấm và vi khuẩn lam trong địa y)."}, {"id": "biology-12-community-ecology-q2", "prompt": "Hiện tượng diễn thế sinh thái khởi đầu từ một môi trường trống trơn (như đảo tro tàn núi lửa mới hình thành) gọi là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Diễn thế nguyên sinh"}, {"id": "b", "text": "Diễn thế thứ sinh"}, {"id": "c", "text": "Diễn thế thoái hóa"}], "correctOptionId": "a", "explanation": "Diễn thế nguyên sinh bắt đầu từ môi trường chưa từng có quần xã sinh vật nào sinh sống trước đó."}, {"id": "biology-12-community-ecology-q3", "prompt": "Ổ sinh thái (ecological niche) của một loài sinh vật trong quần xã biểu thị điều gì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chỉ là nơi cư trú vật lí đơn thuần của loài đó"}, {"id": "b", "text": "Tổng khối lượng sinh khối của toàn bộ cá thể trong loài"}, {"id": "c", "text": "Cách thức sinh sống và toàn bộ giới hạn sinh thái của loài đối với mọi nhân tố trong môi trường"}], "correctOptionId": "c", "explanation": "Ổ sinh thái là ''không gian sinh thái'' bao gồm nơi ở, vai trò dinh dưỡng và cách thức tương tác của loài với môi trường."}]'::jsonb,'["biology-12-community-ecology"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-ecosystem-matter-energy',22,'LESSON','Hệ sinh thái và dòng năng lượng','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Cấu trúc hệ sinh thái: sinh vật sản xuất (quang hợp/hóa dưỡng), sinh vật tiêu thụ (động vật ăn cỏ, ăn thịt), sinh vật phân giải (vi khuẩn, nấm). Chuỗi thức ăn (chăn nuôi và phế liệu) và lưới thức ăn. Dòng năng lượng: một chiều (mặt trời -> SV sản xuất -> SV tiêu thụ -> tỏa nhiệt ra môi trường), không tuần hoàn; hiệu suất sinh thái giữa các bậc dinh dưỡng khoảng 10%."]'::jsonb,'["Trong chuỗi Cỏ -> Sâu -> Chim sâu -> Đại bàng, năng lượng truyền từ cỏ lên đại bàng giảm dần qua mỗi bậc dinh dưỡng, thất thoát tới 90% dưới dạng nhiệt và bài tiết."]'::jsonb,'[{"id": "biology-12-ecosystem-matter-energy-q1", "prompt": "Trong cấu trúc thành phần sinh học của một hệ sinh thái, sinh vật nào sau đây đóng vai trò là sinh vật sản xuất sơ cấp?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cây xanh và vi khuẩn lam quang hợp"}, {"id": "b", "text": "Động vật ăn cỏ như trâu bò"}, {"id": "c", "text": "Nấm mốc và vi khuẩn hoại sinh trong đất"}], "correctOptionId": "a", "explanation": "Sinh vật sản xuất sơ cấp tự tổng hợp chất hữu cơ từ năng lượng ánh sáng mặt trời hoặc năng lượng hóa học."}, {"id": "biology-12-ecosystem-matter-energy-q2", "prompt": "Dòng năng lượng trong một hệ sinh thái tự nhiên có đặc điểm căn bản nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Luôn tuần hoàn khép kín 100% quay trở lại sinh vật sản xuất"}, {"id": "b", "text": "Càng lên bậc dinh dưỡng cao năng lượng tích lũy càng tăng vọt"}, {"id": "c", "text": "Di chuyển theo một chiều qua các bậc dinh dưỡng và tiêu hao dần dưới dạng nhiệt"}], "correctOptionId": "c", "explanation": "Năng lượng đi vào hệ sinh thái một chiều và tỏa nhiệt qua hô hấp, bài tiết ở từng bậc dinh dưỡng chứ không tuần hoàn."}, {"id": "biology-12-ecosystem-matter-energy-q3", "prompt": "Hiệu suất chuyển hóa năng lượng trung bình giữa hai bậc dinh dưỡng liên tiếp trong một hệ sinh thái tự nhiên thường đạt xấp xỉ khoảng:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Khoảng 90%"}, {"id": "b", "text": "Khoảng 10%"}, {"id": "c", "text": "Khoảng 50%"}], "correctOptionId": "b", "explanation": "Khoảng 90% năng lượng bị tiêu hao qua hô hấp, nhiệt lượng và chất thải; chỉ khoảng 10% năng lượng chuyển tiếp lên bậc dinh dưỡng kế tiếp."}]'::jsonb,'["biology-12-ecosystem-matter-energy"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-biosphere-conservation',23,'LESSON','Sinh quyển và bảo vệ môi trường','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Sinh quyển là quyển lớn nhất của Trái Đất có sự sống. Chu trình sinh - địa - hóa: chu trình carbon (quang hợp hấp thụ CO2, hô hấp/đốt cháy thải CO2; hiệu ứng nhà kính), chu trình nitơ (cố định đạm bởi Rhizobium, phản nitrat hóa), chu trình nước. Phát triển bền vững: bảo tồn đa dạng sinh học (tại chỗ in-situ và chuyển chỗ ex-situ), sử dụng năng lượng tái tạo."]'::jsonb,'["Trồng rừng đầu nguồn và bảo vệ các vườn quốc gia giúp bảo tồn nguồn gene quý hiếm và điều hòa chu trình nước, carbon toàn cầu."]'::jsonb,'[{"id": "biology-12-biosphere-conservation-q1", "prompt": "Nhóm vi sinh vật nào có khả năng biến đổi khí nitrogen tự do (N2) trong khí quyển thành dạng ion ammonium (NH4+) cây có thể hấp thụ được?", "difficulty": "EASY", "options": [{"id": "a", "text": "Vi khuẩn phản nitrat hóa phân giải đạm"}, {"id": "b", "text": "Các loại nấm men làm bánh mì"}, {"id": "c", "text": "Vi khuẩn cố định đạm (như Rhizobium sống cộng sinh trong nốt sần cây họ Đậu)"}], "correctOptionId": "c", "explanation": "Nhờ enzyme nitrogenase, vi khuẩn cố định đạm phá vỡ liên kết ba N≡N để cố định nitrogen thành dạng hợp chất hữu dụng cho thực vật."}, {"id": "biology-12-biosphere-conservation-q2", "prompt": "Biện pháp bảo tồn đa dạng sinh học nào sau đây là hình thức bảo tồn tại chỗ (in-situ conservation)?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chuyển các loài động vật quý hiếm vào nuôi nhốt trong vườn bách thú"}, {"id": "b", "text": "Thành lập các vườn quốc gia và khu dự trữ sinh quyển thiên nhiên"}, {"id": "c", "text": "Thu thập hạt giống đưa vào bảo quản đông lạnh trong ngân hàng gene"}], "correctOptionId": "b", "explanation": "Bảo tồn tại chỗ bảo vệ loài sinh vật ngay tại môi trường sống tự nhiên vốn có của chúng trong các vườn quốc gia, khu bảo tồn."}, {"id": "biology-12-biosphere-conservation-q3", "prompt": "Sự gia tăng nhanh chóng nồng độ khí CO2 và CH4 trong khí quyển do hoạt động công nghiệp của con người gây ra hậu quả môi trường toàn cầu nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Hiệu ứng nhà kính làm Trái Đất nóng lên và biến đổi khí hậu"}, {"id": "b", "text": "Làm mỏng và thủng tầng ozone bảo vệ tia cực tím"}, {"id": "c", "text": "Hiện tượng sa mạc hóa hoàn toàn các vùng biển sâu"}], "correctOptionId": "a", "explanation": "CO2 và CH4 giữ lại bức xạ nhiệt hồng ngoại từ mặt đất, gây hiệu ứng nhà kính gia tăng và biến đổi khí hậu toàn cầu."}]'::jsonb,'["biology-12-biosphere-conservation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('biology',12,'intro-2026.1','biology-12-review-4',24,'FIVE_LESSON_REVIEW','Ôn tập 4','Sinh học 12: Di truyền học, Tiến hóa và Sinh thái học','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "biology-12-ecological-factors-q1", "prompt": "Giới hạn sinh thái của một loài đối với một nhân tố sinh thái nhất định được định nghĩa là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Khoảng giá trị xác định của nhân tố sinh thái mà trong đó sinh vật có thể tồn tại và phát triển ổn định"}, {"id": "b", "text": "Điểm nhiệt độ cao nhất mà sinh vật bắt đầu bị chết"}, {"id": "c", "text": "Toàn bộ các nhân tố môi trường tác động đồng thời lên sinh vật"}], "correctOptionId": "a", "explanation": "Giới hạn sinh thái là giới hạn chịu đựng của loài đối với một nhân tố sinh thái (giữa giới hạn dưới và giới hạn trên)."}, {"id": "biology-12-ecological-factors-q2", "prompt": "Nhóm nhân tố sinh thái nào sau đây thuộc nhóm nhân tố sinh thái hữu sinh?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Độ pH và lượng oxy hòa tan trong nước ao"}, {"id": "b", "text": "Ánh sáng mặt trời và nhiệt độ không khí"}, {"id": "c", "text": "Mối quan hệ cạnh tranh thức ăn giữa các loài động vật trong rừng"}], "correctOptionId": "c", "explanation": "Nhân tố hữu sinh là thế giới sống xung quanh sinh vật bao gồm các sinh vật khác và mối quan hệ giữa chúng, cũng như con người."}, {"id": "biology-12-population-ecology-q1", "prompt": "Đặc trưng cơ bản quan trọng nhất ảnh hưởng trực tiếp đến mức độ sử dụng nguồn sống và khả năng sinh sản của quần thể là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tỉ lệ giới tính ở nhóm tuổi già"}, {"id": "b", "text": "Màu sắc bộ lông của các cá thể non"}, {"id": "c", "text": "Mật độ cá thể trong quần thể"}], "correctOptionId": "c", "explanation": "Mật độ (số cá thể trên đơn vị diện tích/thể tích) quyết định mức độ cạnh tranh, khả năng tìm kiếm thức ăn và bạn tình."}, {"id": "biology-12-population-ecology-q2", "prompt": "Trong điều kiện môi trường sống bị giới hạn về không gian và nguồn thức ăn, đường cong tăng trưởng số lượng của quần thể sinh vật trong tự nhiên có dạng hình chữ gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đường thẳng nằm ngang không đổi"}, {"id": "b", "text": "Hình chữ S (tăng trưởng logistic tiệm cận sức chứa K)"}, {"id": "c", "text": "Hình chữ J tăng trưởng theo hàm mũ vô hạn"}], "correctOptionId": "b", "explanation": "Nguồn sống giới hạn làm mức sinh giảm và mức tử tăng khi kích thước quần thể tiến tới sức chứa tối đa K của môi trường, tạo đường cong chữ S."}, {"id": "biology-12-community-ecology-q1", "prompt": "Mối quan hệ sinh thái chặt chẽ giữa hai loài sinh vật trong đó cả hai bên cùng có lợi và không thể tách rời nhau gọi là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Quan hệ kí sinh (parasitism)"}, {"id": "b", "text": "Quan hệ cộng sinh (mutualism)"}, {"id": "c", "text": "Quan hệ hội sinh (commensalism)"}], "correctOptionId": "b", "explanation": "Cộng sinh là quan hệ bắt buộc giữa hai loài, cả hai đều có lợi và sống phụ thuộc vào nhau (như nấm và vi khuẩn lam trong địa y)."}, {"id": "biology-12-community-ecology-q2", "prompt": "Hiện tượng diễn thế sinh thái khởi đầu từ một môi trường trống trơn (như đảo tro tàn núi lửa mới hình thành) gọi là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Diễn thế nguyên sinh"}, {"id": "b", "text": "Diễn thế thứ sinh"}, {"id": "c", "text": "Diễn thế thoái hóa"}], "correctOptionId": "a", "explanation": "Diễn thế nguyên sinh bắt đầu từ môi trường chưa từng có quần xã sinh vật nào sinh sống trước đó."}, {"id": "biology-12-ecosystem-matter-energy-q1", "prompt": "Trong cấu trúc thành phần sinh học của một hệ sinh thái, sinh vật nào sau đây đóng vai trò là sinh vật sản xuất sơ cấp?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cây xanh và vi khuẩn lam quang hợp"}, {"id": "b", "text": "Động vật ăn cỏ như trâu bò"}, {"id": "c", "text": "Nấm mốc và vi khuẩn hoại sinh trong đất"}], "correctOptionId": "a", "explanation": "Sinh vật sản xuất sơ cấp tự tổng hợp chất hữu cơ từ năng lượng ánh sáng mặt trời hoặc năng lượng hóa học."}, {"id": "biology-12-ecosystem-matter-energy-q2", "prompt": "Dòng năng lượng trong một hệ sinh thái tự nhiên có đặc điểm căn bản nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Luôn tuần hoàn khép kín 100% quay trở lại sinh vật sản xuất"}, {"id": "b", "text": "Càng lên bậc dinh dưỡng cao năng lượng tích lũy càng tăng vọt"}, {"id": "c", "text": "Di chuyển theo một chiều qua các bậc dinh dưỡng và tiêu hao dần dưới dạng nhiệt"}], "correctOptionId": "c", "explanation": "Năng lượng đi vào hệ sinh thái một chiều và tỏa nhiệt qua hô hấp, bài tiết ở từng bậc dinh dưỡng chứ không tuần hoàn."}, {"id": "biology-12-biosphere-conservation-q1", "prompt": "Nhóm vi sinh vật nào có khả năng biến đổi khí nitrogen tự do (N2) trong khí quyển thành dạng ion ammonium (NH4+) cây có thể hấp thụ được?", "difficulty": "EASY", "options": [{"id": "a", "text": "Vi khuẩn phản nitrat hóa phân giải đạm"}, {"id": "b", "text": "Các loại nấm men làm bánh mì"}, {"id": "c", "text": "Vi khuẩn cố định đạm (như Rhizobium sống cộng sinh trong nốt sần cây họ Đậu)"}], "correctOptionId": "c", "explanation": "Nhờ enzyme nitrogenase, vi khuẩn cố định đạm phá vỡ liên kết ba N≡N để cố định nitrogen thành dạng hợp chất hữu dụng cho thực vật."}, {"id": "biology-12-biosphere-conservation-q2", "prompt": "Biện pháp bảo tồn đa dạng sinh học nào sau đây là hình thức bảo tồn tại chỗ (in-situ conservation)?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chuyển các loài động vật quý hiếm vào nuôi nhốt trong vườn bách thú"}, {"id": "b", "text": "Thành lập các vườn quốc gia và khu dự trữ sinh quyển thiên nhiên"}, {"id": "c", "text": "Thu thập hạt giống đưa vào bảo quản đông lạnh trong ngân hàng gene"}], "correctOptionId": "b", "explanation": "Bảo tồn tại chỗ bảo vệ loài sinh vật ngay tại môi trường sống tự nhiên vốn có của chúng trong các vườn quốc gia, khu bảo tồn."}]'::jsonb,'["biology-12-ecological-factors", "biology-12-population-ecology", "biology-12-community-ecology", "biology-12-ecosystem-matter-energy", "biology-12-biosphere-conservation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','placement',0,'PLACEMENT','Khảo sát đầu vào','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "literature-12-narrative-voice-q1", "prompt": "Người kể chuyện toàn tri trong tác phẩm tự sự là người kể chuyện:", "difficulty": "EASY", "options": [{"id": "a", "text": "Biết hết mọi hành động, suy nghĩ và quá khứ của tất cả các nhân vật"}, {"id": "b", "text": "Chỉ biết những gì nhân vật chính tận mắt chứng kiến"}, {"id": "c", "text": "Luôn xuất hiện trực tiếp dưới danh xưng tôi"}], "correctOptionId": "a", "explanation": "Người kể toàn tri (omniscient) đứng ngoài câu chuyện nhưng thấu suốt toàn bộ thế giới nội tâm và hành động của mọi nhân vật."}, {"id": "literature-12-narrative-voice-q2", "prompt": "Việc chuyển đổi linh hoạt giữa điểm nhìn bên ngoài và điểm nhìn bên trong trong truyện ngắn hiện đại có tác dụng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Làm người đọc hoàn toàn không hiểu được diễn biến cốt truyện"}, {"id": "b", "text": "Rút ngắn tối đa dung lượng của văn bản"}, {"id": "c", "text": "Khám phá chiều sâu tâm lí phức tạp và tạo tính đa thanh cho tác phẩm"}], "correctOptionId": "c", "explanation": "Dịch chuyển điểm nhìn giúp soi chiếu nhân vật từ nhiều góc độ, làm hiện rõ những xung đột tinh tế trong tâm thức."}, {"id": "literature-12-modern-poetry-q1", "prompt": "Đặc điểm nổi bật về hình thức tổ chức nhịp điệu của thơ hiện đại so với thơ ca cổ điển là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn bắt buộc tuân thủ nghiêm ngặt luật bằng trắc và niêm luật cổ"}, {"id": "b", "text": "Hoàn toàn không bao giờ sử dụng vần điệu"}, {"id": "c", "text": "Nhịp điệu linh hoạt, phóng khoáng, biến đổi theo mạch vận động của cảm xúc"}], "correctOptionId": "c", "explanation": "Thơ hiện đại phá vỡ khuôn khổ niêm luật cứng nhắc để nhịp điệu tuôn chảy tự nhiên theo xung lực cảm xúc của cái tôi trữ tình."}, {"id": "literature-12-modern-poetry-q2", "prompt": "Yếu tố nào đóng vai trò là ''linh hồn'' định hình toàn bộ cấu tứ và hệ thống hình ảnh trong một bài thơ trữ tình?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tên gọi địa danh xuất hiện trong bài thơ"}, {"id": "b", "text": "Mạch cảm xúc và tư tưởng của chủ thể trữ tình"}, {"id": "c", "text": "Số lượng từ ngữ và số câu thơ trong một khổ"}], "correctOptionId": "b", "explanation": "Cảm xúc chân thực, mãnh liệt của chủ thể trữ tình là hạt nhân liên kết và chi phối việc lựa chọn hình ảnh, ngôn từ, nhạc điệu."}, {"id": "literature-12-dramatic-conflict-q1", "prompt": "Yếu tố then chốt tạo nên sức hấp dẫn và thúc đẩy toàn bộ cốt truyện kịch phát triển là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Lời bình luận của người dẫn chuyện gián tiếp"}, {"id": "b", "text": "Xung đột kịch"}, {"id": "c", "text": "Miêu tả cảnh thiên nhiên dài dòng"}], "correctOptionId": "b", "explanation": "Không có xung đột thì không có kịch; xung đột giữa các tính cách, quyền lợi, quan điểm là động lực của hành động kịch."}, {"id": "literature-12-dramatic-conflict-q2", "prompt": "Độc thoại nội tâm của nhân vật trong kịch có chức năng nghệ thuật chính là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bộc lộ trực tiếp những giằng xé, toan tính và thế giới tinh thần sâu kín của nhân vật"}, {"id": "b", "text": "Trao đổi thông tin hàng ngày với các nhân vật khác trên sân khấu"}, {"id": "c", "text": "Hướng dẫn diễn viên phụ cách di chuyển đạo cụ sân khấu"}], "correctOptionId": "a", "explanation": "Độc thoại nội tâm là tiếng nói cất lên từ đáy lòng nhân vật khi đối diện với chính mình, phơi bày những trăn trở dằn vặt sâu kín."}, {"id": "literature-12-rhetorical-devices-q1", "prompt": "Biện pháp tu từ nghịch ngữ (nghịch lí - paradox) có đặc điểm nổi bật nào sau đây?", "difficulty": "EASY", "options": [{"id": "a", "text": "Kết hợp những từ ngữ tưởng như mâu thuẫn đối lập nhưng lại diễn tả một chân lí sâu xa"}, {"id": "b", "text": "Liệt kê các sự vật đồng nghĩa liên tiếp nhau"}, {"id": "c", "text": "Nói quá sự thật gấp hàng nghìn lần để gây cười"}], "correctOptionId": "a", "explanation": "Nghịch ngữ tạo ra sự bất ngờ bằng cách ghép hai yếu tố tương phản, buộc người đọc suy ngẫm để nhận ra bản chất sâu kín."}, {"id": "literature-12-rhetorical-devices-q2", "prompt": "Cụm từ ''ánh nắng ngọt ngào rơi trên mái hiên'' sử dụng biện pháp tu từ nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "So sánh ngang bằng có từ như"}, {"id": "b", "text": "Nhân hóa đồ vật thành người"}, {"id": "c", "text": "Ẩn dụ chuyển đổi cảm giác (thị giác sang vị giác)"}], "correctOptionId": "c", "explanation": "Ánh nắng vốn cảm nhận bằng thị giác được miêu tả bằng tính từ ''ngọt ngào'' thuộc vị giác, tạo ấn tượng tinh tế."}, {"id": "literature-12-literary-critique-q1", "prompt": "Quá trình tiếp nhận văn học của bạn đọc được coi là một hoạt động:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tiếp thu thụ động y nguyên những gì tác giả viết mà không cần suy nghĩ"}, {"id": "b", "text": "Sao chép lại toàn bộ văn bản để lưu trữ cá nhân"}, {"id": "c", "text": "Đồng sáng tạo tích cực, làm sống dậy và làm phong phú thêm ý nghĩa của tác phẩm"}], "correctOptionId": "c", "explanation": "Người đọc mang vốn sống, trải nghiệm và cảm nhận riêng để lấp đầy các ''khoảng trống'' nghệ thuật, tạo nên đời sống sinh động cho tác phẩm."}, {"id": "literature-12-literary-critique-q2", "prompt": "Khi đánh giá giá trị tư tưởng của một tác phẩm văn học, người đọc cần đặt tác phẩm vào:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Số lượng bản in bán ra tại các hiệu sách"}, {"id": "b", "text": "Bối cảnh lịch sử, xã hội và văn hóa cụ thể của thời đại mà tác phẩm ra đời"}, {"id": "c", "text": "Chỉ dựa vào sở thích nhất thời của cá nhân người đọc"}], "correctOptionId": "b", "explanation": "Đặt tác phẩm vào hoàn cảnh lịch sử giúp đánh giá đúng tính tiên phong, giá trị hiện thực và chiều sâu nhân đạo của tác giả."}, {"id": "literature-12-argument-structure-q1", "prompt": "Trong cấu trúc của một văn bản nghị luận, ''luận điểm'' đóng vai trò là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Lời mở đầu giới thiệu tiểu sử tác giả"}, {"id": "b", "text": "Các ý kiến, quan điểm chính triển khai làm sáng tỏ cho luận đề của bài viết"}, {"id": "c", "text": "Các số liệu thống kê cụ thể trích dẫn từ bài báo"}], "correctOptionId": "b", "explanation": "Luận điểm là những phán đoán cốt lõi thể hiện quan điểm của người viết về từng khía cạnh của vấn đề nghị luận."}, {"id": "literature-12-argument-structure-q2", "prompt": "Yêu cầu quan trọng nhất đối với hệ thống luận cứ (lí lẽ và dẫn chứng) trong văn bản nghị luận là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Phải chân thực, tiêu biểu, xác đáng và có mối liên hệ logic chặt chẽ với luận điểm"}, {"id": "b", "text": "Càng dài dòng và nhiều chi tiết vụn vặt càng tốt"}, {"id": "c", "text": "Phải sử dụng hoàn toàn những câu chuyện hư cấu hoang đường"}], "correctOptionId": "a", "explanation": "Luận cứ xác thực, tiêu biểu mới đủ sức thuyết phục người đọc tin vào tính đúng đắn của luận điểm."}, {"id": "literature-12-evidence-evaluation-q1", "prompt": "Tiêu chí nào sau đây là quan trọng hàng đầu khi lựa chọn dẫn chứng cho bài văn nghị luận xã hội?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tính xác thực, khách quan và có nguồn gốc xuất xứ tin cậy"}, {"id": "b", "text": "Dẫn chứng phải hoàn toàn bí ẩn không ai kiểm chứng được"}, {"id": "c", "text": "Chỉ sử dụng những tin đồn chưa được kiểm chứng trên mạng"}], "correctOptionId": "a", "explanation": "Dẫn chứng khách quan, kiểm chứng được từ cơ quan chuyên môn mới tạo lập uy tín học thuật vững chắc cho bài viết."}, {"id": "literature-12-evidence-evaluation-q2", "prompt": "Lỗi ngụy biện ''khái quát hóa vội vã'' (hasty generalization) xảy ra khi người viết:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Phân tích quá sâu nguyên nhân sâu xa của vấn đề"}, {"id": "b", "text": "Trích dẫn đầy đủ số liệu điều tra diện rộng trên hàng triệu người"}, {"id": "c", "text": "Rút ra kết luận chung cho toàn bộ tập thể chỉ dựa trên một vài trường hợp cá biệt"}], "correctOptionId": "c", "explanation": "Lấy một vài ví dụ cá biệt không đại diện để quy chụp cho số đông là lỗi ngụy biện khái quát hóa vội vã."}, {"id": "literature-12-persuasive-rhetoric-q1", "prompt": "Phương thức thuyết phục dựa trên uy tín, phẩm hạnh và tư cách đạo đức của người nói trong thuật hùng biện được gọi là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Pathos"}, {"id": "b", "text": "Logos"}, {"id": "c", "text": "Ethos"}], "correctOptionId": "c", "explanation": "Trong thuật hùng biện Aristotle: Ethos là uy tín cá nhân, Pathos là tác động cảm xúc, Logos là lập luận logic."}, {"id": "literature-12-persuasive-rhetoric-q2", "prompt": "Khi muốn lay động lòng trắc ẩn và sự đồng cảm sâu sắc của người nghe về một mảnh đời bất hạnh, người viết thường sử dụng phương thức:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ đọc to danh mục văn bản luật pháp"}, {"id": "b", "text": "Pathos (tác động vào cảm xúc và tâm lí)"}, {"id": "c", "text": "Logos (lập luận toán học khô khan)"}], "correctOptionId": "b", "explanation": "Pathos hướng đến thế giới cảm xúc, chạm vào lòng nhân ái, sự sẻ chia của độc giả."}, {"id": "literature-12-social-argumentation-q1", "prompt": "Khi làm bài văn nghị luận về một vấn đề xã hội, thao tác đầu tiên sau khi giới thiệu vấn đề cần thực hiện là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Đưa ra ngay kết luận cuối cùng của bài viết"}, {"id": "b", "text": "Giải thích rõ nghĩa của các từ khóa và nội hàm cốt lõi của vấn đề"}, {"id": "c", "text": "Lập tức phê phán gay gắt những người có ý kiến trái chiều"}], "correctOptionId": "b", "explanation": "Giải thích khái niệm giúp xác lập định nghĩa chuẩn xác, tránh lạc đề hoặc hiểu sai lệch vấn đề trước khi bàn luận."}, {"id": "literature-12-social-argumentation-q2", "prompt": "Để các giải pháp đề xuất trong bài nghị luận xã hội có tính thuyết phục cao, người viết cần đảm bảo:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tính cụ thể, khả thi, phù hợp với thực tế và giải quyết trúng nguyên nhân gốc rễ"}, {"id": "b", "text": "Đưa ra những lời hứa hão huyền không ai làm được"}, {"id": "c", "text": "Chỉ yêu cầu người khác làm mà bản thân không cần thay đổi"}], "correctOptionId": "a", "explanation": "Giải pháp phải xuất phát từ nguyên nhân thực tế, có tính khả thi và phân định rõ trách nhiệm cá nhân, cộng đồng."}, {"id": "literature-12-literary-argumentation-q1", "prompt": "Khi viết bài văn nghị luận phân tích một tác phẩm văn học, người viết cần kết hợp chặt chẽ giữa hai yếu tố nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Phân tích nội dung tư tưởng và các thủ pháp nghệ thuật độc đáo"}, {"id": "b", "text": "Chỉ tóm tắt cốt truyện từ đầu đến cuối như văn kể chuyện"}, {"id": "c", "text": "Sao chép lại tiểu sử năm sinh năm mất của tác giả"}], "correctOptionId": "a", "explanation": "Tác phẩm văn học là sự thống nhất giữa nội dung và hình thức; nghệ thuật là phương tiện chuyên chở tư tưởng tác giả."}, {"id": "literature-12-literary-argumentation-q2", "prompt": "Thao tác ''so sánh văn học'' trong bài văn nghị luận có tác dụng nghệ thuật chủ yếu là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Để kéo dài dung lượng bài viết khi thiếu ý tưởng"}, {"id": "b", "text": "Khẳng định tác phẩm kia hoàn toàn vô giá trị"}, {"id": "c", "text": "Làm nổi bật nét độc đáo, dấu ấn phong cách riêng biệt của tác giả đang phân tích"}], "correctOptionId": "c", "explanation": "So sánh với tác phẩm cùng đề tài hoặc cùng thời kì giúp nhận diện rõ nét sáng tạo độc đáo riêng của nhà văn."}, {"id": "literature-12-informational-synthesis-q1", "prompt": "Trong một văn bản thông tin đa phương thức, các yếu tố phi ngôn ngữ (như biểu đồ, sơ đồ, hình ảnh) có vai trò:", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ để trang trí cho văn bản bớt tẻ nhạt mà không mang ý nghĩa gì"}, {"id": "b", "text": "Làm sai lệch thông tin của phần văn bản chữ viết"}, {"id": "c", "text": "Trực quan hóa dữ liệu phức tạp giúp người đọc tiếp nhận thông tin nhanh chóng và chính xác"}], "correctOptionId": "c", "explanation": "Yếu tố phi ngôn ngữ giúp cô đọng số liệu trực quan, tăng tính sinh động và hỗ trợ đắc lực cho văn bản thuyết minh."}, {"id": "literature-12-informational-synthesis-q2", "prompt": "Kĩ năng quan trọng nhất khi tổng hợp thông tin từ nhiều nguồn tài liệu khác nhau về cùng một đề tài là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ chọn nguồn tin có độ dài ngắn nhất để đọc"}, {"id": "b", "text": "So sánh, đối chiếu tính nhất quán của dữ liệu và chắt lọc các điểm đồng thuận cốt lõi"}, {"id": "c", "text": "Sao chép nguyên văn tất cả các tài liệu gom lại thành một tập dài"}], "correctOptionId": "b", "explanation": "Tổng hợp thông tin đòi hỏi tư duy phân tích, đối chiếu chéo để loại bỏ mâu thuẫn và xây dựng bức tranh tổng thể tin cậy."}, {"id": "literature-12-media-literacy-q1", "prompt": "Hiện tượng ''đóng khung thông điệp'' (framing) trong truyền thông đại chúng có nghĩa là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Hoàn toàn cấm đoán người dân phát biểu ý kiến cá nhân"}, {"id": "b", "text": "Cách thức cơ quan truyền thông lựa chọn nhấn mạnh một khía cạnh nhất định để định hướng cách nhìn của công chúng"}, {"id": "c", "text": "Đóng khung các bài báo in vào khung gỗ để treo tường"}], "correctOptionId": "b", "explanation": "Framing là kĩ thuật định hướng dư luận bằng cách làm nổi bật một góc nhìn cụ thể và làm lu mờ các góc nhìn khác."}, {"id": "literature-12-media-literacy-q2", "prompt": "Dấu hiệu điển hình của một tiêu đề mang tính chất ''mồi câu nhấp chuột'' (clickbait) trên mạng là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Sử dụng ngôn từ giật gân, lấp lửng, phóng đại cảm xúc để kích thích người dùng bấm vào xem"}, {"id": "b", "text": "Cung cấp đầy đủ thông tin tóm tắt khách quan ngay ở tiêu đề"}, {"id": "c", "text": "Trích dẫn chính xác báo cáo khoa học có nguồn thẩm định rõ ràng"}], "correctOptionId": "a", "explanation": "Clickbait dùng các từ khóa kích động cảm xúc tò mò, thường phóng đại hoặc làm sai lệch nội dung thực tế bên trong bài viết."}, {"id": "literature-12-research-report-q1", "prompt": "Phần ''Tóm tắt'' (Abstract) ở đầu một báo cáo nghiên cứu khoa học có nhiệm vụ chính là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tóm lược cô đọng mục tiêu, phương pháp, kết quả then chốt và kết luận của công trình"}, {"id": "b", "text": "Liệt kê danh sách tất cả các thành viên trong gia đình tác giả"}, {"id": "c", "text": "Trình bày chi tiết toàn bộ các bảng số liệu thô thu thập được"}], "correctOptionId": "a", "explanation": "Abstract giúp người đọc nhanh chóng nắm bắt bản chất và những phát hiện quan trọng nhất của công trình nghiên cứu."}, {"id": "literature-12-research-report-q2", "prompt": "Hành vi nào sau đây bị coi là ''đạo văn'' (plagiarism) nghiêm trọng trong nghiên cứu học thuật?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Trích dẫn nguyên văn câu nói của tác giả và đặt trong dấu ngoặc kép kèm ghi chú nguồn"}, {"id": "b", "text": "Diễn đạt lại ý kiến của chuyên gia và chú thích rõ tài liệu tham khảo"}, {"id": "c", "text": "Sử dụng ý tưởng hoặc câu chữ của người khác mà không dẫn nguồn và trích dẫn rõ ràng"}], "correctOptionId": "c", "explanation": "Đạo văn là hành vi chiếm đoạt sản phẩm trí tuệ khi sử dụng tư liệu của người khác như thể là của chính mình."}, {"id": "literature-12-formal-speech-q1", "prompt": "Kĩ thuật ''câu móc'' (hook) trong phần mở đầu của một bài thuyết trình được dùng để:", "difficulty": "EASY", "options": [{"id": "a", "text": "Đọc nhanh danh sách tất cả các tài liệu tham khảo của bài"}, {"id": "b", "text": "Xin lỗi khán giả vì chưa chuẩn bị bài kĩ càng"}, {"id": "c", "text": "Thu hút sự chú ý và khơi gợi trí tò mò của khán giả ngay từ những giây đầu tiên"}], "correctOptionId": "c", "explanation": "Hook (câu hỏi thú vị, số liệu gây sốc, câu chuyện ngắn) kết nối người nghe với chủ đề ngay từ lúc mở màn."}, {"id": "literature-12-formal-speech-q2", "prompt": "Khi thiết kế slide trình chiếu hỗ trợ bài thuyết trình, nguyên tắc quan trọng về mặt thị giác là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Dùng thật nhiều phông chữ sặc sỡ và hiệu ứng hoạt họa nhấp nháy liên tục"}, {"id": "b", "text": "Trình bày cô đọng, ưu tiên hình ảnh biểu đồ trực quan và hạn chế tối đa các đoạn văn bản dài"}, {"id": "c", "text": "Chép toàn bộ nguyên văn bài nói lên màn hình để đọc lại từng chữ"}], "correctOptionId": "b", "explanation": "Slide chỉ mang tính trực quan hỗ trợ; văn bản quá nhiều sẽ làm khán giả mải đọc chữ và phân tâm khỏi lời nói của diễn giả."}, {"id": "literature-12-debate-skills-q1", "prompt": "Trong mô hình tranh biện học thuật tiêu chuẩn, một lập luận hoàn chỉnh bao gồm các thành tố cốt lõi nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Những lời công kích đời tư nhằm làm đối phương mất bình tĩnh"}, {"id": "b", "text": "Luận điểm khẳng định, lí lẽ giải thích và dẫn chứng thực tế minh chứng"}, {"id": "c", "text": "Chỉ gồm một lời khẳng định to tiếng và áp đặt"}], "correctOptionId": "b", "explanation": "Mô hình ARE (Assertion, Reasoning, Evidence) là tiêu chuẩn vàng cho một luận cứ tranh biện logic và thuyết phục."}, {"id": "literature-12-debate-skills-q2", "prompt": "Thao tác phản biện hiệu quả nhất khi đối thoại tranh luận với ý kiến trái chiều là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tập trung phân tích lỗ hổng logic hoặc tính thiếu căn cứ của dẫn chứng mà đối phương đưa ra"}, {"id": "b", "text": "Ngắt lời đối phương liên tục không cho họ phát biểu"}, {"id": "c", "text": "Lặp đi lặp lại ý kiến của mình với giọng điệu to hơn"}], "correctOptionId": "a", "explanation": "Phản biện sắc bén nhắm thẳng vào giả định sai lầm, sự thiếu hụt bằng chứng hoặc nghịch lí logic trong lập luận của đối thủ."}]'::jsonb,'[]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-narrative-voice',1,'LESSON','Điểm nhìn và ngôi kể trong truyện hiện đại','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Ngôi kể thứ nhất (nhân vật xưng ''tôi'' - trực tiếp, chủ quan) và ngôi thứ ba (người kể giấu mình, toàn tri hoặc hạn tri). Điểm nhìn: bên trong (tâm lí nhân vật) vs bên ngoài. Sự dịch chuyển điểm nhìn làm tăng chiều sâu tâm lí và tính đa thanh của tác phẩm."]'::jsonb,'["Trong truyện ngắn hiện đại, người kể chuyện chuyển từ điểm nhìn khách quan bên ngoài sang điểm nhìn bên trong tâm tư của nhân vật để làm nổi bật dằn vặt nội tâm."]'::jsonb,'[{"id": "literature-12-narrative-voice-q1", "prompt": "Người kể chuyện toàn tri trong tác phẩm tự sự là người kể chuyện:", "difficulty": "EASY", "options": [{"id": "a", "text": "Biết hết mọi hành động, suy nghĩ và quá khứ của tất cả các nhân vật"}, {"id": "b", "text": "Chỉ biết những gì nhân vật chính tận mắt chứng kiến"}, {"id": "c", "text": "Luôn xuất hiện trực tiếp dưới danh xưng tôi"}], "correctOptionId": "a", "explanation": "Người kể toàn tri (omniscient) đứng ngoài câu chuyện nhưng thấu suốt toàn bộ thế giới nội tâm và hành động của mọi nhân vật."}, {"id": "literature-12-narrative-voice-q2", "prompt": "Việc chuyển đổi linh hoạt giữa điểm nhìn bên ngoài và điểm nhìn bên trong trong truyện ngắn hiện đại có tác dụng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Làm người đọc hoàn toàn không hiểu được diễn biến cốt truyện"}, {"id": "b", "text": "Rút ngắn tối đa dung lượng của văn bản"}, {"id": "c", "text": "Khám phá chiều sâu tâm lí phức tạp và tạo tính đa thanh cho tác phẩm"}], "correctOptionId": "c", "explanation": "Dịch chuyển điểm nhìn giúp soi chiếu nhân vật từ nhiều góc độ, làm hiện rõ những xung đột tinh tế trong tâm thức."}, {"id": "literature-12-narrative-voice-q3", "prompt": "Đọc đoạn văn miêu tả: ''Gió lạnh thấu xương lùa qua khe cửa. Nó co ro kéo tấm chăn rách, thầm nghĩ chẳng biết ngày mai có còn việc để làm''. Điểm nhìn trần thuật ở đây là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Điểm nhìn của nhân vật xưng tôi ngôi thứ nhất"}, {"id": "b", "text": "Điểm nhìn bên trong kết hợp lời nửa trực tiếp của nhân vật"}, {"id": "c", "text": "Điểm nhìn hoàn toàn khách quan không biểu lộ cảm xúc"}], "correctOptionId": "b", "explanation": "Người kể chuyện thâm nhập vào suy tư lo âu của nhân vật (''thầm nghĩ chẳng biết ngày mai...'') thể hiện điểm nhìn bên trong."}]'::jsonb,'["literature-12-narrative-voice"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-modern-poetry',2,'LESSON','Hình tượng và cảm xúc trong thơ hiện đại','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Thơ hiện đại tự do về vần điệu, nhịp điệu co duỗi linh hoạt theo dòng cảm xúc. Hình tượng thơ mang tính biểu tượng, liên tưởng bất ngờ, phá vỡ ước lệ cổ điển. Giọng điệu đa dạng: trữ tình sâu lắng, triết lí chiêm nghiệm, hoặc xót xa trăn trở."]'::jsonb,'["Câu thơ hiện đại dùng hình ảnh ''mùa thu lá rụng như chiếc vé tàu đã hết hạn'' tạo liên tưởng độc đáo về thời gian trôi qua không thể lấy lại."]'::jsonb,'[{"id": "literature-12-modern-poetry-q1", "prompt": "Đặc điểm nổi bật về hình thức tổ chức nhịp điệu của thơ hiện đại so với thơ ca cổ điển là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn bắt buộc tuân thủ nghiêm ngặt luật bằng trắc và niêm luật cổ"}, {"id": "b", "text": "Hoàn toàn không bao giờ sử dụng vần điệu"}, {"id": "c", "text": "Nhịp điệu linh hoạt, phóng khoáng, biến đổi theo mạch vận động của cảm xúc"}], "correctOptionId": "c", "explanation": "Thơ hiện đại phá vỡ khuôn khổ niêm luật cứng nhắc để nhịp điệu tuôn chảy tự nhiên theo xung lực cảm xúc của cái tôi trữ tình."}, {"id": "literature-12-modern-poetry-q2", "prompt": "Yếu tố nào đóng vai trò là ''linh hồn'' định hình toàn bộ cấu tứ và hệ thống hình ảnh trong một bài thơ trữ tình?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tên gọi địa danh xuất hiện trong bài thơ"}, {"id": "b", "text": "Mạch cảm xúc và tư tưởng của chủ thể trữ tình"}, {"id": "c", "text": "Số lượng từ ngữ và số câu thơ trong một khổ"}], "correctOptionId": "b", "explanation": "Cảm xúc chân thực, mãnh liệt của chủ thể trữ tình là hạt nhân liên kết và chi phối việc lựa chọn hình ảnh, ngôn từ, nhạc điệu."}, {"id": "literature-12-modern-poetry-q3", "prompt": "Khi phân tích một hình ảnh thơ mang tính biểu tượng đa nghĩa, người đọc cần chú ý nhất điều gì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Đặt hình ảnh trong chỉnh thể bài thơ và mối liên hệ giữa nghĩa thực với các lớp nghĩa liên tưởng sâu xa"}, {"id": "b", "text": "Chỉ tra cứu nghĩa đen thuần túy của từ ngữ trong từ điển tiếng Việt"}, {"id": "c", "text": "Xem xét độ dài của câu thơ chứa hình ảnh đó"}], "correctOptionId": "a", "explanation": "Biểu tượng thơ luôn có tầng nghĩa thực và các lớp nghĩa ẩn dụ, biểu cảm cần được giải mã qua ngữ cảnh chỉnh thể tác phẩm."}]'::jsonb,'["literature-12-modern-poetry"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-dramatic-conflict',3,'LESSON','Xung đột kịch và hành động kịch','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Xung đột kịch là động lực phát triển cốt truyện kịch (xung đột giữa cái thiện và cái ác, giữa khát vọng và hoàn cảnh thực tại, xung đột nội tâm). Hành động kịch thể hiện qua lời thoại (đối thoại, độc thoại, độc thoại nội tâm). Sự thanh lọc (catharsis) giúp người xem thấu hiểu và nâng cao tâm hồn."]'::jsonb,'["Trong vở kịch hiện đại, xung đột nổ ra giữa hai thế hệ: người cha muốn bảo thủ nếp cũ và người con muốn đổi mới tư duy kinh doanh."]'::jsonb,'[{"id": "literature-12-dramatic-conflict-q1", "prompt": "Yếu tố then chốt tạo nên sức hấp dẫn và thúc đẩy toàn bộ cốt truyện kịch phát triển là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Lời bình luận của người dẫn chuyện gián tiếp"}, {"id": "b", "text": "Xung đột kịch"}, {"id": "c", "text": "Miêu tả cảnh thiên nhiên dài dòng"}], "correctOptionId": "b", "explanation": "Không có xung đột thì không có kịch; xung đột giữa các tính cách, quyền lợi, quan điểm là động lực của hành động kịch."}, {"id": "literature-12-dramatic-conflict-q2", "prompt": "Độc thoại nội tâm của nhân vật trong kịch có chức năng nghệ thuật chính là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bộc lộ trực tiếp những giằng xé, toan tính và thế giới tinh thần sâu kín của nhân vật"}, {"id": "b", "text": "Trao đổi thông tin hàng ngày với các nhân vật khác trên sân khấu"}, {"id": "c", "text": "Hướng dẫn diễn viên phụ cách di chuyển đạo cụ sân khấu"}], "correctOptionId": "a", "explanation": "Độc thoại nội tâm là tiếng nói cất lên từ đáy lòng nhân vật khi đối diện với chính mình, phơi bày những trăn trở dằn vặt sâu kín."}, {"id": "literature-12-dramatic-conflict-q3", "prompt": "Khái niệm ''thanh lọc'' (catharsis) trong tiếp nhận nghệ thuật kịch có ý nghĩa gì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Làm khán giả cảm thấy hoàn toàn tuyệt vọng và mất niềm tin vào cuộc sống"}, {"id": "b", "text": "Xóa sạch toàn bộ trí nhớ của người xem sau khi rời rạp hát"}, {"id": "c", "text": "Nâng đỡ, thanh lọc tâm hồn khán giả qua việc đồng cảm với nỗi đau và sự chiến thắng đạo đức của nhân vật"}], "correctOptionId": "c", "explanation": "Theo mĩ học từ thời Aristotle, trải nghiệm bi kịch giúp khán giả trải qua nỗi sợ và lòng trắc ẩn để thanh lọc cảm xúc, vươn tới cái đẹp."}]'::jsonb,'["literature-12-dramatic-conflict"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-rhetorical-devices',4,'LESSON','Biện pháp tu từ và hiệu quả biểu đạt nâng cao','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Nghịch ngữ (oxymoron / paradox): kết hợp những khái niệm tưởng chừng mâu thuẫn để làm nổi bật chân lí sâu sắc. Ẩn dụ chuyển đổi cảm giác. Nói mỉa (irony): tạo khoảng cách giữa nghĩa bề mặt và nghĩa hàm ẩn. Điệp cấu trúc tạo âm hưởng hùng hồn hoặc da diết."]'::jsonb,'["Cụm từ ''tiếng im lặng chói chang'' là nghịch ngữ kết hợp ẩn dụ chuyển đổi cảm giác, nhấn mạnh sự cô đơn tột cùng."]'::jsonb,'[{"id": "literature-12-rhetorical-devices-q1", "prompt": "Biện pháp tu từ nghịch ngữ (nghịch lí - paradox) có đặc điểm nổi bật nào sau đây?", "difficulty": "EASY", "options": [{"id": "a", "text": "Kết hợp những từ ngữ tưởng như mâu thuẫn đối lập nhưng lại diễn tả một chân lí sâu xa"}, {"id": "b", "text": "Liệt kê các sự vật đồng nghĩa liên tiếp nhau"}, {"id": "c", "text": "Nói quá sự thật gấp hàng nghìn lần để gây cười"}], "correctOptionId": "a", "explanation": "Nghịch ngữ tạo ra sự bất ngờ bằng cách ghép hai yếu tố tương phản, buộc người đọc suy ngẫm để nhận ra bản chất sâu kín."}, {"id": "literature-12-rhetorical-devices-q2", "prompt": "Cụm từ ''ánh nắng ngọt ngào rơi trên mái hiên'' sử dụng biện pháp tu từ nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "So sánh ngang bằng có từ như"}, {"id": "b", "text": "Nhân hóa đồ vật thành người"}, {"id": "c", "text": "Ẩn dụ chuyển đổi cảm giác (thị giác sang vị giác)"}], "correctOptionId": "c", "explanation": "Ánh nắng vốn cảm nhận bằng thị giác được miêu tả bằng tính từ ''ngọt ngào'' thuộc vị giác, tạo ấn tượng tinh tế."}, {"id": "literature-12-rhetorical-devices-q3", "prompt": "Tác dụng thẩm mĩ lớn nhất của thủ pháp mỉa mai (irony) trong văn học châm biếm là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Tuyên truyền trực tiếp các điều luật pháp lý khô khan"}, {"id": "b", "text": "Tạo khoảng cách giữa lời nói bề mặt và ý nghĩa thực tế để phê phán thói hư tật xấu"}, {"id": "c", "text": "Làm cho câu văn trở nên dài dòng và khó hiểu"}], "correctOptionId": "b", "explanation": "Mỉa mai dùng lời nói có vẻ khen ngợi hoặc vô tư để ngầm lật tẩy, chế giễu những hiện tượng lố lăng, bất công."}]'::jsonb,'["literature-12-rhetorical-devices"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-literary-critique',5,'LESSON','Tiếp nhận và đánh giá tác phẩm văn học','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Tiếp nhận văn học là hoạt động sáng tạo của người đọc: từ văn bản ngôn từ đồng sáng tạo ra thế giới hình tượng. Ý thức về bối cảnh lịch sử - văn hóa của thời đại ra đời tác phẩm. Tính đa nghĩa và đời sống lịch sử của tác phẩm qua các thời kì khác nhau."]'::jsonb,'["Một tác phẩm viết về số phận con người trong chiến tranh khi đọc trong thời bình gợi lên những suy ngẫm nhân bản về hòa bình và lòng vị tha."]'::jsonb,'[{"id": "literature-12-literary-critique-q1", "prompt": "Quá trình tiếp nhận văn học của bạn đọc được coi là một hoạt động:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tiếp thu thụ động y nguyên những gì tác giả viết mà không cần suy nghĩ"}, {"id": "b", "text": "Sao chép lại toàn bộ văn bản để lưu trữ cá nhân"}, {"id": "c", "text": "Đồng sáng tạo tích cực, làm sống dậy và làm phong phú thêm ý nghĩa của tác phẩm"}], "correctOptionId": "c", "explanation": "Người đọc mang vốn sống, trải nghiệm và cảm nhận riêng để lấp đầy các ''khoảng trống'' nghệ thuật, tạo nên đời sống sinh động cho tác phẩm."}, {"id": "literature-12-literary-critique-q2", "prompt": "Khi đánh giá giá trị tư tưởng của một tác phẩm văn học, người đọc cần đặt tác phẩm vào:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Số lượng bản in bán ra tại các hiệu sách"}, {"id": "b", "text": "Bối cảnh lịch sử, xã hội và văn hóa cụ thể của thời đại mà tác phẩm ra đời"}, {"id": "c", "text": "Chỉ dựa vào sở thích nhất thời của cá nhân người đọc"}], "correctOptionId": "b", "explanation": "Đặt tác phẩm vào hoàn cảnh lịch sử giúp đánh giá đúng tính tiên phong, giá trị hiện thực và chiều sâu nhân đạo của tác giả."}, {"id": "literature-12-literary-critique-q3", "prompt": "Hiện tượng một tác phẩm kinh điển có nhiều cách hiểu và bình luận khác nhau qua các thời kì lịch sử chứng minh:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Tác phẩm văn học chân chính luôn có tính đa nghĩa và sức sống vượt thời gian"}, {"id": "b", "text": "Tác giả tác phẩm đó viết sai ngữ pháp nghiêm trọng"}, {"id": "c", "text": "Tác phẩm hoàn toàn không có giá trị nội dung cụ thể"}], "correctOptionId": "a", "explanation": "Văn học nghệ thuật giàu biểu tượng và chiều sâu nhân bản nên luôn mở ra những góc nhìn mới cho mỗi thế hệ độc giả."}]'::jsonb,'["literature-12-literary-critique"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-review-1',6,'FIVE_LESSON_REVIEW','Ôn tập 1','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "literature-12-narrative-voice-q1", "prompt": "Người kể chuyện toàn tri trong tác phẩm tự sự là người kể chuyện:", "difficulty": "EASY", "options": [{"id": "a", "text": "Biết hết mọi hành động, suy nghĩ và quá khứ của tất cả các nhân vật"}, {"id": "b", "text": "Chỉ biết những gì nhân vật chính tận mắt chứng kiến"}, {"id": "c", "text": "Luôn xuất hiện trực tiếp dưới danh xưng tôi"}], "correctOptionId": "a", "explanation": "Người kể toàn tri (omniscient) đứng ngoài câu chuyện nhưng thấu suốt toàn bộ thế giới nội tâm và hành động của mọi nhân vật."}, {"id": "literature-12-narrative-voice-q2", "prompt": "Việc chuyển đổi linh hoạt giữa điểm nhìn bên ngoài và điểm nhìn bên trong trong truyện ngắn hiện đại có tác dụng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Làm người đọc hoàn toàn không hiểu được diễn biến cốt truyện"}, {"id": "b", "text": "Rút ngắn tối đa dung lượng của văn bản"}, {"id": "c", "text": "Khám phá chiều sâu tâm lí phức tạp và tạo tính đa thanh cho tác phẩm"}], "correctOptionId": "c", "explanation": "Dịch chuyển điểm nhìn giúp soi chiếu nhân vật từ nhiều góc độ, làm hiện rõ những xung đột tinh tế trong tâm thức."}, {"id": "literature-12-modern-poetry-q1", "prompt": "Đặc điểm nổi bật về hình thức tổ chức nhịp điệu của thơ hiện đại so với thơ ca cổ điển là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Luôn bắt buộc tuân thủ nghiêm ngặt luật bằng trắc và niêm luật cổ"}, {"id": "b", "text": "Hoàn toàn không bao giờ sử dụng vần điệu"}, {"id": "c", "text": "Nhịp điệu linh hoạt, phóng khoáng, biến đổi theo mạch vận động của cảm xúc"}], "correctOptionId": "c", "explanation": "Thơ hiện đại phá vỡ khuôn khổ niêm luật cứng nhắc để nhịp điệu tuôn chảy tự nhiên theo xung lực cảm xúc của cái tôi trữ tình."}, {"id": "literature-12-modern-poetry-q2", "prompt": "Yếu tố nào đóng vai trò là ''linh hồn'' định hình toàn bộ cấu tứ và hệ thống hình ảnh trong một bài thơ trữ tình?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tên gọi địa danh xuất hiện trong bài thơ"}, {"id": "b", "text": "Mạch cảm xúc và tư tưởng của chủ thể trữ tình"}, {"id": "c", "text": "Số lượng từ ngữ và số câu thơ trong một khổ"}], "correctOptionId": "b", "explanation": "Cảm xúc chân thực, mãnh liệt của chủ thể trữ tình là hạt nhân liên kết và chi phối việc lựa chọn hình ảnh, ngôn từ, nhạc điệu."}, {"id": "literature-12-dramatic-conflict-q1", "prompt": "Yếu tố then chốt tạo nên sức hấp dẫn và thúc đẩy toàn bộ cốt truyện kịch phát triển là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Lời bình luận của người dẫn chuyện gián tiếp"}, {"id": "b", "text": "Xung đột kịch"}, {"id": "c", "text": "Miêu tả cảnh thiên nhiên dài dòng"}], "correctOptionId": "b", "explanation": "Không có xung đột thì không có kịch; xung đột giữa các tính cách, quyền lợi, quan điểm là động lực của hành động kịch."}, {"id": "literature-12-dramatic-conflict-q2", "prompt": "Độc thoại nội tâm của nhân vật trong kịch có chức năng nghệ thuật chính là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bộc lộ trực tiếp những giằng xé, toan tính và thế giới tinh thần sâu kín của nhân vật"}, {"id": "b", "text": "Trao đổi thông tin hàng ngày với các nhân vật khác trên sân khấu"}, {"id": "c", "text": "Hướng dẫn diễn viên phụ cách di chuyển đạo cụ sân khấu"}], "correctOptionId": "a", "explanation": "Độc thoại nội tâm là tiếng nói cất lên từ đáy lòng nhân vật khi đối diện với chính mình, phơi bày những trăn trở dằn vặt sâu kín."}, {"id": "literature-12-rhetorical-devices-q1", "prompt": "Biện pháp tu từ nghịch ngữ (nghịch lí - paradox) có đặc điểm nổi bật nào sau đây?", "difficulty": "EASY", "options": [{"id": "a", "text": "Kết hợp những từ ngữ tưởng như mâu thuẫn đối lập nhưng lại diễn tả một chân lí sâu xa"}, {"id": "b", "text": "Liệt kê các sự vật đồng nghĩa liên tiếp nhau"}, {"id": "c", "text": "Nói quá sự thật gấp hàng nghìn lần để gây cười"}], "correctOptionId": "a", "explanation": "Nghịch ngữ tạo ra sự bất ngờ bằng cách ghép hai yếu tố tương phản, buộc người đọc suy ngẫm để nhận ra bản chất sâu kín."}, {"id": "literature-12-rhetorical-devices-q2", "prompt": "Cụm từ ''ánh nắng ngọt ngào rơi trên mái hiên'' sử dụng biện pháp tu từ nào sau đây?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "So sánh ngang bằng có từ như"}, {"id": "b", "text": "Nhân hóa đồ vật thành người"}, {"id": "c", "text": "Ẩn dụ chuyển đổi cảm giác (thị giác sang vị giác)"}], "correctOptionId": "c", "explanation": "Ánh nắng vốn cảm nhận bằng thị giác được miêu tả bằng tính từ ''ngọt ngào'' thuộc vị giác, tạo ấn tượng tinh tế."}, {"id": "literature-12-literary-critique-q1", "prompt": "Quá trình tiếp nhận văn học của bạn đọc được coi là một hoạt động:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tiếp thu thụ động y nguyên những gì tác giả viết mà không cần suy nghĩ"}, {"id": "b", "text": "Sao chép lại toàn bộ văn bản để lưu trữ cá nhân"}, {"id": "c", "text": "Đồng sáng tạo tích cực, làm sống dậy và làm phong phú thêm ý nghĩa của tác phẩm"}], "correctOptionId": "c", "explanation": "Người đọc mang vốn sống, trải nghiệm và cảm nhận riêng để lấp đầy các ''khoảng trống'' nghệ thuật, tạo nên đời sống sinh động cho tác phẩm."}, {"id": "literature-12-literary-critique-q2", "prompt": "Khi đánh giá giá trị tư tưởng của một tác phẩm văn học, người đọc cần đặt tác phẩm vào:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Số lượng bản in bán ra tại các hiệu sách"}, {"id": "b", "text": "Bối cảnh lịch sử, xã hội và văn hóa cụ thể của thời đại mà tác phẩm ra đời"}, {"id": "c", "text": "Chỉ dựa vào sở thích nhất thời của cá nhân người đọc"}], "correctOptionId": "b", "explanation": "Đặt tác phẩm vào hoàn cảnh lịch sử giúp đánh giá đúng tính tiên phong, giá trị hiện thực và chiều sâu nhân đạo của tác giả."}]'::jsonb,'["literature-12-narrative-voice", "literature-12-modern-poetry", "literature-12-dramatic-conflict", "literature-12-rhetorical-devices", "literature-12-literary-critique"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-argument-structure',7,'LESSON','Cấu trúc luận điểm trong văn bản nghị luận','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Luận đề (vấn đề chính) -> Luận điểm (các khía cạnh then chốt) -> Luận cứ (lý lẽ và dẫn chứng minh họa). Mối liên hệ logic giữa các luận điểm: song song, móc xích, tổng - phân - hợp. Tính mạch lạc và liên kết câu, đoạn."]'::jsonb,'["Luận đề ''Bảo vệ nguồn nước sạch'': Luận điểm 1 (Vai trò sống còn của nước), Luận điểm 2 (Thực trạng ô nhiễm), Luận điểm 3 (Giải pháp hành động)."]'::jsonb,'[{"id": "literature-12-argument-structure-q1", "prompt": "Trong cấu trúc của một văn bản nghị luận, ''luận điểm'' đóng vai trò là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Lời mở đầu giới thiệu tiểu sử tác giả"}, {"id": "b", "text": "Các ý kiến, quan điểm chính triển khai làm sáng tỏ cho luận đề của bài viết"}, {"id": "c", "text": "Các số liệu thống kê cụ thể trích dẫn từ bài báo"}], "correctOptionId": "b", "explanation": "Luận điểm là những phán đoán cốt lõi thể hiện quan điểm của người viết về từng khía cạnh của vấn đề nghị luận."}, {"id": "literature-12-argument-structure-q2", "prompt": "Yêu cầu quan trọng nhất đối với hệ thống luận cứ (lí lẽ và dẫn chứng) trong văn bản nghị luận là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Phải chân thực, tiêu biểu, xác đáng và có mối liên hệ logic chặt chẽ với luận điểm"}, {"id": "b", "text": "Càng dài dòng và nhiều chi tiết vụn vặt càng tốt"}, {"id": "c", "text": "Phải sử dụng hoàn toàn những câu chuyện hư cấu hoang đường"}], "correctOptionId": "a", "explanation": "Luận cứ xác thực, tiêu biểu mới đủ sức thuyết phục người đọc tin vào tính đúng đắn của luận điểm."}, {"id": "literature-12-argument-structure-q3", "prompt": "Mô hình lập luận ''Tổng - Phân - Hợp'' trong đoạn văn nghị luận có tiến trình triển khai như thế nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Đi từ ví dụ cụ thể rồi mới kết luận mà không có phần phân tích"}, {"id": "b", "text": "Nêu ba ý kiến hoàn toàn trái ngược nhau mà không có kết luận"}, {"id": "c", "text": "Nêu ý khái quát toàn đoạn, sau đó phân tích các khía cạnh cụ thể, cuối cùng tổng hợp và nâng cao"}], "correctOptionId": "c", "explanation": "''Tổng'' nêu luận điểm ban đầu, ''Phân'' triển khai các lí lẽ dẫn chứng, ''Hợp'' khái quát lại vấn đề ở tầm nhận thức cao hơn."}]'::jsonb,'["literature-12-argument-structure"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-evidence-evaluation',8,'LESSON','Thẩm định tính xác thực và logic của dẫn chứng','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Phân biệt sự thật (fact) và ý kiến cá nhân (opinion). Thẩm định dẫn chứng: nguồn gốc tin cậy, tính cập nhật, tính đại diện, tính liên quan trực tiếp đến luận điểm. Nhận diện ngụy biện: khái quát hóa vội vã, dẫn chứng thiên kiến."]'::jsonb,'["Trích dẫn số liệu tỉ lệ thất nghiệp từ Tổng cục Thống kê có độ tin cậy cao hơn hẳn trích dẫn từ một bình luận ẩn danh trên mạng xã hội."]'::jsonb,'[{"id": "literature-12-evidence-evaluation-q1", "prompt": "Tiêu chí nào sau đây là quan trọng hàng đầu khi lựa chọn dẫn chứng cho bài văn nghị luận xã hội?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tính xác thực, khách quan và có nguồn gốc xuất xứ tin cậy"}, {"id": "b", "text": "Dẫn chứng phải hoàn toàn bí ẩn không ai kiểm chứng được"}, {"id": "c", "text": "Chỉ sử dụng những tin đồn chưa được kiểm chứng trên mạng"}], "correctOptionId": "a", "explanation": "Dẫn chứng khách quan, kiểm chứng được từ cơ quan chuyên môn mới tạo lập uy tín học thuật vững chắc cho bài viết."}, {"id": "literature-12-evidence-evaluation-q2", "prompt": "Lỗi ngụy biện ''khái quát hóa vội vã'' (hasty generalization) xảy ra khi người viết:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Phân tích quá sâu nguyên nhân sâu xa của vấn đề"}, {"id": "b", "text": "Trích dẫn đầy đủ số liệu điều tra diện rộng trên hàng triệu người"}, {"id": "c", "text": "Rút ra kết luận chung cho toàn bộ tập thể chỉ dựa trên một vài trường hợp cá biệt"}], "correctOptionId": "c", "explanation": "Lấy một vài ví dụ cá biệt không đại diện để quy chụp cho số đông là lỗi ngụy biện khái quát hóa vội vã."}, {"id": "literature-12-evidence-evaluation-q3", "prompt": "Đọc câu sau: ''Nhạc sĩ đó rất tài hoa vì nhiều người nói âm nhạc của ông thật tuyệt vời''. Câu này mắc lỗi logic nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Nhầm lẫn giữa nguyên nhân và kết quả thời gian"}, {"id": "b", "text": "Lập luận vòng quanh (chứng minh điều A bằng điều A được diễn đạt lại)"}, {"id": "c", "text": "So sánh khập khiễng hai sự vật không liên quan"}], "correctOptionId": "b", "explanation": "Khẳng định ''tài hoa'' bằng lý lẽ ''nhiều người khen tuyệt vời'' không đưa ra bằng chứng thực tế nào về chất lượng tác phẩm, là lập luận vòng tròn."}]'::jsonb,'["literature-12-evidence-evaluation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-persuasive-rhetoric',9,'LESSON','Ngôn ngữ và thủ pháp thuyết phục','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Ba phương thức thuyết phục cổ điển: Ethos (xây dựng uy tín cá nhân), Pathos (lay động cảm xúc, trắc ẩn), Logos (lập luận logic, bằng chứng xác thực). Giọng điệu phù hợp, ngôn từ chính xác, mạch lạc, tránh công kích cá nhân (ad hominem)."]'::jsonb,'["Diễn giả kêu gọi bảo vệ môi trường vừa đưa ra số liệu biến đổi khí hậu (Logos), vừa thể hiện trách nhiệm công dân (Ethos), vừa khơi gợi tình yêu với thiên nhiên (Pathos)."]'::jsonb,'[{"id": "literature-12-persuasive-rhetoric-q1", "prompt": "Phương thức thuyết phục dựa trên uy tín, phẩm hạnh và tư cách đạo đức của người nói trong thuật hùng biện được gọi là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Pathos"}, {"id": "b", "text": "Logos"}, {"id": "c", "text": "Ethos"}], "correctOptionId": "c", "explanation": "Trong thuật hùng biện Aristotle: Ethos là uy tín cá nhân, Pathos là tác động cảm xúc, Logos là lập luận logic."}, {"id": "literature-12-persuasive-rhetoric-q2", "prompt": "Khi muốn lay động lòng trắc ẩn và sự đồng cảm sâu sắc của người nghe về một mảnh đời bất hạnh, người viết thường sử dụng phương thức:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ đọc to danh mục văn bản luật pháp"}, {"id": "b", "text": "Pathos (tác động vào cảm xúc và tâm lí)"}, {"id": "c", "text": "Logos (lập luận toán học khô khan)"}], "correctOptionId": "b", "explanation": "Pathos hướng đến thế giới cảm xúc, chạm vào lòng nhân ái, sự sẻ chia của độc giả."}, {"id": "literature-12-persuasive-rhetoric-q3", "prompt": "Lỗi ngụy biện ''công kích cá nhân'' (ad hominem) trong văn bản tranh luận xảy ra khi:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Tấn công vào đời tư, tính cách của đối phương thay vì phản bác luận điểm của họ"}, {"id": "b", "text": "Chỉ ra điểm thiếu logic trong lập luận của đối phương"}, {"id": "c", "text": "Dẫn chứng số liệu khoa học chứng minh đối phương tính toán sai"}], "correctOptionId": "a", "explanation": "Ad hominem là lỗi chuyển hướng công kích vào con người đối thoại thay vì thảo luận thẳng thắn về luận điểm tranh cãi."}]'::jsonb,'["literature-12-persuasive-rhetoric"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-social-argumentation',10,'LESSON','Nghị luận về một vấn đề xã hội','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Các bước viết bài nghị luận xã hội: giải thích khái niệm, phân tích thực trạng, chỉ ra nguyên nhân (chủ quan, khách quan), đánh giá hậu quả/ý nghĩa, đề xuất giải pháp khả thi và rút ra bài học cho bản thân. Tránh viết chung chung, sáo rỗng."]'::jsonb,'["Bàn về ''Văn hóa ứng xử trên không gian mạng'': nêu hiện tượng bạo lực mạng, nguyên nhân do ẩn danh và thiếu kĩ năng số, giải pháp luật an ninh mạng và giáo dục tự giác."]'::jsonb,'[{"id": "literature-12-social-argumentation-q1", "prompt": "Khi làm bài văn nghị luận về một vấn đề xã hội, thao tác đầu tiên sau khi giới thiệu vấn đề cần thực hiện là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Đưa ra ngay kết luận cuối cùng của bài viết"}, {"id": "b", "text": "Giải thích rõ nghĩa của các từ khóa và nội hàm cốt lõi của vấn đề"}, {"id": "c", "text": "Lập tức phê phán gay gắt những người có ý kiến trái chiều"}], "correctOptionId": "b", "explanation": "Giải thích khái niệm giúp xác lập định nghĩa chuẩn xác, tránh lạc đề hoặc hiểu sai lệch vấn đề trước khi bàn luận."}, {"id": "literature-12-social-argumentation-q2", "prompt": "Để các giải pháp đề xuất trong bài nghị luận xã hội có tính thuyết phục cao, người viết cần đảm bảo:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tính cụ thể, khả thi, phù hợp với thực tế và giải quyết trúng nguyên nhân gốc rễ"}, {"id": "b", "text": "Đưa ra những lời hứa hão huyền không ai làm được"}, {"id": "c", "text": "Chỉ yêu cầu người khác làm mà bản thân không cần thay đổi"}], "correctOptionId": "a", "explanation": "Giải pháp phải xuất phát từ nguyên nhân thực tế, có tính khả thi và phân định rõ trách nhiệm cá nhân, cộng đồng."}, {"id": "literature-12-social-argumentation-q3", "prompt": "Việc xem xét một vấn đề xã hội từ nhiều góc độ đa chiều (kinh tế, văn hóa, tâm lí lứa tuổi) giúp bài viết:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Trở nên mâu thuẫn và tự bác bỏ chính mình"}, {"id": "b", "text": "Làm người chấm điểm không nhận ra quan điểm của tác giả"}, {"id": "c", "text": "Tránh được cái nhìn phiến diện, cực đoan và thể hiện tư duy phản biện sắc bén"}], "correctOptionId": "c", "explanation": "Tư duy đa chiều giúp nhận định thấu đáo bản chất phức tạp của đời sống xã hội, nâng cao tính thuyết phục."}]'::jsonb,'["literature-12-social-argumentation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-literary-argumentation',11,'LESSON','Nghị luận về một tư tưởng, đạo lí hoặc hiện tượng văn học','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Nghị luận văn học kết hợp phân tích nội dung tư tưởng và hình thức nghệ thuật. Luận điểm rõ ràng bám sát tác phẩm. Trích dẫn câu thơ, đoạn văn chính xác. Liên hệ mở rộng với các tác phẩm cùng đề tài, thời đại để làm nổi bật đóng góp độc đáo của tác giả."]'::jsonb,'["Phân tích vẻ đẹp người nông dân nghĩa sĩ: phân tích tinh thần quả cảm, lí tưởng vì nước quên thân, kết hợp nghệ thuật ngôn từ trang trọng, hào hùng."]'::jsonb,'[{"id": "literature-12-literary-argumentation-q1", "prompt": "Khi viết bài văn nghị luận phân tích một tác phẩm văn học, người viết cần kết hợp chặt chẽ giữa hai yếu tố nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Phân tích nội dung tư tưởng và các thủ pháp nghệ thuật độc đáo"}, {"id": "b", "text": "Chỉ tóm tắt cốt truyện từ đầu đến cuối như văn kể chuyện"}, {"id": "c", "text": "Sao chép lại tiểu sử năm sinh năm mất của tác giả"}], "correctOptionId": "a", "explanation": "Tác phẩm văn học là sự thống nhất giữa nội dung và hình thức; nghệ thuật là phương tiện chuyên chở tư tưởng tác giả."}, {"id": "literature-12-literary-argumentation-q2", "prompt": "Thao tác ''so sánh văn học'' trong bài văn nghị luận có tác dụng nghệ thuật chủ yếu là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Để kéo dài dung lượng bài viết khi thiếu ý tưởng"}, {"id": "b", "text": "Khẳng định tác phẩm kia hoàn toàn vô giá trị"}, {"id": "c", "text": "Làm nổi bật nét độc đáo, dấu ấn phong cách riêng biệt của tác giả đang phân tích"}], "correctOptionId": "c", "explanation": "So sánh với tác phẩm cùng đề tài hoặc cùng thời kì giúp nhận diện rõ nét sáng tạo độc đáo riêng của nhà văn."}, {"id": "literature-12-literary-argumentation-q3", "prompt": "Yêu cầu bắt buộc khi đưa dẫn chứng là lời thoại hoặc câu thơ của tác phẩm vào bài nghị luận văn học là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Tự ý bịa thêm câu từ mới vào thơ của tác giả"}, {"id": "b", "text": "Dẫn chứng phải trích dẫn chính xác, tiêu biểu và có lời phân tích bình luận đi kèm"}, {"id": "c", "text": "Trích bừa bãi toàn bộ tác phẩm mà không bình luận gì"}], "correctOptionId": "b", "explanation": "Trích dẫn phải trung thực với nguyên tác và phải có thao tác ''bình dẫn chứng'' để làm sáng tỏ luận điểm của người viết."}]'::jsonb,'["literature-12-literary-argumentation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-review-2',12,'FIVE_LESSON_REVIEW','Ôn tập 2','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "literature-12-argument-structure-q1", "prompt": "Trong cấu trúc của một văn bản nghị luận, ''luận điểm'' đóng vai trò là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Lời mở đầu giới thiệu tiểu sử tác giả"}, {"id": "b", "text": "Các ý kiến, quan điểm chính triển khai làm sáng tỏ cho luận đề của bài viết"}, {"id": "c", "text": "Các số liệu thống kê cụ thể trích dẫn từ bài báo"}], "correctOptionId": "b", "explanation": "Luận điểm là những phán đoán cốt lõi thể hiện quan điểm của người viết về từng khía cạnh của vấn đề nghị luận."}, {"id": "literature-12-argument-structure-q2", "prompt": "Yêu cầu quan trọng nhất đối với hệ thống luận cứ (lí lẽ và dẫn chứng) trong văn bản nghị luận là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Phải chân thực, tiêu biểu, xác đáng và có mối liên hệ logic chặt chẽ với luận điểm"}, {"id": "b", "text": "Càng dài dòng và nhiều chi tiết vụn vặt càng tốt"}, {"id": "c", "text": "Phải sử dụng hoàn toàn những câu chuyện hư cấu hoang đường"}], "correctOptionId": "a", "explanation": "Luận cứ xác thực, tiêu biểu mới đủ sức thuyết phục người đọc tin vào tính đúng đắn của luận điểm."}, {"id": "literature-12-evidence-evaluation-q1", "prompt": "Tiêu chí nào sau đây là quan trọng hàng đầu khi lựa chọn dẫn chứng cho bài văn nghị luận xã hội?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tính xác thực, khách quan và có nguồn gốc xuất xứ tin cậy"}, {"id": "b", "text": "Dẫn chứng phải hoàn toàn bí ẩn không ai kiểm chứng được"}, {"id": "c", "text": "Chỉ sử dụng những tin đồn chưa được kiểm chứng trên mạng"}], "correctOptionId": "a", "explanation": "Dẫn chứng khách quan, kiểm chứng được từ cơ quan chuyên môn mới tạo lập uy tín học thuật vững chắc cho bài viết."}, {"id": "literature-12-evidence-evaluation-q2", "prompt": "Lỗi ngụy biện ''khái quát hóa vội vã'' (hasty generalization) xảy ra khi người viết:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Phân tích quá sâu nguyên nhân sâu xa của vấn đề"}, {"id": "b", "text": "Trích dẫn đầy đủ số liệu điều tra diện rộng trên hàng triệu người"}, {"id": "c", "text": "Rút ra kết luận chung cho toàn bộ tập thể chỉ dựa trên một vài trường hợp cá biệt"}], "correctOptionId": "c", "explanation": "Lấy một vài ví dụ cá biệt không đại diện để quy chụp cho số đông là lỗi ngụy biện khái quát hóa vội vã."}, {"id": "literature-12-persuasive-rhetoric-q1", "prompt": "Phương thức thuyết phục dựa trên uy tín, phẩm hạnh và tư cách đạo đức của người nói trong thuật hùng biện được gọi là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Pathos"}, {"id": "b", "text": "Logos"}, {"id": "c", "text": "Ethos"}], "correctOptionId": "c", "explanation": "Trong thuật hùng biện Aristotle: Ethos là uy tín cá nhân, Pathos là tác động cảm xúc, Logos là lập luận logic."}, {"id": "literature-12-persuasive-rhetoric-q2", "prompt": "Khi muốn lay động lòng trắc ẩn và sự đồng cảm sâu sắc của người nghe về một mảnh đời bất hạnh, người viết thường sử dụng phương thức:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ đọc to danh mục văn bản luật pháp"}, {"id": "b", "text": "Pathos (tác động vào cảm xúc và tâm lí)"}, {"id": "c", "text": "Logos (lập luận toán học khô khan)"}], "correctOptionId": "b", "explanation": "Pathos hướng đến thế giới cảm xúc, chạm vào lòng nhân ái, sự sẻ chia của độc giả."}, {"id": "literature-12-social-argumentation-q1", "prompt": "Khi làm bài văn nghị luận về một vấn đề xã hội, thao tác đầu tiên sau khi giới thiệu vấn đề cần thực hiện là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Đưa ra ngay kết luận cuối cùng của bài viết"}, {"id": "b", "text": "Giải thích rõ nghĩa của các từ khóa và nội hàm cốt lõi của vấn đề"}, {"id": "c", "text": "Lập tức phê phán gay gắt những người có ý kiến trái chiều"}], "correctOptionId": "b", "explanation": "Giải thích khái niệm giúp xác lập định nghĩa chuẩn xác, tránh lạc đề hoặc hiểu sai lệch vấn đề trước khi bàn luận."}, {"id": "literature-12-social-argumentation-q2", "prompt": "Để các giải pháp đề xuất trong bài nghị luận xã hội có tính thuyết phục cao, người viết cần đảm bảo:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tính cụ thể, khả thi, phù hợp với thực tế và giải quyết trúng nguyên nhân gốc rễ"}, {"id": "b", "text": "Đưa ra những lời hứa hão huyền không ai làm được"}, {"id": "c", "text": "Chỉ yêu cầu người khác làm mà bản thân không cần thay đổi"}], "correctOptionId": "a", "explanation": "Giải pháp phải xuất phát từ nguyên nhân thực tế, có tính khả thi và phân định rõ trách nhiệm cá nhân, cộng đồng."}, {"id": "literature-12-literary-argumentation-q1", "prompt": "Khi viết bài văn nghị luận phân tích một tác phẩm văn học, người viết cần kết hợp chặt chẽ giữa hai yếu tố nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Phân tích nội dung tư tưởng và các thủ pháp nghệ thuật độc đáo"}, {"id": "b", "text": "Chỉ tóm tắt cốt truyện từ đầu đến cuối như văn kể chuyện"}, {"id": "c", "text": "Sao chép lại tiểu sử năm sinh năm mất của tác giả"}], "correctOptionId": "a", "explanation": "Tác phẩm văn học là sự thống nhất giữa nội dung và hình thức; nghệ thuật là phương tiện chuyên chở tư tưởng tác giả."}, {"id": "literature-12-literary-argumentation-q2", "prompt": "Thao tác ''so sánh văn học'' trong bài văn nghị luận có tác dụng nghệ thuật chủ yếu là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Để kéo dài dung lượng bài viết khi thiếu ý tưởng"}, {"id": "b", "text": "Khẳng định tác phẩm kia hoàn toàn vô giá trị"}, {"id": "c", "text": "Làm nổi bật nét độc đáo, dấu ấn phong cách riêng biệt của tác giả đang phân tích"}], "correctOptionId": "c", "explanation": "So sánh với tác phẩm cùng đề tài hoặc cùng thời kì giúp nhận diện rõ nét sáng tạo độc đáo riêng của nhà văn."}]'::jsonb,'["literature-12-argument-structure", "literature-12-evidence-evaluation", "literature-12-persuasive-rhetoric", "literature-12-social-argumentation", "literature-12-literary-argumentation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-informational-synthesis',13,'LESSON','Tiếp nhận và tổng hợp thông tin đa nguồn','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Văn bản thông tin: số liệu, biểu đồ, infographic, văn bản đa phương thức. Kĩ năng đọc: phân loại thông tin chính/phụ, kiểm tra tính nhất quán giữa các nguồn, tổng hợp và rút ra nhận định tổng quan."]'::jsonb,'["Đọc báo cáo về tỉ lệ sử dụng năng lượng tái tạo gồm biểu đồ hình cột và đoạn văn phân tích xu hướng để tóm tắt các điểm then chốt."]'::jsonb,'[{"id": "literature-12-informational-synthesis-q1", "prompt": "Trong một văn bản thông tin đa phương thức, các yếu tố phi ngôn ngữ (như biểu đồ, sơ đồ, hình ảnh) có vai trò:", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ để trang trí cho văn bản bớt tẻ nhạt mà không mang ý nghĩa gì"}, {"id": "b", "text": "Làm sai lệch thông tin của phần văn bản chữ viết"}, {"id": "c", "text": "Trực quan hóa dữ liệu phức tạp giúp người đọc tiếp nhận thông tin nhanh chóng và chính xác"}], "correctOptionId": "c", "explanation": "Yếu tố phi ngôn ngữ giúp cô đọng số liệu trực quan, tăng tính sinh động và hỗ trợ đắc lực cho văn bản thuyết minh."}, {"id": "literature-12-informational-synthesis-q2", "prompt": "Kĩ năng quan trọng nhất khi tổng hợp thông tin từ nhiều nguồn tài liệu khác nhau về cùng một đề tài là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ chọn nguồn tin có độ dài ngắn nhất để đọc"}, {"id": "b", "text": "So sánh, đối chiếu tính nhất quán của dữ liệu và chắt lọc các điểm đồng thuận cốt lõi"}, {"id": "c", "text": "Sao chép nguyên văn tất cả các tài liệu gom lại thành một tập dài"}], "correctOptionId": "b", "explanation": "Tổng hợp thông tin đòi hỏi tư duy phân tích, đối chiếu chéo để loại bỏ mâu thuẫn và xây dựng bức tranh tổng thể tin cậy."}, {"id": "literature-12-informational-synthesis-q3", "prompt": "Khi phát hiện hai bài báo uy tín đưa ra số liệu chênh lệch nhau về cùng một hiện tượng, người đọc thông thái nên:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Kiểm tra lại phương pháp thu thập dữ liệu, thời điểm khảo sát và phạm vi mẫu của từng bài báo"}, {"id": "b", "text": "Lập tức tin ngay bài báo xuất bản sau cùng mà không cần kiểm tra"}, {"id": "c", "text": "Bỏ qua hoàn toàn đề tài đó và không quan tâm nữa"}], "correctOptionId": "a", "explanation": "Chênh lệch số liệu thường xuất phát từ phương pháp chọn mẫu, thời điểm đo đạc hoặc tiêu chuẩn thống kê khác nhau."}]'::jsonb,'["literature-12-informational-synthesis"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-media-literacy',14,'LESSON','Phân tích ngôn ngữ truyền thông và diễn ngôn đại chúng','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Ngôn ngữ truyền thông: giật gân, đóng khung thông điệp (framing), thiên kiến xác nhận. Phân tích diễn ngôn: ai nói, mục đích gì, nhắm đến đối tượng nào, những gì bị ẩn giấu hoặc lược bỏ. Nhận diện tin giả (fake news)."]'::jsonb,'["Một tiêu đề bài báo dùng từ ngữ giật gân ''Kinh hoàng'', ''Sốc'' nhằm thu hút tương tác (clickbait) thay vì phản ánh bản chất trung thực của sự việc."]'::jsonb,'[{"id": "literature-12-media-literacy-q1", "prompt": "Hiện tượng ''đóng khung thông điệp'' (framing) trong truyền thông đại chúng có nghĩa là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Hoàn toàn cấm đoán người dân phát biểu ý kiến cá nhân"}, {"id": "b", "text": "Cách thức cơ quan truyền thông lựa chọn nhấn mạnh một khía cạnh nhất định để định hướng cách nhìn của công chúng"}, {"id": "c", "text": "Đóng khung các bài báo in vào khung gỗ để treo tường"}], "correctOptionId": "b", "explanation": "Framing là kĩ thuật định hướng dư luận bằng cách làm nổi bật một góc nhìn cụ thể và làm lu mờ các góc nhìn khác."}, {"id": "literature-12-media-literacy-q2", "prompt": "Dấu hiệu điển hình của một tiêu đề mang tính chất ''mồi câu nhấp chuột'' (clickbait) trên mạng là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Sử dụng ngôn từ giật gân, lấp lửng, phóng đại cảm xúc để kích thích người dùng bấm vào xem"}, {"id": "b", "text": "Cung cấp đầy đủ thông tin tóm tắt khách quan ngay ở tiêu đề"}, {"id": "c", "text": "Trích dẫn chính xác báo cáo khoa học có nguồn thẩm định rõ ràng"}], "correctOptionId": "a", "explanation": "Clickbait dùng các từ khóa kích động cảm xúc tò mò, thường phóng đại hoặc làm sai lệch nội dung thực tế bên trong bài viết."}, {"id": "literature-12-media-literacy-q3", "prompt": "Để thẩm định một thông tin gây sốc lan truyền trên mạng xã hội có phải là tin giả (fake news) hay không, bước làm đầu tiên nên là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chia sẻ ngay lập tức lên trang cá nhân để cảnh báo bạn bè"}, {"id": "b", "text": "Bình luận thật nhiều cảm xúc phẫn nộ dưới bài viết"}, {"id": "c", "text": "Kiểm tra nguồn gốc tác giả, ngày đăng và đối chiếu với các cơ quan báo chí chính thống"}], "correctOptionId": "c", "explanation": "Kiểm tra nguồn tin gốc, ngày phát hành và xác thực chéo qua báo chí chính thống là bước kiểm chứng căn bản nhất."}]'::jsonb,'["literature-12-media-literacy"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-research-report',15,'LESSON','Kĩ thuật viết báo cáo nghiên cứu và trích dẫn','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Cấu trúc báo cáo nghiên cứu: Tên đề tài, Tóm tắt (Abstract), Đặt vấn đề, Phương pháp nghiên cứu, Kết quả và Bàn luận, Kết luận, Danh mục tài liệu tham khảo. Quy tắc trích dẫn học thuật (APA, MLA): trích trực tiếp vs gián tiếp, phòng chống đạo văn (plagiarism)."]'::jsonb,'["Khi trích dẫn ý kiến của một chuyên gia, học sinh ghi rõ tên tác giả, năm công bố và đóng ngoặc kép câu trích dẫn kèm số trang."]'::jsonb,'[{"id": "literature-12-research-report-q1", "prompt": "Phần ''Tóm tắt'' (Abstract) ở đầu một báo cáo nghiên cứu khoa học có nhiệm vụ chính là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tóm lược cô đọng mục tiêu, phương pháp, kết quả then chốt và kết luận của công trình"}, {"id": "b", "text": "Liệt kê danh sách tất cả các thành viên trong gia đình tác giả"}, {"id": "c", "text": "Trình bày chi tiết toàn bộ các bảng số liệu thô thu thập được"}], "correctOptionId": "a", "explanation": "Abstract giúp người đọc nhanh chóng nắm bắt bản chất và những phát hiện quan trọng nhất của công trình nghiên cứu."}, {"id": "literature-12-research-report-q2", "prompt": "Hành vi nào sau đây bị coi là ''đạo văn'' (plagiarism) nghiêm trọng trong nghiên cứu học thuật?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Trích dẫn nguyên văn câu nói của tác giả và đặt trong dấu ngoặc kép kèm ghi chú nguồn"}, {"id": "b", "text": "Diễn đạt lại ý kiến của chuyên gia và chú thích rõ tài liệu tham khảo"}, {"id": "c", "text": "Sử dụng ý tưởng hoặc câu chữ của người khác mà không dẫn nguồn và trích dẫn rõ ràng"}], "correctOptionId": "c", "explanation": "Đạo văn là hành vi chiếm đoạt sản phẩm trí tuệ khi sử dụng tư liệu của người khác như thể là của chính mình."}, {"id": "literature-12-research-report-q3", "prompt": "Trong danh mục tài liệu tham khảo theo quy chuẩn học thuật, các nguồn tài liệu thường được sắp xếp theo trật tự:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Xếp theo số lượng trang của cuốn sách từ dày đến mỏng"}, {"id": "b", "text": "Thứ tự bảng chữ cái (A-Z) theo tên tác giả hoặc chữ cái đầu của tên tác phẩm"}, {"id": "c", "text": "Xếp ngẫu nhiên theo thứ tự tác giả nào nổi tiếng hơn"}], "correctOptionId": "b", "explanation": "Quy chuẩn học thuật quốc tế (như APA, MLA) yêu cầu danh mục tài liệu tham khảo phải được sắp xếp theo thứ tự chữ cái A-Z."}]'::jsonb,'["literature-12-research-report"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-formal-speech',16,'LESSON','Thuyết trình và đối thoại học thuật','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Cấu trúc bài thuyết trình: Mở đầu gây ấn tượng (hook), Thân bài có cấu trúc rõ ràng với các từ nối chuyển ý (signposting), Kết luận đọng lại thông điệp. Sử dụng phương tiện trực quan (slides) tinh gọn. Kĩ năng xử lý phần hỏi - đáp (Q&A): lắng nghe, ghi nhận, trả lời đúng trọng tâm và khiêm tốn."]'::jsonb,'["Mở đầu bài thuyết trình bằng một câu hỏi gợi mở hoặc một câu chuyện thực tế ngắn tạo sự chú ý tức thì của người nghe."]'::jsonb,'[{"id": "literature-12-formal-speech-q1", "prompt": "Kĩ thuật ''câu móc'' (hook) trong phần mở đầu của một bài thuyết trình được dùng để:", "difficulty": "EASY", "options": [{"id": "a", "text": "Đọc nhanh danh sách tất cả các tài liệu tham khảo của bài"}, {"id": "b", "text": "Xin lỗi khán giả vì chưa chuẩn bị bài kĩ càng"}, {"id": "c", "text": "Thu hút sự chú ý và khơi gợi trí tò mò của khán giả ngay từ những giây đầu tiên"}], "correctOptionId": "c", "explanation": "Hook (câu hỏi thú vị, số liệu gây sốc, câu chuyện ngắn) kết nối người nghe với chủ đề ngay từ lúc mở màn."}, {"id": "literature-12-formal-speech-q2", "prompt": "Khi thiết kế slide trình chiếu hỗ trợ bài thuyết trình, nguyên tắc quan trọng về mặt thị giác là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Dùng thật nhiều phông chữ sặc sỡ và hiệu ứng hoạt họa nhấp nháy liên tục"}, {"id": "b", "text": "Trình bày cô đọng, ưu tiên hình ảnh biểu đồ trực quan và hạn chế tối đa các đoạn văn bản dài"}, {"id": "c", "text": "Chép toàn bộ nguyên văn bài nói lên màn hình để đọc lại từng chữ"}], "correctOptionId": "b", "explanation": "Slide chỉ mang tính trực quan hỗ trợ; văn bản quá nhiều sẽ làm khán giả mải đọc chữ và phân tâm khỏi lời nói của diễn giả."}, {"id": "literature-12-formal-speech-q3", "prompt": "Khi nhận được một câu hỏi phản biện khó từ khán giả trong phần Q&A mà bản thân chưa nắm rõ câu trả lời, thái độ đúng đắn là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Cảm ơn câu hỏi sâu sắc, thừa nhận thẳng thắn giới hạn và hẹn sẽ tìm hiểu phản hồi sau"}, {"id": "b", "text": "Cố tình nói quanh co dài dòng và bịa đặt số liệu giả để trả lời"}, {"id": "c", "text": "Tỏ thái độ bực bội và yêu cầu khán giả không được hỏi câu hỏi đó"}], "correctOptionId": "a", "explanation": "Trung thực học thuật và khiêm tốn là phẩm chất cốt lõi; thừa nhận giới hạn và tiếp thu thể hiện tính chuyên nghiệp."}]'::jsonb,'["literature-12-formal-speech"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-debate-skills',17,'LESSON','Kĩ năng tranh biện và phản biện logic','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Bản chất tranh biện là đối thoại tư duy tìm chân lí, không phải cãi cọ ăn thua. Mô hình lập luận ARE (Assertion - Luận điểm, Reasoning - Lí lẽ, Evidence - Dẫn chứng). Kĩ thuật phản biện: chỉ ra lỗ hổng logic, đưa ra phản chứng, hoặc chứng minh tính phi thực tế của giải pháp đối phương."]'::jsonb,'["Trong một cuộc tranh biện về ''Học trực tuyến thay thế hoàn toàn trường học'', đội phản đối chỉ ra lỗ hổng: thiếu tương tác xã hội trực tiếp phát triển cảm xúc cho học sinh."]'::jsonb,'[{"id": "literature-12-debate-skills-q1", "prompt": "Trong mô hình tranh biện học thuật tiêu chuẩn, một lập luận hoàn chỉnh bao gồm các thành tố cốt lõi nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Những lời công kích đời tư nhằm làm đối phương mất bình tĩnh"}, {"id": "b", "text": "Luận điểm khẳng định, lí lẽ giải thích và dẫn chứng thực tế minh chứng"}, {"id": "c", "text": "Chỉ gồm một lời khẳng định to tiếng và áp đặt"}], "correctOptionId": "b", "explanation": "Mô hình ARE (Assertion, Reasoning, Evidence) là tiêu chuẩn vàng cho một luận cứ tranh biện logic và thuyết phục."}, {"id": "literature-12-debate-skills-q2", "prompt": "Thao tác phản biện hiệu quả nhất khi đối thoại tranh luận với ý kiến trái chiều là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tập trung phân tích lỗ hổng logic hoặc tính thiếu căn cứ của dẫn chứng mà đối phương đưa ra"}, {"id": "b", "text": "Ngắt lời đối phương liên tục không cho họ phát biểu"}, {"id": "c", "text": "Lặp đi lặp lại ý kiến của mình với giọng điệu to hơn"}], "correctOptionId": "a", "explanation": "Phản biện sắc bén nhắm thẳng vào giả định sai lầm, sự thiếu hụt bằng chứng hoặc nghịch lí logic trong lập luận của đối thủ."}, {"id": "literature-12-debate-skills-q3", "prompt": "Mục đích cao nhất của hoạt động tranh biện học thuật trong nhà trường là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Đánh bại đối thủ bằng mọi giá kể cả dùng tiểu xảo ngụy biện"}, {"id": "b", "text": "Chứng minh mình luôn là người hoàn hảo không bao giờ mắc sai lầm"}, {"id": "c", "text": "Rèn luyện tư duy phản biện, khả năng nhìn nhận vấn đề đa chiều và tôn trọng sự khác biệt"}], "correctOptionId": "c", "explanation": "Tranh biện là phương pháp học tập nhằm khai phóng tư duy, mở rộng tầm nhìn và rèn luyện kĩ năng lắng nghe thấu cảm."}]'::jsonb,'["literature-12-debate-skills"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('literature',12,'intro-2026.1','literature-12-review-3',18,'FIVE_LESSON_REVIEW','Ôn tập 3','Ngữ văn 12: Đọc hiểu văn bản, Nghị luận và Kĩ năng giao tiếp','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "literature-12-informational-synthesis-q1", "prompt": "Trong một văn bản thông tin đa phương thức, các yếu tố phi ngôn ngữ (như biểu đồ, sơ đồ, hình ảnh) có vai trò:", "difficulty": "EASY", "options": [{"id": "a", "text": "Chỉ để trang trí cho văn bản bớt tẻ nhạt mà không mang ý nghĩa gì"}, {"id": "b", "text": "Làm sai lệch thông tin của phần văn bản chữ viết"}, {"id": "c", "text": "Trực quan hóa dữ liệu phức tạp giúp người đọc tiếp nhận thông tin nhanh chóng và chính xác"}], "correctOptionId": "c", "explanation": "Yếu tố phi ngôn ngữ giúp cô đọng số liệu trực quan, tăng tính sinh động và hỗ trợ đắc lực cho văn bản thuyết minh."}, {"id": "literature-12-informational-synthesis-q2", "prompt": "Kĩ năng quan trọng nhất khi tổng hợp thông tin từ nhiều nguồn tài liệu khác nhau về cùng một đề tài là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chỉ chọn nguồn tin có độ dài ngắn nhất để đọc"}, {"id": "b", "text": "So sánh, đối chiếu tính nhất quán của dữ liệu và chắt lọc các điểm đồng thuận cốt lõi"}, {"id": "c", "text": "Sao chép nguyên văn tất cả các tài liệu gom lại thành một tập dài"}], "correctOptionId": "b", "explanation": "Tổng hợp thông tin đòi hỏi tư duy phân tích, đối chiếu chéo để loại bỏ mâu thuẫn và xây dựng bức tranh tổng thể tin cậy."}, {"id": "literature-12-media-literacy-q1", "prompt": "Hiện tượng ''đóng khung thông điệp'' (framing) trong truyền thông đại chúng có nghĩa là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Hoàn toàn cấm đoán người dân phát biểu ý kiến cá nhân"}, {"id": "b", "text": "Cách thức cơ quan truyền thông lựa chọn nhấn mạnh một khía cạnh nhất định để định hướng cách nhìn của công chúng"}, {"id": "c", "text": "Đóng khung các bài báo in vào khung gỗ để treo tường"}], "correctOptionId": "b", "explanation": "Framing là kĩ thuật định hướng dư luận bằng cách làm nổi bật một góc nhìn cụ thể và làm lu mờ các góc nhìn khác."}, {"id": "literature-12-media-literacy-q2", "prompt": "Dấu hiệu điển hình của một tiêu đề mang tính chất ''mồi câu nhấp chuột'' (clickbait) trên mạng là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Sử dụng ngôn từ giật gân, lấp lửng, phóng đại cảm xúc để kích thích người dùng bấm vào xem"}, {"id": "b", "text": "Cung cấp đầy đủ thông tin tóm tắt khách quan ngay ở tiêu đề"}, {"id": "c", "text": "Trích dẫn chính xác báo cáo khoa học có nguồn thẩm định rõ ràng"}], "correctOptionId": "a", "explanation": "Clickbait dùng các từ khóa kích động cảm xúc tò mò, thường phóng đại hoặc làm sai lệch nội dung thực tế bên trong bài viết."}, {"id": "literature-12-research-report-q1", "prompt": "Phần ''Tóm tắt'' (Abstract) ở đầu một báo cáo nghiên cứu khoa học có nhiệm vụ chính là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Tóm lược cô đọng mục tiêu, phương pháp, kết quả then chốt và kết luận của công trình"}, {"id": "b", "text": "Liệt kê danh sách tất cả các thành viên trong gia đình tác giả"}, {"id": "c", "text": "Trình bày chi tiết toàn bộ các bảng số liệu thô thu thập được"}], "correctOptionId": "a", "explanation": "Abstract giúp người đọc nhanh chóng nắm bắt bản chất và những phát hiện quan trọng nhất của công trình nghiên cứu."}, {"id": "literature-12-research-report-q2", "prompt": "Hành vi nào sau đây bị coi là ''đạo văn'' (plagiarism) nghiêm trọng trong nghiên cứu học thuật?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Trích dẫn nguyên văn câu nói của tác giả và đặt trong dấu ngoặc kép kèm ghi chú nguồn"}, {"id": "b", "text": "Diễn đạt lại ý kiến của chuyên gia và chú thích rõ tài liệu tham khảo"}, {"id": "c", "text": "Sử dụng ý tưởng hoặc câu chữ của người khác mà không dẫn nguồn và trích dẫn rõ ràng"}], "correctOptionId": "c", "explanation": "Đạo văn là hành vi chiếm đoạt sản phẩm trí tuệ khi sử dụng tư liệu của người khác như thể là của chính mình."}, {"id": "literature-12-formal-speech-q1", "prompt": "Kĩ thuật ''câu móc'' (hook) trong phần mở đầu của một bài thuyết trình được dùng để:", "difficulty": "EASY", "options": [{"id": "a", "text": "Đọc nhanh danh sách tất cả các tài liệu tham khảo của bài"}, {"id": "b", "text": "Xin lỗi khán giả vì chưa chuẩn bị bài kĩ càng"}, {"id": "c", "text": "Thu hút sự chú ý và khơi gợi trí tò mò của khán giả ngay từ những giây đầu tiên"}], "correctOptionId": "c", "explanation": "Hook (câu hỏi thú vị, số liệu gây sốc, câu chuyện ngắn) kết nối người nghe với chủ đề ngay từ lúc mở màn."}, {"id": "literature-12-formal-speech-q2", "prompt": "Khi thiết kế slide trình chiếu hỗ trợ bài thuyết trình, nguyên tắc quan trọng về mặt thị giác là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Dùng thật nhiều phông chữ sặc sỡ và hiệu ứng hoạt họa nhấp nháy liên tục"}, {"id": "b", "text": "Trình bày cô đọng, ưu tiên hình ảnh biểu đồ trực quan và hạn chế tối đa các đoạn văn bản dài"}, {"id": "c", "text": "Chép toàn bộ nguyên văn bài nói lên màn hình để đọc lại từng chữ"}], "correctOptionId": "b", "explanation": "Slide chỉ mang tính trực quan hỗ trợ; văn bản quá nhiều sẽ làm khán giả mải đọc chữ và phân tâm khỏi lời nói của diễn giả."}, {"id": "literature-12-debate-skills-q1", "prompt": "Trong mô hình tranh biện học thuật tiêu chuẩn, một lập luận hoàn chỉnh bao gồm các thành tố cốt lõi nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Những lời công kích đời tư nhằm làm đối phương mất bình tĩnh"}, {"id": "b", "text": "Luận điểm khẳng định, lí lẽ giải thích và dẫn chứng thực tế minh chứng"}, {"id": "c", "text": "Chỉ gồm một lời khẳng định to tiếng và áp đặt"}], "correctOptionId": "b", "explanation": "Mô hình ARE (Assertion, Reasoning, Evidence) là tiêu chuẩn vàng cho một luận cứ tranh biện logic và thuyết phục."}, {"id": "literature-12-debate-skills-q2", "prompt": "Thao tác phản biện hiệu quả nhất khi đối thoại tranh luận với ý kiến trái chiều là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tập trung phân tích lỗ hổng logic hoặc tính thiếu căn cứ của dẫn chứng mà đối phương đưa ra"}, {"id": "b", "text": "Ngắt lời đối phương liên tục không cho họ phát biểu"}, {"id": "c", "text": "Lặp đi lặp lại ý kiến của mình với giọng điệu to hơn"}], "correctOptionId": "a", "explanation": "Phản biện sắc bén nhắm thẳng vào giả định sai lầm, sự thiếu hụt bằng chứng hoặc nghịch lí logic trong lập luận của đối thủ."}]'::jsonb,'["literature-12-informational-synthesis", "literature-12-media-literacy", "literature-12-research-report", "literature-12-formal-speech", "literature-12-debate-skills"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','placement',0,'PLACEMENT','Khảo sát đầu vào','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "english-12-sustainable-future-q1", "prompt": "Which word best describes materials that can break down naturally without harming the environment?", "difficulty": "EASY", "options": [{"id": "a", "text": "Biodegradable"}, {"id": "b", "text": "Non-recyclable"}, {"id": "c", "text": "Indestructible"}], "correctOptionId": "a", "explanation": "''Biodegradable'' refers to substances capable of being decomposed by bacteria or other biological agents."}, {"id": "english-12-sustainable-future-q2", "prompt": "Rewrite for emphasis using a cleft sentence: ''Plastic bags pollute our rivers.''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Plastic bags are what they pollute our rivers."}, {"id": "b", "text": "There is plastic bags polluting our rivers."}, {"id": "c", "text": "It is plastic bags that pollute our rivers."}], "correctOptionId": "c", "explanation": "The cleft sentence structure ''It is/was + emphasized element + that/who + clause'' is used to focus attention on ''plastic bags''."}, {"id": "english-12-climate-action-q1", "prompt": "What term refers to the rich variety of animal and plant life in a specific habitat or on Earth?", "difficulty": "EASY", "options": [{"id": "a", "text": "Deforestation"}, {"id": "b", "text": "Urbanisation"}, {"id": "c", "text": "Biodiversity"}], "correctOptionId": "c", "explanation": "''Biodiversity'' is the variety of plant and animal life in a particular habitat or in the world as a whole."}, {"id": "english-12-climate-action-q2", "prompt": "Choose the correct passive modal form: ''Strict environmental policies _______ immediately to curb industrial emissions.''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "must have implemented"}, {"id": "b", "text": "must be implemented"}, {"id": "c", "text": "must implement"}], "correctOptionId": "b", "explanation": "Passive with modal verb: modal + be + past participle (''must be implemented'')."}, {"id": "english-12-urbanisation-q1", "prompt": "Which noun refers to the basic physical systems and structures of a city, such as roads, water supplies, and electricity grids?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ruralization"}, {"id": "b", "text": "Infrastructure"}, {"id": "c", "text": "Congestion"}], "correctOptionId": "b", "explanation": "''Infrastructure'' encompasses the fundamental facilities and systems serving a country, city, or area."}, {"id": "english-12-urbanisation-q2", "prompt": "Choose the participle clause that correctly replaces ''Because city planners realized the lack of green spaces, they created more public parks.'':", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Realizing the lack of green spaces, city planners created more public parks."}, {"id": "b", "text": "To realize the lack of green spaces, city planners created more public parks."}, {"id": "c", "text": "Realized the lack of green spaces, city planners created more public parks."}], "correctOptionId": "a", "explanation": "A present participle clause (-ing) replaces an active adverbial clause of reason when both clauses share the same subject."}, {"id": "english-12-cultural-heritage-q1", "prompt": "Folk singing, traditional festivals, and indigenous craftsmanship belong to which category of cultural heritage?", "difficulty": "EASY", "options": [{"id": "a", "text": "Intangible cultural heritage"}, {"id": "b", "text": "Tangible architectural heritage"}, {"id": "c", "text": "Natural ecological heritage"}], "correctOptionId": "a", "explanation": "''Intangible heritage'' includes non-physical traditions, living expressions, and performing arts transmitted from generation to generation."}, {"id": "english-12-cultural-heritage-q2", "prompt": "Choose the correct formal inverted conditional sentence:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "If had the historic pagoda been renovated properly, it would withstand."}, {"id": "b", "text": "Were the historic pagoda renovated properly, it will withstand."}, {"id": "c", "text": "Had the historic pagoda been renovated properly, it would have withstood the earthquake."}], "correctOptionId": "c", "explanation": "Third conditional inversion replaces ''If it had been renovated'' with ''Had it been renovated'' without using ''if''."}, {"id": "english-12-global-citizenship-q1", "prompt": "What does having ''cross-cultural competence'' primarily involve?", "difficulty": "EASY", "options": [{"id": "a", "text": "The requirement to abandon one''s own national identity and mother tongue"}, {"id": "b", "text": "The memorization of all historical dates of every country in the world"}, {"id": "c", "text": "The ability to understand, communicate with, and effectively interact with people across cultures"}], "correctOptionId": "c", "explanation": "Cross-cultural competence involves awareness, attitudes, knowledge, and skills to engage respectfully across diverse cultural boundaries."}, {"id": "english-12-global-citizenship-q2", "prompt": "Select the correct linker of contrast to join the ideas: ''Online platforms facilitate worldwide communication; _______, they can sometimes amplify misunderstandings.''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "in addition"}, {"id": "b", "text": "nevertheless"}, {"id": "c", "text": "consequently"}], "correctOptionId": "b", "explanation": "''Nevertheless'' introduces a contrast or concession to the preceding independent clause."}, {"id": "english-12-higher-education-q1", "prompt": "Education and training provided by universities, colleges, and technical institutes after secondary school is called:", "difficulty": "EASY", "options": [{"id": "a", "text": "Pre-school education"}, {"id": "b", "text": "Tertiary education"}, {"id": "c", "text": "Primary education"}], "correctOptionId": "b", "explanation": "''Tertiary education'' refers to any level of formal education pursued after high school graduation, including university and vocational colleges."}, {"id": "english-12-higher-education-q2", "prompt": "Choose the sentence with the correct formal relative clause containing a preposition:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Architecture is an interdisciplinary field in which artistic vision meets engineering precision."}, {"id": "b", "text": "Architecture is an interdisciplinary field which in artistic vision meets engineering."}, {"id": "c", "text": "Architecture is an interdisciplinary field where in artistic vision meets engineering."}], "correctOptionId": "a", "explanation": "In formal academic English, prepositions precede relative pronouns: ''field in which''."}, {"id": "english-12-future-careers-q1", "prompt": "What term describes working from home or another remote location using telecommunications and the internet?", "difficulty": "EASY", "options": [{"id": "a", "text": "Telecommuting"}, {"id": "b", "text": "Commuting"}, {"id": "c", "text": "Assembly line"}], "correctOptionId": "a", "explanation": "''Telecommuting'' (or remote working) involves working outside a traditional office space by connecting through digital tools."}, {"id": "english-12-future-careers-q2", "prompt": "Complete the sentence using the Future Perfect tense: ''By the end of this decade, automated algorithms _______ millions of manual routine operations.''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "will be replacing"}, {"id": "b", "text": "have replaced"}, {"id": "c", "text": "will have replaced"}], "correctOptionId": "c", "explanation": "Future Perfect (will have + past participle) expresses an action that will be completed before a specified point in the future."}, {"id": "english-12-artificial-intelligence-q1", "prompt": "A system or machine capable of performing tasks that typically require human intelligence is called:", "difficulty": "EASY", "options": [{"id": "a", "text": "Manual typewriter"}, {"id": "b", "text": "Analog calculator"}, {"id": "c", "text": "Artificial intelligence"}], "correctOptionId": "c", "explanation": "''Artificial intelligence'' (AI) is the simulation of human intelligence processes by computer systems."}, {"id": "english-12-artificial-intelligence-q2", "prompt": "Choose the grammatically correct sentence using an advanced reporting verb:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Leading computer scientists recommended regulate autonomous weapons."}, {"id": "b", "text": "Leading computer scientists recommended regulating autonomous weapons before deployment."}, {"id": "c", "text": "Leading computer scientists recommended to regulate autonomous weapons."}], "correctOptionId": "b", "explanation": "The verb ''recommend'' takes a gerund (-ing) when directly followed by an action without a personal object: ''recommended regulating''."}, {"id": "english-12-workplace-skills-q1", "prompt": "The official written record of what was discussed and agreed upon during a business meeting is known as:", "difficulty": "EASY", "options": [{"id": "a", "text": "Marketing flyer"}, {"id": "b", "text": "Meeting minutes"}, {"id": "c", "text": "Casual gossip"}], "correctOptionId": "b", "explanation": "''Minutes'' are the instant written record of a meeting or hearing, describing the events and listing attendees, discussions, and decisions."}, {"id": "english-12-workplace-skills-q2", "prompt": "Convert into a polite indirect question: ''Where is the quarterly sales report?''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Could you please tell me where the quarterly sales report is?"}, {"id": "b", "text": "Could you please tell me where is the quarterly sales report?"}, {"id": "c", "text": "Where the quarterly sales report could you please tell me?"}], "correctOptionId": "a", "explanation": "In indirect questions, the clause following the introductory phrase uses normal statement word order: ''where + subject + verb''."}, {"id": "english-12-financial-literacy-q1", "prompt": "The interest calculated on the initial principal and also on the accumulated interest of previous periods of a deposit is called:", "difficulty": "EASY", "options": [{"id": "a", "text": "Compound interest"}, {"id": "b", "text": "Fixed deduction"}, {"id": "c", "text": "Bank penalty"}], "correctOptionId": "a", "explanation": "''Compound interest'' is interest calculated on the principal amount plus any accrued interest over time."}, {"id": "english-12-financial-literacy-q2", "prompt": "Choose the mixed conditional sentence connecting a past action with a present result:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "If they conducted market research, their start-up would not have been in financial crisis."}, {"id": "b", "text": "If they had conducted market research, their start-up will not be in financial crisis."}, {"id": "c", "text": "If they had conducted market research, their start-up would not be in financial crisis right now."}], "correctOptionId": "c", "explanation": "Mixed conditional (Past condition -> Present result): If + past perfect (had conducted), would + bare infinitive (would not be ... now)."}, {"id": "english-12-academic-reading-q1", "prompt": "Which academic reading skill involves rapidly reading through a text to get an overview of the main theme and structure?", "difficulty": "EASY", "options": [{"id": "a", "text": "Proofreading"}, {"id": "b", "text": "Scanning for a phone number"}, {"id": "c", "text": "Skimming"}], "correctOptionId": "c", "explanation": "''Skimming'' is reading rapidly to get a general overview and understand the main idea of a passage."}, {"id": "english-12-academic-reading-q2", "prompt": "Which statement represents an objective fact rather than a subjective opinion?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Every student ought to find biology the most fascinating subject."}, {"id": "b", "text": "The Earth revolves around the Sun in approximately 365.25 days."}, {"id": "c", "text": "Solar energy is by far the most magnificent human invention in history."}], "correctOptionId": "b", "explanation": "Objective facts can be empirically verified through measurement and scientific observation, unlike personal evaluative judgments."}, {"id": "english-12-academic-writing-q1", "prompt": "What is the core sentence in the introductory paragraph that clearly states the author''s central claim and roadmap for the essay?", "difficulty": "EASY", "options": [{"id": "a", "text": "The bibliography citation"}, {"id": "b", "text": "The thesis statement"}, {"id": "c", "text": "The rhetorical question"}], "correctOptionId": "b", "explanation": "The ''thesis statement'' expresses the main argument and sets up the scope and focus of the entire academic essay."}, {"id": "english-12-academic-writing-q2", "prompt": "What is the purpose of addressing a ''counter-argument'' in an argumentative essay?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "To acknowledge an opposing viewpoint and systematically refute it to strengthen one''s own position"}, {"id": "b", "text": "To confuse the reader and make the essay look longer"}, {"id": "c", "text": "To admit that the author''s main thesis is completely mistaken"}], "correctOptionId": "a", "explanation": "Acknowledging and refuting opposing perspectives demonstrates intellectual rigor and strengthens the validity of the author''s argument."}, {"id": "english-12-data-description-q1", "prompt": "Which verb means to rise rapidly and dramatically in value or quantity within a short period?", "difficulty": "EASY", "options": [{"id": "a", "text": "Surge"}, {"id": "b", "text": "Plummet"}, {"id": "c", "text": "Stagnate"}], "correctOptionId": "a", "explanation": "To ''surge'' means to experience a sudden and powerful upward movement or increase."}, {"id": "english-12-data-description-q2", "prompt": "Choose the sentence that accurately describes a line that goes up and down erratically over time:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Oil prices remained completely static throughout the year."}, {"id": "b", "text": "Oil prices plummeted to zero and stayed there permanently."}, {"id": "c", "text": "Oil prices fluctuated wildly between 70 and 110 dollars per barrel throughout the year."}], "correctOptionId": "c", "explanation": "''Fluctuate'' means to rise and fall irregularly in number or amount."}, {"id": "english-12-presentation-skills-q1", "prompt": "What is ''signposting language'' in oral presentations?", "difficulty": "EASY", "options": [{"id": "a", "text": "Words painted on wooden traffic road signs"}, {"id": "b", "text": "Technical jargon intended to confuse uneducated listeners"}, {"id": "c", "text": "Phrases used to guide listeners through the structure of a presentation and signal transitions between topics"}], "correctOptionId": "c", "explanation": "Signposting phrases (e.g., ''Moving on to'', ''To conclude'') indicate what direction the speaker is taking and keep the audience oriented."}, {"id": "english-12-presentation-skills-q2", "prompt": "Which signposting phrase is most appropriate when moving to a completely new section of your presentation?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Forget everything I just mentioned because it was wrong,..."}, {"id": "b", "text": "Turning our attention now to our next main topic,..."}, {"id": "c", "text": "To repeat once again what I said five minutes ago,..."}], "correctOptionId": "b", "explanation": "''Turning our attention now to...'' politely directs the audience''s focus toward the upcoming section."}, {"id": "english-12-interviews-cv-q1", "prompt": "In the STAR technique for answering competency-based interview questions, what does the letter ''A'' stand for?", "difficulty": "EASY", "options": [{"id": "a", "text": "Annual salary requested"}, {"id": "b", "text": "Action taken by the candidate"}, {"id": "c", "text": "Academic grades"}], "correctOptionId": "b", "explanation": "STAR stands for Situation, Task, Action, and Result, guiding candidates to describe specific behaviors and positive outcomes."}, {"id": "english-12-interviews-cv-q2", "prompt": "Why are powerful action verbs (e.g., ''orchestrated'', ''streamlined'', ''pioneered'') recommended when describing achievements on a CV?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "They highlight active leadership, initiative, and measurable contribution to past projects"}, {"id": "b", "text": "They disguise the fact that the applicant has no real qualifications"}, {"id": "c", "text": "They are required by national law in every resume"}], "correctOptionId": "a", "explanation": "Dynamic action verbs emphasize proactive contribution and impact rather than passive job descriptions."}]'::jsonb,'[]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-sustainable-future',1,'LESSON','Green Living and Sustainability','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Vocabulary on eco-friendly living: carbon footprint, renewable energy, biodegradable, sustainability, eco-conscious. Grammar: Cleft sentences with ''It is/was... that'' to add emphasis."]'::jsonb,'["It is the irresponsible disposal of plastic waste that poses the gravest threat to marine ecosystems."]'::jsonb,'[{"id": "english-12-sustainable-future-q1", "prompt": "Which word best describes materials that can break down naturally without harming the environment?", "difficulty": "EASY", "options": [{"id": "a", "text": "Biodegradable"}, {"id": "b", "text": "Non-recyclable"}, {"id": "c", "text": "Indestructible"}], "correctOptionId": "a", "explanation": "''Biodegradable'' refers to substances capable of being decomposed by bacteria or other biological agents."}, {"id": "english-12-sustainable-future-q2", "prompt": "Rewrite for emphasis using a cleft sentence: ''Plastic bags pollute our rivers.''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Plastic bags are what they pollute our rivers."}, {"id": "b", "text": "There is plastic bags polluting our rivers."}, {"id": "c", "text": "It is plastic bags that pollute our rivers."}], "correctOptionId": "c", "explanation": "The cleft sentence structure ''It is/was + emphasized element + that/who + clause'' is used to focus attention on ''plastic bags''."}, {"id": "english-12-sustainable-future-q3", "prompt": "Complete the sentence: ''Transitioning to renewable energy sources is essential if we want to minimize our global _______.''", "difficulty": "APPLIED", "options": [{"id": "a", "text": "fossil fuel"}, {"id": "b", "text": "carbon footprint"}, {"id": "c", "text": "ozone layer"}], "correctOptionId": "b", "explanation": "''Carbon footprint'' is the total amount of greenhouse gases generated by our actions and lifestyle."}]'::jsonb,'["english-12-sustainable-future"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-climate-action',2,'LESSON','Climate Change and Natural Ecosystems','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Vocabulary: deforestation, biodiversity loss, extreme weather events, habitat fragmentation, mitigation. Grammar: Passive voice with modal verbs (must be protected, should be reduced)."]'::jsonb,'["Vulnerable coastal areas must be safeguarded against rising sea levels through sustainable infrastructure."]'::jsonb,'[{"id": "english-12-climate-action-q1", "prompt": "What term refers to the rich variety of animal and plant life in a specific habitat or on Earth?", "difficulty": "EASY", "options": [{"id": "a", "text": "Deforestation"}, {"id": "b", "text": "Urbanisation"}, {"id": "c", "text": "Biodiversity"}], "correctOptionId": "c", "explanation": "''Biodiversity'' is the variety of plant and animal life in a particular habitat or in the world as a whole."}, {"id": "english-12-climate-action-q2", "prompt": "Choose the correct passive modal form: ''Strict environmental policies _______ immediately to curb industrial emissions.''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "must have implemented"}, {"id": "b", "text": "must be implemented"}, {"id": "c", "text": "must implement"}], "correctOptionId": "b", "explanation": "Passive with modal verb: modal + be + past participle (''must be implemented'')."}, {"id": "english-12-climate-action-q3", "prompt": "Identify the cohesive linker expressing cause and consequence: ''The polar ice caps are melting at an alarming rate; _______, low-lying coastal cities face heightened flood risks.''", "difficulty": "APPLIED", "options": [{"id": "a", "text": "consequently"}, {"id": "b", "text": "nevertheless"}, {"id": "c", "text": "on the contrary"}], "correctOptionId": "a", "explanation": "''Consequently'' signals a direct result or consequence of the preceding statement."}]'::jsonb,'["english-12-climate-action"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-urbanisation',3,'LESSON','Modern Cities and Smart Urbanisation','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Vocabulary: infrastructure, rural-to-urban migration, congestion, public amenities, high-density housing. Grammar: Participle clauses for reason and time (Having lived in crowded cities, ...)."]'::jsonb,'["Facing severe traffic congestion, metropolitan authorities invested heavily in underground metro networks."]'::jsonb,'[{"id": "english-12-urbanisation-q1", "prompt": "Which noun refers to the basic physical systems and structures of a city, such as roads, water supplies, and electricity grids?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ruralization"}, {"id": "b", "text": "Infrastructure"}, {"id": "c", "text": "Congestion"}], "correctOptionId": "b", "explanation": "''Infrastructure'' encompasses the fundamental facilities and systems serving a country, city, or area."}, {"id": "english-12-urbanisation-q2", "prompt": "Choose the participle clause that correctly replaces ''Because city planners realized the lack of green spaces, they created more public parks.'':", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Realizing the lack of green spaces, city planners created more public parks."}, {"id": "b", "text": "To realize the lack of green spaces, city planners created more public parks."}, {"id": "c", "text": "Realized the lack of green spaces, city planners created more public parks."}], "correctOptionId": "a", "explanation": "A present participle clause (-ing) replaces an active adverbial clause of reason when both clauses share the same subject."}, {"id": "english-12-urbanisation-q3", "prompt": "Complete the sentence: ''Rapid _______ has placed immense strain on sanitation, public healthcare, and housing in developing metropolises.''", "difficulty": "APPLIED", "options": [{"id": "a", "text": "agriculture"}, {"id": "b", "text": "conservation"}, {"id": "c", "text": "urbanisation"}], "correctOptionId": "c", "explanation": "''Urbanisation'' denotes the population shift from rural to urban areas and the gradual increase in the proportion of people living in towns and cities."}]'::jsonb,'["english-12-urbanisation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-cultural-heritage',4,'LESSON','Preserving Cultural Heritage in a Globalised World','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Vocabulary: tangible heritage (monuments, artifacts), intangible heritage (folklore, traditions, oral history), cultural identity, homogenization. Grammar: Inverted conditionals (Had we preserved..., Should you visit...)."]'::jsonb,'["Had local authorities restored the ancient citadel earlier, valuable architectural features would not have decayed."]'::jsonb,'[{"id": "english-12-cultural-heritage-q1", "prompt": "Folk singing, traditional festivals, and indigenous craftsmanship belong to which category of cultural heritage?", "difficulty": "EASY", "options": [{"id": "a", "text": "Intangible cultural heritage"}, {"id": "b", "text": "Tangible architectural heritage"}, {"id": "c", "text": "Natural ecological heritage"}], "correctOptionId": "a", "explanation": "''Intangible heritage'' includes non-physical traditions, living expressions, and performing arts transmitted from generation to generation."}, {"id": "english-12-cultural-heritage-q2", "prompt": "Choose the correct formal inverted conditional sentence:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "If had the historic pagoda been renovated properly, it would withstand."}, {"id": "b", "text": "Were the historic pagoda renovated properly, it will withstand."}, {"id": "c", "text": "Had the historic pagoda been renovated properly, it would have withstood the earthquake."}], "correctOptionId": "c", "explanation": "Third conditional inversion replaces ''If it had been renovated'' with ''Had it been renovated'' without using ''if''."}, {"id": "english-12-cultural-heritage-q3", "prompt": "Complete the sentence: ''Cultural _______ occurs when local customs and languages are gradually replaced by uniform global consumer trends.''", "difficulty": "APPLIED", "options": [{"id": "a", "text": "documentation"}, {"id": "b", "text": "homogenization"}, {"id": "c", "text": "diversification"}], "correctOptionId": "b", "explanation": "''Cultural homogenization'' is the reduction in cultural diversity through the popularization and diffusion of a wide array of cultural symbols."}]'::jsonb,'["english-12-cultural-heritage"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-global-citizenship',5,'LESSON','Cross-Cultural Communication and Global Citizenship','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Vocabulary: cultural competence, open-mindedness, stereotype, empathy, cross-cultural diplomacy. Grammar: Discourse markers of contrast (whereas, on the other hand, in spite of) and addition (moreover, furthermore)."]'::jsonb,'["While mastering a foreign language is crucial, cultivating genuine empathy is equally indispensable for cross-cultural collaboration."]'::jsonb,'[{"id": "english-12-global-citizenship-q1", "prompt": "What does having ''cross-cultural competence'' primarily involve?", "difficulty": "EASY", "options": [{"id": "a", "text": "The requirement to abandon one''s own national identity and mother tongue"}, {"id": "b", "text": "The memorization of all historical dates of every country in the world"}, {"id": "c", "text": "The ability to understand, communicate with, and effectively interact with people across cultures"}], "correctOptionId": "c", "explanation": "Cross-cultural competence involves awareness, attitudes, knowledge, and skills to engage respectfully across diverse cultural boundaries."}, {"id": "english-12-global-citizenship-q2", "prompt": "Select the correct linker of contrast to join the ideas: ''Online platforms facilitate worldwide communication; _______, they can sometimes amplify misunderstandings.''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "in addition"}, {"id": "b", "text": "nevertheless"}, {"id": "c", "text": "consequently"}], "correctOptionId": "b", "explanation": "''Nevertheless'' introduces a contrast or concession to the preceding independent clause."}, {"id": "english-12-global-citizenship-q3", "prompt": "A fixed, oversimplified, and often biased belief about a particular group of people is known as a:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "stereotype"}, {"id": "b", "text": "milestone"}, {"id": "c", "text": "consensus"}], "correctOptionId": "a", "explanation": "A ''stereotype'' is an over-generalized belief or assumption about a particular category or group of people."}]'::jsonb,'["english-12-global-citizenship"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-review-1',6,'FIVE_LESSON_REVIEW','Ôn tập 1','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "english-12-sustainable-future-q1", "prompt": "Which word best describes materials that can break down naturally without harming the environment?", "difficulty": "EASY", "options": [{"id": "a", "text": "Biodegradable"}, {"id": "b", "text": "Non-recyclable"}, {"id": "c", "text": "Indestructible"}], "correctOptionId": "a", "explanation": "''Biodegradable'' refers to substances capable of being decomposed by bacteria or other biological agents."}, {"id": "english-12-sustainable-future-q2", "prompt": "Rewrite for emphasis using a cleft sentence: ''Plastic bags pollute our rivers.''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Plastic bags are what they pollute our rivers."}, {"id": "b", "text": "There is plastic bags polluting our rivers."}, {"id": "c", "text": "It is plastic bags that pollute our rivers."}], "correctOptionId": "c", "explanation": "The cleft sentence structure ''It is/was + emphasized element + that/who + clause'' is used to focus attention on ''plastic bags''."}, {"id": "english-12-climate-action-q1", "prompt": "What term refers to the rich variety of animal and plant life in a specific habitat or on Earth?", "difficulty": "EASY", "options": [{"id": "a", "text": "Deforestation"}, {"id": "b", "text": "Urbanisation"}, {"id": "c", "text": "Biodiversity"}], "correctOptionId": "c", "explanation": "''Biodiversity'' is the variety of plant and animal life in a particular habitat or in the world as a whole."}, {"id": "english-12-climate-action-q2", "prompt": "Choose the correct passive modal form: ''Strict environmental policies _______ immediately to curb industrial emissions.''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "must have implemented"}, {"id": "b", "text": "must be implemented"}, {"id": "c", "text": "must implement"}], "correctOptionId": "b", "explanation": "Passive with modal verb: modal + be + past participle (''must be implemented'')."}, {"id": "english-12-urbanisation-q1", "prompt": "Which noun refers to the basic physical systems and structures of a city, such as roads, water supplies, and electricity grids?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ruralization"}, {"id": "b", "text": "Infrastructure"}, {"id": "c", "text": "Congestion"}], "correctOptionId": "b", "explanation": "''Infrastructure'' encompasses the fundamental facilities and systems serving a country, city, or area."}, {"id": "english-12-urbanisation-q2", "prompt": "Choose the participle clause that correctly replaces ''Because city planners realized the lack of green spaces, they created more public parks.'':", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Realizing the lack of green spaces, city planners created more public parks."}, {"id": "b", "text": "To realize the lack of green spaces, city planners created more public parks."}, {"id": "c", "text": "Realized the lack of green spaces, city planners created more public parks."}], "correctOptionId": "a", "explanation": "A present participle clause (-ing) replaces an active adverbial clause of reason when both clauses share the same subject."}, {"id": "english-12-cultural-heritage-q1", "prompt": "Folk singing, traditional festivals, and indigenous craftsmanship belong to which category of cultural heritage?", "difficulty": "EASY", "options": [{"id": "a", "text": "Intangible cultural heritage"}, {"id": "b", "text": "Tangible architectural heritage"}, {"id": "c", "text": "Natural ecological heritage"}], "correctOptionId": "a", "explanation": "''Intangible heritage'' includes non-physical traditions, living expressions, and performing arts transmitted from generation to generation."}, {"id": "english-12-cultural-heritage-q2", "prompt": "Choose the correct formal inverted conditional sentence:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "If had the historic pagoda been renovated properly, it would withstand."}, {"id": "b", "text": "Were the historic pagoda renovated properly, it will withstand."}, {"id": "c", "text": "Had the historic pagoda been renovated properly, it would have withstood the earthquake."}], "correctOptionId": "c", "explanation": "Third conditional inversion replaces ''If it had been renovated'' with ''Had it been renovated'' without using ''if''."}, {"id": "english-12-global-citizenship-q1", "prompt": "What does having ''cross-cultural competence'' primarily involve?", "difficulty": "EASY", "options": [{"id": "a", "text": "The requirement to abandon one''s own national identity and mother tongue"}, {"id": "b", "text": "The memorization of all historical dates of every country in the world"}, {"id": "c", "text": "The ability to understand, communicate with, and effectively interact with people across cultures"}], "correctOptionId": "c", "explanation": "Cross-cultural competence involves awareness, attitudes, knowledge, and skills to engage respectfully across diverse cultural boundaries."}, {"id": "english-12-global-citizenship-q2", "prompt": "Select the correct linker of contrast to join the ideas: ''Online platforms facilitate worldwide communication; _______, they can sometimes amplify misunderstandings.''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "in addition"}, {"id": "b", "text": "nevertheless"}, {"id": "c", "text": "consequently"}], "correctOptionId": "b", "explanation": "''Nevertheless'' introduces a contrast or concession to the preceding independent clause."}]'::jsonb,'["english-12-sustainable-future", "english-12-climate-action", "english-12-urbanisation", "english-12-cultural-heritage", "english-12-global-citizenship"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-higher-education',7,'LESSON','Choosing University and Lifelong Learning','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Vocabulary: tertiary education, vocational training, academic curriculum, tuition fees, scholarship, extracurricular. Grammar: Relative clauses with prepositions (the field in which she excels, the mentor with whom I consulted)."]'::jsonb,'["Higher education offers specialized environments in which students develop critical thinking and professional networks."]'::jsonb,'[{"id": "english-12-higher-education-q1", "prompt": "Education and training provided by universities, colleges, and technical institutes after secondary school is called:", "difficulty": "EASY", "options": [{"id": "a", "text": "Pre-school education"}, {"id": "b", "text": "Tertiary education"}, {"id": "c", "text": "Primary education"}], "correctOptionId": "b", "explanation": "''Tertiary education'' refers to any level of formal education pursued after high school graduation, including university and vocational colleges."}, {"id": "english-12-higher-education-q2", "prompt": "Choose the sentence with the correct formal relative clause containing a preposition:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Architecture is an interdisciplinary field in which artistic vision meets engineering precision."}, {"id": "b", "text": "Architecture is an interdisciplinary field which in artistic vision meets engineering."}, {"id": "c", "text": "Architecture is an interdisciplinary field where in artistic vision meets engineering."}], "correctOptionId": "a", "explanation": "In formal academic English, prepositions precede relative pronouns: ''field in which''."}, {"id": "english-12-higher-education-q3", "prompt": "Which option best describes ''lifelong learning''?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Studying exclusively during the years of compulsory high school education"}, {"id": "b", "text": "Memorizing textbooks only to pass a single final exam"}, {"id": "c", "text": "The ongoing, voluntary, and self-motivated pursuit of knowledge throughout one''s personal or professional life"}], "correctOptionId": "c", "explanation": "''Lifelong learning'' is the continuous pursuit of knowledge and skills throughout life to adapt to changing career and personal demands."}]'::jsonb,'["english-12-higher-education"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-future-careers',8,'LESSON','The Changing World of Work','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Vocabulary: telecommuting (remote work), automation, gig economy, career adaptability, soft skills. Grammar: Future continuous (will be doing) and future perfect (will have done)."]'::jsonb,'["By the year 2035, artificial intelligence systems will have transformed most conventional administrative tasks."]'::jsonb,'[{"id": "english-12-future-careers-q1", "prompt": "What term describes working from home or another remote location using telecommunications and the internet?", "difficulty": "EASY", "options": [{"id": "a", "text": "Telecommuting"}, {"id": "b", "text": "Commuting"}, {"id": "c", "text": "Assembly line"}], "correctOptionId": "a", "explanation": "''Telecommuting'' (or remote working) involves working outside a traditional office space by connecting through digital tools."}, {"id": "english-12-future-careers-q2", "prompt": "Complete the sentence using the Future Perfect tense: ''By the end of this decade, automated algorithms _______ millions of manual routine operations.''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "will be replacing"}, {"id": "b", "text": "have replaced"}, {"id": "c", "text": "will have replaced"}], "correctOptionId": "c", "explanation": "Future Perfect (will have + past participle) expresses an action that will be completed before a specified point in the future."}, {"id": "english-12-future-careers-q3", "prompt": "In addition to technical expertise, employers increasingly value _______ such as adaptability, teamwork, and conflict resolution.", "difficulty": "APPLIED", "options": [{"id": "a", "text": "hardware drives"}, {"id": "b", "text": "soft skills"}, {"id": "c", "text": "machinery parts"}], "correctOptionId": "b", "explanation": "''Soft skills'' are interpersonal attributes and communication abilities that characterize how a person interacts and collaborates in the workplace."}]'::jsonb,'["english-12-future-careers"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-artificial-intelligence',9,'LESSON','Artificial Intelligence and Innovation','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Vocabulary: machine learning, algorithmic bias, autonomous vehicles, ethical dilemma, big data. Grammar: Reporting verbs followed by gerunds or infinitives (advise, warn, recommend, insist on)."]'::jsonb,'["Tech ethicists warned against relying uncritically on unvetted algorithms in judicial decision-making."]'::jsonb,'[{"id": "english-12-artificial-intelligence-q1", "prompt": "A system or machine capable of performing tasks that typically require human intelligence is called:", "difficulty": "EASY", "options": [{"id": "a", "text": "Manual typewriter"}, {"id": "b", "text": "Analog calculator"}, {"id": "c", "text": "Artificial intelligence"}], "correctOptionId": "c", "explanation": "''Artificial intelligence'' (AI) is the simulation of human intelligence processes by computer systems."}, {"id": "english-12-artificial-intelligence-q2", "prompt": "Choose the grammatically correct sentence using an advanced reporting verb:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Leading computer scientists recommended regulate autonomous weapons."}, {"id": "b", "text": "Leading computer scientists recommended regulating autonomous weapons before deployment."}, {"id": "c", "text": "Leading computer scientists recommended to regulate autonomous weapons."}], "correctOptionId": "b", "explanation": "The verb ''recommend'' takes a gerund (-ing) when directly followed by an action without a personal object: ''recommended regulating''."}, {"id": "english-12-artificial-intelligence-q3", "prompt": "When an AI recruitment tool unfairly favors male candidates due to historical data imbalances, it exhibits:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "algorithmic bias"}, {"id": "b", "text": "renewable energy"}, {"id": "c", "text": "biological diversity"}], "correctOptionId": "a", "explanation": "''Algorithmic bias'' refers to systematic and repeatable errors in a computer system that create unfair outcomes, such as privileging one arbitrary group over another."}]'::jsonb,'["english-12-artificial-intelligence"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-workplace-skills',10,'LESSON','Workplace Communication and Collaboration','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Vocabulary: constructive feedback, negotiation, minutes of meeting, consensus, protocol. Grammar: Polite requests, indirect questions, and hedging language (Could you please clarify..., It would appear that...)."]'::jsonb,'["Could you kindly let me know whether the financial audit will be finalized by Friday afternoon?"]'::jsonb,'[{"id": "english-12-workplace-skills-q1", "prompt": "The official written record of what was discussed and agreed upon during a business meeting is known as:", "difficulty": "EASY", "options": [{"id": "a", "text": "Marketing flyer"}, {"id": "b", "text": "Meeting minutes"}, {"id": "c", "text": "Casual gossip"}], "correctOptionId": "b", "explanation": "''Minutes'' are the instant written record of a meeting or hearing, describing the events and listing attendees, discussions, and decisions."}, {"id": "english-12-workplace-skills-q2", "prompt": "Convert into a polite indirect question: ''Where is the quarterly sales report?''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Could you please tell me where the quarterly sales report is?"}, {"id": "b", "text": "Could you please tell me where is the quarterly sales report?"}, {"id": "c", "text": "Where the quarterly sales report could you please tell me?"}], "correctOptionId": "a", "explanation": "In indirect questions, the clause following the introductory phrase uses normal statement word order: ''where + subject + verb''."}, {"id": "english-12-workplace-skills-q3", "prompt": "In professional communication, feedback intended to help a colleague improve their performance without causing offense is termed:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "destructive criticism"}, {"id": "b", "text": "hostile accusation"}, {"id": "c", "text": "constructive feedback"}], "correctOptionId": "c", "explanation": "''Constructive feedback'' is supportive feedback given to an individual to help identify solutions to some areas of weakness."}]'::jsonb,'["english-12-workplace-skills"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-financial-literacy',11,'LESSON','Personal Finance and Entrepreneurship','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Vocabulary: budgeting, compound interest, return on investment (ROI), asset, liability, start-up. Grammar: Mixed conditionals (If I had invested earlier, I would be financially secure today)."]'::jsonb,'["If she had saved a portion of her earnings during college, she would not be struggling with student debt now."]'::jsonb,'[{"id": "english-12-financial-literacy-q1", "prompt": "The interest calculated on the initial principal and also on the accumulated interest of previous periods of a deposit is called:", "difficulty": "EASY", "options": [{"id": "a", "text": "Compound interest"}, {"id": "b", "text": "Fixed deduction"}, {"id": "c", "text": "Bank penalty"}], "correctOptionId": "a", "explanation": "''Compound interest'' is interest calculated on the principal amount plus any accrued interest over time."}, {"id": "english-12-financial-literacy-q2", "prompt": "Choose the mixed conditional sentence connecting a past action with a present result:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "If they conducted market research, their start-up would not have been in financial crisis."}, {"id": "b", "text": "If they had conducted market research, their start-up will not be in financial crisis."}, {"id": "c", "text": "If they had conducted market research, their start-up would not be in financial crisis right now."}], "correctOptionId": "c", "explanation": "Mixed conditional (Past condition -> Present result): If + past perfect (had conducted), would + bare infinitive (would not be ... now)."}, {"id": "english-12-financial-literacy-q3", "prompt": "Something valuable that an individual or business owns and can convert into cash is defined as an:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "liability"}, {"id": "b", "text": "asset"}, {"id": "c", "text": "expense"}], "correctOptionId": "b", "explanation": "An ''asset'' is a resource with economic value that an individual, corporation, or country owns or controls with the expectation that it will provide a future benefit."}]'::jsonb,'["english-12-financial-literacy"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-review-2',12,'FIVE_LESSON_REVIEW','Ôn tập 2','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "english-12-higher-education-q1", "prompt": "Education and training provided by universities, colleges, and technical institutes after secondary school is called:", "difficulty": "EASY", "options": [{"id": "a", "text": "Pre-school education"}, {"id": "b", "text": "Tertiary education"}, {"id": "c", "text": "Primary education"}], "correctOptionId": "b", "explanation": "''Tertiary education'' refers to any level of formal education pursued after high school graduation, including university and vocational colleges."}, {"id": "english-12-higher-education-q2", "prompt": "Choose the sentence with the correct formal relative clause containing a preposition:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Architecture is an interdisciplinary field in which artistic vision meets engineering precision."}, {"id": "b", "text": "Architecture is an interdisciplinary field which in artistic vision meets engineering."}, {"id": "c", "text": "Architecture is an interdisciplinary field where in artistic vision meets engineering."}], "correctOptionId": "a", "explanation": "In formal academic English, prepositions precede relative pronouns: ''field in which''."}, {"id": "english-12-future-careers-q1", "prompt": "What term describes working from home or another remote location using telecommunications and the internet?", "difficulty": "EASY", "options": [{"id": "a", "text": "Telecommuting"}, {"id": "b", "text": "Commuting"}, {"id": "c", "text": "Assembly line"}], "correctOptionId": "a", "explanation": "''Telecommuting'' (or remote working) involves working outside a traditional office space by connecting through digital tools."}, {"id": "english-12-future-careers-q2", "prompt": "Complete the sentence using the Future Perfect tense: ''By the end of this decade, automated algorithms _______ millions of manual routine operations.''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "will be replacing"}, {"id": "b", "text": "have replaced"}, {"id": "c", "text": "will have replaced"}], "correctOptionId": "c", "explanation": "Future Perfect (will have + past participle) expresses an action that will be completed before a specified point in the future."}, {"id": "english-12-artificial-intelligence-q1", "prompt": "A system or machine capable of performing tasks that typically require human intelligence is called:", "difficulty": "EASY", "options": [{"id": "a", "text": "Manual typewriter"}, {"id": "b", "text": "Analog calculator"}, {"id": "c", "text": "Artificial intelligence"}], "correctOptionId": "c", "explanation": "''Artificial intelligence'' (AI) is the simulation of human intelligence processes by computer systems."}, {"id": "english-12-artificial-intelligence-q2", "prompt": "Choose the grammatically correct sentence using an advanced reporting verb:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Leading computer scientists recommended regulate autonomous weapons."}, {"id": "b", "text": "Leading computer scientists recommended regulating autonomous weapons before deployment."}, {"id": "c", "text": "Leading computer scientists recommended to regulate autonomous weapons."}], "correctOptionId": "b", "explanation": "The verb ''recommend'' takes a gerund (-ing) when directly followed by an action without a personal object: ''recommended regulating''."}, {"id": "english-12-workplace-skills-q1", "prompt": "The official written record of what was discussed and agreed upon during a business meeting is known as:", "difficulty": "EASY", "options": [{"id": "a", "text": "Marketing flyer"}, {"id": "b", "text": "Meeting minutes"}, {"id": "c", "text": "Casual gossip"}], "correctOptionId": "b", "explanation": "''Minutes'' are the instant written record of a meeting or hearing, describing the events and listing attendees, discussions, and decisions."}, {"id": "english-12-workplace-skills-q2", "prompt": "Convert into a polite indirect question: ''Where is the quarterly sales report?''", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Could you please tell me where the quarterly sales report is?"}, {"id": "b", "text": "Could you please tell me where is the quarterly sales report?"}, {"id": "c", "text": "Where the quarterly sales report could you please tell me?"}], "correctOptionId": "a", "explanation": "In indirect questions, the clause following the introductory phrase uses normal statement word order: ''where + subject + verb''."}, {"id": "english-12-financial-literacy-q1", "prompt": "The interest calculated on the initial principal and also on the accumulated interest of previous periods of a deposit is called:", "difficulty": "EASY", "options": [{"id": "a", "text": "Compound interest"}, {"id": "b", "text": "Fixed deduction"}, {"id": "c", "text": "Bank penalty"}], "correctOptionId": "a", "explanation": "''Compound interest'' is interest calculated on the principal amount plus any accrued interest over time."}, {"id": "english-12-financial-literacy-q2", "prompt": "Choose the mixed conditional sentence connecting a past action with a present result:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "If they conducted market research, their start-up would not have been in financial crisis."}, {"id": "b", "text": "If they had conducted market research, their start-up will not be in financial crisis."}, {"id": "c", "text": "If they had conducted market research, their start-up would not be in financial crisis right now."}], "correctOptionId": "c", "explanation": "Mixed conditional (Past condition -> Present result): If + past perfect (had conducted), would + bare infinitive (would not be ... now)."}]'::jsonb,'["english-12-higher-education", "english-12-future-careers", "english-12-artificial-intelligence", "english-12-workplace-skills", "english-12-financial-literacy"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-academic-reading',13,'LESSON','Critical Reading and Identifying Author Stance','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Reading techniques: skimming (reading quickly for main ideas), scanning (searching for specific facts/keywords), inferring tone, differentiating objective facts from subjective claims."]'::jsonb,'["While statistical data represent objective facts, the author''s choice of adjectives reveals a distinctly skeptical stance toward nuclear expansion."]'::jsonb,'[{"id": "english-12-academic-reading-q1", "prompt": "Which academic reading skill involves rapidly reading through a text to get an overview of the main theme and structure?", "difficulty": "EASY", "options": [{"id": "a", "text": "Proofreading"}, {"id": "b", "text": "Scanning for a phone number"}, {"id": "c", "text": "Skimming"}], "correctOptionId": "c", "explanation": "''Skimming'' is reading rapidly to get a general overview and understand the main idea of a passage."}, {"id": "english-12-academic-reading-q2", "prompt": "Which statement represents an objective fact rather than a subjective opinion?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Every student ought to find biology the most fascinating subject."}, {"id": "b", "text": "The Earth revolves around the Sun in approximately 365.25 days."}, {"id": "c", "text": "Solar energy is by far the most magnificent human invention in history."}], "correctOptionId": "b", "explanation": "Objective facts can be empirically verified through measurement and scientific observation, unlike personal evaluative judgments."}, {"id": "english-12-academic-reading-q3", "prompt": "When an author uses words like ''presumably'', ''allegedly'', and ''dubious'', what stance are they expressing toward the claim?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Skepticism and caution"}, {"id": "b", "text": "Unconditional certainty"}, {"id": "c", "text": "Enthusiastic agreement"}], "correctOptionId": "a", "explanation": "Words like ''allegedly'' and ''dubious'' are epistemic markers indicating doubt, reservation, and a critical distance from the asserted claim."}]'::jsonb,'["english-12-academic-reading"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-academic-writing',14,'LESSON','Structuring an Argumentative Essay','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Essay structure: Introduction (hook, background, thesis statement), Body paragraphs (topic sentence, evidence, explanation, counter-argument & refutation), Conclusion (restated thesis, summary of main points, final thought). Cohesion and coherence."]'::jsonb,'["A well-crafted topic sentence announces the main idea of the paragraph and connects directly back to the overarching thesis statement."]'::jsonb,'[{"id": "english-12-academic-writing-q1", "prompt": "What is the core sentence in the introductory paragraph that clearly states the author''s central claim and roadmap for the essay?", "difficulty": "EASY", "options": [{"id": "a", "text": "The bibliography citation"}, {"id": "b", "text": "The thesis statement"}, {"id": "c", "text": "The rhetorical question"}], "correctOptionId": "b", "explanation": "The ''thesis statement'' expresses the main argument and sets up the scope and focus of the entire academic essay."}, {"id": "english-12-academic-writing-q2", "prompt": "What is the purpose of addressing a ''counter-argument'' in an argumentative essay?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "To acknowledge an opposing viewpoint and systematically refute it to strengthen one''s own position"}, {"id": "b", "text": "To confuse the reader and make the essay look longer"}, {"id": "c", "text": "To admit that the author''s main thesis is completely mistaken"}], "correctOptionId": "a", "explanation": "Acknowledging and refuting opposing perspectives demonstrates intellectual rigor and strengthens the validity of the author''s argument."}, {"id": "english-12-academic-writing-q3", "prompt": "Which transition word is best suited to introduce an opposing perspective in an academic paragraph?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Furthermore"}, {"id": "b", "text": "In illustration"}, {"id": "c", "text": "Conversely"}], "correctOptionId": "c", "explanation": "''Conversely'' is used to introduce an idea that is the exact opposite of the preceding statement."}]'::jsonb,'["english-12-academic-writing"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-data-description',15,'LESSON','Describing Graphs, Charts and Trends','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Academic vocabulary for trend analysis: fluctuate, peak at, plummet, surge, level off, remain steady. Adverbs of degree: dramatically, steadily, marginally, considerably."]'::jsonb,'["Between 2020 and 2024, solar panel installations surged considerably before leveling off at 150 gigawatts."]'::jsonb,'[{"id": "english-12-data-description-q1", "prompt": "Which verb means to rise rapidly and dramatically in value or quantity within a short period?", "difficulty": "EASY", "options": [{"id": "a", "text": "Surge"}, {"id": "b", "text": "Plummet"}, {"id": "c", "text": "Stagnate"}], "correctOptionId": "a", "explanation": "To ''surge'' means to experience a sudden and powerful upward movement or increase."}, {"id": "english-12-data-description-q2", "prompt": "Choose the sentence that accurately describes a line that goes up and down erratically over time:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Oil prices remained completely static throughout the year."}, {"id": "b", "text": "Oil prices plummeted to zero and stayed there permanently."}, {"id": "c", "text": "Oil prices fluctuated wildly between 70 and 110 dollars per barrel throughout the year."}], "correctOptionId": "c", "explanation": "''Fluctuate'' means to rise and fall irregularly in number or amount."}, {"id": "english-12-data-description-q3", "prompt": "In academic IELTS/B1 writing, the phrase ''leveled off'' describes a trend that:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "increased at an exponential pace"}, {"id": "b", "text": "stopped increasing or decreasing and became stable"}, {"id": "c", "text": "reached zero instantaneously"}], "correctOptionId": "b", "explanation": "To ''level off'' (or level out) means to stabilize after a period of increase or decrease."}]'::jsonb,'["english-12-data-description"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-presentation-skills',16,'LESSON','Delivering an Effective Oral Presentation','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Signposting language: ''Turning now to...'', ''To illustrate this point...'', ''In summary...''. Body language, eye contact, managing pacing. Handling audience questions politely and precisely."]'::jsonb,'["Having discussed the environmental ramifications, I would now like to turn your attention to the economic viability of green technologies."]'::jsonb,'[{"id": "english-12-presentation-skills-q1", "prompt": "What is ''signposting language'' in oral presentations?", "difficulty": "EASY", "options": [{"id": "a", "text": "Words painted on wooden traffic road signs"}, {"id": "b", "text": "Technical jargon intended to confuse uneducated listeners"}, {"id": "c", "text": "Phrases used to guide listeners through the structure of a presentation and signal transitions between topics"}], "correctOptionId": "c", "explanation": "Signposting phrases (e.g., ''Moving on to'', ''To conclude'') indicate what direction the speaker is taking and keep the audience oriented."}, {"id": "english-12-presentation-skills-q2", "prompt": "Which signposting phrase is most appropriate when moving to a completely new section of your presentation?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Forget everything I just mentioned because it was wrong,..."}, {"id": "b", "text": "Turning our attention now to our next main topic,..."}, {"id": "c", "text": "To repeat once again what I said five minutes ago,..."}], "correctOptionId": "b", "explanation": "''Turning our attention now to...'' politely directs the audience''s focus toward the upcoming section."}, {"id": "english-12-presentation-skills-q3", "prompt": "If a presenter does not understand an audience member''s question during Q&A, the best strategy is to:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "politely ask the questioner to rephrase or clarify their question"}, {"id": "b", "text": "pretend to answer an unrelated question and hope nobody notices"}, {"id": "c", "text": "tell the questioner that their question is completely useless"}], "correctOptionId": "a", "explanation": "Politely asking for clarification (''Could you please clarify what you mean by...?'') demonstrates active listening and professional demeanor."}]'::jsonb,'["english-12-presentation-skills"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-interviews-cv',17,'LESSON','Writing a Résumé and Job Interview Techniques','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Résumé components: Profile summary, Education, Work experience, Key competencies. Action verbs: coordinated, spearheaded, streamlined, implemented. STAR method for behavioral interviews (Situation, Task, Action, Result)."]'::jsonb,'["Using the STAR method, the candidate explained how she streamlined inventory management, reducing operational costs by 15%."]'::jsonb,'[{"id": "english-12-interviews-cv-q1", "prompt": "In the STAR technique for answering competency-based interview questions, what does the letter ''A'' stand for?", "difficulty": "EASY", "options": [{"id": "a", "text": "Annual salary requested"}, {"id": "b", "text": "Action taken by the candidate"}, {"id": "c", "text": "Academic grades"}], "correctOptionId": "b", "explanation": "STAR stands for Situation, Task, Action, and Result, guiding candidates to describe specific behaviors and positive outcomes."}, {"id": "english-12-interviews-cv-q2", "prompt": "Why are powerful action verbs (e.g., ''orchestrated'', ''streamlined'', ''pioneered'') recommended when describing achievements on a CV?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "They highlight active leadership, initiative, and measurable contribution to past projects"}, {"id": "b", "text": "They disguise the fact that the applicant has no real qualifications"}, {"id": "c", "text": "They are required by national law in every resume"}], "correctOptionId": "a", "explanation": "Dynamic action verbs emphasize proactive contribution and impact rather than passive job descriptions."}, {"id": "english-12-interviews-cv-q3", "prompt": "When an interviewer asks ''What is your greatest weakness?'', the most effective approach is to:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "claim that you have absolutely no flaws and are completely flawless"}, {"id": "b", "text": "state that you despise working with other human beings"}, {"id": "c", "text": "name a genuine area for development and explain the concrete steps you are taking to overcome it"}], "correctOptionId": "c", "explanation": "Discussing a real professional area for growth along with proactive mitigation steps displays self-awareness, honesty, and growth mindset."}]'::jsonb,'["english-12-interviews-cv"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('english',12,'intro-2026.1','english-12-review-3',18,'FIVE_LESSON_REVIEW','Ôn tập 3','Tiếng Anh 12: Global Issues, Future Careers and Academic Communication','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "english-12-academic-reading-q1", "prompt": "Which academic reading skill involves rapidly reading through a text to get an overview of the main theme and structure?", "difficulty": "EASY", "options": [{"id": "a", "text": "Proofreading"}, {"id": "b", "text": "Scanning for a phone number"}, {"id": "c", "text": "Skimming"}], "correctOptionId": "c", "explanation": "''Skimming'' is reading rapidly to get a general overview and understand the main idea of a passage."}, {"id": "english-12-academic-reading-q2", "prompt": "Which statement represents an objective fact rather than a subjective opinion?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Every student ought to find biology the most fascinating subject."}, {"id": "b", "text": "The Earth revolves around the Sun in approximately 365.25 days."}, {"id": "c", "text": "Solar energy is by far the most magnificent human invention in history."}], "correctOptionId": "b", "explanation": "Objective facts can be empirically verified through measurement and scientific observation, unlike personal evaluative judgments."}, {"id": "english-12-academic-writing-q1", "prompt": "What is the core sentence in the introductory paragraph that clearly states the author''s central claim and roadmap for the essay?", "difficulty": "EASY", "options": [{"id": "a", "text": "The bibliography citation"}, {"id": "b", "text": "The thesis statement"}, {"id": "c", "text": "The rhetorical question"}], "correctOptionId": "b", "explanation": "The ''thesis statement'' expresses the main argument and sets up the scope and focus of the entire academic essay."}, {"id": "english-12-academic-writing-q2", "prompt": "What is the purpose of addressing a ''counter-argument'' in an argumentative essay?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "To acknowledge an opposing viewpoint and systematically refute it to strengthen one''s own position"}, {"id": "b", "text": "To confuse the reader and make the essay look longer"}, {"id": "c", "text": "To admit that the author''s main thesis is completely mistaken"}], "correctOptionId": "a", "explanation": "Acknowledging and refuting opposing perspectives demonstrates intellectual rigor and strengthens the validity of the author''s argument."}, {"id": "english-12-data-description-q1", "prompt": "Which verb means to rise rapidly and dramatically in value or quantity within a short period?", "difficulty": "EASY", "options": [{"id": "a", "text": "Surge"}, {"id": "b", "text": "Plummet"}, {"id": "c", "text": "Stagnate"}], "correctOptionId": "a", "explanation": "To ''surge'' means to experience a sudden and powerful upward movement or increase."}, {"id": "english-12-data-description-q2", "prompt": "Choose the sentence that accurately describes a line that goes up and down erratically over time:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Oil prices remained completely static throughout the year."}, {"id": "b", "text": "Oil prices plummeted to zero and stayed there permanently."}, {"id": "c", "text": "Oil prices fluctuated wildly between 70 and 110 dollars per barrel throughout the year."}], "correctOptionId": "c", "explanation": "''Fluctuate'' means to rise and fall irregularly in number or amount."}, {"id": "english-12-presentation-skills-q1", "prompt": "What is ''signposting language'' in oral presentations?", "difficulty": "EASY", "options": [{"id": "a", "text": "Words painted on wooden traffic road signs"}, {"id": "b", "text": "Technical jargon intended to confuse uneducated listeners"}, {"id": "c", "text": "Phrases used to guide listeners through the structure of a presentation and signal transitions between topics"}], "correctOptionId": "c", "explanation": "Signposting phrases (e.g., ''Moving on to'', ''To conclude'') indicate what direction the speaker is taking and keep the audience oriented."}, {"id": "english-12-presentation-skills-q2", "prompt": "Which signposting phrase is most appropriate when moving to a completely new section of your presentation?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Forget everything I just mentioned because it was wrong,..."}, {"id": "b", "text": "Turning our attention now to our next main topic,..."}, {"id": "c", "text": "To repeat once again what I said five minutes ago,..."}], "correctOptionId": "b", "explanation": "''Turning our attention now to...'' politely directs the audience''s focus toward the upcoming section."}, {"id": "english-12-interviews-cv-q1", "prompt": "In the STAR technique for answering competency-based interview questions, what does the letter ''A'' stand for?", "difficulty": "EASY", "options": [{"id": "a", "text": "Annual salary requested"}, {"id": "b", "text": "Action taken by the candidate"}, {"id": "c", "text": "Academic grades"}], "correctOptionId": "b", "explanation": "STAR stands for Situation, Task, Action, and Result, guiding candidates to describe specific behaviors and positive outcomes."}, {"id": "english-12-interviews-cv-q2", "prompt": "Why are powerful action verbs (e.g., ''orchestrated'', ''streamlined'', ''pioneered'') recommended when describing achievements on a CV?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "They highlight active leadership, initiative, and measurable contribution to past projects"}, {"id": "b", "text": "They disguise the fact that the applicant has no real qualifications"}, {"id": "c", "text": "They are required by national law in every resume"}], "correctOptionId": "a", "explanation": "Dynamic action verbs emphasize proactive contribution and impact rather than passive job descriptions."}]'::jsonb,'["english-12-academic-reading", "english-12-academic-writing", "english-12-data-description", "english-12-presentation-skills", "english-12-interviews-cv"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','placement',0,'PLACEMENT','Khảo sát đầu vào','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "history-12-cold-war-origins-q1", "prompt": "Hội nghị Ianta diễn ra vào tháng 2/1945 có sự tham gia của nguyên thủ ba cường quốc nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Liên Xô, Mĩ và Anh"}, {"id": "b", "text": "Mĩ, Anh và Pháp"}, {"id": "c", "text": "Liên Xô, Trung Quốc và Mĩ"}], "correctOptionId": "a", "explanation": "Hội nghị Ianta quy tụ ba nguyên thủ: Stalin (Liên Xô), Roosevelt (Mĩ) và Churchill (Anh) để thỏa thuận phân chia phạm vi ảnh hưởng sau Thế chiến II."}, {"id": "history-12-cold-war-origins-q2", "prompt": "Sự kiện nào sau đây đánh dấu sự khởi đầu chính thức của cuộc Chiến tranh Lạnh giữa hai phe?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Sự ra đời của tổ chức Hiệp ước Bắc Đại Tây Dương (NATO) năm 1949"}, {"id": "b", "text": "Sự thành lập khối Hiệp ước Warsaw tại Đông Âu năm 1955"}, {"id": "c", "text": "Thông điệp của Tổng thống Mĩ Truman tại Quốc hội Mĩ (tháng 3/1947)"}], "correctOptionId": "c", "explanation": "Tháng 3/1947, Thông điệp Truman khẳng định sự tồn tại của Liên Xô là mối đe dọa và viện trợ cho Hy Lạp, Thổ Nhĩ Kỳ, mở đầu Chiến tranh Lạnh."}, {"id": "history-12-united-nations-q1", "prompt": "Mục tiêu bao trùm hàng đầu của tổ chức Liên hợp quốc được ghi nhận trong Hiến chương năm 1945 là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Thành lập một chính phủ liên bang chung cho toàn cầu"}, {"id": "b", "text": "Xóa bỏ hoàn toàn mọi đường biên giới quốc gia giữa các nước"}, {"id": "c", "text": "Duy trì hòa bình và an ninh quốc tế"}], "correctOptionId": "c", "explanation": "Điều 1 Hiến chương Liên hợp quốc xác định mục tiêu cao nhất là duy trì hòa bình và an ninh thế giới, ngăn ngừa chiến tranh tái diễn."}, {"id": "history-12-united-nations-q2", "prompt": "Cơ quan nào của Liên hợp quốc giữ vai trò trọng yếu trong việc duy trì hòa bình và an ninh thế giới?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tòa án Công lí Quốc tế"}, {"id": "b", "text": "Hội đồng Bảo an"}, {"id": "c", "text": "Đại hội đồng"}], "correctOptionId": "b", "explanation": "Hội đồng Bảo an là cơ quan duy nhất của Liên hợp quốc có thẩm quyền ra các quyết định mang tính ràng buộc pháp lí về duy trì hòa bình và an ninh."}, {"id": "history-12-asean-integration-q1", "prompt": "Hiệp hội các quốc gia Đông Nam Á (ASEAN) được thành lập vào ngày tháng năm nào và tại đâu?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngày 20/9/1977 tại New York (Mĩ)"}, {"id": "b", "text": "Ngày 8/8/1967 tại Bangkok (Thái Lan)"}, {"id": "c", "text": "Ngày 2/9/1945 tại Hà Nội (Việt Nam)"}], "correctOptionId": "b", "explanation": "Tuyên bố Bangkok ngày 8/8/1967 do đại diện 5 nước sáng lập kí kết chính thức khai sinh tổ chức ASEAN."}, {"id": "history-12-asean-integration-q2", "prompt": "Việt Nam chính thức trở thành thành viên thứ 7 của ASEAN vào thời điểm nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ngày 28/7/1995"}, {"id": "b", "text": "Ngày 30/4/1975"}, {"id": "c", "text": "Ngày 31/12/2015"}], "correctOptionId": "a", "explanation": "Ngày 28/7/1995, tại Hội nghị Bộ trưởng Ngoại giao ASEAN lần thứ 28 ở Brunei, Việt Nam chính thức kết nạp làm thành viên thứ 7."}, {"id": "history-12-cold-war-end-multipolar-q1", "prompt": "Sự kiện lịch sử nào đánh dấu sự sụp đổ hoàn toàn của trật tự thế giới hai cực Ianta?", "difficulty": "EASY", "options": [{"id": "a", "text": "Sự sụp đổ và tan rã của Liên bang Xô viết vào tháng 12/1991"}, {"id": "b", "text": "Hiệp định đình chiến tại bán đảo Triều Tiên năm 1953"}, {"id": "c", "text": "Sự thành lập khối liên minh quân sự NATO năm 1949"}], "correctOptionId": "a", "explanation": "Khi Liên Xô tan rã cuối năm 1991, một trong hai cực đối đầu không còn tồn tại, trật tự hai cực Ianta chính thức kết thúc."}, {"id": "history-12-cold-war-end-multipolar-q2", "prompt": "Sau khi Chiến tranh Lạnh chấm dứt, xu thế chủ đạo trong quan hệ quốc tế của hầu hết các quốc gia là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tập trung chạy đua vũ trang hạt nhân và chuẩn bị thế chiến mới"}, {"id": "b", "text": "Đóng cửa biên giới hoàn toàn và ngừng mọi quan hệ ngoại giao"}, {"id": "c", "text": "Hòa hoãn, đối thoại và hợp tác phát triển kinh tế làm trọng tâm chiến lược"}], "correctOptionId": "c", "explanation": "Các nước chuyển trọng tâm sang xây dựng sức mạnh quốc gia tổng hợp, lấy phát triển kinh tế làm nền tảng cạnh tranh lành mạnh và đối thoại giải quyết tranh chấp."}, {"id": "history-12-fourth-industrial-revolution-q1", "prompt": "Công nghệ nào sau đây được coi là một trong những trụ cột cốt lõi của cuộc Cách mạng công nghiệp lần thứ tư?", "difficulty": "EASY", "options": [{"id": "a", "text": "Động cơ hơi nước cải tiến của James Watt"}, {"id": "b", "text": "Dây chuyền sản xuất cơ khí hóa chạy bằng sức nước"}, {"id": "c", "text": "Trí tuệ nhân tạo (AI) và Internet vạn vật (IoT)"}], "correctOptionId": "c", "explanation": "Công nghiệp 4.0 dựa trên nền tảng kỹ thuật số với AI, IoT, Big Data kết nối thế giới thực và thế giới ảo."}, {"id": "history-12-fourth-industrial-revolution-q2", "prompt": "Thời cơ lớn nhất mà Cách mạng công nghiệp lần thứ tư mang lại cho các quốc gia đang phát triển như Việt Nam là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chấm dứt hoàn toàn mọi tác động tiêu cực của thiên tai và dịch bệnh"}, {"id": "b", "text": "Khả năng đi tắt đón đầu, chuyển đổi số nhanh để nâng cao năng suất lao động và năng lực cạnh tranh quốc gia"}, {"id": "c", "text": "Loại bỏ hoàn toàn sự cần thiết của giáo dục đại học và đào tạo nghề nghiệp"}], "correctOptionId": "b", "explanation": "Công nghệ số cho phép các nước đi sau tiếp cận tri thức và giải pháp quản trị hiện đại nhanh chóng mà không cần lặp lại toàn bộ các nấc thang công nghiệp hóa truyền thống."}, {"id": "history-12-august-revolution-1945-q1", "prompt": "Ngày 2/9/1945, tại Quảng trường Ba Đình (Hà Nội), sự kiện lịch sử trọng đại nào đã diễn ra?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khởi nghĩa giành chính quyền thắng lợi hoàn toàn tại Sài Gòn"}, {"id": "b", "text": "Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa"}, {"id": "c", "text": "Đại hội Quốc dân Tân Trào thông qua 10 chính sách lớn của Việt Minh"}], "correctOptionId": "b", "explanation": "Bản Tuyên ngôn Độc lập ngày 2/9/1945 tuyên bố trước quốc dân và thế giới quyền tự do, độc lập thiêng liêng của dân tộc Việt Nam."}, {"id": "history-12-august-revolution-1945-q2", "prompt": "Thời cơ lịch sử ''ngàn năm có một'' của Cách mạng tháng Tám năm 1945 xuất hiện khi nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chính phủ phát xít Nhật Bản tuyên bố đầu hàng Đồng minh vô điều kiện (giữa tháng 8/1945)"}, {"id": "b", "text": "Thực dân Pháp bắt đầu quay trở lại nổ súng đánh chiếm Sài Gòn"}, {"id": "c", "text": "Quân đội Tưởng Giới Thạch tiến vào miền Bắc giải giáp quân Nhật"}], "correctOptionId": "a", "explanation": "Nhật đầu hàng Đồng minh khiến quân Nhật ở Đông Dương tê liệt, chính phủ bù nhìn Trần Trọng Kim hoang mang cực độ, tạo thời cơ chín muồi giành chính quyền trước khi quân Đồng minh vào."}, {"id": "history-12-anti-french-resistance-q1", "prompt": "Lời kêu gọi toàn quốc kháng chiến của Chủ tịch Hồ Chí Minh được phát đi vào thời điểm lịch sử nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đêm ngày 19/12/1946"}, {"id": "b", "text": "Ngày 2/9/1945"}, {"id": "c", "text": "Ngày 7/5/1954"}], "correctOptionId": "a", "explanation": "Trước tối hậu thư đòi tước vũ khí của thực dân Pháp tại Hà Nội, Trung ương Đảng và Hồ Chủ tịch đã quyết định phát động toàn quốc kháng chiến đêm 19/12/1946."}, {"id": "history-12-anti-french-resistance-q2", "prompt": "Chiến dịch nào sau đây đã giúp quân đội ta giành được quyền chủ động chiến lược trên chiến trường chính Bắc Bộ?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chiến dịch Việt Bắc thu - đông năm 1947"}, {"id": "b", "text": "Cuộc chiến đấu 60 ngày đêm bảo vệ Thủ đô Hà Nội cuối năm 1946"}, {"id": "c", "text": "Chiến dịch Biên giới thu - đông năm 1950"}], "correctOptionId": "c", "explanation": "Chiến dịch Biên giới 1950 tiêu diệt nhiều sinh lực địch, giải phóng dải biên giới phía Bắc, khai thông đường liên lạc quốc tế và chuyển sang thế chủ động tiến công."}, {"id": "history-12-dien-bien-phu-1954-q1", "prompt": "Chiến dịch lịch sử Điện Biên Phủ năm 1954 toàn thắng vào ngày tháng năm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngày 13/3/1954"}, {"id": "b", "text": "Ngày 21/7/1954"}, {"id": "c", "text": "Ngày 7/5/1954"}], "correctOptionId": "c", "explanation": "Chiều ngày 7/5/1954, lá cờ Quyết chiến Quyết thắng tung bay trên nóc hầm tướng De Castries, chiến dịch Điện Biên Phủ kết thúc thắng lợi rực rỡ."}, {"id": "history-12-dien-bien-phu-1954-q2", "prompt": "Quyết định thay đổi phương châm tác chiến mang tính bước ngoặt quyết định thắng lợi của Đại tướng Võ Nguyên Giáp tại Điện Biên Phủ là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chuyển từ tiến công đường bộ sang đổ bộ đường không"}, {"id": "b", "text": "Chuyển từ phương châm ''đánh nhanh, thắng nhanh'' sang ''đánh chắc, tiến chắc''"}, {"id": "c", "text": "Chuyển từ bao vây chiến hào sang rút lui toàn bộ lực lượng về căn cứ Việt Bắc"}], "correctOptionId": "b", "explanation": "Nhận thấy địch đã tăng cường công sự kiên cố, việc chuyển sang ''đánh chắc, tiến chắc'' bóc dỡ từng cứ điểm bảo đảm chắc thắng cho từng trận đánh."}, {"id": "history-12-tet-offensive-1968-q1", "prompt": "Điểm độc đáo và bất ngờ nhất về mặt không gian tác chiến của cuộc Tổng tiến công Xuân Mậu Thân 1968 là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Đổ bộ tấn công bất ngờ bằng đường biển vào các hòn đảo xa bờ"}, {"id": "b", "text": "Đồng loạt tiến công trực diện vào các đô thị lớn và cơ quan đầu não đối phương"}, {"id": "c", "text": "Chỉ mở các cuộc phục kích nhỏ ở các vùng rừng núi hẻo lánh"}], "correctOptionId": "b", "explanation": "Đòn tiến công diễn ra đúng đêm Giao thừa Tết nhắm thẳng vào các trung tâm đô thị kiên cố nơi đối phương tập trung phòng thủ dày đặc nhất."}, {"id": "history-12-tet-offensive-1968-q2", "prompt": "Hậu quả chính trị - quân sự lớn nhất mà cuộc Tổng tiến công Xuân Mậu Thân 1968 gây ra cho giới cầm quyền Washington là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Làm lung lay ý chí xâm lược của Mĩ, buộc Tổng thống Johnson phải tuyên bố ''phi Mĩ hóa'' chiến tranh và ngồi vào bàn đàm phán Paris"}, {"id": "b", "text": "Khiến quân Mĩ phải kí ngay hiệp định đầu hàng vô điều kiện trong vòng một tuần"}, {"id": "c", "text": "Làm cho toàn bộ lực lượng quân đội Sài Gòn tự nguyện giải thể vũ khí"}], "correctOptionId": "a", "explanation": "Đòn Mậu Thân phá sản hoàn toàn chiến lược Chiến tranh cục bộ, buộc Mĩ phải xuống thang chiến tranh và thừa nhận thất bại quân sự trên bàn đàm phán."}, {"id": "history-12-ho-chi-minh-campaign-1975-q1", "prompt": "Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được kí kết chính thức vào thời gian nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngày 27/1/1973"}, {"id": "b", "text": "Ngày 21/7/1954"}, {"id": "c", "text": "Ngày 30/4/1975"}], "correctOptionId": "a", "explanation": "Hiệp định Paris được kí ngày 27/1/1973 sau thắng lợi oanh liệt của trận ''Điện Biên Phủ trên không'' cuối năm 1972, buộc Mĩ phải rút hết quân viễn chinh."}, {"id": "history-12-ho-chi-minh-campaign-1975-q2", "prompt": "Đòn tiến công mở màn mang tính đột phá chiến lược của cuộc Tổng tiến công mùa Xuân 1975 là trận đánh giải phóng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thành phố Huế và Đà Nẵng"}, {"id": "b", "text": "Căn cứ quân sự Cam Ranh"}, {"id": "c", "text": "Thị xã Buôn Ma Thuột (trong Chiến dịch Tây Nguyên, ngày 10/3/1975)"}], "correctOptionId": "c", "explanation": "Trận Buôn Ma Thuột ngày 10/3/1975 đánh trúng điểm hiểm yếu bất ngờ, làm rung chuyển toàn bộ tuyến phòng thủ Tây Nguyên và dẫn đến sự tan rã của đối phương."}, {"id": "history-12-national-reunification-state-q1", "prompt": "Kì họp thứ nhất Quốc hội khóa VI (tháng 6 - 7/1976) đã đưa ra quyết định trọng đại nào về quốc hiệu?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đặt tên nước là Việt Nam Dân chủ Cộng hòa"}, {"id": "b", "text": "Giữ nguyên hai tên gọi nhà nước riêng biệt ở hai miền"}, {"id": "c", "text": "Đặt tên nước là Cộng hòa Xã hội chủ nghĩa Việt Nam"}], "correctOptionId": "c", "explanation": "Quốc hội khóa VI đã thống nhất thể chế, quyết định quốc hiệu là Cộng hòa Xã hội chủ nghĩa Việt Nam từ ngày 2/7/1976."}, {"id": "history-12-national-reunification-state-q2", "prompt": "Ý nghĩa lịch sử then chốt của việc hoàn thành thống nhất đất nước về mặt nhà nước (1975 - 1976) là gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cho phép đất nước ngay lập tức tham gia vào tất cả các hiệp định thương mại tự do"}, {"id": "b", "text": "Tạo cơ sở pháp lí và sức mạnh tổng hợp của toàn dân tộc để xây dựng, phát triển kinh tế và bảo vệ vững chắc Tổ quốc"}, {"id": "c", "text": "Chấm dứt hoàn toàn mọi khó khăn về kinh tế - xã hội thời hậu chiến"}], "correctOptionId": "b", "explanation": "Thống nhất nhà nước tạo nên sự đồng bộ về thể chế, luật pháp, chính quyền từ trung ương đến địa phương để huy động mọi nguồn lực kiến thiết đất nước."}, {"id": "history-12-doi-moi-1986-q1", "prompt": "Đại hội đại biểu toàn quốc lần thứ VI của Đảng Cộng sản Việt Nam họp vào tháng 12/1986 có ý nghĩa lịch sử gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tuyên bố xóa bỏ hoàn toàn nền kinh tế thị trường để chuyển sang kinh tế thuần nông"}, {"id": "b", "text": "Khởi xướng và đề ra đường lối Đổi mới toàn diện đất nước"}, {"id": "c", "text": "Quyết định phát động cuộc kháng chiến toàn quốc chống Mĩ cứu nước"}], "correctOptionId": "b", "explanation": "Đại hội VI (12/1986) nhìn thẳng vào sự thật, đánh dấu bước ngoặt lịch sử mở đường cho công cuộc Đổi mới đất nước."}, {"id": "history-12-doi-moi-1986-q2", "prompt": "Trọng tâm của đường lối Đổi mới do Đại hội VI đề ra bắt đầu từ lĩnh vực nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đổi mới về kinh tế"}, {"id": "b", "text": "Đổi mới về chính trị"}, {"id": "c", "text": "Đổi mới về quốc phòng"}], "correctOptionId": "a", "explanation": "Đảng xác định đổi mới kinh tế là trọng tâm, kết hợp từng bước đổi mới chính trị vững chắc nhằm giải quyết khủng hoảng đời sống nhân dân trước tiên."}, {"id": "history-12-vietnam-international-integration-q1", "prompt": "Năm 1995 ghi dấu ấn lịch sử nổi bật nào trong tiến trình hội nhập quốc tế của Việt Nam?", "difficulty": "EASY", "options": [{"id": "a", "text": "Bình thường hóa quan hệ ngoại giao với Hoa Kỳ và chính thức gia nhập ASEAN"}, {"id": "b", "text": "Gia nhập Tổ chức Thương mại Thế giới (WTO)"}, {"id": "c", "text": "Kí kết Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP)"}], "correctOptionId": "a", "explanation": "Tháng 7/1995 là dấu mốc lịch sử khi Việt Nam và Mĩ bình thường hóa quan hệ ngoại giao (11/7) và Việt Nam trở thành thành viên ASEAN (28/7)."}, {"id": "history-12-vietnam-international-integration-q2", "prompt": "Việt Nam chính thức trở thành thành viên thứ 150 của Tổ chức Thương mại Thế giới (WTO) vào năm nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Năm 1995"}, {"id": "b", "text": "Năm 1986"}, {"id": "c", "text": "Năm 2007"}], "correctOptionId": "c", "explanation": "Tháng 1/2007, Việt Nam chính thức trở thành thành viên WTO, đánh dấu bước hội nhập sâu rộng vào sân chơi kinh tế toàn cầu."}, {"id": "history-12-east-sea-sovereignty-q1", "prompt": "Tổ chức nào trong lịch sử phong kiến Việt Nam được các chúa Nguyễn và triều Nguyễn lập ra để thực thi chủ quyền hàng năm tại Hoàng Sa và Trường Sa?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đoàn tàu buôn phương Tây"}, {"id": "b", "text": "Vạn chài ven sông Hồng"}, {"id": "c", "text": "Hải đội Hoàng Sa (và Đội Bắc Hải)"}], "correctOptionId": "c", "explanation": "Hải đội Hoàng Sa được thành lập từ thời chúa Nguyễn có nhiệm vụ ra hai quần đảo đo đạc thủy trình, cắm mốc chủ quyền, thu lượm hải vật và cứu hộ tàu thuyền."}, {"id": "history-12-east-sea-sovereignty-q2", "prompt": "Văn bản pháp lí quốc tế quan trọng nhất hiện nay quy định chế độ pháp lí của các vùng biển và quyền của các quốc gia ven biển là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hiến chương Liên minh châu Âu"}, {"id": "b", "text": "Công ước Liên hợp quốc về Luật Biển năm 1982 (UNCLOS 1982)"}, {"id": "c", "text": "Tuyên bố Cairo năm 1943"}], "correctOptionId": "b", "explanation": "UNCLOS 1982 được coi là ''Hiến pháp của đại dương'', xác lập rõ ràng phạm vi nội thủy, lãnh hải, vùng đặc quyền kinh tế 200 hải lí và thềm lục địa."}, {"id": "history-12-ho-chi-minh-national-liberation-q1", "prompt": "Sự kiện lịch sử nào đánh dấu bước ngoặt quyết định đưa Nguyễn Ái Quốc từ người yêu nước trở thành chiến sĩ cộng sản?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tham gia thành lập Hội Liên hiệp thuộc địa tại Paris năm 1921"}, {"id": "b", "text": "Đọc Luận cương của Lênin về vấn đề dân tộc và thuộc địa (1920) và bỏ phiếu tán thành Quốc tế Cộng sản tại Đại hội Tours"}, {"id": "c", "text": "Rời bến cảng Nhà Rồng sang phương Tây tìm đường cứu nước năm 1911"}], "correctOptionId": "b", "explanation": "Tháng 7/1920, khi đọc Sơ thảo Luận cương của Lênin, Nguyễn Ái Quốc đã tìm thấy con đường giải phóng cho dân tộc và bỏ phiếu tán thành Quốc tế Cộng sản vào tháng 12/1920."}, {"id": "history-12-ho-chi-minh-national-liberation-q2", "prompt": "Tác phẩm lý luận chính trị xuất sắc do Nguyễn Ái Quốc biên soạn năm 1927 dùng làm tài liệu huấn luyện cán bộ cách mạng tiền phong là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đường Kách mệnh"}, {"id": "b", "text": "Bản án chế độ thực dân Pháp"}, {"id": "c", "text": "Tuyên ngôn Độc lập"}], "correctOptionId": "a", "explanation": "Cuốn sách ''Đường Kách mệnh'' (1927) tập hợp các bài giảng của Nguyễn Ái Quốc tại Quảng Châu, chuẩn bị nền tảng tư tưởng và chính trị cho sự ra đời của Đảng."}]'::jsonb,'[]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-cold-war-origins',1,'LESSON','Trật tự thế giới hai cực Ianta và nguồn gốc Chiến tranh Lạnh','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Hội nghị Ianta (2/1945) với sự tham gia của ba cường quốc (Liên Xô, Mĩ, Anh) đã phân chia phạm vi ảnh hưởng ở châu Âu và châu Á, hình thành trật tự hai cực Ianta. Chiến tranh Lạnh khởi đầu từ Thông điệp của Tổng thống Mĩ Truman (3/1947), Kế hoạch Marshall, và sự xác lập hai khối quân sự đối đầu: NATO (1949) và Hiệp ước Warsaw (1955)."]'::jsonb,'["Sự phân chia nước Đức thành Cộng hòa Liên bang Đức (Tây Đức) và Cộng hòa Dân chủ Đức (Đông Đức) năm 1949 là biểu hiện cụ thể của trật tự hai cực Ianta tại châu Âu."]'::jsonb,'[{"id": "history-12-cold-war-origins-q1", "prompt": "Hội nghị Ianta diễn ra vào tháng 2/1945 có sự tham gia của nguyên thủ ba cường quốc nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Liên Xô, Mĩ và Anh"}, {"id": "b", "text": "Mĩ, Anh và Pháp"}, {"id": "c", "text": "Liên Xô, Trung Quốc và Mĩ"}], "correctOptionId": "a", "explanation": "Hội nghị Ianta quy tụ ba nguyên thủ: Stalin (Liên Xô), Roosevelt (Mĩ) và Churchill (Anh) để thỏa thuận phân chia phạm vi ảnh hưởng sau Thế chiến II."}, {"id": "history-12-cold-war-origins-q2", "prompt": "Sự kiện nào sau đây đánh dấu sự khởi đầu chính thức của cuộc Chiến tranh Lạnh giữa hai phe?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Sự ra đời của tổ chức Hiệp ước Bắc Đại Tây Dương (NATO) năm 1949"}, {"id": "b", "text": "Sự thành lập khối Hiệp ước Warsaw tại Đông Âu năm 1955"}, {"id": "c", "text": "Thông điệp của Tổng thống Mĩ Truman tại Quốc hội Mĩ (tháng 3/1947)"}], "correctOptionId": "c", "explanation": "Tháng 3/1947, Thông điệp Truman khẳng định sự tồn tại của Liên Xô là mối đe dọa và viện trợ cho Hy Lạp, Thổ Nhĩ Kỳ, mở đầu Chiến tranh Lạnh."}, {"id": "history-12-cold-war-origins-q3", "prompt": "Đặc điểm nổi bật nhất chi phối quan hệ quốc tế trong phần lớn nửa sau thế kỉ XX (1945 - 1991) là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Sự thống trị tuyệt đối của một siêu cường duy nhất trên toàn bộ thế giới"}, {"id": "b", "text": "Tình trạng đối đầu căng thẳng giữa hai khối tư bản chủ nghĩa và xã hội chủ nghĩa do Mĩ và Liên Xô đứng đầu"}, {"id": "c", "text": "Sự hợp tác kinh tế toàn diện và không có xung đột quân sự cục bộ nào xảy ra"}], "correctOptionId": "b", "explanation": "Cục diện hai cực hai phe do Mĩ và Liên Xô đứng đầu đã bao trùm và chi phối hầu hết các mối quan hệ chính trị, quân sự toàn cầu trong thời kì này."}]'::jsonb,'["history-12-cold-war-origins"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-united-nations',2,'LESSON','Liên hợp quốc: Mục tiêu, nguyên tắc và vai trò giữ gìn hòa bình','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Hiến chương Liên hợp quốc có hiệu lực ngày 24/10/1945 xác định mục tiêu duy trì hòa bình, an ninh quốc tế và thúc đẩy hợp tác hữu nghị giữa các dân tộc. Nguyên tắc hoạt động trọng yếu gồm: bình đẳng chủ quyền, không can thiệp vào công việc nội bộ, giải quyết tranh chấp bằng biện pháp hòa bình, và sự nhất trí giữa 5 nước ủy viên thường trực Hội đồng Bảo an (Mĩ, Nga, Anh, Pháp, Trung Quốc)."]'::jsonb,'["Việt Nam chính thức gia nhập Liên hợp quốc vào ngày 20/9/1977 và tích cực tham gia lực lượng gìn giữ hòa bình tại Nam Sudan, Cộng hòa Trung Phi."]'::jsonb,'[{"id": "history-12-united-nations-q1", "prompt": "Mục tiêu bao trùm hàng đầu của tổ chức Liên hợp quốc được ghi nhận trong Hiến chương năm 1945 là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Thành lập một chính phủ liên bang chung cho toàn cầu"}, {"id": "b", "text": "Xóa bỏ hoàn toàn mọi đường biên giới quốc gia giữa các nước"}, {"id": "c", "text": "Duy trì hòa bình và an ninh quốc tế"}], "correctOptionId": "c", "explanation": "Điều 1 Hiến chương Liên hợp quốc xác định mục tiêu cao nhất là duy trì hòa bình và an ninh thế giới, ngăn ngừa chiến tranh tái diễn."}, {"id": "history-12-united-nations-q2", "prompt": "Cơ quan nào của Liên hợp quốc giữ vai trò trọng yếu trong việc duy trì hòa bình và an ninh thế giới?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tòa án Công lí Quốc tế"}, {"id": "b", "text": "Hội đồng Bảo an"}, {"id": "c", "text": "Đại hội đồng"}], "correctOptionId": "b", "explanation": "Hội đồng Bảo an là cơ quan duy nhất của Liên hợp quốc có thẩm quyền ra các quyết định mang tính ràng buộc pháp lí về duy trì hòa bình và an ninh."}, {"id": "history-12-united-nations-q3", "prompt": "Nguyên tắc ''sự nhất trí của 5 nước Ủy viên thường trực Hội đồng Bảo an Liên hợp quốc'' (quyền phủ quyết) có ý nghĩa thực tiễn là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Ngăn chặn một quyết định quân sự hoặc trừng phạt lớn khi chưa có sự đồng thuận của các cường quốc hạt nhân chủ chốt"}, {"id": "b", "text": "Bắt buộc tất cả các nước thành viên Đại hội đồng phải có ý kiến giống nhau"}, {"id": "c", "text": "Cho phép bất kì quốc gia nào cũng có quyền đình chỉ hoạt động của Liên hợp quốc"}], "correctOptionId": "a", "explanation": "Quy tắc veto của 5 cường quốc (Mĩ, Nga, Anh, Pháp, Trung Quốc) buộc các siêu cường phải thỏa hiệp, tránh nguy cơ nổ ra chiến tranh hạt nhân trực tiếp giữa các nước lớn."}]'::jsonb,'["history-12-united-nations"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-asean-integration',3,'LESSON','Quá trình hình thành và phát triển của ASEAN','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Hiệp hội các quốc gia Đông Nam Á (ASEAN) thành lập ngày 8/8/1967 tại Bangkok bởi 5 nước (Indonesia, Malaysia, Philippines, Singapore, Thái Lan). Hiệp ước Bali (1976) xác định nguyên tắc tôn trọng độc lập, chủ quyền, không can thiệp nội bộ và giải quyết hòa bình tranh chấp. Quá trình mở rộng: Brunei (1984), Việt Nam (28/7/1995), Lào và Myanmar (1997), Campuchia (1999). Ngày 31/12/2015, Cộng đồng ASEAN chính thức thành lập với 3 trụ cột: APSC, AEC, ASCC."]'::jsonb,'["Việt Nam đảm nhiệm thành công vai trò Chủ tịch ASEAN vào các năm 1998, 2010 và 2020, đóng góp tích cực vào sự đoàn kết và vị thế quốc tế của khối."]'::jsonb,'[{"id": "history-12-asean-integration-q1", "prompt": "Hiệp hội các quốc gia Đông Nam Á (ASEAN) được thành lập vào ngày tháng năm nào và tại đâu?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngày 20/9/1977 tại New York (Mĩ)"}, {"id": "b", "text": "Ngày 8/8/1967 tại Bangkok (Thái Lan)"}, {"id": "c", "text": "Ngày 2/9/1945 tại Hà Nội (Việt Nam)"}], "correctOptionId": "b", "explanation": "Tuyên bố Bangkok ngày 8/8/1967 do đại diện 5 nước sáng lập kí kết chính thức khai sinh tổ chức ASEAN."}, {"id": "history-12-asean-integration-q2", "prompt": "Việt Nam chính thức trở thành thành viên thứ 7 của ASEAN vào thời điểm nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ngày 28/7/1995"}, {"id": "b", "text": "Ngày 30/4/1975"}, {"id": "c", "text": "Ngày 31/12/2015"}], "correctOptionId": "a", "explanation": "Ngày 28/7/1995, tại Hội nghị Bộ trưởng Ngoại giao ASEAN lần thứ 28 ở Brunei, Việt Nam chính thức kết nạp làm thành viên thứ 7."}, {"id": "history-12-asean-integration-q3", "prompt": "Cộng đồng ASEAN được chính thức thành lập vào ngày 31/12/2015 dựa trên ba trụ cột vững chắc nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Cộng đồng Quốc phòng chung, Đồng tiền chung và Tòa án tư pháp chung"}, {"id": "b", "text": "Liên minh Quân sự Đông Nam Á, Thị trường vốn và Khối dầu khí tự do"}, {"id": "c", "text": "Cộng đồng Chính trị - An ninh (APSC), Cộng đồng Kinh tế (AEC) và Cộng đồng Văn hóa - Xã hội (ASCC)"}], "correctOptionId": "c", "explanation": "Ba trụ cột APSC, AEC và ASCC tạo nên khuôn khổ hợp tác toàn diện, gắn kết chặt chẽ về chính trị, kinh tế và giao lưu văn hóa giữa các dân tộc."}]'::jsonb,'["history-12-asean-integration"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-cold-war-end-multipolar',4,'LESSON','Sự chấm dứt Chiến tranh Lạnh và xu thế trật tự thế giới đa cực','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Tháng 12/1989, tại cuộc gặp cấp cao ở đảo Malta, hai nhà lãnh đạo Mĩ (G. Bush) và Liên Xô (M. Gorbachev) cùng tuyên bố chấm dứt Chiến tranh Lạnh. Trật tự hai cực Ianta sụp đổ hoàn toàn sau khi Liên Xô tan rã (12/1991). Thế giới bước vào thời kì quá độ hướng tới trật tự đa cực, nhiều trung tâm (Mĩ, Trung Quốc, EU, Nga, Nhật Bản, Ấn Độ), hòa hoãn và lấy phát triển kinh tế làm trọng tâm."]'::jsonb,'["Các diễn đàn hợp tác đa phương như G20, BRICS, APEC phản ánh rõ nét sự phân bổ quyền lực đa cực, không còn một siêu cường đơn lẻ nào có thể chi phối toàn diện nền kinh tế toàn cầu."]'::jsonb,'[{"id": "history-12-cold-war-end-multipolar-q1", "prompt": "Sự kiện lịch sử nào đánh dấu sự sụp đổ hoàn toàn của trật tự thế giới hai cực Ianta?", "difficulty": "EASY", "options": [{"id": "a", "text": "Sự sụp đổ và tan rã của Liên bang Xô viết vào tháng 12/1991"}, {"id": "b", "text": "Hiệp định đình chiến tại bán đảo Triều Tiên năm 1953"}, {"id": "c", "text": "Sự thành lập khối liên minh quân sự NATO năm 1949"}], "correctOptionId": "a", "explanation": "Khi Liên Xô tan rã cuối năm 1991, một trong hai cực đối đầu không còn tồn tại, trật tự hai cực Ianta chính thức kết thúc."}, {"id": "history-12-cold-war-end-multipolar-q2", "prompt": "Sau khi Chiến tranh Lạnh chấm dứt, xu thế chủ đạo trong quan hệ quốc tế của hầu hết các quốc gia là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tập trung chạy đua vũ trang hạt nhân và chuẩn bị thế chiến mới"}, {"id": "b", "text": "Đóng cửa biên giới hoàn toàn và ngừng mọi quan hệ ngoại giao"}, {"id": "c", "text": "Hòa hoãn, đối thoại và hợp tác phát triển kinh tế làm trọng tâm chiến lược"}], "correctOptionId": "c", "explanation": "Các nước chuyển trọng tâm sang xây dựng sức mạnh quốc gia tổng hợp, lấy phát triển kinh tế làm nền tảng cạnh tranh lành mạnh và đối thoại giải quyết tranh chấp."}, {"id": "history-12-cold-war-end-multipolar-q3", "prompt": "Thuật ngữ ''trật tự thế giới đa cực'' phản ánh thực trạng quan hệ quốc tế đương đại như thế nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Tất cả các quốc gia trên thế giới đều có quy mô kinh tế và quân sự hoàn toàn ngang bằng nhau"}, {"id": "b", "text": "Quyền lực và ảnh hưởng quốc tế phân bổ giữa nhiều trung tâm kinh tế, chính trị lớn thay vì tập trung vào một hoặc hai siêu cường"}, {"id": "c", "text": "Thế giới bị chia rẽ thành vô số các liên minh quân sự đối đầu vũ trang trực tiếp"}], "correctOptionId": "b", "explanation": "Trật tự đa cực thể hiện sự trỗi dậy của nhiều cường quốc và trung tâm khu vực (Mĩ, EU, Trung Quốc, Nga, Ấn Độ, Nhật Bản) cùng tham gia định hình luật chơi quốc tế."}]'::jsonb,'["history-12-cold-war-end-multipolar"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-fourth-industrial-revolution',5,'LESSON','Cách mạng công nghiệp lần thứ tư và tác động xã hội','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Cách mạng công nghiệp lần thứ tư (Công nghiệp 4.0) bùng nổ từ những năm đầu thế kỉ XXI, dựa trên sự kết hợp giữa thế giới thực và số qua các công nghệ đột phá: Trí tuệ nhân tạo (AI), Internet vạn vật (IoT), Dữ liệu lớn (Big Data), Điện toán đám mây và Công nghệ sinh học. Tác động sâu sắc: đột phá năng suất, chuyển dịch mô hình việc làm, thúc đẩy chính phủ số, nhưng đặt ra thách thức lớn về an ninh mạng, bảo vệ dữ liệu cá nhân và bất bình đẳng số."]'::jsonb,'["Việc ứng dụng cảm biến IoT và phân tích dữ liệu AI trong nông nghiệp thông minh tại Việt Nam giúp theo dõi độ ẩm, sâu bệnh theo thời gian thực và tiết kiệm tới 40% nước tưới."]'::jsonb,'[{"id": "history-12-fourth-industrial-revolution-q1", "prompt": "Công nghệ nào sau đây được coi là một trong những trụ cột cốt lõi của cuộc Cách mạng công nghiệp lần thứ tư?", "difficulty": "EASY", "options": [{"id": "a", "text": "Động cơ hơi nước cải tiến của James Watt"}, {"id": "b", "text": "Dây chuyền sản xuất cơ khí hóa chạy bằng sức nước"}, {"id": "c", "text": "Trí tuệ nhân tạo (AI) và Internet vạn vật (IoT)"}], "correctOptionId": "c", "explanation": "Công nghiệp 4.0 dựa trên nền tảng kỹ thuật số với AI, IoT, Big Data kết nối thế giới thực và thế giới ảo."}, {"id": "history-12-fourth-industrial-revolution-q2", "prompt": "Thời cơ lớn nhất mà Cách mạng công nghiệp lần thứ tư mang lại cho các quốc gia đang phát triển như Việt Nam là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chấm dứt hoàn toàn mọi tác động tiêu cực của thiên tai và dịch bệnh"}, {"id": "b", "text": "Khả năng đi tắt đón đầu, chuyển đổi số nhanh để nâng cao năng suất lao động và năng lực cạnh tranh quốc gia"}, {"id": "c", "text": "Loại bỏ hoàn toàn sự cần thiết của giáo dục đại học và đào tạo nghề nghiệp"}], "correctOptionId": "b", "explanation": "Công nghệ số cho phép các nước đi sau tiếp cận tri thức và giải pháp quản trị hiện đại nhanh chóng mà không cần lặp lại toàn bộ các nấc thang công nghiệp hóa truyền thống."}, {"id": "history-12-fourth-industrial-revolution-q3", "prompt": "Một trong những thách thức an ninh phi truyền thống gay gắt nhất phát sinh từ quá trình chuyển đổi số và phát triển Internet toàn cầu là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Tội phạm công nghệ cao, tấn công an ninh mạng và rò rỉ dữ liệu thông tin cá nhân"}, {"id": "b", "text": "Sự thiếu hụt nguồn tài nguyên than đá cho các nhà máy cơ khí cổ điển"}, {"id": "c", "text": "Sự suy giảm đột ngột của các phương tiện truyền thông vô tuyến"}], "correctOptionId": "a", "explanation": "Không gian mạng mở rộng làm gia tăng nguy cơ tấn công hạ tầng trọng yếu, đánh cắp dữ liệu tài chính và phát tán tin giả đe dọa an ninh xã hội."}]'::jsonb,'["history-12-fourth-industrial-revolution"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-review-1',6,'FIVE_LESSON_REVIEW','Ôn tập 1','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "history-12-cold-war-origins-q1", "prompt": "Hội nghị Ianta diễn ra vào tháng 2/1945 có sự tham gia của nguyên thủ ba cường quốc nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Liên Xô, Mĩ và Anh"}, {"id": "b", "text": "Mĩ, Anh và Pháp"}, {"id": "c", "text": "Liên Xô, Trung Quốc và Mĩ"}], "correctOptionId": "a", "explanation": "Hội nghị Ianta quy tụ ba nguyên thủ: Stalin (Liên Xô), Roosevelt (Mĩ) và Churchill (Anh) để thỏa thuận phân chia phạm vi ảnh hưởng sau Thế chiến II."}, {"id": "history-12-cold-war-origins-q2", "prompt": "Sự kiện nào sau đây đánh dấu sự khởi đầu chính thức của cuộc Chiến tranh Lạnh giữa hai phe?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Sự ra đời của tổ chức Hiệp ước Bắc Đại Tây Dương (NATO) năm 1949"}, {"id": "b", "text": "Sự thành lập khối Hiệp ước Warsaw tại Đông Âu năm 1955"}, {"id": "c", "text": "Thông điệp của Tổng thống Mĩ Truman tại Quốc hội Mĩ (tháng 3/1947)"}], "correctOptionId": "c", "explanation": "Tháng 3/1947, Thông điệp Truman khẳng định sự tồn tại của Liên Xô là mối đe dọa và viện trợ cho Hy Lạp, Thổ Nhĩ Kỳ, mở đầu Chiến tranh Lạnh."}, {"id": "history-12-united-nations-q1", "prompt": "Mục tiêu bao trùm hàng đầu của tổ chức Liên hợp quốc được ghi nhận trong Hiến chương năm 1945 là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Thành lập một chính phủ liên bang chung cho toàn cầu"}, {"id": "b", "text": "Xóa bỏ hoàn toàn mọi đường biên giới quốc gia giữa các nước"}, {"id": "c", "text": "Duy trì hòa bình và an ninh quốc tế"}], "correctOptionId": "c", "explanation": "Điều 1 Hiến chương Liên hợp quốc xác định mục tiêu cao nhất là duy trì hòa bình và an ninh thế giới, ngăn ngừa chiến tranh tái diễn."}, {"id": "history-12-united-nations-q2", "prompt": "Cơ quan nào của Liên hợp quốc giữ vai trò trọng yếu trong việc duy trì hòa bình và an ninh thế giới?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tòa án Công lí Quốc tế"}, {"id": "b", "text": "Hội đồng Bảo an"}, {"id": "c", "text": "Đại hội đồng"}], "correctOptionId": "b", "explanation": "Hội đồng Bảo an là cơ quan duy nhất của Liên hợp quốc có thẩm quyền ra các quyết định mang tính ràng buộc pháp lí về duy trì hòa bình và an ninh."}, {"id": "history-12-asean-integration-q1", "prompt": "Hiệp hội các quốc gia Đông Nam Á (ASEAN) được thành lập vào ngày tháng năm nào và tại đâu?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngày 20/9/1977 tại New York (Mĩ)"}, {"id": "b", "text": "Ngày 8/8/1967 tại Bangkok (Thái Lan)"}, {"id": "c", "text": "Ngày 2/9/1945 tại Hà Nội (Việt Nam)"}], "correctOptionId": "b", "explanation": "Tuyên bố Bangkok ngày 8/8/1967 do đại diện 5 nước sáng lập kí kết chính thức khai sinh tổ chức ASEAN."}, {"id": "history-12-asean-integration-q2", "prompt": "Việt Nam chính thức trở thành thành viên thứ 7 của ASEAN vào thời điểm nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ngày 28/7/1995"}, {"id": "b", "text": "Ngày 30/4/1975"}, {"id": "c", "text": "Ngày 31/12/2015"}], "correctOptionId": "a", "explanation": "Ngày 28/7/1995, tại Hội nghị Bộ trưởng Ngoại giao ASEAN lần thứ 28 ở Brunei, Việt Nam chính thức kết nạp làm thành viên thứ 7."}, {"id": "history-12-cold-war-end-multipolar-q1", "prompt": "Sự kiện lịch sử nào đánh dấu sự sụp đổ hoàn toàn của trật tự thế giới hai cực Ianta?", "difficulty": "EASY", "options": [{"id": "a", "text": "Sự sụp đổ và tan rã của Liên bang Xô viết vào tháng 12/1991"}, {"id": "b", "text": "Hiệp định đình chiến tại bán đảo Triều Tiên năm 1953"}, {"id": "c", "text": "Sự thành lập khối liên minh quân sự NATO năm 1949"}], "correctOptionId": "a", "explanation": "Khi Liên Xô tan rã cuối năm 1991, một trong hai cực đối đầu không còn tồn tại, trật tự hai cực Ianta chính thức kết thúc."}, {"id": "history-12-cold-war-end-multipolar-q2", "prompt": "Sau khi Chiến tranh Lạnh chấm dứt, xu thế chủ đạo trong quan hệ quốc tế của hầu hết các quốc gia là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tập trung chạy đua vũ trang hạt nhân và chuẩn bị thế chiến mới"}, {"id": "b", "text": "Đóng cửa biên giới hoàn toàn và ngừng mọi quan hệ ngoại giao"}, {"id": "c", "text": "Hòa hoãn, đối thoại và hợp tác phát triển kinh tế làm trọng tâm chiến lược"}], "correctOptionId": "c", "explanation": "Các nước chuyển trọng tâm sang xây dựng sức mạnh quốc gia tổng hợp, lấy phát triển kinh tế làm nền tảng cạnh tranh lành mạnh và đối thoại giải quyết tranh chấp."}, {"id": "history-12-fourth-industrial-revolution-q1", "prompt": "Công nghệ nào sau đây được coi là một trong những trụ cột cốt lõi của cuộc Cách mạng công nghiệp lần thứ tư?", "difficulty": "EASY", "options": [{"id": "a", "text": "Động cơ hơi nước cải tiến của James Watt"}, {"id": "b", "text": "Dây chuyền sản xuất cơ khí hóa chạy bằng sức nước"}, {"id": "c", "text": "Trí tuệ nhân tạo (AI) và Internet vạn vật (IoT)"}], "correctOptionId": "c", "explanation": "Công nghiệp 4.0 dựa trên nền tảng kỹ thuật số với AI, IoT, Big Data kết nối thế giới thực và thế giới ảo."}, {"id": "history-12-fourth-industrial-revolution-q2", "prompt": "Thời cơ lớn nhất mà Cách mạng công nghiệp lần thứ tư mang lại cho các quốc gia đang phát triển như Việt Nam là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chấm dứt hoàn toàn mọi tác động tiêu cực của thiên tai và dịch bệnh"}, {"id": "b", "text": "Khả năng đi tắt đón đầu, chuyển đổi số nhanh để nâng cao năng suất lao động và năng lực cạnh tranh quốc gia"}, {"id": "c", "text": "Loại bỏ hoàn toàn sự cần thiết của giáo dục đại học và đào tạo nghề nghiệp"}], "correctOptionId": "b", "explanation": "Công nghệ số cho phép các nước đi sau tiếp cận tri thức và giải pháp quản trị hiện đại nhanh chóng mà không cần lặp lại toàn bộ các nấc thang công nghiệp hóa truyền thống."}]'::jsonb,'["history-12-cold-war-origins", "history-12-united-nations", "history-12-asean-integration", "history-12-cold-war-end-multipolar", "history-12-fourth-industrial-revolution"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-august-revolution-1945',7,'LESSON','Cách mạng tháng Tám năm 1945 và sự ra đời của nước Việt Nam Dân chủ Cộng hòa','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Giữa tháng 8/1945, phát xít Nhật đầu hàng Đồng minh, thời cơ ngàn năm có một xuất hiện. Hội nghị toàn quốc của Đảng họp tại Tân Trào (14 - 15/8) và Đại hội Quốc dân Tân Trào (16 - 17/8) quyết định Tổng khởi nghĩa. Nhân dân cả nước vùng lên giành chính quyền thắng lợi ở Hà Nội (19/8), Huế (23/8), Sài Gòn (25/8). Ngày 2/9/1945, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình, khai sinh nước Việt Nam Dân chủ Cộng hòa."]'::jsonb,'["Vua Bảo Đại thoái vị ngày 30/8/1945 tại Huế với lời tuyên bố nổi tiếng: ''Thà làm dân một nước độc lập hơn làm vua một nước nô lệ'', chấm dứt hoàn toàn chế độ phong kiến Việt Nam."]'::jsonb,'[{"id": "history-12-august-revolution-1945-q1", "prompt": "Ngày 2/9/1945, tại Quảng trường Ba Đình (Hà Nội), sự kiện lịch sử trọng đại nào đã diễn ra?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khởi nghĩa giành chính quyền thắng lợi hoàn toàn tại Sài Gòn"}, {"id": "b", "text": "Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa"}, {"id": "c", "text": "Đại hội Quốc dân Tân Trào thông qua 10 chính sách lớn của Việt Minh"}], "correctOptionId": "b", "explanation": "Bản Tuyên ngôn Độc lập ngày 2/9/1945 tuyên bố trước quốc dân và thế giới quyền tự do, độc lập thiêng liêng của dân tộc Việt Nam."}, {"id": "history-12-august-revolution-1945-q2", "prompt": "Thời cơ lịch sử ''ngàn năm có một'' của Cách mạng tháng Tám năm 1945 xuất hiện khi nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chính phủ phát xít Nhật Bản tuyên bố đầu hàng Đồng minh vô điều kiện (giữa tháng 8/1945)"}, {"id": "b", "text": "Thực dân Pháp bắt đầu quay trở lại nổ súng đánh chiếm Sài Gòn"}, {"id": "c", "text": "Quân đội Tưởng Giới Thạch tiến vào miền Bắc giải giáp quân Nhật"}], "correctOptionId": "a", "explanation": "Nhật đầu hàng Đồng minh khiến quân Nhật ở Đông Dương tê liệt, chính phủ bù nhìn Trần Trọng Kim hoang mang cực độ, tạo thời cơ chín muồi giành chính quyền trước khi quân Đồng minh vào."}, {"id": "history-12-august-revolution-1945-q3", "prompt": "Bài học kinh nghiệm quý báu nhất về nghệ thuật chỉ đạo khởi nghĩa của Đảng trong Cách mạng tháng Tám năm 1945 là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chờ đợi sự viện trợ quân sự trực tiếp của các cường quốc Đồng minh bên ngoài"}, {"id": "b", "text": "Chỉ tập trung khởi nghĩa ở vùng rừng núi hiểm trở và bỏ qua các đô thị lớn"}, {"id": "c", "text": "Nắm bắt chính xác thời cơ lịch sử, kết hợp linh hoạt lực lượng chính trị quần chúng với lực lượng vũ trang"}], "correctOptionId": "c", "explanation": "Đảng đã dự đoán đúng thời cơ, chớp lấy khoảng trống quyền lực trong vòng 15 ngày để huy động sức mạnh toàn dân tổng khởi nghĩa đồng loạt thành công trên cả nước."}]'::jsonb,'["history-12-august-revolution-1945"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-anti-french-resistance',8,'LESSON','Cuộc kháng chiến toàn quốc chống thực dân Pháp (1946 - 1954)','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Trước hành động bội ước và khiêu khích của thực dân Pháp, đêm 19/12/1946, Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến. Đường lối kháng chiến được xác định: toàn dân, toàn diện, trường kì, tự lực cánh sinh và tranh thủ sự ủng hộ quốc tế. Các chiến dịch tiêu biểu: Việt Bắc thu - đông 1947 (bẻ gãy chiến lược đánh nhanh thắng nhanh của Pháp), Biên giới thu - đông 1950 (giành quyền chủ động chiến lược trên chiến trường chính Bắc Bộ, khai thông biên giới Việt - Trung)."]'::jsonb,'["Trong chiến dịch Biên giới 1950, Chủ tịch Hồ Chí Minh trực tiếp lên đài quan sát chỉ đạo mặt trận Đông Khê, cổ vũ tinh thần chiến đấu quật cường của quân và dân ta."]'::jsonb,'[{"id": "history-12-anti-french-resistance-q1", "prompt": "Lời kêu gọi toàn quốc kháng chiến của Chủ tịch Hồ Chí Minh được phát đi vào thời điểm lịch sử nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đêm ngày 19/12/1946"}, {"id": "b", "text": "Ngày 2/9/1945"}, {"id": "c", "text": "Ngày 7/5/1954"}], "correctOptionId": "a", "explanation": "Trước tối hậu thư đòi tước vũ khí của thực dân Pháp tại Hà Nội, Trung ương Đảng và Hồ Chủ tịch đã quyết định phát động toàn quốc kháng chiến đêm 19/12/1946."}, {"id": "history-12-anti-french-resistance-q2", "prompt": "Chiến dịch nào sau đây đã giúp quân đội ta giành được quyền chủ động chiến lược trên chiến trường chính Bắc Bộ?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chiến dịch Việt Bắc thu - đông năm 1947"}, {"id": "b", "text": "Cuộc chiến đấu 60 ngày đêm bảo vệ Thủ đô Hà Nội cuối năm 1946"}, {"id": "c", "text": "Chiến dịch Biên giới thu - đông năm 1950"}], "correctOptionId": "c", "explanation": "Chiến dịch Biên giới 1950 tiêu diệt nhiều sinh lực địch, giải phóng dải biên giới phía Bắc, khai thông đường liên lạc quốc tế và chuyển sang thế chủ động tiến công."}, {"id": "history-12-anti-french-resistance-q3", "prompt": "Nguyên tắc ''toàn dân, toàn diện, trường kì, tự lực cánh sinh'' trong đường lối kháng chiến chống Pháp thể hiện tư tưởng chiến lược gì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Giao toàn bộ nhiệm vụ đánh giặc cho lực lượng vũ trang chính quy trong các trận đánh đô thị"}, {"id": "b", "text": "Huy động sức mạnh tổng hợp của toàn thể nhân dân trên mọi mặt trận quân sự, chính trị, kinh tế, văn hóa để chiến thắng kẻ thù mạnh hơn về trang bị"}, {"id": "c", "text": "Chỉ dựa hoàn toàn vào sự chi viện vũ khí của nước ngoài để giải quyết nhanh cuộc chiến"}], "correctOptionId": "b", "explanation": "Vì xuất phát điểm ta nghèo và vũ khí thô sơ hơn địch, đường lối kháng chiến toàn dân trường kì nhằm vừa đánh vừa bồi dưỡng sức dân, từng bước chuyển hóa tương quan lực lượng."}]'::jsonb,'["history-12-anti-french-resistance"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-dien-bien-phu-1954',9,'LESSON','Chiến dịch Điện Biên Phủ năm 1954 và Hiệp định Giơ-ne-vơ','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Tập đoàn cứ điểm Điện Biên Phủ gồm 49 cứ điểm chia thành 3 phân khu, được Pháp - Mĩ coi là ''pháo đài bất khả xâm phạm''. Đại tướng Võ Nguyên Giáp đã quyết định chuyển phương châm tác chiến từ ''đánh nhanh, thắng nhanh'' sang ''đánh chắc, tiến chắc''. Sau 56 ngày đêm chiến đấu kiên cường (13/3 - 7/5/1954), ta tiêu diệt hoàn toàn tập đoàn cứ điểm. Thắng lợi dẫn tới việc kí kết Hiệp định Giơ-ne-vơ (21/7/1954), công nhận độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của Việt Nam."]'::jsonb,'["Quyết định kéo pháo vào rồi lại lệnh kéo pháo ra để chuẩn bị trận địa vững chắc của Đại tướng Võ Nguyên Giáp được lịch sử ghi nhận là quyết định khó khăn nhất nhưng sáng suốt nhất trong cuộc đời chỉ huy."]'::jsonb,'[{"id": "history-12-dien-bien-phu-1954-q1", "prompt": "Chiến dịch lịch sử Điện Biên Phủ năm 1954 toàn thắng vào ngày tháng năm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngày 13/3/1954"}, {"id": "b", "text": "Ngày 21/7/1954"}, {"id": "c", "text": "Ngày 7/5/1954"}], "correctOptionId": "c", "explanation": "Chiều ngày 7/5/1954, lá cờ Quyết chiến Quyết thắng tung bay trên nóc hầm tướng De Castries, chiến dịch Điện Biên Phủ kết thúc thắng lợi rực rỡ."}, {"id": "history-12-dien-bien-phu-1954-q2", "prompt": "Quyết định thay đổi phương châm tác chiến mang tính bước ngoặt quyết định thắng lợi của Đại tướng Võ Nguyên Giáp tại Điện Biên Phủ là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chuyển từ tiến công đường bộ sang đổ bộ đường không"}, {"id": "b", "text": "Chuyển từ phương châm ''đánh nhanh, thắng nhanh'' sang ''đánh chắc, tiến chắc''"}, {"id": "c", "text": "Chuyển từ bao vây chiến hào sang rút lui toàn bộ lực lượng về căn cứ Việt Bắc"}], "correctOptionId": "b", "explanation": "Nhận thấy địch đã tăng cường công sự kiên cố, việc chuyển sang ''đánh chắc, tiến chắc'' bóc dỡ từng cứ điểm bảo đảm chắc thắng cho từng trận đánh."}, {"id": "history-12-dien-bien-phu-1954-q3", "prompt": "Nội dung quan trọng hàng đầu của Hiệp định Giơ-ne-vơ năm 1954 về Đông Dương là các nước tham dự hội nghị cam kết:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Tôn trọng các quyền dân tộc cơ bản của Việt Nam, Lào, Campuchia là độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ"}, {"id": "b", "text": "Công nhận sự cai trị lâu dài của thực dân Pháp tại miền Nam Việt Nam"}, {"id": "c", "text": "Chia cắt vĩnh viễn lãnh thổ Việt Nam thành hai quốc gia riêng biệt tại vĩ tuyến 17"}], "correctOptionId": "a", "explanation": "Hiệp định Giơ-ne-vơ là văn bản pháp lí quốc tế đầu tiên ghi nhận đầy đủ các quyền dân tộc cơ bản của ba nước Đông Dương, quy định giới tuyến quân sự tạm thời tại vĩ tuyến 17."}]'::jsonb,'["history-12-dien-bien-phu-1954"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-tet-offensive-1968',10,'LESSON','Cuộc Tổng tiến công và nổi dậy Xuân Mậu Thân 1968','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Đêm Giao thừa Tết Mậu Thân (cuối tháng 1/1968), quân và dân ta bất ngờ mở cuộc Tổng tiến công và nổi dậy đồng loạt đánh vào các đô thị trọng yếu ở miền Nam, tập kích các vị trí đầu não đối phương tại Sài Gòn (Tòa Đại sứ Mĩ, Dinh Độc Lập, Bộ Tổng tham mưu). Thắng lợi đã giáng đòn chí mạng vào chiến lược ''Chiến tranh cục bộ'', làm lung lay ý chí xâm lược của giới cầm quyền Mĩ, buộc Mĩ phải tuyên bố ''phi Mĩ hóa'' chiến tranh, ngừng ném bom miền Bắc và chấp nhận đàm phán tại Paris."]'::jsonb,'["Hình ảnh các chiến sĩ biệt động Sài Gòn tấn công Tòa Đại sứ Mĩ truyền hình trực tiếp về Washington đã gây chấn động dư luận nước Mĩ, thổi bùng phong trào phản chiến đòi hòa bình."]'::jsonb,'[{"id": "history-12-tet-offensive-1968-q1", "prompt": "Điểm độc đáo và bất ngờ nhất về mặt không gian tác chiến của cuộc Tổng tiến công Xuân Mậu Thân 1968 là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Đổ bộ tấn công bất ngờ bằng đường biển vào các hòn đảo xa bờ"}, {"id": "b", "text": "Đồng loạt tiến công trực diện vào các đô thị lớn và cơ quan đầu não đối phương"}, {"id": "c", "text": "Chỉ mở các cuộc phục kích nhỏ ở các vùng rừng núi hẻo lánh"}], "correctOptionId": "b", "explanation": "Đòn tiến công diễn ra đúng đêm Giao thừa Tết nhắm thẳng vào các trung tâm đô thị kiên cố nơi đối phương tập trung phòng thủ dày đặc nhất."}, {"id": "history-12-tet-offensive-1968-q2", "prompt": "Hậu quả chính trị - quân sự lớn nhất mà cuộc Tổng tiến công Xuân Mậu Thân 1968 gây ra cho giới cầm quyền Washington là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Làm lung lay ý chí xâm lược của Mĩ, buộc Tổng thống Johnson phải tuyên bố ''phi Mĩ hóa'' chiến tranh và ngồi vào bàn đàm phán Paris"}, {"id": "b", "text": "Khiến quân Mĩ phải kí ngay hiệp định đầu hàng vô điều kiện trong vòng một tuần"}, {"id": "c", "text": "Làm cho toàn bộ lực lượng quân đội Sài Gòn tự nguyện giải thể vũ khí"}], "correctOptionId": "a", "explanation": "Đòn Mậu Thân phá sản hoàn toàn chiến lược Chiến tranh cục bộ, buộc Mĩ phải xuống thang chiến tranh và thừa nhận thất bại quân sự trên bàn đàm phán."}, {"id": "history-12-tet-offensive-1968-q3", "prompt": "Ý nghĩa chiến lược quan trọng của cuộc đàm phán tại Hội nghị Paris (bắt đầu từ tháng 5/1968) đối với cuộc kháng chiến chống Mĩ là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Thay thế hoàn toàn mọi hoạt động tác chiến của quân giải phóng trên chiến trường"}, {"id": "b", "text": "Buộc các nước xã hội chủ nghĩa ngừng viện trợ kinh tế cho Việt Nam"}, {"id": "c", "text": "Mở ra cục diện ''vừa đánh, vừa đàm'', kết hợp chặt chẽ giữa đấu tranh quân sự, chính trị và mặt trận ngoại giao"}], "correctOptionId": "c", "explanation": "Hội nghị Paris là vũ đài ngoại giao quốc tế phối hợp nhịp nhàng với những chiến thắng trên chiến trường để từng bước buộc Mĩ phải rút quân về nước."}]'::jsonb,'["history-12-tet-offensive-1968"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-ho-chi-minh-campaign-1975',11,'LESSON','Hiệp định Paris 1973 và Chiến dịch Hồ Chí Minh năm 1975','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Hiệp định Paris kí kết ngày 27/1/1973 buộc quân viễn chinh Mĩ phải rút hết về nước, tạo so sánh lực lượng có lợi cho cách mạng (''đánh cho Mĩ cút''). Cuộc Tổng tiến công và nổi dậy mùa Xuân 1975 diễn ra với tốc độ thần tốc qua ba chiến dịch lớn: Chiến dịch Tây Nguyên (đột phá then chốt giải phóng Buôn Ma Thuột 10/3), Chiến dịch Huế - Đà Nẵng, và Chiến dịch Hồ Chí Minh lịch sử (26/4 - 30/4/1975). Đúng 11 giờ 30 phút ngày 30/4/1975, cờ cách mạng tung bay trên nóc Dinh Độc Lập, miền Nam hoàn toàn giải phóng."]'::jsonb,'["Mệnh lệnh lịch sử của Đại tướng Võ Nguyên Giáp gửi toàn quân ngày 7/4/1975: ''Thần tốc, thần tốc hơn nữa; táo bạo, táo bạo hơn nữa; tranh thủ từng giờ, từng phút, xốc tới mặt trận, giải phóng miền Nam!''."]'::jsonb,'[{"id": "history-12-ho-chi-minh-campaign-1975-q1", "prompt": "Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được kí kết chính thức vào thời gian nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngày 27/1/1973"}, {"id": "b", "text": "Ngày 21/7/1954"}, {"id": "c", "text": "Ngày 30/4/1975"}], "correctOptionId": "a", "explanation": "Hiệp định Paris được kí ngày 27/1/1973 sau thắng lợi oanh liệt của trận ''Điện Biên Phủ trên không'' cuối năm 1972, buộc Mĩ phải rút hết quân viễn chinh."}, {"id": "history-12-ho-chi-minh-campaign-1975-q2", "prompt": "Đòn tiến công mở màn mang tính đột phá chiến lược của cuộc Tổng tiến công mùa Xuân 1975 là trận đánh giải phóng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thành phố Huế và Đà Nẵng"}, {"id": "b", "text": "Căn cứ quân sự Cam Ranh"}, {"id": "c", "text": "Thị xã Buôn Ma Thuột (trong Chiến dịch Tây Nguyên, ngày 10/3/1975)"}], "correctOptionId": "c", "explanation": "Trận Buôn Ma Thuột ngày 10/3/1975 đánh trúng điểm hiểm yếu bất ngờ, làm rung chuyển toàn bộ tuyến phòng thủ Tây Nguyên và dẫn đến sự tan rã của đối phương."}, {"id": "history-12-ho-chi-minh-campaign-1975-q3", "prompt": "Chiến thắng lịch sử của Chiến dịch Hồ Chí Minh ngày 30/4/1975 có ý nghĩa thời đại to lớn như thế nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Xóa bỏ hoàn toàn mọi tàn dư chiến tranh ngay lập tức trong một ngày"}, {"id": "b", "text": "Kết thúc vẻ vang 30 năm chiến tranh giải phóng dân tộc, bảo vệ Tổ quốc, chấm dứt hoàn toàn ách thống trị của chủ nghĩa thực dân, đế quốc và mở ra kỉ nguyên thống nhất đi lên chủ nghĩa xã hội"}, {"id": "c", "text": "Bắt đầu thời kì mở rộng lãnh thổ sang các nước lân cận ở khu vực"}], "correctOptionId": "b", "explanation": "Thắng lợi ngày 30/4/1975 non sông thu về một mối, hoàn thành cách mạng dân tộc dân chủ nhân dân trên phạm vi cả nước và cổ vũ phong trào giải phóng dân tộc trên thế giới."}]'::jsonb,'["history-12-ho-chi-minh-campaign-1975"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-review-2',12,'FIVE_LESSON_REVIEW','Ôn tập 2','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "history-12-august-revolution-1945-q1", "prompt": "Ngày 2/9/1945, tại Quảng trường Ba Đình (Hà Nội), sự kiện lịch sử trọng đại nào đã diễn ra?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khởi nghĩa giành chính quyền thắng lợi hoàn toàn tại Sài Gòn"}, {"id": "b", "text": "Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa"}, {"id": "c", "text": "Đại hội Quốc dân Tân Trào thông qua 10 chính sách lớn của Việt Minh"}], "correctOptionId": "b", "explanation": "Bản Tuyên ngôn Độc lập ngày 2/9/1945 tuyên bố trước quốc dân và thế giới quyền tự do, độc lập thiêng liêng của dân tộc Việt Nam."}, {"id": "history-12-august-revolution-1945-q2", "prompt": "Thời cơ lịch sử ''ngàn năm có một'' của Cách mạng tháng Tám năm 1945 xuất hiện khi nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chính phủ phát xít Nhật Bản tuyên bố đầu hàng Đồng minh vô điều kiện (giữa tháng 8/1945)"}, {"id": "b", "text": "Thực dân Pháp bắt đầu quay trở lại nổ súng đánh chiếm Sài Gòn"}, {"id": "c", "text": "Quân đội Tưởng Giới Thạch tiến vào miền Bắc giải giáp quân Nhật"}], "correctOptionId": "a", "explanation": "Nhật đầu hàng Đồng minh khiến quân Nhật ở Đông Dương tê liệt, chính phủ bù nhìn Trần Trọng Kim hoang mang cực độ, tạo thời cơ chín muồi giành chính quyền trước khi quân Đồng minh vào."}, {"id": "history-12-anti-french-resistance-q1", "prompt": "Lời kêu gọi toàn quốc kháng chiến của Chủ tịch Hồ Chí Minh được phát đi vào thời điểm lịch sử nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đêm ngày 19/12/1946"}, {"id": "b", "text": "Ngày 2/9/1945"}, {"id": "c", "text": "Ngày 7/5/1954"}], "correctOptionId": "a", "explanation": "Trước tối hậu thư đòi tước vũ khí của thực dân Pháp tại Hà Nội, Trung ương Đảng và Hồ Chủ tịch đã quyết định phát động toàn quốc kháng chiến đêm 19/12/1946."}, {"id": "history-12-anti-french-resistance-q2", "prompt": "Chiến dịch nào sau đây đã giúp quân đội ta giành được quyền chủ động chiến lược trên chiến trường chính Bắc Bộ?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chiến dịch Việt Bắc thu - đông năm 1947"}, {"id": "b", "text": "Cuộc chiến đấu 60 ngày đêm bảo vệ Thủ đô Hà Nội cuối năm 1946"}, {"id": "c", "text": "Chiến dịch Biên giới thu - đông năm 1950"}], "correctOptionId": "c", "explanation": "Chiến dịch Biên giới 1950 tiêu diệt nhiều sinh lực địch, giải phóng dải biên giới phía Bắc, khai thông đường liên lạc quốc tế và chuyển sang thế chủ động tiến công."}, {"id": "history-12-dien-bien-phu-1954-q1", "prompt": "Chiến dịch lịch sử Điện Biên Phủ năm 1954 toàn thắng vào ngày tháng năm nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngày 13/3/1954"}, {"id": "b", "text": "Ngày 21/7/1954"}, {"id": "c", "text": "Ngày 7/5/1954"}], "correctOptionId": "c", "explanation": "Chiều ngày 7/5/1954, lá cờ Quyết chiến Quyết thắng tung bay trên nóc hầm tướng De Castries, chiến dịch Điện Biên Phủ kết thúc thắng lợi rực rỡ."}, {"id": "history-12-dien-bien-phu-1954-q2", "prompt": "Quyết định thay đổi phương châm tác chiến mang tính bước ngoặt quyết định thắng lợi của Đại tướng Võ Nguyên Giáp tại Điện Biên Phủ là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chuyển từ tiến công đường bộ sang đổ bộ đường không"}, {"id": "b", "text": "Chuyển từ phương châm ''đánh nhanh, thắng nhanh'' sang ''đánh chắc, tiến chắc''"}, {"id": "c", "text": "Chuyển từ bao vây chiến hào sang rút lui toàn bộ lực lượng về căn cứ Việt Bắc"}], "correctOptionId": "b", "explanation": "Nhận thấy địch đã tăng cường công sự kiên cố, việc chuyển sang ''đánh chắc, tiến chắc'' bóc dỡ từng cứ điểm bảo đảm chắc thắng cho từng trận đánh."}, {"id": "history-12-tet-offensive-1968-q1", "prompt": "Điểm độc đáo và bất ngờ nhất về mặt không gian tác chiến của cuộc Tổng tiến công Xuân Mậu Thân 1968 là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Đổ bộ tấn công bất ngờ bằng đường biển vào các hòn đảo xa bờ"}, {"id": "b", "text": "Đồng loạt tiến công trực diện vào các đô thị lớn và cơ quan đầu não đối phương"}, {"id": "c", "text": "Chỉ mở các cuộc phục kích nhỏ ở các vùng rừng núi hẻo lánh"}], "correctOptionId": "b", "explanation": "Đòn tiến công diễn ra đúng đêm Giao thừa Tết nhắm thẳng vào các trung tâm đô thị kiên cố nơi đối phương tập trung phòng thủ dày đặc nhất."}, {"id": "history-12-tet-offensive-1968-q2", "prompt": "Hậu quả chính trị - quân sự lớn nhất mà cuộc Tổng tiến công Xuân Mậu Thân 1968 gây ra cho giới cầm quyền Washington là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Làm lung lay ý chí xâm lược của Mĩ, buộc Tổng thống Johnson phải tuyên bố ''phi Mĩ hóa'' chiến tranh và ngồi vào bàn đàm phán Paris"}, {"id": "b", "text": "Khiến quân Mĩ phải kí ngay hiệp định đầu hàng vô điều kiện trong vòng một tuần"}, {"id": "c", "text": "Làm cho toàn bộ lực lượng quân đội Sài Gòn tự nguyện giải thể vũ khí"}], "correctOptionId": "a", "explanation": "Đòn Mậu Thân phá sản hoàn toàn chiến lược Chiến tranh cục bộ, buộc Mĩ phải xuống thang chiến tranh và thừa nhận thất bại quân sự trên bàn đàm phán."}, {"id": "history-12-ho-chi-minh-campaign-1975-q1", "prompt": "Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được kí kết chính thức vào thời gian nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngày 27/1/1973"}, {"id": "b", "text": "Ngày 21/7/1954"}, {"id": "c", "text": "Ngày 30/4/1975"}], "correctOptionId": "a", "explanation": "Hiệp định Paris được kí ngày 27/1/1973 sau thắng lợi oanh liệt của trận ''Điện Biên Phủ trên không'' cuối năm 1972, buộc Mĩ phải rút hết quân viễn chinh."}, {"id": "history-12-ho-chi-minh-campaign-1975-q2", "prompt": "Đòn tiến công mở màn mang tính đột phá chiến lược của cuộc Tổng tiến công mùa Xuân 1975 là trận đánh giải phóng:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thành phố Huế và Đà Nẵng"}, {"id": "b", "text": "Căn cứ quân sự Cam Ranh"}, {"id": "c", "text": "Thị xã Buôn Ma Thuột (trong Chiến dịch Tây Nguyên, ngày 10/3/1975)"}], "correctOptionId": "c", "explanation": "Trận Buôn Ma Thuột ngày 10/3/1975 đánh trúng điểm hiểm yếu bất ngờ, làm rung chuyển toàn bộ tuyến phòng thủ Tây Nguyên và dẫn đến sự tan rã của đối phương."}]'::jsonb,'["history-12-august-revolution-1945", "history-12-anti-french-resistance", "history-12-dien-bien-phu-1954", "history-12-tet-offensive-1968", "history-12-ho-chi-minh-campaign-1975"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-national-reunification-state',13,'LESSON','Thống nhất đất nước về mặt nhà nước (1975 - 1976)','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Sau ngày 30/4/1975, đất nước đã thống nhất về mặt lãnh thổ nhưng vẫn tồn tại hai chính phủ ở hai miền. Hội nghị Hiệp thương chính trị (11/1975) đã nhất trí tổ chức Tổng tuyển cử bầu Quốc hội chung. Ngày 25/4/1976, cử tri cả nước nô nức đi bầu cử Quốc hội khóa VI. Kì họp thứ nhất (6 - 7/1976) đã quyết định: đặt tên nước là Cộng hòa Xã hội chủ nghĩa Việt Nam, thủ đô là Hà Nội, Quốc huy, Quốc kì (cờ đỏ sao vàng), Quốc ca (Tiến quân ca), và đổi tên thành phố Sài Gòn - Gia Định thành Thành phố Hồ Chí Minh."]'::jsonb,'["Cuộc Tổng tuyển cử ngày 25/4/1976 là ngày hội non sông với hơn 23 triệu cử tri (đạt 98,77%) lần đầu tiên cùng đi bỏ phiếu bầu ra Quốc hội thống nhất."]'::jsonb,'[{"id": "history-12-national-reunification-state-q1", "prompt": "Kì họp thứ nhất Quốc hội khóa VI (tháng 6 - 7/1976) đã đưa ra quyết định trọng đại nào về quốc hiệu?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đặt tên nước là Việt Nam Dân chủ Cộng hòa"}, {"id": "b", "text": "Giữ nguyên hai tên gọi nhà nước riêng biệt ở hai miền"}, {"id": "c", "text": "Đặt tên nước là Cộng hòa Xã hội chủ nghĩa Việt Nam"}], "correctOptionId": "c", "explanation": "Quốc hội khóa VI đã thống nhất thể chế, quyết định quốc hiệu là Cộng hòa Xã hội chủ nghĩa Việt Nam từ ngày 2/7/1976."}, {"id": "history-12-national-reunification-state-q2", "prompt": "Ý nghĩa lịch sử then chốt của việc hoàn thành thống nhất đất nước về mặt nhà nước (1975 - 1976) là gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cho phép đất nước ngay lập tức tham gia vào tất cả các hiệp định thương mại tự do"}, {"id": "b", "text": "Tạo cơ sở pháp lí và sức mạnh tổng hợp của toàn dân tộc để xây dựng, phát triển kinh tế và bảo vệ vững chắc Tổ quốc"}, {"id": "c", "text": "Chấm dứt hoàn toàn mọi khó khăn về kinh tế - xã hội thời hậu chiến"}], "correctOptionId": "b", "explanation": "Thống nhất nhà nước tạo nên sự đồng bộ về thể chế, luật pháp, chính quyền từ trung ương đến địa phương để huy động mọi nguồn lực kiến thiết đất nước."}, {"id": "history-12-national-reunification-state-q3", "prompt": "Tại sao sau đại thắng mùa Xuân 1975, nhiệm vụ thống nhất đất nước về mặt nhà nước lại trở nên cấp thiết hàng đầu?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Vì dù lãnh thổ đã liền một dải nhưng mỗi miền vẫn có bộ máy nhà nước và pháp luật riêng biệt, cản trở sự quản lí thống nhất và phát triển kinh tế"}, {"id": "b", "text": "Vì các cường quốc bên ngoài yêu cầu phải có một chính phủ liên hiệp tạm thời"}, {"id": "c", "text": "Vì cần chia lại địa giới các tỉnh thành theo mô hình thuộc địa"}], "correctOptionId": "a", "explanation": "Tình trạng tồn tại hai nhà nước (ở miền Bắc là VNDCCH, miền Nam là Chính phủ Cách mạng lâm thời CHMNVN) đòi hỏi phải thể chế hóa ý chí thống nhất của toàn dân thành một nhà nước pháp quyền duy nhất."}]'::jsonb,'["history-12-national-reunification-state"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-doi-moi-1986',14,'LESSON','Đại hội đại biểu toàn quốc lần thứ VI (12/1986) và đường lối Đổi mới','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Trong những năm 1976 - 1985, cơ chế quản lí tập trung quan liêu bao cấp và khủng hoảng kinh tế - xã hội trầm trọng (lạm phát phi mã lên tới hơn 700% năm 1986) đã đặt ra yêu cầu sống còn phải đổi mới. Đại hội đại biểu toàn quốc lần thứ VI của Đảng (12/1986) đã đề ra đường lối Đổi mới toàn diện: đổi mới tư duy kinh tế, phát triển nền kinh tế nhiều thành phần định hướng XHCN, vận hành theo cơ chế thị trường có sự quản lí của Nhà nước, thực hiện ba chương trình kinh tế lớn (lương thực - thực phẩm, hàng tiêu dùng, hàng xuất khẩu)."]'::jsonb,'["Nghị quyết 10 của Bộ Chính trị (Khoán 10 năm 1988) giao quyền tự chủ ruộng đất cho hộ nông dân, giúp Việt Nam nhanh chóng thoát cảnh thiếu đói và trở thành nước xuất khẩu gạo hàng đầu thế giới."]'::jsonb,'[{"id": "history-12-doi-moi-1986-q1", "prompt": "Đại hội đại biểu toàn quốc lần thứ VI của Đảng Cộng sản Việt Nam họp vào tháng 12/1986 có ý nghĩa lịch sử gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tuyên bố xóa bỏ hoàn toàn nền kinh tế thị trường để chuyển sang kinh tế thuần nông"}, {"id": "b", "text": "Khởi xướng và đề ra đường lối Đổi mới toàn diện đất nước"}, {"id": "c", "text": "Quyết định phát động cuộc kháng chiến toàn quốc chống Mĩ cứu nước"}], "correctOptionId": "b", "explanation": "Đại hội VI (12/1986) nhìn thẳng vào sự thật, đánh dấu bước ngoặt lịch sử mở đường cho công cuộc Đổi mới đất nước."}, {"id": "history-12-doi-moi-1986-q2", "prompt": "Trọng tâm của đường lối Đổi mới do Đại hội VI đề ra bắt đầu từ lĩnh vực nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đổi mới về kinh tế"}, {"id": "b", "text": "Đổi mới về chính trị"}, {"id": "c", "text": "Đổi mới về quốc phòng"}], "correctOptionId": "a", "explanation": "Đảng xác định đổi mới kinh tế là trọng tâm, kết hợp từng bước đổi mới chính trị vững chắc nhằm giải quyết khủng hoảng đời sống nhân dân trước tiên."}, {"id": "history-12-doi-moi-1986-q3", "prompt": "Một trong những nội dung căn bản của việc đổi mới tư duy kinh tế tại Đại hội VI (1986) là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Quốc hữu hóa toàn bộ ruộng đất và cấm đoán tư nhân buôn bán"}, {"id": "b", "text": "Chỉ tập trung vào công nghiệp nặng và dừng sản xuất hàng tiêu dùng"}, {"id": "c", "text": "Xóa bỏ cơ chế quản lí tập trung quan liêu, bao cấp, phát triển nền kinh tế nhiều thành phần vận hành theo cơ chế thị trường có sự quản lí của Nhà nước"}], "correctOptionId": "c", "explanation": "Đại hội VI công nhận sự tồn tại khách quan của nền kinh tế nhiều thành phần và quy luật giá trị thị trường định hướng xã hội chủ nghĩa."}]'::jsonb,'["history-12-doi-moi-1986"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-vietnam-international-integration',15,'LESSON','Quá trình hội nhập quốc tế sâu rộng của Việt Nam','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Thực hiện đường lối đối ngoại độc lập, tự chủ, đa phương hóa, đa dạng hóa (''Việt Nam sẵn sàng là bạn, là đối tác tin cậy và thành viên có trách nhiệm của cộng đồng quốc tế''), Việt Nam từng bước phá vỡ bao vây cô lập: bình thường hóa quan hệ với Trung Quốc (1991), bình thường hóa quan hệ với Hoa Kỳ (11/7/1995), gia nhập ASEAN (28/7/1995), APEC (1998), WTO (2007). Việt Nam đã thiết lập quan hệ ngoại giao với gần 200 quốc gia và nâng cấp quan hệ Đối tác chiến lược toàn diện với nhiều cường quốc hàng đầu thế giới."]'::jsonb,'["Việc kí kết các Hiệp định thương mại tự do thế hệ mới như CPTPP (2018) và EVFTA (2020) mở rộng cánh cửa xuất khẩu hàng hóa Việt Nam sang các thị trường phát triển nhất thế giới."]'::jsonb,'[{"id": "history-12-vietnam-international-integration-q1", "prompt": "Năm 1995 ghi dấu ấn lịch sử nổi bật nào trong tiến trình hội nhập quốc tế của Việt Nam?", "difficulty": "EASY", "options": [{"id": "a", "text": "Bình thường hóa quan hệ ngoại giao với Hoa Kỳ và chính thức gia nhập ASEAN"}, {"id": "b", "text": "Gia nhập Tổ chức Thương mại Thế giới (WTO)"}, {"id": "c", "text": "Kí kết Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP)"}], "correctOptionId": "a", "explanation": "Tháng 7/1995 là dấu mốc lịch sử khi Việt Nam và Mĩ bình thường hóa quan hệ ngoại giao (11/7) và Việt Nam trở thành thành viên ASEAN (28/7)."}, {"id": "history-12-vietnam-international-integration-q2", "prompt": "Việt Nam chính thức trở thành thành viên thứ 150 của Tổ chức Thương mại Thế giới (WTO) vào năm nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Năm 1995"}, {"id": "b", "text": "Năm 1986"}, {"id": "c", "text": "Năm 2007"}], "correctOptionId": "c", "explanation": "Tháng 1/2007, Việt Nam chính thức trở thành thành viên WTO, đánh dấu bước hội nhập sâu rộng vào sân chơi kinh tế toàn cầu."}, {"id": "history-12-vietnam-international-integration-q3", "prompt": "Đường lối đối ngoại ''đa phương hóa, đa dạng hóa quan hệ quốc tế'' mang lại lợi ích chiến lược lớn nhất cho Việt Nam là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Đóng cửa thị trường nội địa để bảo hộ tuyệt đối cho các doanh nghiệp yếu kém"}, {"id": "b", "text": "Nâng cao vị thế và uy tín quốc tế, tranh thủ nguồn vốn đầu tư, công nghệ hiện đại và củng cố môi trường hòa bình để phát triển đất nước"}, {"id": "c", "text": "Phụ thuộc hoàn toàn vào viện trợ không hoàn lại của một siêu cường duy nhất"}], "correctOptionId": "b", "explanation": "Chính sách ngoại giao rộng mở giúp đất nước giữ vững độc lập chủ quyền, thu hút hàng trăm tỉ USD vốn FDI và mở rộng thị trường xuất khẩu."}]'::jsonb,'["history-12-vietnam-international-integration"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-east-sea-sovereignty',16,'LESSON','Chủ quyền biển, đảo của Việt Nam trên Biển Đông trong lịch sử và luật pháp quốc tế','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Nhà nước Việt Nam qua các triều đại lịch sử đã xác lập, thực thi chủ quyền liên tục, hòa bình đối với hai quần đảo Hoàng Sa và Trường Sa phù hợp với luật pháp quốc tế. Chứng cứ lịch sử: Châu bản triều Nguyễn, Toàn tập Thiên Nam tứ chí lộ đồ thư (1686), Đại Nam thực lục, hoạt động của Hải đội Hoàng Sa và Bắc Hải kiêm quản. Về mặt pháp lí quốc tế: Công ước Liên hợp quốc về Luật Biển năm 1982 (UNCLOS 1982), Luật Biển Việt Nam năm 2012 khẳng định chủ quyền, quyền chủ quyền và quyền tài phán; cam kết thực hiện Tuyên bố DOC và hướng tới Bộ Quy tắc COC ở Biển Đông."]'::jsonb,'["Lễ Khao lề thế lính Hoàng Sa được nhân dân huyện đảo Lý Sơn (Quảng Ngãi) duy trì hàng trăm năm qua là bằng chứng sống động về lòng tri ân và ý chí gìn giữ chủ quyền biển đảo thiêng liêng của cha ông."]'::jsonb,'[{"id": "history-12-east-sea-sovereignty-q1", "prompt": "Tổ chức nào trong lịch sử phong kiến Việt Nam được các chúa Nguyễn và triều Nguyễn lập ra để thực thi chủ quyền hàng năm tại Hoàng Sa và Trường Sa?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đoàn tàu buôn phương Tây"}, {"id": "b", "text": "Vạn chài ven sông Hồng"}, {"id": "c", "text": "Hải đội Hoàng Sa (và Đội Bắc Hải)"}], "correctOptionId": "c", "explanation": "Hải đội Hoàng Sa được thành lập từ thời chúa Nguyễn có nhiệm vụ ra hai quần đảo đo đạc thủy trình, cắm mốc chủ quyền, thu lượm hải vật và cứu hộ tàu thuyền."}, {"id": "history-12-east-sea-sovereignty-q2", "prompt": "Văn bản pháp lí quốc tế quan trọng nhất hiện nay quy định chế độ pháp lí của các vùng biển và quyền của các quốc gia ven biển là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hiến chương Liên minh châu Âu"}, {"id": "b", "text": "Công ước Liên hợp quốc về Luật Biển năm 1982 (UNCLOS 1982)"}, {"id": "c", "text": "Tuyên bố Cairo năm 1943"}], "correctOptionId": "b", "explanation": "UNCLOS 1982 được coi là ''Hiến pháp của đại dương'', xác lập rõ ràng phạm vi nội thủy, lãnh hải, vùng đặc quyền kinh tế 200 hải lí và thềm lục địa."}, {"id": "history-12-east-sea-sovereignty-q3", "prompt": "Chủ trương nhất quán của Đảng và Nhà nước Việt Nam trong việc giải quyết các tranh chấp về chủ quyền trên Biển Đông là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Giải quyết bằng biện pháp hòa bình trên cơ sở tôn trọng luật pháp quốc tế, đặc biệt là UNCLOS 1982, giữ vững hòa bình và an ninh khu vực"}, {"id": "b", "text": "Sử dụng ngay biện pháp quân sự đối đầu trực diện khi có tranh chấp"}, {"id": "c", "text": "Từ bỏ hoàn toàn các quyền chủ quyền trên vùng đặc quyền kinh tế để giữ hòa khí"}], "correctOptionId": "a", "explanation": "Việt Nam kiên quyết bảo vệ chủ quyền nhưng kiên trì giải quyết bất đồng thông qua đối thoại hòa bình, tuân thủ UNCLOS 1982 và các thỏa thuận quốc tế."}]'::jsonb,'["history-12-east-sea-sovereignty"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-ho-chi-minh-national-liberation',17,'LESSON','Chủ tịch Hồ Chí Minh - Anh hùng giải phóng dân tộc và dấu ấn lịch sử','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Chủ tịch Hồ Chí Minh (1890 - 1969) là vị lãnh tụ thiên tài của cách mạng Việt Nam, Anh hùng giải phóng dân tộc và Danh nhân văn hóa thế giới được UNESCO vinh danh năm 1987. Cuộc đời hoạt động cách mạng: ra đi tìm đường cứu nước (1911), tiếp cận chủ nghĩa Mác - Lênin (1920), sáng lập Đảng Cộng sản Việt Nam (1930), lãnh đạo Cách mạng tháng Tám lập nên nước Việt Nam Dân chủ Cộng hòa (1945), và cùng toàn Đảng, toàn dân lãnh đạo thắng lợi các cuộc kháng chiến vì độc lập, tự do và thống nhất Tổ quốc."]'::jsonb,'["Năm 1920, tại Đại hội Tours (Pháp), Nguyễn Ái Quốc bỏ phiếu tán thành gia nhập Quốc tế thứ ba và tham gia sáng lập Đảng Cộng sản Pháp, đánh dấu bước chuyển dứt khoát từ chủ nghĩa yêu nước sang chủ nghĩa cộng sản."]'::jsonb,'[{"id": "history-12-ho-chi-minh-national-liberation-q1", "prompt": "Sự kiện lịch sử nào đánh dấu bước ngoặt quyết định đưa Nguyễn Ái Quốc từ người yêu nước trở thành chiến sĩ cộng sản?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tham gia thành lập Hội Liên hiệp thuộc địa tại Paris năm 1921"}, {"id": "b", "text": "Đọc Luận cương của Lênin về vấn đề dân tộc và thuộc địa (1920) và bỏ phiếu tán thành Quốc tế Cộng sản tại Đại hội Tours"}, {"id": "c", "text": "Rời bến cảng Nhà Rồng sang phương Tây tìm đường cứu nước năm 1911"}], "correctOptionId": "b", "explanation": "Tháng 7/1920, khi đọc Sơ thảo Luận cương của Lênin, Nguyễn Ái Quốc đã tìm thấy con đường giải phóng cho dân tộc và bỏ phiếu tán thành Quốc tế Cộng sản vào tháng 12/1920."}, {"id": "history-12-ho-chi-minh-national-liberation-q2", "prompt": "Tác phẩm lý luận chính trị xuất sắc do Nguyễn Ái Quốc biên soạn năm 1927 dùng làm tài liệu huấn luyện cán bộ cách mạng tiền phong là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đường Kách mệnh"}, {"id": "b", "text": "Bản án chế độ thực dân Pháp"}, {"id": "c", "text": "Tuyên ngôn Độc lập"}], "correctOptionId": "a", "explanation": "Cuốn sách ''Đường Kách mệnh'' (1927) tập hợp các bài giảng của Nguyễn Ái Quốc tại Quảng Châu, chuẩn bị nền tảng tư tưởng và chính trị cho sự ra đời của Đảng."}, {"id": "history-12-ho-chi-minh-national-liberation-q3", "prompt": "Năm 1987, Đại hội đồng UNESCO đã ra Nghị quyết 24C/18.65 tôn vinh Chủ tịch Hồ Chí Minh với danh hiệu cao quý nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Đại sứ hòa bình danh dự của phong trào không liên kết"}, {"id": "b", "text": "Nhà cải cách giáo dục tiêu biểu của thế kỉ XX"}, {"id": "c", "text": "Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất của Việt Nam"}], "correctOptionId": "c", "explanation": "Nghị quyết của UNESCO khẳng định Chủ tịch Hồ Chí Minh là biểu tượng xuất sắc về sự kiên cường đấu tranh giải phóng dân tộc và kết tinh các giá trị văn hóa nhân loại cao đẹp."}]'::jsonb,'["history-12-ho-chi-minh-national-liberation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('history',12,'intro-2026.1','history-12-review-3',18,'FIVE_LESSON_REVIEW','Ôn tập 3','Lịch sử 12: Thế giới và Việt Nam từ thế kỉ XX đến nay','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "history-12-national-reunification-state-q1", "prompt": "Kì họp thứ nhất Quốc hội khóa VI (tháng 6 - 7/1976) đã đưa ra quyết định trọng đại nào về quốc hiệu?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đặt tên nước là Việt Nam Dân chủ Cộng hòa"}, {"id": "b", "text": "Giữ nguyên hai tên gọi nhà nước riêng biệt ở hai miền"}, {"id": "c", "text": "Đặt tên nước là Cộng hòa Xã hội chủ nghĩa Việt Nam"}], "correctOptionId": "c", "explanation": "Quốc hội khóa VI đã thống nhất thể chế, quyết định quốc hiệu là Cộng hòa Xã hội chủ nghĩa Việt Nam từ ngày 2/7/1976."}, {"id": "history-12-national-reunification-state-q2", "prompt": "Ý nghĩa lịch sử then chốt của việc hoàn thành thống nhất đất nước về mặt nhà nước (1975 - 1976) là gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cho phép đất nước ngay lập tức tham gia vào tất cả các hiệp định thương mại tự do"}, {"id": "b", "text": "Tạo cơ sở pháp lí và sức mạnh tổng hợp của toàn dân tộc để xây dựng, phát triển kinh tế và bảo vệ vững chắc Tổ quốc"}, {"id": "c", "text": "Chấm dứt hoàn toàn mọi khó khăn về kinh tế - xã hội thời hậu chiến"}], "correctOptionId": "b", "explanation": "Thống nhất nhà nước tạo nên sự đồng bộ về thể chế, luật pháp, chính quyền từ trung ương đến địa phương để huy động mọi nguồn lực kiến thiết đất nước."}, {"id": "history-12-doi-moi-1986-q1", "prompt": "Đại hội đại biểu toàn quốc lần thứ VI của Đảng Cộng sản Việt Nam họp vào tháng 12/1986 có ý nghĩa lịch sử gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tuyên bố xóa bỏ hoàn toàn nền kinh tế thị trường để chuyển sang kinh tế thuần nông"}, {"id": "b", "text": "Khởi xướng và đề ra đường lối Đổi mới toàn diện đất nước"}, {"id": "c", "text": "Quyết định phát động cuộc kháng chiến toàn quốc chống Mĩ cứu nước"}], "correctOptionId": "b", "explanation": "Đại hội VI (12/1986) nhìn thẳng vào sự thật, đánh dấu bước ngoặt lịch sử mở đường cho công cuộc Đổi mới đất nước."}, {"id": "history-12-doi-moi-1986-q2", "prompt": "Trọng tâm của đường lối Đổi mới do Đại hội VI đề ra bắt đầu từ lĩnh vực nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đổi mới về kinh tế"}, {"id": "b", "text": "Đổi mới về chính trị"}, {"id": "c", "text": "Đổi mới về quốc phòng"}], "correctOptionId": "a", "explanation": "Đảng xác định đổi mới kinh tế là trọng tâm, kết hợp từng bước đổi mới chính trị vững chắc nhằm giải quyết khủng hoảng đời sống nhân dân trước tiên."}, {"id": "history-12-vietnam-international-integration-q1", "prompt": "Năm 1995 ghi dấu ấn lịch sử nổi bật nào trong tiến trình hội nhập quốc tế của Việt Nam?", "difficulty": "EASY", "options": [{"id": "a", "text": "Bình thường hóa quan hệ ngoại giao với Hoa Kỳ và chính thức gia nhập ASEAN"}, {"id": "b", "text": "Gia nhập Tổ chức Thương mại Thế giới (WTO)"}, {"id": "c", "text": "Kí kết Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP)"}], "correctOptionId": "a", "explanation": "Tháng 7/1995 là dấu mốc lịch sử khi Việt Nam và Mĩ bình thường hóa quan hệ ngoại giao (11/7) và Việt Nam trở thành thành viên ASEAN (28/7)."}, {"id": "history-12-vietnam-international-integration-q2", "prompt": "Việt Nam chính thức trở thành thành viên thứ 150 của Tổ chức Thương mại Thế giới (WTO) vào năm nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Năm 1995"}, {"id": "b", "text": "Năm 1986"}, {"id": "c", "text": "Năm 2007"}], "correctOptionId": "c", "explanation": "Tháng 1/2007, Việt Nam chính thức trở thành thành viên WTO, đánh dấu bước hội nhập sâu rộng vào sân chơi kinh tế toàn cầu."}, {"id": "history-12-east-sea-sovereignty-q1", "prompt": "Tổ chức nào trong lịch sử phong kiến Việt Nam được các chúa Nguyễn và triều Nguyễn lập ra để thực thi chủ quyền hàng năm tại Hoàng Sa và Trường Sa?", "difficulty": "EASY", "options": [{"id": "a", "text": "Đoàn tàu buôn phương Tây"}, {"id": "b", "text": "Vạn chài ven sông Hồng"}, {"id": "c", "text": "Hải đội Hoàng Sa (và Đội Bắc Hải)"}], "correctOptionId": "c", "explanation": "Hải đội Hoàng Sa được thành lập từ thời chúa Nguyễn có nhiệm vụ ra hai quần đảo đo đạc thủy trình, cắm mốc chủ quyền, thu lượm hải vật và cứu hộ tàu thuyền."}, {"id": "history-12-east-sea-sovereignty-q2", "prompt": "Văn bản pháp lí quốc tế quan trọng nhất hiện nay quy định chế độ pháp lí của các vùng biển và quyền của các quốc gia ven biển là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hiến chương Liên minh châu Âu"}, {"id": "b", "text": "Công ước Liên hợp quốc về Luật Biển năm 1982 (UNCLOS 1982)"}, {"id": "c", "text": "Tuyên bố Cairo năm 1943"}], "correctOptionId": "b", "explanation": "UNCLOS 1982 được coi là ''Hiến pháp của đại dương'', xác lập rõ ràng phạm vi nội thủy, lãnh hải, vùng đặc quyền kinh tế 200 hải lí và thềm lục địa."}, {"id": "history-12-ho-chi-minh-national-liberation-q1", "prompt": "Sự kiện lịch sử nào đánh dấu bước ngoặt quyết định đưa Nguyễn Ái Quốc từ người yêu nước trở thành chiến sĩ cộng sản?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tham gia thành lập Hội Liên hiệp thuộc địa tại Paris năm 1921"}, {"id": "b", "text": "Đọc Luận cương của Lênin về vấn đề dân tộc và thuộc địa (1920) và bỏ phiếu tán thành Quốc tế Cộng sản tại Đại hội Tours"}, {"id": "c", "text": "Rời bến cảng Nhà Rồng sang phương Tây tìm đường cứu nước năm 1911"}], "correctOptionId": "b", "explanation": "Tháng 7/1920, khi đọc Sơ thảo Luận cương của Lênin, Nguyễn Ái Quốc đã tìm thấy con đường giải phóng cho dân tộc và bỏ phiếu tán thành Quốc tế Cộng sản vào tháng 12/1920."}, {"id": "history-12-ho-chi-minh-national-liberation-q2", "prompt": "Tác phẩm lý luận chính trị xuất sắc do Nguyễn Ái Quốc biên soạn năm 1927 dùng làm tài liệu huấn luyện cán bộ cách mạng tiền phong là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đường Kách mệnh"}, {"id": "b", "text": "Bản án chế độ thực dân Pháp"}, {"id": "c", "text": "Tuyên ngôn Độc lập"}], "correctOptionId": "a", "explanation": "Cuốn sách ''Đường Kách mệnh'' (1927) tập hợp các bài giảng của Nguyễn Ái Quốc tại Quảng Châu, chuẩn bị nền tảng tư tưởng và chính trị cho sự ra đời của Đảng."}]'::jsonb,'["history-12-national-reunification-state", "history-12-doi-moi-1986", "history-12-vietnam-international-integration", "history-12-east-sea-sovereignty", "history-12-ho-chi-minh-national-liberation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','placement',0,'PLACEMENT','Khảo sát đầu vào','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "geography-12-vietnam-location-territory-q1", "prompt": "Điểm cực Bắc trên đất liền của nước ta thuộc xã Lũng Cú (huyện Đồng Văn, tỉnh Hà Giang) nằm ở vĩ độ nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "23°23''B"}, {"id": "b", "text": "8°34''B"}, {"id": "c", "text": "102°09''Đ"}], "correctOptionId": "a", "explanation": "Điểm cực Bắc tại Lũng Cú (Hà Giang) ở vĩ độ 23°23''B; điểm cực Nam tại Ngọc Hiển (Cà Mau) ở vĩ độ 8°34''B."}, {"id": "geography-12-vietnam-location-territory-q2", "prompt": "Vùng biển thuộc chủ quyền hoàn toàn và tuyệt đối của quốc gia ven biển, có chiều rộng 12 hải lí tính từ đường cơ sở gọi là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Nội thủy"}, {"id": "b", "text": "Vùng đặc quyền kinh tế"}, {"id": "c", "text": "Lãnh hải"}], "correctOptionId": "c", "explanation": "Theo Luật Biển Việt Nam và UNCLOS 1982, lãnh hải là vùng biển có chiều rộng 12 hải lí tính từ đường cơ sở ra phía biển, thuộc chủ quyền quốc gia."}, {"id": "geography-12-vietnam-relief-landforms-q1", "prompt": "Đặc điểm nào sau đây phản ánh đúng nhất cấu trúc cơ bản của địa hình đồi núi Việt Nam?", "difficulty": "EASY", "options": [{"id": "a", "text": "Địa hình chủ yếu là núi cao hiểm trở trên 3000 m chiếm hơn một nửa diện tích"}, {"id": "b", "text": "Đồng bằng châu thổ chiếm tới 75% toàn bộ diện tích đất liền"}, {"id": "c", "text": "Đồi núi chiếm 3/4 diện tích lãnh thổ, nhưng chủ yếu là đồi núi thấp dưới 1000 m"}], "correctOptionId": "c", "explanation": "Đồi núi thấp dưới 1000 m chiếm tới 85% diện tích cả nước, núi cao trên 2000 m chỉ chiếm khoảng 1%."}, {"id": "geography-12-vietnam-relief-landforms-q2", "prompt": "Hai hướng núi chính thể hiện rõ nét nhất trong cấu trúc sơn văn của lãnh thổ Việt Nam là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hướng đông bắc - tây nam và hướng kinh tuyến"}, {"id": "b", "text": "Hướng tây bắc - đông nam và hướng vòng cung"}, {"id": "c", "text": "Hướng bắc - nam và hướng đông - tây"}], "correctOptionId": "b", "explanation": "Các dãy núi Tây Bắc và Trường Sơn Bắc có hướng tây bắc - đông nam; vùng núi Đông Bắc có 4 cánh cung lớn chụm đầu ở Tam Đảo."}, {"id": "geography-12-vietnam-tropical-monsoon-climate-q1", "prompt": "Biểu hiện rõ nét nhất của tính chất nhiệt đới trong khí hậu Việt Nam là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Lượng mưa hàng năm rất thấp dưới 200 mm giống như hoang mạc"}, {"id": "b", "text": "Nhiệt độ trung bình năm trên hầu khắp cả nước đều vượt 20 °C và tổng số giờ nắng dồi dào"}, {"id": "c", "text": "Quanh năm luôn có bão tuyết và nhiệt độ âm"}], "correctOptionId": "b", "explanation": "Nhờ nằm hoàn toàn trong vùng nội chí tuyến, lãnh thổ nhận được lượng bức xạ mặt trời lớn, cân bằng bức xạ dương quanh năm."}, {"id": "geography-12-vietnam-tropical-monsoon-climate-q2", "prompt": "Đặc điểm thời tiết nổi bật của miền Bắc nước ta vào nửa sau mùa đông (từ tháng 2 đến tháng 4) là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thời tiết lạnh ẩm và có mưa phùn"}, {"id": "b", "text": "Thời tiết khô hanh, trời quang mây và không mưa"}, {"id": "c", "text": "Nắng nóng gay gắt kéo dài nhiều tuần liên tiếp"}], "correctOptionId": "a", "explanation": "Nửa sau mùa đông khối không khí lạnh lệch đông đi qua biển vào đất liền mang theo lượng ẩm lớn, gây thời tiết lạnh ẩm và mưa phùn rải rác."}, {"id": "geography-12-vietnam-population-demographics-q1", "prompt": "Quy mô dân số Việt Nam hiện nay đã chính thức vượt qua mốc dân số nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Trên 100 triệu người"}, {"id": "b", "text": "Khoảng 50 triệu người"}, {"id": "c", "text": "Trên 200 triệu người"}], "correctOptionId": "a", "explanation": "Năm 2023, dân số Việt Nam đã chính thức vượt qua mốc 100 triệu người, xếp thứ 3 ở Đông Nam Á sau Indonesia và Philippines."}, {"id": "geography-12-vietnam-population-demographics-q2", "prompt": "Cơ hội phát triển kinh tế - xã hội lớn nhất do thời kì ''cơ cấu dân số vàng'' mang lại cho nước ta là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Làm giảm chi phí đầu tư cho hệ thống giáo dục tiểu học về mức 0"}, {"id": "b", "text": "Loại bỏ hoàn toàn vấn đề thất nghiệp ở các vùng đô thị"}, {"id": "c", "text": "Cung cấp lực lượng lao động trẻ dồi dào, thúc đẩy tăng trưởng kinh tế nhanh nếu được đào tạo tốt"}], "correctOptionId": "c", "explanation": "Dân số vàng nghĩa là cứ hai người đi làm nuôi dưới một người phụ thuộc, tạo lợi thế lớn về năng suất và tích lũy vốn phát triển."}, {"id": "geography-12-vietnam-urbanization-process-q1", "prompt": "Hai đô thị trực thuộc trung ương được xếp vào cấp đô thị loại đặc biệt ở Việt Nam là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Đà Nẵng và Hải Phòng"}, {"id": "b", "text": "Cần Thơ và Nha Trang"}, {"id": "c", "text": "Hà Nội và Thành phố Hồ Chí Minh"}], "correctOptionId": "c", "explanation": "Hà Nội (thủ đô) và TP. Hồ Chí Minh (đầu tàu kinh tế phía Nam) là hai đô thị loại đặc biệt của cả nước."}, {"id": "geography-12-vietnam-urbanization-process-q2", "prompt": "Đặc điểm cơ bản của quá trình đô thị hóa ở Việt Nam hiện nay là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Các đô thị hoàn toàn không có sự đóng góp nào vào nguồn thu ngân sách"}, {"id": "b", "text": "Tốc độ đô thị hóa diễn ra nhanh nhưng trình độ đô thị hóa nhìn chung vẫn còn thấp"}, {"id": "c", "text": "Tỉ lệ dân số thành thị đã chiếm trên 90% tổng số dân cả nước"}], "correctOptionId": "b", "explanation": "Dù tỉ lệ dân thành thị tăng đều đặn qua các năm nhưng chất lượng cơ sở hạ tầng và dịch vụ đô thị còn nhiều hạn chế."}, {"id": "geography-12-vietnam-agriculture-restructuring-q1", "prompt": "Xu hướng chuyển dịch cơ cấu nội bộ ngành trồng trọt của nước ta hiện nay là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Chuyển toàn bộ diện tích đất nông nghiệp sang khai thác mỏ khoáng sản"}, {"id": "b", "text": "Giảm tỉ trọng cây lương thực phẩm cấp thấp, tăng tỉ trọng cây công nghiệp lâu năm và cây ăn quả chất lượng cao"}, {"id": "c", "text": "Xóa bỏ hoàn toàn diện tích trồng lúa để trồng toàn bộ cỏ chăn nuôi"}], "correctOptionId": "b", "explanation": "Tái cơ cấu trồng trọt tập trung vào nâng cao giá trị gia tăng, đáp ứng tiêu chuẩn xuất khẩu và thích ứng biến đổi khí hậu."}, {"id": "geography-12-vietnam-agriculture-restructuring-q2", "prompt": "Vùng chuyên canh cây cà phê lớn nhất của Việt Nam, đưa nước ta trở thành quốc gia xuất khẩu cà phê Robusta hàng đầu thế giới là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Vùng Tây Nguyên"}, {"id": "b", "text": "Vùng Đồng bằng sông Hồng"}, {"id": "c", "text": "Vùng Bắc Trung Bộ"}], "correctOptionId": "a", "explanation": "Tây Nguyên có diện tích đất đỏ bazan màu mỡ và khí hậu cận xích đạo rất thích hợp hình thành các vùng chuyên canh cà phê quy mô lớn."}, {"id": "geography-12-vietnam-forestry-fisheries-q1", "prompt": "Loại rừng nào sau đây có chức năng chủ yếu là bảo tồn nguồn gene sinh vật quý hiếm và nghiên cứu khoa học?", "difficulty": "EASY", "options": [{"id": "a", "text": "Rừng đặc dụng (các vườn quốc gia, khu bảo tồn thiên nhiên)"}, {"id": "b", "text": "Rừng sản xuất lấy gỗ"}, {"id": "c", "text": "Rừng trồng bạch đàn thương phẩm"}], "correctOptionId": "a", "explanation": "Rừng đặc dụng bảo vệ hệ sinh thái mẫu chuẩn, bảo tồn đa dạng sinh học và cảnh quan di sản thiên nhiên."}, {"id": "geography-12-vietnam-forestry-fisheries-q2", "prompt": "Hai mặt hàng thủy sản nuôi trồng xuất khẩu chủ lực mang lại kim ngạch hàng tỉ USD mỗi năm cho nước ta là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cá hồi và cá tầm ôn đới"}, {"id": "b", "text": "Rong biển tươi và cua đồng"}, {"id": "c", "text": "Tôm nước lợ và cá tra"}], "correctOptionId": "c", "explanation": "Đồng bằng sông Cửu Long là vựa tôm và cá tra lớn nhất nước, đóng góp phần lớn kim ngạch xuất khẩu thủy sản của Việt Nam."}, {"id": "geography-12-vietnam-industry-restructuring-q1", "prompt": "Nhóm ngành công nghiệp hiện đang chiếm tỉ trọng áp đảo và đóng vai trò động lực tăng trưởng chính của công nghiệp Việt Nam là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Công nghiệp khai thác than và quặng kim loại thô"}, {"id": "b", "text": "Công nghiệp đan lát thủ công gia đình"}, {"id": "c", "text": "Công nghiệp chế biến, chế tạo"}], "correctOptionId": "c", "explanation": "Công nghiệp chế biến, chế tạo đóng góp trên 80% giá trị sản xuất công nghiệp và là nguồn thu xuất khẩu lớn nhất của đất nước."}, {"id": "geography-12-vietnam-industry-restructuring-q2", "prompt": "Hai vùng kinh tế tập trung mật độ các khu công nghiệp và trung tâm công nghiệp quy mô lớn nhất cả nước là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Vùng Bắc Trung Bộ và Duyên hải Nam Trung Bộ"}, {"id": "b", "text": "Vùng Đông Nam Bộ và Vùng Đồng bằng sông Hồng"}, {"id": "c", "text": "Vùng Tây Nguyên và Vùng Tây Bắc"}], "correctOptionId": "b", "explanation": "Đông Nam Bộ và Đồng bằng sông Hồng hội tụ hạ tầng giao thông, cảng biển, nguồn nhân lực chất lượng cao và thị trường tiêu thụ lớn nhất nước."}, {"id": "geography-12-vietnam-energy-transition-q1", "prompt": "Nhà máy thủy điện có công suất lớn nhất Việt Nam và khu vực Đông Nam Á hiện nay là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Thủy điện Trị An"}, {"id": "b", "text": "Thủy điện Sơn La (trên sông Đà)"}, {"id": "c", "text": "Thủy điện Hòa Bình"}], "correctOptionId": "b", "explanation": "Thủy điện Sơn La có công suất thiết kế 2400 MW, khánh thành năm 2012, là công trình thủy điện lớn nhất Đông Nam Á."}, {"id": "geography-12-vietnam-energy-transition-q2", "prompt": "Hai tỉnh Duyên hải Nam Trung Bộ có tiềm năng bức xạ mặt trời và tốc độ gió lớn nhất, trở thành trung tâm năng lượng tái tạo của cả nước là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ninh Thuận và Bình Thuận"}, {"id": "b", "text": "Nam Định và Thái Bình"}, {"id": "c", "text": "Điện Biên và Lai Châu"}], "correctOptionId": "a", "explanation": "Ninh Thuận và Bình Thuận có số giờ nắng cao quanh năm và lượng gió ổn định, thu hút hàng loạt dự án điện mặt trời và điện gió quy mô lớn."}, {"id": "geography-12-vietnam-services-transport-tourism-q1", "prompt": "Tuyến đường bộ huyết mạch nối liền đất nước từ Bắc vào Nam dọc theo chiều dài dải đất non sông là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Quốc lộ 1A và đường cao tốc Bắc - Nam phía Đông"}, {"id": "b", "text": "Đường Hồ Chí Minh trên biển"}, {"id": "c", "text": "Tuyến đường vành đai biên giới số 4"}], "correctOptionId": "a", "explanation": "Quốc lộ 1A và tuyến cao tốc Bắc - Nam là trục xương sống giao thông vận tải đường bộ kết nối các trung tâm kinh tế từ Lạng Sơn đến Cà Mau."}, {"id": "geography-12-vietnam-services-transport-tourism-q2", "prompt": "Cụm cảng biển nước sâu quốc tế ở Đông Nam Bộ có khả năng tiếp nhận các siêu tàu container đi trực tiếp sang bờ Tây nước Mĩ là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cảng Cửa Lò (Nghệ An)"}, {"id": "b", "text": "Cảng Quy Nhơn (Bình Định)"}, {"id": "c", "text": "Cụm cảng Cái Mép - Thị Vải (Bà Rịa - Vũng Tàu)"}], "correctOptionId": "c", "explanation": "Cái Mép - Thị Vải có luồng sâu tự nhiên, là cửa ngõ xuất nhập khẩu hàng hải quốc tế hiện đại hàng đầu của Việt Nam."}, {"id": "geography-12-red-river-delta-development-q1", "prompt": "Thế mạnh vượt trội nhất về mặt nguồn nhân lực của vùng Đồng bằng sông Hồng so với các vùng khác là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Toàn bộ lao động chỉ có kinh nghiệm săn bắt thú hoang dã"}, {"id": "b", "text": "Chi phí thuê nhân công rẻ nhất trong toàn bộ khu vực"}, {"id": "c", "text": "Nguồn lao động rất dồi dào và có tỉ lệ lao động qua đào tạo cao nhất cả nước"}], "correctOptionId": "c", "explanation": "Vùng tập trung phần lớn các trường đại học, viện nghiên cứu lớn nên có mật độ tri thức và tay nghề kĩ thuật đứng đầu cả nước."}, {"id": "geography-12-red-river-delta-development-q2", "prompt": "Vụ sản xuất nông nghiệp đặc trưng tạo nên nét độc đáo của Đồng bằng sông Hồng nhờ có mùa đông lạnh là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Vụ mưa tuyết trồng cây cao su"}, {"id": "b", "text": "Vụ đông (trồng các loại rau màu ưa lạnh như khoai tây, su hào, bắp cải)"}, {"id": "c", "text": "Vụ hè thu trồng lúa nổi"}], "correctOptionId": "b", "explanation": "Mùa đông lạnh ở miền Bắc cho phép trồng các giống cây nguồn gốc cận nhiệt và ôn đới, biến vụ đông thành vụ hàng hóa có hiệu quả kinh tế cao."}, {"id": "geography-12-mekong-delta-climate-adaptation-q1", "prompt": "Vai trò quan trọng hàng đầu của vùng Đồng bằng sông Cửu Long đối với cả nước là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Là trung tâm luyện kim đen và chế tạo máy bay lớn nhất nước"}, {"id": "b", "text": "Là vùng trọng điểm sản xuất lương thực, thủy sản và trái cây lớn nhất, bảo đảm an ninh lương thực quốc gia và xuất khẩu"}, {"id": "c", "text": "Là vùng tập trung nhiều nhất các mỏ quặng sắt và than đá"}], "correctOptionId": "b", "explanation": "Đồng bằng sông Cửu Long chiếm hơn một nửa sản lượng lúa cả nước và cung cấp phần lớn sản lượng gạo xuất khẩu của Việt Nam."}, {"id": "geography-12-mekong-delta-climate-adaptation-q2", "prompt": "Thách thức môi trường tự nhiên gay gắt nhất đe dọa sinh kế của người dân Đồng bằng sông Cửu Long vào mùa khô hiện nay là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hiện tượng hạn hán kết hợp với xâm nhập mặn lấn sâu vào nội đồng"}, {"id": "b", "text": "Bão tuyết và rét đậm kéo dài nhiều tháng"}, {"id": "c", "text": "Núi lửa phun trào dung nham dọc các bờ kênh"}], "correctOptionId": "a", "explanation": "Lưu lượng dòng chảy thượng nguồn giảm làm nước biển theo triều dâng xâm nhập sâu hàng chục km vào các nhánh sông, làm thiếu nước ngọt sinh hoạt và tưới tiêu."}, {"id": "geography-12-southeast-region-growth-pole-q1", "prompt": "Đặc điểm nào sau đây khẳng định vị thế kinh tế số 1 của vùng Đông Nam Bộ ở Việt Nam?", "difficulty": "EASY", "options": [{"id": "a", "text": "Là vùng đóng góp tỉ trọng GDP và thu ngân sách nhà nước cao nhất cả nước"}, {"id": "b", "text": "Là vùng có diện tích đất tự nhiên rộng lớn nhất cả nước"}, {"id": "c", "text": "Là vùng có mật độ dân số thấp nhất trong tất cả các vùng"}], "correctOptionId": "a", "explanation": "Đông Nam Bộ là cực tăng trưởng kinh tế năng động nhất, dẫn đầu cả nước về quy mô kinh tế, thu hút vốn FDI và xuất khẩu."}, {"id": "geography-12-southeast-region-growth-pole-q2", "prompt": "Tài nguyên khoáng sản nổi bật ở thềm lục địa của vùng Đông Nam Bộ có ý nghĩa chiến lược quốc gia là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Than đá và than bùn"}, {"id": "b", "text": "Quặng sắt và bauxite"}, {"id": "c", "text": "Dầu mỏ và khí tự nhiên"}], "correctOptionId": "c", "explanation": "Các mỏ dầu khí lớn ngoài khơi Bà Rịa - Vũng Tàu (Bạch Hổ, Rạng Đông) là nguồn nguyên liệu cho công nghiệp năng lượng và hóa dầu."}, {"id": "geography-12-vietnam-marine-economy-q1", "prompt": "Nghị quyết 36-NQ/TW của Trung ương Đảng xác định ngành kinh tế biển nào giữ vị trí ưu tiên hàng đầu?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khai thác cát sỏi lòng biển làm vật liệu san lấp"}, {"id": "b", "text": "Chế biến dầu thô xuất khẩu"}, {"id": "c", "text": "Du lịch và dịch vụ biển"}], "correctOptionId": "c", "explanation": "Du lịch biển với bờ biển dài và hàng nghìn hòn đảo đẹp là ngành kinh tế có tiềm năng đột phá và lan tỏa nhanh nhất."}, {"id": "geography-12-vietnam-marine-economy-q2", "prompt": "Hệ thống các đảo và quần đảo của Việt Nam trên Biển Đông có ý nghĩa chiến lược to lớn về:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không có bất kì giá trị kinh tế nào do diện tích quá nhỏ"}, {"id": "b", "text": "Kinh tế biển, căn cứ tiến ra biển lớn và bảo đảm quốc phòng, an ninh bảo vệ Tổ quốc"}, {"id": "c", "text": "Chỉ dùng để làm nơi lưu giữ rác thải công nghiệp"}], "correctOptionId": "b", "explanation": "Hệ thống đảo tạo nên các tiền tiêu bảo vệ lãnh thổ, là điểm tựa cho ngư dân bám biển và xác định các vùng biển theo luật pháp quốc tế."}, {"id": "geography-12-environmental-sustainability-vietnam-q1", "prompt": "Tại Hội nghị biến đổi khí hậu COP26 (năm 2021), Thủ tướng Chính phủ Việt Nam đã đưa ra cam kết mạnh mẽ nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngừng hoàn toàn mọi hoạt động sản xuất công nghiệp vào năm 2025"}, {"id": "b", "text": "Đạt mức phát thải ròng bằng 0 (Net Zero) vào năm 2050"}, {"id": "c", "text": "Tăng gấp đôi lượng khí thải nhà kính vào năm 2030"}], "correctOptionId": "b", "explanation": "Cam kết Net Zero vào năm 2050 thể hiện trách nhiệm cao của Việt Nam trong nỗ lực toàn cầu ngăn chặn biến đổi khí hậu."}, {"id": "geography-12-environmental-sustainability-vietnam-q2", "prompt": "Mô hình ''Kinh tế tuần hoàn'' (Circular Economy) trong quản lí tài nguyên và môi trường hướng tới mục tiêu cốt lõi nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Kéo dài vòng đời của sản phẩm, tái sử dụng và tái chế chất thải thành tài nguyên, giảm thiểu phát thải ra môi trường"}, {"id": "b", "text": "Khai thác triệt để tài nguyên một lần rồi chôn lấp toàn bộ"}, {"id": "c", "text": "Tăng lượng rác thải nhựa không phân hủy sinh học ra sông hồ"}], "correctOptionId": "a", "explanation": "Kinh tế tuần hoàn thay thế mô hình kinh tế tuyến tính truyền thống (khai thác - sản xuất - vứt bỏ) bằng chu trình khép kín tài nguyên."}]'::jsonb,'[]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-vietnam-location-territory',1,'LESSON','Vị trí địa lí, phạm vi lãnh thổ và ý nghĩa chiến lược của Việt Nam','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Lãnh thổ Việt Nam nằm ở rìa phía đông của bán đảo Đông Dương, gần trung tâm khu vực Đông Nam Á. Tọa độ địa lí trên đất liền: điểm cực Bắc tại Lũng Cú (Hà Giang, 23°23''B), cực Nam tại Đất Mũi (Cà Mau, 8°34''B), cực Tây tại A Pa Chải (Điện Biên, 102°09''Đ), cực Đông tại Mũi Đôi (Khánh Hòa, 109°28''Đ). Vùng biển có diện tích khoảng 1 triệu km² với 5 bộ phận: nội thủy, lãnh hải (12 hải lí), vùng tiếp giáp lãnh hải, vùng đặc quyền kinh tế (200 hải lí) và thềm lục địa. Vị trí nằm trong vùng nội chí tuyến bán cầu Bắc mang lại khí hậu nhiệt đới ẩm gió mùa và vị thế địa - chính trị quan trọng."]'::jsonb,'["Mũi Đôi (Khánh Hòa) ở kinh độ 109°28''Đ là nơi đón ánh bình minh đầu tiên trên đất liền của Tổ quốc Việt Nam."]'::jsonb,'[{"id": "geography-12-vietnam-location-territory-q1", "prompt": "Điểm cực Bắc trên đất liền của nước ta thuộc xã Lũng Cú (huyện Đồng Văn, tỉnh Hà Giang) nằm ở vĩ độ nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "23°23''B"}, {"id": "b", "text": "8°34''B"}, {"id": "c", "text": "102°09''Đ"}], "correctOptionId": "a", "explanation": "Điểm cực Bắc tại Lũng Cú (Hà Giang) ở vĩ độ 23°23''B; điểm cực Nam tại Ngọc Hiển (Cà Mau) ở vĩ độ 8°34''B."}, {"id": "geography-12-vietnam-location-territory-q2", "prompt": "Vùng biển thuộc chủ quyền hoàn toàn và tuyệt đối của quốc gia ven biển, có chiều rộng 12 hải lí tính từ đường cơ sở gọi là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Nội thủy"}, {"id": "b", "text": "Vùng đặc quyền kinh tế"}, {"id": "c", "text": "Lãnh hải"}], "correctOptionId": "c", "explanation": "Theo Luật Biển Việt Nam và UNCLOS 1982, lãnh hải là vùng biển có chiều rộng 12 hải lí tính từ đường cơ sở ra phía biển, thuộc chủ quyền quốc gia."}, {"id": "geography-12-vietnam-location-territory-q3", "prompt": "Vị trí địa lí nằm ở ngã tư đường hàng hải và hàng không quốc tế mang lại cho Việt Nam thế mạnh kinh tế nổi bật nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Có khí hậu quanh năm băng giá thích hợp thể thao mùa đông"}, {"id": "b", "text": "Thuận lợi phát triển giao lưu kinh tế quốc tế, kinh tế biển, logistics và thu hút đầu tư nước ngoài"}, {"id": "c", "text": "Tránh được hoàn toàn mọi loại thiên tai bão nhiệt đới từ biển"}], "correctOptionId": "b", "explanation": "Nằm trên các tuyến hàng hải nhộn nhịp kết nối Ấn Độ Dương và Thái Bình Dương tạo điều kiện phát triển cảng biển nước sâu và mở cửa hội nhập."}]'::jsonb,'["geography-12-vietnam-location-territory"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-vietnam-relief-landforms',2,'LESSON','Đặc điểm địa hình và sự phân hóa cảnh quan tự nhiên Việt Nam','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Địa hình nước ta có 4 đặc điểm cơ bản: Đồi núi chiếm 3/4 diện tích nhưng chủ yếu là đồi núi thấp (dưới 1000m chiếm 85%, núi cao trên 2000m chỉ chiếm 1%); cấu trúc địa hình được Tân kiến tạo trẻ hóa, có tính phân bậc rõ rệt; hướng nghiêng chung là tây bắc - đông nam; hai hướng núi chính là tây bắc - đông nam (vùng Tây Bắc, Trường Sơn Bắc) và vòng cung (vùng Đông Bắc, Trường Sơn Nam). Địa hình chia thành các khu vực: đồi núi (Đông Bắc, Tây Bắc, Trường Sơn Bắc, Trường Sơn Nam) và đồng bằng (Đồng bằng sông Hồng, Đồng bằng sông Cửu Long, dải đồng bằng ven biển miền Trung)."]'::jsonb,'["Dãy Hoàng Liên Sơn với đỉnh Fansipan cao 3143 m được mệnh danh là ''nóc nhà Đông Dương'', thuộc vùng núi Tây Bắc có hướng nghiêng tây bắc - đông nam."]'::jsonb,'[{"id": "geography-12-vietnam-relief-landforms-q1", "prompt": "Đặc điểm nào sau đây phản ánh đúng nhất cấu trúc cơ bản của địa hình đồi núi Việt Nam?", "difficulty": "EASY", "options": [{"id": "a", "text": "Địa hình chủ yếu là núi cao hiểm trở trên 3000 m chiếm hơn một nửa diện tích"}, {"id": "b", "text": "Đồng bằng châu thổ chiếm tới 75% toàn bộ diện tích đất liền"}, {"id": "c", "text": "Đồi núi chiếm 3/4 diện tích lãnh thổ, nhưng chủ yếu là đồi núi thấp dưới 1000 m"}], "correctOptionId": "c", "explanation": "Đồi núi thấp dưới 1000 m chiếm tới 85% diện tích cả nước, núi cao trên 2000 m chỉ chiếm khoảng 1%."}, {"id": "geography-12-vietnam-relief-landforms-q2", "prompt": "Hai hướng núi chính thể hiện rõ nét nhất trong cấu trúc sơn văn của lãnh thổ Việt Nam là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hướng đông bắc - tây nam và hướng kinh tuyến"}, {"id": "b", "text": "Hướng tây bắc - đông nam và hướng vòng cung"}, {"id": "c", "text": "Hướng bắc - nam và hướng đông - tây"}], "correctOptionId": "b", "explanation": "Các dãy núi Tây Bắc và Trường Sơn Bắc có hướng tây bắc - đông nam; vùng núi Đông Bắc có 4 cánh cung lớn chụm đầu ở Tam Đảo."}, {"id": "geography-12-vietnam-relief-landforms-q3", "prompt": "Sự tương phản sâu sắc về tự nhiên giữa vùng núi Đông Bắc và Tây Bắc nước ta thể hiện ở chỗ:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Đông Bắc đón gió mùa đông bắc sâu sắc nên mùa đông đến sớm và lạnh nhất cả nước; Tây Bắc có địa hình cao chắn gió nên mùa đông ấm hơn ở vùng thấp"}, {"id": "b", "text": "Đông Bắc chỉ có đồng bằng ven biển không có đồi núi"}, {"id": "c", "text": "Tây Bắc có lượng mưa gấp mười lần Đông Bắc trong suốt mùa đông"}], "correctOptionId": "a", "explanation": "Các cánh cung mở rộng về phía bắc ở Đông Bắc tạo điều kiện cho gió mùa Đông Bắc tràn sâu; dãy Hoàng Liên Sơn đồ sộ ngăn bớt ảnh hưởng của gió lạnh sang Tây Bắc."}]'::jsonb,'["geography-12-vietnam-relief-landforms"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-vietnam-tropical-monsoon-climate',3,'LESSON','Khí hậu nhiệt đới ẩm gió mùa và tài nguyên khí hậu','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Tính chất nhiệt đới: tổng bức xạ lớn, cân bằng bức xạ dương quanh năm, nhiệt độ trung bình năm trên 20 °C (trừ vùng núi cao), số giờ nắng 1400 - 3000 giờ/năm. Tính chất ẩm: lượng mưa lớn trung bình 1500 - 2000 mm/năm, độ ẩm không khí cao trên 80%. Tính chất gió mùa: gió mùa mùa đông (gió mùa Đông Bắc từ tháng 11 đến tháng 4 năm sau; nửa đầu đông lạnh khô, nửa sau đông lạnh ẩm có mưa phùn) và gió mùa mùa hạ (gió Tây Nam từ tháng 5 đến tháng 10; đầu mùa gây mưa cho Nam Bộ, Tây Nguyên và gây hiệu ứng phơn khô nóng ở Trung Bộ; giữa và cuối mùa gió tây nam kết hợp dải hội tụ gây mưa lớn cả nước)."]'::jsonb,'["Hiện tượng gió phơn Tây Nam (gió Lào) thổi vượt qua dãy Trường Sơn khiến khu vực Bắc Trung Bộ vào đầu mùa hạ có những đợt nắng nóng gay gắt trên 39 °C với độ ẩm giảm dưới 45%."]'::jsonb,'[{"id": "geography-12-vietnam-tropical-monsoon-climate-q1", "prompt": "Biểu hiện rõ nét nhất của tính chất nhiệt đới trong khí hậu Việt Nam là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Lượng mưa hàng năm rất thấp dưới 200 mm giống như hoang mạc"}, {"id": "b", "text": "Nhiệt độ trung bình năm trên hầu khắp cả nước đều vượt 20 °C và tổng số giờ nắng dồi dào"}, {"id": "c", "text": "Quanh năm luôn có bão tuyết và nhiệt độ âm"}], "correctOptionId": "b", "explanation": "Nhờ nằm hoàn toàn trong vùng nội chí tuyến, lãnh thổ nhận được lượng bức xạ mặt trời lớn, cân bằng bức xạ dương quanh năm."}, {"id": "geography-12-vietnam-tropical-monsoon-climate-q2", "prompt": "Đặc điểm thời tiết nổi bật của miền Bắc nước ta vào nửa sau mùa đông (từ tháng 2 đến tháng 4) là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thời tiết lạnh ẩm và có mưa phùn"}, {"id": "b", "text": "Thời tiết khô hanh, trời quang mây và không mưa"}, {"id": "c", "text": "Nắng nóng gay gắt kéo dài nhiều tuần liên tiếp"}], "correctOptionId": "a", "explanation": "Nửa sau mùa đông khối không khí lạnh lệch đông đi qua biển vào đất liền mang theo lượng ẩm lớn, gây thời tiết lạnh ẩm và mưa phùn rải rác."}, {"id": "geography-12-vietnam-tropical-monsoon-climate-q3", "prompt": "Hiệu ứng phơn khô nóng (gió Lào) thường xuất hiện vào đầu mùa hạ ở vùng Bắc Trung Bộ do nguyên nhân địa lí nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Gió mùa Đông Bắc mang hơi nước từ biển vào đất liền"}, {"id": "b", "text": "Bão nhiệt đới gây lốc xoáy làm tăng nhiệt độ không khí"}, {"id": "c", "text": "Gió mùa Tây Nam vượt qua các dãy núi Trường Sơn bị chắn lại gây mưa ở sườn tây, khi sang sườn đông bị biến tính trở nên khô nóng"}], "correctOptionId": "c", "explanation": "Không khí ẩm khi leo lên sườn tây dãy núi bị ngưng tụ gây mưa, khi hạ xuống sườn đông nhiệt độ tăng theo độ dốc đoạn nhiệt khô (100m tăng 1 °C) tạo gió rất khô nóng."}]'::jsonb,'["geography-12-vietnam-tropical-monsoon-climate"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-vietnam-population-demographics',4,'LESSON','Dân số, cơ cấu dân số và sự phân bố dân cư Việt Nam','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Dân số Việt Nam đã vượt mốc 100 triệu người (đứng thứ 3 Đông Nam Á, thứ 15 thế giới). Nước ta đang trong thời kì ''cơ cấu dân số vàng'' (tỉ lệ người trong độ tuổi lao động từ 15-64 tuổi chiếm trên 65%) nhưng đồng thời tốc độ già hóa dân số diễn ra rất nhanh. Cơ cấu lao động theo ngành chuyển dịch tích cực: giảm tỉ trọng nông - lâm - thủy sản, tăng tỉ trọng công nghiệp - xây dựng và dịch vụ. Phân bố dân cư không đều: tập trung đông đúc ở đồng bằng và đô thị (Đồng bằng sông Hồng mật độ trên 1000 người/km²), thưa thớt ở vùng đồi núi (Tây Bắc, Tây Nguyên dưới 100 người/km²)."]'::jsonb,'["Vùng Đồng bằng sông Hồng có mật độ dân số cao gấp gần 10 lần mức trung bình của cả nước, tạo áp lực lớn lên nhà ở, việc làm và môi trường đô thị."]'::jsonb,'[{"id": "geography-12-vietnam-population-demographics-q1", "prompt": "Quy mô dân số Việt Nam hiện nay đã chính thức vượt qua mốc dân số nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Trên 100 triệu người"}, {"id": "b", "text": "Khoảng 50 triệu người"}, {"id": "c", "text": "Trên 200 triệu người"}], "correctOptionId": "a", "explanation": "Năm 2023, dân số Việt Nam đã chính thức vượt qua mốc 100 triệu người, xếp thứ 3 ở Đông Nam Á sau Indonesia và Philippines."}, {"id": "geography-12-vietnam-population-demographics-q2", "prompt": "Cơ hội phát triển kinh tế - xã hội lớn nhất do thời kì ''cơ cấu dân số vàng'' mang lại cho nước ta là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Làm giảm chi phí đầu tư cho hệ thống giáo dục tiểu học về mức 0"}, {"id": "b", "text": "Loại bỏ hoàn toàn vấn đề thất nghiệp ở các vùng đô thị"}, {"id": "c", "text": "Cung cấp lực lượng lao động trẻ dồi dào, thúc đẩy tăng trưởng kinh tế nhanh nếu được đào tạo tốt"}], "correctOptionId": "c", "explanation": "Dân số vàng nghĩa là cứ hai người đi làm nuôi dưới một người phụ thuộc, tạo lợi thế lớn về năng suất và tích lũy vốn phát triển."}, {"id": "geography-12-vietnam-population-demographics-q3", "prompt": "Sự phân bố dân cư không đồng đều giữa vùng đồng bằng và miền núi ở Việt Nam gây ra khó khăn chủ yếu nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Khiến mọi con sông ở đồng bằng đều bị nhiễm mặn quanh năm"}, {"id": "b", "text": "Nơi đồng bằng đất chật người đông gây áp lực việc làm, còn miền núi giàu tài nguyên lại thiếu hụt lao động"}, {"id": "c", "text": "Làm cho nguồn tài nguyên khoáng sản ở miền núi bị cạn kiệt trong thời gian ngắn"}], "correctOptionId": "b", "explanation": "Mật độ dân số chênh lệch lớn cản trở việc khai thác hợp lí tiềm năng kinh tế phong phú của vùng núi và gây sức ép hạ tầng tại đồng bằng."}]'::jsonb,'["geography-12-vietnam-population-demographics"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-vietnam-urbanization-process',5,'LESSON','Quá trình đô thị hóa và mạng lưới đô thị ở Việt Nam','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Đặc điểm đô thị hóa ở Việt Nam: diễn ra với tốc độ nhanh nhưng trình độ đô thị hóa còn thấp so với các nước trong khu vực (tỉ lệ dân thành thị đạt khoảng 42%); mạng lưới đô thị phân bố không đều, tập trung nhiều ở các vùng đồng bằng và ven biển. Phân loại đô thị gồm: 2 đô thị loại đặc biệt (Hà Nội, TP. Hồ Chí Minh), đô thị loại I, II, III, IV, V. Đô thị đóng vai trò là hạt nhân thúc đẩy tăng trưởng kinh tế, chuyển dịch cơ cấu và đổi mới sáng tạo, nhưng đối mặt với thách thức ùn tắc giao thông, ô nhiễm môi trường và ngập úng."]'::jsonb,'["Hà Nội và TP. Hồ Chí Minh là hai cực tăng trưởng kinh tế lớn nhất, đóng góp hơn 45% tổng thu ngân sách nhà nước của cả nước."]'::jsonb,'[{"id": "geography-12-vietnam-urbanization-process-q1", "prompt": "Hai đô thị trực thuộc trung ương được xếp vào cấp đô thị loại đặc biệt ở Việt Nam là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Đà Nẵng và Hải Phòng"}, {"id": "b", "text": "Cần Thơ và Nha Trang"}, {"id": "c", "text": "Hà Nội và Thành phố Hồ Chí Minh"}], "correctOptionId": "c", "explanation": "Hà Nội (thủ đô) và TP. Hồ Chí Minh (đầu tàu kinh tế phía Nam) là hai đô thị loại đặc biệt của cả nước."}, {"id": "geography-12-vietnam-urbanization-process-q2", "prompt": "Đặc điểm cơ bản của quá trình đô thị hóa ở Việt Nam hiện nay là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Các đô thị hoàn toàn không có sự đóng góp nào vào nguồn thu ngân sách"}, {"id": "b", "text": "Tốc độ đô thị hóa diễn ra nhanh nhưng trình độ đô thị hóa nhìn chung vẫn còn thấp"}, {"id": "c", "text": "Tỉ lệ dân số thành thị đã chiếm trên 90% tổng số dân cả nước"}], "correctOptionId": "b", "explanation": "Dù tỉ lệ dân thành thị tăng đều đặn qua các năm nhưng chất lượng cơ sở hạ tầng và dịch vụ đô thị còn nhiều hạn chế."}, {"id": "geography-12-vietnam-urbanization-process-q3", "prompt": "Tác động tích cực hàng đầu của mạng lưới đô thị đối với sự phát triển kinh tế - xã hội các vùng là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Đóng vai trò là các cực tăng trưởng, lan tỏa công nghiệp hóa, hiện đại hóa và thu hút vốn đầu tư"}, {"id": "b", "text": "Làm tăng tỉ trọng nông nghiệp truyền thống trong cơ cấu GDP vùng"}, {"id": "c", "text": "Làm giảm nhu cầu sử dụng mạng lưới điện và viễn thông quốc gia"}], "correctOptionId": "a", "explanation": "Đô thị là trung tâm dịch vụ, công nghiệp, đào tạo nhân lực và thị trường tiêu thụ thúc đẩy kinh tế các vùng phụ cận cùng phát triển."}]'::jsonb,'["geography-12-vietnam-urbanization-process"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-review-1',6,'FIVE_LESSON_REVIEW','Ôn tập 1','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "geography-12-vietnam-location-territory-q1", "prompt": "Điểm cực Bắc trên đất liền của nước ta thuộc xã Lũng Cú (huyện Đồng Văn, tỉnh Hà Giang) nằm ở vĩ độ nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "23°23''B"}, {"id": "b", "text": "8°34''B"}, {"id": "c", "text": "102°09''Đ"}], "correctOptionId": "a", "explanation": "Điểm cực Bắc tại Lũng Cú (Hà Giang) ở vĩ độ 23°23''B; điểm cực Nam tại Ngọc Hiển (Cà Mau) ở vĩ độ 8°34''B."}, {"id": "geography-12-vietnam-location-territory-q2", "prompt": "Vùng biển thuộc chủ quyền hoàn toàn và tuyệt đối của quốc gia ven biển, có chiều rộng 12 hải lí tính từ đường cơ sở gọi là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Nội thủy"}, {"id": "b", "text": "Vùng đặc quyền kinh tế"}, {"id": "c", "text": "Lãnh hải"}], "correctOptionId": "c", "explanation": "Theo Luật Biển Việt Nam và UNCLOS 1982, lãnh hải là vùng biển có chiều rộng 12 hải lí tính từ đường cơ sở ra phía biển, thuộc chủ quyền quốc gia."}, {"id": "geography-12-vietnam-relief-landforms-q1", "prompt": "Đặc điểm nào sau đây phản ánh đúng nhất cấu trúc cơ bản của địa hình đồi núi Việt Nam?", "difficulty": "EASY", "options": [{"id": "a", "text": "Địa hình chủ yếu là núi cao hiểm trở trên 3000 m chiếm hơn một nửa diện tích"}, {"id": "b", "text": "Đồng bằng châu thổ chiếm tới 75% toàn bộ diện tích đất liền"}, {"id": "c", "text": "Đồi núi chiếm 3/4 diện tích lãnh thổ, nhưng chủ yếu là đồi núi thấp dưới 1000 m"}], "correctOptionId": "c", "explanation": "Đồi núi thấp dưới 1000 m chiếm tới 85% diện tích cả nước, núi cao trên 2000 m chỉ chiếm khoảng 1%."}, {"id": "geography-12-vietnam-relief-landforms-q2", "prompt": "Hai hướng núi chính thể hiện rõ nét nhất trong cấu trúc sơn văn của lãnh thổ Việt Nam là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hướng đông bắc - tây nam và hướng kinh tuyến"}, {"id": "b", "text": "Hướng tây bắc - đông nam và hướng vòng cung"}, {"id": "c", "text": "Hướng bắc - nam và hướng đông - tây"}], "correctOptionId": "b", "explanation": "Các dãy núi Tây Bắc và Trường Sơn Bắc có hướng tây bắc - đông nam; vùng núi Đông Bắc có 4 cánh cung lớn chụm đầu ở Tam Đảo."}, {"id": "geography-12-vietnam-tropical-monsoon-climate-q1", "prompt": "Biểu hiện rõ nét nhất của tính chất nhiệt đới trong khí hậu Việt Nam là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Lượng mưa hàng năm rất thấp dưới 200 mm giống như hoang mạc"}, {"id": "b", "text": "Nhiệt độ trung bình năm trên hầu khắp cả nước đều vượt 20 °C và tổng số giờ nắng dồi dào"}, {"id": "c", "text": "Quanh năm luôn có bão tuyết và nhiệt độ âm"}], "correctOptionId": "b", "explanation": "Nhờ nằm hoàn toàn trong vùng nội chí tuyến, lãnh thổ nhận được lượng bức xạ mặt trời lớn, cân bằng bức xạ dương quanh năm."}, {"id": "geography-12-vietnam-tropical-monsoon-climate-q2", "prompt": "Đặc điểm thời tiết nổi bật của miền Bắc nước ta vào nửa sau mùa đông (từ tháng 2 đến tháng 4) là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Thời tiết lạnh ẩm và có mưa phùn"}, {"id": "b", "text": "Thời tiết khô hanh, trời quang mây và không mưa"}, {"id": "c", "text": "Nắng nóng gay gắt kéo dài nhiều tuần liên tiếp"}], "correctOptionId": "a", "explanation": "Nửa sau mùa đông khối không khí lạnh lệch đông đi qua biển vào đất liền mang theo lượng ẩm lớn, gây thời tiết lạnh ẩm và mưa phùn rải rác."}, {"id": "geography-12-vietnam-population-demographics-q1", "prompt": "Quy mô dân số Việt Nam hiện nay đã chính thức vượt qua mốc dân số nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Trên 100 triệu người"}, {"id": "b", "text": "Khoảng 50 triệu người"}, {"id": "c", "text": "Trên 200 triệu người"}], "correctOptionId": "a", "explanation": "Năm 2023, dân số Việt Nam đã chính thức vượt qua mốc 100 triệu người, xếp thứ 3 ở Đông Nam Á sau Indonesia và Philippines."}, {"id": "geography-12-vietnam-population-demographics-q2", "prompt": "Cơ hội phát triển kinh tế - xã hội lớn nhất do thời kì ''cơ cấu dân số vàng'' mang lại cho nước ta là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Làm giảm chi phí đầu tư cho hệ thống giáo dục tiểu học về mức 0"}, {"id": "b", "text": "Loại bỏ hoàn toàn vấn đề thất nghiệp ở các vùng đô thị"}, {"id": "c", "text": "Cung cấp lực lượng lao động trẻ dồi dào, thúc đẩy tăng trưởng kinh tế nhanh nếu được đào tạo tốt"}], "correctOptionId": "c", "explanation": "Dân số vàng nghĩa là cứ hai người đi làm nuôi dưới một người phụ thuộc, tạo lợi thế lớn về năng suất và tích lũy vốn phát triển."}, {"id": "geography-12-vietnam-urbanization-process-q1", "prompt": "Hai đô thị trực thuộc trung ương được xếp vào cấp đô thị loại đặc biệt ở Việt Nam là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Đà Nẵng và Hải Phòng"}, {"id": "b", "text": "Cần Thơ và Nha Trang"}, {"id": "c", "text": "Hà Nội và Thành phố Hồ Chí Minh"}], "correctOptionId": "c", "explanation": "Hà Nội (thủ đô) và TP. Hồ Chí Minh (đầu tàu kinh tế phía Nam) là hai đô thị loại đặc biệt của cả nước."}, {"id": "geography-12-vietnam-urbanization-process-q2", "prompt": "Đặc điểm cơ bản của quá trình đô thị hóa ở Việt Nam hiện nay là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Các đô thị hoàn toàn không có sự đóng góp nào vào nguồn thu ngân sách"}, {"id": "b", "text": "Tốc độ đô thị hóa diễn ra nhanh nhưng trình độ đô thị hóa nhìn chung vẫn còn thấp"}, {"id": "c", "text": "Tỉ lệ dân số thành thị đã chiếm trên 90% tổng số dân cả nước"}], "correctOptionId": "b", "explanation": "Dù tỉ lệ dân thành thị tăng đều đặn qua các năm nhưng chất lượng cơ sở hạ tầng và dịch vụ đô thị còn nhiều hạn chế."}]'::jsonb,'["geography-12-vietnam-location-territory", "geography-12-vietnam-relief-landforms", "geography-12-vietnam-tropical-monsoon-climate", "geography-12-vietnam-population-demographics", "geography-12-vietnam-urbanization-process"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-vietnam-agriculture-restructuring',7,'LESSON','Chuyển dịch cơ cấu ngành nông nghiệp theo hướng hàng hóa, sinh thái','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Nông nghiệp Việt Nam đang chuyển đổi mạnh mẽ từ ''tư duy sản xuất nông nghiệp'' sang ''tư duy kinh tế nông nghiệp'' tích hợp đa giá trị. Cơ cấu trồng trọt: giảm tỉ trọng lúa gạo phẩm cấp thấp, tăng diện tích cây ăn quả nhiệt đới (sầu riêng, thanh long, xoài) và cây công nghiệp lâu năm giá trị cao (cà phê, cao su, hồ tiêu, điều); mở rộng diện tích nông nghiệp hữu cơ, ứng dụng công nghệ cao (tưới nhỏ giọt, nhà màng). Chăn nuôi chuyển từ quy mô nhỏ lẻ sang trang trại tập trung công nghiệp, an toàn sinh học."]'::jsonb,'["Mô hình trồng bưởi da xanh và sầu riêng chuyên canh xuất khẩu tại Tiền Giang và Bến Tre mang lại doanh thu hàng trăm triệu đồng trên mỗi hecta, gấp nhiều lần trồng lúa truyền thống."]'::jsonb,'[{"id": "geography-12-vietnam-agriculture-restructuring-q1", "prompt": "Xu hướng chuyển dịch cơ cấu nội bộ ngành trồng trọt của nước ta hiện nay là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Chuyển toàn bộ diện tích đất nông nghiệp sang khai thác mỏ khoáng sản"}, {"id": "b", "text": "Giảm tỉ trọng cây lương thực phẩm cấp thấp, tăng tỉ trọng cây công nghiệp lâu năm và cây ăn quả chất lượng cao"}, {"id": "c", "text": "Xóa bỏ hoàn toàn diện tích trồng lúa để trồng toàn bộ cỏ chăn nuôi"}], "correctOptionId": "b", "explanation": "Tái cơ cấu trồng trọt tập trung vào nâng cao giá trị gia tăng, đáp ứng tiêu chuẩn xuất khẩu và thích ứng biến đổi khí hậu."}, {"id": "geography-12-vietnam-agriculture-restructuring-q2", "prompt": "Vùng chuyên canh cây cà phê lớn nhất của Việt Nam, đưa nước ta trở thành quốc gia xuất khẩu cà phê Robusta hàng đầu thế giới là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Vùng Tây Nguyên"}, {"id": "b", "text": "Vùng Đồng bằng sông Hồng"}, {"id": "c", "text": "Vùng Bắc Trung Bộ"}], "correctOptionId": "a", "explanation": "Tây Nguyên có diện tích đất đỏ bazan màu mỡ và khí hậu cận xích đạo rất thích hợp hình thành các vùng chuyên canh cà phê quy mô lớn."}, {"id": "geography-12-vietnam-agriculture-restructuring-q3", "prompt": "Việc áp dụng công nghệ tưới tiết kiệm nhỏ giọt Israel và nhà màng trong sản xuất nông nghiệp công nghệ cao nhằm mục đích chủ yếu gì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Làm tăng chi phí sản xuất lên mức tối đa mà không cần thu hoạch"}, {"id": "b", "text": "Biến đổi mọi giống cây nhiệt đới thành cây ôn đới tuyết phủ"}, {"id": "c", "text": "Chủ động điều tiết nước và phân bón, giảm thiểu sâu bệnh, tiết kiệm tài nguyên và nâng cao năng suất sản phẩm"}], "correctOptionId": "c", "explanation": "Nông nghiệp công nghệ cao tối ưu hóa dinh dưỡng và nước tưới theo nhu cầu sinh trưởng của cây, nâng cao chất lượng nông sản sạch xuất khẩu."}]'::jsonb,'["geography-12-vietnam-agriculture-restructuring"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-vietnam-forestry-fisheries',8,'LESSON','Phát triển lâm nghiệp và thủy sản bền vững','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Lâm nghiệp có cơ cấu gồm quản lí, bảo vệ, khoanh nuôi và phát triển rừng. Ba loại rừng: rừng đặc dụng (bảo tồn gene, vườn quốc gia), rừng phòng hộ (đầu nguồn, chắn sóng ven biển), rừng sản xuất (cung cấp gỗ, lâm sản). Chính sách đóng cửa rừng tự nhiên và đẩy mạnh trồng rừng gỗ lớn có chứng chỉ FSC. Ngành thủy sản: đường bờ biển dài 3260 km, 4 ngư trường trọng điểm; đẩy mạnh nuôi trồng thủy sản nước ngọt, lợ, mặn (tôm nước lợ, cá tra); khắc phục ''thẻ vàng'' IUU qua giám sát hành trình tàu cá, phát triển nghề cá có trách nhiệm."]'::jsonb,'["Ngành nuôi và chế biến tôm xuất khẩu tại Cà Mau, Bạc Liêu áp dụng mô hình tôm - rừng ngập mặn sinh thái đạt chứng nhận quốc tế, vừa giữ rừng vừa đạt giá trị kinh tế cao."]'::jsonb,'[{"id": "geography-12-vietnam-forestry-fisheries-q1", "prompt": "Loại rừng nào sau đây có chức năng chủ yếu là bảo tồn nguồn gene sinh vật quý hiếm và nghiên cứu khoa học?", "difficulty": "EASY", "options": [{"id": "a", "text": "Rừng đặc dụng (các vườn quốc gia, khu bảo tồn thiên nhiên)"}, {"id": "b", "text": "Rừng sản xuất lấy gỗ"}, {"id": "c", "text": "Rừng trồng bạch đàn thương phẩm"}], "correctOptionId": "a", "explanation": "Rừng đặc dụng bảo vệ hệ sinh thái mẫu chuẩn, bảo tồn đa dạng sinh học và cảnh quan di sản thiên nhiên."}, {"id": "geography-12-vietnam-forestry-fisheries-q2", "prompt": "Hai mặt hàng thủy sản nuôi trồng xuất khẩu chủ lực mang lại kim ngạch hàng tỉ USD mỗi năm cho nước ta là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cá hồi và cá tầm ôn đới"}, {"id": "b", "text": "Rong biển tươi và cua đồng"}, {"id": "c", "text": "Tôm nước lợ và cá tra"}], "correctOptionId": "c", "explanation": "Đồng bằng sông Cửu Long là vựa tôm và cá tra lớn nhất nước, đóng góp phần lớn kim ngạch xuất khẩu thủy sản của Việt Nam."}, {"id": "geography-12-vietnam-forestry-fisheries-q3", "prompt": "Nhiệm vụ cấp bách hàng đầu của ngành khai thác hải sản xa bờ Việt Nam nhằm gỡ bỏ cảnh báo ''thẻ vàng'' của Ủy ban châu Âu (EC) là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Đóng cửa các cảng cá và cấm xuất khẩu hải sản sang mọi châu lục"}, {"id": "b", "text": "Chấm dứt hoàn toàn tình trạng khai thác hải sản bất hợp pháp, không báo cáo và không theo quy định (IUU)"}, {"id": "c", "text": "Ngừng hoàn toàn hoạt động đánh bắt cá của tất cả ngư dân trên biển"}], "correctOptionId": "b", "explanation": "Gỡ thẻ vàng IUU đòi hỏi lắp đặt 100% thiết bị giám sát hành trình (VMS), truy xuất nguồn gốc thủy sản và xử lí nghiêm vi phạm vùng biển nước ngoài."}]'::jsonb,'["geography-12-vietnam-forestry-fisheries"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-vietnam-industry-restructuring',9,'LESSON','Chuyển dịch cơ cấu ngành công nghiệp và phát triển công nghiệp xanh','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Cơ cấu ngành công nghiệp dịch chuyển theo hướng hiện đại: giảm tỉ trọng công nghiệp khai khoáng, tăng nhanh tỉ trọng công nghiệp chế biến - chế tạo và công nghiệp công nghệ cao (điện tử, máy vi tính, viễn thông, linh kiện bán dẫn). Giảm thâm dụng lao động phổ thông, chuyển dịch sang tự động hóa, chuyển đổi số và kinh tế xanh. Không gian công nghiệp hình thành các trung tâm công nghiệp lớn (Hà Nội - Hải Phòng - Quảng Ninh ở phía Bắc; TP. Hồ Chí Minh - Bình Dương - Đồng Nai - Bà Rịa - Vũng Tàu ở phía Nam) gắn với các khu công nghiệp sinh thái."]'::jsonb,'["Sự hình thành các tổ hợp sản xuất vi mạch bán dẫn và thiết bị di động của các tập đoàn công nghệ toàn cầu tại Bắc Ninh, Thái Nguyên, TP. Hồ Chí Minh đưa Việt Nam vào chuỗi giá trị công nghệ cao."]'::jsonb,'[{"id": "geography-12-vietnam-industry-restructuring-q1", "prompt": "Nhóm ngành công nghiệp hiện đang chiếm tỉ trọng áp đảo và đóng vai trò động lực tăng trưởng chính của công nghiệp Việt Nam là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Công nghiệp khai thác than và quặng kim loại thô"}, {"id": "b", "text": "Công nghiệp đan lát thủ công gia đình"}, {"id": "c", "text": "Công nghiệp chế biến, chế tạo"}], "correctOptionId": "c", "explanation": "Công nghiệp chế biến, chế tạo đóng góp trên 80% giá trị sản xuất công nghiệp và là nguồn thu xuất khẩu lớn nhất của đất nước."}, {"id": "geography-12-vietnam-industry-restructuring-q2", "prompt": "Hai vùng kinh tế tập trung mật độ các khu công nghiệp và trung tâm công nghiệp quy mô lớn nhất cả nước là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Vùng Bắc Trung Bộ và Duyên hải Nam Trung Bộ"}, {"id": "b", "text": "Vùng Đông Nam Bộ và Vùng Đồng bằng sông Hồng"}, {"id": "c", "text": "Vùng Tây Nguyên và Vùng Tây Bắc"}], "correctOptionId": "b", "explanation": "Đông Nam Bộ và Đồng bằng sông Hồng hội tụ hạ tầng giao thông, cảng biển, nguồn nhân lực chất lượng cao và thị trường tiêu thụ lớn nhất nước."}, {"id": "geography-12-vietnam-industry-restructuring-q3", "prompt": "Mục tiêu phát triển các ''Khu công nghiệp sinh thái'' (Eco-Industrial Park) trong định hướng công nghiệp xanh ở Việt Nam là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Áp dụng kinh tế tuần hoàn, tận dụng chất thải của nhà máy này làm nguyên liệu cho nhà máy khác và giảm phát thải carbon"}, {"id": "b", "text": "Chỉ cho phép trồng cây ăn quả bên trong khuôn viên nhà xưởng"}, {"id": "c", "text": "Ngừng sử dụng toàn bộ máy móc cơ khí và chuyển sang làm thủ công"}], "correctOptionId": "a", "explanation": "Khu công nghiệp sinh thái tối ưu hóa tài nguyên qua cộng sinh công nghiệp, giảm thiểu ô nhiễm và hướng tới tiêu chuẩn phát thải ròng bằng 0."}]'::jsonb,'["geography-12-vietnam-industry-restructuring"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-vietnam-energy-transition',10,'LESSON','Phát triển ngành năng lượng và chuyển dịch năng lượng tái tạo','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Ngành năng lượng là huyết mạch bảo đảm an ninh năng lượng quốc gia. Cơ cấu nguồn điện trước đây dựa vào thủy điện (Sơn La, Hòa Bình) và nhiệt điện than, khí. Thực hiện cam kết quốc tế đạt phát thải ròng bằng 0 (Net Zero) vào năm 2050 theo Quy hoạch điện VIII, Việt Nam đang đẩy mạnh chuyển dịch năng lượng công bằng (JETP): hạn chế nhiệt điện than, phát triển nhiệt điện khí LNG, bùng nổ năng lượng tái tạo (điện gió trên bờ và ngoài khơi, điện mặt trời, điện sinh khối) và hiện đại hóa lưới điện thông minh."]'::jsonb,'["Các cánh đồng điện gió ngoài khơi tại Bạc Liêu, Sóc Trăng và các dự án điện mặt trời tại Ninh Thuận, Bình Thuận đã bổ sung hàng tỉ kWh điện sạch vào lưới điện quốc gia mỗi năm."]'::jsonb,'[{"id": "geography-12-vietnam-energy-transition-q1", "prompt": "Nhà máy thủy điện có công suất lớn nhất Việt Nam và khu vực Đông Nam Á hiện nay là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Thủy điện Trị An"}, {"id": "b", "text": "Thủy điện Sơn La (trên sông Đà)"}, {"id": "c", "text": "Thủy điện Hòa Bình"}], "correctOptionId": "b", "explanation": "Thủy điện Sơn La có công suất thiết kế 2400 MW, khánh thành năm 2012, là công trình thủy điện lớn nhất Đông Nam Á."}, {"id": "geography-12-vietnam-energy-transition-q2", "prompt": "Hai tỉnh Duyên hải Nam Trung Bộ có tiềm năng bức xạ mặt trời và tốc độ gió lớn nhất, trở thành trung tâm năng lượng tái tạo của cả nước là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ninh Thuận và Bình Thuận"}, {"id": "b", "text": "Nam Định và Thái Bình"}, {"id": "c", "text": "Điện Biên và Lai Châu"}], "correctOptionId": "a", "explanation": "Ninh Thuận và Bình Thuận có số giờ nắng cao quanh năm và lượng gió ổn định, thu hút hàng loạt dự án điện mặt trời và điện gió quy mô lớn."}, {"id": "geography-12-vietnam-energy-transition-q3", "prompt": "Xu hướng chuyển dịch năng lượng theo Quy hoạch phát triển điện lực quốc gia (Quy hoạch điện VIII) hướng tới cam kết Net Zero năm 2050 là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Tăng tối đa việc xây dựng thêm các nhà máy nhiệt điện đốt than bùn"}, {"id": "b", "text": "Cấm hoàn toàn việc sử dụng điện năng trong sản xuất công nghiệp"}, {"id": "c", "text": "Giảm dần tỉ trọng nhiệt điện than, phát triển mạnh mẽ điện gió, điện mặt trời và năng lượng sạch tái tạo"}], "correctOptionId": "c", "explanation": "Quy hoạch điện VIII ưu tiên tối đa nguồn năng lượng tái tạo nhằm giảm phát thải khí nhà kính và bảo đảm an ninh năng lượng bền vững."}]'::jsonb,'["geography-12-vietnam-energy-transition"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-vietnam-services-transport-tourism',11,'LESSON','Phát triển các ngành dịch vụ, giao thông vận tải và du lịch','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Khu vực dịch vụ chiếm tỉ trọng ngày càng lớn trong GDP (>40%). Giao thông vận tải phát triển đồng bộ: đường bộ cao tốc Bắc - Nam, đường sắt đô thị (Hà Nội, TP.HCM), cảng biển nước sâu quốc tế (Lạch Huyện - Hải Phòng, Cái Mép - Thị Vải - Bà Rịa Vũng Tàu tiếp nhận tàu mẹ xuyên đại dương), hàng không mở rộng các sân bay quốc tế (Long Thành, Nội Bài, Tân Sơn Nhất). Ngành du lịch trở thành ngành kinh tế mũi nhọn với tài nguyên du lịch tự nhiên (kì quan thiên nhiên, bãi biển) và nhân văn (di sản văn hóa, ẩm thực); phát triển du lịch sinh thái, di sản, nghỉ dưỡng."]'::jsonb,'["Cảng quốc tế Cái Mép - Thị Vải là một trong số ít cảng nước sâu của Đông Nam Á có thể tiếp nhận trực tiếp các siêu tàu container lớn nhất thế giới đi thẳng sang châu Âu và bờ Tây Hoa Kỳ mà không cần trung chuyển."]'::jsonb,'[{"id": "geography-12-vietnam-services-transport-tourism-q1", "prompt": "Tuyến đường bộ huyết mạch nối liền đất nước từ Bắc vào Nam dọc theo chiều dài dải đất non sông là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Quốc lộ 1A và đường cao tốc Bắc - Nam phía Đông"}, {"id": "b", "text": "Đường Hồ Chí Minh trên biển"}, {"id": "c", "text": "Tuyến đường vành đai biên giới số 4"}], "correctOptionId": "a", "explanation": "Quốc lộ 1A và tuyến cao tốc Bắc - Nam là trục xương sống giao thông vận tải đường bộ kết nối các trung tâm kinh tế từ Lạng Sơn đến Cà Mau."}, {"id": "geography-12-vietnam-services-transport-tourism-q2", "prompt": "Cụm cảng biển nước sâu quốc tế ở Đông Nam Bộ có khả năng tiếp nhận các siêu tàu container đi trực tiếp sang bờ Tây nước Mĩ là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cảng Cửa Lò (Nghệ An)"}, {"id": "b", "text": "Cảng Quy Nhơn (Bình Định)"}, {"id": "c", "text": "Cụm cảng Cái Mép - Thị Vải (Bà Rịa - Vũng Tàu)"}], "correctOptionId": "c", "explanation": "Cái Mép - Thị Vải có luồng sâu tự nhiên, là cửa ngõ xuất nhập khẩu hàng hải quốc tế hiện đại hàng đầu của Việt Nam."}, {"id": "geography-12-vietnam-services-transport-tourism-q3", "prompt": "Để ngành du lịch Việt Nam thực sự trở thành ngành kinh tế mũi nhọn và phát triển bền vững, giải pháp then chốt là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chặt phá các khu rừng nguyên sinh để xây dựng toàn bộ sân golf"}, {"id": "b", "text": "Nâng cao chất lượng dịch vụ, đa dạng hóa sản phẩm du lịch độc đáo, bảo vệ môi trường cảnh quan và ứng dụng công nghệ số"}, {"id": "c", "text": "Chỉ tập trung vào hạ giá vé thật thấp và chấp nhận xả rác bừa bãi tại điểm đến"}], "correctOptionId": "b", "explanation": "Phát triển du lịch xanh, chuyên nghiệp, giữ gìn bản sắc văn hóa và môi trường tự nhiên giúp gia tăng thời gian lưu trú và chi tiêu của du khách."}]'::jsonb,'["geography-12-vietnam-services-transport-tourism"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-review-2',12,'FIVE_LESSON_REVIEW','Ôn tập 2','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "geography-12-vietnam-agriculture-restructuring-q1", "prompt": "Xu hướng chuyển dịch cơ cấu nội bộ ngành trồng trọt của nước ta hiện nay là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Chuyển toàn bộ diện tích đất nông nghiệp sang khai thác mỏ khoáng sản"}, {"id": "b", "text": "Giảm tỉ trọng cây lương thực phẩm cấp thấp, tăng tỉ trọng cây công nghiệp lâu năm và cây ăn quả chất lượng cao"}, {"id": "c", "text": "Xóa bỏ hoàn toàn diện tích trồng lúa để trồng toàn bộ cỏ chăn nuôi"}], "correctOptionId": "b", "explanation": "Tái cơ cấu trồng trọt tập trung vào nâng cao giá trị gia tăng, đáp ứng tiêu chuẩn xuất khẩu và thích ứng biến đổi khí hậu."}, {"id": "geography-12-vietnam-agriculture-restructuring-q2", "prompt": "Vùng chuyên canh cây cà phê lớn nhất của Việt Nam, đưa nước ta trở thành quốc gia xuất khẩu cà phê Robusta hàng đầu thế giới là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Vùng Tây Nguyên"}, {"id": "b", "text": "Vùng Đồng bằng sông Hồng"}, {"id": "c", "text": "Vùng Bắc Trung Bộ"}], "correctOptionId": "a", "explanation": "Tây Nguyên có diện tích đất đỏ bazan màu mỡ và khí hậu cận xích đạo rất thích hợp hình thành các vùng chuyên canh cà phê quy mô lớn."}, {"id": "geography-12-vietnam-forestry-fisheries-q1", "prompt": "Loại rừng nào sau đây có chức năng chủ yếu là bảo tồn nguồn gene sinh vật quý hiếm và nghiên cứu khoa học?", "difficulty": "EASY", "options": [{"id": "a", "text": "Rừng đặc dụng (các vườn quốc gia, khu bảo tồn thiên nhiên)"}, {"id": "b", "text": "Rừng sản xuất lấy gỗ"}, {"id": "c", "text": "Rừng trồng bạch đàn thương phẩm"}], "correctOptionId": "a", "explanation": "Rừng đặc dụng bảo vệ hệ sinh thái mẫu chuẩn, bảo tồn đa dạng sinh học và cảnh quan di sản thiên nhiên."}, {"id": "geography-12-vietnam-forestry-fisheries-q2", "prompt": "Hai mặt hàng thủy sản nuôi trồng xuất khẩu chủ lực mang lại kim ngạch hàng tỉ USD mỗi năm cho nước ta là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cá hồi và cá tầm ôn đới"}, {"id": "b", "text": "Rong biển tươi và cua đồng"}, {"id": "c", "text": "Tôm nước lợ và cá tra"}], "correctOptionId": "c", "explanation": "Đồng bằng sông Cửu Long là vựa tôm và cá tra lớn nhất nước, đóng góp phần lớn kim ngạch xuất khẩu thủy sản của Việt Nam."}, {"id": "geography-12-vietnam-industry-restructuring-q1", "prompt": "Nhóm ngành công nghiệp hiện đang chiếm tỉ trọng áp đảo và đóng vai trò động lực tăng trưởng chính của công nghiệp Việt Nam là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Công nghiệp khai thác than và quặng kim loại thô"}, {"id": "b", "text": "Công nghiệp đan lát thủ công gia đình"}, {"id": "c", "text": "Công nghiệp chế biến, chế tạo"}], "correctOptionId": "c", "explanation": "Công nghiệp chế biến, chế tạo đóng góp trên 80% giá trị sản xuất công nghiệp và là nguồn thu xuất khẩu lớn nhất của đất nước."}, {"id": "geography-12-vietnam-industry-restructuring-q2", "prompt": "Hai vùng kinh tế tập trung mật độ các khu công nghiệp và trung tâm công nghiệp quy mô lớn nhất cả nước là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Vùng Bắc Trung Bộ và Duyên hải Nam Trung Bộ"}, {"id": "b", "text": "Vùng Đông Nam Bộ và Vùng Đồng bằng sông Hồng"}, {"id": "c", "text": "Vùng Tây Nguyên và Vùng Tây Bắc"}], "correctOptionId": "b", "explanation": "Đông Nam Bộ và Đồng bằng sông Hồng hội tụ hạ tầng giao thông, cảng biển, nguồn nhân lực chất lượng cao và thị trường tiêu thụ lớn nhất nước."}, {"id": "geography-12-vietnam-energy-transition-q1", "prompt": "Nhà máy thủy điện có công suất lớn nhất Việt Nam và khu vực Đông Nam Á hiện nay là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Thủy điện Trị An"}, {"id": "b", "text": "Thủy điện Sơn La (trên sông Đà)"}, {"id": "c", "text": "Thủy điện Hòa Bình"}], "correctOptionId": "b", "explanation": "Thủy điện Sơn La có công suất thiết kế 2400 MW, khánh thành năm 2012, là công trình thủy điện lớn nhất Đông Nam Á."}, {"id": "geography-12-vietnam-energy-transition-q2", "prompt": "Hai tỉnh Duyên hải Nam Trung Bộ có tiềm năng bức xạ mặt trời và tốc độ gió lớn nhất, trở thành trung tâm năng lượng tái tạo của cả nước là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ninh Thuận và Bình Thuận"}, {"id": "b", "text": "Nam Định và Thái Bình"}, {"id": "c", "text": "Điện Biên và Lai Châu"}], "correctOptionId": "a", "explanation": "Ninh Thuận và Bình Thuận có số giờ nắng cao quanh năm và lượng gió ổn định, thu hút hàng loạt dự án điện mặt trời và điện gió quy mô lớn."}, {"id": "geography-12-vietnam-services-transport-tourism-q1", "prompt": "Tuyến đường bộ huyết mạch nối liền đất nước từ Bắc vào Nam dọc theo chiều dài dải đất non sông là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Quốc lộ 1A và đường cao tốc Bắc - Nam phía Đông"}, {"id": "b", "text": "Đường Hồ Chí Minh trên biển"}, {"id": "c", "text": "Tuyến đường vành đai biên giới số 4"}], "correctOptionId": "a", "explanation": "Quốc lộ 1A và tuyến cao tốc Bắc - Nam là trục xương sống giao thông vận tải đường bộ kết nối các trung tâm kinh tế từ Lạng Sơn đến Cà Mau."}, {"id": "geography-12-vietnam-services-transport-tourism-q2", "prompt": "Cụm cảng biển nước sâu quốc tế ở Đông Nam Bộ có khả năng tiếp nhận các siêu tàu container đi trực tiếp sang bờ Tây nước Mĩ là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cảng Cửa Lò (Nghệ An)"}, {"id": "b", "text": "Cảng Quy Nhơn (Bình Định)"}, {"id": "c", "text": "Cụm cảng Cái Mép - Thị Vải (Bà Rịa - Vũng Tàu)"}], "correctOptionId": "c", "explanation": "Cái Mép - Thị Vải có luồng sâu tự nhiên, là cửa ngõ xuất nhập khẩu hàng hải quốc tế hiện đại hàng đầu của Việt Nam."}]'::jsonb,'["geography-12-vietnam-agriculture-restructuring", "geography-12-vietnam-forestry-fisheries", "geography-12-vietnam-industry-restructuring", "geography-12-vietnam-energy-transition", "geography-12-vietnam-services-transport-tourism"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-red-river-delta-development',13,'LESSON','Vùng Đồng bằng sông Hồng: Thế mạnh và chuyển dịch cơ cấu kinh tế','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Đồng bằng sông Hồng là trung tâm chính trị, văn hóa, khoa học và kinh tế năng động của cả nước. Thế mạnh nổi bật: nguồn lao động dồi dào có trình độ chuyên môn kĩ thuật cao nhất cả nước; mạng lưới kết cấu hạ tầng giao thông và đô thị hoàn thiện; thị trường tiêu thụ rộng lớn; tài nguyên đất phù sa sông Hồng màu mỡ. Chuyển dịch cơ cấu: tăng nhanh tỉ trọng công nghiệp chế biến, công nghệ thông tin (Hà Nội, Bắc Ninh, Hải Phòng), dịch vụ tài chính, logistics; nông nghiệp phát triển công nghệ cao gắn với rau vụ đông."]'::jsonb,'["Vụ đông với các cây trồng ưa lạnh như khoai tây, cà rốt, bắp cải đã trở thành vụ sản xuất chính thứ ba mang lại giá trị kinh tế cao cho nông dân Đồng bằng sông Hồng."]'::jsonb,'[{"id": "geography-12-red-river-delta-development-q1", "prompt": "Thế mạnh vượt trội nhất về mặt nguồn nhân lực của vùng Đồng bằng sông Hồng so với các vùng khác là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Toàn bộ lao động chỉ có kinh nghiệm săn bắt thú hoang dã"}, {"id": "b", "text": "Chi phí thuê nhân công rẻ nhất trong toàn bộ khu vực"}, {"id": "c", "text": "Nguồn lao động rất dồi dào và có tỉ lệ lao động qua đào tạo cao nhất cả nước"}], "correctOptionId": "c", "explanation": "Vùng tập trung phần lớn các trường đại học, viện nghiên cứu lớn nên có mật độ tri thức và tay nghề kĩ thuật đứng đầu cả nước."}, {"id": "geography-12-red-river-delta-development-q2", "prompt": "Vụ sản xuất nông nghiệp đặc trưng tạo nên nét độc đáo của Đồng bằng sông Hồng nhờ có mùa đông lạnh là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Vụ mưa tuyết trồng cây cao su"}, {"id": "b", "text": "Vụ đông (trồng các loại rau màu ưa lạnh như khoai tây, su hào, bắp cải)"}, {"id": "c", "text": "Vụ hè thu trồng lúa nổi"}], "correctOptionId": "b", "explanation": "Mùa đông lạnh ở miền Bắc cho phép trồng các giống cây nguồn gốc cận nhiệt và ôn đới, biến vụ đông thành vụ hàng hóa có hiệu quả kinh tế cao."}, {"id": "geography-12-red-river-delta-development-q3", "prompt": "Định hướng chuyển dịch cơ cấu ngành kinh tế của vùng Đồng bằng sông Hồng đến năm 2030 là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Phát triển công nghiệp hiện đại, công nghệ cao, dịch vụ chất lượng cao gắn với kinh tế tri thức và đô thị thông minh"}, {"id": "b", "text": "Mở rộng diện tích khai thác quặng than lộ thiên trong các khu dân cư"}, {"id": "c", "text": "Chuyển toàn bộ lực lượng lao động công nghiệp sang làm nông nghiệp tự cấp tự túc"}], "correctOptionId": "a", "explanation": "Đồng bằng sông Hồng được định hướng trở thành trung tâm công nghệ cao, tài chính, logistics và dịch vụ hiện đại hàng đầu khu vực."}]'::jsonb,'["geography-12-red-river-delta-development"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-mekong-delta-climate-adaptation',14,'LESSON','Vùng Đồng bằng sông Cửu Long: Thích ứng biến đổi khí hậu và an ninh lương thực','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Đồng bằng sông Cửu Long là vùng sản xuất lương thực, thực phẩm, thủy sản và trái cây lớn nhất cả nước (đóng góp trên 50% sản lượng lúa và 90% lượng gạo xuất khẩu). Đặc điểm tự nhiên: mạng lưới kênh rạch chằng chịt, đất phù sa ngọt ven sông Tiền, sông Hậu; đất phèn, đất mặn chiếm diện tích lớn. Thách thức lớn: biến đổi khí hậu, nước biển dâng, sụt lún đất, xâm nhập mặn sâu vào mùa khô và thiếu phù sa do thủy điện thượng nguồn Mê Kông. Định hướng: Nghị quyết 120/NQ-CP ''thuận thiên'', chuyển đổi mô hình kinh tế nông nghiệp (lúa - tôm, cây ăn trái), xây dựng hồ trữ nước ngọt."]'::jsonb,'["Mô hình một vụ lúa vào mùa mưa ngọt và một vụ nuôi tôm vào mùa nước lợ mặn tại Bạc Liêu, Sóc Trăng là minh chứng xuất sắc cho giải pháp thích ứng ''thuận thiên''."]'::jsonb,'[{"id": "geography-12-mekong-delta-climate-adaptation-q1", "prompt": "Vai trò quan trọng hàng đầu của vùng Đồng bằng sông Cửu Long đối với cả nước là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Là trung tâm luyện kim đen và chế tạo máy bay lớn nhất nước"}, {"id": "b", "text": "Là vùng trọng điểm sản xuất lương thực, thủy sản và trái cây lớn nhất, bảo đảm an ninh lương thực quốc gia và xuất khẩu"}, {"id": "c", "text": "Là vùng tập trung nhiều nhất các mỏ quặng sắt và than đá"}], "correctOptionId": "b", "explanation": "Đồng bằng sông Cửu Long chiếm hơn một nửa sản lượng lúa cả nước và cung cấp phần lớn sản lượng gạo xuất khẩu của Việt Nam."}, {"id": "geography-12-mekong-delta-climate-adaptation-q2", "prompt": "Thách thức môi trường tự nhiên gay gắt nhất đe dọa sinh kế của người dân Đồng bằng sông Cửu Long vào mùa khô hiện nay là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hiện tượng hạn hán kết hợp với xâm nhập mặn lấn sâu vào nội đồng"}, {"id": "b", "text": "Bão tuyết và rét đậm kéo dài nhiều tháng"}, {"id": "c", "text": "Núi lửa phun trào dung nham dọc các bờ kênh"}], "correctOptionId": "a", "explanation": "Lưu lượng dòng chảy thượng nguồn giảm làm nước biển theo triều dâng xâm nhập sâu hàng chục km vào các nhánh sông, làm thiếu nước ngọt sinh hoạt và tưới tiêu."}, {"id": "geography-12-mekong-delta-climate-adaptation-q3", "prompt": "Quan điểm phát triển ''thuận thiên'' theo tinh thần Nghị quyết 120/NQ-CP của Chính phủ tại vùng Đồng bằng sông Cửu Long có nghĩa là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Để mặc thiên nhiên tàn phá mà không thực hiện bất kì công trình bảo vệ nào"}, {"id": "b", "text": "Xây đê bê tông cao ngăn chặn toàn bộ các dòng sông chảy ra biển"}, {"id": "c", "text": "Chủ động thích ứng với biến đổi khí hậu, coi nước mặn và nước lợ cũng là tài nguyên để chuyển dịch mô hình kinh tế phù hợp thay vì chống lại tự nhiên"}], "correctOptionId": "c", "explanation": "Thuận thiên nghĩa là tôn trọng quy luật tự nhiên, chuyển vùng mặn lợ sang nuôi trồng thủy sản, giảm diện tích lúa 3 vụ không hiệu quả để giảm sức ép tài nguyên nước."}]'::jsonb,'["geography-12-mekong-delta-climate-adaptation"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-southeast-region-growth-pole',15,'LESSON','Vùng Đông Nam Bộ: Đầu tàu kinh tế, công nghiệp và đô thị hóa','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Đông Nam Bộ là vùng kinh tế phát triển năng động nhất cả nước, đóng góp hơn 30% GDP và gần 40% thu ngân sách quốc gia. Thế mạnh: vị trí đầu mối giao thông quốc tế; địa hình bán bình nguyên lượn sóng bằng phẳng, đất bazan và xám thoát nước tốt thích hợp cây công nghiệp (cao su, điều); thềm lục địa giàu dầu mỏ, khí đốt; nguồn nhân lực và vốn FDI dồi dào. Đầu tàu là TP. Hồ Chí Minh. Định hướng phát triển: trung tâm công nghiệp công nghệ cao, bán dẫn, trung tâm tài chính quốc tế, dịch vụ logistics hiện đại và liên kết vùng bền vững."]'::jsonb,'["Thành phố Thủ Đức (thuộc TP. Hồ Chí Minh) với Khu công nghệ cao và khu đô thị đại học đang vươn lên thành thung lũng sáng tạo của vùng kinh tế trọng điểm phía Nam."]'::jsonb,'[{"id": "geography-12-southeast-region-growth-pole-q1", "prompt": "Đặc điểm nào sau đây khẳng định vị thế kinh tế số 1 của vùng Đông Nam Bộ ở Việt Nam?", "difficulty": "EASY", "options": [{"id": "a", "text": "Là vùng đóng góp tỉ trọng GDP và thu ngân sách nhà nước cao nhất cả nước"}, {"id": "b", "text": "Là vùng có diện tích đất tự nhiên rộng lớn nhất cả nước"}, {"id": "c", "text": "Là vùng có mật độ dân số thấp nhất trong tất cả các vùng"}], "correctOptionId": "a", "explanation": "Đông Nam Bộ là cực tăng trưởng kinh tế năng động nhất, dẫn đầu cả nước về quy mô kinh tế, thu hút vốn FDI và xuất khẩu."}, {"id": "geography-12-southeast-region-growth-pole-q2", "prompt": "Tài nguyên khoáng sản nổi bật ở thềm lục địa của vùng Đông Nam Bộ có ý nghĩa chiến lược quốc gia là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Than đá và than bùn"}, {"id": "b", "text": "Quặng sắt và bauxite"}, {"id": "c", "text": "Dầu mỏ và khí tự nhiên"}], "correctOptionId": "c", "explanation": "Các mỏ dầu khí lớn ngoài khơi Bà Rịa - Vũng Tàu (Bạch Hổ, Rạng Đông) là nguồn nguyên liệu cho công nghiệp năng lượng và hóa dầu."}, {"id": "geography-12-southeast-region-growth-pole-q3", "prompt": "Nhiệm vụ trọng tâm trong phát triển công nghiệp của vùng Đông Nam Bộ trong giai đoạn hiện nay là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Ngừng hoàn toàn việc hợp tác đầu tư với các tập đoàn công nghệ quốc tế"}, {"id": "b", "text": "Chuyển từ các ngành thâm dụng lao động phổ thông sang công nghiệp công nghệ cao, kinh tế số và chuỗi cung ứng bán dẫn"}, {"id": "c", "text": "Chỉ tập trung vào công nghiệp đóng gói bao bì thô"}], "correctOptionId": "b", "explanation": "Trước áp lực chi phí nhân công và đất đai, vùng đang tái cơ cấu mạnh mẽ lên nấc thang công nghệ cao và dịch vụ tài chính giá trị gia tăng lớn."}]'::jsonb,'["geography-12-southeast-region-growth-pole"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-vietnam-marine-economy',16,'LESSON','Phát triển kinh tế biển gắn với bảo đảm quốc phòng - an ninh','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Nghị quyết số 36-NQ/TW về Chiến lược phát triển bền vững kinh tế biển Việt Nam đến năm 2030, tầm nhìn đến năm 2045 xác định mục tiêu đưa Việt Nam trở thành quốc gia biển mạnh. Các ngành kinh tế biển then chốt theo thứ tự ưu tiên: 1. Du lịch và dịch vụ biển; 2. Kinh tế hàng hải (vận tải, cảng biển, logistics); 3. Khai thác dầu khí và khoáng sản biển; 4. Nuôi trồng và khai thác hải sản; 5. Công nghiệp ven biển; 6. Năng lượng tái tạo và các ngành kinh tế biển mới. Phát triển kinh tế biển gắn chặt với bảo vệ môi trường biển, đảo và giữ vững chủ quyền, an ninh quốc gia trên biển."]'::jsonb,'["Các đảo ven bờ như Phú Quốc (Kiên Giang), Cát Bà (Hải Phòng), Côn Đảo (Bà Rịa - Vũng Tàu) đang phát triển thành các trung tâm du lịch sinh thái biển đẳng cấp quốc tế."]'::jsonb,'[{"id": "geography-12-vietnam-marine-economy-q1", "prompt": "Nghị quyết 36-NQ/TW của Trung ương Đảng xác định ngành kinh tế biển nào giữ vị trí ưu tiên hàng đầu?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khai thác cát sỏi lòng biển làm vật liệu san lấp"}, {"id": "b", "text": "Chế biến dầu thô xuất khẩu"}, {"id": "c", "text": "Du lịch và dịch vụ biển"}], "correctOptionId": "c", "explanation": "Du lịch biển với bờ biển dài và hàng nghìn hòn đảo đẹp là ngành kinh tế có tiềm năng đột phá và lan tỏa nhanh nhất."}, {"id": "geography-12-vietnam-marine-economy-q2", "prompt": "Hệ thống các đảo và quần đảo của Việt Nam trên Biển Đông có ý nghĩa chiến lược to lớn về:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không có bất kì giá trị kinh tế nào do diện tích quá nhỏ"}, {"id": "b", "text": "Kinh tế biển, căn cứ tiến ra biển lớn và bảo đảm quốc phòng, an ninh bảo vệ Tổ quốc"}, {"id": "c", "text": "Chỉ dùng để làm nơi lưu giữ rác thải công nghiệp"}], "correctOptionId": "b", "explanation": "Hệ thống đảo tạo nên các tiền tiêu bảo vệ lãnh thổ, là điểm tựa cho ngư dân bám biển và xác định các vùng biển theo luật pháp quốc tế."}, {"id": "geography-12-vietnam-marine-economy-q3", "prompt": "Mối quan hệ mật thiết giữa phát triển kinh tế biển và bảo vệ an ninh quốc phòng được thể hiện qua hành động nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Hỗ trợ ngư dân đóng tàu vỏ thép công suất lớn vươn khơi bám biển dài ngày, vừa làm giàu vừa khẳng định mốc chủ quyền sống trên biển"}, {"id": "b", "text": "Rút toàn bộ tàu thuyền đánh cá về bờ để tránh mọi va chạm"}, {"id": "c", "text": "Khai thác san hô tự do để bán cho khách du lịch"}], "correctOptionId": "a", "explanation": "Mỗi con tàu đánh cá của ngư dân trên ngư trường Hoàng Sa, Trường Sa là một ''cột mốc chủ quyền'' bảo vệ vùng trời, vùng biển thiêng liêng của Tổ quốc."}]'::jsonb,'["geography-12-vietnam-marine-economy"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-environmental-sustainability-vietnam',17,'LESSON','Sử dụng tài nguyên, bảo vệ môi trường và ứng phó biến đổi khí hậu','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Thực trạng tài nguyên môi trường Việt Nam: suy giảm diện tích và chất lượng rừng tự nhiên; thoái hóa đất nông nghiệp (xói mòn, bạc màu, nhiễm phèn mặn); ô nhiễm môi trường nước lưu vực sông và rác thải nhựa đại dương; ô nhiễm không khí đô thị (bụi mịn PM2.5). Giải pháp phát triển bền vững: hoàn thiện khung pháp lí (Luật Bảo vệ môi trường 2020), áp dụng kinh tế tuần hoàn, phân loại rác tại nguồn, bảo tồn đa dạng sinh học, trồng 1 tỉ cây xanh, và thực hiện chuyển dịch năng lượng sạch để đạt mục tiêu Net Zero năm 2050 theo cam kết tại COP26."]'::jsonb,'["Chiến dịch ''Chống rác thải nhựa'' và mô hình phân loại rác thải rắn sinh hoạt tại nguồn được triển khai đồng bộ tại các trường học và khu dân cư trên cả nước."]'::jsonb,'[{"id": "geography-12-environmental-sustainability-vietnam-q1", "prompt": "Tại Hội nghị biến đổi khí hậu COP26 (năm 2021), Thủ tướng Chính phủ Việt Nam đã đưa ra cam kết mạnh mẽ nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngừng hoàn toàn mọi hoạt động sản xuất công nghiệp vào năm 2025"}, {"id": "b", "text": "Đạt mức phát thải ròng bằng 0 (Net Zero) vào năm 2050"}, {"id": "c", "text": "Tăng gấp đôi lượng khí thải nhà kính vào năm 2030"}], "correctOptionId": "b", "explanation": "Cam kết Net Zero vào năm 2050 thể hiện trách nhiệm cao của Việt Nam trong nỗ lực toàn cầu ngăn chặn biến đổi khí hậu."}, {"id": "geography-12-environmental-sustainability-vietnam-q2", "prompt": "Mô hình ''Kinh tế tuần hoàn'' (Circular Economy) trong quản lí tài nguyên và môi trường hướng tới mục tiêu cốt lõi nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Kéo dài vòng đời của sản phẩm, tái sử dụng và tái chế chất thải thành tài nguyên, giảm thiểu phát thải ra môi trường"}, {"id": "b", "text": "Khai thác triệt để tài nguyên một lần rồi chôn lấp toàn bộ"}, {"id": "c", "text": "Tăng lượng rác thải nhựa không phân hủy sinh học ra sông hồ"}], "correctOptionId": "a", "explanation": "Kinh tế tuần hoàn thay thế mô hình kinh tế tuyến tính truyền thống (khai thác - sản xuất - vứt bỏ) bằng chu trình khép kín tài nguyên."}, {"id": "geography-12-environmental-sustainability-vietnam-q3", "prompt": "Hành động thiết thực và có ý nghĩa nhất của mỗi học sinh để góp phần bảo vệ môi trường học đường và địa phương là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Vứt rác bừa bãi ra sân trường và để vòi nước chảy tự do"}, {"id": "b", "text": "Sử dụng thật nhiều túi nilon mới trong mỗi lần mua đồ ăn vặt"}, {"id": "c", "text": "Nghiêm túc phân loại rác tại nguồn, hạn chế sử dụng đồ nhựa dùng một lần, tiết kiệm điện nước và tích cực trồng cây xanh"}], "correctOptionId": "c", "explanation": "Ý thức giữ gìn môi trường bắt đầu từ những thói quen nhỏ hàng ngày như bỏ rác đúng nơi quy định và lan tỏa lối sống xanh đến bạn bè."}]'::jsonb,'["geography-12-environmental-sustainability-vietnam"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('geography',12,'intro-2026.1','geography-12-review-3',18,'FIVE_LESSON_REVIEW','Ôn tập 3','Địa lí 12: Địa lí tự nhiên, dân cư và các vùng kinh tế Việt Nam','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "geography-12-red-river-delta-development-q1", "prompt": "Thế mạnh vượt trội nhất về mặt nguồn nhân lực của vùng Đồng bằng sông Hồng so với các vùng khác là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Toàn bộ lao động chỉ có kinh nghiệm săn bắt thú hoang dã"}, {"id": "b", "text": "Chi phí thuê nhân công rẻ nhất trong toàn bộ khu vực"}, {"id": "c", "text": "Nguồn lao động rất dồi dào và có tỉ lệ lao động qua đào tạo cao nhất cả nước"}], "correctOptionId": "c", "explanation": "Vùng tập trung phần lớn các trường đại học, viện nghiên cứu lớn nên có mật độ tri thức và tay nghề kĩ thuật đứng đầu cả nước."}, {"id": "geography-12-red-river-delta-development-q2", "prompt": "Vụ sản xuất nông nghiệp đặc trưng tạo nên nét độc đáo của Đồng bằng sông Hồng nhờ có mùa đông lạnh là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Vụ mưa tuyết trồng cây cao su"}, {"id": "b", "text": "Vụ đông (trồng các loại rau màu ưa lạnh như khoai tây, su hào, bắp cải)"}, {"id": "c", "text": "Vụ hè thu trồng lúa nổi"}], "correctOptionId": "b", "explanation": "Mùa đông lạnh ở miền Bắc cho phép trồng các giống cây nguồn gốc cận nhiệt và ôn đới, biến vụ đông thành vụ hàng hóa có hiệu quả kinh tế cao."}, {"id": "geography-12-mekong-delta-climate-adaptation-q1", "prompt": "Vai trò quan trọng hàng đầu của vùng Đồng bằng sông Cửu Long đối với cả nước là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Là trung tâm luyện kim đen và chế tạo máy bay lớn nhất nước"}, {"id": "b", "text": "Là vùng trọng điểm sản xuất lương thực, thủy sản và trái cây lớn nhất, bảo đảm an ninh lương thực quốc gia và xuất khẩu"}, {"id": "c", "text": "Là vùng tập trung nhiều nhất các mỏ quặng sắt và than đá"}], "correctOptionId": "b", "explanation": "Đồng bằng sông Cửu Long chiếm hơn một nửa sản lượng lúa cả nước và cung cấp phần lớn sản lượng gạo xuất khẩu của Việt Nam."}, {"id": "geography-12-mekong-delta-climate-adaptation-q2", "prompt": "Thách thức môi trường tự nhiên gay gắt nhất đe dọa sinh kế của người dân Đồng bằng sông Cửu Long vào mùa khô hiện nay là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Hiện tượng hạn hán kết hợp với xâm nhập mặn lấn sâu vào nội đồng"}, {"id": "b", "text": "Bão tuyết và rét đậm kéo dài nhiều tháng"}, {"id": "c", "text": "Núi lửa phun trào dung nham dọc các bờ kênh"}], "correctOptionId": "a", "explanation": "Lưu lượng dòng chảy thượng nguồn giảm làm nước biển theo triều dâng xâm nhập sâu hàng chục km vào các nhánh sông, làm thiếu nước ngọt sinh hoạt và tưới tiêu."}, {"id": "geography-12-southeast-region-growth-pole-q1", "prompt": "Đặc điểm nào sau đây khẳng định vị thế kinh tế số 1 của vùng Đông Nam Bộ ở Việt Nam?", "difficulty": "EASY", "options": [{"id": "a", "text": "Là vùng đóng góp tỉ trọng GDP và thu ngân sách nhà nước cao nhất cả nước"}, {"id": "b", "text": "Là vùng có diện tích đất tự nhiên rộng lớn nhất cả nước"}, {"id": "c", "text": "Là vùng có mật độ dân số thấp nhất trong tất cả các vùng"}], "correctOptionId": "a", "explanation": "Đông Nam Bộ là cực tăng trưởng kinh tế năng động nhất, dẫn đầu cả nước về quy mô kinh tế, thu hút vốn FDI và xuất khẩu."}, {"id": "geography-12-southeast-region-growth-pole-q2", "prompt": "Tài nguyên khoáng sản nổi bật ở thềm lục địa của vùng Đông Nam Bộ có ý nghĩa chiến lược quốc gia là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Than đá và than bùn"}, {"id": "b", "text": "Quặng sắt và bauxite"}, {"id": "c", "text": "Dầu mỏ và khí tự nhiên"}], "correctOptionId": "c", "explanation": "Các mỏ dầu khí lớn ngoài khơi Bà Rịa - Vũng Tàu (Bạch Hổ, Rạng Đông) là nguồn nguyên liệu cho công nghiệp năng lượng và hóa dầu."}, {"id": "geography-12-vietnam-marine-economy-q1", "prompt": "Nghị quyết 36-NQ/TW của Trung ương Đảng xác định ngành kinh tế biển nào giữ vị trí ưu tiên hàng đầu?", "difficulty": "EASY", "options": [{"id": "a", "text": "Khai thác cát sỏi lòng biển làm vật liệu san lấp"}, {"id": "b", "text": "Chế biến dầu thô xuất khẩu"}, {"id": "c", "text": "Du lịch và dịch vụ biển"}], "correctOptionId": "c", "explanation": "Du lịch biển với bờ biển dài và hàng nghìn hòn đảo đẹp là ngành kinh tế có tiềm năng đột phá và lan tỏa nhanh nhất."}, {"id": "geography-12-vietnam-marine-economy-q2", "prompt": "Hệ thống các đảo và quần đảo của Việt Nam trên Biển Đông có ý nghĩa chiến lược to lớn về:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Không có bất kì giá trị kinh tế nào do diện tích quá nhỏ"}, {"id": "b", "text": "Kinh tế biển, căn cứ tiến ra biển lớn và bảo đảm quốc phòng, an ninh bảo vệ Tổ quốc"}, {"id": "c", "text": "Chỉ dùng để làm nơi lưu giữ rác thải công nghiệp"}], "correctOptionId": "b", "explanation": "Hệ thống đảo tạo nên các tiền tiêu bảo vệ lãnh thổ, là điểm tựa cho ngư dân bám biển và xác định các vùng biển theo luật pháp quốc tế."}, {"id": "geography-12-environmental-sustainability-vietnam-q1", "prompt": "Tại Hội nghị biến đổi khí hậu COP26 (năm 2021), Thủ tướng Chính phủ Việt Nam đã đưa ra cam kết mạnh mẽ nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Ngừng hoàn toàn mọi hoạt động sản xuất công nghiệp vào năm 2025"}, {"id": "b", "text": "Đạt mức phát thải ròng bằng 0 (Net Zero) vào năm 2050"}, {"id": "c", "text": "Tăng gấp đôi lượng khí thải nhà kính vào năm 2030"}], "correctOptionId": "b", "explanation": "Cam kết Net Zero vào năm 2050 thể hiện trách nhiệm cao của Việt Nam trong nỗ lực toàn cầu ngăn chặn biến đổi khí hậu."}, {"id": "geography-12-environmental-sustainability-vietnam-q2", "prompt": "Mô hình ''Kinh tế tuần hoàn'' (Circular Economy) trong quản lí tài nguyên và môi trường hướng tới mục tiêu cốt lõi nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Kéo dài vòng đời của sản phẩm, tái sử dụng và tái chế chất thải thành tài nguyên, giảm thiểu phát thải ra môi trường"}, {"id": "b", "text": "Khai thác triệt để tài nguyên một lần rồi chôn lấp toàn bộ"}, {"id": "c", "text": "Tăng lượng rác thải nhựa không phân hủy sinh học ra sông hồ"}], "correctOptionId": "a", "explanation": "Kinh tế tuần hoàn thay thế mô hình kinh tế tuyến tính truyền thống (khai thác - sản xuất - vứt bỏ) bằng chu trình khép kín tài nguyên."}]'::jsonb,'["geography-12-red-river-delta-development", "geography-12-mekong-delta-climate-adaptation", "geography-12-southeast-region-growth-pole", "geography-12-vietnam-marine-economy", "geography-12-environmental-sustainability-vietnam"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','placement',0,'PLACEMENT','Khảo sát đầu vào','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "economics_law-12-economic-growth-development-q1", "prompt": "Chỉ tiêu kinh tế vĩ mô nào sau đây phản ánh tổng giá trị thị trường của toàn bộ hàng hóa và dịch vụ cuối cùng được sản xuất ra trên lãnh thổ một quốc gia trong năm?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tổng sản phẩm quốc nội (GDP)"}, {"id": "b", "text": "Chỉ số giá tiêu dùng (CPI)"}, {"id": "c", "text": "Tỉ lệ lạm phát hàng tháng"}], "correctOptionId": "a", "explanation": "GDP (Gross Domestic Product) đo lường toàn bộ giá trị gia tăng tạo ra bên trong biên giới địa lí của quốc gia."}, {"id": "economics_law-12-economic-growth-development-q2", "prompt": "Điểm khác biệt căn bản giữa ''phát triển kinh tế'' và ''tăng trưởng kinh tế'' là gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Phát triển kinh tế chỉ tính riêng số lượng máy móc sản xuất trong một ngày"}, {"id": "b", "text": "Tăng trưởng kinh tế có phạm vi rộng lớn hơn phát triển kinh tế"}, {"id": "c", "text": "Phát triển kinh tế bao hàm tăng trưởng kinh tế kết hợp với tiến bộ cơ cấu xã hội, cải thiện đời sống và bảo vệ môi trường"}], "correctOptionId": "c", "explanation": "Tăng trưởng thuần túy về mặt số lượng (quy mô GDP), còn phát triển bao hàm cả sự biến đổi về chất lượng cuộc sống (giáo dục, y tế, bình đẳng xã hội)."}, {"id": "economics_law-12-international-economic-integration-q1", "prompt": "Tổ chức kinh tế đa phương toàn cầu lớn nhất mà Việt Nam gia nhập năm 2007 để hòa mạng sâu rộng vào thương mại quốc tế là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Quỹ Tiền tệ Quốc tế (IMF)"}, {"id": "b", "text": "Tổ chức Các nước Xuất khẩu Dầu mỏ (OPEC)"}, {"id": "c", "text": "Tổ chức Thương mại Thế giới (WTO)"}], "correctOptionId": "c", "explanation": "Việt Nam trở thành thành viên thứ 150 của WTO vào ngày 11/1/2007 sau hơn 11 năm đàm phán."}, {"id": "economics_law-12-international-economic-integration-q2", "prompt": "Đặc điểm nổi bật của các hiệp định thương mại tự do thế hệ mới (như CPTPP, EVFTA) so với các hiệp định truyền thống là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bắt buộc các nước tham gia phải sử dụng chung một loại tiền tệ duy nhất"}, {"id": "b", "text": "Có phạm vi cam kết sâu rộng hơn, bao gồm cả các vấn đề phi thương mại như môi trường, quyền lao động và sở hữu trí tuệ"}, {"id": "c", "text": "Chỉ cam kết trao đổi hàng hóa nông sản thô mà không có dịch vụ"}], "correctOptionId": "b", "explanation": "FTA thế hệ mới không chỉ xóa bỏ dòng thuế quan mà còn đặt ra các tiêu chuẩn minh bạch hóa, bảo vệ người lao động và phát triển xanh."}, {"id": "economics_law-12-insurance-welfare-system-q1", "prompt": "Loại hình bảo hiểm phi lợi nhuận do Nhà nước tổ chức nhằm bảo đảm quyền lợi khám chữa bệnh cho người dân là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Bảo hiểm cháy nổ nhà xưởng tư nhân"}, {"id": "b", "text": "Bảo hiểm y tế (BHYT)"}, {"id": "c", "text": "Bảo hiểm ô tô thương mại"}], "correctOptionId": "b", "explanation": "BHYT là chính sách an sinh xã hội ưu việt của Đảng và Nhà nước nhằm chăm sóc sức khỏe cộng đồng, không vì mục đích kiếm lợi nhuận."}, {"id": "economics_law-12-insurance-welfare-system-q2", "prompt": "Người lao động tham gia Bảo hiểm xã hội bắt buộc đủ điều kiện theo quy định được hưởng những chế độ cốt lõi nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ốm đau, thai sản, tai nạn lao động - bệnh nghề nghiệp, hưu trí và tử tuất"}, {"id": "b", "text": "Chế độ thưởng du lịch châu Âu hàng năm"}, {"id": "c", "text": "Được cấp miễn phí nhà ở cao cấp và xe hơi cá nhân"}], "correctOptionId": "a", "explanation": "Luật BHXH quy định rõ 5 chế độ của BHXH bắt buộc nhằm bảo đảm an sinh trọn đời cho người lao động từ khi đi làm đến lúc về già."}, {"id": "economics_law-12-business-plan-startup-q1", "prompt": "Bước đầu tiên và giữ vai trò định hướng trong quá trình xây dựng một bản kế hoạch kinh doanh là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Xác định ý tưởng kinh doanh và giá trị độc đáo mang lại cho khách hàng"}, {"id": "b", "text": "Đi vay ngân hàng số tiền tối đa có thể"}, {"id": "c", "text": "Thuê ngay mặt bằng đắt nhất ở trung tâm thành phố"}], "correctOptionId": "a", "explanation": "Ý tưởng kinh doanh xuất phát từ việc phát hiện nhu cầu chưa được đáp ứng tốt trên thị trường là nền tảng khởi đầu của kế hoạch."}, {"id": "economics_law-12-business-plan-startup-q2", "prompt": "Điểm hòa vốn (Break-even point) trong kế hoạch tài chính của một cơ sở kinh doanh là thời điểm:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Lợi nhuận ròng đạt mức cao nhất trong toàn bộ chu kì"}, {"id": "b", "text": "Doanh nghiệp bị phá sản và phải bán thanh lí tài sản"}, {"id": "c", "text": "Tổng doanh thu thu về vừa đủ bù đắp toàn bộ tổng chi phí bỏ ra (lợi nhuận bằng 0)"}], "correctOptionId": "c", "explanation": "Tại điểm hòa vốn, doanh thu bằng chi phí (TR = TC); vượt qua điểm này doanh nghiệp bắt đầu có lãi ròng."}, {"id": "economics_law-12-corporate-social-responsibility-q1", "prompt": "Tầng nền tảng cơ bản đầu tiên trong tháp trách nhiệm xã hội của một doanh nghiệp là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Trách nhiệm tài trợ nghệ thuật quốc tế"}, {"id": "b", "text": "Trách nhiệm tặng quà miễn phí cho tất cả mọi người"}, {"id": "c", "text": "Trách nhiệm kinh tế (hoạt động kinh doanh có hiệu quả, tạo ra sản phẩm và việc làm)"}], "correctOptionId": "c", "explanation": "Doanh nghiệp trước hết phải vận hành hiệu quả, tạo ra lợi nhuận và việc làm chính đáng thì mới có nguồn lực thực hiện các trách nhiệm cao hơn."}, {"id": "economics_law-12-corporate-social-responsibility-q2", "prompt": "Hành vi nào sau đây biểu hiện sự vi phạm nghiêm trọng đạo đức kinh doanh và trách nhiệm xã hội?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cung cấp thông tin trung thực về hạn sử dụng và thành phần sản phẩm"}, {"id": "b", "text": "Xả chất thải độc hại chưa qua xử lí ra sông hồ để cắt giảm chi phí sản xuất"}, {"id": "c", "text": "Trả lương và đóng bảo hiểm xã hội đầy đủ cho nhân viên"}], "correctOptionId": "b", "explanation": "Hành vi lén lút xả thải gây ô nhiễm môi trường hủy hoại hệ sinh thái và sức khỏe cộng đồng là vi phạm pháp luật và đạo đức nghiêm trọng."}, {"id": "economics_law-12-personal-household-budget-q1", "prompt": "Theo quy tắc quản lí ngân sách tài chính cá nhân 50/30/20, tỉ lệ 20% thu nhập nên được ưu tiên cho mục tiêu nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chi trả tiền thuê nhà và tiền ăn uống hàng ngày"}, {"id": "b", "text": "Tiết kiệm, lập quỹ dự phòng khẩn cấp hoặc đầu tư trả nợ"}, {"id": "c", "text": "Đi du lịch nghỉ dưỡng cao cấp hàng tháng"}], "correctOptionId": "b", "explanation": "20% khoản tiền này là đòn bẩy tích lũy tạo sự an tâm tài chính và sinh lời dài hạn trong tương lai."}, {"id": "economics_law-12-personal-household-budget-q2", "prompt": "Mục đích cốt lõi của việc xây dựng ''quỹ dự phòng khẩn cấp'' (tương đương 3 - 6 tháng chi phí) là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chủ động ứng phó tài chính trước các biến cố bất ngờ như ốm đau, mất việc làm hoặc hư hỏng thiết bị thiết yếu mà không phải vay nợ lãi cao"}, {"id": "b", "text": "Dùng toàn bộ để tham gia các trò chơi may rủi trên mạng xã hội"}, {"id": "c", "text": "Mua sắm những món đồ xa xỉ giảm giá nhất thời"}], "correctOptionId": "a", "explanation": "Quỹ khẩn cấp bảo vệ cá nhân khỏi nguy cơ vỡ nợ khi xảy ra rủi ro gián đoạn nguồn thu nhập chính."}, {"id": "economics_law-12-business-tax-citizenship-q1", "prompt": "Theo quy định của Hiến pháp năm 2013 và pháp luật Việt Nam, công dân có quyền tự do kinh doanh trong phạm vi nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Trong những ngành, nghề và lĩnh vực mà luật không cấm"}, {"id": "b", "text": "Trong tất cả mọi lĩnh vực kể cả kinh doanh chất ma túy và vũ khí quân dụng"}, {"id": "c", "text": "Chỉ được phép kinh doanh các mặt hàng nông sản truyền thống tại địa phương"}], "correctOptionId": "a", "explanation": "Điều 33 Hiến pháp 2013 quy định mọi người có quyền tự do kinh doanh trong những ngành nghề mà pháp luật không cấm."}, {"id": "economics_law-12-business-tax-citizenship-q2", "prompt": "Nghĩa vụ hiến định mang tính bắt buộc hàng đầu của mọi tổ chức, cá nhân khi tiến hành hoạt động kinh doanh đối với Nhà nước là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tự ý ấn định mức thuế phải nộp dựa trên mức lợi nhuận mong muốn của cá nhân"}, {"id": "b", "text": "Chỉ nộp thuế khi có sự kiểm tra trực tiếp của cơ quan thuế tại cơ sở kinh doanh"}, {"id": "c", "text": "Kê khai trung thực, chính xác và nộp đầy đủ, đúng thời hạn các khoản thuế theo luật định"}], "correctOptionId": "c", "explanation": "Nộp thuế là nghĩa vụ hiến định của công dân nhằm tạo nguồn lực tài chính công để Nhà nước xây dựng hạ tầng, bảo đảm an sinh và bảo vệ Tổ quốc."}, {"id": "economics_law-12-property-ownership-rights-obligations-q1", "prompt": "Theo quy định của Bộ luật Dân sự năm 2015, quyền sở hữu của chủ sở hữu bao gồm ba quyền năng cơ bản nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quyền phong tỏa, quyền phát mại và quyền chiếm đoạt tài sản"}, {"id": "b", "text": "Quyền vay mượn, quyền thế chấp và quyền giấu giếm tài sản"}, {"id": "c", "text": "Quyền chiếm hữu, quyền sử dụng và quyền định đoạt tài sản"}], "correctOptionId": "c", "explanation": "Điều 158 Bộ luật Dân sự 2015 quy định quyền sở hữu bao gồm quyền chiếm hữu, quyền sử dụng và quyền định đoạt tài sản của chủ sở hữu."}, {"id": "economics_law-12-property-ownership-rights-obligations-q2", "prompt": "Nghĩa vụ tôn trọng tài sản của người khác đòi hỏi mỗi công dân phải thực hiện hành vi nào sau đây khi nhặt được tài sản đánh rơi?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đem vứt bỏ tài sản đó xuống sông hồ để không ai tìm thấy"}, {"id": "b", "text": "Thông báo hoặc trả lại ngay cho người đánh rơi, hoặc giao nộp cho cơ quan công an gần nhất"}, {"id": "c", "text": "Tự ý cất giữ làm của riêng và mang bán lấy tiền chi tiêu cá nhân"}], "correctOptionId": "b", "explanation": "Pháp luật dân sự quy định người nhặt được của rơi có nghĩa vụ thông báo, trả lại cho chủ sở hữu hoặc giao nộp cơ quan có thẩm quyền."}, {"id": "economics_law-12-marriage-family-rights-obligations-q1", "prompt": "Nguyên tắc cốt lõi hàng đầu của chế độ hôn nhân và gia đình theo pháp luật Việt Nam hiện hành là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Cho phép kết hôn với nhiều người cùng một lúc để mở rộng quan hệ họ hàng"}, {"id": "b", "text": "Hôn nhân tự nguyện, tiến bộ, một vợ một chồng, vợ chồng bình đẳng"}, {"id": "c", "text": "Hôn nhân hoàn toàn do cha mẹ sắp đặt và người chồng nắm toàn quyền quyết định"}], "correctOptionId": "b", "explanation": "Điều 2 Luật Hôn nhân và Gia đình 2014 xác định nguyên tắc hôn nhân tự nguyện, tiến bộ, một vợ một chồng, vợ chồng bình đẳng."}, {"id": "economics_law-12-marriage-family-rights-obligations-q2", "prompt": "Bổn phận và nghĩa vụ pháp lí quan trọng hàng đầu của con cái đối với cha mẹ theo luật định là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Yêu quý, kính trọng, biết ơn, hiếu thảo và chăm sóc, phụng dưỡng cha mẹ khi già yếu, ốm đau"}, {"id": "b", "text": "Có quyền từ chối phụng dưỡng cha mẹ nếu cha mẹ không chia phần tài sản thừa kế"}, {"id": "c", "text": "Tự ý định đoạt và sang tên toàn bộ nhà đất của cha mẹ mà không cần cha mẹ đồng ý"}], "correctOptionId": "a", "explanation": "Luật Hôn nhân và Gia đình quy định con cái có nghĩa vụ yêu quý, chăm sóc, nuôi dưỡng cha mẹ, đặc biệt khi cha mẹ mất sức lao động hoặc ốm đau."}, {"id": "economics_law-12-learning-education-rights-obligations-q1", "prompt": "Quy định công dân có thể học từ bậc tiểu học lên đến tiến sĩ theo các hình thức đào tạo khác nhau thể hiện nội dung quyền nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quyền học tập không hạn chế của công dân"}, {"id": "b", "text": "Quyền độc quyền nghiên cứu khoa học của nhà nước"}, {"id": "c", "text": "Nghĩa vụ bắt buộc mọi công dân phải đạt học vị tiến sĩ"}], "correctOptionId": "a", "explanation": "Quyền học tập không hạn chế cho phép công dân học từ thấp đến cao phù hợp với năng lực, điều kiện và nguyện vọng cá nhân suốt đời."}, {"id": "economics_law-12-learning-education-rights-obligations-q2", "prompt": "Chính sách của Nhà nước miễn học phí cho học sinh tiểu học và cấp học bổng cho học sinh vùng đồng bào dân tộc thiểu số thể hiện nguyên tắc gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tạo sự phân biệt đối xử bất lợi đối với học sinh sinh sống tại các đô thị lớn"}, {"id": "b", "text": "Cắt giảm chỉ tiêu đào tạo đại học và cao đẳng trên phạm vi toàn quốc"}, {"id": "c", "text": "Bảo đảm sự bình đẳng và công bằng xã hội về cơ hội tiếp cận giáo dục cho mọi công dân"}], "correctOptionId": "c", "explanation": "Nhà nước ưu tiên hỗ trợ các đối tượng yếu thế nhằm xóa bỏ rào cản kinh tế, hiện thực hóa quyền bình đẳng trong tiếp cận giáo dục cho mọi trẻ em."}, {"id": "economics_law-12-healthcare-social-security-rights-q1", "prompt": "Chính sách an sinh xã hội trụ cột do Nhà nước tổ chức nhằm chăm sóc sức khỏe cộng đồng và chia sẻ chi phí khám chữa bệnh là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Quỹ đầu tư bất động sản thương mại"}, {"id": "b", "text": "Hợp đồng bảo hiểm tài sản doanh nghiệp"}, {"id": "c", "text": "Bảo hiểm y tế (BHYT)"}], "correctOptionId": "c", "explanation": "Bảo hiểm y tế là chính sách an sinh xã hội quan trọng nhằm huy động sự đóng góp cộng đồng, bảo đảm quyền chăm sóc sức khỏe cho nhân dân."}, {"id": "economics_law-12-healthcare-social-security-rights-q2", "prompt": "Trong công tác phòng, chống bệnh truyền nhiễm nguy hiểm, nghĩa vụ bắt buộc của mỗi cá nhân đối với cộng đồng là gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Che giấu tình trạng nhiễm bệnh truyền nhiễm của bản thân và từ chối điều trị"}, {"id": "b", "text": "Khai báo y tế trung thực, thực hiện nghiêm các biện pháp cách ly và tiêm chủng phòng dịch theo hướng dẫn y tế"}, {"id": "c", "text": "Tự ý trốn khỏi khu vực phong tỏa cách ly y tế để tiếp xúc đông người nơi công cộng"}], "correctOptionId": "b", "explanation": "Luật Phòng, chống bệnh truyền nhiễm quy định cá nhân có nghĩa vụ chấp hành nghiêm các biện pháp phòng dịch để bảo đảm an toàn sức khỏe chung."}, {"id": "economics_law-12-cultural-environmental-protection-rights-q1", "prompt": "Quyền cơ bản của mọi người dân đối với môi trường sống được ghi nhận rõ nét tại Điều 43 Hiến pháp năm 2013 là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Mọi người được phép xả chất thải công nghiệp trực tiếp ra nguồn nước sinh hoạt chung"}, {"id": "b", "text": "Mọi người có quyền được sống trong môi trường trong lành và có nghĩa vụ bảo vệ môi trường"}, {"id": "c", "text": "Mọi người có quyền tự do khai thác cạn kiệt tài nguyên rừng phòng hộ mà không cần xin phép"}], "correctOptionId": "b", "explanation": "Hiến pháp 2013 khẳng định quyền được sống trong môi trường trong lành đi đôi với nghĩa vụ bảo vệ môi trường của mọi cá nhân."}, {"id": "economics_law-12-cultural-environmental-protection-rights-q2", "prompt": "Hành vi nào sau đây xâm phạm nghiêm trọng các quy định pháp luật về bảo vệ di sản văn hóa dân tộc?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tự ý đập phá, lấn chiếm khuôn viên, đào bới trái phép hoặc làm biến dạng kiến trúc gốc của di tích lịch sử"}, {"id": "b", "text": "Tích cực tham gia vệ sinh môi trường và trồng hoa tạo cảnh quan đẹp cho khu di tích"}, {"id": "c", "text": "Sưu tầm và giới thiệu các tư liệu lịch sử chính thống về di tích cho du khách tham quan"}], "correctOptionId": "a", "explanation": "Luật Di sản văn hóa nghiêm cấm các hành vi chiếm đoạt, hủy hoại hoặc làm sai lệch hiện vật, cảnh quan di tích lịch sử - văn hóa."}, {"id": "economics_law-12-general-international-law-foundations-q1", "prompt": "Chủ thể cơ bản, ban đầu và giữ vai trò trung tâm nhất trong hệ thống pháp luật quốc tế hiện đại là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Các quốc gia độc lập có chủ quyền"}, {"id": "b", "text": "Các cá nhân công dân mang quốc tịch bất kì"}, {"id": "c", "text": "Các câu lạc bộ thể thao và tập đoàn tư nhân đa quốc gia"}], "correctOptionId": "a", "explanation": "Quốc gia có chủ quyền là chủ thể chủ yếu và cơ bản nhất của luật quốc tế, có đầy đủ thẩm quyền kí kết và thực thi các cam kết quốc tế."}, {"id": "economics_law-12-general-international-law-foundations-q2", "prompt": "Nguyên tắc ''Pacta sunt servanda'' - một trong những nguyên tắc nền tảng linh hồn của luật pháp quốc tế đòi hỏi các quốc gia phải:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Được quyền đơn phương hủy bỏ các điều ước quốc tế bất cứ lúc nào cảm thấy bất lợi cho riêng mình"}, {"id": "b", "text": "Chỉ cần thực hiện các cam kết nếu nhận được sự đồng ý của tất cả các tập đoàn tư nhân"}, {"id": "c", "text": "Tận tâm, thiện chí thực hiện đầy đủ các cam kết và nghĩa vụ trong các điều ước quốc tế mà mình đã kí kết hoặc gia nhập"}], "correctOptionId": "c", "explanation": "Pacta sunt servanda là nguyên tắc thượng tôn các cam kết quốc tế, bảo đảm tính ổn định, tin cậy và pháp quyền trong trật tự quan hệ quốc tế."}, {"id": "economics_law-12-public-international-law-territory-sovereignty-q1", "prompt": "Theo công pháp quốc tế, lãnh thổ quốc gia hoàn chỉnh được cấu thành từ bốn bộ phận không gian địa lí nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Vùng đất liền canh tác nông nghiệp và không tính vùng trời"}, {"id": "b", "text": "Chỉ bao gồm các hải đảo nằm ngoài vùng đặc quyền kinh tế"}, {"id": "c", "text": "Vùng đất, vùng nước, vùng trời và vùng lòng đất"}], "correctOptionId": "c", "explanation": "Lãnh thổ quốc gia là một thể thống nhất gồm 4 bộ phận: vùng đất, vùng nước (nội thủy, lãnh hải), vùng lòng đất và vùng trời phía trên."}, {"id": "economics_law-12-public-international-law-territory-sovereignty-q2", "prompt": "Tính chất ''bất khả xâm phạm'' của chủ quyền và lãnh thổ quốc gia trong luật pháp quốc tế mang ý nghĩa cốt lõi là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Quốc gia ven biển không có quyền quản lí tàu thuyền hoạt động trong vùng biển thuộc chủ quyền của mình"}, {"id": "b", "text": "Mọi hành vi xâm lấn biên giới, đe dọa độc lập và toàn vẹn lãnh thổ của một quốc gia đều là hành vi vi phạm pháp luật quốc tế nghiêm trọng"}, {"id": "c", "text": "Các cường quốc lớn có quyền tự do can thiệp quân sự vào vùng trời của các quốc gia nhỏ hơn"}], "correctOptionId": "b", "explanation": "Luật pháp quốc tế nghiêm cấm mọi hành vi xâm lấn, chiếm đoạt lãnh thổ hoặc can thiệp lật đổ chủ quyền thiêng liêng của một quốc gia độc lập."}, {"id": "economics_law-12-wto-principles-international-commercial-contracts-q1", "prompt": "Nguyên tắc ''Đãi ngộ tối huệ quốc'' (MFN) trong hệ thống thương mại đa phương của WTO quy định điều gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cho phép các nước giàu áp thuế nhập khẩu cao gấp mười lần đối với hàng hóa xuất xứ từ các nước nghèo"}, {"id": "b", "text": "Nếu một thành viên dành ưu đãi thương mại cho một quốc gia thì phải dành ưu đãi tương tự cho tất cả các thành viên khác của WTO"}, {"id": "c", "text": "Chỉ dành ưu đãi thuế quan đặc biệt cho các quốc gia láng giềng có chung đường biên giới đất liền"}], "correctOptionId": "b", "explanation": "Nguyên tắc MFN bảo đảm không phân biệt đối xử giữa các đối tác thương mại: lợi thế dành cho một nước phải được trao bình đẳng cho toàn bộ thành viên WTO."}, {"id": "economics_law-12-wto-principles-international-commercial-contracts-q2", "prompt": "Nguyên tắc ''Đãi ngộ quốc gia'' (NT) của WTO nghiêm cấm hành vi nào sau đây của nước nhập khẩu đối với hàng hóa nước ngoài?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Áp đặt mức thuế tiêu thụ nội địa hoặc quy chuẩn kĩ thuật khắt khe hơn đối với hàng hóa nhập khẩu so với hàng hóa cùng loại sản xuất trong nước"}, {"id": "b", "text": "Thực hiện kiểm tra an toàn thực phẩm bình đẳng đối với mọi lô hàng lưu thông trên thị trường nội địa"}, {"id": "c", "text": "Cắt giảm biểu thuế quan nhập khẩu theo đúng lộ trình cam kết gia nhập WTO"}], "correctOptionId": "a", "explanation": "Nguyên tắc NT yêu cầu hàng nhập khẩu sau khi qua cửa khẩu phải được đối xử công bằng ngang bằng với hàng nội địa, không bị phân biệt đối xử về thuế và quy chuẩn kĩ thuật."}]'::jsonb,'[]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-economic-growth-development',1,'LESSON','Tăng trưởng kinh tế và phát triển kinh tế bền vững','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Tăng trưởng kinh tế là sự gia tăng về quy mô sản lượng hàng hóa và dịch vụ của nền kinh tế trong một thời kì nhất định, đo bằng GDP (Tổng sản phẩm quốc nội), GNI (Tổng thu nhập quốc gia) hoặc GDP bình quân đầu người. Phát triển kinh tế là khái niệm rộng hơn: bao gồm tăng trưởng kinh tế đi đôi với hoàn thiện cơ cấu kinh tế tiến bộ, nâng cao chất lượng cuộc sống và bảo đảm công bằng xã hội (đo bằng chỉ số phát triển con người HDI). Phát triển bền vững đòi hỏi kết hợp hài hòa giữa tăng trưởng kinh tế, tiến bộ xã hội và bảo vệ môi trường sinh thái cho các thế hệ tương lai."]'::jsonb,'["Một quốc gia có GDP tăng trưởng 8% mỗi năm nhưng môi trường bị hủy hoại nghiêm trọng và khoảng cách giàu nghèo đào sâu thì chưa đạt được sự phát triển bền vững."]'::jsonb,'[{"id": "economics_law-12-economic-growth-development-q1", "prompt": "Chỉ tiêu kinh tế vĩ mô nào sau đây phản ánh tổng giá trị thị trường của toàn bộ hàng hóa và dịch vụ cuối cùng được sản xuất ra trên lãnh thổ một quốc gia trong năm?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tổng sản phẩm quốc nội (GDP)"}, {"id": "b", "text": "Chỉ số giá tiêu dùng (CPI)"}, {"id": "c", "text": "Tỉ lệ lạm phát hàng tháng"}], "correctOptionId": "a", "explanation": "GDP (Gross Domestic Product) đo lường toàn bộ giá trị gia tăng tạo ra bên trong biên giới địa lí của quốc gia."}, {"id": "economics_law-12-economic-growth-development-q2", "prompt": "Điểm khác biệt căn bản giữa ''phát triển kinh tế'' và ''tăng trưởng kinh tế'' là gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Phát triển kinh tế chỉ tính riêng số lượng máy móc sản xuất trong một ngày"}, {"id": "b", "text": "Tăng trưởng kinh tế có phạm vi rộng lớn hơn phát triển kinh tế"}, {"id": "c", "text": "Phát triển kinh tế bao hàm tăng trưởng kinh tế kết hợp với tiến bộ cơ cấu xã hội, cải thiện đời sống và bảo vệ môi trường"}], "correctOptionId": "c", "explanation": "Tăng trưởng thuần túy về mặt số lượng (quy mô GDP), còn phát triển bao hàm cả sự biến đổi về chất lượng cuộc sống (giáo dục, y tế, bình đẳng xã hội)."}, {"id": "economics_law-12-economic-growth-development-q3", "prompt": "Chỉ số phát triển con người (HDI) của một quốc gia được tính toán dựa trên tổng hợp ba tiêu chí cơ bản nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Quy mô lực lượng quân đội, số lượng vũ khí và ngân sách quốc phòng"}, {"id": "b", "text": "Thu nhập bình quân đầu người, tuổi thọ kì vọng (sức khỏe) và trình độ học vấn (giáo dục)"}, {"id": "c", "text": "Số lượng xe ô tô cá nhân, diện tích nhà ở và số lượng siêu thị"}], "correctOptionId": "b", "explanation": "HDI do Liên hợp quốc phát triển kết hợp ba yếu tố: mức sống (GNI/người), sức khỏe (tuổi thọ sinh ra) và tri thức (số năm đi học kì vọng và trung bình)."}]'::jsonb,'["economics_law-12-economic-growth-development"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-international-economic-integration',2,'LESSON','Hội nhập kinh tế quốc tế và các hiệp định thương mại tự do','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Hội nhập kinh tế quốc tế là quá trình một quốc gia chủ động gắn kết nền kinh tế của mình với nền kinh tế khu vực và thế giới thông qua các nỗ lực tự do hóa thương mại, đầu tư và tài chính. Các cấp độ hội nhập: song phương (BTA Việt - Mĩ), khu vực (Cộng đồng Kinh tế ASEAN - AEC), đa phương toàn cầu (WTO). Các hiệp định thương mại tự do thế hệ mới tiêu biểu: CPTPP, EVFTA, RCEP với cam kết cắt giảm gần như toàn bộ thuế quan, bảo hộ sở hữu trí tuệ, tiêu chuẩn lao động và môi trường. Cơ hội: mở rộng xuất khẩu, thu hút FDI; Thách thức: cạnh tranh khốc liệt và nguy cơ phụ thuộc chuỗi cung ứng."]'::jsonb,'["Nhờ Hiệp định EVFTA, các mặt hàng nông sản xuất khẩu của Việt Nam như hạt điều, cà phê, thủy sản khi nhập khẩu vào Liên minh châu Âu (EU) được hưởng thuế suất ưu đãi 0%, tạo lợi thế cạnh tranh vượt trội."]'::jsonb,'[{"id": "economics_law-12-international-economic-integration-q1", "prompt": "Tổ chức kinh tế đa phương toàn cầu lớn nhất mà Việt Nam gia nhập năm 2007 để hòa mạng sâu rộng vào thương mại quốc tế là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Quỹ Tiền tệ Quốc tế (IMF)"}, {"id": "b", "text": "Tổ chức Các nước Xuất khẩu Dầu mỏ (OPEC)"}, {"id": "c", "text": "Tổ chức Thương mại Thế giới (WTO)"}], "correctOptionId": "c", "explanation": "Việt Nam trở thành thành viên thứ 150 của WTO vào ngày 11/1/2007 sau hơn 11 năm đàm phán."}, {"id": "economics_law-12-international-economic-integration-q2", "prompt": "Đặc điểm nổi bật của các hiệp định thương mại tự do thế hệ mới (như CPTPP, EVFTA) so với các hiệp định truyền thống là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bắt buộc các nước tham gia phải sử dụng chung một loại tiền tệ duy nhất"}, {"id": "b", "text": "Có phạm vi cam kết sâu rộng hơn, bao gồm cả các vấn đề phi thương mại như môi trường, quyền lao động và sở hữu trí tuệ"}, {"id": "c", "text": "Chỉ cam kết trao đổi hàng hóa nông sản thô mà không có dịch vụ"}], "correctOptionId": "b", "explanation": "FTA thế hệ mới không chỉ xóa bỏ dòng thuế quan mà còn đặt ra các tiêu chuẩn minh bạch hóa, bảo vệ người lao động và phát triển xanh."}, {"id": "economics_law-12-international-economic-integration-q3", "prompt": "Thách thức lớn nhất đối với các doanh nghiệp sản xuất trong nước khi Việt Nam mở cửa hội nhập kinh tế sâu rộng là gì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Phải cạnh tranh gay gắt với hàng hóa, dịch vụ ngoại nhập có chất lượng cao và giá thành cạnh tranh ngay tại thị trường nội địa"}, {"id": "b", "text": "Không được phép xuất khẩu hàng hóa ra thị trường thế giới"}, {"id": "c", "text": "Bị cấm hoàn toàn việc ứng dụng công nghệ nước ngoài vào sản xuất"}], "correctOptionId": "a", "explanation": "Hàng rào thuế quan hạ về 0% khiến hàng hóa ngoại nhập tràn vào, đòi hỏi doanh nghiệp trong nước phải nâng cao năng suất và chất lượng để tồn tại."}]'::jsonb,'["economics_law-12-international-economic-integration"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-insurance-welfare-system',3,'LESSON','Bảo hiểm và hệ thống an sinh xã hội','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Bảo hiểm là phương thức phân tán rủi ro tài chính giữa những người cùng tham gia đóng góp vào quỹ bảo hiểm để bồi thường cho người gặp tổn thất. Các loại bảo hiểm: Bảo hiểm xã hội (BHXH bắt buộc và BHXH tự nguyện gồm các chế độ: ốm đau, thai sản, tai nạn lao động, hưu trí, tử tuất); Bảo hiểm y tế (BHYT hỗ trợ chi phí khám chữa bệnh); Bảo hiểm thất nghiệp (BHTN hỗ trợ khi mất việc làm); Bảo hiểm thương mại (nhân thọ, phi nhân thọ vì mục đích kinh doanh). Hệ thống an sinh xã hội là trụ cột bảo đảm quyền cơ bản của mọi công dân về thu nhập tối thiểu và trợ giúp xã hội khi gặp rủi ro."]'::jsonb,'["Khi không may bị ốm đau phải nằm viện phẫu thuật tốn hàng chục triệu đồng, thẻ Bảo hiểm y tế (BHYT) đã chi trả tới 80% - 100% chi phí điều trị, giúp gia đình người bệnh vượt qua gánh nặng tài chính."]'::jsonb,'[{"id": "economics_law-12-insurance-welfare-system-q1", "prompt": "Loại hình bảo hiểm phi lợi nhuận do Nhà nước tổ chức nhằm bảo đảm quyền lợi khám chữa bệnh cho người dân là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Bảo hiểm cháy nổ nhà xưởng tư nhân"}, {"id": "b", "text": "Bảo hiểm y tế (BHYT)"}, {"id": "c", "text": "Bảo hiểm ô tô thương mại"}], "correctOptionId": "b", "explanation": "BHYT là chính sách an sinh xã hội ưu việt của Đảng và Nhà nước nhằm chăm sóc sức khỏe cộng đồng, không vì mục đích kiếm lợi nhuận."}, {"id": "economics_law-12-insurance-welfare-system-q2", "prompt": "Người lao động tham gia Bảo hiểm xã hội bắt buộc đủ điều kiện theo quy định được hưởng những chế độ cốt lõi nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ốm đau, thai sản, tai nạn lao động - bệnh nghề nghiệp, hưu trí và tử tuất"}, {"id": "b", "text": "Chế độ thưởng du lịch châu Âu hàng năm"}, {"id": "c", "text": "Được cấp miễn phí nhà ở cao cấp và xe hơi cá nhân"}], "correctOptionId": "a", "explanation": "Luật BHXH quy định rõ 5 chế độ của BHXH bắt buộc nhằm bảo đảm an sinh trọn đời cho người lao động từ khi đi làm đến lúc về già."}, {"id": "economics_law-12-insurance-welfare-system-q3", "prompt": "Ý nghĩa xã hội to lớn nhất của chính sách Bảo hiểm thất nghiệp (BHTN) đối với người lao động là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Khuyến khích người lao động nghỉ việc ở nhà không cần đi làm nữa"}, {"id": "b", "text": "Bắt buộc người sử dụng lao động phải trả lương vĩnh viễn cho người đã nghỉ việc"}, {"id": "c", "text": "Hỗ trợ một phần thu nhập, tư vấn học nghề và giới thiệu việc làm mới để người lao động sớm ổn định lại cuộc sống"}], "correctOptionId": "c", "explanation": "BHTN là phao cứu sinh bù đắp tài chính tạm thời và hỗ trợ học nghề chuyển đổi việc làm khi người lao động không may bị mất việc."}]'::jsonb,'["economics_law-12-insurance-welfare-system"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-business-plan-startup',4,'LESSON','Lập kế hoạch kinh doanh và khởi nghiệp sáng tạo','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Kế hoạch kinh doanh là văn bản phác thảo chi tiết mục tiêu, chiến lược và các bước triển khai ý tưởng kinh doanh trong một khoảng thời gian xác định. Các cấu phần chính: Ý tưởng kinh doanh và sự khác biệt; Phân tích thị trường và khách hàng mục tiêu; Kế hoạch sản phẩm/dịch vụ và vận hành; Kế hoạch marketing và bán hàng; Kế hoạch tài chính (vốn đầu tư ban đầu, dự toán doanh thu, chi phí cố định/biến đổi, điểm hòa vốn và dòng tiền). Khởi nghiệp đổi mới sáng tạo (Startup) dựa trên công nghệ mới hoặc mô hình kinh doanh đột phá, chấp nhận rủi ro để tăng trưởng nhanh."]'::jsonb,'["Hai bạn trẻ sáng lập ứng dụng kết nối nông dân với các cửa hàng rau sạch đô thị đã lập kế hoạch kinh doanh tính toán hòa vốn sau 12 tháng với 500 khách hàng thường xuyên, gọi vốn thành công từ nhà đầu tư thiên thần."]'::jsonb,'[{"id": "economics_law-12-business-plan-startup-q1", "prompt": "Bước đầu tiên và giữ vai trò định hướng trong quá trình xây dựng một bản kế hoạch kinh doanh là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Xác định ý tưởng kinh doanh và giá trị độc đáo mang lại cho khách hàng"}, {"id": "b", "text": "Đi vay ngân hàng số tiền tối đa có thể"}, {"id": "c", "text": "Thuê ngay mặt bằng đắt nhất ở trung tâm thành phố"}], "correctOptionId": "a", "explanation": "Ý tưởng kinh doanh xuất phát từ việc phát hiện nhu cầu chưa được đáp ứng tốt trên thị trường là nền tảng khởi đầu của kế hoạch."}, {"id": "economics_law-12-business-plan-startup-q2", "prompt": "Điểm hòa vốn (Break-even point) trong kế hoạch tài chính của một cơ sở kinh doanh là thời điểm:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Lợi nhuận ròng đạt mức cao nhất trong toàn bộ chu kì"}, {"id": "b", "text": "Doanh nghiệp bị phá sản và phải bán thanh lí tài sản"}, {"id": "c", "text": "Tổng doanh thu thu về vừa đủ bù đắp toàn bộ tổng chi phí bỏ ra (lợi nhuận bằng 0)"}], "correctOptionId": "c", "explanation": "Tại điểm hòa vốn, doanh thu bằng chi phí (TR = TC); vượt qua điểm này doanh nghiệp bắt đầu có lãi ròng."}, {"id": "economics_law-12-business-plan-startup-q3", "prompt": "Đặc trưng quan trọng nhất phân biệt ''khởi nghiệp đổi mới sáng tạo'' (Startup) với việc mở một cửa hàng kinh doanh truyền thống là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Hoàn toàn không cần nghiên cứu thị trường hay xây dựng sản phẩm"}, {"id": "b", "text": "Tính đột phá về công nghệ hoặc mô hình kinh doanh mới, có tiềm năng tăng trưởng quy mô thần tốc nhưng đi kèm rủi ro cao"}, {"id": "c", "text": "Chỉ sử dụng tiền vốn do Nhà nước tài trợ 100% không hoàn lại"}], "correctOptionId": "b", "explanation": "Startup ứng dụng công nghệ hoặc giải pháp sáng tạo để giải quyết một bài toán thị trường lớn với khả năng nhân rộng quy mô nhanh chóng."}]'::jsonb,'["economics_law-12-business-plan-startup"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-corporate-social-responsibility',5,'LESSON','Trách nhiệm xã hội của doanh nghiệp (CSR) và đạo đức kinh doanh','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Trách nhiệm xã hội của doanh nghiệp (CSR) là sự cam kết tự nguyện của doanh nghiệp đóng góp vào sự phát triển bền vững thông qua việc bảo đảm lợi ích của người lao động, khách hàng, cộng đồng và môi trường. Tháp trách nhiệm CSR gồm: Trách nhiệm kinh tế (tạo lợi nhuận lành mạnh), Trách nhiệm pháp lí (tuân thủ luật pháp), Trách nhiệm đạo đức (kinh doanh công bằng, trung thực), Trách nhiệm nhân văn/từ thiện (đóng góp cộng đồng). Đạo đức kinh doanh tạo dựng uy tín, niềm tin khách hàng và nâng cao năng lực cạnh tranh dài hạn."]'::jsonb,'["Một doanh nghiệp may mặc lắp đặt hệ thống điện mặt trời mái nhà và xử lí 100% nước thải nhuộm đạt chuẩn sinh thái đã nhận được nhiều đơn hàng lớn từ các đối tác khó tính ở châu Âu."]'::jsonb,'[{"id": "economics_law-12-corporate-social-responsibility-q1", "prompt": "Tầng nền tảng cơ bản đầu tiên trong tháp trách nhiệm xã hội của một doanh nghiệp là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Trách nhiệm tài trợ nghệ thuật quốc tế"}, {"id": "b", "text": "Trách nhiệm tặng quà miễn phí cho tất cả mọi người"}, {"id": "c", "text": "Trách nhiệm kinh tế (hoạt động kinh doanh có hiệu quả, tạo ra sản phẩm và việc làm)"}], "correctOptionId": "c", "explanation": "Doanh nghiệp trước hết phải vận hành hiệu quả, tạo ra lợi nhuận và việc làm chính đáng thì mới có nguồn lực thực hiện các trách nhiệm cao hơn."}, {"id": "economics_law-12-corporate-social-responsibility-q2", "prompt": "Hành vi nào sau đây biểu hiện sự vi phạm nghiêm trọng đạo đức kinh doanh và trách nhiệm xã hội?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cung cấp thông tin trung thực về hạn sử dụng và thành phần sản phẩm"}, {"id": "b", "text": "Xả chất thải độc hại chưa qua xử lí ra sông hồ để cắt giảm chi phí sản xuất"}, {"id": "c", "text": "Trả lương và đóng bảo hiểm xã hội đầy đủ cho nhân viên"}], "correctOptionId": "b", "explanation": "Hành vi lén lút xả thải gây ô nhiễm môi trường hủy hoại hệ sinh thái và sức khỏe cộng đồng là vi phạm pháp luật và đạo đức nghiêm trọng."}, {"id": "economics_law-12-corporate-social-responsibility-q3", "prompt": "Lợi ích lâu dài lớn nhất mà việc thực hiện tốt trách nhiệm xã hội (CSR) mang lại cho doanh nghiệp là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Xây dựng hình ảnh thương hiệu uy tín, gia tăng niềm tin của khách hàng và thu hút nhà đầu tư chất lượng"}, {"id": "b", "text": "Làm cho sản phẩm hoàn toàn không cần kiểm định chất lượng"}, {"id": "c", "text": "Giúp doanh nghiệp được miễn hoàn toàn mọi loại thuế suốt đời"}], "correctOptionId": "a", "explanation": "CSR nâng cao giá trị vô hình của thương hiệu, tạo sự gắn kết của người lao động và mở ra cơ hội tham gia chuỗi cung ứng toàn cầu."}]'::jsonb,'["economics_law-12-corporate-social-responsibility"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-review-1',6,'FIVE_LESSON_REVIEW','Ôn tập 1','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "economics_law-12-economic-growth-development-q1", "prompt": "Chỉ tiêu kinh tế vĩ mô nào sau đây phản ánh tổng giá trị thị trường của toàn bộ hàng hóa và dịch vụ cuối cùng được sản xuất ra trên lãnh thổ một quốc gia trong năm?", "difficulty": "EASY", "options": [{"id": "a", "text": "Tổng sản phẩm quốc nội (GDP)"}, {"id": "b", "text": "Chỉ số giá tiêu dùng (CPI)"}, {"id": "c", "text": "Tỉ lệ lạm phát hàng tháng"}], "correctOptionId": "a", "explanation": "GDP (Gross Domestic Product) đo lường toàn bộ giá trị gia tăng tạo ra bên trong biên giới địa lí của quốc gia."}, {"id": "economics_law-12-economic-growth-development-q2", "prompt": "Điểm khác biệt căn bản giữa ''phát triển kinh tế'' và ''tăng trưởng kinh tế'' là gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Phát triển kinh tế chỉ tính riêng số lượng máy móc sản xuất trong một ngày"}, {"id": "b", "text": "Tăng trưởng kinh tế có phạm vi rộng lớn hơn phát triển kinh tế"}, {"id": "c", "text": "Phát triển kinh tế bao hàm tăng trưởng kinh tế kết hợp với tiến bộ cơ cấu xã hội, cải thiện đời sống và bảo vệ môi trường"}], "correctOptionId": "c", "explanation": "Tăng trưởng thuần túy về mặt số lượng (quy mô GDP), còn phát triển bao hàm cả sự biến đổi về chất lượng cuộc sống (giáo dục, y tế, bình đẳng xã hội)."}, {"id": "economics_law-12-international-economic-integration-q1", "prompt": "Tổ chức kinh tế đa phương toàn cầu lớn nhất mà Việt Nam gia nhập năm 2007 để hòa mạng sâu rộng vào thương mại quốc tế là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Quỹ Tiền tệ Quốc tế (IMF)"}, {"id": "b", "text": "Tổ chức Các nước Xuất khẩu Dầu mỏ (OPEC)"}, {"id": "c", "text": "Tổ chức Thương mại Thế giới (WTO)"}], "correctOptionId": "c", "explanation": "Việt Nam trở thành thành viên thứ 150 của WTO vào ngày 11/1/2007 sau hơn 11 năm đàm phán."}, {"id": "economics_law-12-international-economic-integration-q2", "prompt": "Đặc điểm nổi bật của các hiệp định thương mại tự do thế hệ mới (như CPTPP, EVFTA) so với các hiệp định truyền thống là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Bắt buộc các nước tham gia phải sử dụng chung một loại tiền tệ duy nhất"}, {"id": "b", "text": "Có phạm vi cam kết sâu rộng hơn, bao gồm cả các vấn đề phi thương mại như môi trường, quyền lao động và sở hữu trí tuệ"}, {"id": "c", "text": "Chỉ cam kết trao đổi hàng hóa nông sản thô mà không có dịch vụ"}], "correctOptionId": "b", "explanation": "FTA thế hệ mới không chỉ xóa bỏ dòng thuế quan mà còn đặt ra các tiêu chuẩn minh bạch hóa, bảo vệ người lao động và phát triển xanh."}, {"id": "economics_law-12-insurance-welfare-system-q1", "prompt": "Loại hình bảo hiểm phi lợi nhuận do Nhà nước tổ chức nhằm bảo đảm quyền lợi khám chữa bệnh cho người dân là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Bảo hiểm cháy nổ nhà xưởng tư nhân"}, {"id": "b", "text": "Bảo hiểm y tế (BHYT)"}, {"id": "c", "text": "Bảo hiểm ô tô thương mại"}], "correctOptionId": "b", "explanation": "BHYT là chính sách an sinh xã hội ưu việt của Đảng và Nhà nước nhằm chăm sóc sức khỏe cộng đồng, không vì mục đích kiếm lợi nhuận."}, {"id": "economics_law-12-insurance-welfare-system-q2", "prompt": "Người lao động tham gia Bảo hiểm xã hội bắt buộc đủ điều kiện theo quy định được hưởng những chế độ cốt lõi nào?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Ốm đau, thai sản, tai nạn lao động - bệnh nghề nghiệp, hưu trí và tử tuất"}, {"id": "b", "text": "Chế độ thưởng du lịch châu Âu hàng năm"}, {"id": "c", "text": "Được cấp miễn phí nhà ở cao cấp và xe hơi cá nhân"}], "correctOptionId": "a", "explanation": "Luật BHXH quy định rõ 5 chế độ của BHXH bắt buộc nhằm bảo đảm an sinh trọn đời cho người lao động từ khi đi làm đến lúc về già."}, {"id": "economics_law-12-business-plan-startup-q1", "prompt": "Bước đầu tiên và giữ vai trò định hướng trong quá trình xây dựng một bản kế hoạch kinh doanh là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Xác định ý tưởng kinh doanh và giá trị độc đáo mang lại cho khách hàng"}, {"id": "b", "text": "Đi vay ngân hàng số tiền tối đa có thể"}, {"id": "c", "text": "Thuê ngay mặt bằng đắt nhất ở trung tâm thành phố"}], "correctOptionId": "a", "explanation": "Ý tưởng kinh doanh xuất phát từ việc phát hiện nhu cầu chưa được đáp ứng tốt trên thị trường là nền tảng khởi đầu của kế hoạch."}, {"id": "economics_law-12-business-plan-startup-q2", "prompt": "Điểm hòa vốn (Break-even point) trong kế hoạch tài chính của một cơ sở kinh doanh là thời điểm:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Lợi nhuận ròng đạt mức cao nhất trong toàn bộ chu kì"}, {"id": "b", "text": "Doanh nghiệp bị phá sản và phải bán thanh lí tài sản"}, {"id": "c", "text": "Tổng doanh thu thu về vừa đủ bù đắp toàn bộ tổng chi phí bỏ ra (lợi nhuận bằng 0)"}], "correctOptionId": "c", "explanation": "Tại điểm hòa vốn, doanh thu bằng chi phí (TR = TC); vượt qua điểm này doanh nghiệp bắt đầu có lãi ròng."}, {"id": "economics_law-12-corporate-social-responsibility-q1", "prompt": "Tầng nền tảng cơ bản đầu tiên trong tháp trách nhiệm xã hội của một doanh nghiệp là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Trách nhiệm tài trợ nghệ thuật quốc tế"}, {"id": "b", "text": "Trách nhiệm tặng quà miễn phí cho tất cả mọi người"}, {"id": "c", "text": "Trách nhiệm kinh tế (hoạt động kinh doanh có hiệu quả, tạo ra sản phẩm và việc làm)"}], "correctOptionId": "c", "explanation": "Doanh nghiệp trước hết phải vận hành hiệu quả, tạo ra lợi nhuận và việc làm chính đáng thì mới có nguồn lực thực hiện các trách nhiệm cao hơn."}, {"id": "economics_law-12-corporate-social-responsibility-q2", "prompt": "Hành vi nào sau đây biểu hiện sự vi phạm nghiêm trọng đạo đức kinh doanh và trách nhiệm xã hội?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Cung cấp thông tin trung thực về hạn sử dụng và thành phần sản phẩm"}, {"id": "b", "text": "Xả chất thải độc hại chưa qua xử lí ra sông hồ để cắt giảm chi phí sản xuất"}, {"id": "c", "text": "Trả lương và đóng bảo hiểm xã hội đầy đủ cho nhân viên"}], "correctOptionId": "b", "explanation": "Hành vi lén lút xả thải gây ô nhiễm môi trường hủy hoại hệ sinh thái và sức khỏe cộng đồng là vi phạm pháp luật và đạo đức nghiêm trọng."}]'::jsonb,'["economics_law-12-economic-growth-development", "economics_law-12-international-economic-integration", "economics_law-12-insurance-welfare-system", "economics_law-12-business-plan-startup", "economics_law-12-corporate-social-responsibility"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-personal-household-budget',7,'LESSON','Quản lí tài chính cá nhân và kế hoạch tài chính hộ gia đình','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Quản lí tài chính cá nhân là quá trình lập kế hoạch thu chi, tiết kiệm và đầu tư để đạt được các mục tiêu tài chính tự do và an toàn. Quy tắc ngân sách thông dụng 50/30/20: 50% cho nhu cầu thiết yếu (ăn uống, nhà ở, học tập), 30% cho mong muốn cá nhân (giải trí, mua sắm), 20% cho tiết kiệm và đầu tư trả nợ. Các nguyên tắc: lập quỹ dự phòng khẩn cấp (tương đương 3 - 6 tháng chi phí thiết yếu), tránh bẫy nợ tín dụng tiêu dùng lãi suất cao, chi tiêu dưới mức thu nhập và thiết lập kế hoạch tài chính hộ gia đình dài hạn."]'::jsonb,'["Với thu nhập 10 triệu đồng/tháng, bạn trẻ dành 5 triệu cho sinh hoạt phí, 3 triệu cho học tập giải trí và kiên trì trích ngay 2 triệu đồng vào tài khoản tiết kiệm tích lũy đầu tháng."]'::jsonb,'[{"id": "economics_law-12-personal-household-budget-q1", "prompt": "Theo quy tắc quản lí ngân sách tài chính cá nhân 50/30/20, tỉ lệ 20% thu nhập nên được ưu tiên cho mục tiêu nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chi trả tiền thuê nhà và tiền ăn uống hàng ngày"}, {"id": "b", "text": "Tiết kiệm, lập quỹ dự phòng khẩn cấp hoặc đầu tư trả nợ"}, {"id": "c", "text": "Đi du lịch nghỉ dưỡng cao cấp hàng tháng"}], "correctOptionId": "b", "explanation": "20% khoản tiền này là đòn bẩy tích lũy tạo sự an tâm tài chính và sinh lời dài hạn trong tương lai."}, {"id": "economics_law-12-personal-household-budget-q2", "prompt": "Mục đích cốt lõi của việc xây dựng ''quỹ dự phòng khẩn cấp'' (tương đương 3 - 6 tháng chi phí) là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chủ động ứng phó tài chính trước các biến cố bất ngờ như ốm đau, mất việc làm hoặc hư hỏng thiết bị thiết yếu mà không phải vay nợ lãi cao"}, {"id": "b", "text": "Dùng toàn bộ để tham gia các trò chơi may rủi trên mạng xã hội"}, {"id": "c", "text": "Mua sắm những món đồ xa xỉ giảm giá nhất thời"}], "correctOptionId": "a", "explanation": "Quỹ khẩn cấp bảo vệ cá nhân khỏi nguy cơ vỡ nợ khi xảy ra rủi ro gián đoạn nguồn thu nhập chính."}, {"id": "economics_law-12-personal-household-budget-q3", "prompt": "Một thói quen chi tiêu tài chính thông minh giúp tránh rơi vào bẫy nợ nần là:", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Thấy món đồ mình thích là vay tiền mua ngay lập tức bất kể giá cả"}, {"id": "b", "text": "Chi tiêu hết toàn bộ tiền lương ngay trong tuần đầu tiên của tháng"}, {"id": "c", "text": "Luôn lập ngân sách trước khi chi tiêu, phân biệt rõ giữa ''nhu cầu cần thiết'' (Needs) và ''mong muốn nhất thời'' (Wants)"}], "correctOptionId": "c", "explanation": "Kiểm soát cảm xúc mua sắm và cân nhắc giữa nhu cầu thiết yếu với sở thích nhất thời giúp duy trì dòng tiền cá nhân luôn dương."}]'::jsonb,'["economics_law-12-personal-household-budget"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-business-tax-citizenship',8,'LESSON','Quyền và nghĩa vụ của công dân về kinh doanh và nộp thuế','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Theo Hiến pháp năm 2013, Luật Doanh nghiệp và Luật Quản lý thuế, công dân có quyền tự do kinh doanh những ngành, nghề mà luật không cấm; tự chủ lựa chọn ngành nghề, hình thức tổ chức kinh doanh, quy mô và đối tác. Đi đôi với quyền tự do kinh doanh là nghĩa vụ đăng kí kinh doanh đúng quy định; kê khai trung thực, chính xác và nộp đầy đủ, đúng hạn các khoản thuế, phí vào ngân sách nhà nước; tuân thủ quy chuẩn về an toàn vệ sinh lao động, bảo vệ môi trường và quyền lợi khách hàng. Pháp luật nghiêm cấm các hành vi trốn thuế, gian lận thuế và kinh doanh hàng cấm."]'::jsonb,'["Chị Mai đăng kí thành lập hộ kinh doanh nông sản sạch tại địa phương, sử dụng hóa đơn điện tử và nộp thuế giá trị gia tăng, thuế thu nhập cá nhân định kì qua ứng dụng thuế điện tử đúng hạn."]'::jsonb,'[{"id": "economics_law-12-business-tax-citizenship-q1", "prompt": "Theo quy định của Hiến pháp năm 2013 và pháp luật Việt Nam, công dân có quyền tự do kinh doanh trong phạm vi nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Trong những ngành, nghề và lĩnh vực mà luật không cấm"}, {"id": "b", "text": "Trong tất cả mọi lĩnh vực kể cả kinh doanh chất ma túy và vũ khí quân dụng"}, {"id": "c", "text": "Chỉ được phép kinh doanh các mặt hàng nông sản truyền thống tại địa phương"}], "correctOptionId": "a", "explanation": "Điều 33 Hiến pháp 2013 quy định mọi người có quyền tự do kinh doanh trong những ngành nghề mà pháp luật không cấm."}, {"id": "economics_law-12-business-tax-citizenship-q2", "prompt": "Nghĩa vụ hiến định mang tính bắt buộc hàng đầu của mọi tổ chức, cá nhân khi tiến hành hoạt động kinh doanh đối với Nhà nước là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tự ý ấn định mức thuế phải nộp dựa trên mức lợi nhuận mong muốn của cá nhân"}, {"id": "b", "text": "Chỉ nộp thuế khi có sự kiểm tra trực tiếp của cơ quan thuế tại cơ sở kinh doanh"}, {"id": "c", "text": "Kê khai trung thực, chính xác và nộp đầy đủ, đúng thời hạn các khoản thuế theo luật định"}], "correctOptionId": "c", "explanation": "Nộp thuế là nghĩa vụ hiến định của công dân nhằm tạo nguồn lực tài chính công để Nhà nước xây dựng hạ tầng, bảo đảm an sinh và bảo vệ Tổ quốc."}, {"id": "economics_law-12-business-tax-citizenship-q3", "prompt": "Anh Bình mở cơ sở chế biến thực phẩm nhưng không làm thủ tục đăng kí kinh doanh, sử dụng hóa chất ngoài danh mục cho phép và cố tình không kê khai thuế. Hành vi của anh Bình vi phạm các nghĩa vụ nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Hoàn toàn hợp pháp vì công dân được quyền tự do sản xuất mọi loại thực phẩm"}, {"id": "b", "text": "Vi phạm nghĩa vụ đăng kí kinh doanh, nghĩa vụ bảo đảm an toàn thực phẩm và nghĩa vụ nộp thuế"}, {"id": "c", "text": "Chỉ vi phạm quy tắc ứng xử nội bộ gia đình mà không vi phạm quy định pháp luật"}], "correctOptionId": "b", "explanation": "Hành vi kinh doanh không phép, trốn thuế và vi phạm vệ sinh an toàn thực phẩm xâm phạm trật tự quản lí kinh tế và an toàn sức khỏe cộng đồng."}]'::jsonb,'["economics_law-12-business-tax-citizenship"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-property-ownership-rights-obligations',9,'LESSON','Quyền và nghĩa vụ về sở hữu tài sản và tôn trọng tài sản của người khác','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Theo Bộ luật Dân sự năm 2015, quyền sở hữu bao gồm ba quyền năng cơ bản của chủ sở hữu: quyền chiếm hữu (nắm giữ, chi phối tài sản), quyền sử dụng (khai thác công dụng, hưởng hoa lợi, lợi tức từ tài sản) và quyền định đoạt (chuyển giao quyền sở hữu, cho mượn, từ bỏ hoặc tiêu hủy tài sản). Mọi công dân có nghĩa vụ tôn trọng tài sản hợp pháp của người khác và tài sản công cộng của Nhà nước; khi gây thiệt hại đến tài sản của chủ thể khác thì phải bồi thường theo luật định. Pháp luật nghiêm cấm hành vi trộm cắp, lừa đảo, hủy hoại tài sản."]'::jsonb,'["Anh Tuấn thuê xe máy của cửa hàng trong 3 ngày; anh có quyền chiếm hữu và sử dụng xe để đi lại hợp pháp, nhưng không có quyền bán xe cho người khác và phải hoàn trả xe nguyên vẹn kèm bồi thường nếu làm hư hỏng."]'::jsonb,'[{"id": "economics_law-12-property-ownership-rights-obligations-q1", "prompt": "Theo quy định của Bộ luật Dân sự năm 2015, quyền sở hữu của chủ sở hữu bao gồm ba quyền năng cơ bản nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quyền phong tỏa, quyền phát mại và quyền chiếm đoạt tài sản"}, {"id": "b", "text": "Quyền vay mượn, quyền thế chấp và quyền giấu giếm tài sản"}, {"id": "c", "text": "Quyền chiếm hữu, quyền sử dụng và quyền định đoạt tài sản"}], "correctOptionId": "c", "explanation": "Điều 158 Bộ luật Dân sự 2015 quy định quyền sở hữu bao gồm quyền chiếm hữu, quyền sử dụng và quyền định đoạt tài sản của chủ sở hữu."}, {"id": "economics_law-12-property-ownership-rights-obligations-q2", "prompt": "Nghĩa vụ tôn trọng tài sản của người khác đòi hỏi mỗi công dân phải thực hiện hành vi nào sau đây khi nhặt được tài sản đánh rơi?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đem vứt bỏ tài sản đó xuống sông hồ để không ai tìm thấy"}, {"id": "b", "text": "Thông báo hoặc trả lại ngay cho người đánh rơi, hoặc giao nộp cho cơ quan công an gần nhất"}, {"id": "c", "text": "Tự ý cất giữ làm của riêng và mang bán lấy tiền chi tiêu cá nhân"}], "correctOptionId": "b", "explanation": "Pháp luật dân sự quy định người nhặt được của rơi có nghĩa vụ thông báo, trả lại cho chủ sở hữu hoặc giao nộp cơ quan có thẩm quyền."}, {"id": "economics_law-12-property-ownership-rights-obligations-q3", "prompt": "Do mâu thuẫn cá nhân, Nam đã cố ý đập vỡ máy tính xách tay của Minh có giá trị 18 triệu đồng. Về mặt pháp lí, hành vi cố ý phá hoại tài sản của Nam sẽ bị xử lí như thế nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Bị buộc bồi thường toàn bộ thiệt hại vật chất và có thể bị truy cứu trách nhiệm hình sự về tội cố ý làm hư hỏng tài sản"}, {"id": "b", "text": "Không phải chịu bất kì trách nhiệm bồi thường nào vì sự việc xảy ra trong độ tuổi học sinh"}, {"id": "c", "text": "Chỉ cần công khai xin lỗi Minh trước lớp mà không phải đền bù giá trị máy tính"}], "correctOptionId": "a", "explanation": "Hành vi cố ý làm hư hỏng tài sản của người khác từ 2 triệu đồng trở lên cấu thành tội phạm theo Điều 178 Bộ luật Hình sự và phải bồi thường dân sự toàn bộ thiệt hại."}]'::jsonb,'["economics_law-12-property-ownership-rights-obligations"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-marriage-family-rights-obligations',10,'LESSON','Quyền và nghĩa vụ của công dân trong hôn nhân và gia đình','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Luật Hôn nhân và Gia đình năm 2014 quy định các nguyên tắc cơ bản: hôn nhân tự nguyện, tiến bộ, một vợ một chồng, vợ chồng bình đẳng và tôn trọng lẫn nhau. Quyền và nghĩa vụ giữa vợ và chồng: bình đẳng về quyền, nghĩa vụ trong mọi mặt gia đình; cùng bàn bạc quyết định tài sản chung và kế hoạch chăm sóc gia đình. Quan hệ giữa cha mẹ và con: cha mẹ có nghĩa vụ nuôi dưỡng, giáo dục con phát triển lành mạnh; con cái có bổn phận yêu quý, kính trọng, chăm sóc và phụng dưỡng cha mẹ. Pháp luật nghiêm cấm bạo lực gia đình, tảo hôn, cưỡng ép kết hôn và phân biệt đối xử giữa các con."]'::jsonb,'["Vợ chồng anh Long cùng bàn bạc dân chủ, thống nhất kế hoạch chi tiêu tài chính gia đình và phân chia thời gian dạy dỗ các con mà không có sự áp đặt một chiều từ một phía."]'::jsonb,'[{"id": "economics_law-12-marriage-family-rights-obligations-q1", "prompt": "Nguyên tắc cốt lõi hàng đầu của chế độ hôn nhân và gia đình theo pháp luật Việt Nam hiện hành là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Cho phép kết hôn với nhiều người cùng một lúc để mở rộng quan hệ họ hàng"}, {"id": "b", "text": "Hôn nhân tự nguyện, tiến bộ, một vợ một chồng, vợ chồng bình đẳng"}, {"id": "c", "text": "Hôn nhân hoàn toàn do cha mẹ sắp đặt và người chồng nắm toàn quyền quyết định"}], "correctOptionId": "b", "explanation": "Điều 2 Luật Hôn nhân và Gia đình 2014 xác định nguyên tắc hôn nhân tự nguyện, tiến bộ, một vợ một chồng, vợ chồng bình đẳng."}, {"id": "economics_law-12-marriage-family-rights-obligations-q2", "prompt": "Bổn phận và nghĩa vụ pháp lí quan trọng hàng đầu của con cái đối với cha mẹ theo luật định là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Yêu quý, kính trọng, biết ơn, hiếu thảo và chăm sóc, phụng dưỡng cha mẹ khi già yếu, ốm đau"}, {"id": "b", "text": "Có quyền từ chối phụng dưỡng cha mẹ nếu cha mẹ không chia phần tài sản thừa kế"}, {"id": "c", "text": "Tự ý định đoạt và sang tên toàn bộ nhà đất của cha mẹ mà không cần cha mẹ đồng ý"}], "correctOptionId": "a", "explanation": "Luật Hôn nhân và Gia đình quy định con cái có nghĩa vụ yêu quý, chăm sóc, nuôi dưỡng cha mẹ, đặc biệt khi cha mẹ mất sức lao động hoặc ốm đau."}, {"id": "economics_law-12-marriage-family-rights-obligations-q3", "prompt": "Ông Thắng bắt ép con gái 16 tuổi phải nghỉ học để kết hôn với người giàu theo ý muốn của ông, đồng thời tuyên bố chỉ để lại tài sản cho con trai. Hành vi của ông Thắng vi phạm quy định pháp luật nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Hoàn toàn phù hợp với quyền tự quyết gia trưởng của người đứng đầu gia đình"}, {"id": "b", "text": "Chỉ vi phạm phong tục tập quán làng xã mà không trái với bất kì luật nào"}, {"id": "c", "text": "Vi phạm quy định cấm cưỡng ép kết hôn, tảo hôn, cấm phân biệt đối xử giữa các con và xâm phạm quyền học tập của con"}], "correctOptionId": "c", "explanation": "Pháp luật nghiêm cấm hành vi cưỡng ép kết hôn, tảo hôn (kết hôn khi chưa đủ tuổi luật định: nữ từ đủ 18 tuổi) và cấm phân biệt đối xử giữa con trai và con gái."}]'::jsonb,'["economics_law-12-marriage-family-rights-obligations"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-learning-education-rights-obligations',11,'LESSON','Quyền và nghĩa vụ của công dân trong học tập','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Theo Hiến pháp năm 2013 và Luật Giáo dục năm 2019, học tập là quyền và nghĩa vụ cơ bản của mỗi công dân. Quyền học tập: mọi công dân không phân biệt dân tộc, tôn giáo, giới tính, hoàn cảnh kinh tế đều có quyền bình đẳng về cơ hội học tập; được học không hạn chế từ giáo dục mầm non, phổ thông đến đại học và sau đại học; được tự do lựa chọn ngành nghề, hình thức học tập phù hợp năng lực bản thân. Nghĩa vụ học tập: hoàn thành phổ cập giáo dục tiểu học và trung học cơ sở; tôn trọng nhà giáo, cán bộ quản lí giáo dục và chấp hành nội quy, điều lệ nhà trường."]'::jsonb,'["Bạn Lan đạt giải học sinh giỏi quốc gia được xét tuyển thẳng vào trường đại học sư phạm và được Nhà nước hỗ trợ sinh hoạt phí theo chính sách đào tạo giáo viên."]'::jsonb,'[{"id": "economics_law-12-learning-education-rights-obligations-q1", "prompt": "Quy định công dân có thể học từ bậc tiểu học lên đến tiến sĩ theo các hình thức đào tạo khác nhau thể hiện nội dung quyền nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quyền học tập không hạn chế của công dân"}, {"id": "b", "text": "Quyền độc quyền nghiên cứu khoa học của nhà nước"}, {"id": "c", "text": "Nghĩa vụ bắt buộc mọi công dân phải đạt học vị tiến sĩ"}], "correctOptionId": "a", "explanation": "Quyền học tập không hạn chế cho phép công dân học từ thấp đến cao phù hợp với năng lực, điều kiện và nguyện vọng cá nhân suốt đời."}, {"id": "economics_law-12-learning-education-rights-obligations-q2", "prompt": "Chính sách của Nhà nước miễn học phí cho học sinh tiểu học và cấp học bổng cho học sinh vùng đồng bào dân tộc thiểu số thể hiện nguyên tắc gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tạo sự phân biệt đối xử bất lợi đối với học sinh sinh sống tại các đô thị lớn"}, {"id": "b", "text": "Cắt giảm chỉ tiêu đào tạo đại học và cao đẳng trên phạm vi toàn quốc"}, {"id": "c", "text": "Bảo đảm sự bình đẳng và công bằng xã hội về cơ hội tiếp cận giáo dục cho mọi công dân"}], "correctOptionId": "c", "explanation": "Nhà nước ưu tiên hỗ trợ các đối tượng yếu thế nhằm xóa bỏ rào cản kinh tế, hiện thực hóa quyền bình đẳng trong tiếp cận giáo dục cho mọi trẻ em."}, {"id": "economics_law-12-learning-education-rights-obligations-q3", "prompt": "Một trường học ngoài công lập từ chối tiếp nhận hồ sơ đăng kí xét tuyển của em Nam với lí do Nam là người dân tộc thiểu số và gia đình nghèo. Quyết định từ chối này vi phạm điều gì?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chỉ vi phạm thỏa thuận dân sự mà không vi phạm các quyền cơ bản của công dân"}, {"id": "b", "text": "Vi phạm quyền bình đẳng về cơ hội học tập của công dân theo quy định của Hiến pháp và Luật Giáo dục"}, {"id": "c", "text": "Phù hợp với quyền tự do tuyệt đối trong việc lựa chọn học sinh của các trường tư thục"}], "correctOptionId": "b", "explanation": "Điều 9 Luật Giáo dục 2019 khẳng định mọi công dân không phân biệt dân tộc, tín ngưỡng, thành phần gia đình đều bình đẳng về cơ hội học tập."}]'::jsonb,'["economics_law-12-learning-education-rights-obligations"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-review-2',12,'FIVE_LESSON_REVIEW','Ôn tập 2','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "economics_law-12-personal-household-budget-q1", "prompt": "Theo quy tắc quản lí ngân sách tài chính cá nhân 50/30/20, tỉ lệ 20% thu nhập nên được ưu tiên cho mục tiêu nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Chi trả tiền thuê nhà và tiền ăn uống hàng ngày"}, {"id": "b", "text": "Tiết kiệm, lập quỹ dự phòng khẩn cấp hoặc đầu tư trả nợ"}, {"id": "c", "text": "Đi du lịch nghỉ dưỡng cao cấp hàng tháng"}], "correctOptionId": "b", "explanation": "20% khoản tiền này là đòn bẩy tích lũy tạo sự an tâm tài chính và sinh lời dài hạn trong tương lai."}, {"id": "economics_law-12-personal-household-budget-q2", "prompt": "Mục đích cốt lõi của việc xây dựng ''quỹ dự phòng khẩn cấp'' (tương đương 3 - 6 tháng chi phí) là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Chủ động ứng phó tài chính trước các biến cố bất ngờ như ốm đau, mất việc làm hoặc hư hỏng thiết bị thiết yếu mà không phải vay nợ lãi cao"}, {"id": "b", "text": "Dùng toàn bộ để tham gia các trò chơi may rủi trên mạng xã hội"}, {"id": "c", "text": "Mua sắm những món đồ xa xỉ giảm giá nhất thời"}], "correctOptionId": "a", "explanation": "Quỹ khẩn cấp bảo vệ cá nhân khỏi nguy cơ vỡ nợ khi xảy ra rủi ro gián đoạn nguồn thu nhập chính."}, {"id": "economics_law-12-business-tax-citizenship-q1", "prompt": "Theo quy định của Hiến pháp năm 2013 và pháp luật Việt Nam, công dân có quyền tự do kinh doanh trong phạm vi nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Trong những ngành, nghề và lĩnh vực mà luật không cấm"}, {"id": "b", "text": "Trong tất cả mọi lĩnh vực kể cả kinh doanh chất ma túy và vũ khí quân dụng"}, {"id": "c", "text": "Chỉ được phép kinh doanh các mặt hàng nông sản truyền thống tại địa phương"}], "correctOptionId": "a", "explanation": "Điều 33 Hiến pháp 2013 quy định mọi người có quyền tự do kinh doanh trong những ngành nghề mà pháp luật không cấm."}, {"id": "economics_law-12-business-tax-citizenship-q2", "prompt": "Nghĩa vụ hiến định mang tính bắt buộc hàng đầu của mọi tổ chức, cá nhân khi tiến hành hoạt động kinh doanh đối với Nhà nước là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tự ý ấn định mức thuế phải nộp dựa trên mức lợi nhuận mong muốn của cá nhân"}, {"id": "b", "text": "Chỉ nộp thuế khi có sự kiểm tra trực tiếp của cơ quan thuế tại cơ sở kinh doanh"}, {"id": "c", "text": "Kê khai trung thực, chính xác và nộp đầy đủ, đúng thời hạn các khoản thuế theo luật định"}], "correctOptionId": "c", "explanation": "Nộp thuế là nghĩa vụ hiến định của công dân nhằm tạo nguồn lực tài chính công để Nhà nước xây dựng hạ tầng, bảo đảm an sinh và bảo vệ Tổ quốc."}, {"id": "economics_law-12-property-ownership-rights-obligations-q1", "prompt": "Theo quy định của Bộ luật Dân sự năm 2015, quyền sở hữu của chủ sở hữu bao gồm ba quyền năng cơ bản nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quyền phong tỏa, quyền phát mại và quyền chiếm đoạt tài sản"}, {"id": "b", "text": "Quyền vay mượn, quyền thế chấp và quyền giấu giếm tài sản"}, {"id": "c", "text": "Quyền chiếm hữu, quyền sử dụng và quyền định đoạt tài sản"}], "correctOptionId": "c", "explanation": "Điều 158 Bộ luật Dân sự 2015 quy định quyền sở hữu bao gồm quyền chiếm hữu, quyền sử dụng và quyền định đoạt tài sản của chủ sở hữu."}, {"id": "economics_law-12-property-ownership-rights-obligations-q2", "prompt": "Nghĩa vụ tôn trọng tài sản của người khác đòi hỏi mỗi công dân phải thực hiện hành vi nào sau đây khi nhặt được tài sản đánh rơi?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Đem vứt bỏ tài sản đó xuống sông hồ để không ai tìm thấy"}, {"id": "b", "text": "Thông báo hoặc trả lại ngay cho người đánh rơi, hoặc giao nộp cho cơ quan công an gần nhất"}, {"id": "c", "text": "Tự ý cất giữ làm của riêng và mang bán lấy tiền chi tiêu cá nhân"}], "correctOptionId": "b", "explanation": "Pháp luật dân sự quy định người nhặt được của rơi có nghĩa vụ thông báo, trả lại cho chủ sở hữu hoặc giao nộp cơ quan có thẩm quyền."}, {"id": "economics_law-12-marriage-family-rights-obligations-q1", "prompt": "Nguyên tắc cốt lõi hàng đầu của chế độ hôn nhân và gia đình theo pháp luật Việt Nam hiện hành là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Cho phép kết hôn với nhiều người cùng một lúc để mở rộng quan hệ họ hàng"}, {"id": "b", "text": "Hôn nhân tự nguyện, tiến bộ, một vợ một chồng, vợ chồng bình đẳng"}, {"id": "c", "text": "Hôn nhân hoàn toàn do cha mẹ sắp đặt và người chồng nắm toàn quyền quyết định"}], "correctOptionId": "b", "explanation": "Điều 2 Luật Hôn nhân và Gia đình 2014 xác định nguyên tắc hôn nhân tự nguyện, tiến bộ, một vợ một chồng, vợ chồng bình đẳng."}, {"id": "economics_law-12-marriage-family-rights-obligations-q2", "prompt": "Bổn phận và nghĩa vụ pháp lí quan trọng hàng đầu của con cái đối với cha mẹ theo luật định là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Yêu quý, kính trọng, biết ơn, hiếu thảo và chăm sóc, phụng dưỡng cha mẹ khi già yếu, ốm đau"}, {"id": "b", "text": "Có quyền từ chối phụng dưỡng cha mẹ nếu cha mẹ không chia phần tài sản thừa kế"}, {"id": "c", "text": "Tự ý định đoạt và sang tên toàn bộ nhà đất của cha mẹ mà không cần cha mẹ đồng ý"}], "correctOptionId": "a", "explanation": "Luật Hôn nhân và Gia đình quy định con cái có nghĩa vụ yêu quý, chăm sóc, nuôi dưỡng cha mẹ, đặc biệt khi cha mẹ mất sức lao động hoặc ốm đau."}, {"id": "economics_law-12-learning-education-rights-obligations-q1", "prompt": "Quy định công dân có thể học từ bậc tiểu học lên đến tiến sĩ theo các hình thức đào tạo khác nhau thể hiện nội dung quyền nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Quyền học tập không hạn chế của công dân"}, {"id": "b", "text": "Quyền độc quyền nghiên cứu khoa học của nhà nước"}, {"id": "c", "text": "Nghĩa vụ bắt buộc mọi công dân phải đạt học vị tiến sĩ"}], "correctOptionId": "a", "explanation": "Quyền học tập không hạn chế cho phép công dân học từ thấp đến cao phù hợp với năng lực, điều kiện và nguyện vọng cá nhân suốt đời."}, {"id": "economics_law-12-learning-education-rights-obligations-q2", "prompt": "Chính sách của Nhà nước miễn học phí cho học sinh tiểu học và cấp học bổng cho học sinh vùng đồng bào dân tộc thiểu số thể hiện nguyên tắc gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tạo sự phân biệt đối xử bất lợi đối với học sinh sinh sống tại các đô thị lớn"}, {"id": "b", "text": "Cắt giảm chỉ tiêu đào tạo đại học và cao đẳng trên phạm vi toàn quốc"}, {"id": "c", "text": "Bảo đảm sự bình đẳng và công bằng xã hội về cơ hội tiếp cận giáo dục cho mọi công dân"}], "correctOptionId": "c", "explanation": "Nhà nước ưu tiên hỗ trợ các đối tượng yếu thế nhằm xóa bỏ rào cản kinh tế, hiện thực hóa quyền bình đẳng trong tiếp cận giáo dục cho mọi trẻ em."}]'::jsonb,'["economics_law-12-personal-household-budget", "economics_law-12-business-tax-citizenship", "economics_law-12-property-ownership-rights-obligations", "economics_law-12-marriage-family-rights-obligations", "economics_law-12-learning-education-rights-obligations"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-healthcare-social-security-rights',13,'LESSON','Quyền và nghĩa vụ của công dân trong bảo vệ sức khỏe và an sinh xã hội','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Theo Hiến pháp năm 2013, công dân có quyền được bảo vệ, chăm sóc sức khỏe, bình đẳng trong việc sử dụng các dịch vụ y tế và có quyền được bảo đảm an sinh xã hội. Quyền về sức khỏe: được khám bệnh, chữa bệnh, tiếp cận thuốc thiết yếu và thông tin y tế, tham gia Bảo hiểm y tế (BHYT) để chia sẻ rủi ro viện phí. Nghĩa vụ về sức khỏe: tuân thủ các quy định phòng chống dịch bệnh truyền nhiễm, tiêm chủng theo quy định, giữ vệ sinh công cộng và không làm lây lan mầm bệnh nguy hại cho xã hội. Quyền an sinh xã hội bảo đảm người dân được hỗ trợ tài chính khi giảm sút hoặc mất thu nhập (ốm đau, tai nạn, thất nghiệp, tuổi già) qua hệ thống BHXH và trợ giúp xã hội."]'::jsonb,'["Bác Hùng tham gia Bảo hiểm y tế hộ gia đình; khi phải phẫu thuật điều trị dài ngày tại bệnh viện đa khoa, quỹ BHYT đã thanh toán phần lớn viện phí, giúp gia đình vượt qua khó khăn tài chính."]'::jsonb,'[{"id": "economics_law-12-healthcare-social-security-rights-q1", "prompt": "Chính sách an sinh xã hội trụ cột do Nhà nước tổ chức nhằm chăm sóc sức khỏe cộng đồng và chia sẻ chi phí khám chữa bệnh là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Quỹ đầu tư bất động sản thương mại"}, {"id": "b", "text": "Hợp đồng bảo hiểm tài sản doanh nghiệp"}, {"id": "c", "text": "Bảo hiểm y tế (BHYT)"}], "correctOptionId": "c", "explanation": "Bảo hiểm y tế là chính sách an sinh xã hội quan trọng nhằm huy động sự đóng góp cộng đồng, bảo đảm quyền chăm sóc sức khỏe cho nhân dân."}, {"id": "economics_law-12-healthcare-social-security-rights-q2", "prompt": "Trong công tác phòng, chống bệnh truyền nhiễm nguy hiểm, nghĩa vụ bắt buộc của mỗi cá nhân đối với cộng đồng là gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Che giấu tình trạng nhiễm bệnh truyền nhiễm của bản thân và từ chối điều trị"}, {"id": "b", "text": "Khai báo y tế trung thực, thực hiện nghiêm các biện pháp cách ly và tiêm chủng phòng dịch theo hướng dẫn y tế"}, {"id": "c", "text": "Tự ý trốn khỏi khu vực phong tỏa cách ly y tế để tiếp xúc đông người nơi công cộng"}], "correctOptionId": "b", "explanation": "Luật Phòng, chống bệnh truyền nhiễm quy định cá nhân có nghĩa vụ chấp hành nghiêm các biện pháp phòng dịch để bảo đảm an toàn sức khỏe chung."}, {"id": "economics_law-12-healthcare-social-security-rights-q3", "prompt": "Doanh nghiệp Bình An kí hợp đồng lao động chính thức với 40 công nhân nhưng trốn tránh nghĩa vụ đóng Bảo hiểm xã hội và Bảo hiểm y tế bắt buộc suốt hai năm. Hành vi của doanh nghiệp này vi phạm quyền gì của công nhân?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Xâm phạm quyền được bảo đảm an sinh xã hội và quyền chăm sóc y tế hợp pháp của người lao động"}, {"id": "b", "text": "Không vi phạm vì việc đóng bảo hiểm hoàn toàn tùy thuộc vào quyết định của giám đốc doanh nghiệp"}, {"id": "c", "text": "Chỉ vi phạm quy chế thi đua khen thưởng nội bộ của doanh nghiệp"}], "correctOptionId": "a", "explanation": "Đóng BHXH và BHYT là nghĩa vụ pháp lí bắt buộc của người sử dụng lao động; hành vi trốn đóng bảo hiểm tước đoạt quyền an sinh của người lao động và sẽ bị xử lí nghiêm khắc."}]'::jsonb,'["economics_law-12-healthcare-social-security-rights"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-cultural-environmental-protection-rights',14,'LESSON','Quyền và nghĩa vụ về bảo vệ di sản văn hóa, môi trường và tài nguyên thiên nhiên','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Theo Luật Di sản văn hóa và Luật Bảo vệ môi trường năm 2020, công dân có quyền sống trong môi trường trong lành; quyền hưởng thụ, tiếp cận và phát huy các giá trị di sản văn hóa dân tộc; quyền tố cáo các hành vi vi phạm pháp luật về môi trường và tài nguyên. Nghĩa vụ của công dân: giữ gìn, bảo vệ di tích lịch sử - văn hóa, danh lam thắng cảnh; thực hiện phân loại rác thải sinh hoạt tại nguồn, tiết kiệm năng lượng; khai thác, sử dụng hợp lí, tiết kiệm nguồn nước, khoáng sản và tài nguyên rừng. Pháp luật nghiêm cấm hành vi chiếm đoạt cổ vật, phá hoại cảnh quan di tích, lén lút xả thải chất độc hại và săn bắt trái phép động vật hoang dã."]'::jsonb,'["Nhóm học sinh THPT tích cực tham gia phong trào ngày Chủ nhật xanh, dọn dẹp rác thải quanh di tích đình làng cổ và gửi phản ánh tới chính quyền khi phát hiện bãi tập kết rác thải tự phát gây ô nhiễm."]'::jsonb,'[{"id": "economics_law-12-cultural-environmental-protection-rights-q1", "prompt": "Quyền cơ bản của mọi người dân đối với môi trường sống được ghi nhận rõ nét tại Điều 43 Hiến pháp năm 2013 là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Mọi người được phép xả chất thải công nghiệp trực tiếp ra nguồn nước sinh hoạt chung"}, {"id": "b", "text": "Mọi người có quyền được sống trong môi trường trong lành và có nghĩa vụ bảo vệ môi trường"}, {"id": "c", "text": "Mọi người có quyền tự do khai thác cạn kiệt tài nguyên rừng phòng hộ mà không cần xin phép"}], "correctOptionId": "b", "explanation": "Hiến pháp 2013 khẳng định quyền được sống trong môi trường trong lành đi đôi với nghĩa vụ bảo vệ môi trường của mọi cá nhân."}, {"id": "economics_law-12-cultural-environmental-protection-rights-q2", "prompt": "Hành vi nào sau đây xâm phạm nghiêm trọng các quy định pháp luật về bảo vệ di sản văn hóa dân tộc?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tự ý đập phá, lấn chiếm khuôn viên, đào bới trái phép hoặc làm biến dạng kiến trúc gốc của di tích lịch sử"}, {"id": "b", "text": "Tích cực tham gia vệ sinh môi trường và trồng hoa tạo cảnh quan đẹp cho khu di tích"}, {"id": "c", "text": "Sưu tầm và giới thiệu các tư liệu lịch sử chính thống về di tích cho du khách tham quan"}], "correctOptionId": "a", "explanation": "Luật Di sản văn hóa nghiêm cấm các hành vi chiếm đoạt, hủy hoại hoặc làm sai lệch hiện vật, cảnh quan di tích lịch sử - văn hóa."}, {"id": "economics_law-12-cultural-environmental-protection-rights-q3", "prompt": "Một xưởng sản xuất cơ khí lén lút xả nước thải chứa kim loại nặng chưa qua xử lí xuống dòng kênh dân sinh, làm ô nhiễm nguồn nước tưới tiêu. Cơ sở này phải gánh chịu những chế tài pháp lí nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Chỉ bị lập biên bản nhắc nhở nội bộ mà không phải bồi thường thiệt hại"}, {"id": "b", "text": "Được cơ quan chức năng hỗ trợ kinh phí để tiếp tục xả thải công khai"}, {"id": "c", "text": "Bị xử phạt vi phạm hành chính với số tiền lớn, đình chỉ hoạt động, buộc khắc phục ô nhiễm và bồi thường thiệt hại thực tế"}], "correctOptionId": "c", "explanation": "Hành vi xả chất thải chưa qua xử lí gây ô nhiễm môi trường bị xử phạt hành chính nặng, đình chỉ hoạt động, buộc bồi thường dân sự và có thể bị xử lí hình sự."}]'::jsonb,'["economics_law-12-cultural-environmental-protection-rights"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-general-international-law-foundations',15,'LESSON','Một số vấn đề cơ bản của pháp luật quốc tế','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Pháp luật quốc tế (Luật quốc tế) là hệ thống các nguyên tắc và quy phạm pháp luật do các quốc gia và các chủ thể quốc tế khác cùng thỏa thuận xây dựng nhằm điều chỉnh các quan hệ quốc tế trên nhiều phương diện (chính trị, an ninh, kinh tế, môi trường). Các chủ thể chủ yếu: quốc gia có chủ quyền (chủ thể nền tảng), tổ chức quốc tế liên chính phủ, và dân tộc đang đấu tranh giành độc lập. Nguồn của luật quốc tế: điều ước quốc tế (các công ước, hiệp định đa phương hoặc song phương) và tập quán quốc tế. Các nguyên tắc cơ bản: bình đẳng chủ quyền; cấm đe dọa hoặc sử dụng vũ lực; giải quyết hòa bình các tranh chấp; không can thiệp vào công việc nội bộ; tận tâm thực hiện cam kết quốc tế (Pacta sunt servanda)."]'::jsonb,'["Việt Nam và các quốc gia láng giềng tiến hành đàm phán cắm mốc biên giới trên đất liền dựa trên nguyên tắc bình đẳng chủ quyền và tôn trọng các hiệp ước biên giới song phương phù hợp với luật pháp quốc tế."]'::jsonb,'[{"id": "economics_law-12-general-international-law-foundations-q1", "prompt": "Chủ thể cơ bản, ban đầu và giữ vai trò trung tâm nhất trong hệ thống pháp luật quốc tế hiện đại là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Các quốc gia độc lập có chủ quyền"}, {"id": "b", "text": "Các cá nhân công dân mang quốc tịch bất kì"}, {"id": "c", "text": "Các câu lạc bộ thể thao và tập đoàn tư nhân đa quốc gia"}], "correctOptionId": "a", "explanation": "Quốc gia có chủ quyền là chủ thể chủ yếu và cơ bản nhất của luật quốc tế, có đầy đủ thẩm quyền kí kết và thực thi các cam kết quốc tế."}, {"id": "economics_law-12-general-international-law-foundations-q2", "prompt": "Nguyên tắc ''Pacta sunt servanda'' - một trong những nguyên tắc nền tảng linh hồn của luật pháp quốc tế đòi hỏi các quốc gia phải:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Được quyền đơn phương hủy bỏ các điều ước quốc tế bất cứ lúc nào cảm thấy bất lợi cho riêng mình"}, {"id": "b", "text": "Chỉ cần thực hiện các cam kết nếu nhận được sự đồng ý của tất cả các tập đoàn tư nhân"}, {"id": "c", "text": "Tận tâm, thiện chí thực hiện đầy đủ các cam kết và nghĩa vụ trong các điều ước quốc tế mà mình đã kí kết hoặc gia nhập"}], "correctOptionId": "c", "explanation": "Pacta sunt servanda là nguyên tắc thượng tôn các cam kết quốc tế, bảo đảm tính ổn định, tin cậy và pháp quyền trong trật tự quan hệ quốc tế."}, {"id": "economics_law-12-general-international-law-foundations-q3", "prompt": "Khi phát sinh tranh chấp về chủ quyền lãnh thổ hoặc ranh giới biển giữa các quốc gia, biện pháp giải quyết nào sau đây phù hợp với các nguyên tắc cơ bản của luật quốc tế?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Đơn phương phong tỏa đường hàng hải quốc tế mà không có nghị quyết của Hội đồng Bảo an Liên hợp quốc"}, {"id": "b", "text": "Đàm phán ngoại giao hòa bình, trung gian hòa giải hoặc sử dụng các cơ quan tài phán quốc tế theo thỏa thuận"}, {"id": "c", "text": "Sử dụng ngay lực lượng quân sự tấn công bất ngờ nhằm thôn tính vùng đất tranh chấp"}], "correctOptionId": "b", "explanation": "Nguyên tắc giải quyết hòa bình các tranh chấp quốc tế buộc các bên phải lựa chọn biện pháp thương lượng, hòa giải hoặc tòa án quốc tế, nghiêm cấm sử dụng vũ lực."}]'::jsonb,'["economics_law-12-general-international-law-foundations"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-public-international-law-territory-sovereignty',16,'LESSON','Dân cư, lãnh thổ và chủ quyền quốc gia trong công pháp quốc tế','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Trong công pháp quốc tế, lãnh thổ quốc gia là không gian địa lí xác định thuộc chủ quyền hoàn toàn và riêng biệt của một quốc gia, bao gồm bốn bộ phận: vùng đất (đất liền và hải đảo), vùng nước (nội thủy và lãnh hải), vùng trời và vùng lòng đất bên dưới chúng. Chủ quyền quốc gia là quyền tối cao của nhà nước trong phạm vi lãnh thổ của mình và quyền độc lập trong quan hệ quốc tế, có tính chất bất khả xâm phạm. Dân cư của một quốc gia gồm công dân mang quốc tịch nước sở tại, người nước ngoài và người không quốc tịch; quốc gia thực thi quyền tài phán đối với dân cư trên lãnh thổ. Nguyên tắc toàn vẹn lãnh thổ và bất khả xâm phạm đường biên giới là nền tảng bảo vệ chủ quyền quốc gia."]'::jsonb,'["Lực lượng Cảnh sát biển Việt Nam tuần tra, kiểm soát và thực thi pháp luật nghiêm minh trên vùng lãnh hải 12 hải lí để bảo vệ chủ quyền biển đảo thiêng liêng của Tổ quốc phù hợp với UNCLOS 1982."]'::jsonb,'[{"id": "economics_law-12-public-international-law-territory-sovereignty-q1", "prompt": "Theo công pháp quốc tế, lãnh thổ quốc gia hoàn chỉnh được cấu thành từ bốn bộ phận không gian địa lí nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Vùng đất liền canh tác nông nghiệp và không tính vùng trời"}, {"id": "b", "text": "Chỉ bao gồm các hải đảo nằm ngoài vùng đặc quyền kinh tế"}, {"id": "c", "text": "Vùng đất, vùng nước, vùng trời và vùng lòng đất"}], "correctOptionId": "c", "explanation": "Lãnh thổ quốc gia là một thể thống nhất gồm 4 bộ phận: vùng đất, vùng nước (nội thủy, lãnh hải), vùng lòng đất và vùng trời phía trên."}, {"id": "economics_law-12-public-international-law-territory-sovereignty-q2", "prompt": "Tính chất ''bất khả xâm phạm'' của chủ quyền và lãnh thổ quốc gia trong luật pháp quốc tế mang ý nghĩa cốt lõi là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Quốc gia ven biển không có quyền quản lí tàu thuyền hoạt động trong vùng biển thuộc chủ quyền của mình"}, {"id": "b", "text": "Mọi hành vi xâm lấn biên giới, đe dọa độc lập và toàn vẹn lãnh thổ của một quốc gia đều là hành vi vi phạm pháp luật quốc tế nghiêm trọng"}, {"id": "c", "text": "Các cường quốc lớn có quyền tự do can thiệp quân sự vào vùng trời của các quốc gia nhỏ hơn"}], "correctOptionId": "b", "explanation": "Luật pháp quốc tế nghiêm cấm mọi hành vi xâm lấn, chiếm đoạt lãnh thổ hoặc can thiệp lật đổ chủ quyền thiêng liêng của một quốc gia độc lập."}, {"id": "economics_law-12-public-international-law-territory-sovereignty-q3", "prompt": "Một tàu cá nước ngoài tự ý tiến sâu vào vùng nội thủy của Việt Nam để đánh bắt thủy sản trái phép mà không được cấp phép. Cơ quan chức năng Việt Nam có quyền xử lí như thế nào?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Bắt giữ tàu vi phạm, dẫn giải về đất liền và xử phạt nghiêm minh theo quy định của pháp luật Việt Nam vì nội thủy thuộc chủ quyền tuyệt đối của nước ta"}, {"id": "b", "text": "Không có quyền ngăn chặn vì vùng nội thủy mở cửa tự do cho tàu cá mọi quốc gia"}, {"id": "c", "text": "Bắt buộc phải chờ sự cho phép của thuyền trưởng tàu nước ngoài mới được lên tàu kiểm tra"}], "correctOptionId": "a", "explanation": "Vùng nội thủy thuộc chủ quyền hoàn toàn và tuyệt đối của quốc gia ven biển; mọi hành vi xâm phạm nội thủy trái phép đều bị xử lí theo thẩm quyền tài phán quốc gia."}]'::jsonb,'["economics_law-12-public-international-law-territory-sovereignty"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-wto-principles-international-commercial-contracts',17,'LESSON','Nguyên tắc cơ bản của WTO và hợp đồng thương mại quốc tế','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','["Tổ chức Thương mại Thế giới (WTO) thiết lập các nguyên tắc nền tảng điều chỉnh thương mại toàn cầu: Nguyên tắc Tối huệ quốc (MFN - Most-Favoured-Nation: bất kì sự ưu đãi thuế quan nào dành cho một nước thành viên phải được áp dụng ngay lập tức, vô điều kiện cho mọi thành viên khác); Nguyên tắc Đãi ngộ quốc gia (NT - National Treatment: hàng hóa, dịch vụ nhập khẩu sau khi hoàn tất thủ tục hải quan phải được đối xử bình đẳng như hàng hóa, dịch vụ nội địa cùng loại); tự do hóa thương mại và cạnh tranh công bằng, minh bạch. Hợp đồng thương mại quốc tế là sự thỏa thuận giữa các bên có trụ sở thương mại tại các quốc gia khác nhau nhằm mua bán hàng hóa hoặc cung ứng dịch vụ xuyên biên giới; bao gồm các điều khoản cơ bản: tên hàng, số lượng, chất lượng, giá cả, điều kiện giao hàng (Incoterms như FOB, CIF), phương thức thanh toán (L/C, T/T), luật áp dụng và cơ chế giải quyết tranh chấp (trọng tài thương mại quốc tế)."]'::jsonb,'["Một doanh nghiệp cà phê Việt Nam kí kết hợp đồng thương mại quốc tế xuất khẩu 100 tấn cà phê Robusta sang Đức theo điều kiện CIF Hamburg, thanh toán qua Thư tín dụng chứng từ (L/C) và chọn trọng tài VIAC để giải quyết tranh chấp nếu có phát sinh."]'::jsonb,'[{"id": "economics_law-12-wto-principles-international-commercial-contracts-q1", "prompt": "Nguyên tắc ''Đãi ngộ tối huệ quốc'' (MFN) trong hệ thống thương mại đa phương của WTO quy định điều gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cho phép các nước giàu áp thuế nhập khẩu cao gấp mười lần đối với hàng hóa xuất xứ từ các nước nghèo"}, {"id": "b", "text": "Nếu một thành viên dành ưu đãi thương mại cho một quốc gia thì phải dành ưu đãi tương tự cho tất cả các thành viên khác của WTO"}, {"id": "c", "text": "Chỉ dành ưu đãi thuế quan đặc biệt cho các quốc gia láng giềng có chung đường biên giới đất liền"}], "correctOptionId": "b", "explanation": "Nguyên tắc MFN bảo đảm không phân biệt đối xử giữa các đối tác thương mại: lợi thế dành cho một nước phải được trao bình đẳng cho toàn bộ thành viên WTO."}, {"id": "economics_law-12-wto-principles-international-commercial-contracts-q2", "prompt": "Nguyên tắc ''Đãi ngộ quốc gia'' (NT) của WTO nghiêm cấm hành vi nào sau đây của nước nhập khẩu đối với hàng hóa nước ngoài?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Áp đặt mức thuế tiêu thụ nội địa hoặc quy chuẩn kĩ thuật khắt khe hơn đối với hàng hóa nhập khẩu so với hàng hóa cùng loại sản xuất trong nước"}, {"id": "b", "text": "Thực hiện kiểm tra an toàn thực phẩm bình đẳng đối với mọi lô hàng lưu thông trên thị trường nội địa"}, {"id": "c", "text": "Cắt giảm biểu thuế quan nhập khẩu theo đúng lộ trình cam kết gia nhập WTO"}], "correctOptionId": "a", "explanation": "Nguyên tắc NT yêu cầu hàng nhập khẩu sau khi qua cửa khẩu phải được đối xử công bằng ngang bằng với hàng nội địa, không bị phân biệt đối xử về thuế và quy chuẩn kĩ thuật."}, {"id": "economics_law-12-wto-principles-international-commercial-contracts-q3", "prompt": "Doanh nghiệp Việt Nam kí hợp đồng bán 200 tấn gạo cho đối tác tại Pháp, thỏa thuận giao hàng theo điều kiện CIF cảng Marseille và thanh toán bằng phương thức L/C không hủy ngang. Yếu tố nào sau đây khẳng định đây là hợp đồng thương mại quốc tế?", "difficulty": "APPLIED", "options": [{"id": "a", "text": "Hợp đồng được soạn thảo hoàn toàn bằng tiếng Việt và giao hàng tại một kho nội địa"}, {"id": "b", "text": "Người bán và người mua đều mang quốc tịch Việt Nam và sinh sống cùng một địa phương"}, {"id": "c", "text": "Các bên tham gia hợp đồng có trụ sở kinh doanh tại các quốc gia khác nhau và hàng hóa được vận chuyển dịch chuyển qua biên giới quốc gia"}], "correctOptionId": "c", "explanation": "Dấu hiệu pháp lí đặc trưng của hợp đồng thương mại quốc tế là sự dịch chuyển hàng hóa qua biên giới và các bên chủ thể có trụ sở thương mại ở các quốc gia khác nhau."}]'::jsonb,'["economics_law-12-wto-principles-international-commercial-contracts"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,guidance=excluded.guidance,examples=excluded.examples,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources) values ('economics_law',12,'intro-2026.1','economics_law-12-review-3',18,'FIVE_LESSON_REVIEW','Ôn tập 3','Giáo dục kinh tế và pháp luật 12: Hội nhập kinh tế, chính sách an sinh và pháp luật quốc tế','Tài liệu học tập lớp 12 do AI Mentor biên soạn theo yêu cầu cần đạt của Chương trình GDPT 2018 (định hướng bộ sách Kết nối tri thức với cuộc sống); đây là tuyển chọn chuyên đề nền tảng, không phải bản sao nguyên văn SGK và chưa bao phủ toàn bộ năm học. Bài đầu vào sử dụng 2 câu hỏi từ mỗi bài học để hỗ trợ chẩn đoán năng lực. Nội dung cần được giáo viên chuyên môn thẩm định trước khi áp dụng chính thức.','[]'::jsonb,'[]'::jsonb,'[{"id": "economics_law-12-healthcare-social-security-rights-q1", "prompt": "Chính sách an sinh xã hội trụ cột do Nhà nước tổ chức nhằm chăm sóc sức khỏe cộng đồng và chia sẻ chi phí khám chữa bệnh là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Quỹ đầu tư bất động sản thương mại"}, {"id": "b", "text": "Hợp đồng bảo hiểm tài sản doanh nghiệp"}, {"id": "c", "text": "Bảo hiểm y tế (BHYT)"}], "correctOptionId": "c", "explanation": "Bảo hiểm y tế là chính sách an sinh xã hội quan trọng nhằm huy động sự đóng góp cộng đồng, bảo đảm quyền chăm sóc sức khỏe cho nhân dân."}, {"id": "economics_law-12-healthcare-social-security-rights-q2", "prompt": "Trong công tác phòng, chống bệnh truyền nhiễm nguy hiểm, nghĩa vụ bắt buộc của mỗi cá nhân đối với cộng đồng là gì?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Che giấu tình trạng nhiễm bệnh truyền nhiễm của bản thân và từ chối điều trị"}, {"id": "b", "text": "Khai báo y tế trung thực, thực hiện nghiêm các biện pháp cách ly và tiêm chủng phòng dịch theo hướng dẫn y tế"}, {"id": "c", "text": "Tự ý trốn khỏi khu vực phong tỏa cách ly y tế để tiếp xúc đông người nơi công cộng"}], "correctOptionId": "b", "explanation": "Luật Phòng, chống bệnh truyền nhiễm quy định cá nhân có nghĩa vụ chấp hành nghiêm các biện pháp phòng dịch để bảo đảm an toàn sức khỏe chung."}, {"id": "economics_law-12-cultural-environmental-protection-rights-q1", "prompt": "Quyền cơ bản của mọi người dân đối với môi trường sống được ghi nhận rõ nét tại Điều 43 Hiến pháp năm 2013 là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Mọi người được phép xả chất thải công nghiệp trực tiếp ra nguồn nước sinh hoạt chung"}, {"id": "b", "text": "Mọi người có quyền được sống trong môi trường trong lành và có nghĩa vụ bảo vệ môi trường"}, {"id": "c", "text": "Mọi người có quyền tự do khai thác cạn kiệt tài nguyên rừng phòng hộ mà không cần xin phép"}], "correctOptionId": "b", "explanation": "Hiến pháp 2013 khẳng định quyền được sống trong môi trường trong lành đi đôi với nghĩa vụ bảo vệ môi trường của mọi cá nhân."}, {"id": "economics_law-12-cultural-environmental-protection-rights-q2", "prompt": "Hành vi nào sau đây xâm phạm nghiêm trọng các quy định pháp luật về bảo vệ di sản văn hóa dân tộc?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Tự ý đập phá, lấn chiếm khuôn viên, đào bới trái phép hoặc làm biến dạng kiến trúc gốc của di tích lịch sử"}, {"id": "b", "text": "Tích cực tham gia vệ sinh môi trường và trồng hoa tạo cảnh quan đẹp cho khu di tích"}, {"id": "c", "text": "Sưu tầm và giới thiệu các tư liệu lịch sử chính thống về di tích cho du khách tham quan"}], "correctOptionId": "a", "explanation": "Luật Di sản văn hóa nghiêm cấm các hành vi chiếm đoạt, hủy hoại hoặc làm sai lệch hiện vật, cảnh quan di tích lịch sử - văn hóa."}, {"id": "economics_law-12-general-international-law-foundations-q1", "prompt": "Chủ thể cơ bản, ban đầu và giữ vai trò trung tâm nhất trong hệ thống pháp luật quốc tế hiện đại là:", "difficulty": "EASY", "options": [{"id": "a", "text": "Các quốc gia độc lập có chủ quyền"}, {"id": "b", "text": "Các cá nhân công dân mang quốc tịch bất kì"}, {"id": "c", "text": "Các câu lạc bộ thể thao và tập đoàn tư nhân đa quốc gia"}], "correctOptionId": "a", "explanation": "Quốc gia có chủ quyền là chủ thể chủ yếu và cơ bản nhất của luật quốc tế, có đầy đủ thẩm quyền kí kết và thực thi các cam kết quốc tế."}, {"id": "economics_law-12-general-international-law-foundations-q2", "prompt": "Nguyên tắc ''Pacta sunt servanda'' - một trong những nguyên tắc nền tảng linh hồn của luật pháp quốc tế đòi hỏi các quốc gia phải:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Được quyền đơn phương hủy bỏ các điều ước quốc tế bất cứ lúc nào cảm thấy bất lợi cho riêng mình"}, {"id": "b", "text": "Chỉ cần thực hiện các cam kết nếu nhận được sự đồng ý của tất cả các tập đoàn tư nhân"}, {"id": "c", "text": "Tận tâm, thiện chí thực hiện đầy đủ các cam kết và nghĩa vụ trong các điều ước quốc tế mà mình đã kí kết hoặc gia nhập"}], "correctOptionId": "c", "explanation": "Pacta sunt servanda là nguyên tắc thượng tôn các cam kết quốc tế, bảo đảm tính ổn định, tin cậy và pháp quyền trong trật tự quan hệ quốc tế."}, {"id": "economics_law-12-public-international-law-territory-sovereignty-q1", "prompt": "Theo công pháp quốc tế, lãnh thổ quốc gia hoàn chỉnh được cấu thành từ bốn bộ phận không gian địa lí nào?", "difficulty": "EASY", "options": [{"id": "a", "text": "Vùng đất liền canh tác nông nghiệp và không tính vùng trời"}, {"id": "b", "text": "Chỉ bao gồm các hải đảo nằm ngoài vùng đặc quyền kinh tế"}, {"id": "c", "text": "Vùng đất, vùng nước, vùng trời và vùng lòng đất"}], "correctOptionId": "c", "explanation": "Lãnh thổ quốc gia là một thể thống nhất gồm 4 bộ phận: vùng đất, vùng nước (nội thủy, lãnh hải), vùng lòng đất và vùng trời phía trên."}, {"id": "economics_law-12-public-international-law-territory-sovereignty-q2", "prompt": "Tính chất ''bất khả xâm phạm'' của chủ quyền và lãnh thổ quốc gia trong luật pháp quốc tế mang ý nghĩa cốt lõi là:", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Quốc gia ven biển không có quyền quản lí tàu thuyền hoạt động trong vùng biển thuộc chủ quyền của mình"}, {"id": "b", "text": "Mọi hành vi xâm lấn biên giới, đe dọa độc lập và toàn vẹn lãnh thổ của một quốc gia đều là hành vi vi phạm pháp luật quốc tế nghiêm trọng"}, {"id": "c", "text": "Các cường quốc lớn có quyền tự do can thiệp quân sự vào vùng trời của các quốc gia nhỏ hơn"}], "correctOptionId": "b", "explanation": "Luật pháp quốc tế nghiêm cấm mọi hành vi xâm lấn, chiếm đoạt lãnh thổ hoặc can thiệp lật đổ chủ quyền thiêng liêng của một quốc gia độc lập."}, {"id": "economics_law-12-wto-principles-international-commercial-contracts-q1", "prompt": "Nguyên tắc ''Đãi ngộ tối huệ quốc'' (MFN) trong hệ thống thương mại đa phương của WTO quy định điều gì?", "difficulty": "EASY", "options": [{"id": "a", "text": "Cho phép các nước giàu áp thuế nhập khẩu cao gấp mười lần đối với hàng hóa xuất xứ từ các nước nghèo"}, {"id": "b", "text": "Nếu một thành viên dành ưu đãi thương mại cho một quốc gia thì phải dành ưu đãi tương tự cho tất cả các thành viên khác của WTO"}, {"id": "c", "text": "Chỉ dành ưu đãi thuế quan đặc biệt cho các quốc gia láng giềng có chung đường biên giới đất liền"}], "correctOptionId": "b", "explanation": "Nguyên tắc MFN bảo đảm không phân biệt đối xử giữa các đối tác thương mại: lợi thế dành cho một nước phải được trao bình đẳng cho toàn bộ thành viên WTO."}, {"id": "economics_law-12-wto-principles-international-commercial-contracts-q2", "prompt": "Nguyên tắc ''Đãi ngộ quốc gia'' (NT) của WTO nghiêm cấm hành vi nào sau đây của nước nhập khẩu đối với hàng hóa nước ngoài?", "difficulty": "MEDIUM", "options": [{"id": "a", "text": "Áp đặt mức thuế tiêu thụ nội địa hoặc quy chuẩn kĩ thuật khắt khe hơn đối với hàng hóa nhập khẩu so với hàng hóa cùng loại sản xuất trong nước"}, {"id": "b", "text": "Thực hiện kiểm tra an toàn thực phẩm bình đẳng đối với mọi lô hàng lưu thông trên thị trường nội địa"}, {"id": "c", "text": "Cắt giảm biểu thuế quan nhập khẩu theo đúng lộ trình cam kết gia nhập WTO"}], "correctOptionId": "a", "explanation": "Nguyên tắc NT yêu cầu hàng nhập khẩu sau khi qua cửa khẩu phải được đối xử công bằng ngang bằng với hàng nội địa, không bị phân biệt đối xử về thuế và quy chuẩn kĩ thuật."}]'::jsonb,'["economics_law-12-healthcare-social-security-rights", "economics_law-12-cultural-environmental-protection-rights", "economics_law-12-general-international-law-foundations", "economics_law-12-public-international-law-territory-sovereignty", "economics_law-12-wto-principles-international-commercial-contracts"]'::jsonb) on conflict(subject_id,grade,unit_id) do update set course_version=excluded.course_version,position=excluded.position,title=excluded.title,course_title=excluded.course_title,source_note=excluded.source_note,questions=excluded.questions,sources=excluded.sources;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-math-12-1','Ôn tập bài 1–5','math',12,'Bài 1–5','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "math-12-monotonicity-q1", "prompt": "Cho hàm số y = f(x) có đạo hàm f''(x) > 0 với mọi x thuộc khoảng (1; 3). Kết luận nào sau đây đúng?", "options": [{"id": "A", "text": "Hàm số đồng biến trên khoảng (1; 3)"}, {"id": "B", "text": "Hàm số nghịch biến trên khoảng (1; 3)"}, {"id": "C", "text": "Hàm số không đổi trên khoảng (1; 3)"}], "correctOption": "A", "explanation": "Đạo hàm luôn mang dấu dương trên một khoảng là điều kiện đủ để hàm số đồng biến trên khoảng đó.", "difficulty": "EASY", "points": 10}, {"id": "math-12-monotonicity-q2", "prompt": "Tìm các khoảng nghịch biến của hàm số y = -x³ + 3x.", "options": [{"id": "A", "text": "(-1; 1)"}, {"id": "B", "text": "(-∞; 0)"}, {"id": "C", "text": "(-∞; -1) và (1; +∞)"}], "correctOption": "C", "explanation": "Đạo hàm y'' = -3x² + 3 = -3(x² - 1). Ta có y'' < 0 khi x² - 1 > 0, tức x < -1 hoặc x > 1.", "difficulty": "MEDIUM", "points": 10}, {"id": "math-12-extrema-q1", "prompt": "Giả sử hàm số y = f(x) có đạo hàm tại điểm x₀. Điều kiện cần để x₀ là một điểm cực trị của hàm số là:", "options": [{"id": "A", "text": "f''(x₀) > 0"}, {"id": "B", "text": "f''(x₀) < 0"}, {"id": "C", "text": "f''(x₀) = 0"}], "correctOption": "C", "explanation": "Theo định lí Fermat, nếu hàm số đạt cực trị tại x₀ và có đạo hàm tại đó thì f''(x₀) = 0.", "difficulty": "EASY", "points": 10}, {"id": "math-12-extrema-q2", "prompt": "Tìm điểm cực tiểu của hàm số y = x³ - 3x + 2.", "options": [{"id": "A", "text": "x = 0"}, {"id": "B", "text": "x = 1"}, {"id": "C", "text": "x = -1"}], "correctOption": "B", "explanation": "y'' = 3x² - 3 = 0 ⇔ x = ±1. Đạo hàm đổi dấu từ âm sang dương khi đi qua x = 1 nên x = 1 là điểm cực tiểu.", "difficulty": "MEDIUM", "points": 10}, {"id": "math-12-min-max-q1", "prompt": "Cho hàm số y = f(x) liên tục trên đoạn [a; b]. Khẳng định nào sau đây luôn đúng?", "options": [{"id": "A", "text": "Giá trị lớn nhất luôn đạt tại một trong hai đầu mút a hoặc b"}, {"id": "B", "text": "Hàm số luôn đạt giá trị lớn nhất và giá trị nhỏ nhất trên [a; b]"}, {"id": "C", "text": "Hàm số chỉ đạt cực đại mà không thể đạt giá trị lớn nhất"}], "correctOption": "B", "explanation": "Theo định lí Weierstrass, hàm số liên tục trên một đoạn đóng bị chặn luôn đạt giá trị lớn nhất và nhỏ nhất trên đoạn đó.", "difficulty": "EASY", "points": 10}, {"id": "math-12-min-max-q2", "prompt": "Giá trị lớn nhất của hàm số y = -x² + 4x + 1 trên đoạn [0; 3] bằng bao nhiêu?", "options": [{"id": "A", "text": "5"}, {"id": "B", "text": "4"}, {"id": "C", "text": "1"}], "correctOption": "A", "explanation": "y'' = -2x + 4 = 0 ⇔ x = 2 thuộc [0; 3]. Ta tính: y(0) = 1, y(2) = 5, y(3) = 4. Vậy giá trị lớn nhất bằng 5.", "difficulty": "MEDIUM", "points": 10}, {"id": "math-12-asymptotes-q1", "prompt": "Đường thẳng x = a được gọi là đường tiệm cận đứng của đồ thị hàm số y = f(x) nếu thỏa mãn điều kiện nào?", "options": [{"id": "A", "text": "Ít nhất một trong các giới hạn một bên khi x tiến đến a là vô cực"}, {"id": "B", "text": "Giới hạn khi x tiến đến vô cực bằng a"}, {"id": "C", "text": "Đạo hàm f''(a) bằng 0"}], "correctOption": "A", "explanation": "Định nghĩa tiệm cận đứng yêu cầu lim_{x→a⁺} f(x) = ±∞ hoặc lim_{x→a⁻} f(x) = ±∞.", "difficulty": "EASY", "points": 10}, {"id": "math-12-asymptotes-q2", "prompt": "Tìm phương trình đường tiệm cận ngang của đồ thị hàm số y = (3x - 1)/(x + 2).", "options": [{"id": "A", "text": "x = -2"}, {"id": "B", "text": "y = -1/2"}, {"id": "C", "text": "y = 3"}], "correctOption": "C", "explanation": "Ta có lim_{x→+∞} (3x - 1)/(x + 2) = 3 và lim_{x→-∞} (3x - 1)/(x + 2) = 3 nên y = 3 là tiệm cận ngang.", "difficulty": "MEDIUM", "points": 10}, {"id": "math-12-graph-analysis-q1", "prompt": "Đối với hàm số bậc ba y = ax³ + bx² + cx + d (a ≠ 0), nếu lim_{x→+∞} y = +∞ thì dấu của hệ số a là:", "options": [{"id": "A", "text": "a < 0"}, {"id": "B", "text": "a = 0"}, {"id": "C", "text": "a > 0"}], "correctOption": "C", "explanation": "Khi x tiến ra dương vô cực, giới hạn của đa thức bậc ba cùng dấu với hệ số cao nhất a. Do đó a > 0.", "difficulty": "EASY", "points": 10}, {"id": "math-12-graph-analysis-q2", "prompt": "Tâm đối xứng của đồ thị hàm phân thức bậc nhất trên bậc nhất y = (ax + b)/(cx + d) (với c ≠ 0, ad - bc ≠ 0) là:", "options": [{"id": "A", "text": "Giao điểm của đồ thị với trục hoành Ox"}, {"id": "B", "text": "Giao điểm của tiệm cận đứng và tiệm cận ngang"}, {"id": "C", "text": "Giao điểm của đồ thị với trục tung Oy"}], "correctOption": "B", "explanation": "Đồ thị hàm nhất biến nhận giao điểm của hai đường tiệm cận làm tâm đối xứng.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-math-12-2','Ôn tập bài 6–10','math',12,'Bài 6–10','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "math-12-vectors-space-q1", "prompt": "Trong không gian, quy tắc hình hộp khẳng định tổng ba vectơ chung gốc xuất phát từ một đỉnh của hình hộp bằng vectơ nào?", "options": [{"id": "A", "text": "Vectơ cạnh đối diện"}, {"id": "B", "text": "Vectơ đường chéo xuất phát từ đỉnh đó"}, {"id": "C", "text": "Vectơ đường chéo của mặt đáy"}], "correctOption": "B", "explanation": "Với hình hộp ABCD.A''B''C''D'', ta luôn có vectơ AB + vectơ AD + vectơ AA'' = vectơ AC''.", "difficulty": "EASY", "points": 10}, {"id": "math-12-vectors-space-q2", "prompt": "Cho tứ diện ABCD có G là trọng tâm của tam giác BCD. Đẳng thức vectơ nào sau đây đúng?", "options": [{"id": "A", "text": "vectơ AB + vectơ AC + vectơ AD = 3 vectơ AG"}, {"id": "B", "text": "vectơ AB + vectơ AC + vectơ AD = vectơ AG"}, {"id": "C", "text": "vectơ AB + vectơ AC + vectơ AD = 4 vectơ AG"}], "correctOption": "A", "explanation": "Vì G là trọng tâm tam giác BCD nên vectơ GB + vectơ GC + vectơ GD = vectơ 0. Biểu diễn qua điểm A ta được vectơ AB + AC + AD = 3 AG.", "difficulty": "MEDIUM", "points": 10}, {"id": "math-12-coordinates-space-q1", "prompt": "Trong không gian Oxyz, tọa độ của gốc tọa độ O là:", "options": [{"id": "A", "text": "(0; 0; 0)"}, {"id": "B", "text": "(1; 1; 1)"}, {"id": "C", "text": "(0; 0; 1)"}], "correctOption": "A", "explanation": "Gốc tọa độ O có hoành độ, tung độ và cao độ đều bằng 0.", "difficulty": "EASY", "points": 10}, {"id": "math-12-coordinates-space-q2", "prompt": "Cho hai điểm A(2; -1; 4) và B(4; 3; 0). Tọa độ trung điểm M của đoạn thẳng AB là:", "options": [{"id": "A", "text": "(6; 2; 4)"}, {"id": "B", "text": "(1; 2; -2)"}, {"id": "C", "text": "(3; 1; 2)"}], "correctOption": "C", "explanation": "xM = (2 + 4)/2 = 3; yM = (-1 + 3)/2 = 1; zM = (4 + 0)/2 = 2. Vậy M(3; 1; 2).", "difficulty": "MEDIUM", "points": 10}, {"id": "math-12-dot-product-space-q1", "prompt": "Hai vectơ u và v khác vectơ không trong không gian vuông góc với nhau khi và chỉ khi:", "options": [{"id": "A", "text": "Tổng u + v = 0"}, {"id": "B", "text": "Độ dài |u| = |v|"}, {"id": "C", "text": "Tích vô hướng u · v = 0"}], "correctOption": "C", "explanation": "cos 90° = 0 nên tích vô hướng u · v = |u||v|cos 90° = 0.", "difficulty": "EASY", "points": 10}, {"id": "math-12-dot-product-space-q2", "prompt": "Tính tích vô hướng của hai vectơ a = (1; 3; -2) và b = (4; -1; 1).", "options": [{"id": "A", "text": "9"}, {"id": "B", "text": "-1"}, {"id": "C", "text": "5"}], "correctOption": "B", "explanation": "a · b = 1*4 + 3*(-1) + (-2)*1 = 4 - 3 - 2 = -1.", "difficulty": "MEDIUM", "points": 10}, {"id": "math-12-sphere-equation-q1", "prompt": "Mặt cầu (S): (x - 2)² + (y + 1)² + (z - 3)² = 25 có tọa độ tâm I và bán kính R lần lượt là:", "options": [{"id": "A", "text": "I(2; -1; 3) và R = 25"}, {"id": "B", "text": "I(2; -1; 3) và R = 5"}, {"id": "C", "text": "I(-2; 1; -3) và R = 25"}], "correctOption": "B", "explanation": "Từ phương trình chính tắc (x - a)² + (y - b)² + (z - c)² = R², ta có a = 2, b = -1, c = 3 và R = √25 = 5.", "difficulty": "EASY", "points": 10}, {"id": "math-12-sphere-equation-q2", "prompt": "Viết phương trình mặt cầu nhận đoạn thẳng AB làm đường kính với A(1; 0; 2) và B(3; 4; 0).", "options": [{"id": "A", "text": "(x - 2)² + (y - 2)² + (z - 1)² = 6"}, {"id": "B", "text": "(x - 2)² + (y - 2)² + (z - 1)² = 24"}, {"id": "C", "text": "(x - 1)² + y² + (z - 2)² = 6"}], "correctOption": "A", "explanation": "Tâm I là trung điểm AB: I(2; 2; 1). Bán kính R = AB/2 = √[(3-1)² + (4-0)² + (0-2)²]/2 = √24 / 2 = √6. R² = 6.", "difficulty": "MEDIUM", "points": 10}, {"id": "math-12-plane-equation-q1", "prompt": "Một vectơ pháp tuyến của mặt phẳng (P): 2x - 3y + z - 5 = 0 là:", "options": [{"id": "A", "text": "n = (2; -3; 1)"}, {"id": "B", "text": "n = (2; 3; 1)"}, {"id": "C", "text": "n = (2; -3; -5)"}], "correctOption": "A", "explanation": "Các hệ số của x, y, z trong phương trình tổng quát chính là tọa độ của một vectơ pháp tuyến.", "difficulty": "EASY", "points": 10}, {"id": "math-12-plane-equation-q2", "prompt": "Phương trình mặt phẳng đi qua M(1; 2; -1) và nhận n = (2; 1; 3) làm vectơ pháp tuyến là:", "options": [{"id": "A", "text": "2x + y + 3z + 1 = 0"}, {"id": "B", "text": "x + 2y - z - 6 = 0"}, {"id": "C", "text": "2x + y + 3z - 1 = 0"}], "correctOption": "C", "explanation": "Phương trình: 2(x - 1) + 1(y - 2) + 3(z + 1) = 0 ⇔ 2x + y + 3z - 2 - 2 + 3 = 0 ⇔ 2x + y + 3z - 1 = 0.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-math-12-3','Ôn tập bài 11–15','math',12,'Bài 11–15','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "math-12-antiderivative-q1", "prompt": "Cho F(x) là một nguyên hàm của hàm số f(x) trên khoảng K. Khẳng định nào sau đây đúng?", "options": [{"id": "A", "text": "Đạo hàm F''(x) bằng -f(x) với mọi x thuộc K"}, {"id": "B", "text": "∫ F(x) dx = f(x) + C"}, {"id": "C", "text": "F''(x) = f(x) với mọi x thuộc K"}], "correctOption": "C", "explanation": "Định nghĩa nguyên hàm: F(x) là nguyên hàm của f(x) khi và chỉ khi đạo hàm của F(x) bằng f(x).", "difficulty": "EASY", "points": 10}, {"id": "math-12-antiderivative-q2", "prompt": "Tìm họ nguyên hàm của hàm số f(x) = 4x³ - 2x + 1.", "options": [{"id": "A", "text": "4x⁴ - 2x² + x + C"}, {"id": "B", "text": "x⁴ - x² + x + C"}, {"id": "C", "text": "12x² - 2 + C"}], "correctOption": "B", "explanation": "Áp dụng công thức nguyên hàm từng số hạng: ∫ 4x³ dx = x⁴, ∫ (-2x) dx = -x², ∫ 1 dx = x.", "difficulty": "MEDIUM", "points": 10}, {"id": "math-12-definite-integral-q1", "prompt": "Theo công thức Newton - Leibniz, nếu F(x) là một nguyên hàm của hàm số f(x) liên tục trên [a; b] thì:", "options": [{"id": "A", "text": "∫_a^b f(x) dx = F(a) + F(b)"}, {"id": "B", "text": "∫_a^b f(x) dx = F(b) - F(a)"}, {"id": "C", "text": "∫_a^b f(x) dx = F(a) - F(b)"}], "correctOption": "B", "explanation": "Công thức cơ bản của giải tích liên hệ tích phân xác định với hiệu giá trị của nguyên hàm tại hai đầu mút.", "difficulty": "EASY", "points": 10}, {"id": "math-12-definite-integral-q2", "prompt": "Tính tích phân I = ∫_1^2 (3x² + 1) dx.", "options": [{"id": "A", "text": "8"}, {"id": "B", "text": "10"}, {"id": "C", "text": "7"}], "correctOption": "A", "explanation": "F(x) = x³ + x. Ta có F(2) = 2³ + 2 = 10; F(1) = 1³ + 1 = 2. Vậy I = F(2) - F(1) = 10 - 2 = 8.", "difficulty": "MEDIUM", "points": 10}, {"id": "math-12-grouped-dispersion-q1", "prompt": "Số đặc trưng nào bằng căn bậc hai số học của phương sai trong thống kê?", "options": [{"id": "A", "text": "Độ lệch chuẩn"}, {"id": "B", "text": "Khoảng biến thiên"}, {"id": "C", "text": "Khoảng tứ phân vị"}], "correctOption": "A", "explanation": "Độ lệch chuẩn s được định nghĩa là căn bậc hai số học của phương sai s²: s = √(s²).", "difficulty": "EASY", "points": 10}, {"id": "math-12-grouped-dispersion-q2", "prompt": "Một mẫu số liệu ghép nhóm có tứ phân vị thứ nhất Q₁ = 45 và tứ phân vị thứ ba Q₃ = 75. Khoảng tứ phân vị IQR của mẫu bằng:", "options": [{"id": "A", "text": "120"}, {"id": "B", "text": "60"}, {"id": "C", "text": "30"}], "correctOption": "C", "explanation": "Khoảng tứ phân vị được tính theo công thức IQR = Q₃ - Q₁ = 75 - 45 = 30.", "difficulty": "MEDIUM", "points": 10}, {"id": "math-12-conditional-probability-q1", "prompt": "Cho hai biến cố A và B với P(B) > 0. Công thức tính xác suất có điều kiện của A khi biết B đã xảy ra là:", "options": [{"id": "A", "text": "P(A|B) = P(A) / P(B)"}, {"id": "B", "text": "P(A|B) = P(A ∩ B) · P(B)"}, {"id": "C", "text": "P(A|B) = P(A ∩ B) / P(B)"}], "correctOption": "C", "explanation": "Định nghĩa xác suất có điều kiện là tỉ số giữa xác suất đồng thời P(A ∩ B) và xác suất điều kiện P(B).", "difficulty": "EASY", "points": 10}, {"id": "math-12-conditional-probability-q2", "prompt": "Cho P(A) = 0,6; P(B) = 0,5 và P(A ∩ B) = 0,3. Giá trị của P(A|B) bằng:", "options": [{"id": "A", "text": "0,15"}, {"id": "B", "text": "0,6"}, {"id": "C", "text": "0,5"}], "correctOption": "B", "explanation": "P(A|B) = P(A ∩ B) / P(B) = 0,3 / 0,5 = 0,6.", "difficulty": "MEDIUM", "points": 10}, {"id": "math-12-bayes-formula-q1", "prompt": "Nếu {B₁, B₂} là một hệ đầy đủ các biến cố thì công thức xác suất toàn phần đối với biến cố A là:", "options": [{"id": "A", "text": "P(A) = P(A|B₁) · P(A|B₂)"}, {"id": "B", "text": "P(A) = P(B₁) · P(A|B₁) + P(B₂) · P(A|B₂)"}, {"id": "C", "text": "P(A) = P(B₁) + P(B₂)"}], "correctOption": "B", "explanation": "Công thức xác suất toàn phần phân tích biến cố A thành tổng hợp các trường hợp loại trừ nhau tương ứng với hệ đầy đủ.", "difficulty": "EASY", "points": 10}, {"id": "math-12-bayes-formula-q2", "prompt": "Một xí nghiệp có hai dây chuyền sản xuất: máy I sản xuất 60% sản phẩm với tỉ lệ phế phẩm 2%; máy II sản xuất 40% sản phẩm với tỉ lệ phế phẩm 3%. Tỉ lệ phế phẩm chung P(A) của xí nghiệp là:", "options": [{"id": "A", "text": "0,024 (2,4%)"}, {"id": "B", "text": "0,050 (5,0%)"}, {"id": "C", "text": "0,012 (1,2%)"}], "correctOption": "A", "explanation": "P(A) = P(I)P(A|I) + P(II)P(A|II) = 0,6 * 0,02 + 0,4 * 0,03 = 0,012 + 0,012 = 0,024 = 2,4%.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-physics-12-1','Ôn tập bài 1–5','physics',12,'Bài 1–5','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "physics-12-matter-model-q1", "prompt": "Theo mô hình động học phân tử, khi nhiệt độ của một vật tăng lên thì:", "options": [{"id": "A", "text": "Tốc độ chuyển động hỗn loạn của các phân tử cấu tạo nên vật tăng"}, {"id": "B", "text": "Khối lượng của mỗi phân tử cấu tạo nên vật tăng lên"}, {"id": "C", "text": "Khoảng cách giữa các phân tử luôn giảm đi đáng kể"}], "correctOption": "A", "explanation": "Nhiệt độ là số đo động năng chuyển động nhiệt trung bình của các phân tử. Nhiệt độ tăng nghĩa là phân tử chuyển động nhanh hơn.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-matter-model-q2", "prompt": "Đặc điểm căn bản về cấu trúc phân tử của chất ở thể khí so với thể rắn và lỏng là:", "options": [{"id": "A", "text": "Các phân tử khí liên kết chặt chẽ và chỉ dao động quanh vị trí cân bằng"}, {"id": "B", "text": "Các phân tử khí hoàn toàn không có tương tác đẩy"}, {"id": "C", "text": "Khoảng cách giữa các phân tử rất lớn so với kích thước của chính chúng"}], "correctOption": "C", "explanation": "Ở thể khí, khoảng cách trung bình giữa các phân tử lớn gấp hàng chục lần kích thước phân tử nên lực tương tác rất yếu.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-temperature-scales-q1", "prompt": "Hai vật ở trạng thái cân bằng nhiệt với nhau khi và chỉ khi chúng có cùng:", "options": [{"id": "A", "text": "Nội năng"}, {"id": "B", "text": "Khối lượng"}, {"id": "C", "text": "Nhiệt độ"}], "correctOption": "C", "explanation": "Điều kiện cân bằng nhiệt giữa hai hệ tiếp xúc nhiệt là nhiệt độ của chúng bằng nhau, khi đó không còn dòng nhiệt truyền qua lại.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-temperature-scales-q2", "prompt": "Nhiệt độ sôi của nước ở áp suất tiêu chuẩn là 100 °C tương ứng với bao nhiêu Kelvin?", "options": [{"id": "A", "text": "100 K"}, {"id": "B", "text": "373,15 K"}, {"id": "C", "text": "273,15 K"}], "correctOption": "B", "explanation": "Công thức chuyển đổi: T(K) = t(°C) + 273,15 = 100 + 273,15 = 373,15 K.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-heat-capacity-q1", "prompt": "Đơn vị đo của nhiệt dung riêng trong hệ đơn vị quốc tế SI là:", "options": [{"id": "A", "text": "W/(kg·K)"}, {"id": "B", "text": "J/(kg·K)"}, {"id": "C", "text": "J/kg"}], "correctOption": "B", "explanation": "Nhiệt dung riêng c = Q / (m·ΔT) có đơn vị là Joule trên kilogram Kelvin (J/(kg·K)).", "difficulty": "EASY", "points": 10}, {"id": "physics-12-heat-capacity-q2", "prompt": "Tính nhiệt lượng cần thiết để đun nóng 2 kg nước từ 20 °C lên 80 °C. Biết nhiệt dung riêng của nước c = 4200 J/(kg·K).", "options": [{"id": "A", "text": "504 kJ"}, {"id": "B", "text": "252 kJ"}, {"id": "C", "text": "672 kJ"}], "correctOption": "A", "explanation": "Q = m · c · ΔT = 2 · 4200 · (80 - 20) = 8400 · 60 = 504 000 J = 504 kJ.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-internal-energy-q1", "prompt": "Biểu thức toán học của định luật I nhiệt động lực học là:", "options": [{"id": "A", "text": "ΔU = Q + A"}, {"id": "B", "text": "ΔU = Q · A"}, {"id": "C", "text": "Q = ΔU + A²"}], "correctOption": "A", "explanation": "Định luật I là dạng biểu diễn của định luật bảo toàn và chuyển hóa năng lượng áp dụng cho các quá trình nhiệt: ΔU = Q + A.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-internal-energy-q2", "prompt": "Một khối khí nhận nhiệt lượng 600 J từ nguồn nhiệt và thực hiện công 400 J đẩy piston nâng vật nặng lên. Độ biến thiên nội năng của khối khí là:", "options": [{"id": "A", "text": "+1000 J"}, {"id": "B", "text": "-200 J"}, {"id": "C", "text": "+200 J"}], "correctOption": "C", "explanation": "Hệ nhận nhiệt: Q = +600 J; hệ sinh công: A = -400 J. Ta có ΔU = Q + A = 600 + (-400) = +200 J.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-thermal-efficiency-q1", "prompt": "Hiệu suất nhiệt H của động cơ nhiệt được định nghĩa là tỉ số giữa:", "options": [{"id": "A", "text": "Nhiệt lượng truyền cho nguồn lạnh và nhiệt lượng nhận từ nguồn nóng"}, {"id": "B", "text": "Nhiệt lượng nhận từ nguồn nóng và công toàn phần"}, {"id": "C", "text": "Công cơ học có ích sinh ra và nhiệt lượng nhận từ nguồn nóng"}], "correctOption": "C", "explanation": "Hiệu suất H = A'' / Q₁ phản ánh tỉ lệ nhiệt năng được chuyển hóa thành cơ công hữu ích.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-thermal-efficiency-q2", "prompt": "Một động cơ nhiệt nhận nhiệt lượng 2000 J từ nguồn nóng trong mỗi chu trình và nhả cho nguồn lạnh 1200 J. Hiệu suất của động cơ là:", "options": [{"id": "A", "text": "30%"}, {"id": "B", "text": "40%"}, {"id": "C", "text": "60%"}], "correctOption": "B", "explanation": "Công có ích A'' = Q₁ - |Q₂| = 2000 - 1200 = 800 J. Hiệu suất H = 800 / 2000 = 0,4 = 40%.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-physics-12-2','Ôn tập bài 6–10','physics',12,'Bài 6–10','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "physics-12-ideal-gas-model-q1", "prompt": "Trong mô hình khí lí tưởng, tương tác giữa các phân tử khí được xem xét như thế nào?", "options": [{"id": "A", "text": "Luôn đẩy nhau liên tục kể cả khi ở rất xa nhau"}, {"id": "B", "text": "Chỉ tương tác đẩy hoặc hút khi chúng va chạm vào nhau hoặc vào thành bình"}, {"id": "C", "text": "Luôn hút nhau bằng lực tĩnh điện mạnh ở mọi khoảng cách"}], "correctOption": "B", "explanation": "Mô hình khí lí tưởng bỏ qua tương tác tầm xa giữa các phân tử; lực tương tác chỉ xuất hiện tức thời khi có va chạm.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-ideal-gas-model-q2", "prompt": "Mô hình khí lí tưởng coi các phân tử khí là:", "options": [{"id": "A", "text": "Các chất điểm có khối lượng nhưng thể tích bản thân không đáng kể so với thể tích bình"}, {"id": "B", "text": "Các hình cầu rắn có kích thước bằng thể tích bình chứa"}, {"id": "C", "text": "Các hạt đứng yên tại các nút mạng tinh thể xác định"}], "correctOption": "A", "explanation": "Vì khoảng cách giữa các phân tử khí rất lớn so với kích thước của chúng nên thể tích riêng của các phân tử được coi là chất điểm.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-boyle-law-q1", "prompt": "Định luật Boyle áp dụng cho quá trình biến đổi trạng thái nào của chất khí?", "options": [{"id": "A", "text": "Quá trình đẳng nhiệt"}, {"id": "B", "text": "Quá trình đẳng áp"}, {"id": "C", "text": "Quá trình đẳng tích"}], "correctOption": "A", "explanation": "Định luật Boyle nghiên cứu mối quan hệ giữa áp suất và thể tích khi nhiệt độ T được giữ không đổi.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-boyle-law-q2", "prompt": "Một khối khí lí tưởng có thể tích 6 lít ở áp suất 1,5 atm. Giữ nhiệt độ không đổi, nén khối khí đến thể tích 2 lít thì áp suất mới là:", "options": [{"id": "A", "text": "2,0 atm"}, {"id": "B", "text": "3,0 atm"}, {"id": "C", "text": "4,5 atm"}], "correctOption": "C", "explanation": "Theo định luật Boyle: p₁V₁ = p₂V₂ ⇒ p₂ = (1,5 * 6) / 2 = 9 / 2 = 4,5 atm.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-charles-law-q1", "prompt": "Trong quá trình đẳng áp của một lượng khí lí tưởng xác định, thể tích của khối khí:", "options": [{"id": "A", "text": "Tỉ lệ nghịch với nhiệt độ tuyệt đối T"}, {"id": "B", "text": "Tỉ lệ thuận với bình phương nhiệt độ Celsius"}, {"id": "C", "text": "Tỉ lệ thuận với nhiệt độ tuyệt đối T"}], "correctOption": "C", "explanation": "Định luật Charles: V / T = const, thể tích tỉ lệ thuận với nhiệt độ tính theo thang Kelvin.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-charles-law-q2", "prompt": "Một khối khí có thể tích 5 lít ở nhiệt độ 250 K. Giữ áp suất không đổi, khi nung nóng khối khí đến 350 K thì thể tích của nó bằng:", "options": [{"id": "A", "text": "8,5 lít"}, {"id": "B", "text": "7,0 lít"}, {"id": "C", "text": "6,0 lít"}], "correctOption": "B", "explanation": "Theo định luật Charles: V₂ = V₁ · (T₂ / T₁) = 5 · (350 / 250) = 5 · 1,4 = 7,0 lít.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-state-equation-q1", "prompt": "Phương trình trạng thái của khí lí tưởng cho một lượng khí xác định là:", "options": [{"id": "A", "text": "(p · T) · V = hằng số"}, {"id": "B", "text": "(p · V) / T = hằng số"}, {"id": "C", "text": "p · T / V = hằng số"}], "correctOption": "B", "explanation": "Phương trình trạng thái kết hợp định luật Boyle và Charles cho hệ thức tổng quát pV/T = const.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-state-equation-q2", "prompt": "Tính áp suất của 1 mol khí lí tưởng chứa trong bình kín thể tích 0,01 m³ ở nhiệt độ 300 K. Cho hằng số khí R = 8,31 J/(mol·K).", "options": [{"id": "A", "text": "2,49 × 10⁵ Pa"}, {"id": "B", "text": "1,25 × 10⁵ Pa"}, {"id": "C", "text": "8,31 × 10⁴ Pa"}], "correctOption": "A", "explanation": "Áp dụng p = nRT / V = (1 · 8,31 · 300) / 0,01 = 2493 / 0,01 = 249 300 Pa ≈ 2,49 × 10⁵ Pa.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-molecular-pressure-q1", "prompt": "Động năng chuyển động nhiệt tịnh tiến trung bình của các phân tử khí lí tưởng tỉ lệ thuận với:", "options": [{"id": "A", "text": "Nhiệt độ tuyệt đối T của chất khí"}, {"id": "B", "text": "Thể tích V của bình chứa"}, {"id": "C", "text": "Khối lượng mol M của chất khí"}], "correctOption": "A", "explanation": "Hệ thức Boltzmann E_d = (3/2)kT cho thấy động năng tịnh tiến trung bình tỉ lệ thuận trực tiếp với nhiệt độ Kelvin.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-molecular-pressure-q2", "prompt": "Bản chất vi mô của áp suất chất khí tác dụng lên thành bình chứa là do:", "options": [{"id": "A", "text": "Trọng lực của các phân tử khí đè nén lên đáy bình chứa"}, {"id": "B", "text": "Lực hút tĩnh điện giữa thành bình và các electron của chất khí"}, {"id": "C", "text": "Hàng tỉ phân tử khí va chạm liên tục và truyền động lượng lên thành bình"}], "correctOption": "C", "explanation": "Mỗi phân tử va chạm đàn hồi vào thành bình làm đổi hướng vận tốc, truyền xung lượng; tổng hợp vô số va chạm tạo nên áp suất liên tục.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-physics-12-3','Ôn tập bài 11–15','physics',12,'Bài 11–15','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "physics-12-magnetic-field-q1", "prompt": "Từ trường không tác dụng lực lên đối tượng nào sau đây?", "options": [{"id": "A", "text": "Một đoạn dây dẫn có dòng điện chạy qua"}, {"id": "B", "text": "Một hạt mang điện đang chuyển động cắt các đường sức từ"}, {"id": "C", "text": "Một điện tích đứng yên trong từ trường"}], "correctOption": "C", "explanation": "Lực từ chỉ xuất hiện khi điện tích chuyển động (hoặc có dòng điện); điện tích đứng yên không chịu tác dụng của lực từ.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-magnetic-field-q2", "prompt": "Tính chất hình học cơ bản của các đường sức từ là:", "options": [{"id": "A", "text": "Luôn cắt nhau tại các điểm có từ trường mạnh"}, {"id": "B", "text": "Là những đường cong khép kín (hoặc vô hạn ở hai đầu)"}, {"id": "C", "text": "Là các đoạn thẳng hở bắt đầu từ cực dương và kết thúc ở cực âm"}], "correctOption": "B", "explanation": "Từ trường là trường xoáy, không có điểm khởi đầu hay kết thúc nên các đường sức từ luôn là đường cong kín.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-magnetic-force-q1", "prompt": "Lực từ tác dụng lên đoạn dây dẫn mang dòng điện đặt trong từ trường đều đạt giá trị cực đại khi góc θ giữa đoạn dây và vectơ cảm ứng từ bằng:", "options": [{"id": "A", "text": "180°"}, {"id": "B", "text": "90°"}, {"id": "C", "text": "0°"}], "correctOption": "B", "explanation": "F = B·I·L·sin θ. Hàm sin θ đạt cực đại bằng 1 khi góc θ = 90° (dây dẫn vuông góc với đường sức từ).", "difficulty": "EASY", "points": 10}, {"id": "physics-12-magnetic-force-q2", "prompt": "Đoạn dây dẫn thẳng dài 0,2 m mang dòng điện cường độ 5 A đặt vuông góc với các đường cảm ứng từ của từ trường đều B = 0,4 T. Độ lớn lực từ tác dụng lên đoạn dây là:", "options": [{"id": "A", "text": "0,4 N"}, {"id": "B", "text": "0,8 N"}, {"id": "C", "text": "0,2 N"}], "correctOption": "A", "explanation": "F = B · I · L · sin 90° = 0,4 · 5 · 0,2 · 1 = 0,4 N.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-magnetic-induction-q1", "prompt": "Vectơ cảm ứng từ B tại một điểm đặc trưng cho từ trường tại điểm đó về phương diện:", "options": [{"id": "A", "text": "Tác dụng lực từ"}, {"id": "B", "text": "Năng lượng tĩnh điện"}, {"id": "C", "text": "Tốc độ truyền sóng"}], "correctOption": "A", "explanation": "Cảm ứng từ B là đại lượng vectơ đặc trưng cho từ trường về mặt gây ra lực từ tác dụng lên dòng điện hay điện tích chuyển động.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-magnetic-induction-q2", "prompt": "Tính cảm ứng từ do dòng điện thẳng dài cường độ 10 A gây ra tại một điểm cách dây dẫn 0,05 m trong không khí.", "options": [{"id": "A", "text": "2 × 10⁻⁵ T"}, {"id": "B", "text": "4 × 10⁻⁶ T"}, {"id": "C", "text": "4 × 10⁻⁵ T"}], "correctOption": "C", "explanation": "B = 2 · 10⁻⁷ · (I / r) = 2 · 10⁻⁷ · (10 / 0,05) = 2 · 10⁻⁷ · 200 = 4 · 10⁻⁵ T.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-lorentz-force-q1", "prompt": "Phương của lực Lorentz tác dụng lên hạt mang điện chuyển động trong từ trường đều có đặc điểm nào?", "options": [{"id": "A", "text": "Cùng phương với vectơ cảm ứng từ B"}, {"id": "B", "text": "Cùng phương với vectơ vận tốc v của hạt"}, {"id": "C", "text": "Vuông góc với cả vectơ vận tốc v và vectơ cảm ứng từ B"}], "correctOption": "C", "explanation": "Lực Lorentz có phương vuông góc với mặt phẳng tạo bởi vectơ vận tốc v và vectơ cảm ứng từ B.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-lorentz-force-q2", "prompt": "Một hạt mang điện tích q = 1,6·10⁻¹⁹ C bay với vận tốc v = 2·10⁶ m/s vuông góc vào từ trường đều B = 0,5 T. Độ lớn lực Lorentz tác dụng lên hạt là:", "options": [{"id": "A", "text": "0,8 × 10⁻¹³ N"}, {"id": "B", "text": "1,6 × 10⁻¹³ N"}, {"id": "C", "text": "3,2 × 10⁻¹³ N"}], "correctOption": "B", "explanation": "f = |q| · v · B · sin 90° = 1,6 · 10⁻¹⁹ · 2 · 10⁶ · 0,5 · 1 = 1,6 · 10⁻¹³ N.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-electromagnetic-induction-q1", "prompt": "Điều kiện tiên quyết để xuất hiện dòng điện cảm ứng trong một khung dây dẫn kín là:", "options": [{"id": "A", "text": "Khung dây phải luôn chuyển động nhanh dần đều"}, {"id": "B", "text": "Từ thông qua diện tích giới hạn bởi khung dây biến thiên theo thời gian"}, {"id": "C", "text": "Khung dây phải được đặt trong từ trường có độ lớn cực kì lớn"}], "correctOption": "B", "explanation": "Hiện tượng cảm ứng điện từ chỉ xảy ra khi có sự biến thiên từ thông gửi qua mạch kín theo thời gian.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-electromagnetic-induction-q2", "prompt": "Từ thông qua một mạch kín biến thiên đều giảm từ 0,08 Wb xuống 0,02 Wb trong khoảng thời gian 0,1 s. Độ lớn suất điện động cảm ứng xuất hiện trong mạch là:", "options": [{"id": "A", "text": "0,6 V"}, {"id": "B", "text": "0,06 V"}, {"id": "C", "text": "6,0 V"}], "correctOption": "A", "explanation": "Theo định luật Faraday: |e_c| = |ΔΦ / Δt| = |(0,02 - 0,08) / 0,1| = |-0,06 / 0,1| = 0,6 V.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-physics-12-4','Ôn tập bài 16–20','physics',12,'Bài 16–20','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "physics-12-nuclear-structure-q1", "prompt": "Hạt nhân nguyên tử được cấu tạo bởi hai loại hạt cơ bản (gọi chung là nucleon) gồm:", "options": [{"id": "A", "text": "Proton và neutron"}, {"id": "B", "text": "Proton và electron"}, {"id": "C", "text": "Neutron và electron"}], "correctOption": "A", "explanation": "Nucleon cấu tạo nên hạt nhân nguyên tử bao gồm các hạt proton mang điện tích dương và neutron không mang điện.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-nuclear-structure-q2", "prompt": "Hạt nhân He-4 có độ hụt khối Δm = 0,0304 u. Cho biết 1 u ≈ 931,5 MeV/c². Năng lượng liên kết của hạt nhân He-4 xấp xỉ bằng:", "options": [{"id": "A", "text": "14,2 MeV"}, {"id": "B", "text": "56,6 MeV"}, {"id": "C", "text": "28,3 MeV"}], "correctOption": "C", "explanation": "E_lk = Δm · c² = 0,0304 u · c² = 0,0304 · 931,5 MeV ≈ 28,3 MeV.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-radioactivity-q1", "prompt": "Tia phóng xạ nào sau đây có bản chất là sóng điện từ có bước sóng cực ngắn và năng lượng photon rất cao?", "options": [{"id": "A", "text": "Tia alpha (α)"}, {"id": "B", "text": "Tia beta trừ (β⁻)"}, {"id": "C", "text": "Tia gamma (γ)"}], "correctOption": "C", "explanation": "Tia gamma là bức xạ điện từ không mang điện, có tần số rất cao và khả năng đâm xuyên mạnh nhất.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-radioactivity-q2", "prompt": "Một chất phóng xạ có chu kì bán rã T = 8 ngày. Sau khoảng thời gian 24 ngày, tỉ lệ phần trăm số hạt nhân phóng xạ còn lại chưa phân rã so với ban đầu là:", "options": [{"id": "A", "text": "6,25%"}, {"id": "B", "text": "12,5%"}, {"id": "C", "text": "25,0%"}], "correctOption": "B", "explanation": "Số chu kì bán rã trôi qua là k = t / T = 24 / 8 = 3. Số hạt còn lại: N / N₀ = (1/2)³ = 1/8 = 12,5%.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-nuclear-reactions-q1", "prompt": "Định luật nào sau đây KHÔNG áp dụng cho các phản ứng hạt nhân?", "options": [{"id": "A", "text": "Định luật bảo toàn số nucleon (số khối A)"}, {"id": "B", "text": "Định luật bảo toàn khối lượng nghỉ"}, {"id": "C", "text": "Định luật bảo toàn điện tích"}], "correctOption": "B", "explanation": "Trong phản ứng hạt nhân, tổng khối lượng nghỉ trước và sau phản ứng có sự chênh lệch (độ hụt khối chuyển hóa thành năng lượng) nên khối lượng nghỉ không bảo toàn.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-nuclear-reactions-q2", "prompt": "Trong phản ứng hạt nhân: ₁²H + ₁³H → ₂⁴He + X. Hạt X sinh ra là hạt nào sau đây?", "options": [{"id": "A", "text": "Hạt neutron (₀¹n)"}, {"id": "B", "text": "Hạt proton (₁¹p)"}, {"id": "C", "text": "Hạt electron (-₁⁰e)"}], "correctOption": "A", "explanation": "Áp dụng bảo toàn điện tích Z: 1 + 1 = 2 + Z_X ⇒ Z_X = 0. Bảo toàn số nucleon A: 2 + 3 = 4 + A_X ⇒ A_X = 1. Hạt có Z = 0, A = 1 là neutron.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-fission-fusion-q1", "prompt": "Bản chất của phản ứng nhiệt hạch (phản ứng tổng hợp hạt nhân) là quá trình:", "options": [{"id": "A", "text": "Kết hợp hai hạt nhân rất nhẹ thành một hạt nhân nặng hơn ở nhiệt độ cực kì cao"}, {"id": "B", "text": "Bắn phá hạt nhân nặng bằng neutron làm nó vỡ thành hai mảnh nhẹ"}, {"id": "C", "text": "Hạt nhân tự phát bức xạ tia gamma mà không thay đổi cấu tạo"}], "correctOption": "A", "explanation": "Nhiệt hạch là phản ứng kết hợp hai hạt nhân có số khối nhỏ (như hydro, deuteri, triti) thành hạt nhân nặng hơn ở điều kiện nhiệt độ hàng trăm triệu độ.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-fission-fusion-q2", "prompt": "Để duy trì phản ứng phân hạch dây chuyền tự duy trì có kiểm soát hoạt động ổn định trong lò phản ứng hạt nhân, hệ số nhân neutron k phải bằng:", "options": [{"id": "A", "text": "k > 1"}, {"id": "B", "text": "k < 1"}, {"id": "C", "text": "k = 1"}], "correctOption": "C", "explanation": "Hệ số k = 1 gọi là trạng thái tới hạn: số neutron sinh ra trung bình bù đắp đủ số neutron thất thoát và hấp thụ, duy trì công suất phát điện ổn định.", "difficulty": "MEDIUM", "points": 10}, {"id": "physics-12-radiation-safety-q1", "prompt": "Biện pháp nào sau đây giúp giảm liều chiếu xạ nguy hiểm cho người khi làm việc gần nguồn phóng xạ?", "options": [{"id": "A", "text": "Đứng càng gần nguồn phát phóng xạ càng tốt"}, {"id": "B", "text": "Tăng tối đa thời gian tiếp xúc trực tiếp với nguồn phóng xạ"}, {"id": "C", "text": "Tăng khoảng cách tới nguồn và sử dụng tấm che chắn chì/bê tông dày"}], "correctOption": "C", "explanation": "Liều bức xạ tỉ lệ nghịch với bình phương khoảng cách và giảm theo hàm mũ khi qua các tấm che chắn chì hoặc bê tông.", "difficulty": "EASY", "points": 10}, {"id": "physics-12-radiation-safety-q2", "prompt": "Ứng dụng quan trọng của nguồn phóng xạ phát tia gamma trong y học hiện đại là:", "options": [{"id": "A", "text": "Đun sôi nước khử trùng phòng bệnh nhanh chóng"}, {"id": "B", "text": "Xạ trị tiêu diệt tế bào khối u ác tính hoặc phẫu thuật bằng dao mổ gamma"}, {"id": "C", "text": "Uống trực tiếp để cung cấp năng lượng trao đổi chất cho cơ thể"}], "correctOption": "B", "explanation": "Tia gamma mang năng lượng photon lớn được hội tụ chính xác để phá hủy cấu trúc DNA của các tế bào ung thư mà ít tổn thương mô lành.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-chemistry-12-1','Ôn tập bài 1–5','chemistry',12,'Bài 1–5','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "chemistry-12-ester-structure-q1", "prompt": "Tên gọi theo danh pháp thông thường của ester có công thức cấu tạo thu gọn CH₃COOC₂H₅ là:", "options": [{"id": "A", "text": "Ethyl acetate"}, {"id": "B", "text": "Methyl acetate"}, {"id": "C", "text": "Ethyl propionate"}], "correctOption": "A", "explanation": "Tên gọi gồm tên gốc ethyl (C₂H₅-) kết hợp với gốc acetate (CH₃COO-), thành ethyl acetate.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-ester-structure-q2", "prompt": "Trong các chất có khối lượng phân tử xấp xỉ nhau sau đây, chất nào có nhiệt độ sôi thấp nhất?", "options": [{"id": "A", "text": "CH₃COOH (Acetic acid)"}, {"id": "B", "text": "C₃H₇OH (Propan-1-ol)"}, {"id": "C", "text": "HCOOCH₃ (Methyl formate)"}], "correctOption": "C", "explanation": "Ester không có nguyên tử hydro linh động liên kết với oxy nên không tạo được liên kết hydro liên phân tử, do đó nhiệt độ sôi thấp hơn hẳn acid và alcohol.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-ester-reactions-q1", "prompt": "Phản ứng thủy phân ester trong dung dịch kiềm đun nóng còn được gọi là phản ứng gì?", "options": [{"id": "A", "text": "Phản ứng ester hóa"}, {"id": "B", "text": "Phản ứng trùng hợp"}, {"id": "C", "text": "Phản ứng xà phòng hóa"}], "correctOption": "C", "explanation": "Thủy phân ester tạo ra muối của acid béo (thành phần xà phòng) nên phản ứng này gọi là phản ứng xà phòng hóa.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-ester-reactions-q2", "prompt": "Đun nóng ethyl formate (HCOOC₂H₅) với dung dịch NaOH vừa đủ thu được các sản phẩm là:", "options": [{"id": "A", "text": "HCOONa và CH₃OH"}, {"id": "B", "text": "HCOONa và C₂H₅OH"}, {"id": "C", "text": "CH₃COONa và CH₃OH"}], "correctOption": "B", "explanation": "Phương trình phản ứng: HCOOC₂H₅ + NaOH → HCOONa (sodium formate) + C₂H₅OH (ethanol).", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-lipid-triglyceride-q1", "prompt": "Glycerol (glycerin) là polyalcohol ba chức tham gia cấu tạo nên mọi triglyceride có công thức là:", "options": [{"id": "A", "text": "C₃H₇OH"}, {"id": "B", "text": "C₃H₅(OH)₃"}, {"id": "C", "text": "C₂H₄(OH)₂"}], "correctOption": "B", "explanation": "Glycerol là propane-1,2,3-triol có 3 nhóm -OH liên kết với 3 nguyên tử carbon: C₃H₅(OH)₃.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-lipid-triglyceride-q2", "prompt": "Acid béo nào sau đây là acid béo no phổ biến trong mỡ động vật?", "options": [{"id": "A", "text": "Acid stearic (C₁₇H₃₅COOH)"}, {"id": "B", "text": "Acid oleic (C₁₇H₃₃COOH)"}, {"id": "C", "text": "Acid linoleic (C₁₇H₃₁COOH)"}], "correctOption": "A", "explanation": "Acid stearic có gốc hydrocarbon C₁₇H₃₅- no (dạng C_n H_2n+1) nên là acid béo no.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-lipid-reactions-q1", "prompt": "Xà phòng hóa hoàn toàn 1 mol chất béo triglyceride bằng dung dịch NaOH luôn thu được bao nhiêu mol glycerol?", "options": [{"id": "A", "text": "1 mol"}, {"id": "B", "text": "3 mol"}, {"id": "C", "text": "2 mol"}], "correctOption": "A", "explanation": "Mỗi phân tử triglyceride liên kết 3 gốc acid với 1 khung glycerol, do đó thủy phân 1 mol chất béo luôn giải phóng đúng 1 mol glycerol.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-lipid-reactions-q2", "prompt": "Quá trình chuyển hóa dầu thực vật (chất béo lỏng) thành bơ nhân tạo (chất béo rắn) trong công nghiệp dựa trên phản ứng:", "options": [{"id": "A", "text": "Thủy phân chất béo trong môi trường acid loãng"}, {"id": "B", "text": "Oxi hóa cắt mạch hydrocarbon bằng thuốc tím"}, {"id": "C", "text": "Hydrogen hóa chất béo không no có xúc tác nickel ở nhiệt độ cao"}], "correctOption": "C", "explanation": "Cộng hydrogen vào các liên kết đôi C=C của gốc acid béo không no chuyển thành gốc acid no có nhiệt độ nóng chảy cao hơn ở thể rắn.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-soap-detergent-q1", "prompt": "Muối nào sau đây là thành phần hoạt chất chính trong bánh xà phòng thông thường?", "options": [{"id": "A", "text": "Sodium chloride (NaCl)"}, {"id": "B", "text": "Calcium carbonate (CaCO₃)"}, {"id": "C", "text": "Sodium stearate (C₁₇H₃₅COONa)"}], "correctOption": "C", "explanation": "Xà phòng là muối sodium hoặc potassium của các acid béo, phổ biến là sodium stearate và sodium palmitate.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-soap-detergent-q2", "prompt": "Cơ chế làm sạch vết bẩn dầu mỡ của xà phòng dựa vào đặc điểm cấu tạo phân tử nào?", "options": [{"id": "A", "text": "Phân tử đóng vai trò là chất oxi hóa cực mạnh đốt cháy dầu mỡ"}, {"id": "B", "text": "Phân tử gồm một đầu ưa nước tan trong nước và một đuôi kị nước ưa dầu mỡ"}, {"id": "C", "text": "Phân tử có tính acid mạnh hòa tan mọi kim loại"}], "correctOption": "B", "explanation": "Đuôi kị nước găm vào giọt dầu mỡ, đầu ưa nước quay ra ngoài nước tạo thành các hạt micelle lơ lửng bị dòng nước cuốn đi.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-chemistry-12-2','Ôn tập bài 6–10','chemistry',12,'Bài 6–10','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "chemistry-12-carbohydrate-classification-q1", "prompt": "Chất nào sau đây thuộc loại monosaccharide không bị thủy phân?", "options": [{"id": "A", "text": "Tinh bột"}, {"id": "B", "text": "Glucose"}, {"id": "C", "text": "Saccharose"}], "correctOption": "B", "explanation": "Monosaccharide là carbohydrate đơn giản nhất không thể bị thủy phân thành đường nhỏ hơn, ví dụ glucose và fructose.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-carbohydrate-classification-q2", "prompt": "Glucose và fructose là hai chất:", "options": [{"id": "A", "text": "Đồng phân cấu tạo của nhau có cùng công thức phân tử C₆H₁₂O₆"}, {"id": "B", "text": "Đồng đẳng kế tiếp nhau trong cùng dãy đồng đẳng"}, {"id": "C", "text": "Thuộc hai loại đường disaccharide khác nhau"}], "correctOption": "A", "explanation": "Cả glucose và fructose đều có công thức phân tử C₆H₁₂O₆ nhưng glucose chứa nhóm -CHO còn fructose chứa nhóm >C=O, nên là đồng phân.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-glucose-fructose-reactions-q1", "prompt": "Thuốc thử được dùng để nhận biết dung dịch glucose tạo dung dịch phức chất màu xanh lam thẫm ở nhiệt độ thường là:", "options": [{"id": "A", "text": "Cu(OH)₂ trong môi trường kiềm"}, {"id": "B", "text": "Dung dịch AgNO₃ trong NH₃"}, {"id": "C", "text": "Dung dịch nước vôi trong Ca(OH)₂"}], "correctOption": "A", "explanation": "Vì glucose có nhiều nhóm -OH liền kề (polyalcohol) nên hòa tan Cu(OH)₂ ở nhiệt độ thường tạo dung dịch màu xanh lam thẫm.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-glucose-fructose-reactions-q2", "prompt": "Cho 1 mol glucose tham gia phản ứng tráng bạc hoàn toàn với dung dịch AgNO₃ trong NH₃ dư, lượng Ag kim loại kết tủa thu được tối đa là:", "options": [{"id": "A", "text": "1 mol"}, {"id": "B", "text": "4 mol"}, {"id": "C", "text": "2 mol"}], "correctOption": "C", "explanation": "Phân tử glucose có 1 nhóm aldehyde -CHO, theo phương trình phản ứng tráng bạc: 1 mol -CHO giải phóng 2 mol Ag kim loại.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-sucrose-maltose-q1", "prompt": "Đường mía, đường củ cải dùng làm chất tạo ngọt trong đời sống hàng ngày có thành phần chính là:", "options": [{"id": "A", "text": "Glucose"}, {"id": "B", "text": "Maltose"}, {"id": "C", "text": "Saccharose"}], "correctOption": "C", "explanation": "Saccharose là disaccharide phổ biến nhất, được sản xuất công nghiệp từ cây mía hoặc củ cải đường.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-sucrose-maltose-q2", "prompt": "Khi thủy phân hoàn toàn 1 mol saccharose trong môi trường acid đun nóng, ta thu được sản phẩm gồm:", "options": [{"id": "A", "text": "2 mol fructose"}, {"id": "B", "text": "1 mol glucose và 1 mol fructose"}, {"id": "C", "text": "2 mol glucose"}], "correctOption": "B", "explanation": "Phân tử saccharose được cấu tạo từ 1 gốc glucose và 1 gốc fructose, khi thủy phân phân cắt liên kết glycosidic tạo tỉ lệ mol 1:1.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-starch-q1", "prompt": "Thuốc thử đặc trưng dùng để nhận biết hồ tinh bột bằng phản ứng tạo màu xanh tím là:", "options": [{"id": "A", "text": "Dung dịch AgNO₃/NH₃"}, {"id": "B", "text": "Dung dịch iodine (I₂)"}, {"id": "C", "text": "Dung dịch Cu(OH)₂"}], "correctOption": "B", "explanation": "Cấu trúc xoắn ốc của amylose tạo các khoang rỗng hấp phụ phân tử iodine tạo phức chất có màu xanh tím đặc trưng.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-starch-q2", "prompt": "Điểm khác biệt cơ bản về mặt cấu trúc giữa amylose và amylopectin trong hạt tinh bột là:", "options": [{"id": "A", "text": "Amylose có cấu trúc mạch không phân nhánh, còn amylopectin có cấu trúc mạch phân nhánh"}, {"id": "B", "text": "Amylose là đường đơn, còn amylopectin là đường đôi"}, {"id": "C", "text": "Amylose có liên kết peptide, còn amylopectin có liên kết ester"}], "correctOption": "A", "explanation": "Amylose gồm các gốc α-glucose liên kết α-1,4 mạch thẳng xoắn; amylopectin có thêm các nhánh tại vị trí liên kết α-1,6-glycosidic.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-cellulose-q1", "prompt": "Trong công thức cấu tạo thu gọn [C₆H₇O₂(OH)₃]_n của cellulose, mỗi mắt xích C₆H₁₀O₅ chứa bao nhiêu nhóm hydroxy (-OH) tự do?", "options": [{"id": "A", "text": "3 nhóm -OH"}, {"id": "B", "text": "2 nhóm -OH"}, {"id": "C", "text": "5 nhóm -OH"}], "correctOption": "A", "explanation": "Mỗi mắt xích glucose trong mạch cellulose còn giữ lại đúng 3 nhóm alcohol tự do: [C₆H₇O₂(OH)₃]_n.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-cellulose-q2", "prompt": "Sản phẩm thu được khi cho cellulose phản ứng hoàn toàn với hỗn hợp acid nitric đặc và acid sulfuric đặc làm thuốc súng không khói là:", "options": [{"id": "A", "text": "Cellulose triacetate"}, {"id": "B", "text": "Trinitrotoluene (TNT)"}, {"id": "C", "text": "Cellulose trinitrate"}], "correctOption": "C", "explanation": "Ba nhóm -OH trong mỗi mắt xích bị ester hóa bởi HNO₃ tạo [C₆H₇O₂(ONO₂)₃]_n (cellulose trinitrate), một chất nổ mạnh không khói.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-chemistry-12-3','Ôn tập bài 11–15','chemistry',12,'Bài 11–15','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "chemistry-12-amines-q1", "prompt": "Hợp chất methylamine có công thức CH₃NH₂ thuộc loại amine bậc mấy?", "options": [{"id": "A", "text": "Amine bậc 2"}, {"id": "B", "text": "Amine bậc 3"}, {"id": "C", "text": "Amine bậc 1"}], "correctOption": "C", "explanation": "Bậc của amine tính bằng số nguyên tử H trong NH₃ được thay thế bằng gốc hydrocarbon. CH₃NH₂ có 1 gốc CH₃- nên là amine bậc 1.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-amines-q2", "prompt": "Dãy sắp xếp các chất theo thứ tự lực base giảm dần từ trái sang phải là:", "options": [{"id": "A", "text": "NH₃ > CH₃NH₂ > C₆H₅NH₂"}, {"id": "B", "text": "CH₃NH₂ > NH₃ > C₆H₅NH₂ (aniline)"}, {"id": "C", "text": "C₆H₅NH₂ > NH₃ > CH₃NH₂"}], "correctOption": "B", "explanation": "Gốc alkyl -CH₃ đẩy electron làm tăng mật độ điện tích trên N (tính base mạnh hơn NH₃); vòng phenyl -C₆H₅ hút electron làm giảm mật độ trên N (tính base yếu hơn NH₃).", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-amino-acids-q1", "prompt": "Amino acid đơn giản nhất có tên gọi là glycine có công thức cấu tạo là:", "options": [{"id": "A", "text": "H₂N-CH₂-CH₂-COOH"}, {"id": "B", "text": "H₂N-CH₂-COOH"}, {"id": "C", "text": "CH₃-CH(NH₂)-COOH"}], "correctOption": "B", "explanation": "Glycine (acid aminoacetic) có phân tử khối bằng 75, công thức H₂N-CH₂-COOH.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-amino-acids-q2", "prompt": "Ở trạng thái tinh thể và trong dung dịch nước, phân tử amino acid tồn tại chủ yếu ở dạng cấu trúc nào?", "options": [{"id": "A", "text": "Ion lưỡng cực (muối nội phân tử H₃N⁺-CH(R)-COO⁻)"}, {"id": "B", "text": "Dạng phân tử trung hòa H₂N-CH(R)-COOH"}, {"id": "C", "text": "Dạng cation mang điện tích dương hoàn toàn"}], "correctOption": "A", "explanation": "Nhóm -COOH có tính acid nhường H⁺ cho nhóm -NH₂ có tính base ngay trong phân tử, tạo dạng ion lưỡng cực bền vững.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-peptides-proteins-q1", "prompt": "Liên kết hóa học giữa nhóm -CO- và nhóm -NH- của hai đơn vị α-amino acid được gọi là:", "options": [{"id": "A", "text": "Liên kết peptide"}, {"id": "B", "text": "Liên kết glycosidic"}, {"id": "C", "text": "Liên kết ester"}], "correctOption": "A", "explanation": "Định nghĩa liên kết peptide là liên kết amide tạo bởi nhóm carboxyl của α-amino acid này với nhóm amino của α-amino acid kia.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-peptides-proteins-q2", "prompt": "Hợp chất nào sau đây tham gia phản ứng màu biuret với Cu(OH)₂ trong môi trường kiềm tạo dung dịch màu tím đặc trưng?", "options": [{"id": "A", "text": "Dipeptide"}, {"id": "B", "text": "Monosaccharide"}, {"id": "C", "text": "Tripeptide trở lên và protein"}], "correctOption": "C", "explanation": "Điều kiện của phản ứng màu biuret là phân tử phải có từ 2 liên kết peptide trở lên, tức từ tripeptide trở lên.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-polymer-basics-q1", "prompt": "Phản ứng kết hợp nhiều phân tử nhỏ (monomer) giống nhau hay tương tự nhau thành phân tử lớn (polymer) gọi là:", "options": [{"id": "A", "text": "Phản ứng xà phòng hóa"}, {"id": "B", "text": "Phản ứng este hóa"}, {"id": "C", "text": "Phản ứng trùng hợp"}], "correctOption": "C", "explanation": "Định nghĩa phản ứng trùng hợp là quá trình cộng hợp liên tiếp nhiều phân tử nhỏ thành phân tử có khối lượng phân tử rất lớn.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-polymer-basics-q2", "prompt": "Polyethylene (PE) là vật liệu polymer thông dụng được tổng hợp bằng phản ứng trùng hợp monomer nào?", "options": [{"id": "A", "text": "Vinyl chloride (CH₂=CH-Cl)"}, {"id": "B", "text": "Ethylene (CH₂=CH₂)"}, {"id": "C", "text": "Propylene (CH₂=CH-CH₃)"}], "correctOption": "B", "explanation": "Polyethylene được tạo ra từ phản ứng trùng hợp khí ethylene dưới áp suất và xúc tác thích hợp: n CH₂=CH₂ → (-CH₂-CH₂-)_n.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-polymer-materials-q1", "prompt": "Vật liệu polymer nào sau đây được phủ lên bề mặt chảo chống dính nhờ độ bền nhiệt cao và tính trơ hóa học tuyệt vời?", "options": [{"id": "A", "text": "Polyethylene (PE)"}, {"id": "B", "text": "Teflon (polytetrafluoroethylene)"}, {"id": "C", "text": "Polyvinyl chloride (PVC)"}], "correctOption": "B", "explanation": "Teflon (-CF₂-CF₂-)_n có liên kết C-F rất bền vững, không phản ứng với dầu mỡ ở nhiệt độ nấu nướng và có hệ số ma sát cực thấp.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-polymer-materials-q2", "prompt": "Tơ nylon-6,6 là một loại tơ tổng hợp thuộc phân loại tơ nào sau đây?", "options": [{"id": "A", "text": "Tơ polyamide"}, {"id": "B", "text": "Tơ polyester"}, {"id": "C", "text": "Tơ bán tổng hợp (tơ nhân tạo)"}], "correctOption": "A", "explanation": "Nylon-6,6 được điều chế từ hexamethylenediamine và adipic acid, chứa các liên kết amide -CO-NH- lặp lại nên là tơ polyamide.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-chemistry-12-4','Ôn tập bài 16–20','chemistry',12,'Bài 16–20','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "chemistry-12-electrode-potentials-q1", "prompt": "Trong thang đo thế điện cực chuẩn, điện cực chuẩn hydrogen được quy ước có thế điện cực ở 25 °C bằng:", "options": [{"id": "A", "text": "0,00 V"}, {"id": "B", "text": "1,00 V"}, {"id": "C", "text": "-1,00 V"}], "correctOption": "A", "explanation": "Điện cực hydro chuẩn (SHE) với H⁺ (1 M) và khí H₂ (1 bar) trên bề mặt platin được chọn làm mốc chuẩn có E° = 0,00 V.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-electrode-potentials-q2", "prompt": "Cho thế điện cực chuẩn: E°(Zn²⁺/Zn) = -0,76 V và E°(Cu²⁺/Cu) = +0,34 V. So sánh tính oxi hóa giữa hai ion kim loại:", "options": [{"id": "A", "text": "Ion Zn²⁺ có tính oxi hóa mạnh hơn ion Cu²⁺"}, {"id": "B", "text": "Hai ion có tính oxi hóa tương đương nhau"}, {"id": "C", "text": "Ion Cu²⁺ có tính oxi hóa mạnh hơn ion Zn²⁺"}], "correctOption": "C", "explanation": "Cặp có thế điện cực chuẩn lớn hơn (+0,34 V > -0,76 V) thì dạng oxi hóa (Cu²⁺) có tính oxi hóa mạnh hơn.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-galvanic-cells-q1", "prompt": "Trong pin điện hóa Zn - Cu (pin Daniell) khi hoạt động, tại cực âm (anode) xảy ra quá trình nào?", "options": [{"id": "A", "text": "Quá trình khử ion kẽm (Zn²⁺ + 2e → Zn)"}, {"id": "B", "text": "Quá trình oxi hóa ion đồng (Cu → Cu²⁺ + 2e)"}, {"id": "C", "text": "Quá trình oxi hóa kẽm (Zn → Zn²⁺ + 2e)"}], "correctOption": "C", "explanation": "Tại cực âm (anode), kẽm có tính khử mạnh hơn bị oxi hóa nhường electron đi vào mạch ngoài.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-galvanic-cells-q2", "prompt": "Cho E°(Zn²⁺/Zn) = -0,76 V và E°(Cu²⁺/Cu) = +0,34 V. Sức điện động chuẩn của pin điện hóa Zn - Cu bằng:", "options": [{"id": "A", "text": "-0,42 V"}, {"id": "B", "text": "1,10 V"}, {"id": "C", "text": "0,42 V"}], "correctOption": "B", "explanation": "E°_pin = E°_cathode - E°_anode = E°(Cu²⁺/Cu) - E°(Zn²⁺/Zn) = +0,34 - (-0,76) = +1,10 V.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-electrolysis-q1", "prompt": "Kim loại nhôm (Al) trong công nghiệp được sản xuất với quy mô lớn bằng phương pháp nào sau đây?", "options": [{"id": "A", "text": "Thủy luyện dùng sắt đẩy nhôm ra khỏi dung dịch muối AlCl₃"}, {"id": "B", "text": "Điện phân nóng chảy Al₂O₃ với sự có mặt của phụ gia cryolite (Na₃AlF₆)"}, {"id": "C", "text": "Nhiệt luyện dùng CO khử Al₂O₃ ở nhiệt độ cao"}], "correctOption": "B", "explanation": "Nhôm là kim loại có tính khử mạnh, ion Al³⁺ rất khó bị khử nên bắt buộc phải dùng phương pháp điện phân nóng chảy.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-electrolysis-q2", "prompt": "Trong quá trình điện phân dung dịch CuCl₂ bằng dòng điện một chiều với hai điện cực trơ, tại cathode (cực âm) xảy ra quá trình nào?", "options": [{"id": "A", "text": "Khử ion Cu²⁺ thành Cu kim loại (Cu²⁺ + 2e → Cu)"}, {"id": "B", "text": "Oxi hóa ion Cl⁻ thành khí Cl₂"}, {"id": "C", "text": "Oxi hóa nước giải phóng khí oxy"}], "correctOption": "A", "explanation": "Tại cathode (cực âm), cation Cu²⁺ bị hút về và nhận electron thực hiện quá trình khử tạo đồng kim loại bám lên điện cực.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-metal-corrosion-q1", "prompt": "Điều kiện để xảy ra hiện tượng ăn mòn điện hóa học kim loại bao gồm các yếu tố nào?", "options": [{"id": "A", "text": "Hai điện cực khác bản chất, tiếp xúc trực tiếp hoặc gián tiếp, và cùng tiếp xúc với dung dịch điện li"}, {"id": "B", "text": "Chỉ cần kim loại được đặt trong môi trường chân không tuyệt đối"}, {"id": "C", "text": "Chỉ xảy ra khi nối kim loại với một nguồn điện một chiều bên ngoài"}], "correctOption": "A", "explanation": "Ăn mòn điện hóa đòi hỏi 3 điều kiện: hai điện cực khác nhau, có tiếp xúc điện và cùng nhúng trong môi trường dẫn điện điện li.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-metal-corrosion-q2", "prompt": "Để bảo vệ vỏ tàu thủy bằng thép (chứa Fe) khỏi bị ăn mòn khi hoạt động trên biển, người ta thường gắn vào vỏ tàu các tấm kim loại nào?", "options": [{"id": "A", "text": "Tấm đồng (Cu)"}, {"id": "B", "text": "Tấm bạc (Ag)"}, {"id": "C", "text": "Tấm kẽm (Zn)"}], "correctOption": "C", "explanation": "Kẽm có tính khử mạnh hơn sắt (E°(Zn²⁺/Zn) = -0,76 V < -0,44 V) nên đóng vai trò là anode hi sinh, bị ăn mòn thay cho vỏ tàu thép.", "difficulty": "MEDIUM", "points": 10}, {"id": "chemistry-12-metal-properties-extraction-q1", "prompt": "Các tính chất vật lí chung của kim loại như tính dẫn điện, dẫn nhiệt, tính dẻo và ánh kim do thành phần nào trong tinh thể quyết định?", "options": [{"id": "A", "text": "Các liên kết cộng hóa trị phân cực giữa các nguyên tử"}, {"id": "B", "text": "Kích thước hạt nhân nguyên tử kim loại"}, {"id": "C", "text": "Các electron tự do di chuyển trong toàn bộ mạng tinh thể kim loại"}], "correctOption": "C", "explanation": "Mô hình biển electron tự do giải thích trọn vẹn 4 tính chất vật lí chung đặc trưng của giới kim loại.", "difficulty": "EASY", "points": 10}, {"id": "chemistry-12-metal-properties-extraction-q2", "prompt": "Phương pháp nhiệt luyện dùng khí CO hoặc H₂ để khử oxit kim loại ở nhiệt độ cao thường được áp dụng để điều chế các kim loại nào?", "options": [{"id": "A", "text": "Chỉ dùng riêng cho kim loại nhôm (Al)"}, {"id": "B", "text": "Các kim loại đứng sau nhôm trong dãy hoạt động hóa học (như Fe, Cu, Zn)"}, {"id": "C", "text": "Các kim loại kiềm và kiềm thổ (như Na, K, Ca)"}], "correctOption": "B", "explanation": "CO và H₂ chỉ có thể khử được các ion kim loại có tính oxi hóa từ kẽm (Zn) trở đi (sau Al) ở nhiệt độ cao.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-biology-12-1','Ôn tập bài 1–5','biology',12,'Bài 1–5','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "biology-12-dna-replication-q1", "prompt": "Nguyên tắc bán bảo toàn trong quá trình tái bản DNA có nghĩa là gì?", "options": [{"id": "A", "text": "Mỗi phân tử DNA con tạo ra gồm một mạch cũ của mẹ và một mạch mới tổng hợp"}, {"id": "B", "text": "Hai phân tử DNA con đều gồm toàn bộ các nucleotide hoàn toàn mới"}, {"id": "C", "text": "Toàn bộ phân tử DNA mẹ được giữ nguyên vẹn ở một tế bào con"}], "correctOption": "A", "explanation": "Bán bảo toàn nghĩa là giữ lại một nửa: mỗi phân tử DNA con chứa một mạch gốc từ phân tử mẹ và một mạch mới.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-dna-replication-q2", "prompt": "Enzyme DNA polymerase xúc tác gắn các nucleotide tự do vào đầu nào của chuỗi polynucleotide đang tổng hợp?", "options": [{"id": "A", "text": "Đầu 5''-phosphate tự do (tổng hợp theo chiều 3'' → 5'')"}, {"id": "B", "text": "Có thể gắn ngẫu nhiên vào cả hai đầu 3'' và 5'' cùng lúc"}, {"id": "C", "text": "Đầu 3''-OH tự do (tổng hợp theo chiều 5'' → 3'')"}], "correctOption": "C", "explanation": "DNA polymerase chỉ có thể gắn nucleotide vào nhóm 3''-OH tự do nên chuỗi mới luôn kéo dài theo chiều 5'' -> 3''.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-transcription-q1", "prompt": "Phân tử enzyme trực tiếp xúc tác quá trình tháo xoắn và tổng hợp mạch RNA trong phiên mã là:", "options": [{"id": "A", "text": "DNA polymerase"}, {"id": "B", "text": "Enzyme ligase nối mạch"}, {"id": "C", "text": "RNA polymerase"}], "correctOption": "C", "explanation": "RNA polymerase tự tháo xoắn DNA và liên kết các ribonucleotide tự do tương ứng với mạch khuôn DNA.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-transcription-q2", "prompt": "Mạch khuôn của gene được enzyme phiên mã sử dụng để tổng hợp phân tử mRNA có chiều:", "options": [{"id": "A", "text": "Cả hai mạch đều được dùng làm khuôn đồng thời"}, {"id": "B", "text": "Chiều 3'' → 5''"}, {"id": "C", "text": "Chiều 5'' → 3''"}], "correctOption": "B", "explanation": "Mạch khuôn của gene có chiều 3'' -> 5'' để phân tử RNA sinh ra kéo dài theo chiều 5'' -> 3''.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-translation-q1", "prompt": "Đặc điểm thoái hóa (dư thừa) của mã di truyền có nghĩa là gì?", "options": [{"id": "A", "text": "Mã di truyền bị suy giảm chất lượng qua các thế hệ tế bào"}, {"id": "B", "text": "Nhiều bộ ba codon khác nhau có thể cùng mã hóa cho một loại amino acid"}, {"id": "C", "text": "Một bộ ba codon có thể mã hóa cho nhiều loại amino acid khác nhau"}], "correctOption": "B", "explanation": "Tính thoái hóa: 61 codon chỉ mã hóa 20 loại amino acid, do đó nhiều codon cùng chỉ định một amino acid (trừ AUG và UGG).", "difficulty": "EASY", "points": 10}, {"id": "biology-12-translation-q2", "prompt": "Codon nào sau đây trên phân tử mRNA đóng vai trò là tín hiệu bắt đầu dịch mã (codon mở đầu)?", "options": [{"id": "A", "text": "5''-AUG-3''"}, {"id": "B", "text": "5''-UAA-3''"}, {"id": "C", "text": "5''-UGA-3''"}], "correctOption": "A", "explanation": "5''-AUG-3'' là codon mở đầu duy nhất trên mRNA, mã hóa Methionine ở nhân thực (hoặc fMet ở nhân sơ).", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-gene-regulation-q1", "prompt": "Trong cấu trúc của Operon Lac ở vi khuẩn E. coli, vùng vận hành (operator - O) là nơi:", "options": [{"id": "A", "text": "Protein ức chế liên kết để ngăn cản quá trình phiên mã"}, {"id": "B", "text": "Enzyme RNA polymerase bám vào để khởi động phiên mã"}, {"id": "C", "text": "Chứa mã di truyền quy định cấu trúc của enzyme phân giải đường"}], "correctOption": "A", "explanation": "Vùng vận hành O là vị trí gắn của protein ức chế; khi bị chặn, RNA polymerase không thể trượt qua phiên mã.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-gene-regulation-q2", "prompt": "Khi môi trường sống của vi khuẩn E. coli có đường lactose, sự kiện nào sau đây xảy ra?", "options": [{"id": "A", "text": "Gene điều hòa R ngừng hoàn toàn quá trình phiên mã tạo protein"}, {"id": "B", "text": "Vùng khởi động P bị phân hủy bởi các enzyme trong tế bào chất"}, {"id": "C", "text": "Phân tử lactose liên kết làm biến đổi cấu hình protein ức chế khiến nó không bám được vào vùng O"}], "correctOption": "C", "explanation": "Lactose đóng vai trò chất cảm ứng gắn vào protein ức chế làm nó mất khả năng bám vùng vận hành, mở đường cho phiên mã.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-gene-mutation-q1", "prompt": "Dạng đột biến điểm nào sau đây KHÔNG làm thay đổi số lượng liên kết hydro của gene?", "options": [{"id": "A", "text": "Đột biến thay thế cặp A-T bằng cặp G-C"}, {"id": "B", "text": "Đột biến mất một cặp A-T"}, {"id": "C", "text": "Đột biến thay thế cặp A-T bằng cặp T-A"}], "correctOption": "C", "explanation": "Cặp A-T và T-A đều có 2 liên kết hydro, nên đảo chiều thay thế A-T bằng T-A không làm thay đổi tổng số liên kết hydro.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-gene-mutation-q2", "prompt": "Đột biến gene xảy ra làm xuất hiện một bộ ba kết thúc sớm ở đoạn đầu của vùng mã hóa sẽ dẫn tới hậu quả:", "options": [{"id": "A", "text": "Hoàn toàn không ảnh hưởng gì tới hoạt tính sinh học của protein"}, {"id": "B", "text": "Quá trình dịch mã dừng sớm tạo ra chuỗi polypeptide ngắn bất thường và mất chức năng"}, {"id": "C", "text": "Làm tăng gấp đôi chiều dài của phân tử protein được tổng hợp"}], "correctOption": "B", "explanation": "Đột biến vô nghĩa (nonsense) tạo codon kết thúc sớm làm ribosome dừng dịch mã ngay, sinh ra chuỗi polypeptide cụt ngắn.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-biology-12-2','Ôn tập bài 6–10','biology',12,'Bài 6–10','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "biology-12-mendelian-genetics-q1", "prompt": "Cơ sở tế bào học trực tiếp của quy luật phân li độc lập theo quan điểm di truyền học hiện đại là:", "options": [{"id": "A", "text": "Sự nhân đôi đồng thời của các phân tử DNA ở pha S của chu kì tế bào"}, {"id": "B", "text": "Sự phân li độc lập và tổ hợp ngẫu nhiên của các cặp nhiễm sắc thể tương đồng trong giảm phân"}, {"id": "C", "text": "Sự tiếp hợp và trao đổi chéo giữa các chromatid chị em trong nguyên phân"}], "correctOption": "B", "explanation": "Các cặp gene nằm trên các cặp NST tương đồng khác nhau phân li độc lập khi các cặp NST này phân li ngẫu nhiên về hai cực tế bào ở kì sau I.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-mendelian-genetics-q2", "prompt": "Cho phép lai P: AaBb × aabb (lai phân tích hai cặp gene phân li độc lập). Tỉ lệ phân li kiểu hình ở đời con Fa là:", "options": [{"id": "A", "text": "1 : 1 : 1 : 1"}, {"id": "B", "text": "9 : 3 : 3 : 1"}, {"id": "C", "text": "3 : 3 : 1 : 1"}], "correctOption": "A", "explanation": "Cơ thể AaBb cho 4 loại giao tử với tỉ lệ 1/4 AB : 1/4 Ab : 1/4 aB : 1/4 ab; cơ thể aabb cho 1 loại giao tử ab. Con lai phân tích có tỉ lệ kiểu hình 1:1:1:1.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-linkage-crossing-over-q1", "prompt": "Hiện tượng hoán vị gene xảy ra do cơ chế tiếp hợp và trao đổi chéo giữa các đoạn chromatid ở kì nào của quá trình phân bào?", "options": [{"id": "A", "text": "Kì đầu của giảm phân I"}, {"id": "B", "text": "Kì giữa của giảm phân II"}, {"id": "C", "text": "Kì sau của nguyên phân"}], "correctOption": "A", "explanation": "Sự tiếp hợp và trao đổi chéo giữa các chromatid khác nguồn gốc của cặp NST tương đồng xảy ra ở kì đầu I của giảm phân.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-linkage-crossing-over-q2", "prompt": "Tần số hoán vị gene giữa hai locus gene trên cùng một nhiễm sắc thể:", "options": [{"id": "A", "text": "Luôn bằng đúng 100% ở mọi loài sinh vật"}, {"id": "B", "text": "Luôn lớn hơn 75% đối với các gene liên kết xa nhau"}, {"id": "C", "text": "Không bao giờ vượt quá 50%"}], "correctOption": "C", "explanation": "Trao đổi chéo chỉ xảy ra giữa 2 trong 4 chromatid của thể tứ tử, tối đa 50% số giao tử tạo ra là giao tử hoán vị (f ≤ 50%).", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-sex-linked-inheritance-q1", "prompt": "Đặc điểm nổi bật của quy luật di truyền các tính trạng do gene lặn nằm trên vùng không tương đồng của nhiễm sắc thể X quy định ở người là:", "options": [{"id": "A", "text": "Chỉ truyền trực tiếp từ bố cho con trai"}, {"id": "B", "text": "Biểu hiện đồng đều 100% ở tất cả các thế hệ con cháu"}, {"id": "C", "text": "Di truyền chéo và bệnh thường biểu hiện ở nam giới với tần suất cao hơn nữ giới"}], "correctOption": "C", "explanation": "Nam giới chỉ có 1 NST X (XY) nên chỉ cần mang 1 allele lặn là biểu hiện bệnh; tính trạng truyền chéo từ mẹ sang con trai.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-sex-linked-inheritance-q2", "prompt": "Ở người, bệnh máu khó đông do allele lặn h nằm trên vùng không tương đồng của NST X quy định (Xʰ), allele H quy định máu đông bình thường. Bố bình thường kết hôn với mẹ mang gene bệnh dị hợp (XᴴXʰ). Xác suất họ sinh con trai bị bệnh là:", "options": [{"id": "A", "text": "0% vì bố có kiểu gene bình thường"}, {"id": "B", "text": "25% (hay 1/2 số con trai)"}, {"id": "C", "text": "50% tổng số con"}], "correctOption": "B", "explanation": "Sơ đồ lai: XᴴY × XᴴXʰ → 1/4 XᴴXᴴ : 1/4 XᴴXʰ : 1/4 XᴴY : 1/4 XʰY. Xác suất sinh con trai bị bệnh (XʰY) trong tổng số con là 1/4 = 25%.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-chromosomal-mutation-q1", "prompt": "Dạng đột biến cấu trúc nhiễm sắc thể nào sau đây làm giảm số lượng gene trên một nhiễm sắc thể và thường gây hại nhiều nhất cho sinh vật?", "options": [{"id": "A", "text": "Đột biến đảo đoạn"}, {"id": "B", "text": "Đột biến mất đoạn"}, {"id": "C", "text": "Đột biến lặp đoạn"}], "correctOption": "B", "explanation": "Mất đoạn làm mất vật chất di truyền mang gene, phá vỡ cân bằng gene trong hệ gen nên thường gây chết hoặc giảm sức sống nghiêm trọng.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-chromosomal-mutation-q2", "prompt": "Người mắc hội chứng Down có bộ nhiễm sắc thể thuộc dạng đột biến số lượng nào sau đây?", "options": [{"id": "A", "text": "Thể ba nhiễm (2n + 1) ở cặp nhiễm sắc thể số 21"}, {"id": "B", "text": "Thể một nhiễm (2n - 1) ở cặp nhiễm sắc thể giới tính"}, {"id": "C", "text": "Thể tam bội (3n) toàn bộ bộ nhiễm sắc thể"}], "correctOption": "A", "explanation": "Hội chứng Down xuất hiện do có 3 nhiễm sắc thể ở cặp số 21 (thể ba 2n+1 = 47 chiếc).", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-human-genetics-q1", "prompt": "Phương pháp nghiên cứu phả hệ ở người có mục đích chính là:", "options": [{"id": "A", "text": "Theo dõi sự di truyền của một tính trạng qua nhiều thế hệ để xác định quy luật di truyền của tính trạng đó"}, {"id": "B", "text": "Gây đột biến nhân tạo bằng tia phóng xạ để quan sát kiểu hình người"}, {"id": "C", "text": "Lai phân tích người với các loài linh trưởng khác để xác định kiểu gene"}], "correctOption": "A", "explanation": "Do không thể thực hiện các phép lai thực nghiệm ở người, phả hệ ghi nhận lịch sử gia đình qua các thế hệ để suy luận quy luật di truyền.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-human-genetics-q2", "prompt": "Kĩ thuật chọc dò dịch ối hoặc sinh thiết gai nhau ở phụ nữ mang thai nhằm mục đích:", "options": [{"id": "A", "text": "Bơm thêm chất dinh dưỡng trực tiếp vào dạ dày của thai nhi"}, {"id": "B", "text": "Tiêu diệt các vi khuẩn có hại bám trên thành tử cung"}, {"id": "C", "text": "Lấy tế bào thai nhi để phân tích nhiễm sắc thể và phát hiện sớm các dị tật di truyền"}], "correctOption": "C", "explanation": "Tế bào bong từ thai trong dịch ối cho phép lập karyotype để chẩn đoán thể tam nhiễm hoặc giải trình tự gene phát hiện bệnh lý trước sinh.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-biology-12-3','Ôn tập bài 11–15','biology',12,'Bài 11–15','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "biology-12-evolution-evidence-q1", "prompt": "Cánh dơi và tay người có cùng cấu trúc giải phẫu xương nhưng đảm nhiệm các chức năng khác nhau là ví dụ về:", "options": [{"id": "A", "text": "Cơ quan tương tự"}, {"id": "B", "text": "Cơ quan thoái hóa"}, {"id": "C", "text": "Cơ quan tương đồng"}], "correctOption": "C", "explanation": "Cơ quan tương đồng bắt nguồn từ cùng một nguồn gốc phôi thai ở tổ tiên chung nhưng biến đổi thích nghi với các chức năng khác nhau.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-evolution-evidence-q2", "prompt": "Bằng chứng tiến hóa nào sau đây được coi là bằng chứng trực tiếp và xác thực nhất về lịch sử phát triển của sinh giới?", "options": [{"id": "A", "text": "Cơ quan thoái hóa ruột thừa ở người"}, {"id": "B", "text": "Hóa thạch các sinh vật cổ xưa còn lưu lại trong các tầng địa chất"}, {"id": "C", "text": "Sự tương đồng về cấu trúc protein cytochrom c"}], "correctOption": "B", "explanation": "Hóa thạch là di tích thực tế của sinh vật cổ sinh được bảo tồn trong đá, là bằng chứng trực tiếp duy nhất về niên đại và hình dạng sinh vật cổ.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-modern-evolution-synthesis-q1", "prompt": "Theo thuyết tiến hóa tổng hợp hiện đại, đơn vị tiến hóa cơ sở nhỏ nhất có thể biến đổi tần số allele qua thời gian là:", "options": [{"id": "A", "text": "Toàn bộ loài sinh vật trên Trái Đất"}, {"id": "B", "text": "Quần thể"}, {"id": "C", "text": "Cá thể sinh vật đơn lẻ"}], "correctOption": "B", "explanation": "Cá thể không tiến hóa vì hệ gene không đổi; quần thể với vốn gene biến đổi qua các thế hệ giao phối mới là đơn vị tiến hóa cơ sở.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-modern-evolution-synthesis-q2", "prompt": "Nhân tố tiến hóa nào sau đây có vai trò định hướng quá trình tiến hóa bằng cách quy định chiều hướng và tốc độ biến đổi tần số allele?", "options": [{"id": "A", "text": "Chọn lọc tự nhiên"}, {"id": "B", "text": "Đột biến gene ngẫu nhiên"}, {"id": "C", "text": "Giao phối không ngẫu nhiên"}], "correctOption": "A", "explanation": "Chỉ có chọn lọc tự nhiên giữ lại các kiểu hình thích nghi và đào thải kiểu hình có hại, do đó có vai trò định hướng tiến hóa.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-natural-selection-q1", "prompt": "Chọn lọc tự nhiên tác động trực tiếp lên cấp độ nào của sinh vật trong tự nhiên?", "options": [{"id": "A", "text": "Cấp độ kiểu hình của từng cá thể sinh vật"}, {"id": "B", "text": "Trực tiếp lên từng nucleotide của phân tử DNA trong nhân"}, {"id": "C", "text": "Chỉ tác động lên các tế bào sinh dục đơn lẻ"}], "correctOption": "A", "explanation": "Ngoại cảnh tương tác trực tiếp với kiểu hình (hình thái, sinh lí); các kiểu hình thích nghi sống sót sẽ truyền kiểu gene cho thế hệ sau.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-natural-selection-q2", "prompt": "Hiện tượng vi khuẩn kháng thuốc kháng sinh phát triển nhanh chóng sau một thời gian dài sử dụng thuốc trong y tế được giải thích bằng:", "options": [{"id": "A", "text": "Thuốc kháng sinh trực tiếp kích thích vi khuẩn tự tạo ra các gene kháng thuốc mới"}, {"id": "B", "text": "Vi khuẩn học tập được cách phân hủy thuốc kháng sinh để lấy năng lượng"}, {"id": "C", "text": "Thuốc kháng sinh đóng vai trò nhân tố chọn lọc, giữ lại và nhân lên các vi khuẩn mang đột biến kháng thuốc"}], "correctOption": "C", "explanation": "Đột biến kháng thuốc có sẵn ngẫu nhiên trong quần thể vi khuẩn; thuốc kháng sinh diệt vi khuẩn mẫn cảm, tạo ưu thế cho chủng kháng sinh sản nhanh.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-speciation-q1", "prompt": "Tiêu chuẩn cơ bản và quan trọng nhất để phân biệt hai loài sinh sản hữu tính thân thuộc trong tự nhiên là:", "options": [{"id": "A", "text": "Tiêu chuẩn hình thái học bên ngoài"}, {"id": "B", "text": "Tiêu chuẩn màu sắc nơi cư trú"}, {"id": "C", "text": "Tiêu chuẩn cách li sinh sản"}], "correctOption": "C", "explanation": "Khái niệm loài sinh học dựa trên sự cách li sinh sản: nếu hai quần thể không giao phối hoặc con lai bất thụ thì chúng thuộc hai loài khác nhau.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-speciation-q2", "prompt": "Ngựa (2n = 64) lai với lừa (2n = 62) sinh ra con la (2n = 63) hoàn toàn bất thụ. Đây là ví dụ về cơ chế cách li sinh sản nào?", "options": [{"id": "A", "text": "Cách li sinh thái do không gặp nhau"}, {"id": "B", "text": "Cách li sau hợp tử (bất thụ con lai)"}, {"id": "C", "text": "Cách li trước hợp tử về mặt cơ học"}], "correctOption": "B", "explanation": "Con la hình thành từ thụ tinh nhưng bộ NST cọc cạch không giảm phân được, con lai bất thụ thuộc cơ chế cách li sau hợp tử.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-origin-of-life-q1", "prompt": "Thí nghiệm nổi tiếng năm 1953 của Stanley Miller và Harold Urey đã chứng minh điều gì về nguồn gốc sự sống?", "options": [{"id": "A", "text": "Phân tử DNA là dạng vật chất di truyền đầu tiên xuất hiện trên Trái Đất"}, {"id": "B", "text": "Các hợp chất hữu cơ đơn giản có thể được hình thành từ các chất vô cơ trong điều kiện khí quyển nguyên thủy"}, {"id": "C", "text": "Tế bào sống nguyên thủy có thể tự lắp ráp hoàn chỉnh chỉ trong 24 giờ"}], "correctOption": "B", "explanation": "Thí nghiệm mô phỏng phóng điện qua khí quyển nguyên thủy khử tạo ra các amino acid, chứng minh bước tiến hóa hóa học là hoàn toàn khả thi.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-origin-of-life-q2", "prompt": "Đại địa chất nào sau đây được gọi là ''Kỉ nguyên của các loài bò sát'' và chứng kiến sự thống trị của các loài khủng long?", "options": [{"id": "A", "text": "Đại Trung sinh (Mesozoic)"}, {"id": "B", "text": "Đại Cổ sinh (Paleozoic)"}, {"id": "C", "text": "Đại Tân sinh (Cenozoic)"}], "correctOption": "A", "explanation": "Đại Trung sinh gồm kỉ Trias, Jura và Creta là thời kì bò sát khổng lồ (khủng long) phát triển cực thịnh và tuyệt diệt vào cuối kỉ Creta.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-biology-12-4','Ôn tập bài 16–20','biology',12,'Bài 16–20','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "biology-12-ecological-factors-q1", "prompt": "Giới hạn sinh thái của một loài đối với một nhân tố sinh thái nhất định được định nghĩa là:", "options": [{"id": "A", "text": "Khoảng giá trị xác định của nhân tố sinh thái mà trong đó sinh vật có thể tồn tại và phát triển ổn định"}, {"id": "B", "text": "Điểm nhiệt độ cao nhất mà sinh vật bắt đầu bị chết"}, {"id": "C", "text": "Toàn bộ các nhân tố môi trường tác động đồng thời lên sinh vật"}], "correctOption": "A", "explanation": "Giới hạn sinh thái là giới hạn chịu đựng của loài đối với một nhân tố sinh thái (giữa giới hạn dưới và giới hạn trên).", "difficulty": "EASY", "points": 10}, {"id": "biology-12-ecological-factors-q2", "prompt": "Nhóm nhân tố sinh thái nào sau đây thuộc nhóm nhân tố sinh thái hữu sinh?", "options": [{"id": "A", "text": "Độ pH và lượng oxy hòa tan trong nước ao"}, {"id": "B", "text": "Ánh sáng mặt trời và nhiệt độ không khí"}, {"id": "C", "text": "Mối quan hệ cạnh tranh thức ăn giữa các loài động vật trong rừng"}], "correctOption": "C", "explanation": "Nhân tố hữu sinh là thế giới sống xung quanh sinh vật bao gồm các sinh vật khác và mối quan hệ giữa chúng, cũng như con người.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-population-ecology-q1", "prompt": "Đặc trưng cơ bản quan trọng nhất ảnh hưởng trực tiếp đến mức độ sử dụng nguồn sống và khả năng sinh sản của quần thể là:", "options": [{"id": "A", "text": "Tỉ lệ giới tính ở nhóm tuổi già"}, {"id": "B", "text": "Màu sắc bộ lông của các cá thể non"}, {"id": "C", "text": "Mật độ cá thể trong quần thể"}], "correctOption": "C", "explanation": "Mật độ (số cá thể trên đơn vị diện tích/thể tích) quyết định mức độ cạnh tranh, khả năng tìm kiếm thức ăn và bạn tình.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-population-ecology-q2", "prompt": "Trong điều kiện môi trường sống bị giới hạn về không gian và nguồn thức ăn, đường cong tăng trưởng số lượng của quần thể sinh vật trong tự nhiên có dạng hình chữ gì?", "options": [{"id": "A", "text": "Đường thẳng nằm ngang không đổi"}, {"id": "B", "text": "Hình chữ S (tăng trưởng logistic tiệm cận sức chứa K)"}, {"id": "C", "text": "Hình chữ J tăng trưởng theo hàm mũ vô hạn"}], "correctOption": "B", "explanation": "Nguồn sống giới hạn làm mức sinh giảm và mức tử tăng khi kích thước quần thể tiến tới sức chứa tối đa K của môi trường, tạo đường cong chữ S.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-community-ecology-q1", "prompt": "Mối quan hệ sinh thái chặt chẽ giữa hai loài sinh vật trong đó cả hai bên cùng có lợi và không thể tách rời nhau gọi là:", "options": [{"id": "A", "text": "Quan hệ kí sinh (parasitism)"}, {"id": "B", "text": "Quan hệ cộng sinh (mutualism)"}, {"id": "C", "text": "Quan hệ hội sinh (commensalism)"}], "correctOption": "B", "explanation": "Cộng sinh là quan hệ bắt buộc giữa hai loài, cả hai đều có lợi và sống phụ thuộc vào nhau (như nấm và vi khuẩn lam trong địa y).", "difficulty": "EASY", "points": 10}, {"id": "biology-12-community-ecology-q2", "prompt": "Hiện tượng diễn thế sinh thái khởi đầu từ một môi trường trống trơn (như đảo tro tàn núi lửa mới hình thành) gọi là:", "options": [{"id": "A", "text": "Diễn thế nguyên sinh"}, {"id": "B", "text": "Diễn thế thứ sinh"}, {"id": "C", "text": "Diễn thế thoái hóa"}], "correctOption": "A", "explanation": "Diễn thế nguyên sinh bắt đầu từ môi trường chưa từng có quần xã sinh vật nào sinh sống trước đó.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-ecosystem-matter-energy-q1", "prompt": "Trong cấu trúc thành phần sinh học của một hệ sinh thái, sinh vật nào sau đây đóng vai trò là sinh vật sản xuất sơ cấp?", "options": [{"id": "A", "text": "Cây xanh và vi khuẩn lam quang hợp"}, {"id": "B", "text": "Động vật ăn cỏ như trâu bò"}, {"id": "C", "text": "Nấm mốc và vi khuẩn hoại sinh trong đất"}], "correctOption": "A", "explanation": "Sinh vật sản xuất sơ cấp tự tổng hợp chất hữu cơ từ năng lượng ánh sáng mặt trời hoặc năng lượng hóa học.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-ecosystem-matter-energy-q2", "prompt": "Dòng năng lượng trong một hệ sinh thái tự nhiên có đặc điểm căn bản nào sau đây?", "options": [{"id": "A", "text": "Luôn tuần hoàn khép kín 100% quay trở lại sinh vật sản xuất"}, {"id": "B", "text": "Càng lên bậc dinh dưỡng cao năng lượng tích lũy càng tăng vọt"}, {"id": "C", "text": "Di chuyển theo một chiều qua các bậc dinh dưỡng và tiêu hao dần dưới dạng nhiệt"}], "correctOption": "C", "explanation": "Năng lượng đi vào hệ sinh thái một chiều và tỏa nhiệt qua hô hấp, bài tiết ở từng bậc dinh dưỡng chứ không tuần hoàn.", "difficulty": "MEDIUM", "points": 10}, {"id": "biology-12-biosphere-conservation-q1", "prompt": "Nhóm vi sinh vật nào có khả năng biến đổi khí nitrogen tự do (N2) trong khí quyển thành dạng ion ammonium (NH4+) cây có thể hấp thụ được?", "options": [{"id": "A", "text": "Vi khuẩn phản nitrat hóa phân giải đạm"}, {"id": "B", "text": "Các loại nấm men làm bánh mì"}, {"id": "C", "text": "Vi khuẩn cố định đạm (như Rhizobium sống cộng sinh trong nốt sần cây họ Đậu)"}], "correctOption": "C", "explanation": "Nhờ enzyme nitrogenase, vi khuẩn cố định đạm phá vỡ liên kết ba N≡N để cố định nitrogen thành dạng hợp chất hữu dụng cho thực vật.", "difficulty": "EASY", "points": 10}, {"id": "biology-12-biosphere-conservation-q2", "prompt": "Biện pháp bảo tồn đa dạng sinh học nào sau đây là hình thức bảo tồn tại chỗ (in-situ conservation)?", "options": [{"id": "A", "text": "Chuyển các loài động vật quý hiếm vào nuôi nhốt trong vườn bách thú"}, {"id": "B", "text": "Thành lập các vườn quốc gia và khu dự trữ sinh quyển thiên nhiên"}, {"id": "C", "text": "Thu thập hạt giống đưa vào bảo quản đông lạnh trong ngân hàng gene"}], "correctOption": "B", "explanation": "Bảo tồn tại chỗ bảo vệ loài sinh vật ngay tại môi trường sống tự nhiên vốn có của chúng trong các vườn quốc gia, khu bảo tồn.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-literature-12-1','Ôn tập bài 1–5','literature',12,'Bài 1–5','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "literature-12-narrative-voice-q1", "prompt": "Người kể chuyện toàn tri trong tác phẩm tự sự là người kể chuyện:", "options": [{"id": "A", "text": "Biết hết mọi hành động, suy nghĩ và quá khứ của tất cả các nhân vật"}, {"id": "B", "text": "Chỉ biết những gì nhân vật chính tận mắt chứng kiến"}, {"id": "C", "text": "Luôn xuất hiện trực tiếp dưới danh xưng tôi"}], "correctOption": "A", "explanation": "Người kể toàn tri (omniscient) đứng ngoài câu chuyện nhưng thấu suốt toàn bộ thế giới nội tâm và hành động của mọi nhân vật.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-narrative-voice-q2", "prompt": "Việc chuyển đổi linh hoạt giữa điểm nhìn bên ngoài và điểm nhìn bên trong trong truyện ngắn hiện đại có tác dụng:", "options": [{"id": "A", "text": "Làm người đọc hoàn toàn không hiểu được diễn biến cốt truyện"}, {"id": "B", "text": "Rút ngắn tối đa dung lượng của văn bản"}, {"id": "C", "text": "Khám phá chiều sâu tâm lí phức tạp và tạo tính đa thanh cho tác phẩm"}], "correctOption": "C", "explanation": "Dịch chuyển điểm nhìn giúp soi chiếu nhân vật từ nhiều góc độ, làm hiện rõ những xung đột tinh tế trong tâm thức.", "difficulty": "MEDIUM", "points": 10}, {"id": "literature-12-modern-poetry-q1", "prompt": "Đặc điểm nổi bật về hình thức tổ chức nhịp điệu của thơ hiện đại so với thơ ca cổ điển là:", "options": [{"id": "A", "text": "Luôn bắt buộc tuân thủ nghiêm ngặt luật bằng trắc và niêm luật cổ"}, {"id": "B", "text": "Hoàn toàn không bao giờ sử dụng vần điệu"}, {"id": "C", "text": "Nhịp điệu linh hoạt, phóng khoáng, biến đổi theo mạch vận động của cảm xúc"}], "correctOption": "C", "explanation": "Thơ hiện đại phá vỡ khuôn khổ niêm luật cứng nhắc để nhịp điệu tuôn chảy tự nhiên theo xung lực cảm xúc của cái tôi trữ tình.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-modern-poetry-q2", "prompt": "Yếu tố nào đóng vai trò là ''linh hồn'' định hình toàn bộ cấu tứ và hệ thống hình ảnh trong một bài thơ trữ tình?", "options": [{"id": "A", "text": "Tên gọi địa danh xuất hiện trong bài thơ"}, {"id": "B", "text": "Mạch cảm xúc và tư tưởng của chủ thể trữ tình"}, {"id": "C", "text": "Số lượng từ ngữ và số câu thơ trong một khổ"}], "correctOption": "B", "explanation": "Cảm xúc chân thực, mãnh liệt của chủ thể trữ tình là hạt nhân liên kết và chi phối việc lựa chọn hình ảnh, ngôn từ, nhạc điệu.", "difficulty": "MEDIUM", "points": 10}, {"id": "literature-12-dramatic-conflict-q1", "prompt": "Yếu tố then chốt tạo nên sức hấp dẫn và thúc đẩy toàn bộ cốt truyện kịch phát triển là:", "options": [{"id": "A", "text": "Lời bình luận của người dẫn chuyện gián tiếp"}, {"id": "B", "text": "Xung đột kịch"}, {"id": "C", "text": "Miêu tả cảnh thiên nhiên dài dòng"}], "correctOption": "B", "explanation": "Không có xung đột thì không có kịch; xung đột giữa các tính cách, quyền lợi, quan điểm là động lực của hành động kịch.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-dramatic-conflict-q2", "prompt": "Độc thoại nội tâm của nhân vật trong kịch có chức năng nghệ thuật chính là:", "options": [{"id": "A", "text": "Bộc lộ trực tiếp những giằng xé, toan tính và thế giới tinh thần sâu kín của nhân vật"}, {"id": "B", "text": "Trao đổi thông tin hàng ngày với các nhân vật khác trên sân khấu"}, {"id": "C", "text": "Hướng dẫn diễn viên phụ cách di chuyển đạo cụ sân khấu"}], "correctOption": "A", "explanation": "Độc thoại nội tâm là tiếng nói cất lên từ đáy lòng nhân vật khi đối diện với chính mình, phơi bày những trăn trở dằn vặt sâu kín.", "difficulty": "MEDIUM", "points": 10}, {"id": "literature-12-rhetorical-devices-q1", "prompt": "Biện pháp tu từ nghịch ngữ (nghịch lí - paradox) có đặc điểm nổi bật nào sau đây?", "options": [{"id": "A", "text": "Kết hợp những từ ngữ tưởng như mâu thuẫn đối lập nhưng lại diễn tả một chân lí sâu xa"}, {"id": "B", "text": "Liệt kê các sự vật đồng nghĩa liên tiếp nhau"}, {"id": "C", "text": "Nói quá sự thật gấp hàng nghìn lần để gây cười"}], "correctOption": "A", "explanation": "Nghịch ngữ tạo ra sự bất ngờ bằng cách ghép hai yếu tố tương phản, buộc người đọc suy ngẫm để nhận ra bản chất sâu kín.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-rhetorical-devices-q2", "prompt": "Cụm từ ''ánh nắng ngọt ngào rơi trên mái hiên'' sử dụng biện pháp tu từ nào sau đây?", "options": [{"id": "A", "text": "So sánh ngang bằng có từ như"}, {"id": "B", "text": "Nhân hóa đồ vật thành người"}, {"id": "C", "text": "Ẩn dụ chuyển đổi cảm giác (thị giác sang vị giác)"}], "correctOption": "C", "explanation": "Ánh nắng vốn cảm nhận bằng thị giác được miêu tả bằng tính từ ''ngọt ngào'' thuộc vị giác, tạo ấn tượng tinh tế.", "difficulty": "MEDIUM", "points": 10}, {"id": "literature-12-literary-critique-q1", "prompt": "Quá trình tiếp nhận văn học của bạn đọc được coi là một hoạt động:", "options": [{"id": "A", "text": "Tiếp thu thụ động y nguyên những gì tác giả viết mà không cần suy nghĩ"}, {"id": "B", "text": "Sao chép lại toàn bộ văn bản để lưu trữ cá nhân"}, {"id": "C", "text": "Đồng sáng tạo tích cực, làm sống dậy và làm phong phú thêm ý nghĩa của tác phẩm"}], "correctOption": "C", "explanation": "Người đọc mang vốn sống, trải nghiệm và cảm nhận riêng để lấp đầy các ''khoảng trống'' nghệ thuật, tạo nên đời sống sinh động cho tác phẩm.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-literary-critique-q2", "prompt": "Khi đánh giá giá trị tư tưởng của một tác phẩm văn học, người đọc cần đặt tác phẩm vào:", "options": [{"id": "A", "text": "Số lượng bản in bán ra tại các hiệu sách"}, {"id": "B", "text": "Bối cảnh lịch sử, xã hội và văn hóa cụ thể của thời đại mà tác phẩm ra đời"}, {"id": "C", "text": "Chỉ dựa vào sở thích nhất thời của cá nhân người đọc"}], "correctOption": "B", "explanation": "Đặt tác phẩm vào hoàn cảnh lịch sử giúp đánh giá đúng tính tiên phong, giá trị hiện thực và chiều sâu nhân đạo của tác giả.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-literature-12-2','Ôn tập bài 6–10','literature',12,'Bài 6–10','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "literature-12-argument-structure-q1", "prompt": "Trong cấu trúc của một văn bản nghị luận, ''luận điểm'' đóng vai trò là:", "options": [{"id": "A", "text": "Lời mở đầu giới thiệu tiểu sử tác giả"}, {"id": "B", "text": "Các ý kiến, quan điểm chính triển khai làm sáng tỏ cho luận đề của bài viết"}, {"id": "C", "text": "Các số liệu thống kê cụ thể trích dẫn từ bài báo"}], "correctOption": "B", "explanation": "Luận điểm là những phán đoán cốt lõi thể hiện quan điểm của người viết về từng khía cạnh của vấn đề nghị luận.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-argument-structure-q2", "prompt": "Yêu cầu quan trọng nhất đối với hệ thống luận cứ (lí lẽ và dẫn chứng) trong văn bản nghị luận là:", "options": [{"id": "A", "text": "Phải chân thực, tiêu biểu, xác đáng và có mối liên hệ logic chặt chẽ với luận điểm"}, {"id": "B", "text": "Càng dài dòng và nhiều chi tiết vụn vặt càng tốt"}, {"id": "C", "text": "Phải sử dụng hoàn toàn những câu chuyện hư cấu hoang đường"}], "correctOption": "A", "explanation": "Luận cứ xác thực, tiêu biểu mới đủ sức thuyết phục người đọc tin vào tính đúng đắn của luận điểm.", "difficulty": "MEDIUM", "points": 10}, {"id": "literature-12-evidence-evaluation-q1", "prompt": "Tiêu chí nào sau đây là quan trọng hàng đầu khi lựa chọn dẫn chứng cho bài văn nghị luận xã hội?", "options": [{"id": "A", "text": "Tính xác thực, khách quan và có nguồn gốc xuất xứ tin cậy"}, {"id": "B", "text": "Dẫn chứng phải hoàn toàn bí ẩn không ai kiểm chứng được"}, {"id": "C", "text": "Chỉ sử dụng những tin đồn chưa được kiểm chứng trên mạng"}], "correctOption": "A", "explanation": "Dẫn chứng khách quan, kiểm chứng được từ cơ quan chuyên môn mới tạo lập uy tín học thuật vững chắc cho bài viết.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-evidence-evaluation-q2", "prompt": "Lỗi ngụy biện ''khái quát hóa vội vã'' (hasty generalization) xảy ra khi người viết:", "options": [{"id": "A", "text": "Phân tích quá sâu nguyên nhân sâu xa của vấn đề"}, {"id": "B", "text": "Trích dẫn đầy đủ số liệu điều tra diện rộng trên hàng triệu người"}, {"id": "C", "text": "Rút ra kết luận chung cho toàn bộ tập thể chỉ dựa trên một vài trường hợp cá biệt"}], "correctOption": "C", "explanation": "Lấy một vài ví dụ cá biệt không đại diện để quy chụp cho số đông là lỗi ngụy biện khái quát hóa vội vã.", "difficulty": "MEDIUM", "points": 10}, {"id": "literature-12-persuasive-rhetoric-q1", "prompt": "Phương thức thuyết phục dựa trên uy tín, phẩm hạnh và tư cách đạo đức của người nói trong thuật hùng biện được gọi là:", "options": [{"id": "A", "text": "Pathos"}, {"id": "B", "text": "Logos"}, {"id": "C", "text": "Ethos"}], "correctOption": "C", "explanation": "Trong thuật hùng biện Aristotle: Ethos là uy tín cá nhân, Pathos là tác động cảm xúc, Logos là lập luận logic.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-persuasive-rhetoric-q2", "prompt": "Khi muốn lay động lòng trắc ẩn và sự đồng cảm sâu sắc của người nghe về một mảnh đời bất hạnh, người viết thường sử dụng phương thức:", "options": [{"id": "A", "text": "Chỉ đọc to danh mục văn bản luật pháp"}, {"id": "B", "text": "Pathos (tác động vào cảm xúc và tâm lí)"}, {"id": "C", "text": "Logos (lập luận toán học khô khan)"}], "correctOption": "B", "explanation": "Pathos hướng đến thế giới cảm xúc, chạm vào lòng nhân ái, sự sẻ chia của độc giả.", "difficulty": "MEDIUM", "points": 10}, {"id": "literature-12-social-argumentation-q1", "prompt": "Khi làm bài văn nghị luận về một vấn đề xã hội, thao tác đầu tiên sau khi giới thiệu vấn đề cần thực hiện là:", "options": [{"id": "A", "text": "Đưa ra ngay kết luận cuối cùng của bài viết"}, {"id": "B", "text": "Giải thích rõ nghĩa của các từ khóa và nội hàm cốt lõi của vấn đề"}, {"id": "C", "text": "Lập tức phê phán gay gắt những người có ý kiến trái chiều"}], "correctOption": "B", "explanation": "Giải thích khái niệm giúp xác lập định nghĩa chuẩn xác, tránh lạc đề hoặc hiểu sai lệch vấn đề trước khi bàn luận.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-social-argumentation-q2", "prompt": "Để các giải pháp đề xuất trong bài nghị luận xã hội có tính thuyết phục cao, người viết cần đảm bảo:", "options": [{"id": "A", "text": "Tính cụ thể, khả thi, phù hợp với thực tế và giải quyết trúng nguyên nhân gốc rễ"}, {"id": "B", "text": "Đưa ra những lời hứa hão huyền không ai làm được"}, {"id": "C", "text": "Chỉ yêu cầu người khác làm mà bản thân không cần thay đổi"}], "correctOption": "A", "explanation": "Giải pháp phải xuất phát từ nguyên nhân thực tế, có tính khả thi và phân định rõ trách nhiệm cá nhân, cộng đồng.", "difficulty": "MEDIUM", "points": 10}, {"id": "literature-12-literary-argumentation-q1", "prompt": "Khi viết bài văn nghị luận phân tích một tác phẩm văn học, người viết cần kết hợp chặt chẽ giữa hai yếu tố nào?", "options": [{"id": "A", "text": "Phân tích nội dung tư tưởng và các thủ pháp nghệ thuật độc đáo"}, {"id": "B", "text": "Chỉ tóm tắt cốt truyện từ đầu đến cuối như văn kể chuyện"}, {"id": "C", "text": "Sao chép lại tiểu sử năm sinh năm mất của tác giả"}], "correctOption": "A", "explanation": "Tác phẩm văn học là sự thống nhất giữa nội dung và hình thức; nghệ thuật là phương tiện chuyên chở tư tưởng tác giả.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-literary-argumentation-q2", "prompt": "Thao tác ''so sánh văn học'' trong bài văn nghị luận có tác dụng nghệ thuật chủ yếu là:", "options": [{"id": "A", "text": "Để kéo dài dung lượng bài viết khi thiếu ý tưởng"}, {"id": "B", "text": "Khẳng định tác phẩm kia hoàn toàn vô giá trị"}, {"id": "C", "text": "Làm nổi bật nét độc đáo, dấu ấn phong cách riêng biệt của tác giả đang phân tích"}], "correctOption": "C", "explanation": "So sánh với tác phẩm cùng đề tài hoặc cùng thời kì giúp nhận diện rõ nét sáng tạo độc đáo riêng của nhà văn.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-literature-12-3','Ôn tập bài 11–15','literature',12,'Bài 11–15','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "literature-12-informational-synthesis-q1", "prompt": "Trong một văn bản thông tin đa phương thức, các yếu tố phi ngôn ngữ (như biểu đồ, sơ đồ, hình ảnh) có vai trò:", "options": [{"id": "A", "text": "Chỉ để trang trí cho văn bản bớt tẻ nhạt mà không mang ý nghĩa gì"}, {"id": "B", "text": "Làm sai lệch thông tin của phần văn bản chữ viết"}, {"id": "C", "text": "Trực quan hóa dữ liệu phức tạp giúp người đọc tiếp nhận thông tin nhanh chóng và chính xác"}], "correctOption": "C", "explanation": "Yếu tố phi ngôn ngữ giúp cô đọng số liệu trực quan, tăng tính sinh động và hỗ trợ đắc lực cho văn bản thuyết minh.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-informational-synthesis-q2", "prompt": "Kĩ năng quan trọng nhất khi tổng hợp thông tin từ nhiều nguồn tài liệu khác nhau về cùng một đề tài là:", "options": [{"id": "A", "text": "Chỉ chọn nguồn tin có độ dài ngắn nhất để đọc"}, {"id": "B", "text": "So sánh, đối chiếu tính nhất quán của dữ liệu và chắt lọc các điểm đồng thuận cốt lõi"}, {"id": "C", "text": "Sao chép nguyên văn tất cả các tài liệu gom lại thành một tập dài"}], "correctOption": "B", "explanation": "Tổng hợp thông tin đòi hỏi tư duy phân tích, đối chiếu chéo để loại bỏ mâu thuẫn và xây dựng bức tranh tổng thể tin cậy.", "difficulty": "MEDIUM", "points": 10}, {"id": "literature-12-media-literacy-q1", "prompt": "Hiện tượng ''đóng khung thông điệp'' (framing) trong truyền thông đại chúng có nghĩa là:", "options": [{"id": "A", "text": "Hoàn toàn cấm đoán người dân phát biểu ý kiến cá nhân"}, {"id": "B", "text": "Cách thức cơ quan truyền thông lựa chọn nhấn mạnh một khía cạnh nhất định để định hướng cách nhìn của công chúng"}, {"id": "C", "text": "Đóng khung các bài báo in vào khung gỗ để treo tường"}], "correctOption": "B", "explanation": "Framing là kĩ thuật định hướng dư luận bằng cách làm nổi bật một góc nhìn cụ thể và làm lu mờ các góc nhìn khác.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-media-literacy-q2", "prompt": "Dấu hiệu điển hình của một tiêu đề mang tính chất ''mồi câu nhấp chuột'' (clickbait) trên mạng là:", "options": [{"id": "A", "text": "Sử dụng ngôn từ giật gân, lấp lửng, phóng đại cảm xúc để kích thích người dùng bấm vào xem"}, {"id": "B", "text": "Cung cấp đầy đủ thông tin tóm tắt khách quan ngay ở tiêu đề"}, {"id": "C", "text": "Trích dẫn chính xác báo cáo khoa học có nguồn thẩm định rõ ràng"}], "correctOption": "A", "explanation": "Clickbait dùng các từ khóa kích động cảm xúc tò mò, thường phóng đại hoặc làm sai lệch nội dung thực tế bên trong bài viết.", "difficulty": "MEDIUM", "points": 10}, {"id": "literature-12-research-report-q1", "prompt": "Phần ''Tóm tắt'' (Abstract) ở đầu một báo cáo nghiên cứu khoa học có nhiệm vụ chính là:", "options": [{"id": "A", "text": "Tóm lược cô đọng mục tiêu, phương pháp, kết quả then chốt và kết luận của công trình"}, {"id": "B", "text": "Liệt kê danh sách tất cả các thành viên trong gia đình tác giả"}, {"id": "C", "text": "Trình bày chi tiết toàn bộ các bảng số liệu thô thu thập được"}], "correctOption": "A", "explanation": "Abstract giúp người đọc nhanh chóng nắm bắt bản chất và những phát hiện quan trọng nhất của công trình nghiên cứu.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-research-report-q2", "prompt": "Hành vi nào sau đây bị coi là ''đạo văn'' (plagiarism) nghiêm trọng trong nghiên cứu học thuật?", "options": [{"id": "A", "text": "Trích dẫn nguyên văn câu nói của tác giả và đặt trong dấu ngoặc kép kèm ghi chú nguồn"}, {"id": "B", "text": "Diễn đạt lại ý kiến của chuyên gia và chú thích rõ tài liệu tham khảo"}, {"id": "C", "text": "Sử dụng ý tưởng hoặc câu chữ của người khác mà không dẫn nguồn và trích dẫn rõ ràng"}], "correctOption": "C", "explanation": "Đạo văn là hành vi chiếm đoạt sản phẩm trí tuệ khi sử dụng tư liệu của người khác như thể là của chính mình.", "difficulty": "MEDIUM", "points": 10}, {"id": "literature-12-formal-speech-q1", "prompt": "Kĩ thuật ''câu móc'' (hook) trong phần mở đầu của một bài thuyết trình được dùng để:", "options": [{"id": "A", "text": "Đọc nhanh danh sách tất cả các tài liệu tham khảo của bài"}, {"id": "B", "text": "Xin lỗi khán giả vì chưa chuẩn bị bài kĩ càng"}, {"id": "C", "text": "Thu hút sự chú ý và khơi gợi trí tò mò của khán giả ngay từ những giây đầu tiên"}], "correctOption": "C", "explanation": "Hook (câu hỏi thú vị, số liệu gây sốc, câu chuyện ngắn) kết nối người nghe với chủ đề ngay từ lúc mở màn.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-formal-speech-q2", "prompt": "Khi thiết kế slide trình chiếu hỗ trợ bài thuyết trình, nguyên tắc quan trọng về mặt thị giác là:", "options": [{"id": "A", "text": "Dùng thật nhiều phông chữ sặc sỡ và hiệu ứng hoạt họa nhấp nháy liên tục"}, {"id": "B", "text": "Trình bày cô đọng, ưu tiên hình ảnh biểu đồ trực quan và hạn chế tối đa các đoạn văn bản dài"}, {"id": "C", "text": "Chép toàn bộ nguyên văn bài nói lên màn hình để đọc lại từng chữ"}], "correctOption": "B", "explanation": "Slide chỉ mang tính trực quan hỗ trợ; văn bản quá nhiều sẽ làm khán giả mải đọc chữ và phân tâm khỏi lời nói của diễn giả.", "difficulty": "MEDIUM", "points": 10}, {"id": "literature-12-debate-skills-q1", "prompt": "Trong mô hình tranh biện học thuật tiêu chuẩn, một lập luận hoàn chỉnh bao gồm các thành tố cốt lõi nào?", "options": [{"id": "A", "text": "Những lời công kích đời tư nhằm làm đối phương mất bình tĩnh"}, {"id": "B", "text": "Luận điểm khẳng định, lí lẽ giải thích và dẫn chứng thực tế minh chứng"}, {"id": "C", "text": "Chỉ gồm một lời khẳng định to tiếng và áp đặt"}], "correctOption": "B", "explanation": "Mô hình ARE (Assertion, Reasoning, Evidence) là tiêu chuẩn vàng cho một luận cứ tranh biện logic và thuyết phục.", "difficulty": "EASY", "points": 10}, {"id": "literature-12-debate-skills-q2", "prompt": "Thao tác phản biện hiệu quả nhất khi đối thoại tranh luận với ý kiến trái chiều là:", "options": [{"id": "A", "text": "Tập trung phân tích lỗ hổng logic hoặc tính thiếu căn cứ của dẫn chứng mà đối phương đưa ra"}, {"id": "B", "text": "Ngắt lời đối phương liên tục không cho họ phát biểu"}, {"id": "C", "text": "Lặp đi lặp lại ý kiến của mình với giọng điệu to hơn"}], "correctOption": "A", "explanation": "Phản biện sắc bén nhắm thẳng vào giả định sai lầm, sự thiếu hụt bằng chứng hoặc nghịch lí logic trong lập luận của đối thủ.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-english-12-1','Ôn tập bài 1–5','english',12,'Bài 1–5','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "english-12-sustainable-future-q1", "prompt": "Which word best describes materials that can break down naturally without harming the environment?", "options": [{"id": "A", "text": "Biodegradable"}, {"id": "B", "text": "Non-recyclable"}, {"id": "C", "text": "Indestructible"}], "correctOption": "A", "explanation": "''Biodegradable'' refers to substances capable of being decomposed by bacteria or other biological agents.", "difficulty": "EASY", "points": 10}, {"id": "english-12-sustainable-future-q2", "prompt": "Rewrite for emphasis using a cleft sentence: ''Plastic bags pollute our rivers.''", "options": [{"id": "A", "text": "Plastic bags are what they pollute our rivers."}, {"id": "B", "text": "There is plastic bags polluting our rivers."}, {"id": "C", "text": "It is plastic bags that pollute our rivers."}], "correctOption": "C", "explanation": "The cleft sentence structure ''It is/was + emphasized element + that/who + clause'' is used to focus attention on ''plastic bags''.", "difficulty": "MEDIUM", "points": 10}, {"id": "english-12-climate-action-q1", "prompt": "What term refers to the rich variety of animal and plant life in a specific habitat or on Earth?", "options": [{"id": "A", "text": "Deforestation"}, {"id": "B", "text": "Urbanisation"}, {"id": "C", "text": "Biodiversity"}], "correctOption": "C", "explanation": "''Biodiversity'' is the variety of plant and animal life in a particular habitat or in the world as a whole.", "difficulty": "EASY", "points": 10}, {"id": "english-12-climate-action-q2", "prompt": "Choose the correct passive modal form: ''Strict environmental policies _______ immediately to curb industrial emissions.''", "options": [{"id": "A", "text": "must have implemented"}, {"id": "B", "text": "must be implemented"}, {"id": "C", "text": "must implement"}], "correctOption": "B", "explanation": "Passive with modal verb: modal + be + past participle (''must be implemented'').", "difficulty": "MEDIUM", "points": 10}, {"id": "english-12-urbanisation-q1", "prompt": "Which noun refers to the basic physical systems and structures of a city, such as roads, water supplies, and electricity grids?", "options": [{"id": "A", "text": "Ruralization"}, {"id": "B", "text": "Infrastructure"}, {"id": "C", "text": "Congestion"}], "correctOption": "B", "explanation": "''Infrastructure'' encompasses the fundamental facilities and systems serving a country, city, or area.", "difficulty": "EASY", "points": 10}, {"id": "english-12-urbanisation-q2", "prompt": "Choose the participle clause that correctly replaces ''Because city planners realized the lack of green spaces, they created more public parks.'':", "options": [{"id": "A", "text": "Realizing the lack of green spaces, city planners created more public parks."}, {"id": "B", "text": "To realize the lack of green spaces, city planners created more public parks."}, {"id": "C", "text": "Realized the lack of green spaces, city planners created more public parks."}], "correctOption": "A", "explanation": "A present participle clause (-ing) replaces an active adverbial clause of reason when both clauses share the same subject.", "difficulty": "MEDIUM", "points": 10}, {"id": "english-12-cultural-heritage-q1", "prompt": "Folk singing, traditional festivals, and indigenous craftsmanship belong to which category of cultural heritage?", "options": [{"id": "A", "text": "Intangible cultural heritage"}, {"id": "B", "text": "Tangible architectural heritage"}, {"id": "C", "text": "Natural ecological heritage"}], "correctOption": "A", "explanation": "''Intangible heritage'' includes non-physical traditions, living expressions, and performing arts transmitted from generation to generation.", "difficulty": "EASY", "points": 10}, {"id": "english-12-cultural-heritage-q2", "prompt": "Choose the correct formal inverted conditional sentence:", "options": [{"id": "A", "text": "If had the historic pagoda been renovated properly, it would withstand."}, {"id": "B", "text": "Were the historic pagoda renovated properly, it will withstand."}, {"id": "C", "text": "Had the historic pagoda been renovated properly, it would have withstood the earthquake."}], "correctOption": "C", "explanation": "Third conditional inversion replaces ''If it had been renovated'' with ''Had it been renovated'' without using ''if''.", "difficulty": "MEDIUM", "points": 10}, {"id": "english-12-global-citizenship-q1", "prompt": "What does having ''cross-cultural competence'' primarily involve?", "options": [{"id": "A", "text": "The requirement to abandon one''s own national identity and mother tongue"}, {"id": "B", "text": "The memorization of all historical dates of every country in the world"}, {"id": "C", "text": "The ability to understand, communicate with, and effectively interact with people across cultures"}], "correctOption": "C", "explanation": "Cross-cultural competence involves awareness, attitudes, knowledge, and skills to engage respectfully across diverse cultural boundaries.", "difficulty": "EASY", "points": 10}, {"id": "english-12-global-citizenship-q2", "prompt": "Select the correct linker of contrast to join the ideas: ''Online platforms facilitate worldwide communication; _______, they can sometimes amplify misunderstandings.''", "options": [{"id": "A", "text": "in addition"}, {"id": "B", "text": "nevertheless"}, {"id": "C", "text": "consequently"}], "correctOption": "B", "explanation": "''Nevertheless'' introduces a contrast or concession to the preceding independent clause.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-english-12-2','Ôn tập bài 6–10','english',12,'Bài 6–10','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "english-12-higher-education-q1", "prompt": "Education and training provided by universities, colleges, and technical institutes after secondary school is called:", "options": [{"id": "A", "text": "Pre-school education"}, {"id": "B", "text": "Tertiary education"}, {"id": "C", "text": "Primary education"}], "correctOption": "B", "explanation": "''Tertiary education'' refers to any level of formal education pursued after high school graduation, including university and vocational colleges.", "difficulty": "EASY", "points": 10}, {"id": "english-12-higher-education-q2", "prompt": "Choose the sentence with the correct formal relative clause containing a preposition:", "options": [{"id": "A", "text": "Architecture is an interdisciplinary field in which artistic vision meets engineering precision."}, {"id": "B", "text": "Architecture is an interdisciplinary field which in artistic vision meets engineering."}, {"id": "C", "text": "Architecture is an interdisciplinary field where in artistic vision meets engineering."}], "correctOption": "A", "explanation": "In formal academic English, prepositions precede relative pronouns: ''field in which''.", "difficulty": "MEDIUM", "points": 10}, {"id": "english-12-future-careers-q1", "prompt": "What term describes working from home or another remote location using telecommunications and the internet?", "options": [{"id": "A", "text": "Telecommuting"}, {"id": "B", "text": "Commuting"}, {"id": "C", "text": "Assembly line"}], "correctOption": "A", "explanation": "''Telecommuting'' (or remote working) involves working outside a traditional office space by connecting through digital tools.", "difficulty": "EASY", "points": 10}, {"id": "english-12-future-careers-q2", "prompt": "Complete the sentence using the Future Perfect tense: ''By the end of this decade, automated algorithms _______ millions of manual routine operations.''", "options": [{"id": "A", "text": "will be replacing"}, {"id": "B", "text": "have replaced"}, {"id": "C", "text": "will have replaced"}], "correctOption": "C", "explanation": "Future Perfect (will have + past participle) expresses an action that will be completed before a specified point in the future.", "difficulty": "MEDIUM", "points": 10}, {"id": "english-12-artificial-intelligence-q1", "prompt": "A system or machine capable of performing tasks that typically require human intelligence is called:", "options": [{"id": "A", "text": "Manual typewriter"}, {"id": "B", "text": "Analog calculator"}, {"id": "C", "text": "Artificial intelligence"}], "correctOption": "C", "explanation": "''Artificial intelligence'' (AI) is the simulation of human intelligence processes by computer systems.", "difficulty": "EASY", "points": 10}, {"id": "english-12-artificial-intelligence-q2", "prompt": "Choose the grammatically correct sentence using an advanced reporting verb:", "options": [{"id": "A", "text": "Leading computer scientists recommended regulate autonomous weapons."}, {"id": "B", "text": "Leading computer scientists recommended regulating autonomous weapons before deployment."}, {"id": "C", "text": "Leading computer scientists recommended to regulate autonomous weapons."}], "correctOption": "B", "explanation": "The verb ''recommend'' takes a gerund (-ing) when directly followed by an action without a personal object: ''recommended regulating''.", "difficulty": "MEDIUM", "points": 10}, {"id": "english-12-workplace-skills-q1", "prompt": "The official written record of what was discussed and agreed upon during a business meeting is known as:", "options": [{"id": "A", "text": "Marketing flyer"}, {"id": "B", "text": "Meeting minutes"}, {"id": "C", "text": "Casual gossip"}], "correctOption": "B", "explanation": "''Minutes'' are the instant written record of a meeting or hearing, describing the events and listing attendees, discussions, and decisions.", "difficulty": "EASY", "points": 10}, {"id": "english-12-workplace-skills-q2", "prompt": "Convert into a polite indirect question: ''Where is the quarterly sales report?''", "options": [{"id": "A", "text": "Could you please tell me where the quarterly sales report is?"}, {"id": "B", "text": "Could you please tell me where is the quarterly sales report?"}, {"id": "C", "text": "Where the quarterly sales report could you please tell me?"}], "correctOption": "A", "explanation": "In indirect questions, the clause following the introductory phrase uses normal statement word order: ''where + subject + verb''.", "difficulty": "MEDIUM", "points": 10}, {"id": "english-12-financial-literacy-q1", "prompt": "The interest calculated on the initial principal and also on the accumulated interest of previous periods of a deposit is called:", "options": [{"id": "A", "text": "Compound interest"}, {"id": "B", "text": "Fixed deduction"}, {"id": "C", "text": "Bank penalty"}], "correctOption": "A", "explanation": "''Compound interest'' is interest calculated on the principal amount plus any accrued interest over time.", "difficulty": "EASY", "points": 10}, {"id": "english-12-financial-literacy-q2", "prompt": "Choose the mixed conditional sentence connecting a past action with a present result:", "options": [{"id": "A", "text": "If they conducted market research, their start-up would not have been in financial crisis."}, {"id": "B", "text": "If they had conducted market research, their start-up will not be in financial crisis."}, {"id": "C", "text": "If they had conducted market research, their start-up would not be in financial crisis right now."}], "correctOption": "C", "explanation": "Mixed conditional (Past condition -> Present result): If + past perfect (had conducted), would + bare infinitive (would not be ... now).", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-english-12-3','Ôn tập bài 11–15','english',12,'Bài 11–15','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "english-12-academic-reading-q1", "prompt": "Which academic reading skill involves rapidly reading through a text to get an overview of the main theme and structure?", "options": [{"id": "A", "text": "Proofreading"}, {"id": "B", "text": "Scanning for a phone number"}, {"id": "C", "text": "Skimming"}], "correctOption": "C", "explanation": "''Skimming'' is reading rapidly to get a general overview and understand the main idea of a passage.", "difficulty": "EASY", "points": 10}, {"id": "english-12-academic-reading-q2", "prompt": "Which statement represents an objective fact rather than a subjective opinion?", "options": [{"id": "A", "text": "Every student ought to find biology the most fascinating subject."}, {"id": "B", "text": "The Earth revolves around the Sun in approximately 365.25 days."}, {"id": "C", "text": "Solar energy is by far the most magnificent human invention in history."}], "correctOption": "B", "explanation": "Objective facts can be empirically verified through measurement and scientific observation, unlike personal evaluative judgments.", "difficulty": "MEDIUM", "points": 10}, {"id": "english-12-academic-writing-q1", "prompt": "What is the core sentence in the introductory paragraph that clearly states the author''s central claim and roadmap for the essay?", "options": [{"id": "A", "text": "The bibliography citation"}, {"id": "B", "text": "The thesis statement"}, {"id": "C", "text": "The rhetorical question"}], "correctOption": "B", "explanation": "The ''thesis statement'' expresses the main argument and sets up the scope and focus of the entire academic essay.", "difficulty": "EASY", "points": 10}, {"id": "english-12-academic-writing-q2", "prompt": "What is the purpose of addressing a ''counter-argument'' in an argumentative essay?", "options": [{"id": "A", "text": "To acknowledge an opposing viewpoint and systematically refute it to strengthen one''s own position"}, {"id": "B", "text": "To confuse the reader and make the essay look longer"}, {"id": "C", "text": "To admit that the author''s main thesis is completely mistaken"}], "correctOption": "A", "explanation": "Acknowledging and refuting opposing perspectives demonstrates intellectual rigor and strengthens the validity of the author''s argument.", "difficulty": "MEDIUM", "points": 10}, {"id": "english-12-data-description-q1", "prompt": "Which verb means to rise rapidly and dramatically in value or quantity within a short period?", "options": [{"id": "A", "text": "Surge"}, {"id": "B", "text": "Plummet"}, {"id": "C", "text": "Stagnate"}], "correctOption": "A", "explanation": "To ''surge'' means to experience a sudden and powerful upward movement or increase.", "difficulty": "EASY", "points": 10}, {"id": "english-12-data-description-q2", "prompt": "Choose the sentence that accurately describes a line that goes up and down erratically over time:", "options": [{"id": "A", "text": "Oil prices remained completely static throughout the year."}, {"id": "B", "text": "Oil prices plummeted to zero and stayed there permanently."}, {"id": "C", "text": "Oil prices fluctuated wildly between 70 and 110 dollars per barrel throughout the year."}], "correctOption": "C", "explanation": "''Fluctuate'' means to rise and fall irregularly in number or amount.", "difficulty": "MEDIUM", "points": 10}, {"id": "english-12-presentation-skills-q1", "prompt": "What is ''signposting language'' in oral presentations?", "options": [{"id": "A", "text": "Words painted on wooden traffic road signs"}, {"id": "B", "text": "Technical jargon intended to confuse uneducated listeners"}, {"id": "C", "text": "Phrases used to guide listeners through the structure of a presentation and signal transitions between topics"}], "correctOption": "C", "explanation": "Signposting phrases (e.g., ''Moving on to'', ''To conclude'') indicate what direction the speaker is taking and keep the audience oriented.", "difficulty": "EASY", "points": 10}, {"id": "english-12-presentation-skills-q2", "prompt": "Which signposting phrase is most appropriate when moving to a completely new section of your presentation?", "options": [{"id": "A", "text": "Forget everything I just mentioned because it was wrong,..."}, {"id": "B", "text": "Turning our attention now to our next main topic,..."}, {"id": "C", "text": "To repeat once again what I said five minutes ago,..."}], "correctOption": "B", "explanation": "''Turning our attention now to...'' politely directs the audience''s focus toward the upcoming section.", "difficulty": "MEDIUM", "points": 10}, {"id": "english-12-interviews-cv-q1", "prompt": "In the STAR technique for answering competency-based interview questions, what does the letter ''A'' stand for?", "options": [{"id": "A", "text": "Annual salary requested"}, {"id": "B", "text": "Action taken by the candidate"}, {"id": "C", "text": "Academic grades"}], "correctOption": "B", "explanation": "STAR stands for Situation, Task, Action, and Result, guiding candidates to describe specific behaviors and positive outcomes.", "difficulty": "EASY", "points": 10}, {"id": "english-12-interviews-cv-q2", "prompt": "Why are powerful action verbs (e.g., ''orchestrated'', ''streamlined'', ''pioneered'') recommended when describing achievements on a CV?", "options": [{"id": "A", "text": "They highlight active leadership, initiative, and measurable contribution to past projects"}, {"id": "B", "text": "They disguise the fact that the applicant has no real qualifications"}, {"id": "C", "text": "They are required by national law in every resume"}], "correctOption": "A", "explanation": "Dynamic action verbs emphasize proactive contribution and impact rather than passive job descriptions.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-history-12-1','Ôn tập bài 1–5','history',12,'Bài 1–5','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "history-12-cold-war-origins-q1", "prompt": "Hội nghị Ianta diễn ra vào tháng 2/1945 có sự tham gia của nguyên thủ ba cường quốc nào?", "options": [{"id": "A", "text": "Liên Xô, Mĩ và Anh"}, {"id": "B", "text": "Mĩ, Anh và Pháp"}, {"id": "C", "text": "Liên Xô, Trung Quốc và Mĩ"}], "correctOption": "A", "explanation": "Hội nghị Ianta quy tụ ba nguyên thủ: Stalin (Liên Xô), Roosevelt (Mĩ) và Churchill (Anh) để thỏa thuận phân chia phạm vi ảnh hưởng sau Thế chiến II.", "difficulty": "EASY", "points": 10}, {"id": "history-12-cold-war-origins-q2", "prompt": "Sự kiện nào sau đây đánh dấu sự khởi đầu chính thức của cuộc Chiến tranh Lạnh giữa hai phe?", "options": [{"id": "A", "text": "Sự ra đời của tổ chức Hiệp ước Bắc Đại Tây Dương (NATO) năm 1949"}, {"id": "B", "text": "Sự thành lập khối Hiệp ước Warsaw tại Đông Âu năm 1955"}, {"id": "C", "text": "Thông điệp của Tổng thống Mĩ Truman tại Quốc hội Mĩ (tháng 3/1947)"}], "correctOption": "C", "explanation": "Tháng 3/1947, Thông điệp Truman khẳng định sự tồn tại của Liên Xô là mối đe dọa và viện trợ cho Hy Lạp, Thổ Nhĩ Kỳ, mở đầu Chiến tranh Lạnh.", "difficulty": "MEDIUM", "points": 10}, {"id": "history-12-united-nations-q1", "prompt": "Mục tiêu bao trùm hàng đầu của tổ chức Liên hợp quốc được ghi nhận trong Hiến chương năm 1945 là:", "options": [{"id": "A", "text": "Thành lập một chính phủ liên bang chung cho toàn cầu"}, {"id": "B", "text": "Xóa bỏ hoàn toàn mọi đường biên giới quốc gia giữa các nước"}, {"id": "C", "text": "Duy trì hòa bình và an ninh quốc tế"}], "correctOption": "C", "explanation": "Điều 1 Hiến chương Liên hợp quốc xác định mục tiêu cao nhất là duy trì hòa bình và an ninh thế giới, ngăn ngừa chiến tranh tái diễn.", "difficulty": "EASY", "points": 10}, {"id": "history-12-united-nations-q2", "prompt": "Cơ quan nào của Liên hợp quốc giữ vai trò trọng yếu trong việc duy trì hòa bình và an ninh thế giới?", "options": [{"id": "A", "text": "Tòa án Công lí Quốc tế"}, {"id": "B", "text": "Hội đồng Bảo an"}, {"id": "C", "text": "Đại hội đồng"}], "correctOption": "B", "explanation": "Hội đồng Bảo an là cơ quan duy nhất của Liên hợp quốc có thẩm quyền ra các quyết định mang tính ràng buộc pháp lí về duy trì hòa bình và an ninh.", "difficulty": "MEDIUM", "points": 10}, {"id": "history-12-asean-integration-q1", "prompt": "Hiệp hội các quốc gia Đông Nam Á (ASEAN) được thành lập vào ngày tháng năm nào và tại đâu?", "options": [{"id": "A", "text": "Ngày 20/9/1977 tại New York (Mĩ)"}, {"id": "B", "text": "Ngày 8/8/1967 tại Bangkok (Thái Lan)"}, {"id": "C", "text": "Ngày 2/9/1945 tại Hà Nội (Việt Nam)"}], "correctOption": "B", "explanation": "Tuyên bố Bangkok ngày 8/8/1967 do đại diện 5 nước sáng lập kí kết chính thức khai sinh tổ chức ASEAN.", "difficulty": "EASY", "points": 10}, {"id": "history-12-asean-integration-q2", "prompt": "Việt Nam chính thức trở thành thành viên thứ 7 của ASEAN vào thời điểm nào?", "options": [{"id": "A", "text": "Ngày 28/7/1995"}, {"id": "B", "text": "Ngày 30/4/1975"}, {"id": "C", "text": "Ngày 31/12/2015"}], "correctOption": "A", "explanation": "Ngày 28/7/1995, tại Hội nghị Bộ trưởng Ngoại giao ASEAN lần thứ 28 ở Brunei, Việt Nam chính thức kết nạp làm thành viên thứ 7.", "difficulty": "MEDIUM", "points": 10}, {"id": "history-12-cold-war-end-multipolar-q1", "prompt": "Sự kiện lịch sử nào đánh dấu sự sụp đổ hoàn toàn của trật tự thế giới hai cực Ianta?", "options": [{"id": "A", "text": "Sự sụp đổ và tan rã của Liên bang Xô viết vào tháng 12/1991"}, {"id": "B", "text": "Hiệp định đình chiến tại bán đảo Triều Tiên năm 1953"}, {"id": "C", "text": "Sự thành lập khối liên minh quân sự NATO năm 1949"}], "correctOption": "A", "explanation": "Khi Liên Xô tan rã cuối năm 1991, một trong hai cực đối đầu không còn tồn tại, trật tự hai cực Ianta chính thức kết thúc.", "difficulty": "EASY", "points": 10}, {"id": "history-12-cold-war-end-multipolar-q2", "prompt": "Sau khi Chiến tranh Lạnh chấm dứt, xu thế chủ đạo trong quan hệ quốc tế của hầu hết các quốc gia là:", "options": [{"id": "A", "text": "Tập trung chạy đua vũ trang hạt nhân và chuẩn bị thế chiến mới"}, {"id": "B", "text": "Đóng cửa biên giới hoàn toàn và ngừng mọi quan hệ ngoại giao"}, {"id": "C", "text": "Hòa hoãn, đối thoại và hợp tác phát triển kinh tế làm trọng tâm chiến lược"}], "correctOption": "C", "explanation": "Các nước chuyển trọng tâm sang xây dựng sức mạnh quốc gia tổng hợp, lấy phát triển kinh tế làm nền tảng cạnh tranh lành mạnh và đối thoại giải quyết tranh chấp.", "difficulty": "MEDIUM", "points": 10}, {"id": "history-12-fourth-industrial-revolution-q1", "prompt": "Công nghệ nào sau đây được coi là một trong những trụ cột cốt lõi của cuộc Cách mạng công nghiệp lần thứ tư?", "options": [{"id": "A", "text": "Động cơ hơi nước cải tiến của James Watt"}, {"id": "B", "text": "Dây chuyền sản xuất cơ khí hóa chạy bằng sức nước"}, {"id": "C", "text": "Trí tuệ nhân tạo (AI) và Internet vạn vật (IoT)"}], "correctOption": "C", "explanation": "Công nghiệp 4.0 dựa trên nền tảng kỹ thuật số với AI, IoT, Big Data kết nối thế giới thực và thế giới ảo.", "difficulty": "EASY", "points": 10}, {"id": "history-12-fourth-industrial-revolution-q2", "prompt": "Thời cơ lớn nhất mà Cách mạng công nghiệp lần thứ tư mang lại cho các quốc gia đang phát triển như Việt Nam là:", "options": [{"id": "A", "text": "Chấm dứt hoàn toàn mọi tác động tiêu cực của thiên tai và dịch bệnh"}, {"id": "B", "text": "Khả năng đi tắt đón đầu, chuyển đổi số nhanh để nâng cao năng suất lao động và năng lực cạnh tranh quốc gia"}, {"id": "C", "text": "Loại bỏ hoàn toàn sự cần thiết của giáo dục đại học và đào tạo nghề nghiệp"}], "correctOption": "B", "explanation": "Công nghệ số cho phép các nước đi sau tiếp cận tri thức và giải pháp quản trị hiện đại nhanh chóng mà không cần lặp lại toàn bộ các nấc thang công nghiệp hóa truyền thống.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-history-12-2','Ôn tập bài 6–10','history',12,'Bài 6–10','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "history-12-august-revolution-1945-q1", "prompt": "Ngày 2/9/1945, tại Quảng trường Ba Đình (Hà Nội), sự kiện lịch sử trọng đại nào đã diễn ra?", "options": [{"id": "A", "text": "Khởi nghĩa giành chính quyền thắng lợi hoàn toàn tại Sài Gòn"}, {"id": "B", "text": "Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa"}, {"id": "C", "text": "Đại hội Quốc dân Tân Trào thông qua 10 chính sách lớn của Việt Minh"}], "correctOption": "B", "explanation": "Bản Tuyên ngôn Độc lập ngày 2/9/1945 tuyên bố trước quốc dân và thế giới quyền tự do, độc lập thiêng liêng của dân tộc Việt Nam.", "difficulty": "EASY", "points": 10}, {"id": "history-12-august-revolution-1945-q2", "prompt": "Thời cơ lịch sử ''ngàn năm có một'' của Cách mạng tháng Tám năm 1945 xuất hiện khi nào?", "options": [{"id": "A", "text": "Chính phủ phát xít Nhật Bản tuyên bố đầu hàng Đồng minh vô điều kiện (giữa tháng 8/1945)"}, {"id": "B", "text": "Thực dân Pháp bắt đầu quay trở lại nổ súng đánh chiếm Sài Gòn"}, {"id": "C", "text": "Quân đội Tưởng Giới Thạch tiến vào miền Bắc giải giáp quân Nhật"}], "correctOption": "A", "explanation": "Nhật đầu hàng Đồng minh khiến quân Nhật ở Đông Dương tê liệt, chính phủ bù nhìn Trần Trọng Kim hoang mang cực độ, tạo thời cơ chín muồi giành chính quyền trước khi quân Đồng minh vào.", "difficulty": "MEDIUM", "points": 10}, {"id": "history-12-anti-french-resistance-q1", "prompt": "Lời kêu gọi toàn quốc kháng chiến của Chủ tịch Hồ Chí Minh được phát đi vào thời điểm lịch sử nào?", "options": [{"id": "A", "text": "Đêm ngày 19/12/1946"}, {"id": "B", "text": "Ngày 2/9/1945"}, {"id": "C", "text": "Ngày 7/5/1954"}], "correctOption": "A", "explanation": "Trước tối hậu thư đòi tước vũ khí của thực dân Pháp tại Hà Nội, Trung ương Đảng và Hồ Chủ tịch đã quyết định phát động toàn quốc kháng chiến đêm 19/12/1946.", "difficulty": "EASY", "points": 10}, {"id": "history-12-anti-french-resistance-q2", "prompt": "Chiến dịch nào sau đây đã giúp quân đội ta giành được quyền chủ động chiến lược trên chiến trường chính Bắc Bộ?", "options": [{"id": "A", "text": "Chiến dịch Việt Bắc thu - đông năm 1947"}, {"id": "B", "text": "Cuộc chiến đấu 60 ngày đêm bảo vệ Thủ đô Hà Nội cuối năm 1946"}, {"id": "C", "text": "Chiến dịch Biên giới thu - đông năm 1950"}], "correctOption": "C", "explanation": "Chiến dịch Biên giới 1950 tiêu diệt nhiều sinh lực địch, giải phóng dải biên giới phía Bắc, khai thông đường liên lạc quốc tế và chuyển sang thế chủ động tiến công.", "difficulty": "MEDIUM", "points": 10}, {"id": "history-12-dien-bien-phu-1954-q1", "prompt": "Chiến dịch lịch sử Điện Biên Phủ năm 1954 toàn thắng vào ngày tháng năm nào?", "options": [{"id": "A", "text": "Ngày 13/3/1954"}, {"id": "B", "text": "Ngày 21/7/1954"}, {"id": "C", "text": "Ngày 7/5/1954"}], "correctOption": "C", "explanation": "Chiều ngày 7/5/1954, lá cờ Quyết chiến Quyết thắng tung bay trên nóc hầm tướng De Castries, chiến dịch Điện Biên Phủ kết thúc thắng lợi rực rỡ.", "difficulty": "EASY", "points": 10}, {"id": "history-12-dien-bien-phu-1954-q2", "prompt": "Quyết định thay đổi phương châm tác chiến mang tính bước ngoặt quyết định thắng lợi của Đại tướng Võ Nguyên Giáp tại Điện Biên Phủ là:", "options": [{"id": "A", "text": "Chuyển từ tiến công đường bộ sang đổ bộ đường không"}, {"id": "B", "text": "Chuyển từ phương châm ''đánh nhanh, thắng nhanh'' sang ''đánh chắc, tiến chắc''"}, {"id": "C", "text": "Chuyển từ bao vây chiến hào sang rút lui toàn bộ lực lượng về căn cứ Việt Bắc"}], "correctOption": "B", "explanation": "Nhận thấy địch đã tăng cường công sự kiên cố, việc chuyển sang ''đánh chắc, tiến chắc'' bóc dỡ từng cứ điểm bảo đảm chắc thắng cho từng trận đánh.", "difficulty": "MEDIUM", "points": 10}, {"id": "history-12-tet-offensive-1968-q1", "prompt": "Điểm độc đáo và bất ngờ nhất về mặt không gian tác chiến của cuộc Tổng tiến công Xuân Mậu Thân 1968 là:", "options": [{"id": "A", "text": "Đổ bộ tấn công bất ngờ bằng đường biển vào các hòn đảo xa bờ"}, {"id": "B", "text": "Đồng loạt tiến công trực diện vào các đô thị lớn và cơ quan đầu não đối phương"}, {"id": "C", "text": "Chỉ mở các cuộc phục kích nhỏ ở các vùng rừng núi hẻo lánh"}], "correctOption": "B", "explanation": "Đòn tiến công diễn ra đúng đêm Giao thừa Tết nhắm thẳng vào các trung tâm đô thị kiên cố nơi đối phương tập trung phòng thủ dày đặc nhất.", "difficulty": "EASY", "points": 10}, {"id": "history-12-tet-offensive-1968-q2", "prompt": "Hậu quả chính trị - quân sự lớn nhất mà cuộc Tổng tiến công Xuân Mậu Thân 1968 gây ra cho giới cầm quyền Washington là:", "options": [{"id": "A", "text": "Làm lung lay ý chí xâm lược của Mĩ, buộc Tổng thống Johnson phải tuyên bố ''phi Mĩ hóa'' chiến tranh và ngồi vào bàn đàm phán Paris"}, {"id": "B", "text": "Khiến quân Mĩ phải kí ngay hiệp định đầu hàng vô điều kiện trong vòng một tuần"}, {"id": "C", "text": "Làm cho toàn bộ lực lượng quân đội Sài Gòn tự nguyện giải thể vũ khí"}], "correctOption": "A", "explanation": "Đòn Mậu Thân phá sản hoàn toàn chiến lược Chiến tranh cục bộ, buộc Mĩ phải xuống thang chiến tranh và thừa nhận thất bại quân sự trên bàn đàm phán.", "difficulty": "MEDIUM", "points": 10}, {"id": "history-12-ho-chi-minh-campaign-1975-q1", "prompt": "Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được kí kết chính thức vào thời gian nào?", "options": [{"id": "A", "text": "Ngày 27/1/1973"}, {"id": "B", "text": "Ngày 21/7/1954"}, {"id": "C", "text": "Ngày 30/4/1975"}], "correctOption": "A", "explanation": "Hiệp định Paris được kí ngày 27/1/1973 sau thắng lợi oanh liệt của trận ''Điện Biên Phủ trên không'' cuối năm 1972, buộc Mĩ phải rút hết quân viễn chinh.", "difficulty": "EASY", "points": 10}, {"id": "history-12-ho-chi-minh-campaign-1975-q2", "prompt": "Đòn tiến công mở màn mang tính đột phá chiến lược của cuộc Tổng tiến công mùa Xuân 1975 là trận đánh giải phóng:", "options": [{"id": "A", "text": "Thành phố Huế và Đà Nẵng"}, {"id": "B", "text": "Căn cứ quân sự Cam Ranh"}, {"id": "C", "text": "Thị xã Buôn Ma Thuột (trong Chiến dịch Tây Nguyên, ngày 10/3/1975)"}], "correctOption": "C", "explanation": "Trận Buôn Ma Thuột ngày 10/3/1975 đánh trúng điểm hiểm yếu bất ngờ, làm rung chuyển toàn bộ tuyến phòng thủ Tây Nguyên và dẫn đến sự tan rã của đối phương.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-history-12-3','Ôn tập bài 11–15','history',12,'Bài 11–15','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "history-12-national-reunification-state-q1", "prompt": "Kì họp thứ nhất Quốc hội khóa VI (tháng 6 - 7/1976) đã đưa ra quyết định trọng đại nào về quốc hiệu?", "options": [{"id": "A", "text": "Đặt tên nước là Việt Nam Dân chủ Cộng hòa"}, {"id": "B", "text": "Giữ nguyên hai tên gọi nhà nước riêng biệt ở hai miền"}, {"id": "C", "text": "Đặt tên nước là Cộng hòa Xã hội chủ nghĩa Việt Nam"}], "correctOption": "C", "explanation": "Quốc hội khóa VI đã thống nhất thể chế, quyết định quốc hiệu là Cộng hòa Xã hội chủ nghĩa Việt Nam từ ngày 2/7/1976.", "difficulty": "EASY", "points": 10}, {"id": "history-12-national-reunification-state-q2", "prompt": "Ý nghĩa lịch sử then chốt của việc hoàn thành thống nhất đất nước về mặt nhà nước (1975 - 1976) là gì?", "options": [{"id": "A", "text": "Cho phép đất nước ngay lập tức tham gia vào tất cả các hiệp định thương mại tự do"}, {"id": "B", "text": "Tạo cơ sở pháp lí và sức mạnh tổng hợp của toàn dân tộc để xây dựng, phát triển kinh tế và bảo vệ vững chắc Tổ quốc"}, {"id": "C", "text": "Chấm dứt hoàn toàn mọi khó khăn về kinh tế - xã hội thời hậu chiến"}], "correctOption": "B", "explanation": "Thống nhất nhà nước tạo nên sự đồng bộ về thể chế, luật pháp, chính quyền từ trung ương đến địa phương để huy động mọi nguồn lực kiến thiết đất nước.", "difficulty": "MEDIUM", "points": 10}, {"id": "history-12-doi-moi-1986-q1", "prompt": "Đại hội đại biểu toàn quốc lần thứ VI của Đảng Cộng sản Việt Nam họp vào tháng 12/1986 có ý nghĩa lịch sử gì?", "options": [{"id": "A", "text": "Tuyên bố xóa bỏ hoàn toàn nền kinh tế thị trường để chuyển sang kinh tế thuần nông"}, {"id": "B", "text": "Khởi xướng và đề ra đường lối Đổi mới toàn diện đất nước"}, {"id": "C", "text": "Quyết định phát động cuộc kháng chiến toàn quốc chống Mĩ cứu nước"}], "correctOption": "B", "explanation": "Đại hội VI (12/1986) nhìn thẳng vào sự thật, đánh dấu bước ngoặt lịch sử mở đường cho công cuộc Đổi mới đất nước.", "difficulty": "EASY", "points": 10}, {"id": "history-12-doi-moi-1986-q2", "prompt": "Trọng tâm của đường lối Đổi mới do Đại hội VI đề ra bắt đầu từ lĩnh vực nào?", "options": [{"id": "A", "text": "Đổi mới về kinh tế"}, {"id": "B", "text": "Đổi mới về chính trị"}, {"id": "C", "text": "Đổi mới về quốc phòng"}], "correctOption": "A", "explanation": "Đảng xác định đổi mới kinh tế là trọng tâm, kết hợp từng bước đổi mới chính trị vững chắc nhằm giải quyết khủng hoảng đời sống nhân dân trước tiên.", "difficulty": "MEDIUM", "points": 10}, {"id": "history-12-vietnam-international-integration-q1", "prompt": "Năm 1995 ghi dấu ấn lịch sử nổi bật nào trong tiến trình hội nhập quốc tế của Việt Nam?", "options": [{"id": "A", "text": "Bình thường hóa quan hệ ngoại giao với Hoa Kỳ và chính thức gia nhập ASEAN"}, {"id": "B", "text": "Gia nhập Tổ chức Thương mại Thế giới (WTO)"}, {"id": "C", "text": "Kí kết Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP)"}], "correctOption": "A", "explanation": "Tháng 7/1995 là dấu mốc lịch sử khi Việt Nam và Mĩ bình thường hóa quan hệ ngoại giao (11/7) và Việt Nam trở thành thành viên ASEAN (28/7).", "difficulty": "EASY", "points": 10}, {"id": "history-12-vietnam-international-integration-q2", "prompt": "Việt Nam chính thức trở thành thành viên thứ 150 của Tổ chức Thương mại Thế giới (WTO) vào năm nào?", "options": [{"id": "A", "text": "Năm 1995"}, {"id": "B", "text": "Năm 1986"}, {"id": "C", "text": "Năm 2007"}], "correctOption": "C", "explanation": "Tháng 1/2007, Việt Nam chính thức trở thành thành viên WTO, đánh dấu bước hội nhập sâu rộng vào sân chơi kinh tế toàn cầu.", "difficulty": "MEDIUM", "points": 10}, {"id": "history-12-east-sea-sovereignty-q1", "prompt": "Tổ chức nào trong lịch sử phong kiến Việt Nam được các chúa Nguyễn và triều Nguyễn lập ra để thực thi chủ quyền hàng năm tại Hoàng Sa và Trường Sa?", "options": [{"id": "A", "text": "Đoàn tàu buôn phương Tây"}, {"id": "B", "text": "Vạn chài ven sông Hồng"}, {"id": "C", "text": "Hải đội Hoàng Sa (và Đội Bắc Hải)"}], "correctOption": "C", "explanation": "Hải đội Hoàng Sa được thành lập từ thời chúa Nguyễn có nhiệm vụ ra hai quần đảo đo đạc thủy trình, cắm mốc chủ quyền, thu lượm hải vật và cứu hộ tàu thuyền.", "difficulty": "EASY", "points": 10}, {"id": "history-12-east-sea-sovereignty-q2", "prompt": "Văn bản pháp lí quốc tế quan trọng nhất hiện nay quy định chế độ pháp lí của các vùng biển và quyền của các quốc gia ven biển là:", "options": [{"id": "A", "text": "Hiến chương Liên minh châu Âu"}, {"id": "B", "text": "Công ước Liên hợp quốc về Luật Biển năm 1982 (UNCLOS 1982)"}, {"id": "C", "text": "Tuyên bố Cairo năm 1943"}], "correctOption": "B", "explanation": "UNCLOS 1982 được coi là ''Hiến pháp của đại dương'', xác lập rõ ràng phạm vi nội thủy, lãnh hải, vùng đặc quyền kinh tế 200 hải lí và thềm lục địa.", "difficulty": "MEDIUM", "points": 10}, {"id": "history-12-ho-chi-minh-national-liberation-q1", "prompt": "Sự kiện lịch sử nào đánh dấu bước ngoặt quyết định đưa Nguyễn Ái Quốc từ người yêu nước trở thành chiến sĩ cộng sản?", "options": [{"id": "A", "text": "Tham gia thành lập Hội Liên hiệp thuộc địa tại Paris năm 1921"}, {"id": "B", "text": "Đọc Luận cương của Lênin về vấn đề dân tộc và thuộc địa (1920) và bỏ phiếu tán thành Quốc tế Cộng sản tại Đại hội Tours"}, {"id": "C", "text": "Rời bến cảng Nhà Rồng sang phương Tây tìm đường cứu nước năm 1911"}], "correctOption": "B", "explanation": "Tháng 7/1920, khi đọc Sơ thảo Luận cương của Lênin, Nguyễn Ái Quốc đã tìm thấy con đường giải phóng cho dân tộc và bỏ phiếu tán thành Quốc tế Cộng sản vào tháng 12/1920.", "difficulty": "EASY", "points": 10}, {"id": "history-12-ho-chi-minh-national-liberation-q2", "prompt": "Tác phẩm lý luận chính trị xuất sắc do Nguyễn Ái Quốc biên soạn năm 1927 dùng làm tài liệu huấn luyện cán bộ cách mạng tiền phong là:", "options": [{"id": "A", "text": "Đường Kách mệnh"}, {"id": "B", "text": "Bản án chế độ thực dân Pháp"}, {"id": "C", "text": "Tuyên ngôn Độc lập"}], "correctOption": "A", "explanation": "Cuốn sách ''Đường Kách mệnh'' (1927) tập hợp các bài giảng của Nguyễn Ái Quốc tại Quảng Châu, chuẩn bị nền tảng tư tưởng và chính trị cho sự ra đời của Đảng.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-geography-12-1','Ôn tập bài 1–5','geography',12,'Bài 1–5','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "geography-12-vietnam-location-territory-q1", "prompt": "Điểm cực Bắc trên đất liền của nước ta thuộc xã Lũng Cú (huyện Đồng Văn, tỉnh Hà Giang) nằm ở vĩ độ nào?", "options": [{"id": "A", "text": "23°23''B"}, {"id": "B", "text": "8°34''B"}, {"id": "C", "text": "102°09''Đ"}], "correctOption": "A", "explanation": "Điểm cực Bắc tại Lũng Cú (Hà Giang) ở vĩ độ 23°23''B; điểm cực Nam tại Ngọc Hiển (Cà Mau) ở vĩ độ 8°34''B.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-vietnam-location-territory-q2", "prompt": "Vùng biển thuộc chủ quyền hoàn toàn và tuyệt đối của quốc gia ven biển, có chiều rộng 12 hải lí tính từ đường cơ sở gọi là:", "options": [{"id": "A", "text": "Nội thủy"}, {"id": "B", "text": "Vùng đặc quyền kinh tế"}, {"id": "C", "text": "Lãnh hải"}], "correctOption": "C", "explanation": "Theo Luật Biển Việt Nam và UNCLOS 1982, lãnh hải là vùng biển có chiều rộng 12 hải lí tính từ đường cơ sở ra phía biển, thuộc chủ quyền quốc gia.", "difficulty": "MEDIUM", "points": 10}, {"id": "geography-12-vietnam-relief-landforms-q1", "prompt": "Đặc điểm nào sau đây phản ánh đúng nhất cấu trúc cơ bản của địa hình đồi núi Việt Nam?", "options": [{"id": "A", "text": "Địa hình chủ yếu là núi cao hiểm trở trên 3000 m chiếm hơn một nửa diện tích"}, {"id": "B", "text": "Đồng bằng châu thổ chiếm tới 75% toàn bộ diện tích đất liền"}, {"id": "C", "text": "Đồi núi chiếm 3/4 diện tích lãnh thổ, nhưng chủ yếu là đồi núi thấp dưới 1000 m"}], "correctOption": "C", "explanation": "Đồi núi thấp dưới 1000 m chiếm tới 85% diện tích cả nước, núi cao trên 2000 m chỉ chiếm khoảng 1%.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-vietnam-relief-landforms-q2", "prompt": "Hai hướng núi chính thể hiện rõ nét nhất trong cấu trúc sơn văn của lãnh thổ Việt Nam là:", "options": [{"id": "A", "text": "Hướng đông bắc - tây nam và hướng kinh tuyến"}, {"id": "B", "text": "Hướng tây bắc - đông nam và hướng vòng cung"}, {"id": "C", "text": "Hướng bắc - nam và hướng đông - tây"}], "correctOption": "B", "explanation": "Các dãy núi Tây Bắc và Trường Sơn Bắc có hướng tây bắc - đông nam; vùng núi Đông Bắc có 4 cánh cung lớn chụm đầu ở Tam Đảo.", "difficulty": "MEDIUM", "points": 10}, {"id": "geography-12-vietnam-tropical-monsoon-climate-q1", "prompt": "Biểu hiện rõ nét nhất của tính chất nhiệt đới trong khí hậu Việt Nam là:", "options": [{"id": "A", "text": "Lượng mưa hàng năm rất thấp dưới 200 mm giống như hoang mạc"}, {"id": "B", "text": "Nhiệt độ trung bình năm trên hầu khắp cả nước đều vượt 20 °C và tổng số giờ nắng dồi dào"}, {"id": "C", "text": "Quanh năm luôn có bão tuyết và nhiệt độ âm"}], "correctOption": "B", "explanation": "Nhờ nằm hoàn toàn trong vùng nội chí tuyến, lãnh thổ nhận được lượng bức xạ mặt trời lớn, cân bằng bức xạ dương quanh năm.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-vietnam-tropical-monsoon-climate-q2", "prompt": "Đặc điểm thời tiết nổi bật của miền Bắc nước ta vào nửa sau mùa đông (từ tháng 2 đến tháng 4) là:", "options": [{"id": "A", "text": "Thời tiết lạnh ẩm và có mưa phùn"}, {"id": "B", "text": "Thời tiết khô hanh, trời quang mây và không mưa"}, {"id": "C", "text": "Nắng nóng gay gắt kéo dài nhiều tuần liên tiếp"}], "correctOption": "A", "explanation": "Nửa sau mùa đông khối không khí lạnh lệch đông đi qua biển vào đất liền mang theo lượng ẩm lớn, gây thời tiết lạnh ẩm và mưa phùn rải rác.", "difficulty": "MEDIUM", "points": 10}, {"id": "geography-12-vietnam-population-demographics-q1", "prompt": "Quy mô dân số Việt Nam hiện nay đã chính thức vượt qua mốc dân số nào?", "options": [{"id": "A", "text": "Trên 100 triệu người"}, {"id": "B", "text": "Khoảng 50 triệu người"}, {"id": "C", "text": "Trên 200 triệu người"}], "correctOption": "A", "explanation": "Năm 2023, dân số Việt Nam đã chính thức vượt qua mốc 100 triệu người, xếp thứ 3 ở Đông Nam Á sau Indonesia và Philippines.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-vietnam-population-demographics-q2", "prompt": "Cơ hội phát triển kinh tế - xã hội lớn nhất do thời kì ''cơ cấu dân số vàng'' mang lại cho nước ta là:", "options": [{"id": "A", "text": "Làm giảm chi phí đầu tư cho hệ thống giáo dục tiểu học về mức 0"}, {"id": "B", "text": "Loại bỏ hoàn toàn vấn đề thất nghiệp ở các vùng đô thị"}, {"id": "C", "text": "Cung cấp lực lượng lao động trẻ dồi dào, thúc đẩy tăng trưởng kinh tế nhanh nếu được đào tạo tốt"}], "correctOption": "C", "explanation": "Dân số vàng nghĩa là cứ hai người đi làm nuôi dưới một người phụ thuộc, tạo lợi thế lớn về năng suất và tích lũy vốn phát triển.", "difficulty": "MEDIUM", "points": 10}, {"id": "geography-12-vietnam-urbanization-process-q1", "prompt": "Hai đô thị trực thuộc trung ương được xếp vào cấp đô thị loại đặc biệt ở Việt Nam là:", "options": [{"id": "A", "text": "Đà Nẵng và Hải Phòng"}, {"id": "B", "text": "Cần Thơ và Nha Trang"}, {"id": "C", "text": "Hà Nội và Thành phố Hồ Chí Minh"}], "correctOption": "C", "explanation": "Hà Nội (thủ đô) và TP. Hồ Chí Minh (đầu tàu kinh tế phía Nam) là hai đô thị loại đặc biệt của cả nước.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-vietnam-urbanization-process-q2", "prompt": "Đặc điểm cơ bản của quá trình đô thị hóa ở Việt Nam hiện nay là:", "options": [{"id": "A", "text": "Các đô thị hoàn toàn không có sự đóng góp nào vào nguồn thu ngân sách"}, {"id": "B", "text": "Tốc độ đô thị hóa diễn ra nhanh nhưng trình độ đô thị hóa nhìn chung vẫn còn thấp"}, {"id": "C", "text": "Tỉ lệ dân số thành thị đã chiếm trên 90% tổng số dân cả nước"}], "correctOption": "B", "explanation": "Dù tỉ lệ dân thành thị tăng đều đặn qua các năm nhưng chất lượng cơ sở hạ tầng và dịch vụ đô thị còn nhiều hạn chế.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-geography-12-2','Ôn tập bài 6–10','geography',12,'Bài 6–10','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "geography-12-vietnam-agriculture-restructuring-q1", "prompt": "Xu hướng chuyển dịch cơ cấu nội bộ ngành trồng trọt của nước ta hiện nay là:", "options": [{"id": "A", "text": "Chuyển toàn bộ diện tích đất nông nghiệp sang khai thác mỏ khoáng sản"}, {"id": "B", "text": "Giảm tỉ trọng cây lương thực phẩm cấp thấp, tăng tỉ trọng cây công nghiệp lâu năm và cây ăn quả chất lượng cao"}, {"id": "C", "text": "Xóa bỏ hoàn toàn diện tích trồng lúa để trồng toàn bộ cỏ chăn nuôi"}], "correctOption": "B", "explanation": "Tái cơ cấu trồng trọt tập trung vào nâng cao giá trị gia tăng, đáp ứng tiêu chuẩn xuất khẩu và thích ứng biến đổi khí hậu.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-vietnam-agriculture-restructuring-q2", "prompt": "Vùng chuyên canh cây cà phê lớn nhất của Việt Nam, đưa nước ta trở thành quốc gia xuất khẩu cà phê Robusta hàng đầu thế giới là:", "options": [{"id": "A", "text": "Vùng Tây Nguyên"}, {"id": "B", "text": "Vùng Đồng bằng sông Hồng"}, {"id": "C", "text": "Vùng Bắc Trung Bộ"}], "correctOption": "A", "explanation": "Tây Nguyên có diện tích đất đỏ bazan màu mỡ và khí hậu cận xích đạo rất thích hợp hình thành các vùng chuyên canh cà phê quy mô lớn.", "difficulty": "MEDIUM", "points": 10}, {"id": "geography-12-vietnam-forestry-fisheries-q1", "prompt": "Loại rừng nào sau đây có chức năng chủ yếu là bảo tồn nguồn gene sinh vật quý hiếm và nghiên cứu khoa học?", "options": [{"id": "A", "text": "Rừng đặc dụng (các vườn quốc gia, khu bảo tồn thiên nhiên)"}, {"id": "B", "text": "Rừng sản xuất lấy gỗ"}, {"id": "C", "text": "Rừng trồng bạch đàn thương phẩm"}], "correctOption": "A", "explanation": "Rừng đặc dụng bảo vệ hệ sinh thái mẫu chuẩn, bảo tồn đa dạng sinh học và cảnh quan di sản thiên nhiên.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-vietnam-forestry-fisheries-q2", "prompt": "Hai mặt hàng thủy sản nuôi trồng xuất khẩu chủ lực mang lại kim ngạch hàng tỉ USD mỗi năm cho nước ta là:", "options": [{"id": "A", "text": "Cá hồi và cá tầm ôn đới"}, {"id": "B", "text": "Rong biển tươi và cua đồng"}, {"id": "C", "text": "Tôm nước lợ và cá tra"}], "correctOption": "C", "explanation": "Đồng bằng sông Cửu Long là vựa tôm và cá tra lớn nhất nước, đóng góp phần lớn kim ngạch xuất khẩu thủy sản của Việt Nam.", "difficulty": "MEDIUM", "points": 10}, {"id": "geography-12-vietnam-industry-restructuring-q1", "prompt": "Nhóm ngành công nghiệp hiện đang chiếm tỉ trọng áp đảo và đóng vai trò động lực tăng trưởng chính của công nghiệp Việt Nam là:", "options": [{"id": "A", "text": "Công nghiệp khai thác than và quặng kim loại thô"}, {"id": "B", "text": "Công nghiệp đan lát thủ công gia đình"}, {"id": "C", "text": "Công nghiệp chế biến, chế tạo"}], "correctOption": "C", "explanation": "Công nghiệp chế biến, chế tạo đóng góp trên 80% giá trị sản xuất công nghiệp và là nguồn thu xuất khẩu lớn nhất của đất nước.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-vietnam-industry-restructuring-q2", "prompt": "Hai vùng kinh tế tập trung mật độ các khu công nghiệp và trung tâm công nghiệp quy mô lớn nhất cả nước là:", "options": [{"id": "A", "text": "Vùng Bắc Trung Bộ và Duyên hải Nam Trung Bộ"}, {"id": "B", "text": "Vùng Đông Nam Bộ và Vùng Đồng bằng sông Hồng"}, {"id": "C", "text": "Vùng Tây Nguyên và Vùng Tây Bắc"}], "correctOption": "B", "explanation": "Đông Nam Bộ và Đồng bằng sông Hồng hội tụ hạ tầng giao thông, cảng biển, nguồn nhân lực chất lượng cao và thị trường tiêu thụ lớn nhất nước.", "difficulty": "MEDIUM", "points": 10}, {"id": "geography-12-vietnam-energy-transition-q1", "prompt": "Nhà máy thủy điện có công suất lớn nhất Việt Nam và khu vực Đông Nam Á hiện nay là:", "options": [{"id": "A", "text": "Thủy điện Trị An"}, {"id": "B", "text": "Thủy điện Sơn La (trên sông Đà)"}, {"id": "C", "text": "Thủy điện Hòa Bình"}], "correctOption": "B", "explanation": "Thủy điện Sơn La có công suất thiết kế 2400 MW, khánh thành năm 2012, là công trình thủy điện lớn nhất Đông Nam Á.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-vietnam-energy-transition-q2", "prompt": "Hai tỉnh Duyên hải Nam Trung Bộ có tiềm năng bức xạ mặt trời và tốc độ gió lớn nhất, trở thành trung tâm năng lượng tái tạo của cả nước là:", "options": [{"id": "A", "text": "Ninh Thuận và Bình Thuận"}, {"id": "B", "text": "Nam Định và Thái Bình"}, {"id": "C", "text": "Điện Biên và Lai Châu"}], "correctOption": "A", "explanation": "Ninh Thuận và Bình Thuận có số giờ nắng cao quanh năm và lượng gió ổn định, thu hút hàng loạt dự án điện mặt trời và điện gió quy mô lớn.", "difficulty": "MEDIUM", "points": 10}, {"id": "geography-12-vietnam-services-transport-tourism-q1", "prompt": "Tuyến đường bộ huyết mạch nối liền đất nước từ Bắc vào Nam dọc theo chiều dài dải đất non sông là:", "options": [{"id": "A", "text": "Quốc lộ 1A và đường cao tốc Bắc - Nam phía Đông"}, {"id": "B", "text": "Đường Hồ Chí Minh trên biển"}, {"id": "C", "text": "Tuyến đường vành đai biên giới số 4"}], "correctOption": "A", "explanation": "Quốc lộ 1A và tuyến cao tốc Bắc - Nam là trục xương sống giao thông vận tải đường bộ kết nối các trung tâm kinh tế từ Lạng Sơn đến Cà Mau.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-vietnam-services-transport-tourism-q2", "prompt": "Cụm cảng biển nước sâu quốc tế ở Đông Nam Bộ có khả năng tiếp nhận các siêu tàu container đi trực tiếp sang bờ Tây nước Mĩ là:", "options": [{"id": "A", "text": "Cảng Cửa Lò (Nghệ An)"}, {"id": "B", "text": "Cảng Quy Nhơn (Bình Định)"}, {"id": "C", "text": "Cụm cảng Cái Mép - Thị Vải (Bà Rịa - Vũng Tàu)"}], "correctOption": "C", "explanation": "Cái Mép - Thị Vải có luồng sâu tự nhiên, là cửa ngõ xuất nhập khẩu hàng hải quốc tế hiện đại hàng đầu của Việt Nam.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-geography-12-3','Ôn tập bài 11–15','geography',12,'Bài 11–15','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "geography-12-red-river-delta-development-q1", "prompt": "Thế mạnh vượt trội nhất về mặt nguồn nhân lực của vùng Đồng bằng sông Hồng so với các vùng khác là:", "options": [{"id": "A", "text": "Toàn bộ lao động chỉ có kinh nghiệm săn bắt thú hoang dã"}, {"id": "B", "text": "Chi phí thuê nhân công rẻ nhất trong toàn bộ khu vực"}, {"id": "C", "text": "Nguồn lao động rất dồi dào và có tỉ lệ lao động qua đào tạo cao nhất cả nước"}], "correctOption": "C", "explanation": "Vùng tập trung phần lớn các trường đại học, viện nghiên cứu lớn nên có mật độ tri thức và tay nghề kĩ thuật đứng đầu cả nước.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-red-river-delta-development-q2", "prompt": "Vụ sản xuất nông nghiệp đặc trưng tạo nên nét độc đáo của Đồng bằng sông Hồng nhờ có mùa đông lạnh là:", "options": [{"id": "A", "text": "Vụ mưa tuyết trồng cây cao su"}, {"id": "B", "text": "Vụ đông (trồng các loại rau màu ưa lạnh như khoai tây, su hào, bắp cải)"}, {"id": "C", "text": "Vụ hè thu trồng lúa nổi"}], "correctOption": "B", "explanation": "Mùa đông lạnh ở miền Bắc cho phép trồng các giống cây nguồn gốc cận nhiệt và ôn đới, biến vụ đông thành vụ hàng hóa có hiệu quả kinh tế cao.", "difficulty": "MEDIUM", "points": 10}, {"id": "geography-12-mekong-delta-climate-adaptation-q1", "prompt": "Vai trò quan trọng hàng đầu của vùng Đồng bằng sông Cửu Long đối với cả nước là:", "options": [{"id": "A", "text": "Là trung tâm luyện kim đen và chế tạo máy bay lớn nhất nước"}, {"id": "B", "text": "Là vùng trọng điểm sản xuất lương thực, thủy sản và trái cây lớn nhất, bảo đảm an ninh lương thực quốc gia và xuất khẩu"}, {"id": "C", "text": "Là vùng tập trung nhiều nhất các mỏ quặng sắt và than đá"}], "correctOption": "B", "explanation": "Đồng bằng sông Cửu Long chiếm hơn một nửa sản lượng lúa cả nước và cung cấp phần lớn sản lượng gạo xuất khẩu của Việt Nam.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-mekong-delta-climate-adaptation-q2", "prompt": "Thách thức môi trường tự nhiên gay gắt nhất đe dọa sinh kế của người dân Đồng bằng sông Cửu Long vào mùa khô hiện nay là:", "options": [{"id": "A", "text": "Hiện tượng hạn hán kết hợp với xâm nhập mặn lấn sâu vào nội đồng"}, {"id": "B", "text": "Bão tuyết và rét đậm kéo dài nhiều tháng"}, {"id": "C", "text": "Núi lửa phun trào dung nham dọc các bờ kênh"}], "correctOption": "A", "explanation": "Lưu lượng dòng chảy thượng nguồn giảm làm nước biển theo triều dâng xâm nhập sâu hàng chục km vào các nhánh sông, làm thiếu nước ngọt sinh hoạt và tưới tiêu.", "difficulty": "MEDIUM", "points": 10}, {"id": "geography-12-southeast-region-growth-pole-q1", "prompt": "Đặc điểm nào sau đây khẳng định vị thế kinh tế số 1 của vùng Đông Nam Bộ ở Việt Nam?", "options": [{"id": "A", "text": "Là vùng đóng góp tỉ trọng GDP và thu ngân sách nhà nước cao nhất cả nước"}, {"id": "B", "text": "Là vùng có diện tích đất tự nhiên rộng lớn nhất cả nước"}, {"id": "C", "text": "Là vùng có mật độ dân số thấp nhất trong tất cả các vùng"}], "correctOption": "A", "explanation": "Đông Nam Bộ là cực tăng trưởng kinh tế năng động nhất, dẫn đầu cả nước về quy mô kinh tế, thu hút vốn FDI và xuất khẩu.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-southeast-region-growth-pole-q2", "prompt": "Tài nguyên khoáng sản nổi bật ở thềm lục địa của vùng Đông Nam Bộ có ý nghĩa chiến lược quốc gia là:", "options": [{"id": "A", "text": "Than đá và than bùn"}, {"id": "B", "text": "Quặng sắt và bauxite"}, {"id": "C", "text": "Dầu mỏ và khí tự nhiên"}], "correctOption": "C", "explanation": "Các mỏ dầu khí lớn ngoài khơi Bà Rịa - Vũng Tàu (Bạch Hổ, Rạng Đông) là nguồn nguyên liệu cho công nghiệp năng lượng và hóa dầu.", "difficulty": "MEDIUM", "points": 10}, {"id": "geography-12-vietnam-marine-economy-q1", "prompt": "Nghị quyết 36-NQ/TW của Trung ương Đảng xác định ngành kinh tế biển nào giữ vị trí ưu tiên hàng đầu?", "options": [{"id": "A", "text": "Khai thác cát sỏi lòng biển làm vật liệu san lấp"}, {"id": "B", "text": "Chế biến dầu thô xuất khẩu"}, {"id": "C", "text": "Du lịch và dịch vụ biển"}], "correctOption": "C", "explanation": "Du lịch biển với bờ biển dài và hàng nghìn hòn đảo đẹp là ngành kinh tế có tiềm năng đột phá và lan tỏa nhanh nhất.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-vietnam-marine-economy-q2", "prompt": "Hệ thống các đảo và quần đảo của Việt Nam trên Biển Đông có ý nghĩa chiến lược to lớn về:", "options": [{"id": "A", "text": "Không có bất kì giá trị kinh tế nào do diện tích quá nhỏ"}, {"id": "B", "text": "Kinh tế biển, căn cứ tiến ra biển lớn và bảo đảm quốc phòng, an ninh bảo vệ Tổ quốc"}, {"id": "C", "text": "Chỉ dùng để làm nơi lưu giữ rác thải công nghiệp"}], "correctOption": "B", "explanation": "Hệ thống đảo tạo nên các tiền tiêu bảo vệ lãnh thổ, là điểm tựa cho ngư dân bám biển và xác định các vùng biển theo luật pháp quốc tế.", "difficulty": "MEDIUM", "points": 10}, {"id": "geography-12-environmental-sustainability-vietnam-q1", "prompt": "Tại Hội nghị biến đổi khí hậu COP26 (năm 2021), Thủ tướng Chính phủ Việt Nam đã đưa ra cam kết mạnh mẽ nào?", "options": [{"id": "A", "text": "Ngừng hoàn toàn mọi hoạt động sản xuất công nghiệp vào năm 2025"}, {"id": "B", "text": "Đạt mức phát thải ròng bằng 0 (Net Zero) vào năm 2050"}, {"id": "C", "text": "Tăng gấp đôi lượng khí thải nhà kính vào năm 2030"}], "correctOption": "B", "explanation": "Cam kết Net Zero vào năm 2050 thể hiện trách nhiệm cao của Việt Nam trong nỗ lực toàn cầu ngăn chặn biến đổi khí hậu.", "difficulty": "EASY", "points": 10}, {"id": "geography-12-environmental-sustainability-vietnam-q2", "prompt": "Mô hình ''Kinh tế tuần hoàn'' (Circular Economy) trong quản lí tài nguyên và môi trường hướng tới mục tiêu cốt lõi nào?", "options": [{"id": "A", "text": "Kéo dài vòng đời của sản phẩm, tái sử dụng và tái chế chất thải thành tài nguyên, giảm thiểu phát thải ra môi trường"}, {"id": "B", "text": "Khai thác triệt để tài nguyên một lần rồi chôn lấp toàn bộ"}, {"id": "C", "text": "Tăng lượng rác thải nhựa không phân hủy sinh học ra sông hồ"}], "correctOption": "A", "explanation": "Kinh tế tuần hoàn thay thế mô hình kinh tế tuyến tính truyền thống (khai thác - sản xuất - vứt bỏ) bằng chu trình khép kín tài nguyên.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-economics_law-12-1','Ôn tập bài 1–5','economics_law',12,'Bài 1–5','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "economics_law-12-economic-growth-development-q1", "prompt": "Chỉ tiêu kinh tế vĩ mô nào sau đây phản ánh tổng giá trị thị trường của toàn bộ hàng hóa và dịch vụ cuối cùng được sản xuất ra trên lãnh thổ một quốc gia trong năm?", "options": [{"id": "A", "text": "Tổng sản phẩm quốc nội (GDP)"}, {"id": "B", "text": "Chỉ số giá tiêu dùng (CPI)"}, {"id": "C", "text": "Tỉ lệ lạm phát hàng tháng"}], "correctOption": "A", "explanation": "GDP (Gross Domestic Product) đo lường toàn bộ giá trị gia tăng tạo ra bên trong biên giới địa lí của quốc gia.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-economic-growth-development-q2", "prompt": "Điểm khác biệt căn bản giữa ''phát triển kinh tế'' và ''tăng trưởng kinh tế'' là gì?", "options": [{"id": "A", "text": "Phát triển kinh tế chỉ tính riêng số lượng máy móc sản xuất trong một ngày"}, {"id": "B", "text": "Tăng trưởng kinh tế có phạm vi rộng lớn hơn phát triển kinh tế"}, {"id": "C", "text": "Phát triển kinh tế bao hàm tăng trưởng kinh tế kết hợp với tiến bộ cơ cấu xã hội, cải thiện đời sống và bảo vệ môi trường"}], "correctOption": "C", "explanation": "Tăng trưởng thuần túy về mặt số lượng (quy mô GDP), còn phát triển bao hàm cả sự biến đổi về chất lượng cuộc sống (giáo dục, y tế, bình đẳng xã hội).", "difficulty": "MEDIUM", "points": 10}, {"id": "economics_law-12-international-economic-integration-q1", "prompt": "Tổ chức kinh tế đa phương toàn cầu lớn nhất mà Việt Nam gia nhập năm 2007 để hòa mạng sâu rộng vào thương mại quốc tế là:", "options": [{"id": "A", "text": "Quỹ Tiền tệ Quốc tế (IMF)"}, {"id": "B", "text": "Tổ chức Các nước Xuất khẩu Dầu mỏ (OPEC)"}, {"id": "C", "text": "Tổ chức Thương mại Thế giới (WTO)"}], "correctOption": "C", "explanation": "Việt Nam trở thành thành viên thứ 150 của WTO vào ngày 11/1/2007 sau hơn 11 năm đàm phán.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-international-economic-integration-q2", "prompt": "Đặc điểm nổi bật của các hiệp định thương mại tự do thế hệ mới (như CPTPP, EVFTA) so với các hiệp định truyền thống là:", "options": [{"id": "A", "text": "Bắt buộc các nước tham gia phải sử dụng chung một loại tiền tệ duy nhất"}, {"id": "B", "text": "Có phạm vi cam kết sâu rộng hơn, bao gồm cả các vấn đề phi thương mại như môi trường, quyền lao động và sở hữu trí tuệ"}, {"id": "C", "text": "Chỉ cam kết trao đổi hàng hóa nông sản thô mà không có dịch vụ"}], "correctOption": "B", "explanation": "FTA thế hệ mới không chỉ xóa bỏ dòng thuế quan mà còn đặt ra các tiêu chuẩn minh bạch hóa, bảo vệ người lao động và phát triển xanh.", "difficulty": "MEDIUM", "points": 10}, {"id": "economics_law-12-insurance-welfare-system-q1", "prompt": "Loại hình bảo hiểm phi lợi nhuận do Nhà nước tổ chức nhằm bảo đảm quyền lợi khám chữa bệnh cho người dân là:", "options": [{"id": "A", "text": "Bảo hiểm cháy nổ nhà xưởng tư nhân"}, {"id": "B", "text": "Bảo hiểm y tế (BHYT)"}, {"id": "C", "text": "Bảo hiểm ô tô thương mại"}], "correctOption": "B", "explanation": "BHYT là chính sách an sinh xã hội ưu việt của Đảng và Nhà nước nhằm chăm sóc sức khỏe cộng đồng, không vì mục đích kiếm lợi nhuận.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-insurance-welfare-system-q2", "prompt": "Người lao động tham gia Bảo hiểm xã hội bắt buộc đủ điều kiện theo quy định được hưởng những chế độ cốt lõi nào?", "options": [{"id": "A", "text": "Ốm đau, thai sản, tai nạn lao động - bệnh nghề nghiệp, hưu trí và tử tuất"}, {"id": "B", "text": "Chế độ thưởng du lịch châu Âu hàng năm"}, {"id": "C", "text": "Được cấp miễn phí nhà ở cao cấp và xe hơi cá nhân"}], "correctOption": "A", "explanation": "Luật BHXH quy định rõ 5 chế độ của BHXH bắt buộc nhằm bảo đảm an sinh trọn đời cho người lao động từ khi đi làm đến lúc về già.", "difficulty": "MEDIUM", "points": 10}, {"id": "economics_law-12-business-plan-startup-q1", "prompt": "Bước đầu tiên và giữ vai trò định hướng trong quá trình xây dựng một bản kế hoạch kinh doanh là:", "options": [{"id": "A", "text": "Xác định ý tưởng kinh doanh và giá trị độc đáo mang lại cho khách hàng"}, {"id": "B", "text": "Đi vay ngân hàng số tiền tối đa có thể"}, {"id": "C", "text": "Thuê ngay mặt bằng đắt nhất ở trung tâm thành phố"}], "correctOption": "A", "explanation": "Ý tưởng kinh doanh xuất phát từ việc phát hiện nhu cầu chưa được đáp ứng tốt trên thị trường là nền tảng khởi đầu của kế hoạch.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-business-plan-startup-q2", "prompt": "Điểm hòa vốn (Break-even point) trong kế hoạch tài chính của một cơ sở kinh doanh là thời điểm:", "options": [{"id": "A", "text": "Lợi nhuận ròng đạt mức cao nhất trong toàn bộ chu kì"}, {"id": "B", "text": "Doanh nghiệp bị phá sản và phải bán thanh lí tài sản"}, {"id": "C", "text": "Tổng doanh thu thu về vừa đủ bù đắp toàn bộ tổng chi phí bỏ ra (lợi nhuận bằng 0)"}], "correctOption": "C", "explanation": "Tại điểm hòa vốn, doanh thu bằng chi phí (TR = TC); vượt qua điểm này doanh nghiệp bắt đầu có lãi ròng.", "difficulty": "MEDIUM", "points": 10}, {"id": "economics_law-12-corporate-social-responsibility-q1", "prompt": "Tầng nền tảng cơ bản đầu tiên trong tháp trách nhiệm xã hội của một doanh nghiệp là:", "options": [{"id": "A", "text": "Trách nhiệm tài trợ nghệ thuật quốc tế"}, {"id": "B", "text": "Trách nhiệm tặng quà miễn phí cho tất cả mọi người"}, {"id": "C", "text": "Trách nhiệm kinh tế (hoạt động kinh doanh có hiệu quả, tạo ra sản phẩm và việc làm)"}], "correctOption": "C", "explanation": "Doanh nghiệp trước hết phải vận hành hiệu quả, tạo ra lợi nhuận và việc làm chính đáng thì mới có nguồn lực thực hiện các trách nhiệm cao hơn.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-corporate-social-responsibility-q2", "prompt": "Hành vi nào sau đây biểu hiện sự vi phạm nghiêm trọng đạo đức kinh doanh và trách nhiệm xã hội?", "options": [{"id": "A", "text": "Cung cấp thông tin trung thực về hạn sử dụng và thành phần sản phẩm"}, {"id": "B", "text": "Xả chất thải độc hại chưa qua xử lí ra sông hồ để cắt giảm chi phí sản xuất"}, {"id": "C", "text": "Trả lương và đóng bảo hiểm xã hội đầy đủ cho nhân viên"}], "correctOption": "B", "explanation": "Hành vi lén lút xả thải gây ô nhiễm môi trường hủy hoại hệ sinh thái và sức khỏe cộng đồng là vi phạm pháp luật và đạo đức nghiêm trọng.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-economics_law-12-2','Ôn tập bài 6–10','economics_law',12,'Bài 6–10','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "economics_law-12-personal-household-budget-q1", "prompt": "Theo quy tắc quản lí ngân sách tài chính cá nhân 50/30/20, tỉ lệ 20% thu nhập nên được ưu tiên cho mục tiêu nào?", "options": [{"id": "A", "text": "Chi trả tiền thuê nhà và tiền ăn uống hàng ngày"}, {"id": "B", "text": "Tiết kiệm, lập quỹ dự phòng khẩn cấp hoặc đầu tư trả nợ"}, {"id": "C", "text": "Đi du lịch nghỉ dưỡng cao cấp hàng tháng"}], "correctOption": "B", "explanation": "20% khoản tiền này là đòn bẩy tích lũy tạo sự an tâm tài chính và sinh lời dài hạn trong tương lai.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-personal-household-budget-q2", "prompt": "Mục đích cốt lõi của việc xây dựng ''quỹ dự phòng khẩn cấp'' (tương đương 3 - 6 tháng chi phí) là:", "options": [{"id": "A", "text": "Chủ động ứng phó tài chính trước các biến cố bất ngờ như ốm đau, mất việc làm hoặc hư hỏng thiết bị thiết yếu mà không phải vay nợ lãi cao"}, {"id": "B", "text": "Dùng toàn bộ để tham gia các trò chơi may rủi trên mạng xã hội"}, {"id": "C", "text": "Mua sắm những món đồ xa xỉ giảm giá nhất thời"}], "correctOption": "A", "explanation": "Quỹ khẩn cấp bảo vệ cá nhân khỏi nguy cơ vỡ nợ khi xảy ra rủi ro gián đoạn nguồn thu nhập chính.", "difficulty": "MEDIUM", "points": 10}, {"id": "economics_law-12-business-tax-citizenship-q1", "prompt": "Theo quy định của Hiến pháp năm 2013 và pháp luật Việt Nam, công dân có quyền tự do kinh doanh trong phạm vi nào?", "options": [{"id": "A", "text": "Trong những ngành, nghề và lĩnh vực mà luật không cấm"}, {"id": "B", "text": "Trong tất cả mọi lĩnh vực kể cả kinh doanh chất ma túy và vũ khí quân dụng"}, {"id": "C", "text": "Chỉ được phép kinh doanh các mặt hàng nông sản truyền thống tại địa phương"}], "correctOption": "A", "explanation": "Điều 33 Hiến pháp 2013 quy định mọi người có quyền tự do kinh doanh trong những ngành nghề mà pháp luật không cấm.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-business-tax-citizenship-q2", "prompt": "Nghĩa vụ hiến định mang tính bắt buộc hàng đầu của mọi tổ chức, cá nhân khi tiến hành hoạt động kinh doanh đối với Nhà nước là:", "options": [{"id": "A", "text": "Tự ý ấn định mức thuế phải nộp dựa trên mức lợi nhuận mong muốn của cá nhân"}, {"id": "B", "text": "Chỉ nộp thuế khi có sự kiểm tra trực tiếp của cơ quan thuế tại cơ sở kinh doanh"}, {"id": "C", "text": "Kê khai trung thực, chính xác và nộp đầy đủ, đúng thời hạn các khoản thuế theo luật định"}], "correctOption": "C", "explanation": "Nộp thuế là nghĩa vụ hiến định của công dân nhằm tạo nguồn lực tài chính công để Nhà nước xây dựng hạ tầng, bảo đảm an sinh và bảo vệ Tổ quốc.", "difficulty": "MEDIUM", "points": 10}, {"id": "economics_law-12-property-ownership-rights-obligations-q1", "prompt": "Theo quy định của Bộ luật Dân sự năm 2015, quyền sở hữu của chủ sở hữu bao gồm ba quyền năng cơ bản nào?", "options": [{"id": "A", "text": "Quyền phong tỏa, quyền phát mại và quyền chiếm đoạt tài sản"}, {"id": "B", "text": "Quyền vay mượn, quyền thế chấp và quyền giấu giếm tài sản"}, {"id": "C", "text": "Quyền chiếm hữu, quyền sử dụng và quyền định đoạt tài sản"}], "correctOption": "C", "explanation": "Điều 158 Bộ luật Dân sự 2015 quy định quyền sở hữu bao gồm quyền chiếm hữu, quyền sử dụng và quyền định đoạt tài sản của chủ sở hữu.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-property-ownership-rights-obligations-q2", "prompt": "Nghĩa vụ tôn trọng tài sản của người khác đòi hỏi mỗi công dân phải thực hiện hành vi nào sau đây khi nhặt được tài sản đánh rơi?", "options": [{"id": "A", "text": "Đem vứt bỏ tài sản đó xuống sông hồ để không ai tìm thấy"}, {"id": "B", "text": "Thông báo hoặc trả lại ngay cho người đánh rơi, hoặc giao nộp cho cơ quan công an gần nhất"}, {"id": "C", "text": "Tự ý cất giữ làm của riêng và mang bán lấy tiền chi tiêu cá nhân"}], "correctOption": "B", "explanation": "Pháp luật dân sự quy định người nhặt được của rơi có nghĩa vụ thông báo, trả lại cho chủ sở hữu hoặc giao nộp cơ quan có thẩm quyền.", "difficulty": "MEDIUM", "points": 10}, {"id": "economics_law-12-marriage-family-rights-obligations-q1", "prompt": "Nguyên tắc cốt lõi hàng đầu của chế độ hôn nhân và gia đình theo pháp luật Việt Nam hiện hành là:", "options": [{"id": "A", "text": "Cho phép kết hôn với nhiều người cùng một lúc để mở rộng quan hệ họ hàng"}, {"id": "B", "text": "Hôn nhân tự nguyện, tiến bộ, một vợ một chồng, vợ chồng bình đẳng"}, {"id": "C", "text": "Hôn nhân hoàn toàn do cha mẹ sắp đặt và người chồng nắm toàn quyền quyết định"}], "correctOption": "B", "explanation": "Điều 2 Luật Hôn nhân và Gia đình 2014 xác định nguyên tắc hôn nhân tự nguyện, tiến bộ, một vợ một chồng, vợ chồng bình đẳng.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-marriage-family-rights-obligations-q2", "prompt": "Bổn phận và nghĩa vụ pháp lí quan trọng hàng đầu của con cái đối với cha mẹ theo luật định là:", "options": [{"id": "A", "text": "Yêu quý, kính trọng, biết ơn, hiếu thảo và chăm sóc, phụng dưỡng cha mẹ khi già yếu, ốm đau"}, {"id": "B", "text": "Có quyền từ chối phụng dưỡng cha mẹ nếu cha mẹ không chia phần tài sản thừa kế"}, {"id": "C", "text": "Tự ý định đoạt và sang tên toàn bộ nhà đất của cha mẹ mà không cần cha mẹ đồng ý"}], "correctOption": "A", "explanation": "Luật Hôn nhân và Gia đình quy định con cái có nghĩa vụ yêu quý, chăm sóc, nuôi dưỡng cha mẹ, đặc biệt khi cha mẹ mất sức lao động hoặc ốm đau.", "difficulty": "MEDIUM", "points": 10}, {"id": "economics_law-12-learning-education-rights-obligations-q1", "prompt": "Quy định công dân có thể học từ bậc tiểu học lên đến tiến sĩ theo các hình thức đào tạo khác nhau thể hiện nội dung quyền nào?", "options": [{"id": "A", "text": "Quyền học tập không hạn chế của công dân"}, {"id": "B", "text": "Quyền độc quyền nghiên cứu khoa học của nhà nước"}, {"id": "C", "text": "Nghĩa vụ bắt buộc mọi công dân phải đạt học vị tiến sĩ"}], "correctOption": "A", "explanation": "Quyền học tập không hạn chế cho phép công dân học từ thấp đến cao phù hợp với năng lực, điều kiện và nguyện vọng cá nhân suốt đời.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-learning-education-rights-obligations-q2", "prompt": "Chính sách của Nhà nước miễn học phí cho học sinh tiểu học và cấp học bổng cho học sinh vùng đồng bào dân tộc thiểu số thể hiện nguyên tắc gì?", "options": [{"id": "A", "text": "Tạo sự phân biệt đối xử bất lợi đối với học sinh sinh sống tại các đô thị lớn"}, {"id": "B", "text": "Cắt giảm chỉ tiêu đào tạo đại học và cao đẳng trên phạm vi toàn quốc"}, {"id": "C", "text": "Bảo đảm sự bình đẳng và công bằng xã hội về cơ hội tiếp cận giáo dục cho mọi công dân"}], "correctOption": "C", "explanation": "Nhà nước ưu tiên hỗ trợ các đối tượng yếu thế nhằm xóa bỏ rào cản kinh tế, hiện thực hóa quyền bình đẳng trong tiếp cận giáo dục cho mọi trẻ em.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status) values ('review-economics_law-12-3','Ôn tập bài 11–15','economics_law',12,'Bài 11–15','Ôn tập 5 bài gần nhất','MEDIUM','[{"id": "economics_law-12-healthcare-social-security-rights-q1", "prompt": "Chính sách an sinh xã hội trụ cột do Nhà nước tổ chức nhằm chăm sóc sức khỏe cộng đồng và chia sẻ chi phí khám chữa bệnh là:", "options": [{"id": "A", "text": "Quỹ đầu tư bất động sản thương mại"}, {"id": "B", "text": "Hợp đồng bảo hiểm tài sản doanh nghiệp"}, {"id": "C", "text": "Bảo hiểm y tế (BHYT)"}], "correctOption": "C", "explanation": "Bảo hiểm y tế là chính sách an sinh xã hội quan trọng nhằm huy động sự đóng góp cộng đồng, bảo đảm quyền chăm sóc sức khỏe cho nhân dân.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-healthcare-social-security-rights-q2", "prompt": "Trong công tác phòng, chống bệnh truyền nhiễm nguy hiểm, nghĩa vụ bắt buộc của mỗi cá nhân đối với cộng đồng là gì?", "options": [{"id": "A", "text": "Che giấu tình trạng nhiễm bệnh truyền nhiễm của bản thân và từ chối điều trị"}, {"id": "B", "text": "Khai báo y tế trung thực, thực hiện nghiêm các biện pháp cách ly và tiêm chủng phòng dịch theo hướng dẫn y tế"}, {"id": "C", "text": "Tự ý trốn khỏi khu vực phong tỏa cách ly y tế để tiếp xúc đông người nơi công cộng"}], "correctOption": "B", "explanation": "Luật Phòng, chống bệnh truyền nhiễm quy định cá nhân có nghĩa vụ chấp hành nghiêm các biện pháp phòng dịch để bảo đảm an toàn sức khỏe chung.", "difficulty": "MEDIUM", "points": 10}, {"id": "economics_law-12-cultural-environmental-protection-rights-q1", "prompt": "Quyền cơ bản của mọi người dân đối với môi trường sống được ghi nhận rõ nét tại Điều 43 Hiến pháp năm 2013 là:", "options": [{"id": "A", "text": "Mọi người được phép xả chất thải công nghiệp trực tiếp ra nguồn nước sinh hoạt chung"}, {"id": "B", "text": "Mọi người có quyền được sống trong môi trường trong lành và có nghĩa vụ bảo vệ môi trường"}, {"id": "C", "text": "Mọi người có quyền tự do khai thác cạn kiệt tài nguyên rừng phòng hộ mà không cần xin phép"}], "correctOption": "B", "explanation": "Hiến pháp 2013 khẳng định quyền được sống trong môi trường trong lành đi đôi với nghĩa vụ bảo vệ môi trường của mọi cá nhân.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-cultural-environmental-protection-rights-q2", "prompt": "Hành vi nào sau đây xâm phạm nghiêm trọng các quy định pháp luật về bảo vệ di sản văn hóa dân tộc?", "options": [{"id": "A", "text": "Tự ý đập phá, lấn chiếm khuôn viên, đào bới trái phép hoặc làm biến dạng kiến trúc gốc của di tích lịch sử"}, {"id": "B", "text": "Tích cực tham gia vệ sinh môi trường và trồng hoa tạo cảnh quan đẹp cho khu di tích"}, {"id": "C", "text": "Sưu tầm và giới thiệu các tư liệu lịch sử chính thống về di tích cho du khách tham quan"}], "correctOption": "A", "explanation": "Luật Di sản văn hóa nghiêm cấm các hành vi chiếm đoạt, hủy hoại hoặc làm sai lệch hiện vật, cảnh quan di tích lịch sử - văn hóa.", "difficulty": "MEDIUM", "points": 10}, {"id": "economics_law-12-general-international-law-foundations-q1", "prompt": "Chủ thể cơ bản, ban đầu và giữ vai trò trung tâm nhất trong hệ thống pháp luật quốc tế hiện đại là:", "options": [{"id": "A", "text": "Các quốc gia độc lập có chủ quyền"}, {"id": "B", "text": "Các cá nhân công dân mang quốc tịch bất kì"}, {"id": "C", "text": "Các câu lạc bộ thể thao và tập đoàn tư nhân đa quốc gia"}], "correctOption": "A", "explanation": "Quốc gia có chủ quyền là chủ thể chủ yếu và cơ bản nhất của luật quốc tế, có đầy đủ thẩm quyền kí kết và thực thi các cam kết quốc tế.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-general-international-law-foundations-q2", "prompt": "Nguyên tắc ''Pacta sunt servanda'' - một trong những nguyên tắc nền tảng linh hồn của luật pháp quốc tế đòi hỏi các quốc gia phải:", "options": [{"id": "A", "text": "Được quyền đơn phương hủy bỏ các điều ước quốc tế bất cứ lúc nào cảm thấy bất lợi cho riêng mình"}, {"id": "B", "text": "Chỉ cần thực hiện các cam kết nếu nhận được sự đồng ý của tất cả các tập đoàn tư nhân"}, {"id": "C", "text": "Tận tâm, thiện chí thực hiện đầy đủ các cam kết và nghĩa vụ trong các điều ước quốc tế mà mình đã kí kết hoặc gia nhập"}], "correctOption": "C", "explanation": "Pacta sunt servanda là nguyên tắc thượng tôn các cam kết quốc tế, bảo đảm tính ổn định, tin cậy và pháp quyền trong trật tự quan hệ quốc tế.", "difficulty": "MEDIUM", "points": 10}, {"id": "economics_law-12-public-international-law-territory-sovereignty-q1", "prompt": "Theo công pháp quốc tế, lãnh thổ quốc gia hoàn chỉnh được cấu thành từ bốn bộ phận không gian địa lí nào?", "options": [{"id": "A", "text": "Vùng đất liền canh tác nông nghiệp và không tính vùng trời"}, {"id": "B", "text": "Chỉ bao gồm các hải đảo nằm ngoài vùng đặc quyền kinh tế"}, {"id": "C", "text": "Vùng đất, vùng nước, vùng trời và vùng lòng đất"}], "correctOption": "C", "explanation": "Lãnh thổ quốc gia là một thể thống nhất gồm 4 bộ phận: vùng đất, vùng nước (nội thủy, lãnh hải), vùng lòng đất và vùng trời phía trên.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-public-international-law-territory-sovereignty-q2", "prompt": "Tính chất ''bất khả xâm phạm'' của chủ quyền và lãnh thổ quốc gia trong luật pháp quốc tế mang ý nghĩa cốt lõi là:", "options": [{"id": "A", "text": "Quốc gia ven biển không có quyền quản lí tàu thuyền hoạt động trong vùng biển thuộc chủ quyền của mình"}, {"id": "B", "text": "Mọi hành vi xâm lấn biên giới, đe dọa độc lập và toàn vẹn lãnh thổ của một quốc gia đều là hành vi vi phạm pháp luật quốc tế nghiêm trọng"}, {"id": "C", "text": "Các cường quốc lớn có quyền tự do can thiệp quân sự vào vùng trời của các quốc gia nhỏ hơn"}], "correctOption": "B", "explanation": "Luật pháp quốc tế nghiêm cấm mọi hành vi xâm lấn, chiếm đoạt lãnh thổ hoặc can thiệp lật đổ chủ quyền thiêng liêng của một quốc gia độc lập.", "difficulty": "MEDIUM", "points": 10}, {"id": "economics_law-12-wto-principles-international-commercial-contracts-q1", "prompt": "Nguyên tắc ''Đãi ngộ tối huệ quốc'' (MFN) trong hệ thống thương mại đa phương của WTO quy định điều gì?", "options": [{"id": "A", "text": "Cho phép các nước giàu áp thuế nhập khẩu cao gấp mười lần đối với hàng hóa xuất xứ từ các nước nghèo"}, {"id": "B", "text": "Nếu một thành viên dành ưu đãi thương mại cho một quốc gia thì phải dành ưu đãi tương tự cho tất cả các thành viên khác của WTO"}, {"id": "C", "text": "Chỉ dành ưu đãi thuế quan đặc biệt cho các quốc gia láng giềng có chung đường biên giới đất liền"}], "correctOption": "B", "explanation": "Nguyên tắc MFN bảo đảm không phân biệt đối xử giữa các đối tác thương mại: lợi thế dành cho một nước phải được trao bình đẳng cho toàn bộ thành viên WTO.", "difficulty": "EASY", "points": 10}, {"id": "economics_law-12-wto-principles-international-commercial-contracts-q2", "prompt": "Nguyên tắc ''Đãi ngộ quốc gia'' (NT) của WTO nghiêm cấm hành vi nào sau đây của nước nhập khẩu đối với hàng hóa nước ngoài?", "options": [{"id": "A", "text": "Áp đặt mức thuế tiêu thụ nội địa hoặc quy chuẩn kĩ thuật khắt khe hơn đối với hàng hóa nhập khẩu so với hàng hóa cùng loại sản xuất trong nước"}, {"id": "B", "text": "Thực hiện kiểm tra an toàn thực phẩm bình đẳng đối với mọi lô hàng lưu thông trên thị trường nội địa"}, {"id": "C", "text": "Cắt giảm biểu thuế quan nhập khẩu theo đúng lộ trình cam kết gia nhập WTO"}], "correctOption": "A", "explanation": "Nguyên tắc NT yêu cầu hàng nhập khẩu sau khi qua cửa khẩu phải được đối xử công bằng ngang bằng với hàng nội địa, không bị phân biệt đối xử về thuế và quy chuẩn kĩ thuật.", "difficulty": "MEDIUM", "points": 10}]'::jsonb,'PUBLISHED') on conflict(id) do update set title=excluded.title,subject_id=excluded.subject_id,grade=excluded.grade,chapter=excluded.chapter,topic=excluded.topic,difficulty=excluded.difficulty,questions=excluded.questions,status=excluded.status;
